import heapq
from collections import defaultdict

class Solution:
    def updateMatrix(self, mat: List[List[int]]) -> List[List[int]]:
        dist = [[0 if cell == 0 else float('inf') for cell in row] for row in mat]
        heap = []
        deleted = defaultdict(int)
        m = len(mat)
        n = len(mat[0])
        for i in range(m):
            for j in range(n):
                heapq.heappush(heap, (dist[i][j], i, j))
        while len(heap) > 0:
            currdist, i, j = heapq.heappop(heap)
            while (currdist, i, j) in deleted and len(heap) > 0:
                deleted[(currdist, i, j)] -= 1
                if deleted[(currdist, i, j)] == 0:
                    del deleted[(currdist, i, j)]
                currdist, i, j = heapq.heappop(heap)
            adj = []
            if i > 0:
                adj.append((i - 1, j))
            if i < m - 1:
                adj.append((i + 1, j))
            if j > 0:
                adj.append((i, j - 1))
            if j < n - 1:
                adj.append((i, j + 1))
            for a, b in adj:
                if dist[a][b] > 1 + currdist:
                    deleted[(dist[a][b], a, b)] += 1
                    dist[a][b] = 1 + currdist
                    heapq.heappush(heap, (1 + currdist, a, b))
        return dist

class Solution:
    def isValid(self, bits, i):
        if i == 0:
            if bits[0] == 0:
                return True
            else:
                return False
        if i == 1:
            if bits[0] == 1:
                return True
            elif bits[1] == 0:
                return True
            else:
                return False
        if bits[i - 1] == 1 and self.isValid(bits, i - 2):
            return True
        if bits[i] == 0 and self.isValid(bits, i - 1):
            return True
        return False

    def isOneBitCharacter(self, bits: List[int]) -> bool:
        if len(bits) >= 2:
            return self.isValid(bits, len(bits) - 2)
        else:
            return True

class Solution:
    def find132pattern(self, nums: List[int]) -> bool:
        stack = []
        mn = float('inf')
        for el in nums:
            while len(stack) > 0 and el >= stack[-1][0]:
                stack.pop()
            if len(stack) > 0 and stack[-1][1] < el:
                return True
            stack.append((el, mn))
            mn = min(mn, el)
        return False

from functools import lru_cache

class Solution:
    @lru_cache(maxsize=None)
    def minSteps(self, n: int, k = 1, clipboard = 0) -> int:
        if k == n:
            return 0
        if k > n:
            return float('inf')
        a = float('inf')
        if clipboard > 0:
            a = 1 + self.minSteps(n, k + clipboard, clipboard)
        b = 2 + self.minSteps(n, 2 * k, k)
        return min(a, b)

class Solution:
    def judgePoint24(self, cards: List[int]) -> bool:
        def check(seq):
            n = len(seq)
            dp = [[set() for _ in range(n)] for _ in range(n)]
            for i in range(n):
                dp[i][i].add(float(seq[i]))
            for length in range(2, n+1):
                for l in range(n - length + 1):
                    r = l + length - 1
                    for k in range(l, r):
                        for x in dp[l][k]:
                            for y in dp[k+1][r]:
                                dp[l][r].add(x + y)
                                dp[l][r].add(x - y)
                                dp[l][r].add(y - x)
                                dp[l][r].add(x * y)
                                if abs(y) > 1e-9:
                                    dp[l][r].add(x / y)
                                if abs(x) > 1e-9:
                                    dp[l][r].add(y / x)
            return any(abs(v - 24) < 1e-6 for v in dp[0][n-1])

        for p in permutations(cards):
            if check(p):
                return True
        return False

class Solution:
    def threeSumClosest(self, nums: List[int], target: int) -> int:
        n = len(nums)
        if n < 3:
            return []
        nums = [3 * num - target for num in nums]
        nums.sort()
        closest = float('inf')
        for i in range(n - 2):
            a = nums[i]
            start = i + 1
            end = n - 1
            while start < end:
                b = nums[start]
                c = nums[end]
                total = a + b + c
                if abs(total) < abs(closest):
                    closest = total
                if total > 0:
                    end -= 1
                else:
                    start += 1
        return target + closest // 3

from collections import Counter

class Solution:
    def threeSumMulti(self, arr: List[int], target: int) -> int:
        M = 10 ** 9 + 7
        n = len(arr)
        res = 0
        ctr = Counter()
        for i in range(n):
            for j in range(i + 1, n):
                res += ctr[target - arr[i] - arr[j]]
                res %= M
            ctr[arr[i]] += 1
        return res

class Solution:
    def threeSum(self, nums: List[int]) -> List[List[int]]:
        n = len(nums)
        if n < 3:
            return []
        triplets = set()
        nums.sort()
        for i in range(n - 2):
            a = nums[i]
            start = i + 1
            end = n - 1
            while start < end:
                b = nums[start]
                c = nums[end]
                total = a + b + c
                if total == 0:
                    triplets.add(tuple(sorted([a, b, c])))
                    start += 1
                    end -= 1
                elif total > 0:
                    end -= 1
                else:
                    start += 1
        return [list(triplet) for triplet in triplets]

from collections import Counter

class Solution:
    def fourSumCount(self, a, b, c, d):
        n = len(a)
        res = 0
        ctr = Counter()
        for i in range(n):
            for j in range(n):
                ctr[a[i] + b[j]] += 1
        for i in range(n):
            for j in range(n):
                res += ctr[-c[i] - d[j]]
        return res

class Solution:
    def fourSum(self, nums: List[int], target: int) -> List[List[int]]:
        n = len(nums)
        nums.sort()
        res = set()
        for i in range(n):
            a = nums[i]
            for j in range(i + 1, n - 2):
                b = nums[j]
                start = j + 1
                end = n - 1
                while start < end:
                    c = nums[start]
                    d = nums[end]
                    total = b + c + d
                    if total == target - a:
                        res.add(tuple([a, b, c, d]))
                        start += 1
                        end -= 1
                    elif total > target - a:
                        end -= 1
                    else:
                        start += 1
        return list(res)

