from collections import defaultdict

class Solution:
    def isPossible(self, n: int, edges: List[List[int]]) -> bool:
        degree = [0] * n
        for a, b in edges:
            degree[a - 1] += 1
            degree[b - 1] += 1
        oddctr = 0
        for d in degree:
            if d & 1:
                oddctr += 1
        if oddctr == 0:
            return True
        if oddctr != 2 and oddctr != 4:
            return False
        graph = defaultdict(set)
        for a, b in edges:
            graph[a - 1].add(b - 1)
            graph[b - 1].add(a - 1)
        oddset = set()
        evenset = set()
        for i in range(n):
            if degree[i] & 1:
                oddset.add(i)
            else:
                evenset.add(i)
        if oddctr == 2:
            i, j = min(oddset), max(oddset)
            if j not in graph[i]:
                return True
            elif len(evenset - (graph[i] | graph[j])) > 0:
                return True
        if oddctr == 4:
            a, b, c, d = sorted(oddset)
            print(a, b, c, d)
            if b not in graph[a] and d not in graph[c]:
                return True
            if c not in graph[a] and d not in graph[b]:
                return True
            if d not in graph[a] and c not in graph[b]:
                return True
        return False

from collections import deque

class Solution:
    def addOneRow(self, root: Optional[TreeNode], val: int, depth: int) -> Optional[TreeNode]:
        if depth == 1:
            return TreeNode(val = val, left = root)
        nodes = deque([(root, 1)])
        while len(nodes) > 0:
            curr, d = nodes.pop()
            if curr:
                if d == depth - 1:
                    l = curr.left
                    r = curr.right
                    curr.left = TreeNode(val)
                    curr.left.left = l
                    curr.right = TreeNode(val)
                    curr.right.right = r
                else:
                    nodes.appendleft((curr.left, d + 1))
                    nodes.appendleft((curr.right, d + 1))
        return root

class Solution:
    def addStrings(self, num1: str, num2: str) -> str:
        m = len(num1)
        n = len(num2)
        if m < n:
            num1 = "0" * (n - m) + num1
        else:
            num2 = "0" * (m - n) + num2
        carry = 0
        i = max(m, n) - 1
        op = ""
        while i >= 0:
            val = carry + int(num1[i]) + int(num2[i])
            op = str(val % 10) + op
            carry = val // 10
            i -= 1
        if carry > 0:
            op = "1" + op
        return op

