class Solution:
    def getSeq(self, num, i, n, a, b, ctr):
        if i >= n:
            return ctr >= 3
        for j in range(i + 1, n + 1):
            curr = int(num[i:j])
            if a == None or b == None or curr == a + b:
                if self.getSeq(num, j, n, b, curr, ctr + 1):
                    return True
            if num[i] == "0":
                break
        return False

    def isAdditiveNumber(self, num: str) -> bool:
        return self.getSeq(num, 0, len(num), None, None, 0)

class Solution:
    def hasIncreasingSubarrays(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        dp = [1] * n
        for i in range(n - 2, -1, -1):
            if nums[i] < nums[i + 1]:
                dp[i] = 1 + dp[i + 1]
        for i in range(n - 2 * k + 1):
            if dp[i] >= k and dp[i + k] >= k:
                return True
        return False

class Solution:
    def maxIncreasingSubarrays(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [1] * n
        for i in range(n - 2, -1, -1):
            if nums[i] < nums[i + 1]:
                dp[i] = 1 + dp[i + 1]
        beg = 1
        end = n // 2
        while beg <= end:
            mid = (beg + end) // 2
            pos = False
            for i in range(n - 2 * mid + 1):
                if dp[i] >= mid and dp[i + mid] >= mid:
                    pos = True
                    break
            if pos:
                beg = mid + 1
            else:
                end = mid - 1
        return beg - 1

class Solution:
    def advantageCount(self, nums1: List[int], nums2: List[int]) -> List[int]:
        n = len(nums1)
        a = sorted([(nums1[i], i) for i in range(n)])
        b = sorted([(nums2[i], i) for i in range(n)])
        beg = 1
        end = n
        while beg <= end:
            mid = (beg + end) // 2
            pos = True
            for i in range(mid):
                if a[-mid + i][0] <= b[i][0]:
                    pos = False
                    break
            if pos:
                beg = mid + 1
            else:
                end = mid - 1
        l = beg - 1
        res = [0] * n
        for i in range(n):
            res[b[i][1]] = a[-l+i][0]
        return res

import bisect

class Solution:
    def alertNames(self, keyName: List[str], keyTime: List[str]) -> List[str]:
        n = len(keyName)
        checkins = {}
        for i in range(n):
            name = keyName[i]
            time = keyTime[i]
            time = tuple(int(k) for k in time.split(":"))
            if name in checkins:
                bisect.insort(checkins[name], time)
            else:
                checkins[name] = [time]
        op = []
        names = sorted(checkins.keys())
        for name in names:
            m = len(checkins[name])
            alert = False
            for i in range(m):
                curr = checkins[name][i]
                j = bisect.bisect_right(checkins[name], (curr[0] + 1, curr[1]))
                if j - i >= 3:
                    alert = True
                    break
            if alert:
                op.append(name)
        return op

