class Solution:
    def alienOrder(self, words: List[str]) -> str:
        indegree = Counter()
        for s in words:
            for c in s:
                indegree[c] = 0
        graph = defaultdict(set)
        for i in range(len(words) - 1):
            j = 0
            while j < len(words[i]) and j < len(words[i + 1]) and words[i][j] == words[i + 1][j]:
                j += 1
            if j < len(words[i]):
                if j == len(words[i + 1]):
                    return ""
                graph[words[i][j]].add(words[i + 1][j])
        for a in graph:
            for b in graph[a]:
                indegree[b] += 1
        q = deque()
        for c in indegree:
            if indegree[c] == 0:
                q.appendleft(c)
        res = []
        while q:
            i = q.pop()
            res.append(i)
            for j in graph[i]:
                indegree[j] -= 1
                if indegree[j] == 0:
                    q.appendleft(j)
        if len(res) < len(indegree):
            return ""
        return "".join(res)

class Solution:
    def getAncestors(self, n: int, edges: List[List[int]]) -> List[List[int]]:
        graph = [[] for _ in range(n)]
        res = [[i] for i in range(n)]
        v = [False] * n
        for a, b in edges:
            graph[b].append(a)
        def merge(x, y):
            merged = []
            i, j = 0, 0
            while i < len(x) and j < len(y):
                if x[i] < y[j]:
                    merged.append(x[i])
                    i += 1
                elif x[i] > y[j]:
                    merged.append(y[j])
                    j += 1
                else:
                    merged.append(x[i])
                    i += 1
                    j += 1
            while i < len(x):
                merged.append(x[i])
                i += 1
            while j < len(y):
                merged.append(y[j])
                j += 1
            return merged
        def f(i):
            if v[i]:
                return
            v[i] = True
            for j in graph[i]:
                f(j)
                res[i] = merge(res[i], res[j])
        for i in range(n):
            f(i)
        for i in range(n):
            res[i].remove(i)
        return res

class Solution:
    def maxScoreIndices(self, nums):
        rightones = nums.count(1)
        leftzeroes = 0
        mscore = leftzeroes + rightones
        res = [0]
        for i, el in enumerate(nums):
            if el == 0:
                leftzeroes += 1
            else:
                rightones -= 1
            if leftzeroes + rightones > mscore:
                mscore = leftzeroes + rightones
                res = [i + 1]
            elif mscore == leftzeroes + rightones:
                res.append(i + 1)
        return res

class Solution:
    def getAllElements(self, root1: Optional[TreeNode], root2: Optional[TreeNode]) -> List[int]:
        def dfs(r):
            if not r:
                return []
            return dfs(r.left) + [r.val] + dfs(r.right)
        def merge(a, b):
            res = []
            i = j = 0
            while i < len(a) and j < len(b):
                if a[i] <= b[j]:
                    res.append(a[i])
                    i += 1
                else:
                    res.append(b[j])
                    j += 1
            res.extend(a[i:])
            res.extend(b[j:])
            return res
        return merge(dfs(root1), dfs(root2))

class Solution:
    def dfs(self, root, upper, k, target):
        if not root:
            return float('inf')
        d = float('inf')
        if root.val == target.val:
            d = 0
            upper = k
        l = 1 + self.dfs(root.left, upper - 1, k, target)
        r = 1 + self.dfs(root.right, upper - 1, k, target)
        if l == k or r == k or upper == 0:
            self.res.append(root.val)
        if l < float('inf'):
            self.dfs(root.right, k - l - 1, k, target)
        if r < float('inf'):
            self.dfs(root.left, k - r - 1, k, target)
        return min(d, l, r)

    def distanceK(self, root: TreeNode, target: TreeNode, k: int) -> List[int]:
        self.res = []
        self.dfs(root, float('inf'), k, target)
        return self.res

from collections import defaultdict
import heapq

class AllOne:
    def __init__(self):
        self.ctr = defaultdict(int)
        self.deleted = defaultdict(int)
        self.minheap = []
        self.maxheap = []

    def inc(self, key: str) -> None:
        self.deleted[(self.ctr[key], key)] += 1
        self.deleted[(-self.ctr[key], key)] += 1
        self.ctr[key] += 1
        heapq.heappush(self.minheap, (self.ctr[key], key))
        heapq.heappush(self.maxheap, (-self.ctr[key], key))

    def dec(self, key: str) -> None:
        if self.ctr[key] > 0:
            self.deleted[(self.ctr[key], key)] += 1
            self.deleted[(-self.ctr[key], key)] += 1
            self.ctr[key] -= 1
            heapq.heappush(self.minheap, (self.ctr[key], key))
            heapq.heappush(self.maxheap, (-self.ctr[key], key))

    def getMaxKey(self) -> str:
        while len(self.maxheap) > 0 and self.deleted[self.maxheap[0]] > 0:
            self.deleted[self.maxheap[0]] -= 1
            heapq.heappop(self.maxheap)
        if len(self.maxheap) > 0:
            return self.maxheap[0][1]
        return ""

    def getMinKey(self) -> str:
        while len(self.minheap) > 0 and self.deleted[self.minheap[0]] > 0:
            self.deleted[self.minheap[0]] -= 1
            heapq.heappop(self.minheap)
        if len(self.minheap) > 0:
            return self.minheap[0][1]
        return ""

class Solution:
    def getPath(self, beg, end, graph, v, path):
        if beg == end:
            self.paths.append(path[:])
        for node in graph[beg]:
            if node not in v:
                path.append(node)
                v.add(node)
                self.getPath(node, end, graph, v, path)
                path.pop()
                v.remove(node)

    def allPathsSourceTarget(self, graph: List[List[int]]) -> List[List[int]]:
        n = len(graph)
        self.paths = []
        self.getPath(0, n - 1, graph, {0}, [0])
        return self.paths

# Definition for a binary tree node.
