#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def getTrees(self, n: int) -> List[Optional[TreeNode]]:
        trees = []
        if n == 1:
            return [TreeNode()]
        if n in self.cache:
            return self.cache[n]
        for i in range(1, n, 2):
            lefts = self.getTrees(i)
            rights = self.getTrees(n - i - 1)
            for left in lefts:
                for right in rights:
                    root = TreeNode()
                    root.left = left
                    root.right = right
                    trees.append(root)
        self.cache[n] = trees
        return trees

    def allPossibleFBT(self, n: int) -> List[Optional[TreeNode]]:
        self.cache = {}
        return self.getTrees(n)

class Solution:
    def minDistance(self, houses: List[int], k: int) -> int:
        n = len(houses)
        houses.sort()
        @lru_cache(maxsize = None)
        def dp(i, rem):
            if rem < 0:
                return float('inf')
            if i >= n:
                return 0
            res = float('inf')
            median = i
            sv = 2 * houses[i]
            lv = 2
            s = 0
            for j in range(i, n):
                lv -= 1
                sv -= houses[j]
                while median < (i + j) // 2:
                    median += 1
                    sv += 2 * houses[median]
                    lv += 2
                cost = houses[median] * lv - sv
                res = min(res, cost + dp(j + 1, rem - 1))
            return res
        return dp(0, k)

class Solution:
    def alphabetBoardPath(self, target: str) -> str:
        res = []
        prev = (0, 0)
        for i, c in enumerate(target):
            pos = ord(c) - ord('a')
            curr = (pos // 5, pos % 5)
            px, py = prev
            cx, cy = curr
            def xmove():
                nonlocal px, cx
                while px < cx:
                    res.append('D')
                    px += 1
                while px > cx:
                    res.append('U')
                    px -= 1
            def ymove():
                nonlocal py, cy
                while py < cy:
                    res.append('R')
                    py += 1
                while py > cy:
                    res.append('L')
                    py -= 1
            if c == 'z':
                ymove()
                xmove()
            else:
                xmove()
                ymove()
            res.append('!')
            prev = curr
        return "".join(res)

class Solution:
    def numberOfAlternatingGroups(self, colors: List[int]) -> int:
        k = 3
        for i in range(k - 1):
            colors.append(colors[i])
        n = len(colors)
        res = 0
        last = 0
        for i in range(n - 1, -1, -1):
            if i == n - 1 or colors[i] != colors[i + 1]:
                last += 1
            else:
                last = 1
            if last >= k:
                res += 1
        return res

class Solution:
    def numberOfAlternatingGroups(self, colors: List[int], k: int) -> int:
        for i in range(k - 1):
            colors.append(colors[i])
        n = len(colors)
