        for i in range(n - 1, -1, -1):
            if i == n - 1 or colors[i] != colors[i + 1]:
                last += 1
            else:
                last = 1
            if last >= k:
                res += 1
        return res

from collections import deque, defaultdict

class Solution:
    def inorder(self, root):
        if root.left:
            self.inorder(root.left)
            self.graph[root.val].add(root.left.val)
            self.graph[root.left.val].add(root.val)
        if root.right:
            self.inorder(root.right)
            self.graph[root.val].add(root.right.val)
            self.graph[root.right.val].add(root.val)

    def amountOfTime(self, root: Optional[TreeNode], start: int) -> int:
        if not root:
            return 0
        self.graph = defaultdict(set)
        self.inorder(root)
        q = deque([(start, 0)])
        v = {start}
        maxt = 0
        while len(q) > 0:
            curr, t = q.pop()
            maxt = t
            for j in self.graph[curr]:
                if j not in v:
                    v.add(j)
                    q.appendleft((j, t + 1))
        return maxt

class Solution:
    def angleClock(self, hour: int, minutes: int) -> float:
        mAngle = minutes * 6
        hAngle = (hour * 30 + minutes / 2) % 360
        diff = abs(mAngle - hAngle)
        return min(diff, 360 - diff)

class Solution:
    def returnToBoundaryCount(self, nums: List[int]) -> int:
        res = 0
        x = 0
        for el in nums:
            x += el
            if x == 0:
                res += 1
        return res

class Solution:
    def appendCharacters(self, s: str, t: str) -> int:
        m = len(s)
        n = len(t)
        i = 0
        for j in range(m):
            if i < n and s[j] == t[i]:
