class Solution:
    def discountPrices(self, sentence: str, discount: int) -> str:
        words = sentence.split()
        n = len(words)
        for i in range(n):
            if words[i][0] == '$' and words[i][1:].isnumeric():
                val = words[i][1:]
                newprice = eval(f"{val} * (1 - {discount} / 100)")
                newprice = "{:.2f}".format(newprice)
                words[i] = f"${newprice}"
        return " ".join(words)

class Solution:
    def applyOperations(self, nums: List[int]) -> List[int]:
        n = len(nums)
        for i in range(n - 1):
            if nums[i] == nums[i + 1]:
                nums[i] *= 2
                nums[i + 1] = 0
        i = 0
        for j in range(n):
            if nums[j] != 0:
                nums[i] = nums[j]
                i += 1
        for j in range(i, n):
            nums[j] = 0
        return nums

class Solution:
    def checkArray(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        diff = [0] * (n + 1)
        s = 0
        for i in range(n):
            s += diff[i]
            x = nums[i] - s
            if x < 0:
                return False
            if x > 0 and i + k > n:
                return False
            if x > 0:
                diff[i] += x
                s += x
                diff[i + k] -= x
        return True

from collections import *

class Solution:
    def lastNonEmptyString(self, s: str) -> str:
        n = len(s)
        ctr = Counter(s)
        ops = max(ctr.values())
        last = {}
        for i in range(n):
            last[s[i]] = i
        return "".join([s[i] for i in range(n) if last[s[i]] == i and ctr[s[i]] == ops])

import math

class Solution:
    def minOperations(self, k: int) -> int:
        res = k - 1
        p = int(math.sqrt(k))
        for x in range(p - 10, p + 10):
            if not 0 <= x <= k:
                continue
            val = 1 + x
            rem = math.ceil(k / val)
            res = min(res, x + rem - 1)
        return res

class Solution:
    def minops(self, unequals, i, ctr, n, x):
        if i >= n:
            if ctr == 0:
                return 0
            return float('inf')
        key = (i, ctr)
        if key in self.cache:
            return self.cache[key]
        res = float('inf')
        if i + 1 < n:
            res = min(res, self.minops(unequals, i + 2, ctr, n, x) + min(x, unequals[i + 1] - unequals[i]))
        if ctr > 0:
            res = min(res, self.minops(unequals, i + 1, ctr - 1, n, x))
        res = min(res, x + self.minops(unequals, i + 1, ctr + 1, n, x))
        self.cache[key] = res
        return res

    def minOperations(self, s1: str, s2: str, x: int) -> int:
        n = len(s1)
        unequals = []
        for i in range(n):
            if s1[i] != s2[i]:
                unequals.append(i)
        m = len(unequals)
        if m & 1:
            return -1
        self.cache = {}
        return self.minops(unequals, 0, 0, m, x)

class Solution:
    def maxFrequencyScore(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nums.sort()
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] = p[i] + nums[i]
        def count(i, j):
            l = j - i + 1
            pos = i + l // 2
            median = nums[pos]
            return (pos - i + 1) * median - (p[pos + 1] - p[i]) + (p[j + 1] - p[pos + 1]) - (j - pos) * median
        res = 0
        i = 0
        for j in range(n):
            while i < j and count(i, j) > k:
                i += 1
            if count(i, j) <= k:
                res = max(res, j - i + 1)
        return res

from collections import deque, Counter, defaultdict

class Solution:
    def numberOfArithmeticSlices(self, nums: List[int]) -> int:
        n = len(nums)
        res = 0
        ctr = Counter(nums)
        for el in ctr:
            res += 1 << ctr[el]
            res -= ctr[el] + 1
            res -= ctr[el] * (ctr[el] - 1) // 2
        pos = defaultdict(list)
        q = deque()
        for i in range(n):
            pos[nums[i]].append(i)
            for j in range(i + 1, n):
                if nums[j] != nums[i]:
                    q.appendleft((nums[j] - nums[i], j, 2))
        while len(q) > 0:
            d, i, l = q.pop()
            if l >= 3:
                res += 1
            for j in pos[nums[i] + d]:
                if j > i:
                    q.appendleft((d, j, l + 1))
        return res

from sortedcontainers import SortedList

def mos_algorithm(arr, queries):
    block_size = int(math.sqrt(len(arr)))
    sorted_queries = sorted(enumerate(queries), key=lambda x: x[1][0] // block_size)
    left, right = 0, -1
    order = SortedList()
    diffs = [0] * (max(arr) - min(arr) + 1)
    ctr = 0
    def remove(x):
        nonlocal ctr
        i = order.bisect_left(x)
        p = 0
        old = 0
        for j in [i - 1, i + 1]:
            if 0 <= j < len(order):
                p += 1
                oldiff = abs(order[i] - order[j])
                diffs[oldiff] -= 1
                if diffs[oldiff] == 0:
                    ctr -= 1
                if j == i - 1:
                    old -= order[j]
                else:
                    old += order[j]
        if p == 2:
            diffs[old] += 1
            if diffs[old] == 1:
                ctr += 1
        order.pop(i)
    def add(x):
        nonlocal ctr
        order.add(x)
        i = order.bisect_left(x)
        p = 0
        old = 0
        for j in [i - 1, i + 1]:
            if 0 <= j < len(order):
                p += 1
                oldiff = abs(order[i] - order[j])
                diffs[oldiff] += 1
                if diffs[oldiff] == 1:
                    ctr += 1
                if j == i - 1:
                    old -= order[j]
                else:
                    old += order[j]
        if p == 2:
            diffs[old] -= 1
            if diffs[old] == 0:
                ctr -= 1
    results = [0] * len(queries)
    for query_index, (query_left, query_right) in sorted_queries:
        while left > query_left:
            left -= 1
            add(arr[left])
        while right < query_right:
            right += 1
            add(arr[right])
        while left < query_left:
            remove(arr[left])
            left += 1
        while right > query_right:
            remove(arr[right])
            right -= 1
        results[query_index] = ctr == 1
    return results

class Solution:
    def checkArithmeticSubarrays(self, nums: List[int], l: List[int], r: List[int]) -> List[bool]:
        return mos_algorithm(nums, [(l[i], r[i]) for i in range(len(l))])

import math

class Solution:
    def arrangeCoins(self, n: int) -> int:
        k = math.floor((math.sqrt(1 + 8 * n) - 1) / 2)
        return k

class Solution:
    def DFS(self, nums, i, visited):
        visited.add(i)
        if nums[i] not in visited:
            return self.DFS(nums, nums[i], visited)
        else:
            return (i, visited)

    def arrayNesting(self, nums: List[int]) -> int:
        n = len(nums)
        mlen = 0
        visited = set()
        for i in range(n):
            if i not in visited:
                start, l = self.DFS(nums, i, set())
                end, l = self.DFS(nums, start, set())
                visited.update(l)
                mlen = max(mlen, len(l))
        return mlen

from collections import Counter

class Solution:
    def checkPos(self, arr):
        ctr = Counter()
        for el in arr:
            if ctr[el * 2] > 0:
                ctr[2 * el] -= 1
            else:
                ctr[el] += 1
        return sum(ctr.values()) == 0

    def canReorderDoubled(self, arr: List[int]) -> bool:
        n = len(arr)
        pos = []
        neg = []
        for el in arr:
            if el >= 0:
                pos.append(el)
            else:
                neg.append(-el)
        pos.sort(reverse = True)
        neg.sort(reverse = True)
        return self.checkPos(pos) and self.checkPos(neg)

class Solution:
    def arrayPairSum(self, nums: List[int]) -> int:
        nums.sort()
        n = len(nums)
        total = 0
        for i in range(0, n, 2):
