from collections import deque

class Solution:
    def maxDistance(self, grid: List[List[int]]) -> int:
        n = len(grid)
        q = deque()
        v = set()
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 1:
                    q.appendleft((i, j, 0))
                    v.add((i, j))
        res = -1
        while len(q) > 0:
            i, j, d = q.pop()
            if grid[i][j] == 0:
                res = max(res, d)
            for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
                if 0 <= x < n and 0 <= y < n and (x, y) not in v:
                    v.add((x, y))
                    if grid[i][j] != 1 or grid[x][y] != 1:
                        q.appendleft((x, y, d + 1))
        return res

class Solution:
    def findContentChildren(self, g: List[int], s: List[int]) -> int:
        g.sort()
        s.sort()
        n = len(s)
        ctr = 0
        i = 0
        for greed in g:
            while i < n and s[i] < greed:
                i += 1
            if i < n:
                i += 1
                ctr += 1
        return ctr

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        M = max(groups)
        f = [-1] * (M + 1)
        seen = set()
        for j in range(len(elements)):
            if elements[j] in seen:
                continue
            seen.add(elements[j])
            mul = 1
            while elements[j] * mul <= M:
                if f[elements[j] * mul] == -1:
                    f[elements[j] * mul] = j
                mul += 1
        return [f[x] for x in groups]

class Solution:
    def asteroidCollision(self, asteroids: List[int]) -> List[int]:
        stack = []
        for s in asteroids:
            if s < 0:
                exists = True
                while len(stack) > 0 and stack[-1] > 0:
                    if abs(stack[-1]) > abs(s):
                        exists = False
                        break
                    elif abs(stack[-1]) == abs(s):
                        exists = False
                        stack.pop()
                        break
                    stack.pop()
                if exists:
                    stack.append(s)
            else:
                stack.append(s)
        return stack

class Solution:
    def numRookCaptures(self, board: List[List[str]]) -> int:
        for i in range(8):
            for j in range(8):
                if board[i][j] == 'R':
                    ctr = 0
                    for di, dj in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        n = 0
                        while i + n * di >= 0 and i + n * di < 8 and j + n * dj >= 0 and j + n * dj < 8:
                            if board[i + n * di][j + n * dj] == 'B':
                                break
                            if board[i + n * di][j + n * dj] == 'p':
                                ctr += 1
                                break
                            n += 1
                    return ctr

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def averageOfLevels(self, root: Optional[TreeNode]) -> List[float]:
        if not root:
            return []
        queue = [(root, 0)]
        levels = {}
        level = 0
        while len(queue) > 0:
            curr, level = queue.pop(0)
            levels[level] = levels.get(level, []) + [curr.val]
            if curr.left:
                queue.append((curr.left, level + 1))
            if curr.right:
                queue.append((curr.right, level + 1))
        return [sum(levels[l])/len(levels[l]) for l in range(level + 1)]

class Solution:
    def average(self, salary: List[int]) -> float:
        n = len(salary)
        total = 0
        currmin = float('inf')
        currmax = float('-inf')
        for i in range(n):
            currmin = min(currmin, salary[i])
            currmax = max(currmax, salary[i])
            total += salary[i]
        return (total - currmin - currmax) / (n - 2)

class Solution:
    def averageValue(self, nums: List[int]) -> int:
        total = 0
        ctr = 0
        for el in nums:
            if el % 6 == 0:
                total += el
                ctr += 1
        if ctr == 0:
            return 0
        return total // ctr

class Solution:
    def averageWaitingTime(self, customers: List[List[int]]) -> float:
        free = 0
        res = 0
        for arrival, duration in customers:
            res += max(free - arrival, 0) + duration
            free = max(arrival, free) + duration
        res /= len(customers)
        return res

import heapq

class Solution:
    def avoidFlood(self, rains: List[int]) -> List[int]:
        n = len(rains)
        last = {}
        for i in range(n):
            if rains[i] != 0:
                last[rains[i]] = i
        res = []
        full = []
        fullset = set()
        for i in range(n):
            if rains[i] != 0:
                if rains[i] in fullset:
                    return []
                fullset.add(rains[i])
                heapq.heappush(full, (last.get(rains[i], float('inf')), rains[i]))
                res.append(-1)
            else:
                if full:
                    v, x = heapq.heappop(full)
                    fullset.remove(x)
                    res.append(x)
                else:
                    res.append(1)
            while full and full[0][0] <= i:
                heapq.heappop(full)
        return res

class Solution:
    def backspaceCompare(self, s: str, t: str) -> bool:
        ss = ""
        tt = ""
        for c in s:
            if c == "#":
                ss = ss[:-1]
            else:
                ss += c
        for c in t:
            if c == "#":
                tt = tt[:-1]
            else:
                tt += c
        return ss == tt

class Solution:
    def bagOfTokensScore(self, tokens: List[int], power: int) -> int:
        n = len(tokens)
        tokens.sort()
        res = 0
        i = 0
        j = n - 1
        while i <= j:
            if power >= tokens[i]:
                res += 1
                power -= tokens[i]
                i += 1
            elif res > 0 and i + 1 < j:
                res -= 1
                power += tokens[j]
                j -= 1
            else:
                break
        return res

class Solution:
    def inorder(self, root):
        if root:
            self.inorder(root.left)
            self.tree.append(root.val)
            self.inorder(root.right)

    def arrToTree(self, arr, i, j):
        if i <= j - 1:
            root = TreeNode()
            mid = (i + j) // 2
            root.val = arr[mid]
            root.left = self.arrToTree(arr, i, mid)
            root.right = self.arrToTree(arr, mid + 1, j)
            return root
        return None

    def balanceBST(self, root: TreeNode) -> TreeNode:
        self.tree = []
        self.inorder(root)
        return self.arrToTree(self.tree, 0, len(self.tree))

def check(root):
    if not root:
        return (True, 0)
    lvalid, lh = check(root.left)
    rvalid, rh = check(root.right)
    return lvalid and rvalid and abs(lh - rh) <= 1, 1 + max(lh, rh)

class Solution:
    def isBalanced(self, root: Optional[TreeNode]) -> bool:
        return check(root)[0]

class Solution:
    def convertToBase7(self, num: int) -> str:
        if num == 0:
            return "0"
        sign = ""
        if num < 0:
            sign = "-"
            num *= -1
        op = ""
        while num > 0:
            d = num % 7
            num = num // 7
            op = str(d) + op
        return sign + op

class Solution:
    def calPoints(self, ops: List[str]) -> int:
        score = [0]
        for op in ops:
            if op == "+":
                score.append(score[-1] + score[-2])
            elif op == "C":
                score.pop()
            elif op == "D":
                score.append(score[-1] << 1)
            else:
                score.append(int(op))
        return sum(score)

class Solution:
    def eval(self, a, op, b):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '/':
            return int(a / b)
        elif op == '*':
            return a * b

    def calculate(self, s: str) -> int:
        s += " "
        precedence = {
            '*': 1,
            '/': 1,
            '+': 0,
            '-': 0
        }
        numstack = []
        opstack = []
        chunk = ""
        for c in s:
            if c == " " or c in precedence:
                if len(chunk) > 0:
                    numstack.append(int(chunk))
                    chunk = ""
                if c in precedence:
                    while len(opstack) > 0 and precedence[opstack[-1]] >= precedence[c]:
                        currop = opstack.pop()
                        b = numstack.pop()
                        a = numstack.pop()
                        res = self.eval(a, currop, b)
                        numstack.append(res)
                    opstack.append(c)
            else:
                chunk += c
        while len(opstack) > 0:
            currop = opstack.pop()
            b = numstack.pop()
            a = numstack.pop()
            res = self.eval(a, currop, b)
            numstack.append(res)
        return numstack[0]

class Solution:
    def eval(self, a, op, b):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '/':
            return int(a / b)
        elif op == '*':
            return a * b

    def calculate(self, s: str) -> int:
        s += " "
        precedence = {
            '*': 1,
            '/': 1,
            '+': 0,
            '-': 0
        }
        brackets = {
            '(': 1,
            ')': -1
        }
        numstack = []
        opstack = []
        chunk = ""
        latestOpenBracket = True
        for c in s:
            if c == " " or c in precedence or c in brackets:
                if len(chunk) > 0:
                    numstack.append(int(chunk))
                    chunk = ""
                if c in brackets:
                    if brackets[c] == 1:
                        opstack.append('(')
                        latestOpenBracket = True
                    elif brackets[c] == -1:
                        latestOpenBracket = False
                        while opstack[-1] != '(':
                            currop = opstack.pop()
                            b = numstack.pop()
                            a = numstack.pop()
                            res = self.eval(a, currop, b)
                            numstack.append(res)
                        opstack.pop()
                elif c in precedence:
                    if latestOpenBracket:
                        numstack.append(0)
                    while len(opstack) > 0 and precedence.get(opstack[-1], -1) >= precedence[c]:
                        currop = opstack.pop()
                        b = numstack.pop()
                        a = numstack.pop()
                        res = self.eval(a, currop, b)
                        numstack.append(res)
                    opstack.append(c)
                    latestOpenBracket = False
            else:
                chunk += c
                latestOpenBracket = False
        while len(opstack) > 0:
            currop = opstack.pop()
            b = numstack.pop()
            a = numstack.pop()
            res = self.eval(a, currop, b)
            numstack.append(res)
        return numstack[0]

class Solution:
    def countBattleships(self, board: List[List[str]]) -> int:
        m = len(board)
        n = len(board[0])
        visited = set()
        res = 0
        for i in range(m):
            for j in range(n):
                if board[i][j] == "X" and (i, j) not in visited:
                    res += 1
                    visited.add((i, j))
                    l = 1
                    r = 1
                    u = 1
                    d = 1
                    while j - l >= 0 and board[i][j - l] == "X":
                        visited.add((i, j - l))
                        l += 1
                    while j + r < n and board[i][j + r] == "X":
                        visited.add((i, j + r))
                        r += 1
                    while i - u >= 0 and board[i - u][j] == "X":
                        visited.add((i - u, j))
                        u += 1
                    while i + d < m and board[i + d][j] == "X":
                        visited.add((i + d, j))
                        d += 1
        return res

class Solution:
    def count(self, i, n, used):
        if i > n:
            return 1
        ctr = 0
        for j in range(1, n + 1):
            if j not in used and (j % i == 0 or i % j == 0):
                ctr += self.count(i + 1, n, used.union({j}))
        return ctr

    def countArrangement(self, n: int) -> int:
        return self.count(1, n, set())

class Solution:
    def beautifulArray(self, N):
        return sorted(range(1, N + 1), key=lambda x: bin(x)[:1:-1])

class Solution:
    def maximumSumOfHeights(self, maxHeights: List[int]) -> int:
        n = len(maxHeights)
        pref = [0] * n
        suff = [0] * n
        stack = []
        for i in range(n):
            while len(stack) > 0 and maxHeights[i] < maxHeights[stack[-1]]:
                stack.pop()
            if len(stack) > 0:
                pref[i] = maxHeights[i] * (i - stack[-1]) + pref[stack[-1]]
            else:
                pref[i] = maxHeights[i] * (i + 1)
            stack.append(i)
        stack = []
        for i in range(n - 1, -1, -1):
            while len(stack) > 0 and maxHeights[i] < maxHeights[stack[-1]]:
                stack.pop()
            if len(stack) > 0:
                suff[i] = maxHeights[i] * (stack[-1] - i) + suff[stack[-1]]
            else:
                suff[i] = maxHeights[i] * (n - i)
            stack.append(i)
        res = 0
        for i in range(n):
            res = max(res, pref[i] + suff[i] - maxHeights[i])
        return res

