class Solution:
    def minTotalDistance(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        x = []
        y = []
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    x.append(i)
                    y.append(j)
        x.sort()
        y.sort()
        res = 0
        for el in x:
            res += abs(el - x[len(x) // 2])
        for el in y:
            res += abs(el - y[len(y) // 2])
        return res

from collections import defaultdict

class Solution:
    def bestHand(self, ranks: List[int], suits: List[str]) -> str:
        n = len(ranks)
        ctr = defaultdict(int)
        for r in ranks:
            ctr[r] += 1
        if len(set(suits)) == 1:
            return "Flush"
        for r in sorted(ctr.values(), reverse = True):
            if r >= 3:
                return "Three of a Kind"
            if r == 2:
                return "Pair"
        return "High Card"

import scipy.optimize as opt

class Solution:
    def getMinDistSum(self, positions):
        def f(x, y):
            return sum(math.sqrt((x - px) ** 2 + (y - py) ** 2) for px, py in positions)
        def blackbox_function(xy):
            x, y = xy
            return f(x, y)
        result = opt.minimize(blackbox_function, [50, 50], bounds=[(0, 100), (0, 100)], tol=1e-9)
        return result.fun

class Solution:
    def maxScoreSightseeingPair(self, values: List[int]) -> int:
        n = len(values)
        mleft = float('-inf')
        res = float('-inf')
        for i in range(n):
            res = max(res, mleft + values[i] - i)
            mleft = max(mleft, values[i] + i)
        return res

class Solution:
    def bestTeamScore(self, scores: List[int], ages: List[int]) -> int:
        n = len(scores)
        seq = sorted(range(n), key = lambda i: (ages[i], scores[i]))
        scores = [scores[seq[i]] for i in range(n)]
        scores.append(float('inf'))
        dp = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            for j in range(i + 1, n + 1):
                if scores[j] >= scores[i]:
                    dp[i] = max(dp[i], scores[i] + dp[j])
        return max(dp)

class Solution:
    def profit(self, prices, i, n, sign):
        if i >= n:
            return 0
        key = (i, sign)
        if key in self.cache:
            return self.cache[key]
        a = sign * prices[i] + self.profit(prices, i + 1, n, -sign)
        b = self.profit(prices, i + 1, n, sign)
        res = max(a, b)
        self.cache[key] = res
        return res

    def maxProfit(self, prices: List[int]) -> int:
        n = len(prices)
        self.cache = {}
        return self.profit(prices, 0, n, -1)

class Solution:
    def profit(self, prices, i, n, sign, rem):
        if i >= n or rem == 0:
            return 0
        key = (i, sign, rem)
        if key in self.cache:
            return self.cache[key]
        a = sign * prices[i] + self.profit(prices, i + 1, n, -sign, rem - 1)
        b = self.profit(prices, i + 1, n, sign, rem)
        res = max(a, b)
        self.cache[key] = res
        return res

    def maxProfit(self, k: int, prices: List[int]) -> int:
        n = len(prices)
        self.cache = {}
        return self.profit(prices, 0, n, -1, 2 * k)

class Solution:
    def maxProfit(self, prices: List[int]) -> int:
        n = len(prices)
        dp = [0] * (n + 2)
        mval = float('-inf')
        for i in range(n - 1, -1, -1):
            dp[i] = max(dp[i], mval - prices[i])
            dp[i] = max(dp[i], dp[i + 1])
            mval = max(mval, prices[i] + dp[i + 2])
        return dp[0]

class Solution:
    def profit(self, prices, i, n, sign, fee):
        if i >= n:
            return 0
        key = (i, sign)
        if key in self.cache:
            return self.cache[key]
        a = sign * prices[i] + self.profit(prices, i + 1, n, -sign, fee)
        b = self.profit(prices, i + 1, n, sign, fee)
        if sign == -1:
            a -= fee
        res = max(a, b)
        self.cache[key] = res
        return res

    def maxProfit(self, prices: List[int], fee: int) -> int:
        n = len(prices)
        self.cache = {}
        return self.profit(prices, 0, n, -1, fee)

class Solution:
    def maxProfit(self, prices: List[int]) -> int:
        res = 0
        minpastvalue = float('inf')
        for price in prices:
            res = max(res, price - minpastvalue)
            minpastvalue = min(minpastvalue, price)
        return res

class Solution:
    def binaryGap(self, n: int) -> int:
        curr = "{:b}".format(n)
        n = len(curr)
        mdist = 0
        prev = -1
        for i in range(n):
            if curr[i] == "1":
                if prev >= 0:
                    mdist = max(mdist, i - prev)
                prev = i
        return mdist

class Solution:
    def hasAlternatingBits(self, n: int) -> bool:
        bi = "{:b}".format(n)
        for i, c in enumerate(bi):
            if i > 0:
                if c == bi[i - 1]:
                    return False
        return True

class Solution:
    def prefixesDivBy5(self, nums: List[int]) -> List[bool]:
        val = 0
        op = []
        for num in nums:
            val = 2 * val + num
            if val % 5 == 0:
                op.append(True)
            else:
                op.append(False)
        return op

class Solution:
    def revinorder(self, root):
        if root:
            self.revinorder(root.right)
            self.curr += root.val
            root.val = self.curr
            self.revinorder(root.left)

    def bstToGst(self, root: TreeNode) -> TreeNode:
        self.curr = 0
        self.revinorder(root)
        return root

class Solution:
    def search(self, nums, target):
        n = len(nums)
        res = -1
        for p in range(20, -1, -1):
            pw = 1 << p
            if res + pw < n and nums[res + pw] < target:
                res += pw
        res += 1
        if res >= n or nums[res] != target:
            return -1
        return res

import random

class Solution:
    def queryString(self, s: str, n: int) -> bool:
        for _ in range(10000):
