class Solution:
    def levelOrderBottom(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []
        queue = [(root, 0)]
        levels = {}
        level = 0
        while len(queue) > 0:
            curr, level = queue.pop(0)
            levels[level] = levels.get(level, []) + [curr.val]
            if curr.left:
                queue.append((curr.left, level + 1))
            if curr.right:
                queue.append((curr.right, level + 1))
        return [levels[l] for l in range(level, -1, -1)]

from collections import deque

class Solution:
    def levelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        res = []
        if not root:
            return res
        q = deque([root])
        while q:
            res.append([])
            for _ in range(len(q)):
                curr = q.pop()
                res[-1].append(curr.val)
                if curr.left:
                    q.appendleft(curr.left)
                if curr.right:
                    q.appendleft(curr.right)
        return res

class Solution:
    def pathsum(self, root):
        if root:
            l = self.pathsum(root.left)
            r = self.pathsum(root.right)
            self.msum = max(self.msum, root.val, l + root.val, root.val + r, l + root.val + r)
            return max(root.val, root.val + l, root.val + r)
        return float('-inf')

    def maxPathSum(self, root: Optional[TreeNode]) -> int:
        self.msum = float('-inf')
        self.pathsum(root)
        return self.msum

# Definition for a binary tree node.
