class Solution:
    def hasOne(self, root):
        if root:
            if root.val == 1:
                return True
            if self.hasOne(root.left) or self.hasOne(root.right):
                return True
        return False

    def pruneTree(self, root: Optional[TreeNode]) -> Optional[TreeNode]:
        if not self.hasOne(root):
            return None
        root.left = self.pruneTree(root.left)
        root.right = self.pruneTree(root.right)
        return root

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def getHeight(self, root):
        if root:
            return 1 + max(self.getHeight(root.left), self.getHeight(root.right))
        return 0

    def rightSideView(self, root: Optional[TreeNode]) -> List[int]:
        h = self.getHeight(root)
        cols = (1 << h) - 1
        res = [(None, float('-inf'))] * h
        nodes = [(root, 0, 0, cols)]
        while len(nodes) > 0:
            curr, l, a, b = nodes.pop()
            if curr:
                i = (a + b) // 2
                if i > res[l][1]:
                    res[l] = (curr.val, i)
                nodes.append((curr.left, l + 1, a, i))
                nodes.append((curr.right, l + 1, i, b))
        return [r[0] for r in res]

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def sumOfTree(self, root):
        if root:
            return root.val + self.sumOfTree(root.left) + self.sumOfTree(root.right)
        return 0

    def findTilt(self, root: Optional[TreeNode]) -> int:
        if root:
            l = self.sumOfTree(root.left)
            r = self.sumOfTree(root.right)
            return abs(l - r) + self.findTilt(root.left) + self.findTilt(root.right)
        else:
            return 0

from collections import deque

class Solution:
    def zigzagLevelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []
        queue = deque([(root, 0)])
        levels = {}
        level = 0
        while len(queue) > 0:
            curr, level = queue.pop()
            if curr:
                levels[level] = levels.get(level, []) + [curr.val]
                queue.appendleft((curr.left, level + 1))
                queue.appendleft((curr.right, level + 1))
        return [levels[l][::1 - 2 * (l % 2)] for l in range(level)]

class Solution:
    def rangeBitwiseAnd(self, left: int, right: int) -> int:
        res = 0
        pw = 1
        for b in range(32):
            r = 2 * pw * math.ceil((left + 1) / (pw * 2))
            if left & pw and r > right:
                res += pw
            pw *= 2
        return res

class Solution:
    def subarrayBitwiseORs(self, arr: List[int]) -> int:
        n = len(arr)
        lastone = [-1] * 32
        res = set()
        for i in range(n):
            for b in range(32):
                if arr[i] & (1 << b):
                    lastone[b] = i
            curr = arr[i]
            res.add(curr)
            for j in sorted(lastone, reverse = True):
                if j == -1:
                    break
                curr |= arr[j]
                res.add(curr)
        return len(res)

class Solution:
    def xorAllNums(self, nums1: List[int], nums2: List[int]) -> int:
        res = 0
        m = len(nums1)
        n = len(nums2)
        for i in range(m):
            if n % 2 == 1:
                res ^= nums1[i]
        for j in range(n):
            if m % 2 == 1:
                res ^= nums2[j]
        return res

from sortedcontainers import SortedList

class SegmentTree:
    def __init__(self, data, default=0, func=max):
        """initialize the segment tree with data"""
        self._default = default
        self._func = func
        self._len = len(data)
        self._size = _size = 1 << (self._len - 1).bit_length()

        self.data = [default] * (2 * _size)
        self.data[_size:_size + self._len] = data
        for i in reversed(range(_size)):
            self.data[i] = func(self.data[i + i], self.data[i + i + 1])

    def __delitem__(self, idx):
        self[idx] = self._default

    def __getitem__(self, idx):
        return self.data[idx + self._size]

    def __setitem__(self, idx, value):
        idx += self._size
        self.data[idx] = value
        idx >>= 1
        while idx:
            self.data[idx] = self._func(self.data[2 * idx], self.data[2 * idx + 1])
            idx >>= 1

    def __len__(self):
        return self._len

    def query(self, start, stop):
        """func of data[start, stop)"""
        start += self._size
        stop += self._size

        res_left = res_right = self._default
        while start < stop:
            if start & 1:
                res_left = self._func(res_left, self.data[start])
                start += 1
            if stop & 1:
                stop -= 1
                res_right = self._func(self.data[stop], res_right)
            start >>= 1
            stop >>= 1

        return self._func(res_left, res_right)

class Solution:
    def getResults(self, queries: List[List[int]]) -> List[bool]:
        MX = min(5 * 10 ** 4, 3 * len(queries)) + 10
        bst = SortedList([0, MX])
        segtree = SegmentTree([0] * (MX + 1))
        res = []
        for q in queries:
            if q[0] == 1:
                x = q[1]
                pos = bst.bisect_left(x)
                l = bst[pos - 1]
                r = bst[pos]
                segtree[r] = r - x
                segtree[x] = x - l
                bst.add(x)
            if q[0] == 2:
                x, sz = q[1], q[2]
                pos = bst.bisect_left(x)
                if bst[pos] > x:
                    pos -= 1
                l = bst[pos]
                if x - l >= sz:
                    res.append(True)
                else:
                    res.append(segtree.query(0, x + 1) >= sz)
        return res

class Solution:
    def numRescueBoats(self, people: List[int], limit: int) -> int:
        people.sort()
        n = len(people)
        ctr = 0
        i, j = 0, n - 1
        while i <= j:
            ctr += 1
            if people[i] + people[j] <= limit:
                i += 1
            j -= 1
        return ctr

class Solution:
    def breakPalindrome(self, palindrome: str) -> str:
        n = len(palindrome)
        if n == 1:
            return ""
        isNotA = False
        minstr = ""
        for i in range(n):
            if palindrome[i] > 'a' and 2 * i + 1 != n:
                minstr = palindrome[:i] + 'a' + palindrome[i+1:]
                isNotA = True
                break
        if not isNotA:
            return palindrome[:-1] + 'b'
        return minstr

class Solution:
    def leastBricks(self, wall: List[List[int]]) -> int:
        m = len(wall)
        ctr = {}
        res = m
        for i in range(m):
            n = len(wall[i])
            curr = 0
            for j in range(n - 1):
                curr += wall[i][j]
                x = ctr.get(curr, m) - 1
                ctr[curr] = x
                res = min(res, x)
        return res

class Solution:
    def brokenCalc(self, startValue: int, target: int) -> int:
        if startValue >= target:
            return startValue - target
        if target % 2 == 0:
            return 1 + self.brokenCalc(startValue, target // 2)
        else:
            return 2 + self.brokenCalc(startValue, (target + 1) // 2)

class Solution:
    def buddyStrings(self, s: str, goal: str) -> bool:
        m = len(s)
        n = len(goal)
        if m != n:
            return False
        sdiff = []
        gdiff = []
        eq = False
        seen = set()
        for i in range(n):
            if s[i] != goal[i]:
                sdiff.append(s[i])
                gdiff.append(goal[i])
            else:
                if s[i] in seen:
                    eq = True
                seen.add(s[i])
        if s == goal:
            return eq
        if not len(sdiff) == len(gdiff) == 2:
            return False
        return sorted(sdiff) == sorted(gdiff)

from collections import defaultdict, deque

class Solution:
    def getSort(self, edges, k):
        graph = defaultdict(set)
        for a, b in edges:
            graph[a].add(b)
        indegree = [0] * (k + 1)
        for a in graph:
            for b in graph[a]:
                indegree[b] += 1
        res = []
        q = deque()
        for i in range(1, k + 1):
            if indegree[i] == 0:
                q.append(i)
        while len(q) > 0:
            curr = q.pop()
            res.append(curr)
            for j in graph[curr]:
                indegree[j] -= 1
                if indegree[j] == 0:
                    q.appendleft(j)
        return res

    def buildMatrix(self, k: int, rowConditions: List[List[int]], colConditions: List[List[int]]) -> List[List[int]]:
        matrix = [[0] * k for _ in range(k)]
        colsort = self.getSort(colConditions, k)
        rowsort = self.getSort(rowConditions, k)
        if len(colsort) < k or len(rowsort) < k:
            return []
        pos = {}
        for i in range(k):
            pos[rowsort[i]] = i
        for i in range(k):
            matrix[pos[colsort[i]]][i] = colsort[i]
        return matrix

class Solution:
    def buildArray(self, target: List[int], n: int) -> List[str]:
        res = []
        i = 0
        for j in range(1, target[-1] + 1):
            while i < len(target) and target[i] < j:
                i += 1
            res.append("Push")
            if i == len(target) or target[i] != j:
                res.append("Pop")
        return res

class Solution:
    def buildArray(self, nums: List[int]) -> List[int]:
        return [nums[num] for num in nums]

M = 10 ** 9 + 7

class Solution:
    def count(self, i, n, maxval, m, rem):
        if rem < 0 or rem > n - i:
            return 0
        if i >= n:
            return 1
        key = (i, maxval, rem)
        if key in self.cache:
            return self.cache[key]
        res = maxval * self.count(i + 1, n, maxval, m, rem)
        for j in range(maxval + 1, m + 1):
            res += self.count(i + 1, n, j, m, rem - 1)
            res %= M
        res %= M
        self.cache[key] = res
        return res

    def numOfArrays(self, n: int, m: int, k: int) -> int:
        self.cache = {}
        return self.count(0, n, 0, m, k)

class Solution:
    def bulbSwitch(self, n: int) -> int:
        return int(n ** 0.5)

class Solution:
    def getHint(self, secret: str, guess: str) -> str:
        n = len(secret)
        unused = {}
        bulls = 0
        cows = 0
        for i in range(n):
            if secret[i] == guess[i]:
                bulls += 1
            else:
                unused[secret[i]] = unused.get(secret[i], 0) + 1
        for i in range(n):
            if secret[i] != guess[i]:
                if guess[i] in unused:
                    cows += 1
                    unused[guess[i]] -= 1
                    if unused[guess[i]] == 0:
                        del unused[guess[i]]
        return "{}A{}B".format(bulls, cows)

class Solution:
    def score(self, nums, i, j, n):
        if i > j:
            return 0
        if i == j:
            l = 1 if i == 0 else nums[i - 1]
            r = 1 if i == n - 1 else nums[i + 1]
            return l * nums[i] * r
        if self.cache[i][j] != -1:
            return self.cache[i][j]
        res = 0
        for k in range(i, j + 1):
            l = 1 if i == 0 else nums[i - 1]
            r = 1 if j == n - 1 else nums[j + 1]
            res = max(res, l * nums[k] * r + self.score(nums, i, k - 1, n) + self.score(nums, k + 1, j, n))
        self.cache[i][j] = res
        return res

    def maxCoins(self, nums: List[int]) -> int:
        n = len(nums)
        self.cache = [[-1] * n for _ in range(n)]
        return self.score(nums, 0, n - 1, n)

from collections import *

class Solution:
    def numBusesToDestination(self, routes: List[List[int]], source: int, target: int) -> int:
        if source == target:
            return 0
        graph = defaultdict(set)
        for s in range(len(routes)):
            m = len(routes[s])
            for i in range(m):
                a = (routes[s][i], s)
                b = (routes[s][(i + 1) % m], s)
                graph[a].add((b, 0))
                graph[a].add(((routes[s][i], -1), 0))
                graph[(routes[s][i], -1)].add((a, 1))
        q = deque([(source, -1, 0)])
        dist = defaultdict(lambda: float('inf'))
        dist[(source, -1, 0)] = 0
        while len(q) > 0:
            curr, s, d = q.pop()
            if curr == target and s != -1:
                return d
            for j, cost in graph[(curr, s)]:
                if dist[j] > d + cost:
                    dist[j] = d + cost
                    if cost == 0:
                        q.append((j[0], j[1], dist[j]))
                    else:
                        q.appendleft((j[0], j[1], dist[j]))
        return -1

class Solution:
    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        res = (-1, -1)
        prev = 0
        for pos, t in events:
            curr = t - prev
            if curr > res[0]:
                res = (curr, pos)
            if curr == res[0] and pos < res[1]:
                res = (curr, pos)
            prev = t
        return res[1]

class Solution:
    def buyChoco(self, prices: List[int], money: int) -> int:
        a, b = float('inf'), float('inf')
        for el in prices:
            a, b, temp = sorted([a, b, el])
        if a + b > money:
            return money
        return money - a - b

class Solution:
    def calculateTax(self, brackets: List[List[int]], income: int) -> float:
        rem = income
        tax = 0
        prev = 0
        for b, p in brackets:
            if income >= b:
                tax += (b - prev) * p
                rem -= (b - prev)
                prev = b
            elif rem > 0:
                tax += rem * p
                rem = 0
                break
        return tax / 100

class Solution:
    def findDelayedArrivalTime(self, arrivalTime: int, delayedTime: int) -> int:
