class Solution:
    def digitSum(self, s: str, k: int) -> str:
        while len(s) > k:
            nexts = ""
            for i in range(0, len(s), k):
                nexts += str(sum(int(d) for d in s[i:i+k]))
            s = nexts
        return s

class Solution:
    def totalMoney(self, n: int) -> int:
        k = n // 7
        rem = n % 7
        return 28 * k + 7 * k * (k - 1) // 2 + k * rem + rem * (rem + 1) // 2

class Solution:
    def camelMatch(self, queries: List[str], pattern: str) -> List[bool]:
        n = len(pattern)
        pattCaps = "".join([c for c in pattern if c.isupper()])
        answer = []
        for q in queries:
            m = len(q)
            qCaps = "".join([c for c in q if c.isupper()])
            if pattCaps != qCaps:
                answer.append(False)
                continue
            i = 0
            j = 0
            while i < n and j < m:
                if pattern[i] == q[j]:
                    i += 1
                    j += 1
                else:
                    j += 1
            answer.append(i == n)
        return answer

class Solution:
    def canwin(self, rem, used, mx):
        if rem <= 0:
            return False
        key = used
        if key in self.cache:
            return self.cache[key]
        for c in range(1, mx + 1):
            if not used & (1 << c):
                if not self.canwin(rem - c, used | (1 << c), mx):
                    self.cache[key] = True
                    return True
        self.cache[key] = False
        return False

    def canIWin(self, maxChoosableInteger: int, desiredTotal: int) -> bool:
        if desiredTotal == 0:
            return True
        if maxChoosableInteger * (maxChoosableInteger + 1) < desiredTotal * 2:
            return False
        self.cache = {}
        return self.canwin(desiredTotal, 0, maxChoosableInteger)

from collections import Counter

class Solution:
    def canMakeArithmeticProgression(self, arr: List[int]) -> bool:
        n = len(arr)
        if n == 1:
            return True
        arr = Counter(arr)
        a = min(arr)
        b = max(arr)
        d = (b - a) // (n - 1)
        if d == 0 and len(arr) == 1:
            return True
        for i in range(n):
            if arr[a + i * d] != 1:
                return False
        return True

class Solution:
    def canMakePaliQueries(self, s: str, queries: List[List[int]]) -> List[bool]:
        n = len(s)
        p = [[0] * 26 for _ in range(n + 1)]
        for i in range(n):
            for c in range(26):
                p[i + 1][c] += p[i][c]
            p[i + 1][ord(s[i]) - ord('a')] += 1
        res = []
        for l, r, k in queries:
            odds = 0
            for c in range(26):
                if p[r + 1][c] % 2 != p[l][c] % 2:
                    odds += 1
            res.append(k >= odds // 2)
        return res

class Solution:
    def canPlaceFlowers(self, flowerbed: List[int], n: int) -> bool:
        m = len(flowerbed)
        fctr = 0
        i = 0
        seen = False
        while i < m:
            ctr = 1
            while i < m - 1 and flowerbed[i] == flowerbed[i + 1]:
                i += 1
                ctr += 1
            if flowerbed[i] == 0:
                if seen and i < m - 1:
                    fctr += (ctr - 1) // 2
                elif seen or i < m - 1:
                    fctr += ctr // 2
                else:
                    fctr += (ctr + 1) // 2
            else:
                seen = True
            i += 1
        return fctr >= n

class Solution:
    def candy(self, ratings: List[int]) -> int:
        n = len(ratings)
        graph = [[] for _ in range(n)]
        indeg = [0] * n
        for i in range(n - 1):
            if ratings[i + 1] > ratings[i]:
                graph[i].append(i + 1)
                indeg[i + 1] += 1
            if ratings[i] > ratings[i + 1]:
                graph[i + 1].append(i)
                indeg[i] += 1
        res = [0] * n
        q = deque()
        for i in range(n):
            if indeg[i] == 0:
                q.append(i)
                res[i] = 1
        while q:
            u = q.popleft()
            for v in graph[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    res[v] = res[u] + 1
                    q.append(v)
        return sum(res)

class Solution:
    def numDays(self, weights, capacity):
        curr = 0
        res = 1
        for el in weights:
            if curr + el <= capacity:
                curr += el
            else:
                curr = el
                res += 1
        return res

    def shipWithinDays(self, weights: List[int], days: int) -> int:
        n = len(weights)
        beg = max(weights)
        end = sum(weights)
        res = end
        while beg <= end:
            mid = (beg + end) // 2
            if self.numDays(weights, mid) <= days:
                res = mid
                end = mid - 1
            else:
                beg = mid + 1
        return res

class Solution:
    def capitalizeTitle(self, title: str) -> str:
        words = title.split()
        words = [word.lower() for word in words]
        words = [(word[0].upper() + word[1:]) if len(word) > 2 else word for word in words]
        return " ".join(words)

class Solution:
    def carFleet(self, target: int, position: List[int], speed: List[int]) -> int:
        n = len(position)
        cars = [(position[i], speed[i]) for i in range(n)]
        cars.sort()
        prev = (float('inf'), float('inf'))
        res = n
        for i in range(n - 1, -1, -1):
            dist = prev[0] - cars[i][0]
            duration = cars[i][1] - prev[1]
            if duration * cars[i][0] + dist * cars[i][1] <= target * duration:
                res -= 1
            else:
                prev = cars[i]
        return res

import heapq

class Solution:
    def carPooling(self, trips: List[List[int]], capacity: int) -> bool:
        n = len(trips)
        points = []
        for i in range(n):
            num, source, dest = trips[i]
            heapq.heappush(points, (source, num))
            heapq.heappush(points, (dest, -num))
        curr = 0
        while len(points) > 0:
            curr += heapq.heappop(points)[1]
            if curr > capacity:
                return False
        return True

