        cols = [0] * n
        rows = [0] * m
        ctr = 0
        for r, c in indices:
            rows[r] += 1
            cols[c] += 1
        for i in range(n):
            for j in range(m):
                if (cols[i] + rows[j]) % 2 == 1:
                    ctr += 1
        return ctr

class Solution:
    def getRowState(self, poured, query_row):
        if query_row == 0:
            return [poured]
        prev = self.getRowState(poured, query_row - 1)
        curr = [0] * (query_row + 1)
        for i in range(query_row):
            if prev[i] > 1:
                extra = (prev[i] - 1) / 2
                curr[i] += extra
                curr[i + 1] += extra
        return curr

    def champagneTower(self, poured: int, query_row: int, query_glass: int) -> float:
        state = self.getRowState(poured, query_row)
        return min(state[query_glass], 1)

from collections import defaultdict
import heapq

class Solution:
    def findCheapestPrice(self, n: int, flights: List[List[int]], src: int, dst: int, k: int) -> int:
        graph = defaultdict(list)
        for a, b, c in flights:
            graph[a].append((b, c))
        dist = defaultdict(lambda: float('inf'))
        dist[(src, k)] = 0
        heap = []
        for i in range(n):
            heapq.heappush(heap, (dist[(i, k)], i, k))
        while len(heap) > 0:
            d, curr, rem = heapq.heappop(heap)
            for j, c in graph[curr]:
                newrem = rem - 1
                if j == dst:
                    newrem = rem
                if newrem >= 0 and dist[(j, newrem)] > d + c:
                    dist[(j, newrem)] = d + c
                    heapq.heappush(heap, (dist[(j, newrem)], j, newrem))
        res = float('inf')
        for rem in range(k + 1):
            res = min(res, dist[(dst, rem)])
        if res == float('inf'):
            return -1
        return res

class Solution:
    def canFormArray(self, arr: List[int], pieces: List[List[int]]) -> bool:
