class Solution:
    def isCompleteTree(self, root: Optional[TreeNode]) -> bool:
        nodes = [(root, 0)]
        keys = {}
        while len(nodes) > 0:
            curr, l = nodes.pop()
            keys[l] = curr.val
            if curr.left:
                nodes.append((curr.left, 2 * l + 1))
            if curr.right:
                nodes.append((curr.right, 2 * l + 2))
        mkey = max(keys.keys())
        for l in range(mkey):
            if l not in keys:
                return False
        return True

class Solution:
    def checkDistances(self, s: str, distance: List[int]) -> bool:
        n = len(s)
        prev = [None] * 26
        index = lambda c: ord(c) - ord('a')
        for i in range(n):
            if prev[index(s[i])] != None:
                if i - prev[index(s[i])] - 1 != distance[index(s[i])]:
                    return False
            prev[index(s[i])] = i
        return True

from collections import deque

class Solution:
    def canBeValid(self, s: str, locked: str) -> bool:
        n = len(s)
        if n & 1:
            return False
        opens = []
        extra = []
        for i in range(n):
            if locked[i] == '0':
                extra.append(i)
                continue
            if s[i] == '(':
                opens.append(i)
            else:
                if opens:
                    opens.pop()
                elif extra:
                    extra.pop()
                else:
                    return False
        while opens:
            x = opens.pop()
            if not extra:
                return False
            if extra[-1] < x:
                return False
            extra.pop()
        return len(extra) % 2 == 0

class Solution:
    def check(self, s1, s2):
        n = len(s1)
        ctr = [0] * 26
        for c in s2:
            ctr[ord(c) - ord('a')] += 1
        for c in s1:
            x = ord(c) - ord('a')
            done = False
            for d in range(x, 26):
                if ctr[d] > 0:
                    ctr[d] -= 1
                    done = True
                    break
            if not done:
                return False
        return True

    def checkIfCanBreak(self, s1: str, s2: str) -> bool:
        return self.check(s1, s2) or self.check(s2, s1)

class Solution:
    def hasAllCodes(self, s: str, k: int) -> bool:
        n = len(s)
        codes = set()
        curr = int(s[0:k], 2)
        codes.add(curr)
        for i in range(n - k):
            curr = (curr << 1) - int(s[i]) * (1 << k) + int(s[i + k])
            codes.add(curr)
        return len(codes) == 1 << k

