class Solution:
    # s[i : j + 1] is palindrome if P[i + j + 2] >= j - i + 1
    def manachers(self, s):
        T = '#'.join('^{}$'.format(s))
        n = len(T)
        P = [0] * n
        C = R = 0
        for i in range(1, n - 1):
            if R > i:
                P[i] = min(R - i, P[2 * C - i])
            while T[i + 1 + P[i]] == T[i - 1 - P[i]]:
                P[i] += 1
            if i + P[i] > R:
                C, R = i, i + P[i]
        return P

    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        graph = [[] for _ in range(n)]
        for i in range(1, n):
            graph[parent[i]].append(i)
        ctr = [0] * n
        pos = [0] * n
        v = []
        def dfs(i):
            ctr[i] += 1
            for j in sorted(graph[i]):
                dfs(j)
                ctr[i] += ctr[j]
            v.append(s[i])
            pos[i] = len(v) - 1
        dfs(0)
        pal = self.manachers("".join(v))
        return [pal[2*pos[i]-ctr[i]+3]>=ctr[i] for i in range(n)]

class Solution:
    def hasSameDigits(self, s: str) -> bool:
        def binom_mod2(n, r):
            return 1 if (n & r) == r else 0
        binom5 = [[0] * 5 for _ in range(5)]
        for i in range(5):
            for j in range(i + 1):
                if j == 0 or j == i:
                    binom5[i][j] = 1
                else:
                    binom5[i][j] = (binom5[i - 1][j - 1] + binom5[i - 1][j]) % 5
        def lucas(n, r):
            res = 1
            while n or r:
                n_i, r_i = n % 5, r % 5
                if r_i > n_i:
                    return 0
                res = (res * binom5[n_i][r_i]) % 5
                n //= 5
                r //= 5
            return res
        def combine(x2, x5):
            for cand in range(x5, 10, 5):
                if cand % 2 == x2:
                    return cand
            return 0
        def binom_mod10(n, r):
            return combine(binom_mod2(n, r), lucas(n, r))
        n = len(s)
        if n < 2:
            return True
        mod1 = 0
        mod2 = 0
        for i in range(n - 1):
            c = binom_mod10(n - 2, i)
            mod1 = (mod1 + int(s[i]) * c) % 10
            mod2 = (mod2 + int(s[i + 1]) * c) % 10
        return mod1 == mod2

