        for i in range(m):
            for j in range(n):
                if i + 1 < m and grid[i][j] != grid[i + 1][j]:
                    return False
                if j + 1 < n and grid[i][j] == grid[i][j + 1]:
                    return False
        return True

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

class Solution:
    def isGoodArray(self, nums: List[int]) -> bool:
        res = nums[0]
        for el in nums:
            res = gcd(res, el)
        return res == 1

class Solution:
    def gcd(self, a, b):
        while b:
            a, b = b, a % b
        return a

    def checkStraightLine(self, coordinates: List[List[int]]) -> bool:
        n = len(coordinates)
        m = None
        for i in range(1, n):
            dy = coordinates[i][1] - coordinates[0][1]
            dx = coordinates[i][0] - coordinates[0][0]
            sign = -1 if (dx >= 0) ^ (dy >= 0) else 1
            if dx == 0 or dy == 0:
                sign = 1
            curr = (sign, abs(dy), abs(dx))
            mul = self.gcd(curr[1], curr[2])
            if mul > 0:
                curr = (curr[0], curr[1] // mul, curr[2] // mul)
            if m:
                if curr != m:
                    return False
            else:
                m = curr
        return True

class Solution:
    def check(self, p, i, j, m):
        if i == j:
            return True
        if i + 1 == j:
            return True
        key = (i, j)
        if key in self.cache:
            return self.cache[key]
        s = p[j + 1] - p[i]
        if s - (p[i + 1] - p[i]) >= m and self.check(p, i + 1, j, m):
            self.cache[key] = True
            return True
        if s - (p[j + 1] - p[j]) >= m and self.check(p, i, j - 1, m):
            self.cache[key] = True
            return True
        self.cache[key] = False
        return False

    def canSplitArray(self, nums: List[int], m: int) -> bool:
        n = len(nums)
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] += p[i] + nums[i]
        self.cache = {}
        return self.check(p, 0, n - 1, m)

class Solution:
    def checkXMatrix(self, grid: List[List[int]]) -> bool:
        n = len(grid[0])
        for i in range(n):
            for j in range(n):
                if i - j == 0 or i + j == n - 1:
                    if grid[i][j] == 0:
                        return False
                else:
                    if grid[i][j] != 0:
                        return False
        return True

class Solution:
