        curr = None
        for c in s:
            if c == " ":
                if token.isdigit():
                    if curr:
                        if int(token) <= curr:
                            return False
                    curr = int(token)
                token = ""
            else:
                token += c
        return True

class Solution:
    def areAlmostEqual(self, s1: str, s2: str) -> bool:
        m = len(s1)
        n = len(s2)
        if m != n:
            return False
        if s1 == s2:
            return True
        s1diff = []
        s2diff = []
        for i in range(n):
            if s1[i] != s2[i]:
                s1diff.append(s1[i])
                s2diff.append(s2[i])
        if not len(s1diff) == len(s2diff) == 2:
            return False
        return sorted(s1diff) == sorted(s2diff)

class Solution:
    def sort(self, s):
        n = len(s)
        s = list(s)
        vals = [[], []]
        for i in range(n):
            vals[i % 2].append(s[i])
        vals[0].sort(reverse = True)
        vals[1].sort(reverse = True)
        for i in range(n):
            s[i] = vals[i % 2].pop()
        return "".join(s)

    def canBeEqual(self, s1: str, s2: str) -> bool:
        return self.sort(s1) == self.sort(s2)

class Solution:
