from functools import lru_cache

class Solution:
    @lru_cache(maxsize=None)
    def hasPath(self, i, j, m, n, ctr):
        pmap = { '(': 1, ')': -1 }
        if ctr >= 0 and 0 <= i < m and 0 <= j < n:
            curr = self.grid[i][j]
            ctr += pmap[curr]
            if (i, j) == (m - 1, n - 1):
                return ctr == 0
            if self.hasPath(i + 1, j, m, n, ctr) or self.hasPath(i, j + 1, m, n, ctr):
                return True
        return False

    def hasValidPath(self, grid: List[List[str]]) -> bool:
        m = len(grid)
        n = len(grid[0])
        self.grid = grid
        return self.hasPath(0, 0, m, n, 0)

class Solution:
    def validPartition(self, nums: List[int]) -> bool:
        n = len(nums)
        dp = [False] * (n + 1)
        dp[0] = True
        for i in range(1, n + 1):
            if i >= 2 and nums[i - 1] == nums[i - 2]:
                dp[i] = dp[i] or dp[i - 2]
            if i >= 3 and nums[i - 1] == nums[i - 2] == nums[i - 3]:
                dp[i] = dp[i] or dp[i - 3]
            if i >= 3 and nums[i - 1] == nums[i - 2] + 1 == nums[i - 3] + 2:
                dp[i] = dp[i] or dp[i - 3]
        return dp[n]

class Solution:
    def checkTwoChessboards(self, coordinate1: str, coordinate2: str) -> bool:
