class Solution:
    def arrayStringsAreEqual(self, word1: List[str], word2: List[str]) -> bool:
        m = len(word1)
        n = len(word2)
        a, b = 0, 0
        c, d = 0, 0
        while a < m and c < n:
            if word1[a][b] != word2[c][d]:
                return False
            a, b = a + (b + 1) // len(word1[a]), (b + 1) % len(word1[a])
            c, d = c + (d + 1) // len(word2[c]), (d + 1) % len(word2[c])
        return a >= m and c >= n

class Solution:
    def isValid(self, s: str) -> bool:
        stack = []
        for c in s:
            if len(stack) > 1 and stack[-2] + stack[-1] + c == "abc":
                stack.pop()
                stack.pop()
            else:
                stack.append(c)
        return len(stack) == 0

class Solution:
    def checkValidGrid(self, grid: List[List[int]]) -> bool:
        m = len(grid)
        n = len(grid[0])
        points = []
        for i in range(m):
            for j in range(n):
                points.append((i, j))
        points.sort(key = lambda p: grid[p[0]][p[1]])
        if points[0] != (0, 0):
            return False
        for i in range(1, m * n):
            a, b = points[i - 1]
            c, d = points[i]
            if abs(a - c) + abs(b - d) != 3 or min(abs(a - c), abs(b - d)) == 0:
                return False
        return True

