from typing import Optional
class Solution:
    def cloneGraph(self, node: Optional['Node']) -> Optional['Node']:
        nodecache = {}
        def clone(i):
            if not i:
                return i
            if i.val in nodecache:
                return nodecache[i.val]
            copy = Node(i.val)
            nodecache[copy.val] = copy
            for j in i.neighbors:
                copy.neighbors.append(clone(j))
            return copy
        return clone(node)

class Solution:
    def closestDivisors(self, num: int) -> List[int]:
        closest = (1, num + 1)
        for x in [num + 1, num + 2]:
            curr = (1, x)
            i = 2
            while i * i <= x:
                if x % i == 0:
                    curr = (i, x // i)
                    if curr[1] - curr[0] < closest[1] - closest[0]:
                        closest = curr
                i += 1
        return closest

class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        res = [n] * n
        l = {}
        for i in range(2 * n):
            if nums[i % n] in l:
                res[i % n] = min(res[i % n], i - l[nums[i % n]])
                res[l[nums[i % n]] % n] = min(res[l[nums[i % n]] % n], i - l[nums[i % n]])
            l[nums[i % n]] = i
        return [-1 if res[x] == n else res[x] for x in queries]

class Solution:
    def closestNode(self, n: int, edges: List[List[int]], query: List[List[int]]) -> List[int]:
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        parent = [-1] * n
        depth = [0] * n
        stack = [(0, 0, -1)]
        while stack:
            i, d, p = stack.pop()
            parent[i] = p
            depth[i] = d
            for j in graph[i]:
                if j != p:
                    stack.append((j, d + 1, i))
        res = []
        for u, v, target in query:
            q = deque()
            vs = set()
            while u != -1 and v != -1 and u != v:
                if depth[u] < depth[v]:
                    u, v = v, u
                q.appendleft((u, u))
                vs.add(u)
                u = parent[u]
            if u == v and u != -1:
                if u not in vs:
                    vs.add(u)
                    q.appendleft((u, u))
            while q:
                src, i = q.pop()
                if i == target:
                    res.append(src)
                    break
                for j in graph[i]:
                    if j not in vs:
                        vs.add(j)
                        q.appendleft((src, j))
        return res

import bisect

class Solution:
    def closestNodes(self, root: Optional[TreeNode], queries: List[int]) -> List[List[int]]:
        vals = []
        def inorder(root):
            if root:
                inorder(root.left)
                vals.append(root.val)
                inorder(root.right)
        inorder(root)
        res = []
        for q in queries:
            i = bisect.bisect_left(vals, q)
            res.append([-1, -1])
            if i < len(vals) and vals[i] <= q:
                res[-1][0] = vals[i]
            elif i > 0 and vals[i - 1] <= q:
                res[-1][0] = vals[i - 1]
            if i < len(vals) and vals[i] >= q:
                res[-1][1] = vals[i]
        return res

class Solution:
    def segmented_sieve(self, left, right):
        if left < 2:
            left = 2

        limit = int(math.sqrt(right)) + 1
        is_prime_small = [True] * (limit + 1)
        is_prime = [True] * (right - left + 1)

        for num in range(2, limit + 1):
            if is_prime_small[num]:
                for multiple in range(num * num, limit + 1, num):
                    is_prime_small[multiple] = False
                for multiple in range(max(num * num, (left + num - 1) // num * num), right + 1, num):
                    is_prime[multiple - left] = False

        return [num for num, prime in enumerate(is_prime, start=left) if prime]

    def closestPrimes(self, left: int, right: int) -> List[int]:
        primes = self.segmented_sieve(left, right)
        if len(primes) < 2:
            return [-1, -1]
        return min((primes[i+1] - primes[i], (primes[i], primes[i + 1])) for i in range(len(primes) - 1))[1]

import bisect

class Solution:
    def minAbsDifference(self, nums: List[int], goal: int) -> int:
        pos = neg = 0
        for el in nums:
            if el >= 0:
                pos += el
            else:
                neg += el
        if goal >= pos:
            return goal - pos
        if goal <= neg:
            return neg - goal
        n = len(nums)
        k = n // 2
        x = [1] * max(k + 1, n - k + 1)
        for i in range(1, max(k + 1, n - k + 1)):
            x[i] = 2 * x[i - 1]
        sums = set()
        for mask in range(1 << k):
            s = 0
            for i in range(k):
                if mask & x[i]:
                    s += nums[i]
            sums.add(s)
        res = float('inf')
        sums = sorted(sums)
        for mask in range(1 << (n - k)):
            s = 0
            for i in range(n - k):
                if mask & x[i]:
                    s += nums[k + i]
            i = bisect.bisect_left(sums, goal - s)
            if i < len(sums):
                res = min(res, abs(s + sums[i] - goal))
            if i > 0:
                res = min(res, abs(s + sums[i - 1] - goal))
        return res

class Solution:
    def clumsy(self, n: int) -> int:
        expr = ""
        opr = ["*", "//", "+", "-"]
        for i in range(n):
            expr += str(n - i)
            if i < n - 1:
                expr += opr[i % 4]
        return eval(expr)

class Solution:
    def ways(self, amount, coins, i, n):
        if amount < 0:
            return 0
        if amount == 0:
            return 1
        key = (amount, i)
        if key in self.cache:
            return self.cache[key]
        ctr = 0
        for j in range(i, n):
            ctr += self.ways(amount - coins[j], coins, j, n)
        self.cache[key] = ctr
        return ctr

    def change(self, amount: int, coins: List[int]) -> int:
        n = len(coins)
        coins.sort(reverse = True)
        self.cache = {}
        return self.ways(amount, coins, 0, n)

class Solution:
    def change(self, amount: int, coins: List[int]) -> int:
        dp = [0] * (amount + 1)
        dp[0] = 1
        for c in coins:
            for s in range(amount + 1):
                if s >= c:
                    dp[s] += dp[s - c]
        return dp[amount]

class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        if amount in coins:
            return 1
        coins = [c for c in coins if c < amount]
        dp = [float('inf')] * (amount + 1)
        dp[0] = 0
        for i in range(amount + 1):
            for c in coins:
                if i + c <= amount:
                    dp[i + c] = min(dp[i + c], 1 + dp[i])
        if dp[amount] == float('inf'):
            return -1
        return dp[amount]

class Solution:
    def minCost(self, nums: List[int], x: int) -> int:
        n = len(nums)
        costs = [i * x for i in range(n)]
        for i in range(n):
            curr = nums[i]
            for j in range(n):
                curr = min(curr, nums[(i + j) % n])
                costs[j] += curr
        return min(costs)

from collections import deque

class Solution:
    def combinationSum2(self, candidates: List[int], target: int) -> List[List[int]]:
        n = len(candidates)
        candidates.sort()
        q = deque([(target, -1, 0)])
        res = []
        while len(q) > 0:
            rem, i, used = q.pop()
            if rem == 0:
                res.append([candidates[x] for x in range(n) if used & (1 << x)])
            if rem > 0:
                for j in range(i + 1, n):
                    if j == 0 or j == i + 1 or candidates[j] != candidates[j - 1]:
                        q.appendleft((rem - candidates[j], j, used | 1 << j))
        return res

class Solution:
    def getSums(self, comb, target, p, res):
        if target < 0:
            return
        if p == len(comb):
            if target == 0:
                res.append(comb[1:])
            return
        for i in range(comb[p - 1] + 1, 10):
            comb[p] = i
            self.getSums(comb, target - i, p + 1, res)


    def combinationSum3(self, k: int, n: int) -> List[List[int]]:
        comb = [0] * (k + 1)
        res = []
        self.getSums(comb, n, 1, res)
        return res

class Solution:
    def combinationSum4(self, nums: List[int], target: int) -> int:
        dp = [0] * (target + 1)
        dp[0] = 1
        for i in range(1, target + 1):
            for num in nums:
                if i - num >= 0:
                    dp[i] += dp[i - num]
        return dp[target]

class Solution:
    def combinationSum(self, candidates: List[int], target: int) -> List[List[int]]:
        n = len(candidates)
        op = []
        combs = [([item], item) for item in candidates]
        while len(combs) > 0:
            comb, currsum = combs.pop(0)
            if currsum == target:
                op.append(comb)
            for item in candidates:
                newsum = currsum + item
                if newsum <= target and item >= comb[-1]:
                    combs.append((comb + [item], newsum))
        return op

class Solution:
    def combine(self, n: int, k: int) -> List[List[int]]:
        combs = [[i] for i in range(1, n + 1)]
        i = 0
        while i < len(combs):
            curr = combs[i]
            if len(curr) < k:
                for j in range(curr[-1] + 1, n + 1):
                    combs.append(curr + [j])
                i += 1
            else:
                break
        return combs[i:]

import bisect

class Solution:
    def numSmallerByFrequency(self, queries: List[str], words: List[str]) -> List[int]:
        def f(w):
            return w.count(min(w))
        n = len(words)
        words = sorted([f(w) for w in words])
        res = []
        for q in queries:
            q = f(q)
            res.append(n - bisect.bisect_right(words, q))
        return res

class Solution:
    def compareVersion(self, version1: str, version2: str) -> int:
        a = [int(r) for r in version1.split(".")]
        b = [int(r) for r in version2.split(".")]
        if len(a) < len(b):
            a += [0] * (len(b) - len(a))
        else:
            b += [0] * (len(a) - len(b))
        if tuple(a) > tuple(b):
            return 1
        elif tuple(a) < tuple(b):
            return -1
        return 0

class Solution:
    def complexNumberMultiply(self, num1: str, num2: str) -> str:
        a, b = num1.split("+")
        c, d = num2.split("+")
        a = int(a)
        b = int(b[:-1])
        c = int(c)
        d = int(d[:-1])
        return "{}+{}i".format(a*c-b*d, a*d+b*c)

class Solution:
    def concatenatedDivisibility(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        pow10 = [pow(10, len(str(x)), k) for x in nums]
        dp = [dict() for _ in range(1 << n)]
        dp[0][0] = []
        for mask in range(1 << n):
            for rem, seq in list(dp[mask].items()):
                for i in range(n):
                    if not mask & (1 << i):
                        nm = mask | (1 << i)
                        nr = (rem * pow10[i] + nums[i]) % k
                        cand = seq + [nums[i]]
                        if nr not in dp[nm] or cand < dp[nm][nr]:
                            dp[nm][nr] = cand
        full = (1 << n) - 1
        return dp[full].get(0, [])

class Solution:
    def genline(self, s, i, n, words, curr, res):
        if i >= n:
            res.append(curr[:])
        for j in range(i + 1, n + 1):
            if s[i:j] in words:
                curr.append(s[i:j])
                self.genline(s, j, n, words, curr, res)
                curr.pop()

    def findAllConcatenatedWordsInADict(self, words: List[str]) -> List[str]:
        wordset = set(words)
        res = []
        for w in words:
            curr = []
            found = False
            self.genline(w, 0, len(w), wordset, [], curr)
            for l in curr:
                if len(l) > 1:
                    found = True
                    break
            if found:
                res.append(w)
        return res

class Solution:
    def getConcatenation(self, nums: List[int]) -> List[int]:
        n = len(nums)
        return [nums[i % n] for i in range(2 * n)]

class Solution:
    def concatenatedBinary(self, n: int) -> int:
        MAX = 10 ** 9 + 7
        res = 0
        for i in range(1, n + 1):
            k = len("{:b}".format(i))
            res = (res << k) | i
            res %= MAX
        return res

class Solution:
    def maxPower(self, s: str) -> int:
        s += "0"
        maxCtr = [0] * 26
        curr = [0] * 26
        for c in s:
            for i in range(26):
                maxCtr[i] = max(maxCtr[i], curr[i])
            if c != "0":
                tmp = curr[ord(c) - ord('a')]
                curr = [0] * 26
                curr[ord(c) - ord('a')] = tmp
                curr[ord(c) - ord('a')] += 1
        return max(maxCtr)

class Solution:
    def consecutiveNumbersSum(self, n: int) -> int:
        res = 0
        l = 1
        while l * (l + 1) // 2 <= n:
            if (n - l * (l - 1) // 2) % l == 0:
                res += 1
            l += 1
        return res

from collections import deque

class Solution:
    def constrainedSubsetSum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        q = deque()
        for i in range(n):
            if len(q) > 0:
                nums[i] = max(nums[i], nums[i] + nums[q[0]])
            while len(q) > 0 and q[0] <= i - k:
                q.popleft()
            while len(q) > 0 and nums[i] > nums[q[-1]]:
                q.pop()
            q.append(i)
        return max(nums)

