class Solution:
    def DFS(self, grid, a, b, l):
        root = Node(val = 1)
        currsum = 0
        ctr = 0
        for i in range(a, a + l):
            for j in range(b, b + l):
                currsum += grid[i][j]
                ctr += 1
        if currsum == 0 or currsum == ctr:
            root.isLeaf = True
            root.val = 0 if currsum == 0 else 1
        else:
            root.topLeft = self.DFS(grid, a, b, l // 2)
            root.topRight = self.DFS(grid, a, b + l // 2, l // 2)
            root.bottomLeft = self.DFS(grid, a + l // 2, b, l // 2)
            root.bottomRight = self.DFS(grid, a + l // 2, b + l // 2, l // 2)
        return root

    def construct(self, grid: List[List[int]]) -> 'Node':
        n = len(grid)
        return self.DFS(grid, 0, 0, n)

class Solution:
    def find(self, pattern, i, n, res, prev, used):
        if i >= n:
            return True
        if i == 0:
            for curr in range(1, 10):
                res[i] = str(curr)
                if self.find(pattern, i + 1, n, res, str(curr), used | (1 << curr)):
                    return True
                res[i] = ""
        else:
            if pattern[i - 1] == "I":
                for curr in range(int(prev) + 1, 10):
                    res[i] = str(curr)
                    if not used & (1 << curr) and self.find(pattern, i + 1, n, res, str(curr), used | (1 << curr)):
                        return True
                    res[i] = ""
            if pattern[i - 1] == "D":
                for curr in range(1, int(prev)):
                    res[i] = str(curr)
                    if not used & (1 << curr) and self.find(pattern, i + 1, n, res, str(curr), used | (1 << curr)):
                        return True
                    res[i] = ""
        return False

    def smallestNumber(self, pattern: str) -> str:
        n = len(pattern)
        res = [""] * (n + 1)
        self.find(pattern, 0, n + 1, res, "", 0)
        return "".join(res)

class Solution:
    def tree2str(self, root):
        if root:
            l = self.tree2str(root.left)
            r = self.tree2str(root.right)
            lstr = f"({l})" if l or r else ""
            rstr = f"({r})" if r else ""
            return f"{root.val}{lstr}{rstr}"
        return ""

def compute_lps(pattern):
    length = 0
    lps = [0] * len(pattern)
    i = 1
    while i < len(pattern):
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1
    return lps

def find_pattern_indices(string, pattern):
    indices = []
    n = len(string)
    m = len(pattern)
    lps = compute_lps(pattern)
    i = j = 0
    while i < n:
        if string[i] == pattern[j]:
            i += 1
            j += 1
            if j == m:
                indices.append(i - j)
                j = lps[j - 1]
        else:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1
    return indices

class TrieNode:
    def __init__(self):
        self.child = {}
        self.cost = float('inf')

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, s, cost):
        curr = self.root
        for c in s:
            if c not in curr.child:
                curr.child[c] = TrieNode()
            curr = curr.child[c]
        curr.cost = min(curr.cost, cost)

class Solution:
    def minimumCost(self, target: str, words: List[str], costs: List[int]) -> int:
        n = len(target)
        dp = [float('inf')] * (n + 1)
        dp[n] = 0
        vals = [(words[i], costs[i]) for i in range(len(words))]
        vals.sort(key = lambda x: -len(x[0]))
        K = sum(len(w) for w in words)
        mincosts = [[] for _ in range(n)]
        trie = Trie()
        for w, c in vals:
            l = len(w)
            if l * l <= K:
                trie.insert(w, c)
                continue
            for i in find_pattern_indices(target, w):
                mincosts[i].append((l, c))
        for i in range(n - 1, -1, -1):
            j = i
            root = trie.root
            while j < n and target[j] in root.child:
                root = root.child[target[j]]
                dp[i] = min(dp[i], root.cost + dp[j + 1])
                l = j - i + 1
                if l * l > K:
                    break
                j += 1
            for l, c in mincosts[i]:
                dp[i] = min(dp[i], c + dp[i + l])
        return dp[0] if dp[0] != float('inf') else -1

import heapq
from collections import Counter

class Solution:
    def lastRepeatLen(self, s, currc, replen):
        n = len(s)
        if n == 0 or currc == s[-1]:
            return replen + 1
        return 1

    def repeatLimitedString(self, s: str, repeatLimit: int) -> str:
        ctr = Counter(s)
        op = ""
        replen = 0
        heap = []
        for c in ctr:
            heapq.heappush(heap, (-ord(c), c))
        while len(heap) > 0:
            k, currc = heapq.heappop(heap)
            while len(heap) > 0 and currc not in ctr:
                k, currc = heapq.heappop(heap)
            if self.lastRepeatLen(op, currc, replen) > repeatLimit:
                if len(heap) > 0:
                    newk, newc = heapq.heappop(heap)
                    replen = self.lastRepeatLen(op, newc, replen)
                    op += newc
                    ctr[newc] -= 1
                    if ctr[newc] == 0:
                        del ctr[newc]
                    else:
                        heapq.heappush(heap, (newk, newc))
                    heapq.heappush(heap, (k, currc))
                else:
                    break
            else:
                replen = self.lastRepeatLen(op, currc, replen)
                op += currc
                ctr[currc] -= 1
                if ctr[currc] == 0:
                    del ctr[currc]
                else:
                    heapq.heappush(heap, (k, currc))
        return op

import heapq

class Solution:
    def isPossible(self, target: List[int]) -> bool:
        heap = []
        total = 0
        for i, el in enumerate(target):
            if el > 1:
                heapq.heappush(heap, -el)
            total += el
        while len(heap) > 0:
            largest = -heapq.heappop(heap)
            if total >= 2 * largest or total - largest == 0:
                return False
            newval = largest % (total - largest)
            if newval == 0:
                newval += total - largest
            total = total - largest + newval
            if newval > 1:
                heapq.heappush(heap, -newval)
        return True

class Solution:
    def constructDistancedSequence(self, n):
        res = [0] * (2 * n - 1)
        used = [False] * (n + 1)

        def construct(i):
            if i == len(res):
                return True
            if res[i]:
                return construct(i + 1)
            for num in range(n, 0, -1):
                if used[num]:
                    continue
                used[num] = True
                res[i] = num
                valid = False
                if num == 1:
                    valid = construct(i + 1)
                elif i + num < len(res) and res[i + num] == 0:
                    res[i + num] = num
                    valid = construct(i + 1)
                    if not valid:
                        res[i + num] = 0
                if valid:
                    return True
                res[i] = 0
                used[num] = False
            return False

        construct(0)
        return res

class Solution:
    def minBitwiseArray(self, nums: List[int]) -> List[int]:
        for i in range(len(nums)):
            x = nums[i]
            b = 0
            while nums[i] & (1 << b):
                b += 1
            if b:
                x &= ~(1 << (b - 1))
            if x | (x + 1) == nums[i]:
                nums[i] = x
            else:
                nums[i] = -1
        return nums

