class Solution:
    def containsNearbyDuplicate(self, nums: List[int], k: int) -> bool:
        valIndex = {}
        for i, num in enumerate(nums):
            if num in valIndex:
                curr = valIndex[num][-1]
                if i - curr <= k:
                    return True
                valIndex[num].append(i)
            else:
                valIndex[num] = [i]
        return False

from sortedcontainers import SortedList

class Solution:
    def containsNearbyAlmostDuplicate(self, nums: List[int], indexDiff: int, valueDiff: int) -> bool:
        n = len(nums)
        bst = SortedList()
        for i in range(n - 1):
            bst.add(nums[i])
            if i >= indexDiff:
                bst.remove(nums[i - indexDiff])
            if bst.bisect_right(nums[i + 1] + valueDiff) - bst.bisect_left(nums[i + 1] - valueDiff) > 0:
                return True
        return False

import heapq

class Solution:
    def containsDuplicate(self, nums: List[int]) -> bool:
        n = len(nums)
        heapq.heapify(nums)
        curr = heapq.heappop(nums)
        for _ in range(n - 1):
            currnew = heapq.heappop(nums)
            if curr == currnew:
                return True
            curr = currnew
        return False

class Solution:
    def findMaxLength(self, nums: List[int]) -> int:
        n = len(nums)
        seen = {0:-1}
        curr = 0
        mlen = 0
        for i in range(n):
            curr += 2 * nums[i] - 1
            if curr in seen:
                mlen = max(mlen, i - seen[curr])
            else:
                seen[curr] = i
        return mlen

class Solution:
    def checkSubarraySum(self, nums: List[int], k: int) -> bool:
        ctr = 0
        total = [ctr]
        for num in nums:
            ctr += num
            total.append(ctr)
        exists = {}
        for i, f in enumerate(total):
            rem = f % k
            if rem in exists:
                if i - exists[rem] >= 2:
                    return True
            else:
                exists[rem] = i
        return False

class Stack:
    def __init__(self, init, func):
        self.stack = deque([(init, init)])
        self.func = func

    def push(self, val):
        top, topfunc = self.stack[-1]
        self.stack.append((val, self.func(topfunc, val)))

    def empty(self):
        return len(self.stack) <= 1

    def pop(self):
        if not self.empty():
            top, topfunc = self.stack.pop()
            return top

    def funcval(self):
        top, topfunc = self.stack[-1]
        return topfunc

class Queue:
    def __init__(self, init = float('inf'), func = min):
        self.func = func
        self.f = Stack(init, func)
        self.s = Stack(init, func)

    def push(self, val):
        self.f.push(val)

    def empty(self):
        return self.f.empty() and self.s.empty()

    def pop(self):
        if self.s.empty():
            while not self.f.empty():
                self.s.push(self.f.pop())
        if not self.s.empty():
            return self.s.pop()

    def funcval(self):
        return self.func(self.f.funcval(), self.s.funcval())

class Solution:
    def continuousSubarrays(self, nums: List[int]) -> int:
        n = len(nums)
        res = 0
        minq = Queue(float('inf'), func = min)
        maxq = Queue(float('-inf'), func = max)
        i = 0
        for j in range(n):
            minq.push(nums[j])
            maxq.push(nums[j])
            while i < j and maxq.funcval() - minq.funcval() > 2:
                minq.pop()
                maxq.pop()
                i += 1
            res += j - i + 1
        return res

class Solution:
    def construct2DArray(self, original: List[int], m: int, n: int) -> List[List[int]]:
        k = len(original)
        if k != m * n:
            return []
        for i in range(m):
            original.extend([original[i * n : (i + 1) * n]])
        return original[k:]

