class Solution:
    def sortedArrayToBST(self, nums: List[int]) -> Optional[TreeNode]:
        n = len(nums)
        if n > 1:
            root = TreeNode(nums[n // 2])
            root.left = self.sortedArrayToBST(nums[:n//2])
            root.right = self.sortedArrayToBST(nums[1 + (n//2) :])
            return root
        elif n == 1:
            return TreeNode(val = nums[0])
        else:
            return None

class Solution:
    def sortedListToBST(self, head: Optional[ListNode]) -> Optional[TreeNode]:
        if not head:
            return head
        if not head.next:
            return TreeNode(val = head.val)
        prev = None
        slow = head
        fast = head
        while slow and fast and fast.next:
            prev = slow
            slow = slow.next
            fast = fast.next.next
        prev.next = None
        root = TreeNode(val = slow.val)
        root.left = self.sortedListToBST(head)
        root.right = self.sortedListToBST(slow.next)
        return root

class Solution:
    def convertTemperature(self, celsius: float) -> List[float]:
        f = 1.8 * celsius + 32.0
        k = 273.15 + celsius
        return [k, f]

class Solution:
    def copyRandomList(self, head: 'Optional[Node]') -> 'Optional[Node]':
        nodecache = {}
        def clone(curr):
            if not curr:
                return curr
            if curr in nodecache:
                return nodecache[curr]
            copy = Node(curr.val)
            nodecache[curr] = copy
            copy.next = clone(curr.next)
            copy.random = clone(curr.random)
            return copy
        return clone(head)

class Solution:
    def corpFlightBookings(self, bookings: List[List[int]], n: int) -> List[int]:
        booked = [0] * (n + 1)
        for l, r, ctr in bookings:
            booked[l - 1] += ctr
            booked[r] -= ctr
        for i in range(1, n + 1):
            booked[i] += booked[i - 1]
        booked.pop()
        return booked

