import bisect

class Solution:
    def countRoutes(self, locations: List[int], start: int, finish: int, fuel: int) -> int:
        M = 10 ** 9 + 7
        n = len(locations)
        x = locations[start]
        y = locations[finish]
        locations.sort()
        start = locations.index(x)
        finish = locations.index(y)
        count = defaultdict(lambda: defaultdict(int))
        for f in range(fuel + 1):
            count[start][f] = 1
        for f in range(fuel + 1):
            for i in range(n):
                x = bisect.bisect_left(locations, locations[i] - f) - 1
                y = bisect.bisect_left(locations, locations[i] + f) + 1
                for j in range(max(x, 0), min(y, n)):
                    if i != j and f >= abs(locations[i] - locations[j]):
                        count[i][f] += count[j][f - abs(locations[i] - locations[j])]
                        count[i][f] %= M
        return count[finish][fuel]

class Solution:
    def countAlternatingSubarrays(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [1] * n
        for i in range(n - 2, -1, -1):
            if nums[i] != nums[i + 1]:
                dp[i] += dp[i + 1]
        return sum(dp)

class Solution:
    def countAndSay(self, n: int) -> str:
        if n == 1:
            return "1"
        prev = self.countAndSay(n - 1)
        n = len(prev)
        op = ""
        i = 0
        while i < n:
            ctr = 1
            while i < n - 1 and prev[i] == prev[i + 1]:
                ctr += 1
                i += 1
            i += 1
            op += str(ctr) + prev[i - 1]
        return op

