class Solution:
    def countNodes(self, root: Optional[TreeNode]) -> int:
        mx = 0
        nodes = [(root, 1)]
        while len(nodes) > 0:
            curr, l = nodes.pop()
            if curr:
                mx = max(mx, l)
                nodes.append((curr.left, 2 * l))
                nodes.append((curr.right, 2 * l + 1))
        return mx

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, a):
        if a == self.parent[a]:
            return a
        self.parent[a] = self.find(self.parent[a])
        return self.parent[a]

    def union(self, a, b):
        parent_a = self.find(a)
        parent_b = self.find(b)
        if parent_a != parent_b:
            if self.size[parent_a] < self.size[parent_b]:
                parent_a, parent_b = parent_b, parent_a
            self.parent[parent_b] = parent_a
            self.size[parent_a] += self.size[parent_b]

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        dsu = DSU(threshold + 1)
        for el in nums:
            mul = 1
            while el * mul <= threshold:
                dsu.union(el, el * mul)
                mul += 1
        return len(set(dsu.find(el) for el in nums if el <= threshold))  + len([el for el in nums if el > threshold])

class Solution:
    def countDaysTogether(self, arriveAlice: str, leaveAlice: str, arriveBob: str, leaveBob: str) -> int:
        days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        start = max(arriveAlice, arriveBob)
        sm, sd = map(int, start.split("-"))
        end = min(leaveAlice, leaveBob)
        em, ed = map(int, end.split("-"))
        res = 0
        for m in range(sm + 1, em):
            res += days[m - 1]
        if em > sm:
            res += days[sm - 1] - sd + ed + 1
        elif em == sm:
            res += max(ed - sd + 1, 0)
        return res

class Solution:
    def merge(self, intervals):
        res = []
        intervals.sort()
        prev = float('-inf')
        for l, r in intervals:
            if l <= prev:
                res[-1][-1] = max(res[-1][1], r)
            else:
                res.append([l, r])
            prev = res[-1][1]
        return res

    def countDays(self, days, meetings):
        meetings = self.merge(meetings)
        return days - sum(r - l + 1 for l, r in meetings)

