class Solution:
    def countPyramids(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        res = 0
        def count():
            nonlocal res
            dp = [[0] * n for _ in range(m)]
            for j in range(n):
                if grid[m - 1][j] == 1:
                    dp[m - 1][j] = 1
                else:
                    dp[m - 1][j] = 0
            for i in range(m - 2, -1, -1):
                for j in range(n):
                    l = r = 0
                    if j > 0:
                        l = dp[i + 1][j - 1]
                    if j + 1 < n:
                        r = dp[i + 1][j + 1]
                    if grid[i][j] == grid[i + 1][j] == 1:
                        dp[i][j] = 1 + min(l, r)
                    elif grid[i][j] == 1:
                        dp[i][j] = 1
                    else:
                        dp[i][j] = 0
                    res += max(dp[i][j] - 1, 0)
        count()
        for i in range(m // 2):
            grid[i], grid[m - i - 1] = grid[m - i - 1], grid[i]
        count()
        return res

class Solution:
    def goodNodes(self, root, mval = float('-inf')) -> int:
        res = 0
        if root:
            if root.val >= mval:
                res += 1
                mval = root.val
            res += self.goodNodes(root.left, mval)
            res += self.goodNodes(root.right, mval)
        return res

class Solution:
    def countGoodNumbers(self, n: int) -> int:
        M = 10 ** 9 + 7
        res = pow(4, n // 2, M) * pow(5, n - n // 2, M)
        return res % M

class FenwickTree:
    def __init__(self, x):
        self.bit = x
        for i in range(len(x)):
            j = i | (i + 1)
            if j < len(x):
                x[j] += x[i]

    def update(self, idx, x):
        while idx < len(self.bit):
            self.bit[idx] += x
            idx |= idx + 1

    def query(self, end):
        x = 0
        while end:
            x += self.bit[end - 1]
            end &= end - 1
        return x

class Solution:
    def goodTriplets(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        pos = [[-1, -1, i] for i in range(n)]
        for i in range(n):
            pos[nums1[i]][0] = i
            pos[nums2[i]][1] = i
        pos.sort()
        ctr = [1] * n
        fw = FenwickTree([0] * n)
        for x, y, i in pos:
            ctr[i] *= fw.query(y)
            fw.update(y, 1)
        fw = FenwickTree([0] * n)
        for x, y, i in pos[::-1]:
            ctr[i] *= fw.query(n) - fw.query(y + 1)
            fw.update(y, 1)
        return sum(ctr)

from sortedcontainers import SortedList

class Solution:
    def countGoodTriplets(self, arr, a, b, c):
        n = len(arr)
        res = 0
        for i in range(n):
            sl = SortedList()
            ctr = lambda l, r: (sl.bisect_right(r) - sl.bisect_left(l)) if l <= r else 0
            for k in range(i + 1, n):
                if abs(arr[i] - arr[k]) <= c:
                    l1, r1 = arr[i] - a, arr[i] + a
                    l2, r2 = arr[k] - b, arr[k] + b
                    res += ctr(max(l1, l2), min(r1, r2))
                sl.add(arr[k])
        return res

class Solution:
    def countHillValley(self, nums: List[int]) -> int:
        n = len(nums)
        groups = []
        i = 0
        while i < n:
            ctr = 1
            while i < n - 1 and nums[i] == nums[i + 1]:
                i += 1
                ctr += 1
            i += 1
            groups.append((nums[i - 1], ctr))
        ctr = 0
        m = len(groups)
        for i in range(1, m - 1):
            left = groups[i][0] > groups[i - 1][0]
            right = groups[i][0] > groups[i + 1][0]
            if not left ^ right:
                ctr += 1
        return ctr

from sortedcontainers import SortedList

class CountIntervals:
    def __init__(self):
        self.L = 1
        self.R = 10 ** 9
        self.parts = SortedList()
        self.res = 0

    def split(self, x, y, i, j):
        if y < i or x > j:
            return []
        if x >= i and y <= j:
            return [(x, y)]
        mid = (x + y) // 2
        return self.split(x, mid, i, j) + self.split(mid + 1, y, i, j)

    def add(self, left: int, right: int) -> None:
        for l, r in self.split(self.L, self.R, left, right):
            x = self.parts.bisect_right((l, float('inf'))) - 1
            if 0 <= x < len(self.parts) and self.parts[x][1] >= r:
                continue
            x = self.parts.bisect_left((l, float('-inf')))
            while x < len(self.parts) and self.parts[x][1] <= r:
                rm = self.parts.pop(x)
                self.res -= rm[1] - rm[0] + 1
            self.parts.add((l, r))
            self.res += r - l + 1

    def count(self) -> int:
        return self.res

