M = 10 ** 9 + 7

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        @lru_cache(maxsize = None)
        def count(x):
            if x <= 1:
                return 0
            return 1 + count(x.bit_count())
        cache = {}
        def dp(i, ctr, tight):
            if i >= len(s):
                return int(1 + count(ctr) <= k and not tight)
            key = (i, ctr, tight)
            if key in cache:
                return cache[key]
            up = 1
            if tight:
                up = int(s[i])
            res = 0
            for d in range(0, up + 1):
                res += dp(i + 1, ctr + d, tight and d == up)
                res %= M
            cache[key] = res
            return res
        return (dp(0, 0, True) - 1) % M

from collections import Counter

M = 10 ** 9 + 7

class Solution:
    def count(self, vals, i, rem, remctr):
        if i >= len(vals):
            return 1 if rem == 0 and remctr == 0 else 0
        key = (i, rem, remctr)
        if key in self.cache:
            return self.cache[key]
        res = 0
        if remctr > 0:
            prev = self.count(vals, i + 1, rem - vals[i], remctr - 1)
            res += vals[i] * prev
        res += self.count(vals, i + 1, rem, remctr)
        res %= M
        self.cache[key] = res
        return res

    def countKSubsequencesWithMaxBeauty(self, s: str, k: int) -> int:
        ctr = Counter(s)
        vals = sorted(ctr.values(), reverse = True)
        if len(vals) < k:
            return 0
        s = sum(vals[:k])
        self.cache = {}
        return self.count(vals, 0, s, k)

class Solution:
    def countLatticePoints(self, circles: List[List[int]]) -> int:
        points = set()
        for x, y, r in circles:
            for i in range(x - r, x + r + 1):
                for j in range(y - r, y + r + 1):
                    if (i - x) * (i - x) + (j - y) * (j - y) <= r * r:
                        points.add((i, j))
        return len(points)

