from bisect import *

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        res = [0] * numberOfUsers
        alls = 0
        heres = []
        offlines = defaultdict(list)
        for e in events:
            if e[0] == 'OFFLINE':
                offlines[int(e[2])].append((int(e[1]), int(e[1]) + 60))
            if e[0] == 'MESSAGE':
                if e[2] == 'HERE':
                    heres.append(int(e[1]))
                elif e[2] == 'ALL':
                    alls += 1
                else:
                    for x in map(lambda y: int(y[2:]), e[2].split()):
                        res[x] += 1
        heres.sort()
        for i in range(numberOfUsers):
            res[i] += alls
        for el in range(numberOfUsers):
            arr = sorted(offlines[el])
            prev = float('-inf')
            for x, y in arr:
                res[el] += bisect_right(heres, x - 1) - bisect_left(heres, prev)
                prev = y
            res[el] += bisect_right(heres, float('inf')) - bisect_left(heres, prev)
        return res

class Solution:
    def countNegatives(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        ctr = 0
        for i in range(m):
            beg = 0
            end = n - 1
            while beg <= end:
                mid = (beg + end) // 2
                if beg == end:
                    if grid[i][beg] < 0:
                        ctr += (n - beg)
                    break
                elif grid[i][mid] >= 0:
                    beg = mid + 1
                else:
                    end = mid
        return ctr

class Solution:
    def countNicePairs(self, nums: List[int]) -> int:
        res = 0
        ctr = {}
        for el in nums:
            val = el
            rev = 0
            while el:
                rev = 10 * rev + el % 10
                el //= 10
            val -= rev
            res += ctr.get(val, 0)
            ctr[val] = ctr.get(val, 0) + 1
        return res % 1000000007

class Solution:
    def sumcount(self, root):
        total = 0
        n = 0
        if root:
            ltotal, ln = self.sumcount(root.left)
            rtotal, rn = self.sumcount(root.right)
            total = ltotal + rtotal + root.val
            n = ln + rn + 1
            if root.val == total // n:
                self.ctr += 1
        return (total, n)

    def averageOfSubtree(self, root: Optional[TreeNode]) -> int:
        self.ctr = 0
        self.sumcount(root)
        return self.ctr

import heapq

class Solution:
    def countGreatEnoughNodes(self, root: Optional[TreeNode], k: int) -> int:
        res = 0
        def dfs(r):
            nonlocal res
            curr = []
            if not r:
                return curr
            for lval in dfs(r.left):
                heapq.heappush(curr, lval)
            for rval in dfs(r.right):
                heapq.heappush(curr, rval)
            while len(curr) > k:
                heapq.heappop(curr)
            if len(curr) == k and r.val > -curr[0]:
                res += 1
            heapq.heappush(curr, -r.val)
            return curr
        dfs(root)
        return res

from collections import defaultdict

class Solution:
    def countHighestScoreNodes(self, parents: List[int]) -> int:
        n = len(parents)
        tree = defaultdict(set)
        root = None
        for i in range(n):
            if parents[i] != -1:
                tree[parents[i]].add(i)
            else:
                root = i
        def DFS(tree, root, sums):
            res = 1
            for j in tree[root]:
                res += DFS(tree, j, sums)
            sums[root] = res
            return res
        sums = {}
        DFS(tree, root, sums)
        mscore = 0
        mctr = 0
        stack = [root]
        while len(stack) > 0:
            curr = stack.pop()
            currscore = max(sums[root] - sums[curr], 1)
            for j in tree[curr]:
                stack.append(j)
                currscore *= sums[j]
            if currscore > mscore:
                mscore = currscore
                mctr = 1
            elif currscore == mscore:
                mctr += 1
        return mctr

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        LOG = n.bit_length() + 1
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] = p[i] + nums[i]
        parent = [[i] * LOG for i in range(n + 1)]
        ops = [[0] * LOG for i in range(n + 1)]
        nxt = [n] * n
        stack = []
        for i in range(n):
            while stack and nums[i] >= nums[stack[-1]]:
                nxt[stack.pop()] = i
            stack.append(i)
        for i in range(n):
            ops[i][0] = nums[i] * (nxt[i] - i) - (p[nxt[i]] - p[i])
            parent[i][0] = nxt[i]
        for l in range(1, LOG):
            for i in range(n):
                ops[i][l] = ops[i][l - 1] + ops[parent[i][l - 1]][l - 1]
                parent[i][l] = parent[parent[i][l - 1]][l - 1]
        res = 0
        for i in range(n):
            j = i
            curr = 0
            for b in range(LOG - 1, -1, -1):
                if curr + ops[j][b] <= k:
                    curr += ops[j][b]
                    j = parent[j][b]
            if j == n:
                res += j - i
                continue
            beg = j
            end = nxt[j] - 1
            while beg <= end:
                mid = (beg + end) // 2
                if curr + nums[j] * (mid - j + 1) - (p[mid + 1] - p[j]) <= k:
                    beg = mid + 1
                else:
                    end = mid - 1
            res += beg - i
        return res

from collections import defaultdict

class Solution:
    def countBadPairs(self, nums: List[int]) -> int:
        n = len(nums)
        ctr = defaultdict(int)
        for i in range(n):
            ctr[nums[i] - i] += 1
        res = n * (n - 1) // 2
        for val in ctr.values():
            res -= val * (val - 1) // 2
        return res

M = 10 ** 9 + 7

class Solution:
    def countBalancedPermutations(self, num: str) -> int:
        n = len(num)
        f = [1] * (n + 1)
        rf = [1] * (n + 1)
        for i in range(1, n + 1):
            f[i] = i * f[i - 1]
            f[i] %= M
            rf[i] = pow(f[i], M - 2, M)
        ctr = [0] * 10
        s = 0
        for c in num:
            s += int(c)
            ctr[int(c)] += 1
        if s & 1:
            return 0
        cache = [[[-1] * ((s // 2) + 1) for _ in range(n + 1)] for _ in range(10)]
        def dp(d, l, rem):
            if d > 9:
                return int(l == 0 and rem == 0)
            if cache[d][l][rem] != -1:
                return cache[d][l][rem]
            res = 0
            for take in range(ctr[d] + 1):
                if take > l or d * take > rem:
                    continue
                res += rf[take] * rf[ctr[d] - take] * dp(d + 1, l - take, rem - d * take)
                res %= M
            cache[d][l][rem] = res
            return res
        return (f[n // 2] * f[n - (n // 2)] * dp(0, n // 2, s // 2)) % M

class Solution:
    def countDistinctIntegers(self, nums: List[int]) -> int:
        ctr = set()
        for num in nums:
            ctr.add(num)
            curr = 0
            while num:
                curr = 10 * curr + num % 10
                num //= 10
            ctr.add(curr)
        return len(ctr)

class Solution:
    def countMaxOrSubsets(self, nums: List[int]) -> int:
        target = 0
        for el in nums:
            target |= el
        @cache
        def dp(i, x):
            if i >= len(nums):
                return int(x == target)
            return dp(i + 1, x) + dp(i + 1, x | nums[i])
        return dp(0, 0)

class Solution:
    def numberOfSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        ctr = 0
        odd = 0
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[odd] += 1
            if nums[i] & 1:
                odd += 1
            if odd >= k:
                ctr += prefix[odd - k]
        return ctr

class Solution:
    def countKDifference(self, nums: List[int], k: int) -> int:
        exists = {}
        ctr = 0
        for i, num in enumerate(nums):
            exists[num] = exists.get(num, []) + [i]
        for i, num in enumerate(nums):
            for val in [num - k, num + k]:
                if val in exists:
                    for j in exists[val]:
                        if j > i:
                            ctr += 1
        return ctr

class Solution:
    def rootCount(self, edges: List[List[int]], guesses: List[List[int]], k: int) -> int:
        n = 1 + len(edges)
        graph = [[] for _ in range(n)]
        guess = [set() for _ in range(n)]
        for u, v in guesses:
            guess[u].add(v)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        def subdfs(i, p):
            s = int(p in guess[i])
            for j in graph[i]:
                if j != p:
                    s += subdfs(j, i)
            return s
        res = [0] * n
        res[0] = len(guesses) - subdfs(0, -1)
        def dfs(i, p):
            for j in graph[i]:
                if j != p:
                    res[j] = res[i] - int(j in guess[i]) + int(i in guess[j])
                    dfs(j, i)
        dfs(0, -1)
        return sum(1 for el in res if el >= k)

