import bisect

class Solution:
    def countRectangles(self, rectangles: List[List[int]], points: List[List[int]]) -> List[int]:
        n = len(rectangles)
        heights = defaultdict(list)
        for l, h in rectangles:
            bisect.insort(heights[h], l)
        count = []
        for x, y in points:
            ctr = 0
            for h in range(y, 101):
                ctr += len(heights[h]) - bisect.bisect_left(heights[h], x)
            count.append(ctr)
        return count

M = 10 ** 9 + 7

class Solution:
    def count(self, nums, i, n, zseen, oseen, tseen):
        if i >= n:
            return int(zseen and oseen and tseen)
        key = (i, zseen, oseen, tseen)
        if key in self.cache:
            return self.cache[key]
        res = self.count(nums, i + 1, n, zseen, oseen, tseen)
        if (nums[i] == 0 and not oseen and not tseen) or (nums[i] == 1 and not tseen and zseen) or (nums[i] == 2 and zseen and oseen):
            res += self.count(nums, i + 1, n, zseen or nums[i] == 0, oseen or nums[i] == 1, tseen or nums[i] == 2)
            res %= M
        self.cache[key] = res
        return res

    def countSpecialSubsequences(self, nums: List[int]) -> int:
        self.cache = {}
        return self.count(nums, 0, len(nums), False, False, False)

class Solution:
    def count(self, nums, r):
        n = len(nums)
        B = 10
        res = [0] * n
        MASK = 0
        p = 1 << B
        od = sorted(range(n), reverse = r)
        for b in range(B, -1, -1):
            ctr = defaultdict(lambda: [0, 0])
            for i in od:
                if bool(nums[i] & (1 << b)) != bool(r):
                    res[i] += ctr[nums[i] & MASK][r]
                    ctr[nums[i] & MASK][1 - r] += 1
                else:
                    ctr[nums[i] & MASK][r] += 1
            MASK |= p
            p //= 2
        return res

    def numTeams(self, rating: List[int]) -> int:
        n = len(rating)
        x = {}
        for el in rating:
            x[el] = 0
        for i, el in enumerate(sorted(x)):
            x[el] = i
        for i in range(n):
            rating[i] = x[rating[i]]
        res = 0
        i = 0
        for x, y in zip(self.count(rating, 0), self.count(rating, 1)):
            res += x * y + (i - x) * (n - i - 1 - y)
            i += 1
        return res

class Solution:
    def ways(self, m, n):
        if m == 0:
            return 1
        if (m, n) in self.cache:
            return self.cache[(m, n)]
        ways = 0
        for i in range(1, min(m, n) + 1):
            ways += self.ways(m - i, n)
        self.cache[(m, n)] = ways
        return ways

    def countTexts(self, pressedKeys: str) -> int:
        self.cache = {}
        keys = [0, 0, 3, 3, 3, 3, 3, 4, 3, 4]
        n = len(pressedKeys)
        i = 0
        ways = 1
        while i < n:
            ctr = 1
            while i < n - 1 and pressedKeys[i] == pressedKeys[i + 1]:
                i += 1
                ctr += 1
            i += 1
            c = pressedKeys[i - 1]
            ways = (ways * self.ways(ctr, keys[int(c)])) % (10 ** 9 + 7)
        return ways

class Solution:
    def numplace(self, n, s) -> int:
        if n == 0:
            return 1
        if (n, s) in self.cache:
            return self.cache[(n, s)]
        res = 0
        if s == 0:
            res += self.numplace(n - 1, 0)
            res += 2 * self.numplace(n - 1, 1)
            res += self.numplace(n - 1, 2)
        elif s == 1:
            res += self.numplace(n - 1, 1)
            res += self.numplace(n - 1, 0)
        else:
            res += self.numplace(n - 1, 0)
        self.cache[(n ,s)] = res
        return res

    def countHousePlacements(self, n: int, both = True) -> int:
        self.cache = {}
        return self.numplace(n, 0) % (10 ** 9 + 7)

class Solution:
    def countNumbers(self, l: str, r: str, b: int) -> int:
        mod = 10**9 + 7
        def toBase(x, b):
            if x == 0:
                return [0]
            arr = []
            while x:
                arr.append(x % b)
                x //= b
            return arr[::-1]
        def countUp(x):
            if x < 0:
                return 0
            dig = toBase(x, b)
            n = len(dig)
            @cache
            def dp(pos, tight, started, last):
                if pos == n:
                    return 1
                res = 0
                up = dig[pos] if tight else b - 1
                for d in range(up + 1):
                    nt = tight and (d == up)
                    if not started:
                        if d == 0:
                            res += dp(pos + 1, nt, False, 0)
                        else:
                            res += dp(pos + 1, nt, True, d)
                    else:
                        if d >= last:
                            res += dp(pos + 1, nt, True, d)
                return res % mod
            return dp(0, True, False, 0)
        L = int(l)
        R = int(r)
        return (countUp(R) - countUp(L - 1)) % mod

class Solution:
    def count(self, num, i, n, tight, nzseen, mask):
        if i >= n:
            return 1
        key = (i, tight, nzseen, mask)
        if key in self.cache:
            return self.cache[key]
        maxd = 9
        if tight:
            maxd = int(num[i])
        res = 0
        for d in range(maxd + 1):
            if not mask & (1 << d) or (d == 0 and not nzseen):
                newmask = mask
                if d != 0 or (nzseen and d == 0):
                    newmask = mask | (1 << d)
                res += self.count(num, i + 1, n, tight and d == maxd, nzseen or d != 0, newmask)
        self.cache[key] = res
        return res

    def countNumbersWithUniqueDigits(self, n: int) -> int:
        self.cache = {}
        return self.count(str(10 ** n - 1), 0, n, True, False, 0)

class Solution:
    def countOdds(self, low: int, high: int) -> int:
        return (high + 1) // 2 - low // 2

M = 10 ** 9 + 7

class Solution:
    def countnums(self, num, i, n, tight, s, mins, maxs, cache):
        if i >= n:
            if mins <= s <= maxs:
                return 1
            return 0
        key = (i, tight, s)
        if key in cache:
            return cache[key]
        maxd = 9
        if tight:
            maxd = int(num[i])
        res = 0
        for d in range(maxd + 1):
            res += self.countnums(num, i + 1, n, tight and d == maxd, s + d, mins, maxs, cache)
            res %= M
        cache[key] = res
        return res

    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        x = 0
        if min_sum <= sum(map(int, num1)) <= max_sum:
            x = 1
        return (M + self.countnums(num2, 0, len(num2), True, 0, min_sum, max_sum, {}) - self.countnums(num1, 0, len(num1), True, 0, min_sum, max_sum, {}) + x) % M

class Solution:
    def countInterestingSubarrays(self, nums: List[int], modulo: int, k: int) -> int:
        p = [0]
        for el in nums:
            p.append(p[-1] + int((el % modulo) == k))
        res = 0
        ctr = Counter()
        for el in p:
            res += ctr[(el - k) % modulo]
            ctr[el % modulo] += 1
        return res

class Solution:
    def numberOfMatches(self, n: int) -> int:
        matches = 0
        while n > 1:
            if n % 2 == 1:
                matches += (n - 1) // 2
                n = 1 + (n - 1) // 2
            else:
                matches += n // 2
                n = n // 2
        return matches

class FenwickTree:
    def __init__(self, x):
        self.bit = x
        for i in range(len(x)):
            j = i | (i + 1)
            if j < len(x):
                x[j] += x[i]

    def update(self, idx, x):
        while idx < len(self.bit):
            self.bit[idx] += x
            idx |= idx + 1

    def query(self, end):
        x = 0
        while end:
            x += self.bit[end - 1]
            end &= end - 1
        return x

class Solution:
    def countRangeSum(self, nums: List[int], lower: int, upper: int) -> int:
        n = len(nums)
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] += p[i] + nums[i]
        mp = {}
        for el in p:
            mp[el] = mp[el - lower] = mp[el - upper] = 0
        for i, el in enumerate(sorted(mp)):
            mp[el] = i
        fw = FenwickTree([0] * (len(mp) + 1))
        res = 0
        for el in p:
            res += fw.query(mp[el - lower] + 1) - fw.query(mp[el - upper])
            fw.update(mp[el], 1)
        return res

class Solution:
    def countSmaller(self, nums):
        n = len(nums)
        B = 18
        m = min(nums)
        if m < 0:
            nums = [el - m for el in nums]
        res = [0] * n
        MASK = 0
        p = 1 << B
        for b in range(B, -1, -1):
            ctr = defaultdict(lambda: [0, 0])
            for i in range(n - 1, -1, -1):
                if nums[i] & (1 << b):
                    res[i] += ctr[nums[i] & MASK][0]
                    ctr[nums[i] & MASK][1] += 1
                else:
                    ctr[nums[i] & MASK][0] += 1
            MASK |= p
            p //= 2
        return res

from collections import deque

class Solution:
    def countPairsOfConnectableServers(self, edges: List[List[int]], signalSpeed: int) -> List[int]:
        n = len(edges) + 1
        graph = defaultdict(list)
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))
        res = [0] * n
        def dfs(i, prev, d, f):
            ctr = 0
            for j, w in graph[i]:
                if j == prev:
                    continue
                val = dfs(j, i, d + w, False)
                if f:
                    res[i] += val * ctr
                ctr += val
            if d % signalSpeed == 0:
                ctr += 1
            return ctr
        for i in range(n):
            dfs(i, -1, 0, True)
        return res

from collections import *
import bisect

class Solution:
    def countPairs(self, n: int, edges: List[List[int]], queries: List[int]) -> List[int]:
        graph = defaultdict(list)
        for a, b in edges:
            graph[a - 1].append(b - 1)
            graph[b - 1].append(a - 1)
        res = []
        vals = [len(graph[i]) for i in range(n)]
        vals.sort()
        for q in queries:
            curr = 0
            for i in range(n):
                a = len(graph[i])
                curr += len(vals) - bisect.bisect_left(vals, q - a + 1)
                if a > q - a:
                    curr -= 1
                nb = Counter()
                for j in graph[i]:
                    nb[j] += 1
                for j in nb:
                    if a + len(graph[j]) > q:
                        curr -= 1
                    if a + len(graph[j]) - nb[j] > q:
                        curr += 1
            res.append(curr // 2)
        return res

class Solution:
    def countPairs(self, coordinates: List[List[int]], k: int) -> int:
        n = len(coordinates)
        ctr = Counter()
        res = 0
        for x2, y2 in coordinates:
            for l in range(k + 1):
                x1 = x2 ^ l
                y1 = y2 ^ (k - l)
                res += ctr[(x1, y1)]
            ctr[(x2, y2)] += 1
        return res

