class Solution:
    def countWinningSequences(self, s: str) -> int:
        n = len(s)
        mp = {'FE': 1, 'EF': -1, 'WF': 1, 'FW': -1, 'EW': 1, 'WE': -1, 'FF': 0, 'EE': 0, 'WW': 0}
        dp = [[[-1, -1, -1] for _ in range(2 * n + 1)] for _ in range(n)]
        ss = 'FWE'
        M = 10 ** 9 + 7
        def count(i, diff, prev):
            if i >= n:
                if diff <= 0:
                    return 0
                return 1
            if prev != -1 and dp[i][n + diff][ss.index(prev)] != -1:
                return dp[i][n + diff][ss.index(prev)]
            res = 0
            for x in ss:
                if x != prev:
                    res += count(i + 1, diff + mp[x + s[i]], x)
                    res %= M
            if prev != -1:
                dp[i][n + diff][ss.index(prev)] = res
            return res
        return count(0, 0, -1)

class Solution:
    def coloredCells(self, n: int) -> int:
        return 2 * n * n - 2 * n + 1

class Solution:
    def countUnguarded(self, m: int, n: int, guards: List[List[int]], walls: List[List[int]]) -> int:
        guards = {(x, y) for x, y in guards}
        walls = {(x, y) for x, y in walls}
        res = set()
        for i in range(m):
            for order in [range(n), range(n - 1, -1, -1)]:
                active = False
                for j in order:
                    if (i, j) in guards:
                        active = True
                    elif (i, j) in walls:
                        active = False
                    elif active:
                        res.add((i, j))
        for j in range(n):
            for order in [range(m), range(m - 1, -1, -1)]:
                active = False
                for i in order:
                    if (i, j) in guards:
                        active = True
                    elif (i, j) in walls:
                        active = False
                    elif active:
                        res.add((i, j))
        return m * n - len(guards) - len(walls) - len(res)

class Solution:
    def uniqueLetterString(self, s: str) -> int:
        n = len(s)
        ind = lambda x: ord(x) - ord('A')
        res = [1] * n
        last = [-1] * 26
        for i in range(n):
            res[i] *= i - last[ind(s[i])]
            last[ind(s[i])] = i
        last = [n] * 26
        for i in range(n - 1, -1, -1):
            res[i] *= last[ind(s[i])] - i
            last[ind(s[i])] = i
        return sum(res)

