M = 10 ** 9 + 7

class Solution:
    def countVowelPermutation(self, n: int) -> int:
        trans = [[1], [0, 2], [0, 1, 3, 4], [2, 4], [0]]
        dp = [[int(i == 0)] * 5 for i in range(n)]
        res = 0
        for i in range(1, n):
            for j in range(5):
                for k in trans[j]:
                    dp[i][j] += dp[i - 1][k]
                    dp[i][j] %= M
        return sum(dp[n - 1]) % M

class Solution:
    def countGoodStrings(self, low: int, high: int, zero: int, one: int) -> int:
        res = 0
        M = 10 ** 9 + 7
        dp = [0] * (high + 1)
        dp[0] = 1
        res = 0
        for i in range(high + 1):
            if i >= zero:
                dp[i] += dp[i - zero]
                dp[i] %= M
            if i >= one:
                dp[i] += dp[i - one]
                dp[i] %= M
            if low <= i <= high:
                res = (res + dp[i]) % M
        return res

class Solution:
    def wordCount(self, startWords: List[str], targetWords: List[str]) -> int:
        words = set()
        for s in startWords:
            ctr = [0] * 26
            for c in s:
                ctr[ord(c) - ord('a')] += 1
            words.add(tuple(ctr))
        res = 0
        for w in targetWords:
            ctr = [0] * 26
            for c in w:
                ctr[ord(c) - ord('a')] += 1
            for i in range(26):
                if ctr[i] != 1:
                    continue
                ctr[i] -= 1
                if tuple(ctr) in words:
                    res += 1
                    break
                ctr[i] += 1
        return res

