from collections import defaultdict

class Solution:
    def root(self, x, parent):
        if parent[x] == x:
            return x
        parent[x] = self.root(parent[x], parent)
        return parent[x]

    def connect(self, x, y, parent):
        x = self.root(x, parent)
        y = self.root(y, parent)
        if x != y:
            parent[x] = y

    def minSwapsCouples(self, row: List[int]) -> int:
        n = len(row)
        graph = defaultdict(list)
        pos = {}
        for i in range(n):
            pos[row[i]] = i
        for i in range(n // 2):
            a = row[2 * i]
            a = a + 1 - 2 * (a % 2)
            b = row[2 * i + 1]
            b = b + 1 - 2 * (b % 2)
            graph[i].append(pos[a] // 2)
            graph[i].append(pos[b] // 2)
        parent = list(range(n // 2))
        for i in graph:
            for j in graph[i]:
                self.connect(i, j, parent)
        for i in graph:
            parent[i] = self.root(i, parent)
        ctr = 0
        for i in range(n // 2):
            if parent[i] != i:
                ctr += 1
        return ctr

class Solution:
    def topologicalSort(self, graph, node, visited):
        visited.add(node)
        for j in graph.get(node, []):
            if j not in visited:
                self.topologicalSort(graph, j, visited)
        self.sorted.append(node)

    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        graph = {}
        for a, b in prerequisites:
            graph[b] = graph.get(b, []) + [a]
        self.sorted = []
        visited = set()
        for node in range(numCourses):
            if node not in visited:
                self.topologicalSort(graph, node, visited)
        self.sorted.reverse()
        pos = {}
        for i, node in enumerate(self.sorted):
            pos[node] = i
        for i in graph:
            for j in graph[i]:
                if pos[i] > pos[j]:
                    return []
        return self.sorted

class Solution:
    def checkIfPrerequisite(self, n: int, prerequisites: List[List[int]], queries: List[List[int]]) -> List[bool]:
        graph = [[] for _ in range(n)]
        for u, v in prerequisites:
            graph[u].append(v)
        @cache
        def check(x, y):
            if x == y:
                return True
            for z in graph[x]:
                if check(z, y):
                    return True
            return False
        return [check(u, v) for u, v in queries]

class Solution:
    def canFinish(self, numCourses: int, prerequisites: List[List[int]]) -> bool:
        graph = {}
        indegree = [0] * numCourses
        for a, b in prerequisites:
            graph[b] = graph.get(b, []) + [a]
            indegree[a] += 1
        queue = []
        for i in range(numCourses):
            if indegree[i] == 0:
                queue.append(i)
        ctr = 0
        while len(queue) > 0:
            curr = queue.pop(0)
            for j in graph.get(curr, []):
                indegree[j] -= 1
                if indegree[j] == 0:
                    queue.append(j)
            ctr += 1
        if ctr < numCourses:
            return False
        return True

from collections import deque

class Solution:
    def replaceValueInTree(self, root: Optional[TreeNode]) -> Optional[TreeNode]:
        sums = []
        q = deque([root])
        while q:
            n = len(q)
            s = 0
            for _ in range(n):
                r = q.pop()
                if not r:
                    continue
                s += r.val
                if r.left:
                    q.appendleft(r.left)
                if r.right:
                    q.appendleft(r.right)
            sums.append(s)
        if root:
            root.val = 0
        q = deque([(root, 0)])
        while q:
            r, d = q.pop()
            if not r:
                continue
            s = 0
            if r.left:
                s += r.left.val
                q.appendleft((r.left, d + 1))
            if r.right:
                s += r.right.val
                q.appendleft((r.right, d + 1))
            if r.left:
                r.left.val = sums[d + 1] - s
            if r.right:
                r.right.val = sums[d + 1] - s
        return root

class Solution:
    def minOperations(self, logs: List[str]) -> int:
        ctr = 0
        for log in logs:
            if log == "../":
                ctr =  max(ctr - 1, 0)
            elif log != "./":
                ctr += 1
        return ctr

class Solution:
    def makeTree(self, tree, node):
        root = None
        if node:
            root = TreeNode(val = node)
            if node in tree:
                root.left = self.makeTree(tree, tree[node][0])
                root.right = self.makeTree(tree, tree[node][1])
        return root

    def createBinaryTree(self, descriptions: List[List[int]]) -> Optional[TreeNode]:
        roots = set(d[0] for d in descriptions)
        tree = {}
        for p, c, left in descriptions:
            if p not in tree:
                tree[p] = [None, None]
            if left:
                tree[p][0] = c
            else:
                tree[p][1] = c
            if c in roots:
                roots.remove(c)
        root = list(roots)[0]
        return self.makeTree(tree, root)

from collections import *

class Solution:
    def maxsplits(self, graph, i, prev, k, values):
        res = 0
        curr = values[i]
        res = 0
        for j in graph[i]:
            if j != prev:
                ncurr, nres = self.maxsplits(graph, j, i, k, values)
                curr += ncurr
                res += nres
        if curr == k:
            res += 1
            curr = 0
        return curr, res

    def componentValue(self, nums: List[int], edges: List[List[int]]) -> int:
        graph = defaultdict(set)
        for a, b in edges:
            graph[a].add(b)
            graph[b].add(a)
        res = 0
        total = sum(nums)
        s = 1
        while s * s <= total:
            if total % s == 0:
                x = self.maxsplits(graph, 0, -1, s, nums)
                if x[0] == 0:
                    res = max(res, x[1] - 1)
                if s * s < total:
                    x = self.maxsplits(graph, 0, -1, total // s, nums)
                    if x[0] == 0:
                        res = max(res, x[1] - 1)
            s += 1
        return res

class Solution:
    def largestMerge(self, a: str, b: str) -> str:
        m = len(a)
        n = len(b)
        res = []
        i = j = 0
        while i < m and j < n:
            if a[i] > b[j]:
                res.append(a[i])
                i += 1
            elif b[j] > a[i]:
                res.append(b[j])
                j += 1
            else:
                if a[i:] >= b[j:]:
                    res.append(a[i])
                    i += 1
                else:
                    res.append(b[j])
                    j += 1
        res.extend(a[i:] + b[j:])
        return res

    def maxNum(self, arr, l):
        n = len(arr)
        stack = []
        for i in range(n):
            while stack and arr[i] > stack[-1] and len(stack) + (n - i - 1) >= l:
                stack.pop()
            stack.append(arr[i])
        while len(stack) > l:
            stack.pop()
        return stack

    def maxNumber(self, nums1: List[int], nums2: List[int], k: int) -> List[int]:
        res = []
        for f in range(max(k - len(nums2), 0), min(k, len(nums1)) + 1):
            a = self.maxNum(nums1, f)
            b = self.maxNum(nums2, k - f)
            res = max(res, self.largestMerge(a, b))
        return res

class TrieNode:
    def __init__(self):
        self.children = {}
        self.count = 0

class Bigger:
    def __init__(self):
        self.root = TrieNode()
        self.B = 24

    def insert(self, val):
        node = self.root
        for i in range(self.B - 1, -1, -1):
            bit = (val >> i) & 1
            if bit not in node.children:
                node.children[bit] = TrieNode()
            node = node.children[bit]
            node.count += 1

    def countBigger(self, val):
        node = self.root
        res = 0
        for i in range(self.B - 1, -1, -1):
            bit = (val >> i) & 1
            if bit == 0 and 1 in node.children:
                res += node.children[1].count
            if bit not in node.children:
                break
            node = node.children[bit]
        return res

class Solution:
    def createSortedArray(self, instructions: List[int]) -> int:
        MOD = 10 ** 9 + 7
        ctr = Counter()
        bg = Bigger()
        res = 0
        x = 0
        for el in instructions:
            v = bg.countBigger(el)
            res += min(v, x - ctr[el] - v)
            res %= MOD
            bg.insert(el)
            ctr[el] += 1
            x += 1
        return res

class Solution:
    def createTargetArray(self, nums: List[int], index: List[int]) -> List[int]:
        n = len(nums)
        op = []
        for i in range(n):
            op.insert(index[i], nums[i])
