from collections import deque

class Solution:
    def cutOffTree(self, forest: List[List[int]]) -> int:
        if forest[0][0] == 0:
            return -1
        m = len(forest)
        n = len(forest[0])
        vals = set()
        for i in range(m):
            for j in range(n):
                if forest[i][j] not in {0, 1}:
                    vals.add((forest[i][j], i, j))
        vals = [(0, 0, 0)] + sorted(vals)
        k = len(vals)
        res = 0
        for pos in range(k - 1):
            vv, ii, jj = vals[pos]
            q = deque([(ii, jj, 0)])
            v = {(ii, jj)}
            found = False
            while len(q) > 0:
                i, j, d = q.pop()
                if forest[i][j] == vals[pos + 1][0]:
                    res += d
                    found = True
                    break
                for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
                    if 0 <= x < m and 0 <= y < n and forest[x][y] != 0 and (x, y) not in v:
                        v.add((x, y))
                        q.appendleft((x, y, d + 1))
            if not found:
                return -1
        return res

class Solution:
    def cycleLengthQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        res = []
        for a, b in queries:
            avals = set()
            bvals = set()
            ah = {}
            bh = {}
            while a:
                avals.add(a)
                ah[a] = len(avals) - 1
                a //= 2
            while b:
                bvals.add(b)
                bh[b] = len(bvals) - 1
                b //= 2
            lca = max(set.intersection(avals, bvals))
            res.append(1 + ah[lca] + bh[lca])
        return res

class Solution:
    def dailyTemperatures(self, temperatures: List[int]) -> List[int]:
        n = len(temperatures)
        answer = [0 for i in range(n)]
        stack = []
        for i in range(n):
            while len(stack) > 0 and temperatures[i] > temperatures[stack[-1]]:
                curr = stack.pop()
                answer[curr] = i - curr
            stack.append(i)
        return answer

import bisect

class SummaryRanges:

    def __init__(self):
        self.nums = []
        self.dup = set()

    def addNum(self, val: int) -> None:
        if val not in self.dup:
            bisect.insort(self.nums, val)
            self.dup.add(val)

    def getIntervals(self) -> List[List[int]]:
        nums = self.nums
        n = len(nums)
        if n == 0:
            return []
        ranges = [[nums[0]]]
        for i in range(1, n):
            if nums[i] == ranges[-1][-1] or nums[i] == ranges[-1][-1] + 1:
                ranges[-1].append(nums[i])
            else:
                ranges.append([nums[i]])
        return [[r[0], r[-1]] for r in ranges]


