class Solution:
    def decodeMessage(self, key: str, message: str) -> str:
        seen = set()
        cipher = {}
        i = 0
        for c in key:
            if c not in seen and c.isalpha():
                cipher[c] = chr(ord('a') + i)
                i += 1
                seen.add(c)
        return "".join([cipher.get(c, c) for c in message])

class Solution:
    def decodeCiphertext(self, encodedText: str, rows: int) -> str:
        m, n = rows, len(encodedText) // rows
        op = ""
        for i in range(n):
            for j in range(m):
                if i + j < n:
                    op += encodedText[(n + 1) * j + i]
        return op.rstrip()

M = 10 ** 9 + 7

class Solution:
    def count(self, s, i, l, n):
        ctr = 0
        if s[i] == '0':
            return ctr
        key = s[i:i+l]
        if key in self.cache:
            return self.cache[key]
        for x in range(1, 27):
            x = str(x)
            if len(x) != l:
                continue
            valid = True
            for j in range(len(x)):
                if i + j >= n:
                    valid = False
                    break
                if s[i + j] != '*' and s[i + j] != x[j]:
                    valid = False
                    break
                if s[i + j] == '*' and x[j] == '0':
                    valid = False
                    break
            if valid:
                ctr += 1
        self.cache[key] = ctr
        return ctr

    def numDecodings(self, s: str) -> int:
        n = len(s)
        dp = [0] * (n + 2)
        dp[n] = 1
        self.cache = {}
        for i in range(n - 1, -1, -1):
            dp[i] += self.count(s, i, 1, n) * dp[i + 1]
            dp[i] += self.count(s, i, 2, n) * dp[i + 2]
            dp[i] %= M
        return dp[0]

class Solution:
    def isCorrect(self, n):
        if n[0] == "0":
            return False
        return int(n) >= 1 and int(n) <= 26

    def numDecodingsRec(self, s):
        if len(s) == 0:
            return 1
        if len(s) == 1:
            if self.isCorrect(s):
                return 1
            else:
                return 0
        if s in self.memo:
            return self.memo[s]
        numWays = 0
        if self.isCorrect(s[:1]):
            numWays += self.numDecodingsRec(s[1:])
        if self.isCorrect(s[:2]):
            numWays += self.numDecodingsRec(s[2:])
        self.memo[s] = numWays
        return numWays

    def numDecodings(self, s: str) -> int:
        self.memo = {}
        return self.numDecodingsRec(s)

class Solution:
    def decode(self, encoded: List[int], first: int) -> List[int]:
        op = [first]
