class Solution:
    def makeFancyString(self, s: str) -> str:
        n = len(s)
        i = 0
        dels = set()
        while i < n:
            ctr = 1
            while i < n - 1 and s[i] == s[i + 1]:
                ctr += 1
                if ctr > 2:
                    dels.add(i)
                i += 1
            i += 1
        return "".join([s[i] for i in range(n) if i not in dels])

class Solution:
    def minDeletionSize(self, strs: List[str]) -> int:
        m = len(strs[0])
        @lru_cache(maxsize = None)
        def dp(i, prev):
            if i >= m:
                return 0
            take = True
            for s in strs:
                if prev != -1 and s[prev] > s[i]:
                    take = False
                    break
            res = dp(i + 1, prev)
            if take:
                res = max(res, 1 + dp(i + 1, i))
            return res
        return m - dp(0, -1)

class Solution:
    def isSorted(self, arr, i, n):
        if i == n - 1:
            return True
        if arr[i] <= arr[i + 1] and self.isSorted(arr, i + 1, n):
            return True
        return False

    def minDeletionSize(self, strs: List[str]) -> int:
        n = len(strs[0])
        k = len(strs)
        ctr = 0
        for i in range(n):
            col = [s[i] for s in strs]
            if not self.isSorted(col, 0, k):
                ctr += 1
        return ctr

class TrieNode:
    def __init__(self):
        self.children = {}
        self.duplicate = False

class Solution:
    def deleteDuplicateFolder(self, paths: List[List[str]]) -> List[List[str]]:
        root = TrieNode()
        for path in paths:
            node = root
            for folder in path:
                if folder not in node.children:
                    node.children[folder] = TrieNode()
                node = node.children[folder]

        serial_map = defaultdict(list)

        def serialize(node):
            if not node.children:
                return ""
            items = []
            for name in sorted(node.children):
                child_serial = serialize(node.children[name])
                items.append(f"({name}{child_serial})")
            serial = ''.join(items)
            serial_map[serial].append(node)
            return serial

        serialize(root)

        for nodes in serial_map.values():
            if len(nodes) > 1:
                for node in nodes:
                    node.duplicate = True

        res = []

        def collect(node, path):
            for name, child in node.children.items():
                if not child.duplicate:
                    new_path = path + [name]
                    res.append(new_path)
                    collect(child, new_path)

        collect(root, [])
        return res

