        res = 0
        for j in range(n):
            curr = float('-inf')
            for i in range(m):
                curr = max(curr, grid[i][j])
            res += curr
        return res

class Solution:
    def removeLeafNodes(self, root, target):
        if root:
            if not root.left and not root.right and root.val == target:
                return None
            root.left = self.removeLeafNodes(root.left, target)
            root.right = self.removeLeafNodes(root.right, target)
            if not root.left and not root.right and root.val == target:
                return None
        return root

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def insert(self, root, node):
        if root:
            if node:
                if node.val <= root.val:
                    root.left = self.insert(root.left, node)
                else:
                    root.right = self.insert(root.right, node)
        else:
            root = node
        return root

    def deleteNode(self, root: Optional[TreeNode], key: int) -> Optional[TreeNode]:
        if root:
            if root.val == key:
                root = self.insert(root.left, root.right)
            elif key < root.val:
                root.left = self.deleteNode(root.left, key)
            else:
                root.right = self.deleteNode(root.right, key)
            return root
        else:
            return None

class Solution:
    def deleteNode(self, node):
        prev = node
        curr = node
        while curr and curr.next:
            curr.val = curr.next.val
            prev = curr
            curr = curr.next
        prev.next = None

class Solution:
    def delNodes(self, root: Optional[TreeNode], to_delete: List[int]) -> List[TreeNode]:
        to_delete = set(to_delete)
        nodes = []
        def DFS(r):
            if r:
                nodes.append(r)
                DFS(r.left)
                DFS(r.right)
        DFS(root)
        def DFS(r, v):
            v.add(r.val)
            if r.left:
                if r.left.val not in to_delete:
                    DFS(r.left, v)
                else:
                    r.left = None
            if r.right:
                if r.right.val not in to_delete:
                    DFS(r.right, v)
                else:
                    r.right = None
        res = set()
        v = set()
        for r in nodes:
            if r.val not in v and r.val not in to_delete:
                res.add(r)
                v.add(r.val)
                DFS(r, v)
        return res

class Solution:
    def modifiedList(self, nums: List[int], head: Optional[ListNode]) -> Optional[ListNode]:
        nums = set(nums)
        def get(r):
            if not r:
                return r
            if r.val in nums:
                return get(r.next)
            r.next = get(r.next)
            return r
        return get(head)

class Solution:
    def md(self, word1, word2, i1, i2):
        if (i1, i2) in self.cache:
            return self.cache[(i1, i2)]
        if i1 == len(word1):
            return len(word2) - i2
        if i2 == len(word2):
            return len(word1) - i1
        if word1[i1] == word2[i2]:
            self.cache[(i1, i2)] = min(self.md(word1, word2, i1 + 1, i2 + 1), 1 + self.md(word1, word2, i1, i2 + 1), 1 + self.md(word1, word2, i1 + 1, i2))
            return self.cache[(i1, i2)]
        else:
            self.cache[(i1, i2)] = 1 + min(self.md(word1, word2, i1, i2 + 1), self.md(word1, word2, i1 + 1, i2))
            return self.cache[(i1, i2)]

    def minDistance(self, word1: str, word2: str) -> int:
        self.cache = {}
        return self.md(word1, word2, 0, 0)

class Solution:
    def deleteTreeNodes(self, n: int, parent: List[int], value: List[int]) -> int:
        graph = [[] for _ in range(n)]
        for i in range(1, n):
            graph[parent[i]].append(i)
        def dfs(i):
            s = value[i]
            ctr = 1
            for j in graph[i]:
                cs, cctr = dfs(j)
                s += cs
                ctr += cctr
            if s == 0:
                ctr = 0
            return s, ctr
        return dfs(0)[1]

class Solution:
    def splitPainting(self, segments: List[List[int]]) -> List[List[int]]:
        vals = {}
        for l, r, c in segments:
            vals[l] = vals.get(l, 0) + c
            vals[r] = vals.get(r, 0) - c
        vals = sorted(vals.items())
        res = []
        p = 0
        for i in range(len(vals) - 1):
            p += vals[i][1]
            if p:
                res.append((vals[i][0], vals[i + 1][0], p))
        return res

