import heapq

class FoodRatings:

    def __init__(self, foods: List[str], cuisines: List[str], ratings: List[int]):
        n = len(foods)
        self.deleted = defaultdict(int)
        self.cuisines = defaultdict(list)
        self.f2c = {}
        self.ratings = {}
        for i in range(n):
            heapq.heappush(self.cuisines[cuisines[i]], (-ratings[i], foods[i]))
            self.f2c[foods[i]] = cuisines[i]
            self.ratings[foods[i]] = ratings[i]

    def changeRating(self, food: str, newRating: int) -> None:
        cuisine = self.f2c[food]
        old = self.ratings[food]
        self.deleted[(cuisine, -old, food)] += 1
        self.ratings[food] = newRating
        heapq.heappush(self.cuisines[cuisine], (-newRating, food))

    def highestRated(self, cuisine: str) -> str:
        rating, food = self.cuisines[cuisine][0]
        while (cuisine, rating, food) in self.deleted:
            heapq.heappop(self.cuisines[cuisine])
            self.deleted[(cuisine, rating, food)] -= 1
            if self.deleted[(cuisine, rating, food)] == 0:
                del self.deleted[(cuisine, rating, food)]
            rating, food = self.cuisines[cuisine][0]
        return food

from sortedcontainers import SortedList
from collections import defaultdict

class NumberContainers:

    def __init__(self):
        self.vals = {}
        self.pos = defaultdict(SortedList)

    def change(self, index: int, number: int) -> None:
        if index in self.vals:
            self.pos[self.vals[index]].remove(index)
        self.pos[number].add(index)
        self.vals[index] = number

    def find(self, number: int) -> int:
        if len(self.pos[number]) > 0:
            return self.pos[number][0]
        return -1

from collections import Counter

class CustomStack:
    def __init__(self, maxSize: int):
        self.s = []
        self.increments = Counter()
        self.maxSize = maxSize

    def push(self, x: int) -> None:
        if len(self.s) == self.maxSize:
            return -1
        self.s.append(x)

    def pop(self) -> int:
        if len(self.s) == 0:
            return -1
        self.s[-1] += self.increments[len(self.s)]
        self.increments[len(self.s) - 1] += self.increments[len(self.s)]
        del self.increments[len(self.s)]
        return self.s.pop()

    def increment(self, k: int, val: int) -> None:
        self.increments[min(k, len(self.s))] += val

class Node:
    def __init__(self, val=None, children=[], end=False):
        self.val = val
        self.children = children
        self.end = end

class WordDictionary:

    def __init__(self):
        self.root = Node(val=None, children=[])

    def addWord(self, word: str) -> None:
        n = len(word)
        curr = self.root
        for i, c in enumerate(word):
            found = False
            for node in curr.children:
                if node.val == c:
                    curr = node
                    found = True
                    break
            if not found:
                newcurr = Node(val=c, children=[])
                curr.children.append(newcurr)
                curr = newcurr
        curr.end = True

    def search(self, word: str) -> bool:
        n = len(word)
        paths = [(self.root, 0)]
        while len(paths) > 0:
            curr, i = paths.pop()
            if i == n and curr.end:
                return True
            if curr.children and i < n:
                for c in curr.children:
                    if word[i] == "." or c.val == word[i]:
                        paths.append((c, i + 1))
        return False

from collections import defaultdict

class ATM:

    def __init__(self):
        self.notectr = defaultdict(int)

    def deposit(self, banknotesCount: List[int]) -> None:
        for i in range(5):
            self.notectr[[20, 50, 100, 200, 500][i]] += banknotesCount[i]

    def withdraw(self, amount: int) -> List[int]:
        currnotectr = self.notectr.copy()
        for note in [500, 200, 100, 50, 20]:
            notesused = min(amount // note, currnotectr[note])
            amount -= notesused * note
            currnotectr[note] -= notesused
            if amount == 0:
                break
        if amount != 0:
            return [-1]
        used = [self.notectr[note] - currnotectr[note] for note in [20, 50, 100, 200, 500]]
        self.notectr = currnotectr
        return used



