class Bitset:
    def __init__(self, size: int):
        B = int(pow(size, 0.5) + 1)
        blocks = [[set(), set()] for _ in range(B)]
        self.total = 0
        for i in range(size):
            blocks[i // B][0].add(i % B)
        self.B = B
        self.blocks = blocks
        self.size = size

    def fix(self, idx: int) -> None:
        if idx % self.B in self.blocks[idx // self.B][0]:
            self.blocks[idx // self.B][0].remove(idx % self.B)
            self.blocks[idx // self.B][1].add(idx % self.B)
            self.total += 1

    def unfix(self, idx: int) -> None:
        if idx % self.B in self.blocks[idx // self.B][1]:
            self.blocks[idx // self.B][1].remove(idx % self.B)
            self.blocks[idx // self.B][0].add(idx % self.B)
            self.total -= 1

    def flip(self) -> None:
        for idx in range(self.B):
            self.total -= len(self.blocks[idx][1])
            self.blocks[idx].reverse()
            self.total += len(self.blocks[idx][1])

    def all(self) -> bool:
        return self.total == self.size

    def one(self) -> bool:
        return self.total > 0

    def count(self) -> int:
        return self.total

    def toString(self) -> str:
        return "".join("0" if idx % self.B in self.blocks[idx // self.B][0] else "1" for idx in range(self.size))

class BrowserHistory:

    def __init__(self, homepage: str):
        self.stack = [homepage]
        self.next = []

    def visit(self, url: str) -> None:
        self.stack.append(url)
        self.next = []

    def back(self, steps: int) -> str:
        for _ in range(steps):
            if len(self.stack) > 1:
                self.next.append(self.stack.pop())
        return self.stack[-1]

    def forward(self, steps: int) -> str:
        for _ in range(steps):
            if len(self.next) > 0:
                self.stack.append(self.next.pop())
        return self.stack[-1]

class MyCircularDeque:
    def __init__(self, k: int):
        self.i = 0
        self.l = 0
        self.k = k
        self.q = [-1] * self.k

    def insertFront(self, value: int) -> bool:
        if self.isFull():
            return False
        self.l += 1
        self.i = (self.i + self.k - 1) % self.k
        self.q[self.i] = value
        return True

    def insertLast(self, value: int) -> bool:
        if self.isFull():
            return False
        self.l += 1
        self.q[(self.i + self.l + self.k - 1) % self.k] = value
        return True

    def deleteFront(self) -> bool:
        if self.isEmpty():
            return False
        self.i = (self.i + 1) % self.k
        self.l -= 1
        return True

    def deleteLast(self) -> bool:
        if self.isEmpty():
            return False
        self.l -= 1
        return True

    def getFront(self) -> int:
        if self.isEmpty():
            return -1
        return self.q[self.i]

    def getRear(self) -> int:
        if self.isEmpty():
            return -1
        return self.q[(self.i + self.l + self.k - 1) % self.k]

    def isEmpty(self) -> bool:
        return self.l == 0

    def isFull(self) -> bool:
        return self.l == self.k

class MyCircularQueue:
    def __init__(self, k: int):
        self.queue = [None] * k
        self.k = k
        self.i = 0
        self.size = 0

    def enQueue(self, value: int) -> bool:
        if self.isFull():
            return False
        self.queue[(self.i + self.size) % self.k] = value
        self.size += 1
        return True

    def deQueue(self) -> bool:
        if self.isEmpty():
            return False
        self.queue[self.i] = None
        self.i = (self.i + 1) % self.k
        self.size -= 1
        return True

    def Front(self) -> int:
        if self.isEmpty():
            return -1
        return self.queue[self.i]

    def Rear(self) -> int:
        if self.isEmpty():
            return -1
        return self.queue[(self.k + self.i + self.size - 1) % self.k]

    def isEmpty(self) -> bool:
        return self.size == 0

    def isFull(self) -> bool:
        return self.size == self.k

from collections import deque

class FrontMiddleBackQueue:
    def __init__(self):
        self.l = deque()
        self.r = deque()

    def empty(self):
        return len(self.l) == 0 and len(self.r) == 0

    def balance(self):
        while len(self.r) < len(self.l):
            self.r.appendleft(self.l.pop())
        while len(self.r) - len(self.l) > 1:
            self.l.append(self.r.popleft())

    def pushFront(self, val: int) -> None:
        self.l.appendleft(val)
        self.balance()

    def pushMiddle(self, val: int) -> None:
        self.l.append(val)
        self.balance()

    def pushBack(self, val: int) -> None:
        self.r.append(val)
        self.balance()

    def popFront(self) -> int:
        if self.empty():
            return -1
        res = -1
        if len(self.l) == 0:
            res = self.r.popleft()
        else:
            res = self.l.popleft()
        self.balance()
        return res

    def popMiddle(self) -> int:
        if self.empty():
            return -1
        if len(self.r) > len(self.l):
            res = self.r.popleft()
        else:
            res = self.l.pop()
        self.balance()
        return res

    def popBack(self) -> int:
        if self.empty():
            return -1
        res = self.r.pop()
        self.balance()
        return res

