import heapq

class Graph:
    def __init__(self, n: int, edges: List[List[int]]):
        self.graph = defaultdict(set)
        for edge in edges:
            self.addEdge(edge)

    def addEdge(self, edge: List[int]) -> None:
        self.graph[edge[0]].add((edge[1], edge[2]))

    def shortestPath(self, node1: int, node2: int) -> int:
        dist = defaultdict(lambda: float('inf'))
        dist[node1] = 0
        heap = [(dist[node1], node1)]
        while len(heap) > 0:
            currd, node = heapq.heappop(heap)
            if node == node2:
                return currd
            for j, w in self.graph[node]:
                if dist[j] > currd + w:
                    dist[j] = currd + w
                    heapq.heappush(heap, (dist[j], j))
        return -1

class Node:
    def __init__(self, val=None):
        self.left = None
        self.right = None
        self.val = val
        self.end = False

class MyHashMap:

    def __init__(self):
        self.root = Node()

    def put(self, key: int, value: int) -> None:
        curr = self.root
        while key:
            if key & 1:
                if curr.right == None:
                    curr.right = Node()
                curr = curr.right
            else:
                if curr.left == None:
                    curr.left = Node()
                curr = curr.left
            key = key >> 1
        curr.val = value
        curr.end = True

    def get(self, key: int) -> int:
        curr = self.root
        while key:
            if curr == None:
                return -1
            if key & 1:
                curr = curr.right
            else:
                curr = curr.left
            key = key >> 1
        if not curr or not curr.end:
            return -1
        return curr.val

    def remove(self, key: int) -> None:
        curr = self.root
        while key:
            if curr == None:
                return None
            if key & 1:
                curr = curr.right
            else:
                curr = curr.left
            key = key >> 1
        if not curr or not curr.end:
            return
        curr.end = False

