class Solution:
    def minimumSum(self, n: int, k: int) -> int:
        res = 0
        curr = 1
        blocked = set()
        for _ in range(n):
            while curr in blocked:
                curr += 1
            blocked.add(k - curr)
            res += curr
            curr += 1
        return res

class Solution:
    def isWinner(self, player1: List[int], player2: List[int]) -> int:
        n = len(player1)
        a = 0
        b = 0
        for i in range(n):
            actr = 0
            for j in [i - 2, i - 1]:
                if j >= 0 and player1[j] == 10:
                    actr += 1
            bctr = 0
            for j in [i - 2, i - 1]:
                if j >= 0 and player2[j] == 10:
                    bctr += 1
            if actr == 0:
                a += player1[i]
            else:
                a += 2 * player1[i]
            if bctr == 0:
                b += player2[i]
            else:
                b += 2 * player2[i]
        if a > b:
            return 1
        elif b > a:
            return 2
        else:
            return 0

class Solution:
    def verticalFlip(self, matrix, n):
        for i in range(n // 2):
            for j in range(n):
                matrix[i][j], matrix[n - i - 1][j] = matrix[n - i - 1][j], matrix[i][j]

    def diagonalFlip(self, matrix, n):
        for i in range(n):
            for j in range(i, n):
                matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    def equals(self, m1, m2, n):
        for i in range(n):
            for j in range(n):
                if m1[i][j] != m2[i][j]:
                    return False
        return True

    def findRotation(self, mat: List[List[int]], target: List[List[int]]) -> bool:
        n = len(mat)
        for _ in range(4):
            if self.equals(mat, target, n):
                return True
            self.verticalFlip(mat, n)
            self.diagonalFlip(mat, n)
        return False

from collections import defaultdict

class Solution:
    def maximumDetonation(self, bombs):
        n = len(bombs)
        graph = defaultdict(set)
        for i in range(n):
            for j in range(n):
                if i != j and (bombs[i][0] - bombs[j][0]) ** 2 + (bombs[i][1] - bombs[j][1]) ** 2 <= bombs[i][2] ** 2:
                    graph[i].add(j)
        res = 0
        for i in range(n):
            v = {i}
            stack = [i]
            while len(stack) > 0:
                curr = stack.pop()
                for j in graph[curr]:
                    if j not in v:
                        v.add(j)
                        stack.append(j)
            res = max(res, len(v))
        return res

