class Solution:
    def findDiagonalOrder(self, nums: List[List[int]]) -> List[int]:
        m = len(nums)
        diags = defaultdict(list)
        for i in range(m):
            n = len(nums[i])
            for j in range(n):
                diags[i + j].append((j, nums[i][j]))
        res = []
        for i in sorted(diags.keys()):
            res.extend([j[1] for j in sorted(diags[i])])
        return res

class Solution:
    def findDiagonalOrder(self, mat: List[List[int]]) -> List[int]:
        m = len(mat)
        n = len(mat[0])
        op = []
        x, y = 0, 0
        while len(op) != m * n:
            slope = (x + y) & 1
            op.append(mat[y][x])
            dx, dy = (-1, 1) if slope else (1, -1)
            if x + dx < 0 or x + dx >= n or y + dy < 0 or y + dy >= m:
                if slope:
                    if y < m - 1:
                        y += 1
                    else:
                        x += 1
                else:
                    if x < n - 1:
                        x += 1
                    else:
                        y += 1
            else:
                x += dx
                y += dy
        return op

class Solution:
    def maxDepth(self, root):
        if not root:
            return -1
        a = 1 + self.maxDepth(root.left)
        b =  1 + self.maxDepth(root.right)
        self.md = max(self.md, a + b)
        return max(a, b)

    def diameterOfBinaryTree(self, root: Optional[TreeNode]) -> int:
        self.md = float('-inf')
        self.maxDepth(root)
        return self.md

class Solution:
    def getcount(self, ctr, rollMax, rem):
        if rem == 0:
            return 1
        key = tuple(ctr + [rem])
        if key in self.cache:
            return self.cache[key]
        res = 0
        for i in range(6):
            if ctr[i] < rollMax[i]:
                currctr = ctr[:]
                for j in range(6):
                    currctr[j] = 0
                currctr[i] = ctr[i] + 1
                res += self.getcount(currctr, rollMax, rem - 1)
        self.cache[key] = res
        return res

    def dieSimulator(self, n: int, rollMax: List[int]) -> int:
        ctr = [0] * 6
        self.cache = {}
        return self.getcount(ctr, rollMax, n) % (10 ** 9 + 7)

from collections import *

class Solution:
    def BFS(self, graph, i):
        q = deque([(i, self.price[i])])
        dist = {}
        dist[i] = self.price[i]
        while len(q) > 0:
            curr, d = q.pop()
            for j in graph[curr]:
                if dist.get(j, float('inf')) > d + self.price[j]:
                    dist[j] = d + self.price[j]
                    q.appendleft((j, d + self.price[j]))
        res = max(dist.keys(), key = lambda i: dist[i])
        return (res, dist)

    def maxOutput(self, n: int, edges: List[List[int]], price: List[int]) -> int:
        self.price = price
        graph = defaultdict(set)
        for a, b in edges:
            graph[a].add(b)
            graph[b].add(a)
        x, dx = self.BFS(graph, 0)
        y, dy = self.BFS(graph, x)
        z, dz = self.BFS(graph, y)
        res = 0
        for i in range(n):
            cost = max(dy[i], dz[i])
            res = max(res, cost - price[i])
        return res

class Solution:
    def onesMinusZeros(self, grid: List[List[int]]) -> List[List[int]]:
        m = len(grid)
        n = len(grid[0])
        onerows = [0] * m
        onecols = [0] * n
        for i in range(m):
            for j in range(n):
                onerows[i] += grid[i][j]
                onecols[j] += grid[i][j]
        for i in range(m):
            for j in range(n):
                grid[i][j] = 2 * onerows[i] + 2 * onecols[j] - m - n
        return grid

class Solution:
    def diffWaysToCompute(self, expression: str) -> List[int]:
        def find(s):
            res = []
            if s.isdigit():
                res.append(int(s))
                return res
            for i in range(len(s)):
                if not s[i].isdigit():
                    a = find(s[:i])
                    b = find(s[i+1:])
                    for x in a:
                        for y in b:
                            res.append(eval(f"{x}{s[i]}{y}"))
            return res
        return sorted(find(expression))

class Solution:
    def count(self, s, i, tight, nzseen, ctr, target, cache):
        if i >= len(s):
            return ctr
        key = (i, tight, nzseen, ctr)
        if key in cache:
            return cache[key]
        maxd = 9
        if tight:
            maxd = int(s[i])
        res = 0
        for d in range(maxd + 1):
            newnzseen = nzseen or d != 0
            res += self.count(s, i + 1, tight and d == maxd, newnzseen, ctr + int(newnzseen and d == target), target, cache)
        cache[key] = res
        return res

    def digitsCount(self, d: int, low: int, high: int) -> int:
        return self.count(str(high), 0, True, False, 0, d, {}) - self.count(str(low - 1), 0, True, False, 0, d, {})

from collections import deque

class Solution:
    def distanceToCycle(self, n: int, edges: List[List[int]]) -> List[int]:
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        v = [False] * n
        q = deque()
        def dfs(i, p):
            q.appendleft((i, 0))
            v[i] = True
            for j in graph[i]:
                if not v[j]:
                    if dfs(j, i):
                        return True
                elif j != p:
                    while q and q[-1][0] != j:
                        q.pop()
                    return True
            q.popleft()
            v[i] = False
            return False
        dfs(0, -1)
        v = [False] * n
        for i, d in q:
            v[i] = True
        res = [0] * n
        while q:
            i, d = q.pop()
            res[i] = d
            for j in graph[i]:
                if not v[j]:
                    v[j] = True
                    q.appendleft((j, d + 1))
        return res

import bisect

class Solution:
    def rearrangeBarcodes(self, barcodes: List[int]) -> List[int]:
        n = len(barcodes)
        ctr = {}
        for b in barcodes:
            ctr[b] = ctr.get(b, 0) + 1
        freq = sorted([(-v, k) for k, v in ctr.items()])
        op = []
        while len(op) < n:
            i = 0
            curr = freq[i]
            if len(op) > 0:
                while curr[1] == op[-1]:
                    i += 1
                    curr = freq[i]
                c = curr[1]
            else:
                c = curr[1]
            op.append(c)
            del freq[bisect.bisect_left(freq, curr)]
            if curr[0] + 1 < 0:
                bisect.insort(freq, (curr[0] + 1, curr[1]))
        return op

class Solution:
    def powers(self, n, p, ip, M):
        pw = 1
        invpw = 1
        ppow = []
        invppow = []
        for _ in range(n):
            ppow.append(pw)
            invppow.append(invpw)
            pw = (pw * p) % M
            invpw = (invpw * ip) % M
        return ppow, invppow

    def hashes(self, s, p, M):
        n = len(s)
        h = [0] * (n + 1)
        for i in range(n):
            h[i + 1] = (h[i] + self.ppow[i] * (ord(s[i]) - ord('a'))) % M
        return h

    def distinctEchoSubstrings(self, text: str) -> int:
        n = len(text)
        M = 10 ** 9 + 9
        p = 31
        self.ppow, self.invppow = self.powers(n + 1, p, pow(p, M - 2, M), M)
        subhash = lambda h, i, j: (self.invppow[i] * (h[j + 1] + M - h[i])) % M
        hashes = self.hashes(text, p, M)
        res = set()
        for i in range(n):
            for j in range(i, (i + n) // 2):
                if subhash(hashes, i, j) == subhash(hashes, j + 1, 2 * j - i + 1):
                    res.add(text[i:j+1])
        return len(res)

class Solution:
    def distinctNumbers(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        res = []
        ctr = Counter()
        for i in range(n):
            ctr[nums[i]] += 1
            if i >= k:
                ctr[nums[i - k]] -= 1
                if ctr[nums[i - k]] == 0:
                    del ctr[nums[i - k]]
            if i >= k - 1:
                res.append(len(ctr))
        return res

class Solution:
    def factors(self, n):
        i = 2
        factors = set()
        while i * i <= n:
            if n % i:
                i += 1
            else:
                while n % i == 0:
                    n //= i
                factors.add(i)
        if n > 1:
            factors.add(n)
        return factors

    def distinctPrimeFactors(self, nums: List[int]) -> int:
        res = set()
        for el in nums:
            res.update(self.factors(el))
        return len(res)

class Solution:
    def distinctSubseqII(self, s: str) -> int:
        n = len(s)
        dp = [1] * (n + 1)
        prev = {}
        for i in range(1, n + 1):
            dp[i] = 2 * dp[i - 1]
            if s[i - 1] in prev:
                dp[i] -= dp[prev[s[i - 1]]]
            prev[s[i - 1]] = i - 1
        dp[n] -= 1
        return dp[n] % (10 ** 9 + 7)

