class Solution:
    def check(self, graph, i, color):
        for j in graph[i]:
            if color[j] != -1 and color[j] != 1 - color[i]:
                return False
            if color[j] == -1:
                color[j] = 1 - color[i]
                self.currv.add(j)
                if not self.check(graph, j, color):
                    return False
        return True

    def count(self, graph, i):
        q = deque([(i, 1)])
        v = {i}
        res = 0
        while len(q) > 0:
            curr, ctr = q.pop()
            res = ctr
            for j in graph[curr]:
                if j not in v:
                    v.add(j)
                    q.appendleft((j, ctr + 1))
        return res

    def magnificentSets(self, n: int, edges: List[List[int]]) -> int:
        graph = defaultdict(set)
        for a, b in edges:
            graph[a - 1].add(b - 1)
            graph[b - 1].add(a - 1)
        color = [-1] * n
        res = 0
        for i in range(n):
            if color[i] == -1:
                color[i] = 0
                self.currv = {i}
                if not self.check(graph, i, color):
                    return -1
                curr = 0
                for x in self.currv:
                    curr = max(curr, self.count(graph, x))
                res += curr
        return res

class Solution:
    def dividePlayers(self, skill: List[int]) -> int:
        n = len(skill)
        s = sum(skill)
        if s % (n // 2) != 0:
            return -1
        s //= (n // 2)
        res = 0
        ctr = Counter(skill)
        for el in ctr:
            if 2 * el < s:
                if ctr[el] != ctr[s - el]:
                    return -1
                res += el * (s - el) * ctr[el]
        if s % 2 == 0:
            if ctr[s // 2] & 1:
                return -1
            res += (ctr[s // 2] // 2) * (s // 2) ** 2
        return res

class Solution:
    def divide(self, dividend: int, divisor: int) -> int:
        sign = [1, -1][(dividend >= 0) ^ (divisor >= 0)]
        dividend = abs(dividend)
        divisor = abs(divisor)
        res = 0
        beg = 0
        end = dividend
        while beg <= end:
            mid = (beg + end) // 2
            if divisor * mid <= dividend:
                res = mid
                beg = mid + 1
            else:
                end = mid - 1
        return min(max(-2147483648, sign * res), 2147483647)

class Solution:
    def differenceOfSums(self, n: int, m: int) -> int:
