        return n * (n + 1) // 2 - m * k * (k + 1)

class Solution:
    def DG(self, n: int) -> bool:
        if n in self.cache:
            return self.cache[n]
        for x in range(1, n):
            if n % x == 0 and not self.DG(n - x):
                self.cache[n] = True
                return True
        self.cache[n] = False
        return False

    def divisorGame(self, n: int) -> bool:
        self.cache = {}
        return self.DG(n)

from collections import deque

class Solution:
    def predictPartyVictory(self, senate: str) -> str:    
        ctr = [senate.count('R'), senate.count('D')]
        senate = deque(senate)
        l = len(senate)
        while min(ctr) > 0:
            r = d = 0
            extraDire = max(ctr[0] - ctr[1], 0)
            extraRad = max(ctr[1] - ctr[0], 0)
            ctr[0] = ctr[1] = 0
            for _ in range(l):
                c = senate.popleft()
                l -= 1
                if c == 'R':
                    if r == 0:
                        if extraRad == 0:
                            senate.append('R')
                            l += 1
                            ctr[0] += 1
                        else:
                            extraRad -= 1
                        d += 1
                    else:
                        r -= 1
                else:
                    if d == 0:
                        if extraDire == 0:
                            senate.append('D')
                            l += 1
                            ctr[1] += 1
                        else:
                            extraDire -= 1
                        r += 1
                    else:
                        d -= 1
        if ctr[0] > 0:
            return "Radiant"
        return "Dire"

class Solution:
    def reverseList(self, head):
        prev, curr = None, head
        while curr:
            curr.next, prev, curr = prev, curr, curr.next
        return prev

    def addTwoNumbers(self, l1, l2, carry):
        if l1 or l2:
            l1val = l1.val if l1 else 0
            l2val = l2.val if l2 else 0
            currval = l1val + l2val + carry
            curr = ListNode(val = currval % 10)
            curr.next = self.addTwoNumbers(l1.next if l1 else None, l2.next if l2 else None, carry = currval // 10)
            return curr
        else:
            if carry > 0:
                return ListNode(val = carry)
            return None

    def doubleIt(self, head: Optional[ListNode]) -> Optional[ListNode]:
        head = self.reverseList(head)
        head = self.addTwoNumbers(head, head, carry = 0)
        return self.reverseList(head)

