class Solution:
    def equalPairs(self, grid: List[List[int]]) -> int:
        n = len(grid)
        colctr = defaultdict(int)
        rowctr = defaultdict(int)
        for i in range(n):
            rowctr[tuple(grid[i])] += 1
            colctr[tuple([grid[k][i] for k in range(n)])] += 1
        res = 0
        for row in rowctr:
            res += rowctr[row] * colctr[row]
        return res

from functools import cmp_to_key

class Solution:
    def distance(self, a, b):
        return (b[0] - a[0]) * (b[0] - a[0]) + (b[1] - a[1]) * (b[1] - a[1])

    def orientation(self, a, b, c):
        return (b[1] - a[1]) * (c[0] - b[0]) - (b[0] - a[0]) * (c[1] - b[1])

    def outerTrees(self, trees: List[List[int]]) -> List[List[int]]:
        n = len(trees)
        if n <= 1:
            return trees
        beg = min(trees)
        def cmp(a, b):
            d = self.orientation(beg, a, b) - self.orientation(beg, b, a)
            if d == 0:
                return self.distance(beg, a) - self.distance(beg, b)
            return 1 if d > 0 else -1
        trees.sort(key = cmp_to_key(cmp))
        i = n - 1
        while i >= 0 and self.orientation(beg, trees[-1], trees[i]) == 0:
            i -= 1
        j = i + 1
        k = n - 1
        while j < k:
            trees[j], trees[k] = trees[k], trees[j]
            j += 1
            k -= 1
        stack = []
        stack.append(trees[0])
        stack.append(trees[1])
        for i in range(2, n):
            curr = stack.pop()
            while self.orientation(stack[-1], curr, trees[i]) > 0:
                curr = stack.pop()
            stack.append(curr)
            stack.append(trees[i])
        return stack

class Solution:
    def escapeGhosts(self, ghosts: List[List[int]], target: List[int]) -> bool:
        t = float('inf')
        tx, ty = target
        for i, j in ghosts:
            t = min(t, abs(tx - i) + abs(ty - j))
        return t > abs(tx) + abs(ty)

class Solution:
    def evaluateTree(self, root: Optional[TreeNode]) -> bool:
        if root:
            l = self.evaluateTree(root.left) == 1
            r = self.evaluateTree(root.right) == 1
            if root.val == 2:
                return l or r
            elif root.val == 3:
                return l and r
            else:
                return root.val == 1
        return False

class Solution:
    def calcEquation(self, equations: List[List[str]], values: List[float], queries: List[List[str]]) -> List[float]:
        graph = {}
        n = len(equations)
        for i in range(n):
            a, b = equations[i]
            graph[a] = graph.get(a, []) + [(b, values[i])]
            graph[b] = graph.get(b, []) + [(a, 1 / values[i])]
        op = []
        for c, d in queries:
            found = False
            paths = [(c, 1, {c})]
            while len(paths) > 0:
                curr, prod, visited = paths.pop()
                if curr not in graph:
                    break
                if curr == d:
                    op.append(prod)
                    found = True
                    break
                for j, div in graph.get(curr, []):
                    if j not in visited:
                        paths.append((j, prod * div, visited.union({j})))
            if not found:
                op.append(-1.0)
        return op

class Solution:
    def evalRPN(self, tokens: List[str]) -> int:
        stack = []
        for t in tokens:
            if t in { '+', '-', '*', '/' }:
                op2 = stack.pop()
                op1 = stack.pop()
                if t == '+':
                    stack.append(op1 + op2)
                elif t == '-':
                    stack.append(op1 - op2)
                elif t == '*':
                    stack.append(op1 * op2)
                elif t == '/':
                    stack.append(int(op1 / op2))
            else:
                stack.append(int(t))
        return stack.pop()

class Solution:
    def evaluate(self, s: str, knowledge: List[List[str]]) -> str:
        knw = {}
        for k, v in knowledge:
            knw[k] = v
        openings = []
        i = 0
        while i < len(s):
            if s[i] == "(":
                openings.append(i)
            elif s[i] == ")":
                prev = openings.pop()
                repl = knw.get(s[prev + 1:i], '?')
                s = s[:prev] + repl + s[i + 1:]
                i = prev
            i += 1
        return s

from collections import deque


class Solution:
    def isEvenOddTree(self, root: Optional[TreeNode]) -> bool:
        if not root:
            return True
        q = deque([root])
        even = True
        while q:
            lastodd = float('-inf')
            lasteven = float('inf')
            for _ in range(len(q)):
                curr = q.pop()
                if curr.val & 1:
                    if not even:
                        return False
                    if curr.val <= lastodd:
                        return False
                    lastodd = curr.val
                else:
                    if even:
                        return False
                    if curr.val >= lasteven:
                        return False
                    lasteven = curr.val
                if curr.left:
                    q.appendleft(curr.left)
                if curr.right:
                    q.appendleft(curr.right)
            even = not even
        return True

class Solution:
    def titleToNumber(self, columnTitle: str) -> int:
        total = 0
        for c in columnTitle:
            total = 26 * total + ord(c) - ord('A') + 1
        return total

class Solution:
    def convertToTitle(self, columnNumber: int) -> str:
        res = []
        while columnNumber:
            columnNumber -= 1
            res.append(chr(ord('A') + columnNumber % 26))
            columnNumber //= 26
        res.reverse()
        return "".join(res)

class Solution:
    def getexp(self, num, target, i, n, lastop, curr):
        if i >= n:
            x = "".join(curr)
            if eval(x) == target:
                self.res.append(x)
            return
        if lastop:
            self.getexp(num, target, i + 1, n, False, curr + [num[i]])
        else:
            if curr[-1] != "0":
                self.getexp(num, target, i + 1, n, False, curr[:-1] + [curr[-1] + num[i]])
            for op in "+-*":
                self.getexp(num, target, i, n, True, curr + [op])

    def addOperators(self, num: str, target: int) -> List[str]:
        if len(set(num)) == 1 and num[0] != "0" and target % int(num[0]) != 0:
            return []
        self.res = []
        self.getexp(num, target, 0, len(num), True, [])
        return self.res

class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        n = len(s)
        dc = set(dictionary)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0
        for i in range(1, n + 1):
            dp[i] = min(dp[i], 1 + dp[i - 1])
            for l in range(1, i + 1):
                if s[i-l:i] in dc:
                    dp[i] = min(dp[i], dp[i - l])
        return dp[n]

class Solution:
    def trailingZeroes(self, n: int) -> int:
        ctr = [0, 0]
        for i in range(1, n + 1):
            curr = i
            while curr % 2 == 0:
                ctr[0] += 1
                curr = curr // 2
            while curr % 5 == 0:
                ctr[1] += 1
                curr = curr // 5
        return min(ctr)

class Solution:
    def distributeCookies(self, cookies: List[int], k: int) -> int:
        n = len(cookies)
        s = [0] * (1 << n)
        dp = [[float('inf')] * (k + 1) for _ in range(1 << n)]
        dp[0][0] = 0
        for mask in range(1, 1 << n):
            for i in range(n):
                if mask & (1 << i):
                    s[mask] += cookies[i]
            for rem in range(1, k + 1):
                submask = mask
                while submask:
                    dp[mask][rem] = min(dp[mask][rem], max(s[submask], dp[mask ^ submask][rem - 1]))
                    submask = (submask - 1) & mask
        return dp[-1][k]

class Solution:
    def finalString(self, s: str) -> str:
        res = ""
        for c in s:
            if c == "i":
                res = res[::-1]
            else:
                res += c
        return res

class Solution:
    def fib(self, n: int) -> int:
        if n == 0:
            return 0
        a = 0
        b = 1
        for _ in range(n - 1):
            a, b = b, a + b
        return b

class Solution:
    def minHeightShelves(self, books: List[List[int]], shelfWidth: int) -> int:
        n = len(books)
        dp = [float('inf')] * (n + 1)
        dp[n] = 0
        for i in range(n - 1, -1, -1):
            s = 0
            mx = 0
            for j in range(i, n):
                s += books[j][0]
                mx = max(mx, books[j][1])
                if s > shelfWidth:
                    break
                dp[i] = min(dp[i], mx + dp[j + 1])
        return dp[0]

class Solution:
    def getFinalState(self, nums: List[int], k: int, multiplier: int) -> List[int]:
        for _ in range(k):
            nums[nums.index(min(nums))] *= multiplier
        return nums

class Solution:
    def finalPrices(self, prices: List[int]) -> List[int]:
        stack = []
        for i, el in enumerate(prices):
            while stack and el <= prices[stack[-1]]:
                prices[stack.pop()] -= el
            stack.append(i)
        return prices

class Solution:
    def finalValueAfterOperations(self, operations: List[str]) -> int:
        x = 0
        for o in operations:
            if o[1] == '+':
                x += 1
            if o[1] == '-':
                x -= 1
        return x

