class Solution:
    def getTargetCopy(self, original: TreeNode, cloned: TreeNode, target: TreeNode) -> TreeNode:
        nodes = [(original, cloned)]
        while len(nodes) > 0:
            og, cp = nodes.pop()
            if og and cp:
                if og == target:
                    return cp
                nodes.append((og.left, cp.left))
                nodes.append((og.right, cp.right))

class Solution:
    def goodSubsetofBinaryMatrix(self, grid: List[List[int]]) -> List[int]:
        m = len(grid)
        n = len(grid[0])
        if m == 1 and sum(grid[0]) == 0:
            return [0]
        pos = {}
        for i in range(m):
            for mask in range(1 << n):
                valid = True
                for j in range(n):
                    if mask & (1 << j) and grid[i][j] + 1 > 1:
                        valid = False
                        break
                if valid and mask in pos:
                    return [pos[mask], i]
            curr = 0
            for j in range(n):
                if grid[i][j] == 1:
                    curr |= 1 << j
            pos[curr] = i
        return []

class Solution:
    def findSafeWalk(self, grid: List[List[int]], health: int) -> bool:
        m = len(grid)
        n = len(grid[0])
        v = set()
        q = deque([(0, 0, health - grid[0][0])])
        while q:
            i, j, h = q.pop()
            if h > 0 and (i, j) == (m - 1, n - 1):
                return True
            if h <= 0:
                continue
            for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
                if 0 <= x < m and 0 <= y < n and (x, y, h - grid[x][y]) not in v:
                    v.add((x, y, h - grid[x][y]))
                    q.appendleft((x, y, h - grid[x][y]))
        return False

class SparseTable:
    def __init__(self, arr, func, init):
        self.func = func
        self.init = init
        n = len(arr)
        k = n.bit_length()
        table = [[self.init] * k for _ in range(n)]
        self.mpow = [(0, 1)] * (n + 1)
        l = 0
        p = 1
        for i in range(1, n + 1):
            if p * 2 <= i:
                l += 1
                p *= 2
            self.mpow[i] = (l, p)
        for l in range(k):
            for i in range(n):
                if l == 0:
                    table[i][l] = arr[i]
                else:
                    a = table[i][l - 1]
                    b = self.init
                    if i + (1 << l - 1) < n:
                        b = table[i + (1 << l - 1)][l - 1]
                    table[i][l] = self.func(a, b)
        self.table = table

    def query(self, l, r):
        i, p = self.mpow[r - l + 1]
        return self.func(self.table[l][i], self.table[r - p + 1][i])

class Solution:
    def closestToTarget(self, arr: List[int], target: int) -> int:
        n = len(arr)
        sp = SparseTable(arr, lambda x, y: x & y, (1 << 20) - 1)
        res = float('inf')
        for i in range(n):
            beg = i
            end = n - 1
            while beg <= end:
                mid = (beg + end) // 2
                curr = sp.query(i, mid)
                res = min(res, abs(curr - target))
                if curr < target:
                    end = mid - 1
                else:
                    beg = mid + 1
        return res

class Solution:
    def findAnagrams(self, s: str, p: str) -> List[int]:
        np = len(p)
        ns = len(s)
        op = []
        if np > ns:
            return op
        pctr = [0] * 26
        for c in p:
            pctr[ord(c) - ord('a')] += 1
        sctr = [0] * 26
        for i in range(np):
            sctr[ord(s[i]) - ord('a')] += 1
        i = 0
        while i < ns - np:
            if pctr == sctr:
                op.append(i)
            sctr[ord(s[i]) - ord('a')] -= 1
            sctr[ord(s[i + np]) - ord('a')] += 1
            i += 1
        if pctr == sctr:
            op.append(i)
        return op

class Solution:
    def findDuplicates(self, nums: List[int]) -> List[int]:
        exists = set()
        op = []
        for num in nums:
            if num in exists:
                op.append(num)
            else:
                exists.add(num)
        return op

class Solution:
    def goodIndices(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        dec = [1] * n
        inc = [1] * n
        for i in range(1, n):
            if nums[i] <= nums[i - 1]:
                dec[i] = dec[i - 1] + 1
        for i in range(n - 2, -1, -1):
            if nums[i] <= nums[i + 1]:
                inc[i] = inc[i + 1] + 1
        res = []
        for i in range(k, n - k):
            if dec[i - 1] >= k and inc[i + 1] >= k:
                res.append(i)
        return res

MOD = 10 ** 9 + 7

def count_strings_with_constraints(upper, sub):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    M = len(sub)
    N = len(upper)

    prefix = [0] * M
    for i in range(1, M):
        j = prefix[i - 1]
        while j > 0 and sub[j] != sub[i]:
            j = prefix[j - 1]
        if sub[j] == sub[i]:
            j += 1
        prefix[i] = j

    dp = [[[0] * 2 for _ in range(M)] for _ in range(N + 1)]
    dp[0][0][1] = 1

    for i in range(1, N + 1):
        for j in range(M):
            for t in range(2):
                if dp[i - 1][j][t] > 0:
                    limit = upper[i - 1] if t == 1 else 'z'
                    for c in alphabet:
                        if c > limit:
                            break

                        k = j
                        while k > 0 and sub[k] != c:
                            k = prefix[k - 1]
                        if sub[k] == c:
                            k += 1

                        if k < M:
                            dp[i][k][t and (c == limit)] = (dp[i][k][t and (c == limit)] + dp[i - 1][j][t]) % MOD

    return sum((dp[N][j][0] + dp[N][j][1]) % MOD for j in range(M)) % MOD

class Solution:
    def findGoodStrings(self, n: int, s1: str, s2: str, evil: str) -> int:
        return (count_strings_with_constraints(s2, evil) - count_strings_with_constraints(s1, evil) + int(evil not in s1)) % MOD

class Solution:
    def findFarmland(self, land: List[List[int]]) -> List[List[int]]:
        m = len(land)
        n = len(land[0])
        res = []
        for i in range(m):
            for j in range(n):
                if land[i][j] == 1:
                    if (i == 0 or land[i - 1][j] == 0) and (j == 0 or land[i][j - 1] == 0):
                        k, l = i, j
                        while k < m - 1 and land[k + 1][j] == 1:
                            k += 1
                        while l < n - 1 and land[i][l + 1] == 1:
                            l += 1
                        res.append([i, j, k, l])
        return res

class Solution:
    def findKDistantIndices(self, nums: List[int], key: int, k: int) -> List[int]:
        n = len(nums)
        indices = set()
        for i, el in enumerate(nums):
            if el == key:
                for j in range(max(i - k, 0), min(i + k + 1, n)):
                    indices.add(j)
        return sorted(indices)

from collections import Counter

class Solution:
    def findLonely(self, nums: List[int]) -> List[int]:
        numctr = Counter(nums)
        op = []
        for num in nums:
            if numctr[num] == 1 and num - 1 not in numctr and num + 1 not in numctr:
                op.append(num)
        return op

class Solution:
    def findDisappearedNumbers(self, nums: List[int]) -> List[int]:
        n = len(nums)
        ctr = set()
        for i in range(1, n + 1):
            ctr.add(i)
        for num in nums:
            if num in ctr:
                ctr.remove(num)
        return list(ctr)

from collections import defaultdict

class Solution:
    def getParent(self, parent, x):
        if parent[x] == x:
            return x
        parent[x] = self.getParent(parent, parent[x])
        return parent[x]

    def connect(self, parent, a, b):
        parent[self.getParent(parent, a)] = self.getParent(parent, b)

    def isConnected(self, parent, a, b):
        return self.getParent(parent, a) == self.getParent(parent, b)

    def findAllPeople(self, n: int, meetings: List[List[int]], firstPerson: int) -> List[int]:
        parent = list(range(n))
        meets = defaultdict(list)
        for a, b, t in meetings:
            meets[t].append((a, b))
        self.connect(parent, 0, firstPerson)
        people = set()
        for t in sorted(meets.keys()):
            people.clear()
            for a, b in meets[t]:
                self.connect(parent, a, b)
                people.update({a, b})
            for p in people:
                if not self.isConnected(parent, p, 0):
                    parent[p] = p
        return [i for i in range(n) if self.isConnected(parent, i, 0)]

class Solution:
    def topologicalSort(self, graph, node, visited, stack, pos):
        visited.add(node)
        for n in graph.get(node, []):
            if n not in visited:
                self.topologicalSort(graph, n, visited, stack, pos)
        if node in pos:
            stack.append(pos[node])

    def findAllRecipes(self, recipes: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        graph = {}
        supplies = set(supplies)
        n = len(recipes)
        for i in range(n):
            for item in ingredients[i]:
                graph[item] = graph.get(item, []) + [recipes[i]]
        pos = {}
        for i, item in enumerate(recipes):
            pos[item] = i
        stack = []
        visited = set()
        for node in graph:
            if node not in visited:
                self.topologicalSort(graph, node, visited, stack, pos)
        for i in stack[::-1]:
            valid = True
            for item in ingredients[i]:
                if item not in supplies:
                    valid = False
                    break
            if valid:
                supplies.add(recipes[i])
            else:
                recipes[i] = False
        return [r for r in recipes if r]

class Solution:
    def findReplaceString(self, s: str, indices: List[int], sources: List[str], targets: List[str]) -> str:
        n = len(indices)
        op = list(s)
        for i in range(n):
            if s[indices[i]:indices[i]+len(sources[i])] == sources[i]:
                op[indices[i]] = targets[i]
                for j in range(indices[i] + 1, indices[i] + len(sources[i])):
                    op[j] = ""
        return "".join(op)

class Solution:
    def keygen(self, s):
        smap = {}
        slist = []
        i = 0
        for c in s:
            if c not in smap:
                smap[c] = i
                i += 1
            slist.append(smap[c])
        return slist

    def findAndReplacePattern(self, words: List[str], pattern: str) -> List[str]:
        plist = self.keygen(pattern)
        return [w for w in words if self.keygen(w) == plist]

def compute_lps(pattern):
    length = 0
    lps = [0] * len(pattern)
    i = 1

    while i < len(pattern):
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1

    return lps

def find_pattern_indices(string, pattern):
    indices = []
    n = len(string)
    m = len(pattern)
    lps = compute_lps(pattern)
    i = j = 0

    while i < n:
        if string[i] == pattern[j]:
            i += 1
            j += 1

            if j == m:
                indices.append(i - j)
                j = lps[j - 1]
        else:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return indices

class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        n = len(s)
        x = find_pattern_indices(s, a)
        y = find_pattern_indices(s, b)
        val = [0] * (n + 1)
        for i in y:
            val[i] = 1
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] = p[i] + val[i]
        res = []
        for i in x:
            ctr = p[min(i + k + 1, n)] - p[max(i - k, 0)]
            if ctr > 0:
                res.append(i)
        return res

def find_pattern_indices(s, p):
    s = p + "#" + s
    n = len(s)
    Z = [0] * n
    l = r = 0
    for i in range(1, n):
        z = Z[i - l]
        if i + z >= r:
            z = max(r - i, 0)
            while i + z < n and s[z] == s[i + z]:
                z += 1
            l, r = i, i + z
        Z[i] = z
        if i > len(p) and z >= len(p):
            yield i - len(p) - 1

class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        n = len(s)
        x = find_pattern_indices(s, a)
        y = find_pattern_indices(s, b)
        val = [0] * (n + 1)
        for i in y:
            val[i] = 1
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] = p[i] + val[i]
        res = []
        for i in x:
            ctr = p[min(i + k + 1, n)] - p[max(i - k, 0)]
            if ctr > 0:
                res.append(i)
        return res

class Solution:
    def findBottomLeftValue(self, root) -> int:
        res = (-1, 0, 0)
        def inorder(r, d, w):
            nonlocal res
            if not r:
                return
            inorder(r.left, d + 1, 2 * w)
            res = max(res, (d, -w, r.val))
            inorder(r.right, d + 1, 2 * w + 1)
        inorder(root, 0, 0)
        return res[2]

class SparseTable:
    def __init__(self, arr, func, init):
        self.func = func
        self.init = init
        n = len(arr)
        k = n.bit_length()
        table = [[self.init] * k for _ in range(n)]
        self.mpow = [(0, 1)] * (n + 1)
        l = 0
        p = 1
        for i in range(1, n + 1):
            if p * 2 <= i:
                l += 1
                p *= 2
            self.mpow[i] = (l, p)
        for l in range(k):
            for i in range(n):
                if l == 0:
                    table[i][l] = arr[i]
                else:
                    a = table[i][l - 1]
                    b = self.init
                    if i + (1 << l - 1) < n:
                        b = table[i + (1 << l - 1)][l - 1]
                    table[i][l] = self.func(a, b)
        self.table = table

    def query(self, l, r):
        i, p = self.mpow[r - l + 1]
        return self.func(self.table[l][i], self.table[r - p + 1][i])

class Solution:
    def leftmostBuildingQueries(self, heights: List[int], queries: List[List[int]]) -> List[int]:
        n = len(heights)
        res = []
        sp = SparseTable(heights, lambda x, y: max(x, y), float('-inf'))
        for a, b in queries:
            a, b = min(a, b), max(a, b)
            if a == b:
                res.append(a)
                continue
            if heights[b] > heights[a]:
                res.append(b)
                continue
            val = max(heights[a], heights[b])
            pos = b
            beg = b + 1
            end = n - 1
            curr = n
            while beg <= end:
                mid = (beg + end) // 2
                if sp.query(pos, mid) > val:
                    curr = mid
                    end = mid - 1
                else:
                    beg = mid + 1
            if curr < n:
                res.append(curr)
            else:
                res.append(-1)
        return res

class Solution:
    def findCenter(self, edges: List[List[int]]) -> int:
        graph = {}
        for a, b in edges:
            if a in graph:
                graph[a][0] += 1
                graph[a][1] += 1
            else:
                graph[a] = [1, 1]
            if b in graph:
                graph[b][1] += 1
                graph[a][0] += 1
            else:
                graph[b] = [1, 1]
        k = len(graph) - 1
        for node in graph:
            if graph[node][1] == k:
                return node

class Solution:
    def findChampion(self, grid: List[List[int]]) -> int:
        n = len(grid)
        for i in range(n):
            curr = sum(grid[x][i] for x in range(n))
            if curr == 0:
                return i
        return -1

class Solution:
    def findChampion(self, n: int, edges: List[List[int]]) -> int:
        parent = list(range(n))
        def find(x):
            if parent[x] == x:
                return x
            parent[x] = find(parent[x])
            return parent[x]
        for a, b in edges:
            parent[b] = find(a)
        res = []
        for i in range(n):
            if find(i) == i:
                res.append(i)
        if len(res) > 1 or len(res) == 0:
            return -1
        return res[0]

from collections import deque

class Solution:
    def closestMeetingNode(self, edges: List[int], node1: int, node2: int) -> int:
        n = len(edges)
        res = []
        for beg in [node1, node2]:
            q = deque([(beg, 0)])
            v = {beg}
            dists = {}
            while len(q) > 0:
                curr, d = q.pop()
                dists[curr] = d
                if edges[curr] != -1 and edges[curr] not in v:
                    v.add(edges[curr])
                    q.appendleft((edges[curr], d + 1))
            res.append(dists)
        minnode = None
        mindist = float('inf')
        for i in range(n):
            currdist = max(res[0].get(i, float('inf')), res[1].get(i, float('inf')))
            if currdist < mindist:
                mindist = currdist
                minnode = i
            elif currdist == mindist:
                if minnode == None or i < minnode:
                    minnode = i
        if minnode == None or mindist == float('inf'):
            return -1
        return minnode

