class Solution:
    def findDuplicate(self, paths: List[str]) -> List[List[str]]:
        files = defaultdict(list)
        for file in paths:
            val = file.split()
            n = len(val)
            for i in range(1, n):
                file, content = re.search("(\S+)\((\S+)\)", val[i]).groups()
                files[content].append(f"{val[0]}/{file}")
        return [v for v in files.values() if len(v) > 1]

class FindElements:

    def __init__(self, root: Optional[TreeNode]):
        self.root = root
        self.exists = set()
        nodes = [(self.root, 0)]
        while len(nodes) > 0:
            curr, l = nodes.pop()
            if curr:
                self.exists.add(l)
                nodes.append((curr.left, 2 * l + 1))
                nodes.append((curr.right, 2 * l + 2))

    def find(self, target: int) -> bool:
        return target in self.exists

from collections import defaultdict, deque

class Solution:
    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:
        n = len(graph)
        g = defaultdict(set)
        indegree = [0] * n
        for i in range(n):
            for j in graph[i]:
                g[j].add(i)
                indegree[i] += 1
        q = deque()
        for i in range(n):
            if indegree[i] == 0:
                q.appendleft(i)
        res = []
        while len(q) > 0:
            curr = q.pop()
            res.append(curr)
            for j in g[curr]:
                indegree[j] -= 1
                if indegree[j] == 0:
                    q.appendleft(j)
        res.sort()
        return res

class Solution:
    def search(self, nums, target, cmp, ncmp):
        beg = 0
        end = len(nums)
        while beg <= end:
            mid = (beg + end) // 2
            if mid >= len(nums):
                break
            curr = nums[mid]
            prev = nums[mid - 1] if mid > 0 else curr - 1
            forw = nums[mid + 1] if mid < len(nums) - 1 else curr + 1
            if curr == target and cmp(prev, forw):
                return mid
            elif beg == end:
                break
            elif ncmp(curr):
                beg = mid + 1
            else:
                end = mid
        return -1

    def searchRange(self, nums: List[int], target: int) -> List[int]:
        return [
            self.search(nums, target, lambda p, f: p < target, lambda c: c < target),
            self.search(nums, target, lambda p, f: f > target, lambda c: c <= target)
        ]

class Solution:
    def firstPalindrome(self, words: List[str]) -> str:
