                return word
        return ""

class Solution:
    def goodDaysToRobBank(self, security: List[int], time: int) -> List[int]:
        n = len(security)
        mdec = [1] * n
        minc = [1] * n
        for i in range(1, n):
            if security[i] <= security[i - 1]:
                mdec[i] = 1 + mdec[i - 1]
        for i in range(n - 2, -1, -1):
            if security[i] <= security[i + 1]:
                minc[i] = 1 + minc[i + 1]
        res = []
        for i in range(time, n - time):
            if mdec[i] >= time + 1 and minc[i] >= time + 1:
                res.append(i)
        return res

class Solution:
    def gcd(self, a, b):
        if b == 0:
            return a
        else:
            return self.gcd(b, a % b)

    def findGCD(self, nums: List[int]) -> int:
        minNum = float('inf')
        maxNum = float('-inf')
        for num in nums:
            minNum = min(minNum, num)
            maxNum = max(maxNum, num)
        return self.gcd(minNum, maxNum)

class Solution:
    def canSortArray(self, nums: List[int]) -> bool:
        n = len(nums)
        prev = float('-inf')
        i = 0
        while i < n:
            ctr = 1
            while i < n - 1 and nums[i].bit_count() == nums[i + 1].bit_count():
                i += 1
                ctr += 1
            curr = nums[i - ctr + 1 : i + 1]
            if min(curr) < prev:
                return False
            prev = max(curr)
            i += 1
        return True

class Solution:
    def canAliceWin(self, nums: List[int]) -> bool:
        s = sum(nums)
        ss = 0
        for el in nums:
            if el < 10:
                ss += el
        return s - ss != ss

class Solution:
    def DFS(self, graph, i, dest, v):
        if i == dest:
            return True
        v.add(i)
        for j in graph[i]:
            if j not in v:
                if self.DFS(graph, j, dest, v):
                    return True
        return False

    def validPath(self, n: int, edges: List[List[int]], source: int, destination: int) -> bool:
        graph = [[] for _ in range(n)]
        for a, b in edges:
            graph[a].append(b)
            graph[b].append(a)
        v = set()
        return self.DFS(graph, source, destination, v)

