import bisect

class Solution:
    def findClosestElements(self, arr: List[int], k: int, x: int) -> List[int]:
        heap = []
        for num in arr:
            heapq.heappush(heap, (abs(x - num), num))
        kclosest = []
        for i in range(k):
            bisect.insort(kclosest, heapq.heappop(heap)[1])
        return kclosest

import heapq

class Solution:
    def kSmallestPairs(self, nums1: List[int], nums2: List[int], k: int) -> List[List[int]]:
        m = len(nums1)
        n = len(nums2)
        heap = [(nums1[0] + nums2[0], 0, 0)]
        res = []
        v = {(0, 0)}
        while len(heap) > 0 and k > 0:
            val, i, j = heapq.heappop(heap)
            res.append((nums1[i], nums2[j]))
            k -= 1
            for x, y in [(i + 1, j), (i, j + 1)]:
                if x < m and y < n:
                    if (x, y) not in v:
                        v.add((x, y))
                        heapq.heappush(heap, (nums1[x] + nums2[y], x, y))
        return res

class Solution:
    def possible(self, nums, m, k):
        n = len(nums)
        res = 0
        i = 0
        for j in range(n):
            while nums[j] - nums[i] > m:
                i += 1
            res += j - i
        return res >= k

    def smallestDistancePair(self, nums: List[int], k: int) -> int:
        nums.sort()
        beg = 0
        end = nums[-1] - nums[0]
        res = -1
        while beg <= end:
            mid = (beg + end) // 2
            if self.possible(nums, mid, k):
                res = mid
                end = mid - 1
            else:
                beg = mid + 1
        return res

class Solution:
    def findKthBit(self, n: int, k: int) -> str:
        inv = lambda x: str(1 - int(x))
        def find(k, n):
            if n == 1:
                return "0"
            x = 1
            for _ in range(n - 2):
                x = 2 * x + 1
            if k == x + 1:
                return "1"
            if k > x + 1:
                return inv(find(2 * x + 2 - k, n - 1))
            return find(k, n - 1)
        return find(k, n)

class Solution:
    def largestValues(self, root: Optional[TreeNode]) -> List[int]:
        mvals = {}
        nodes = [(root, 0)]
        mlevel = -1
        while len(nodes) > 0:
            curr, l = nodes.pop()
            if curr:
                mlevel = max(mlevel, l)
                mvals[l] = max(mvals.get(l, float('-inf')), curr.val)
                nodes.append((curr.left, l + 1))
                nodes.append((curr.right, l + 1))
        return [mvals[l] for l in range(mlevel + 1)]

