class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)
        v = [0] * n
        for i in targetIndices:
            v[i] = 1
        dp = [float('-inf')] * (m + 1)
        ndp = [float('-inf')] * (m + 1)
        dp[m] = 0
        for i in range(n - 1, -1, -1):
            for j in range(m + 1):
                if j < m and source[i] == pattern[j]:
                    ndp[j] = dp[j + 1]
                ndp[j] = max(ndp[j], v[i] + dp[j])
            dp, ndp = ndp, dp
        return dp[0]

import heapq

class MedianFinder:
    def __init__(self):
        self.l = []
        self.r = []

    def balance(self):
        while len(self.r) > len(self.l):
            heapq.heappush(self.l, -heapq.heappop(self.r))
        while len(self.l) - len(self.r) > 1:
            heapq.heappush(self.r, -heapq.heappop(self.l))

    def addNum(self, num: int) -> None:
        if self.l and num > -self.l[0]:
            heapq.heappush(self.r, num)
        else:
            heapq.heappush(self.l, -num)
        self.balance()

    def findMedian(self) -> float:
        if len(self.l) > len(self.r):
            return -self.l[0]
        if len(self.l) + len(self.r) == 1:
            return -self.l[0]
        return (-self.l[0] + self.r[0]) / 2

class Solution:
    def minCost(self, nums):
        n = len(nums)
        if n <= 2:
            return max(nums)
        dp = [[float('inf')] * (n + 2) for _ in range(n)]
        for i in range(n):
            dp[i][n] = nums[i]
            dp[i][n+1] = nums[i]
        for i in range(n-1):
            dp[i][n-1] = max(nums[i], nums[n-1])
        for j in range(n-2, 0, -1):
            for i in range(j):
                op1 = max(nums[i], nums[j]) + dp[j+1][j+2]
                op2 = max(nums[i], nums[j+1]) + dp[j][j+2]
                op3 = max(nums[j], nums[j+1]) + dp[i][j+2]
                dp[i][j] = min(op1, op2, op3)
        op1 = max(nums[0], nums[1]) + dp[2][3]
        op2 = max(nums[0], nums[2]) + dp[1][3]
        op3 = max(nums[1], nums[2]) + dp[0][3]
        return min(op1, op2, op3)

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.diameters = [(i, i) for i in range(n)]
        self.size = [1] * n

    def find(self, a):
        if a == self.parent[a]:
            return a
        self.parent[a] = self.find(self.parent[a])
        return self.parent[a]

    def union(self, a, b):
        parent_a = self.find(a)
        parent_b = self.find(b)
        if parent_a != parent_b:
            if self.size[parent_a] < self.size[parent_b]:
                parent_a, parent_b = parent_b, parent_a
            self.parent[parent_b] = parent_a
            self.size[parent_a] += self.size[parent_b]

class Solution:
    def diameter(self, edges):
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        depth = [0] * n
        LOG = 18
        p = [[i] * LOG for i in range(n)]
        stack = [(0, -1, 0)]
        while stack:
            i, pr, d = stack.pop()
            depth[i] = d
            for j in graph[i]:
                if j != pr:
                    p[j][0] = i
                    stack.append((j, i, d + 1)) 
        for l in range(1, LOG):
            for i in range(n):
                p[i][l] = p[p[i][l - 1]][l - 1]
        dsu = DSU(n)
        ldiameter = 0    
        def addEdge(u, v):
            nonlocal ldiameter
            l = max(dsu.diameters[dsu.find(u)], key = lambda x: getDist(u, x))
            r = max(dsu.diameters[dsu.find(v)], key = lambda x: getDist(v, x))
            first, last = max([(l, r), dsu.diameters[dsu.find(u)], dsu.diameters[dsu.find(v)]], key = lambda e: getDist(e[0], e[1]))
            dsu.union(u, v)
            dsu.diameters[dsu.find(u)] = (first, last)
            ldiameter = max(ldiameter, getDist(first, last))   
        def getDist(u, v):
            res = depth[u] + depth[v]
            if depth[u] > depth[v]:
                u, v = v, u
            diff = depth[v] - depth[u]
            jump = 0
            while diff:
                if diff & 1:
                    v = p[v][jump]
                jump += 1
                diff //= 2
            for jump in range(LOG - 1, -1, -1):
                if p[u][jump] != p[v][jump]:
                    u = p[u][jump]
                    v = p[v][jump]
            LCA = p[u][0] if u != v else u
            res -= 2 * depth[LCA]
            return res
        for u, v in edges:
            addEdge(u, v)
        return ldiameter

    def minimumDiameterAfterMerge(self, edges1: List[List[int]], edges2: List[List[int]]) -> int:
        a = self.diameter(edges1)
        b = self.diameter(edges2)
        return max(a, b, (a + 1) // 2 + (b + 1) // 2 + 1)

class Solution:
    def findMin(self, nums: List[int]) -> int:
        n = len(nums)
        beg = 0
        end = n
        while beg <= end:
            mid = (beg + end) // 2
            if mid < n - 1 and nums[mid] > nums[mid + 1]:
                return nums[mid + 1]
            if beg >= end - 1:
                return nums[0]
            elif nums[mid] > nums[0]:
                beg = mid
            else:
                end = mid

class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        res = 0
        for el in nums:
            res += min((el % 3), 3 - (el % 3))
        return res

import heapq

class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        m = len(moveTime)
        n = len(moveTime[0])
        dist = [[float('inf')] * n for _ in range(m)]
        dist[0][0] = 0
        heap = [(0, 0, 0, True)]
        while heap:
            d, i, j, even = heapq.heappop(heap)
            if (i, j) == (m - 1, n - 1):
                return d
            cost = 1
            for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
                if 0 <= x < m and 0 <= y < n and max(d, moveTime[x][y]) + cost < dist[x][y]:
                    dist[x][y] = max(d, moveTime[x][y]) + cost
                    heapq.heappush(heap, (dist[x][y], x, y, not even))

import heapq

class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        m = len(moveTime)
        n = len(moveTime[0])
        dist = [[float('inf')] * n for _ in range(m)]
        dist[0][0] = 0
        heap = [(0, 0, 0, True)]
        while heap:
            d, i, j, even = heapq.heappop(heap)
            if (i, j) == (m - 1, n - 1):
                return d
            cost = 1 if even else 2
            for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
                if 0 <= x < m and 0 <= y < n and max(d, moveTime[x][y]) + cost < dist[x][y]:
                    dist[x][y] = max(d, moveTime[x][y]) + cost
                    heapq.heappush(heap, (dist[x][y], x, y, not even))

class Solution:
    def findMissingAndRepeatedValues(self, grid):
        n = len(grid)
        ctr = [0] * (n * n + 1)

        for row in grid:
            for num in row:
                ctr[num] += 1

        a = b = -1
        for i in range(1, n * n + 1):
            if ctr[i] == 2:
                a = i
            elif ctr[i] == 0:
                b = i

        return [a, b]

class Solution:
    def missingRolls(self, rolls: List[int], mean: int, n: int) -> List[int]:
        m = len(rolls)
        total = mean * (m + n)
        rem = total - sum(rolls)
        res = [rem // n] * n
        k = rem % n
        for i in range(k):
            res[i] += 1
        if max(res) > 6 or min(res) < 1:
            return []
        return res

class Solution:
    def inorder(self, root, ctr):
        if root:
            self.inorder(root.left, ctr)
            ctr[root.val] = ctr.get(root.val, 0) + 1
            self.inorder(root.right, ctr)

    def findMode(self, root: Optional[TreeNode]) -> List[int]:
        ctr = {}
        self.inorder(root, ctr)
        maxVal = max(ctr.values())
        return [k for k, v in ctr.items() if v == maxVal]

class Solution:
    def sumZero(self, n: int) -> List[int]:
        if n == 1:
            return [0]
        if n == 2:
            return [-1, 1]
        prev = self.sumZero(n - 2)
        return [prev[0] - 1] + prev + [prev[-1] + 1]

class Solution:
    def nearestValidPoint(self, x: int, y: int, points: List[List[int]]) -> int:
        n = len(points)
        vals = [i for i in range(n) if points[i][0] == x or points[i][1] == y]
        if len(vals) == 0:
            return -1
        return min(vals, key = lambda j: abs(points[j][0] - x) + abs(points[j][1] - y))

cache = {}

class Solution:
    def waysToReachStair(self, k: int) -> int:
        def count(i, k, jump, lused):
            if i >= k + 2:
                return 0
            key = (k - i, jump, lused)
            if key in cache:
                return cache[key]
            res = int(i == k)
            if i > 0 and not lused:
                res += count(i - 1, k, jump, True)
            res += count(i + pow(2, jump), k, jump + 1, False)
            cache[key] = res
            return res
        return count(1, k, 0, False)

