from collections import Counter

class Solution:
    def findOriginalArray(self, changed: List[int]) -> List[int]:
        n = len(changed)
        ctr = Counter(changed)
        res = []
        changed.sort()
        for el in changed:
            if el != 0 and ctr[el] > 0 and ctr[2 * el] > 0:
                res.append(el)
                ctr[el] -= 1
                ctr[2 * el] -= 1
        res.extend([0] * (ctr[0] // 2))
        if 2 * len(res) != n:
            return []
        return res

class Solution:
    def kthPalindrome(self, queries: List[int], intLength: int) -> List[int]:
        ogLength = intLength
        isOdd = intLength & 1
        if isOdd:
            intLength += 1
        k = intLength // 2
        k = 10 ** (k - 1)
        op = []
        for q in queries:
            pal = str(k + q - 1)
            if isOdd:
                pal += pal[::-1][1:]
            else:
                pal += pal[::-1]
            if len(pal) == ogLength:
                op.append(int(pal))
            else:
                op.append(-1)
        return op

class Solution:
    def findPeakElement(self, nums: List[int]) -> int:
        n = len(nums)
        for i in range(n):
            left = nums[i] > nums[i - 1] if i > 0 else True
            right = nums[i] > nums[i + 1] if i < n - 1 else True
            if left and right:
                return i

class Solution:
    def pivotIndex(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0
        total = sum(nums)
        curr = 0
        if curr * 2 == total - nums[0]:
            return 0
        for i in range(n - 1):
            curr += nums[i]
            if curr * 2 == total - nums[i + 1]:
                return i + 1
        return -1

from collections import defaultdict

class Solution:
    def findWinners(self, matches: List[List[int]]) -> List[List[int]]:
        played = defaultdict(int)
        won = defaultdict(int)
        for winner, loser in matches:
            won[winner] += 1
            played[winner] += 1
            played[loser] += 1
        answer = [[], []]
        for player in sorted(played):
            lost = played[player] - won[player]
            if lost == 0:
                answer[0].append(player)
            elif lost == 1:
                answer[1].append(player)
        return answer

class Solution:
    def largestPerimeter(self, nums: List[int]) -> int:
        nums.sort()
        s = c = 0
        res = -1
        for el in nums:
            if c >= 2 and s > el:
                res = max(res, s + el)
            s += el
            c += 1
        return res

"""
   This is the custom function interface.
   You should not implement it, or speculate about its implementation
   class CustomFunction:
       # Returns f(x, y) for any given positive integers x and y.
       # Note that f(x, y) is increasing with respect to both x and y.
       # i.e. f(x, y) < f(x + 1, y), f(x, y) < f(x, y + 1)
       def f(self, x, y):

"""

class Solution:
    def findSolution(self, customfunction: 'CustomFunction', z: int) -> List[List[int]]:
        op = []
        for x in range(1, 1001):
            beg = 1
            end = 1000
            while beg <= end:
                y = (beg + end) // 2
                val =  customfunction.f(x, y)
                if val == z:
                    op.append([x, y])
                    break
                elif beg == end:
                    break
                elif val > z:
                    end = y
                else:
                    beg = y + 1
        return op

def getcount(n, k):
    n += 1
    res = (n >> (k + 1)) << k
    if (n >> k) & 1:
        res += n & ((1 << k) - 1)
    return res

def gettotal(n):
    res = 0
    for b in range(60):
        res += getcount(n, b)
    return res

class Solution:
    def findProductsOfElements(self, queries: List[List[int]]) -> List[int]:
        res = []
        for f, t, mod in queries:
            beg = 1
            end = 10 ** 15
            l = r = 0
            while beg <= end:
                mid = (beg + end) // 2
                if gettotal(mid - 1) >= f:
                    l = mid
                    end = mid - 1
                else:
                    beg = mid + 1
            beg = 1
            end = 10 ** 15
            while beg <= end:
                mid = (beg + end) // 2
                if gettotal(mid) - 1 <= t:
                    r = mid
                    beg = mid + 1
                else:
                    end = mid - 1
            s = 0
            for b in range(60):
                if l > r:
                    continue
                s += b * (getcount(r, b) - getcount(l - 1, b))
            curr = pow(2, s, mod)
            val = l - 1
            pos = gettotal(val - 1)
            pw = 1
            while val:
                if val & 1:
                    if f <= pos <= t:
                        curr *= pw
                        curr %= mod
                    pos += 1
                pw *= 2
                val //= 2
            if r + 1 != l - 1:
                val = r + 1
                pos = gettotal(val - 1)
                pw = 1
                while val:
                    if val & 1:
                        if f <= pos <= t:
                            curr *= pw
                            curr %= mod
                        pos += 1
                    pw *= 2
                    val //= 2
            res.append(curr)
        return res

class Solution:
    def removeAnagrams(self, words: List[str]) -> List[str]:
        stack = []
