import heapq

class Solution:
    def shortestPathWithHops(self, n: int, edges: List[List[int]], s: int, d: int, k: int) -> int:
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))
        dist = defaultdict(lambda: float('inf'))
        dist[(s, k)] = 0
        heap = [(0, s, k)]
        while heap:
            dt, i, rem = heapq.heappop(heap)
            if i == d:
                return dt
            for j, w in graph[i]:
                if dist[(j, rem)] > dt + w:
                    dist[(j, rem)] = dt + w
                    heapq.heappush(heap, (dist[(j, rem)], j, rem))
                if rem == 0:
                    continue
                if dist[(j, rem - 1)] > dt:
                    dist[(j, rem - 1)] = dt
                    heapq.heappush(heap, (dist[(j, rem - 1)], j, rem - 1))

class Solution:
    def nextGreatestLetter(self, letters: List[str], target: str) -> str:
        n = len(letters)
        beg = 0
        end = n - 1
        res = letters[0]
        while beg <= end:
            mid = (beg + end) // 2
            if letters[mid] > target:
                res = letters[mid]
                end = mid - 1
            else:
                beg = mid + 1
        return res

class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        i = 0
        while i < n:
            ctr = 1
            while i < n - 1 and s[i] == s[i + 1]:
                i += 1
                ctr += 1
            if ctr == k:
                return True
            i += 1
        return False

class Solution:
    def minimumDifference(self, nums: List[int], k: int) -> int:
        res = float('inf')
        last = [-1] * 32
        for i, el in enumerate(nums):
            for b in range(32):
                if not el & (1 << b):
                    last[b] = i
            ands = el
            res = min(res, abs(k - ands))
            for i in sorted(last, reverse = True):
                if i >= 0:
                    ands &= nums[i]
                    res = min(res, abs(k - ands))
        return res

class Solution:
    def findSubarrays(self, nums: List[int]) -> bool:
        n = len(nums)
        exists = set()
        for i in range(n - 1):
            curr = nums[i] + nums[i + 1]
            if curr in exists:
                return True
            else:
                exists.add(curr)
        return False

