class Solution:
    def maxSubsequence(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        heap = []
        for i in range(n):
            heapq.heappush(heap, (nums[i], i))
            if len(heap) > k:
                heapq.heappop(heap)
        heap.sort(key = lambda x: x[1])
        return [h[0] for h in heap]

class Solution:
    def subStrHash(self, s: str, power: int, modulo: int, k: int, hashValue: int) -> str:
        n = len(s)
        val = lambda c: ord(c) - ord('a') + 1
        p = 1
        powers = []
        for _ in range(k):
            powers.append(p)
            p = (p * power) % modulo
        curr = 0
        for i in range(k):
            curr = (curr + val(s[n - k + i]) * powers[i]) % modulo
        res = None
        for i in range(n - k - 1, -1, -1):
            if curr == hashValue:
                res = s[i + 1 : i + k + 1]
            curr = (power * (curr + modulo - (val(s[i + k]) * powers[k - 1]) % modulo) + val(s[i])) % modulo
        if curr == hashValue:
            res = s[:k]
        return res

from collections import defaultdict

class Solution:
    def findSubtreeSizes(self, parent: List[int], s: str) -> List[int]:
        n = len(s)
        res = [0] * n
        graph = [[] for _ in range(n)]
        newgraph = [[] for _ in range(n)]
        for i in range(1, n):
            graph[parent[i]].append(i)
        depths = defaultdict(list)
        def dfs(i, d, p):
            if len(depths[s[i]]) > 0:
                newgraph[depths[s[i]][-1]].append(i)
            elif p != -1:
                newgraph[p].append(i)
            depths[s[i]].append(i)
            for j in graph[i]:
                dfs(j, d + 1, i)
            depths[s[i]].pop()
        dfs(0, 0, -1)
        def sdfs(i):
            res[i] += 1
            for j in newgraph[i]:
                sdfs(j)
                res[i] += res[j]
        sdfs(0)
        return res

class Solution:
