class Solution:
    def numberOfChild(self, n: int, k: int) -> int:
        k %= 2 * (n - 1)
        if k <= n - 1:
            return k
        return 2 * (n - 1) - k

class Solution:
    def findTheCity(self, n: int, edges: List[List[int]], distanceThreshold: int) -> int:
        dist = [[float('inf') for i in range(n)] for j in range(n)]
        for i in range(n):
            dist[i][i] = 0
        for i, j, d in edges:
            dist[i][j] = d
            dist[j][i] = d
        for k in range(n):
            for i in range(n):
                for j in range(n):
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]
        res = (float('inf'), 0)
        for i in range(n):
            curr = len([d for d in dist[i] if d <= distanceThreshold])
            res = min(res, (curr, -i))
        return -res[1]

class Solution:
    def nearestPalindromic(self, n: str) -> str:
        if n == '9' * len(n) and n != '9':
            return '1' + ('0' * (len(n) - 1)) + '1'
        if n == '1' + '0' * (len(n) - 1) and len(n) > 1:
            return '9' * (len(n) - 1)
        if n == '11':
            return '9'
        res = (float('inf'), float('inf'))
        nval = int(n)
        if len(n) > 2:
            val = int('9' * (len(n) - 1))
            res = min(res, (abs(val - nval), val))
        if len(n) % 2 == 0:
            k = len(n) // 2 - 1
            for x in range(10):
                val = int(n[:k] + str(x) * 2 + n[:k][::-1])
                if val != nval:
                    res = min(res, (abs(val - nval), val))
            if len(n) >= 4:
                k = len(n) // 2 - 2
                for x in range(10, 100):
                    val = int(n[:k] + str(x) + str(x)[::-1] + n[:k][::-1])
                    if val != nval:
                        res = min(res, (abs(val - nval), val))
            return str(res[1])
        k = len(n) // 2
        for x in range(10):
            val = int(n[:k] + str(x) + n[:k][::-1])
            if val != nval:
                res = min(res, (abs(val - nval), val))
        return str(res[1])

class Solution:
    def countGoodIntegers(self, n: int, k: int) -> int:
        if n == 1:
            return len([i for i in range(1, 10) if i % k == 0])
        vals = set()
        res = 0
        for i in range(1, pow(10, n // 2)):
            i = str(i)
            pals = [int(i + i[::-1])]
            for d in range(10):
                pals.append(int(i + str(d) + i[::-1]))
            for val in pals:
                if len(str(val)) == n and val % k == 0:
                    ctr = [0] * 10
                    for _ in range(n):
                        ctr[val % 10] += 1
                        val //= 10
                    vals.add(tuple(ctr))
        f = [1] * (n + 1)
        for i in range(1, n + 1):
            f[i] = i * f[i - 1]
        for val in vals:
            curr = f[n]
            for c in val:
                curr //= f[c]
            if val[0] > 0:
                sub = f[n - 1]
                for i in range(10):
                    sub //= (f[val[i]] if i > 0 else f[val[i] - 1])
                curr -= sub
            res += curr
        return res

import bisect

MAX = 100001

primes = [True] * MAX
primes[0] = primes[1] = False
i = 0
while i * i <= MAX:
    if primes[i]:
        mul = 2
        while i * mul < MAX:
            primes[i * mul] = False
            mul += 1
    i += 1

vals = [i * i for i in range(2, MAX) if primes[i]]

class Solution:
    def nonSpecialCount(self, l: int, r: int) -> int:
        return r - l + 1 - bisect.bisect_right(vals, r) + bisect.bisect_left(vals, l)

class Solution:
    def findDifference(self, nums1: List[int], nums2: List[int]) -> List[List[int]]:
        nums1 = set(nums1)
        nums2 = set(nums2)
        return [list(nums1 - nums2), list(nums2 - nums1)]

class Solution:
    def findTheDifference(self, s: str, t: str) -> str:
        ctr = {}
        for c in t:
            ctr[c] = ctr.get(c, 0) + 1
        for c in s:
            ctr[c] -= 1
            if ctr[c] == 0:
                del ctr[c]
        return list(ctr)[0]

class Solution:
    def findTheDistanceValue(self, arr1: List[int], arr2: List[int], d: int) -> int:
        ctr = 0
        for i in arr1:
            found = False
            for j in arr2:
                if abs(i - j) <= d:
                    found = True
                    break
            if not found:
                ctr += 1
        return ctr

from collections import Counter

class Solution:
    def distinctDifferenceArray(self, nums: List[int]) -> List[int]:
        n = len(nums)
        total = Counter(nums)
        curr = Counter()
        res = [0] * n
        for i in range(n):
            curr[nums[i]] += 1
            l = r = 0
            for el in total:
                if total[el] - curr[el] > 0:
                    r += 1
                if curr[el] > 0:
                    l += 1
            res[i] = l - r
        return res

class Solution:
    def divisibilityArray(self, word: str, m: int) -> List[int]:
        res = []
        x = 0
        for c in word:
            x = 10 * x + int(c)
            x %= m
            res.append(int(x == 0))
        return res

class Solution:
    def findDuplicate(self, nums: List[int]) -> int:
        n = len(nums)
        slow = nums[0]
        fast = nums[0]
        while True:
            slow = nums[slow]
            fast = nums[fast]
            fast = nums[fast]
            if slow == fast:
                slow = nums[0]
                while slow != fast:
                    slow = nums[slow]
                    fast = nums[fast]
                return slow

class Solution:
    def getEncryptedString(self, s: str, k: int) -> str:
        return "".join(s[(i + k) % len(s)] for i in range(len(s)))

class Solution:
    def resultGrid(self, image: List[List[int]], threshold: int) -> List[List[int]]:
        m = len(image)
        n = len(image[0])
        averages = {}
        groups = {}
        for i in range(m - 2):
            for j in range(n - 2):
                valid = True
                s = 0
                for x in range(3):
                    for y in range(3):
                        s += image[i + x][j + y]
                        if x > 0 and abs(image[i + x - 1][j + y] - image[i + x][j + y]) > threshold:
                            valid = False
                            break
                        if y > 0 and abs(image[i + x][j + y - 1] - image[i + x][j + y]) > threshold:
                            valid = False
                            break
                    if not valid:
                        break
                if valid:
                    for x in range(3):
                        for y in range(3):
                            if (i + x, j + y) not in groups:
                                groups[(i + x, j + y)] = []
                            groups[(i + x, j + y)].append(s // 9)
        for i in range(m):
            for j in range(n):
                if (i, j) in groups:
                    image[i][j] = sum(groups[(i, j)]) // len(groups[(i, j)])
        return image

class Solution:
    def largestAltitude(self, gain: List[int]) -> int:
        maxval = 0
        curr = 0
        for g in gain:
            curr += g
            maxval = max(maxval, curr)
        return maxval

class Solution:
    def strStr(self, haystack: str, needle: str) -> int:
        s = needle + "#" + haystack
        n = len(s)
        Z = [0] * n
        l = r = 0
        for i in range(1, n):
            z = Z[i - l]
            if i + z >= r:
                z = max(r - i, 0)
                while i + z < n and s[z] == s[i + z]:
                    z += 1
                l, r = i, i + z
            Z[i] = z
            if i > len(needle) and z >= len(needle):
                return i - len(needle) - 1
        return -1

class Solution:
    def addedInteger(self, nums1: List[int], nums2: List[int]) -> int:
        nums2.sort()
        nums1.sort()
        return nums2[0] - nums1[0]

class Solution:
    def minimumAddedInteger(self, nums1: List[int], nums2: List[int]) -> int:
        nums2.sort()
        n = len(nums1)
        res = float('inf')
        for i in range(n):
            for j in range(i + 1, n):
                curr = [nums1[k] for k in range(n) if k != i and k != j]
                curr.sort()
                valid = True
                for k in range(n - 2):
                    if curr[k] - nums2[k] != curr[0] - nums2[0]:
                        valid = False
                        break
                if valid:
                    res = min(res, nums2[0] - curr[0])
        return res

class Solution:
    def divisorSubstrings(self, num: int, k: int) -> int:
        strnum = str(num)
        n = len(strnum)
        ctr = 0
        for i in range(n - k + 1):
            curr = int(strnum[i:i+k])
            if curr != 0 and num % curr == 0:
                ctr += 1
        return ctr

class Solution:
    def findKOr(self, nums: List[int], k: int) -> int:
        ctr = [0] * 32
        for el in nums:
            for b in range(32):
                if el & (1 << b):
                    ctr[b] += 1
        return sum(1 << b for b in range(32) if ctr[b] >= k)

class Solution:
    def kthCharacter(self, k: int) -> str:
        s = "a"
        def nxt(c):
            c = ord(c) - ord('a')
            c += 1
            c %= 26
            return chr(ord('a') + c)
        while len(s) < k:
            s += "".join(nxt(c) for c in s)
        return s[k-1]

class Solution:
    def kthCharacter(self, k: int, operations: List[int]) -> str:
        n = len(operations)
        def nxt(c):
            c = ord(c) - ord('a')
            c += 1
            c %= 26
            return chr(ord('a') + c)
        def get(k, i):
            if i == 0:
                return "a"
            elif k <= pow(2, i - 1):
                return get(k, i - 1)
            elif operations[i - 1] == 0:
                return get(k - pow(2, i - 1), i - 1)
            return nxt(get(k - pow(2, i - 1), i - 1))
        return get(k, n)

class Solution:
    def kthLuckyNumber(self, k: int) -> str:
        l = 1
        while k > pow(2, l):
            k -= pow(2, l)
            l += 1
        return "".join("4" if c == "0" else "7" for c in ('{:0' + str(l) + 'b}').format(k - 1))

import heapq

class Solution:
    def kthLargestNumber(self, nums: List[str], k: int) -> str:
        heap = []
        for num in nums:
            heapq.heappush(heap, int(num))
            if len(heap) > k:
                heapq.heappop(heap)
        return str(heap[0])

import heapq

class Solution:
    def kthSmallest(self, mat: List[List[int]], k: int) -> int:
        m = len(mat)
        n = len(mat[0])
        pos = [0] * m
        s = 0
        for i in range(m):
            s += mat[i][pos[0]]
        v = {tuple(pos)}
        heap = [(s, pos)]
        rem = k
        while heap:
            s, pos = heapq.heappop(heap)
            rem -= 1
            if rem == 0:
                return s
            for i in range(m):
                if pos[i] + 1 < n:
                    newpos = pos[:]
                    newpos[i] += 1
                    news = s - mat[i][pos[i]] + mat[i][pos[i] + 1]
                    if tuple(newpos) not in v:
                        v.add(tuple(newpos))
                        heapq.heappush(heap, (news, newpos))

class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        res = -1
        for el in set(nums):
            ctr = 0
            for i in range(n - k + 1):
                if el in nums[i:i+k]:
                    ctr += 1
            if ctr == 1:
                res = max(res, el)
        return res

class Solution:
    def BFS(self, graph, i):
        q = deque([(i, 0)])
        dist = {}
        dist[i] = 0
        while len(q) > 0:
            curr, d = q.pop()
            for j in graph[curr]:
                if dist.get(j, float('inf')) > d + 1:
                    dist[j] = d + 1
                    q.appendleft((j, d + 1))
        res = max(dist.keys(), key = lambda i: dist[i])
        return (res, dist)

    def lastMarkedNodes(self, edges: List[List[int]]) -> List[int]:
        n = 1 + len(edges)
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        x, dx = self.BFS(graph, 0)
        y, dy = self.BFS(graph, x)
        z, dz = self.BFS(graph, y)
        return [max([(x, dy), (y, dz)], key = lambda p: p[1][i])[0] for i in range(n)]

class Solution:
    def longestCommonPrefix(self, arr1: List[int], arr2: List[int]) -> int:
        res = 0
        pref = set()
        for el in arr1:
            s = str(el)
            for i in range(1, len(s) + 1):
                pref.add(s[:i])
        for el in arr2:
            s = str(el)
            for i in range(res, len(s) + 1):
                if s[:i] in pref:
                    res = i
        return res

from collections import deque

class Solution:
    def minimumLevel(self, root: Optional[TreeNode]) -> int:
        res = []
        q = deque([root])
        while q:
            n = len(q)
            s = 0
            for _ in range(n):
                r = q.pop()
                if not r:
                    continue
                s += r.val
                if r.left:
                    q.appendleft(r.left)
                if r.right:
                    q.appendleft(r.right)
            res.append(s)
        return res.index(min(res)) + 1

class Solution:
    def findTheLongestBalancedSubstring(self, s: str) -> int:
        n = len(s)
        res = 0
        vals = []
        i = 0
        while i < n:
            ctr = 1
            while i < n - 1 and s[i] == s[i + 1]:
                ctr += 1
                i += 1
            vals.append((s[i], ctr))
            i += 1
        for i in range(len(vals) - 1):
            if vals[i][0] == '0' and vals[i + 1][0] == '1':
                res = max(res, 2 * min(vals[i][1], vals[i + 1][1]))
        return res

from collections import defaultdict

class Solution:
    def longestEqualSubarray(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pos = defaultdict(list)
        for i in range(n):
            pos[nums[i]].append(i)
        res = 1
        for el in pos:
            curr = pos[el]
            m = len(curr)
            i = 0
            dels = 0
            for j in range(m - 1):
                dels += curr[j + 1] - curr[j] - 1
                while i <= j and dels > k:
                    dels -= curr[i + 1] - curr[i] - 1
                    i += 1
                if dels <= k:
                    res = max(res, j - i + 2)
        return res

class Solution:
    def findTheLongestSubstring(self, s: str) -> int:
        n = len(s)
        pos = {}
        res = 0
        p = 0
        pos[p] = 0
        for i in range(n):
            if s[i] in "aeiou":
                p ^= 1 << "aeiou".index(s[i])
            if p not in pos:
                pos[p] = i + 1
            else:
                res = max(res, i + 1 - pos[p])
        return res

import bisect

class Solution:
    def longestObstacleCourseAtEachPosition(self, obstacles: List[int]) -> List[int]:
        res = []
        b = []
        for i, el in enumerate(obstacles):
            x = bisect.bisect_left(b, (el, i))
            if x < len(b):
                b[x] = (el, i)
            else:
                b.append((el, i))
            res.append(x + 1)
        return res

class Solution:
    def circularGameLosers(self, n: int, k: int) -> List[int]:
        used = [False] * n
        i = 0
        s = k
        while True:
            if used[i]:
                break
            used[i] = True
            i = (i + s) % n
            s += k
        return [i + 1 for i in range(n) if not used[i]]

class Solution:
    def theMaximumAchievableX(self, num: int, t: int) -> int:
        return num + 2 * t

class Solution:
    def maxDivScore(self, nums: List[int], divisors: List[int]) -> int:
        res = (float('inf'), -1)
        for d in divisors:
            ctr = 0
            for el in nums:
                if el % d == 0:
                    ctr += 1
            res = min(res, (-ctr, d))
        return res[1]

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        n = len(nums)
        pfg = [0] * (n + 1)
        sfg = [0] * (n + 1)
        pfl = [1] * (n + 1)
        sfl = [1] * (n + 1)
        for i in range(n):
            pfg[i + 1] = gcd(pfg[i], nums[i])
            pfl[i + 1] = lcm(pfl[i], nums[i])
            sfg[i + 1] = gcd(sfg[i], nums[n - i - 1])
            sfl[i + 1] = lcm(sfl[i], nums[n - i - 1])
        res = max(gcd(pfg[i], sfg[n - i - 1]) * lcm(pfl[i], sfl[n - i - 1]) for i in range(n))
        return max(res, pfl[n] * pfg[n])

from collections import *
from sortedcontainers import SortedList

class DICT:
    def __init__(self):
        self.vals = {}
        self.vv = SortedList()

    def get(self, key):
        if key in self.vals:
            return self.vals[key]
        return float('-inf')

    def set(self, key, val):
        if key in self.vals:
            self.vv.remove(self.vals[key])
        self.vals[key] = val
        self.vv.add(self.vals[key])

    def maxwithout(self, key):
        if key in self.vals:
            self.vv.remove(self.vals[key])
        res = float('-inf')
        if len(self.vv) > 0:
            res = self.vv[-1]
        if key in self.vals:
            self.vv.add(self.vals[key])
        return res

class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        dp = [[0] * (k + 1) for _ in range(n)]
        mrems = defaultdict(DICT)
        for i in range(n - 1, -1, -1):
            for rem in range(k + 1):
                if rem > 0:
                    dp[i][rem] = max(dp[i][rem], dp[i][rem - 1])
                dp[i][rem] = max(dp[i][rem], 1 + mrems[rem].get(nums[i]))
                if rem == 0:
                    continue
                dp[i][rem] = max(dp[i][rem], 1 + mrems[rem - 1].maxwithout(nums[i]))
            for rem in range(k + 1):
                mrems[rem].set(nums[i], max(mrems[rem].get(nums[i]), dp[i][rem]))
        res = 0
        for i in range(n):
            res = max(res, 1 + dp[i][k])
        return res

