class Solution:
    def maximumLength(self, nums: List[int]) -> int:
        n = len(nums)
        res = max(len([el for el in nums if el % 2 == 0]), len([el for el in nums if el % 2 == 1]))
        odd = even = 0
        for i in range(n):
            curr = 0
            if nums[i] % 2 == 0:
                curr = max(curr, 1 + odd)
                even = max(even, curr)
            else:
                curr = max(curr, 1 + even)
                odd = max(odd, curr)
            res = max(res, curr)
        return res

class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        res = 0
        dp = defaultdict(lambda: float('-inf'))
        for i in range(n - 1, -1, -1):
                for j in range(i + 1, n):
                    m = (nums[i] + nums[j]) % k
                    dp[(i, m)] = max(dp[(i, m)], 1 + dp[(j, m)], 2)
                    res = max(res, dp[(i, m)])
        return res

from collections import Counter

class Solution:
    def maximumLength(self, nums: List[int]) -> int:
        k = nums.count(1)
        res = max(k if k & 1 else k - 1, 1)
        ctr = Counter(nums)
        for el in ctr:
            if el != 1:
                curr = 0
                p = 1
                while ctr[pow(el, p)] >= 2:
                    curr += 2
                    if ctr[pow(el, p * 2)] >= 1:
                        res = max(res, curr + 1)
                    p *= 2
        return res

