class Solution:
    def maxCollectedFruits(self, fruits: List[List[int]]) -> int:
        n = len(fruits)
        diag = 0
        for i in range(n):
            diag += fruits[i][i]
        def topright():
            dist = [[0] * n for _ in range(n)]
            for i in range(n - 1, -1, -1):
                for j in range(n):
                    dist[i][j] = fruits[i][j]
                    for di, dj in [(1, -1), (1, 0), (1, 1)]:
                        x = i + di
                        y = j + dj
                        if not 0 <= x < n or not 0 <= y < n:
                            continue
                        if x == y and (x, y) != (n - 1, n - 1):
                            continue
                        if (i < j) != (x < y) and (x, y) != (n - 1, n - 1):
                            continue
                        dist[i][j] = max(dist[i][j], fruits[i][j] + dist[x][y])
            return dist[0][n - 1]
        def bottomleft():
            dist = [[0] * n for _ in range(n)]
            for j in range(n - 1, -1, -1):
                for i in range(n):
                    dist[i][j] = fruits[i][j]
                    for di, dj in [(-1, 1), (0, 1), (1, 1)]:
                        x = i + di
                        y = j + dj
                        if not 0 <= x < n or not 0 <= y < n:
                            continue
                        if x == y and (x, y) != (n - 1, n - 1):
                            continue
                        if (i < j) != (x < y) and (x, y) != (n - 1, n - 1):
                            continue
                        dist[i][j] = max(dist[i][j], fruits[i][j] + dist[x][y])
            return dist[n - 1][0]
        return diag + topright() + bottomleft() - 2 * fruits[n - 1][n - 1]

class Solution:
    def maxNumOfMarkedIndices(self, nums: List[int]) -> int:
        n = len(nums)
        nums.sort()
        beg = 1
        end = n // 2
        while beg <= end:
            mid = (beg + end) // 2
            v = True
            for i in range(mid):
                if 2 * nums[i] > nums[-mid + i]:
                    v = False
                    break
            if v:
                beg = mid + 1
            else:
                end = mid - 1
        return 2 * (beg - 1)

class Solution:
    def maximumValueSum(self, nums: List[int], k: int, edges: List[List[int]]) -> int:
        total = sum(nums)
        res = total
        vals = [(el ^ k, el) for el in nums]
        vals.sort(key = lambda x: x[1] - x[0])
        p = 0
        for i in range(len(nums)):
            p += vals[i][0]
            total -= vals[i][1]
            if i & 1:
                res = max(res, p + total)
        return res

class Solution:
    def atMostK(self, A, K):
        count = collections.Counter()
        res = i = 0
        for j in range(len(A)):
            if count[A[j]] == 0: K -= 1
            count[A[j]] += 1
            while K < 0:
                count[A[i]] -= 1
                if count[A[i]] == 0: K += 1
                i += 1
            res += j - i + 1
        return res

    def medianOfUniquenessArray(self, nums: List[int]) -> int:
        n = len(nums)
        beg = 1
        end = len(set(nums))
        res = end
        pos = ((n * (n + 1) // 2) - 1) // 2
        while beg <= end:
            mid = (beg + end) // 2
            l = self.atMostK(nums, mid - 1)
            r = self.atMostK(nums, mid)
            if l <= pos <= r - 1:
                res = mid
                break
            if pos < l:
                res = mid
                end = mid - 1
            else:
                beg = mid + 1
        return res

class Solution:
    def findMiddleIndex(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0
        total = sum(nums)
        curr = 0
        if curr * 2 == total - nums[0]:
            return 0
        for i in range(n - 1):
            curr += nums[i]
            if curr * 2 == total - nums[i + 1]:
                return i + 1
        return -1

class Solution:
    def minTime(self, skill, mana):
        n = len(skill)
        m = len(mana)
        p = [0] * n
        p[0] = skill[0]
        for i in range(1, n):
            p[i] = p[i - 1] + skill[i]
        t = 0
        for j in range(1, m):
            a = mana[j - 1]
            b = mana[j]
            d = p[0] * a
            for i in range(1, n):
                cand = p[i] * a - p[i - 1] * b
                if cand > d:
                    d = cand
            t += d
        return t + p[-1] * mana[-1]

class Solution:
    def isCritical(self, curr, prev, forw):
        if curr.val > prev.val and curr.val > forw.val:
            return True
        if curr.val < prev.val and curr.val < forw.val:
            return True
        return False

    def nodesBetweenCriticalPoints(self, head: Optional[ListNode]) -> List[int]:
        critical = []
        prev = None
        curr = head
        i = 0
        mindist = float('inf')
        while curr and curr.next:
            if prev and self.isCritical(curr, prev, curr.next):
                if len(critical) > 0:
                    mindist = min(mindist, i - critical[-1])
                critical.append(i)
            prev = curr
            curr = curr.next
            i += 1
        if len(critical) >= 2:
            k = len(critical)
            return [mindist, critical[-1] - critical[0]]
        return [-1, -1]

class Solution:
    def minimumArea(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        mnx = m + 1
        mxx = -1
        mny = n + 1
        mxy = -1
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    mnx = min(mnx, i)
                    mxx = max(mxx, i)
                    mny = min(mny, j)
                    mxy = max(mxy, j)
        return (mxx - mnx + 1) * (mxy - mny + 1)

class Solution:
    def getperm(self, nums, used, prev):
        if used == self.target:
            return 0
        res = float('inf')
        if self.cache[used][prev] != -1:
            return self.cache[used][prev]
        for i in range(len(nums)):
            if not used & (1 << i):
                curr = (abs(nums[i] - prev) if prev != -1 else 0) + (abs(nums[0] - i) if used | (1 << i) == self.target else 0) + self.getperm(nums, used | (1 << i), i)
                res = min(res, curr)
        self.cache[used][prev] = res
        return res

    def findPermutation(self, nums: List[int]) -> List[int]:
        n = len(nums)
        self.target = (1 << n) - 1
        self.cache = [[-1] * (n + 1) for _ in range(self.target + 1)]
        res = [0]
        used = 1
        prev = 0
        for _ in range(n - 1):
            curr = (float('inf'), -1)
            for i in range(n):
                if not used & (1 << i):
                    curr = min(curr, ((abs(nums[i] - prev) if prev != -1 else 0) + (abs(nums[0] - i) if used | (1 << i) == self.target else 0) + self.getperm(nums, used | (1 << i), i), i))
            res.append(curr[1])
            used |= (1 << curr[1])
            prev = curr[1]
        return res

import bisect

class Solution:
    def findMinFibonacciNumbers(self, k: int) -> int:
        fibs = [1, 1]
        for _ in range(45):
            fibs.append(fibs[-2] + fibs[-1])
        res = 0
        while k:
            pos = bisect.bisect_left(fibs, k)
            if fibs[pos] > k:
                pos -= 1
            k -= fibs[pos]
            res += 1
        return res

class Solution:
    def minimumPossibleSum(self, n: int, target: int) -> int:
        curr = 1
        res = 0
        seen = set()
        for _ in range(n):
            while target - curr in seen:
                curr += 1
            seen.add(curr)
            res += curr
            curr += 1
        return res

class Solution:
    def mostCompetitive(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        stack = []
        for i in range(n):
            while len(stack) > 0 and nums[i] < nums[stack[-1]] and len(stack) + n - i - 1 >= k:
                stack.pop()
            stack.append(i)
        while len(stack) > k:
            stack.pop()
        return [nums[i] for i in stack]

class Solution:
    def valueAfterKSeconds(self, n: int, k: int) -> int:
        res = [1] * n
        M = 10 ** 9 + 7
        for _ in range(k):
            for i in range(1, n):
                res[i] += res[i - 1]
                res[i] %= M
        return res[-1]

class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        n = len(original)
        up = min(bounds[i][1] - original[i] for i in range(n))
        down = max(bounds[i][0] - original[i] for i in range(n))
        return up - down + 1 if up >= down else 0

