M = 10 ** 9 + 7

class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        k = min(n, x)
        dp = [[0 for _ in range(n + 1)] for _ in range(k + 1)]
        for i in range(k + 1):
            dp[i][i] = 1
        for i in range(1, k + 1):
            for j in range(i + 1, n + 1):
                dp[i][j] = (i * dp[i][j - 1] + dp[i - 1][j - 1]) % M
        res = 0
        v = x * y
        for choose in range(1, k + 1):
            res += dp[choose][n] * v
            v *= y * (x - choose)
            v %= M
            res %= M
        return res

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

gcds = [[0] * 201 for _ in range(201)]
for i in range(201):
    for j in range(201):
        gcds[i][j] = gcd(i, j)

class Solution:
    def subsequencePairCount(self, nums: List[int]) -> int:
        M = 10 ** 9 + 7
        n = len(nums)
        mx = max(nums)
        dp = [[0] * (mx + 1) for _ in range(mx + 1)]
        ndp = [[0] * (mx + 1) for _ in range(mx + 1)]
        for i in range(1, mx + 1):
            dp[i][i] = 1
        for i in range(n - 1, -1, -1):
            for a in range(mx + 1):
                for b in range(mx + 1):
                    ndp[a][b] = dp[a][b] + dp[gcds[a][nums[i]]][b] + dp[a][gcds[b][nums[i]]]
                    ndp[a][b] %= M
            dp, ndp = ndp, dp
        return dp[0][0]

