            dp[i] = 1
            if i < n - 1 and nums[i] + 1 == nums[i + 1]:
                dp[i] = 1 + dp[i + 1]
        res = []
        for i in range(n - k + 1):
            if dp[i] >= k:
                res.append(nums[i] + k - 1)
