from collections import deque, defaultdict
import heapq

class Solution:
    def match(self, a, b):
        m = len(a)
        n = len(b)
        for i in range(min(m, n), 0, -1):
            if a[-i:] == b[:i]:
                return i
        return 0

    def shortestSuperstring(self, words: List[str]) -> str:
        n = len(words)
        if n == 1:
            return "".join(words)
        match = [[0] * n for _ in range(n)]
        for i in range(n):
            match[i][i] = len(words[i])
            for j in range(i + 1, n):
                match[i][j] = self.match(words[i], words[j])
                match[j][i] = self.match(words[j], words[i])
        heap = []
        dist = defaultdict(lambda: float('inf'))
        parent = {}
        for i in range(n):
            heapq.heappush(heap, (0, i, 1 << i))
            dist[(i, 1 << i)] = len(words[i])
        while len(heap) > 0:
            d, i, mask = heapq.heappop(heap)
            for j in range(n):
                if i != j and dist[(j, mask | 1 << j)] > dist[(i, mask)] + len(words[j]) - match[i][j]:
                    dist[(j, mask | 1 << j)] = dist[(i, mask)] + len(words[j]) - match[i][j]
                    heapq.heappush(heap, (dist[(j, mask | 1 << j)], j, mask | 1 << j))
                    parent[(j, mask | 1 << j)] = (i, mask)
        mlen = float('inf')
        for i in range(n):
            mlen = min(mlen, dist[(i, (1 << n) - 1)])
        seq = []
        for el in parent:
            if el[1] + 1 == 1 << n and dist[el] == mlen:
                path = [el[0]]
                while el in parent:
                    el = parent[el]
                    path.append(el[0])
                seq = path[::-1]
                break
        res = []
        for i in range(len(seq) - 1):
            res.append(words[seq[i]][:len(words[seq[i]]) - match[seq[i]][seq[i+1]]])
        res.append(words[seq[-1]])
        return "".join(res)

import math

class Solution:
    def getSum(self, nums, d):
        val = 0
        if d == 0:
            return float('inf')
        for num in nums:
            val += math.ceil(num / d)
        return val

    def smallestDivisor(self, nums: List[int], threshold: int) -> int:
        end = 1
        while self.getSum(nums, end) > threshold:
            end *= 2
        beg = end // 2
        res = end
        while beg <= end:
            mid = (beg + end) // 2
            if self.getSum(nums, mid) <= threshold:
                res = mid
                end = mid - 1
            else:
                beg = mid + 1
        return res

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, a):
        if a == self.parent[a]:
            return a
        self.parent[a] = self.find(self.parent[a])
        return self.parent[a]

    def union(self, a, b):
        parent_a = self.find(a)
        parent_b = self.find(b)
        if parent_a != parent_b:
            if self.size[parent_a] < self.size[parent_b]:
                parent_a, parent_b = parent_b, parent_a
            self.parent[parent_b] = parent_a
            self.size[parent_a] += self.size[parent_b]

class Solution:
    def findTheString(self, lcp: List[List[int]]) -> str:
        n = len(lcp)
        dsu = DSU(n)
        for i in range(n):
            for j in range(n):
                if lcp[i][j] > 0:
                    dsu.union(i, j)
        res = []
        x = 0
        mp = {}
        for i in range(n):
            if dsu.find(i) not in mp:
                if x >= 26:
                    return ""
                mp[dsu.find(i)] = chr(ord('a') + x)
                x += 1
            res.append(mp[dsu.find(i)])
        res = "".join(res)
        for i in range(n):
            for j in range(n):
                curr = 1 + lcp[i + 1][j + 1] if i + 1 < n and j + 1 < n else 1
                if res[i] != res[j]:
                    curr = 0
                if curr != lcp[i][j]:
                    return ""
        return res

