class Solution:
    def sumOfEncryptedInt(self, nums: List[int]) -> int:
        res = 0
        for el in nums:
            ctr = 0
            d = 0
            while el:
                d = max(d, el % 10)
                el //= 10
                ctr += 1
            x = 0
            for _ in range(ctr):
                x = 10 * x + d
            res += x
        return res

M = 10 ** 9 + 7

class Solution:
    def count(self, nums, i, n, rem, used):
        if rem < 0:
            return 0
        if i >= n:
            if rem > 0:
                return 0
            return self.pw[n - used]
        key = (i, rem, used)
        if key in self.cache:
            return self.cache[key]
        res = self.count(nums, i + 1, n, rem, used)
        res += self.count(nums, i + 1, n, rem - nums[i], used + 1)
        res %= M
        self.cache[key] = res
        return res

    def sumOfPower(self, nums: List[int], k: int) -> int:
        n = len(nums)
        self.cache = {}
        self.pw = [1] * (n + 1)
        for i in range(1, n + 1):
            self.pw[i] = 2 * self.pw[i - 1]
            self.pw[i] %= M
        return self.count(nums, 0, n, k, 0)

class Solution:
    def findJudge(self, n: int, trust: List[List[int]]) -> int:
        trustedGraph = {}
        trustingGraph = {}
        for a, b in trust:
            trustedGraph[b] = trustedGraph.get(b, 0) + 1
            trustingGraph[a] = trustingGraph.get(a, 0) + 1
        for i in range(1, n + 1):
            if trustedGraph.get(i, 0) == n - 1 and trustingGraph.get(i, 0) == 0:
                return i
        return -1

