from collections import Counter

class Solution:
    def countCharacters(self, words: List[str], chars: str) -> int:
        chars = Counter(chars)
        l = 0
        for w in words:
            curr = Counter(w)
            possible = True
            for c in curr:
                if chars[c] < curr[c]:
                    possible = False
                    break
            if possible:
                l += len(w)
        return l

from collections import Counter
from sortedcontainers import SortedList

class Solution:
    def findXSum(self, nums: List[int], k: int, x: int) -> List[int]:
        n = len(nums)
        res = []
        ctr = Counter()
        r = SortedList()
        l = SortedList()
        s = 0
        def balance():
            nonlocal s
            while len(r) > x:
                v = r.pop(0)
                s -= v[0] * v[1]
                l.add(v)
            while len(r) < x and len(l) > 0:
                v = l.pop(-1)
                s += v[0] * v[1]
                r.add(v)
        def add(val):
            nonlocal s
            if len(r) > 0 and val >= r[0]:
                s += val[0] * val[1]
                r.add(val)
            else:
                l.add(val)
            balance()
        def remove(val):
            nonlocal s
            if len(r) > 0 and val >= r[0]:
                s -= val[0] * val[1]
                r.remove(val)
            else:
                l.remove(val)
            balance()
        for i in range(n):
            if ctr[nums[i]]:
                remove((ctr[nums[i]], nums[i]))
            ctr[nums[i]] += 1
            add((ctr[nums[i]], nums[i]))
            if i >= k:
                remove((ctr[nums[i - k]], nums[i - k]))
                ctr[nums[i - k]] -= 1
                if ctr[nums[i - k]]:
                    add((ctr[nums[i - k]], nums[i - k]))
            if i >= k - 1:
                res.append(s)
        return res

from collections import Counter
from sortedcontainers import SortedList

class Solution:
    def findXSum(self, nums: List[int], k: int, x: int) -> List[int]:
        n = len(nums)
        res = []
        ctr = Counter()
        r = SortedList()
        l = SortedList()
        s = 0
        def balance():
            nonlocal s
            while len(r) > x:
                v = r.pop(0)
                s -= v[0] * v[1]
                l.add(v)
            while len(r) < x and len(l) > 0:
                v = l.pop(-1)
                s += v[0] * v[1]
                r.add(v)
        def add(val):
            nonlocal s
            if len(r) > 0 and val >= r[0]:
                s += val[0] * val[1]
                r.add(val)
            else:
                l.add(val)
            balance()
        def remove(val):
            nonlocal s
            if len(r) > 0 and val >= r[0]:
                s -= val[0] * val[1]
                r.remove(val)
            else:
                l.remove(val)
            balance()
        for i in range(n):
            if ctr[nums[i]]:
                remove((ctr[nums[i]], nums[i]))
            ctr[nums[i]] += 1
            add((ctr[nums[i]], nums[i]))
            if i >= k:
                remove((ctr[nums[i - k]], nums[i - k]))
                ctr[nums[i - k]] -= 1
                if ctr[nums[i - k]]:
                    add((ctr[nums[i - k]], nums[i - k]))
            if i >= k - 1:
                res.append(s)
        return res

class Solution:
    def resultArray(self, nums: List[int], k: int) -> List[int]:
        res = [0] * k
        dp = [0] * k
        for a in nums:
            ndp = [0] * k
            am = a % k
            ndp[am] += 1
            for r in range(k):
                if dp[r]:
                    ndp[(r * am) % k] += dp[r]
            for r in range(k):
                res[r] += ndp[r]
            dp = ndp
        return res

class SegTree:
    def __init__(self, arr, k):
        self.n = len(arr)
        self.k = k
        self.size = 1
        while self.size < self.n:
            self.size <<= 1
        self.tree = [None] * (2 * self.size)
        for i in range(self.size):
            if i < self.n:
                tot = arr[i] % k
                freq = [0] * k
                freq[tot] = 1
                self.tree[self.size + i] = (tot, freq)
            else:
                self.tree[self.size + i] = (1, [0] * k)
        for i in range(self.size - 1, 0, -1):
            self.tree[i] = self._merge(self.tree[2 * i], self.tree[2 * i + 1])

    def _merge(self, left, right):
        tot = (left[0] * right[0]) % self.k
        freq = [0] * self.k
        for i in range(self.k):
            freq[i] += left[1][i]
        for j in range(self.k):
            freq[(left[0] * j) % self.k] += right[1][j]
        return (tot, freq)

    def update(self, pos, val):
        p = pos + self.size
        tot = val % self.k
        freq = [0] * self.k
        freq[tot] = 1
        self.tree[p] = (tot, freq)
        p //= 2
        while p:
            self.tree[p] = self._merge(self.tree[2 * p], self.tree[2 * p + 1])
            p //= 2

    def query(self, l, r):
        resl = (1, [0] * self.k)
        resr = (1, [0] * self.k)
        l += self.size
        r += self.size
        while l < r:
            if l & 1:
                resl = self._merge(resl, self.tree[l])
                l += 1
            if r & 1:
                r -= 1
                resr = self._merge(self.tree[r], resr)
            l //= 2
            r //= 2
        res = self._merge(resl, resr)
        return res[1]

class Solution:
    def resultArray(self, nums: List[int], k: int, queries: List[List[int]]) -> List[int]:
        n = len(nums)
        seg = SegTree(nums, k)
        res = []
        for i, v, l, x in queries:
            seg.update(i, v)
            res.append(seg.query(l, n)[x])
        return res

class Solution:
    def xorBeauty(self, nums: List[int]) -> int:
        n = len(nums)
        res = 0
        ctr = [0] * 32
        for el in nums:
            for b in range(32):
                if el & (1 << b):
                    ctr[b] += 1
        for el in nums:
            curr = 0
            for b in range(32):
                sets = 0
                unsets = 0
                if el & (1 << b):
                    sets += ctr[b]
                    unsets += n - ctr[b]
                else:
                    unsets += n
                if sets & 1:
                    curr |= 1 << b
            res ^= curr
        return res

class Solution:
    def getXORSum(self, arr1: List[int], arr2: List[int]) -> int:
        ctr = [0] * 32
        for el in arr2:
            for b in range(32):
                if el & (1 << b):
                    ctr[b] += 1
        res = 0
        for el in arr1:
            curr = 0
            for b in range(32):
                if el & (1 << b) and ctr[b] & 1:
                    curr |= 1 << b
            res ^= curr
        return res

import bisect

class Solution:
    def findEvenNumbers(self, digits: List[int]) -> List[int]:
        n = len(digits)
        f = [i for i in range(n) if digits[i] != 0]
        s = [i for i in range(n)]
        t = [i for i in range(n) if digits[i] in {0, 2, 4, 6, 8}]
        nums = []
        for i in f:
            for j in s:
                if i == j:
                    continue
                for k in t:
                    if i != k and j != k:
                        val = 100 * digits[i] + 10 * digits[j] + digits[k]
                        pos = bisect.bisect_left(nums, val)
                        if pos >= len(nums) or nums[pos] != val:
                            bisect.insort(nums, val)
        return nums

from collections import Counter

class FindSumPairs:
    def __init__(self, nums1: List[int], nums2: List[int]):
        self.ctr = Counter(nums2)
        self.nums2 = nums2
        self.nums1 = nums1

    def add(self, index: int, val: int) -> None:
        self.ctr[self.nums2[index]] -= 1
        self.nums2[index] += val
        self.ctr[self.nums2[index]] += 1

    def count(self, tot: int) -> int:
        res = 0
        for el in self.nums1:
            res += self.ctr[tot - el]
        return res

