class Solution:
    def flatten(self, head: 'Optional[Node]') -> 'Optional[Node]':
        if head:
            curr = head
            while curr:
                tmp = curr.next
                if curr.child:
                    curr.next = self.flatten(curr.child)
                    if curr.next:
                        curr.next.prev = curr
                    curr.child = None
                    ccurr = curr.next
                    while ccurr and ccurr.next:
                        ccurr = ccurr.next
                    ccurr.next = tmp
                    if tmp:
                        tmp.prev = ccurr
                curr = tmp
        return head

class Solution:
    def flatten(self, root: Optional[TreeNode]) -> None:
        def flat(r):
            if not r:
                return r
            lend = flat(r.left)
            rend = flat(r.right)
            r.right, (lend or r).right, r.left, = r.left, r.right, None
            return rend or lend or r
        flat(root)
        return root

class NestedIterator:
    def __init__(self, nestedList: [NestedInteger]):
        self.arr = []
        self.expand(nestedList)
        self.i = 0

    def expand(self, nestedList):
        for nl in nestedList:
            if nl.isInteger():
                self.arr += [nl.getInteger()]
            else:
                self.expand(nl.getList())

    def next(self) -> int:
        self.i += 1
        return self.arr[self.i - 1]

    def hasNext(self) -> bool:
        return self.i < len(self.arr)

class Solution:
    def po(self, root):
        if root:
            return [root.val] + self.po(root.left) + self.po(root.right)
        return []

    def preorder(self, root, voyage):
        if root:
            self.i += 1
            valid = True
            if root.left:
                if self.i >= len(voyage):
                    return
                if root.left.val != voyage[self.i]:
                    root.left, root.right = root.right, root.left
                    valid = False
                self.preorder(root.left, voyage)
            if root.right:
                if self.i >= len(voyage):
                    return
                if root.right.val != voyage[self.i]:
                    root.left, root.right = root.right, root.left
                    valid = False
                self.preorder(root.right, voyage)
            if not valid:
                self.res.append(root.val)

    def flipMatchVoyage(self, root: Optional[TreeNode], voyage: List[int]) -> List[int]:
        n = len(voyage)
        self.i = 0
        self.res = []
        self.preorder(root, voyage)
        if self.po(root) != voyage:
            return [-1]
        return self.res

class Solution:
    def maxEqualRowsAfterFlips(self, matrix: List[List[int]]) -> int:
        m = len(matrix)
        n = len(matrix[0])
        ctr = Counter()
        for r in matrix:
            r = min(r, [1 - x for x in r])
            ctr[tuple(r)] += 1
        return max(ctr.values())

class Solution:
    def flipEquiv(self, root1: Optional[TreeNode], root2: Optional[TreeNode]) -> bool:
        if not root1 and not root2:
            return True
        if root1 and root2:
            if root1.val != root2.val:
                return False
            if self.flipEquiv(root1.left, root2.left) and self.flipEquiv(root1.right, root2.right):
                return True
            if self.flipEquiv(root1.left, root2.right) and self.flipEquiv(root1.right, root2.left):
                return True
        return False

class Solution:
    def minFlipsMonoIncr(self, s: str) -> int:
        n = len(s)
        res = float('inf')
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] += p[i] + int(s[i])
        for i in range(n + 1):
            leftones = p[i]
            rightzeroes = (n - p[n]) - (i - p[i])
            res = min(res, leftones + rightzeroes)
        return res

import math

class Solution:
    def flipAndInvertImage(self, image: List[List[int]]) -> List[List[int]]:
        n = len(image)
        for j in range(math.ceil(n/2)):
            for i in range(n):
                image[i][j], image[i][n - j - 1] = 1 - image[i][n - j - 1], 1 - image[i][j]
        return image

class Solution:
    def fill(self, image: List[List[int]], sr: int, sc: int, color: int, og) -> List[List[int]]:
        m = len(image)
        n = len(image[0])
        if image[sr][sc] == color:
            return
        image[sr][sc] = color
        for x, y in [(sr - 1, sc), (sr, sc - 1), (sr + 1, sc), (sr, sc + 1)]:
            if 0 <= x < m and 0 <= y < n and image[x][y] == og:
                self.fill(image, x, y, color, og)

    def floodFill(self, image: List[List[int]], sr: int, sc: int, color: int) -> List[List[int]]:
        self.fill(image, sr, sc, color, image[sr][sc])
        return image

class Solution:
    def gardenNoAdj(self, n: int, paths: List[List[int]]) -> List[int]:
        types = [1] * n
        graph = {}
        for a, b in paths:
            graph[a - 1] = graph.get(a - 1, []) + [b - 1]
            graph[b - 1] = graph.get(b - 1, []) + [a - 1]
        visited = set()
        stack = list(range(n))
        while len(stack) > 0:
            curr = stack.pop()
            visited.add(curr)
            colors = set()
            for j in graph.get(curr, []):
                colors.add(types[j])
                if j not in visited:
                    stack.append(j)
            if types[curr] in colors:
                for i in range(1, n + 1):
                    if i not in colors:
                        types[curr] = i
                        break
        return types

class Solution:
    def largestNumber(self, cost: List[int], target: int) -> str:
        dp = [[float('-inf')] * (target + 1) for _ in range(10)]
        dp[0][0] = 0
        for d in range(1, 10):
            for rem in range(target + 1):
                dp[d][rem] = dp[d - 1][rem]
                if cost[d - 1] <= rem:
                    dp[d][rem] = max(dp[d][rem], 1 + max(dp[d - 1][rem - cost[d - 1]], dp[d][rem - cost[d - 1]]))
        res = []
        rem = target
        for d in range(9, 0, -1):
            mx = (-1, -1)
            for ctr in range(rem // cost[d - 1], -1, -1):
                 mx = max(mx, (ctr + dp[d - 1][rem - ctr * cost[d - 1]], ctr))
            if mx[0] != -1:
                res.append(str(d) * mx[1])
                rem -= mx[1] * cost[d - 1]
        return "".join(res) or "0"

class Solution:
    def minNumber(self, nums1: List[int], nums2: List[int]) -> int:
        a, b = min(nums1), min(nums2)
        common = set.intersection(set(nums1), set(nums2))
        if len(common) > 0:
            return min(common)
        a, b = min(a, b), max(a, b)
        return 10 * a + b

