class Solution:
    def sumFourDivisors(self, nums: List[int]) -> int:
        return sum(s[el] for el in nums)

class Solution:
    def gcd(self, a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(self, arr):
        n = len(arr)
        curr = arr[0]
        for i in range(1, n):
            l = arr[i]
            curr = (curr * l) // self.gcd(curr, l)
        return curr

    def fractionAddition(self, expression: str) -> str:
        expression += "x"
        sign = 1
        chunk = ""
        nums = []
        for c in expression:
            if c == "+" or c == "-" or c == "x":
                if len(chunk) > 0:
                    a, b = chunk.split("/")
                    a, b = int(a), int(b)
                    nums.append([sign * a, b])
                chunk = ""
                if c == "+":
                    sign = 1
                elif c == "-":
                    sign = -1
            else:
                chunk += c
        mul = self.lcm([num[1] for num in nums])
        ans = sum([num[0] * mul // num[1] for num in nums])
        hcf = self.gcd(ans, mul)
        return "{}/{}".format(ans // hcf, mul // hcf)

class Solution:
    def minsteps(self, key, i, pos, j, l):
        if i >= len(key):
            return 0
        if (i, j) in self.cache:
            return self.cache[(i, j)]
        res = float('inf')
        for k in pos[key[i]]:
            cost = abs(k - j)
            cost = min(cost, l - cost) + 1
            res = min(res, cost + self.minsteps(key, i + 1, pos, k, l))
        self.cache[(i, j)] = res
        return res

    def findRotateSteps(self, ring: str, key: str) -> int:
        self.cache = {}
        pos = defaultdict(list)
        for i, c in enumerate(ring):
            pos[c].append(i)
        return self.minsteps(key, 0, pos, 0, len(ring))

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nums.sort()
        p = [0]
        for el in nums:
            p.append(p[-1] + el)
        steps = lambda x, y: nums[y] * (y - x + 1) - p[y + 1] + p[x]
        res = 1
        i = 0
        for j in range(n):
            while i < j and steps(i, j) > k:
                i += 1
            if steps(i, j) <= k:
                res = max(res, j - i + 1)
        return res

from collections import Counter

class FrequencyTracker:
    def __init__(self):
        self.freq = Counter()
        self.freqfreq = Counter()

    def add(self, number: int) -> None:
        self.freqfreq[self.freq[number]] -= 1
        self.freq[number] += 1
        self.freqfreq[self.freq[number]] += 1

    def deleteOne(self, number: int) -> None:
        if self.freq[number] > 0:
            self.freqfreq[self.freq[number]] -= 1
            self.freq[number] -= 1
            self.freqfreq[self.freq[number]] += 1

    def hasFrequency(self, frequency: int) -> bool:
        return self.freqfreq[frequency] > 0

class Solution:
    def possible(self, stones, n, x):
        i = 0
        v = set()
        prev = {}
        pj = 0
        for j in range(n):
            if stones[j] - stones[i] <= x and (j == n - 1 or stones[j + 1] - stones[i] > x):
                i = j
                if j != n - 1:
                    v.add(j)
            else:
                prev[j] = pj
                pj = j
        prev[n - 1] = pj
        if i != n - 1:
            return False
        i = n - 1
        for j in range(n - 1, -1, -1):
            if j not in v:
                if stones[i] - stones[j] <= x and (j == 0 or stones[i] - stones[prev[j]] > x):
                    i = j
        return i == 0

    def maxJump(self, stones: List[int]) -> int:
        n = len(stones)
        beg = 0
        end = 1
        while not self.possible(stones, n, end):
            end *= 2
        beg = end // 2
        res = end
        while beg <= end:
            mid = (beg + end) // 2
            if self.possible(stones, n, mid):
                res = mid
                end = mid - 1
            else:
                beg = mid + 1
        return res

class Solution:
    def possible(self, i, n, stones, pos, allowedJumps):
        if i == n - 1:
            return True
        key = tuple([i] + allowedJumps)
        if key in self.cache:
            return self.cache[key]
        for jump in allowedJumps:
            if jump > 0 and stones[i] + jump in pos:
                if self.possible(pos[stones[i] + jump], n, stones, pos, [jump - 1, jump, jump + 1]):
                    self.cache[key] = True
                    return True
        self.cache[key] = False
        return False

    def canCross(self, stones: List[int]) -> bool:
        n = len(stones)
        pos = {}
        for i, stone in enumerate(stones):
            pos[stone] = i
        self.cache = {}
        return self.possible(0, n, stones, pos, [1])

class Solution:
    def frogPosition(self, n: int, edges: List[List[int]], t: int, target: int) -> float:
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u - 1].append(v - 1)
            graph[v - 1].append(u - 1)
        @lru_cache(maxsize = None)
        def p(i, pv, rem):
            if rem < 0:
                return 0
            leaf = True
            for j in graph[i]:
                if j != pv:
                    leaf = False
            if i == target - 1:
                if rem > 0 and not leaf:
                    return 0
                else:
                    return 1
            if rem == 0:
                return 0
            s = 0
            ctr = 0
            for j in graph[i]:
                if j != pv:
                    s += p(j, i, rem - 1)
                    ctr += 1
            if ctr == 0:
                return 0
            return s / ctr
        return p(0, -1, t)

from collections import Counter

class Solution:
    def totalFruit(self, fruits: List[int]) -> int:
        n = len(fruits)
        i = 0
        ctr = Counter()
        mlen = 0
        for j in range(n):
            ctr[fruits[j]] += 1
            if len(ctr) <= 2:
                mlen = max(mlen, j - i + 1)
            else:
                while i < j and len(ctr) > 2:
                    ctr[fruits[i]] -= 1
                    if ctr[fruits[i]] == 0:
                        del ctr[fruits[i]]
                    i += 1
                if len(ctr) <= 2:
                    mlen = max(mlen, j - i + 1)
        return mlen

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        res = 0
        for i in range(len(fruits)):
            j = 0
            while j < len(baskets) and baskets[j] < fruits[i]:
                j += 1
            if j < len(baskets):
                baskets[j] = 0
            else:
                res += 1
        return res

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(baskets)
        if n == 0:
            return len(fruits)
        N = 1
        while N < n:
            N *= 2
        tree = [0] * (2 * N)
        for i in range(n):
            tree[N + i] = baskets[i]
        for i in range(N - 1, 0, -1):
            tree[i] = max(tree[2 * i], tree[2 * i + 1])
        res = 0
        for fruit in fruits:
            if tree[1] < fruit:
                res += 1
                continue
            pos = 1
            while pos < N:
                if tree[2 * pos] >= fruit:
                    pos = 2 * pos
                else:
                    pos = 2 * pos + 1
            tree[pos] = 0
            pos //= 2
            while pos:
                tree[pos] = max(tree[2 * pos], tree[2 * pos + 1])
                pos //= 2
        return res

import heapq

class Solution:
    def furthestBuilding(self, heights: List[int], bricks: int, ladders: int) -> int:
        n = len(heights)
        heap = []
        total = 0
        totalheap = 0
        for i in range(n - 1):
            if heights[i] < heights[i + 1]:
                diff = heights[i + 1] - heights[i]
                total += diff
                heapq.heappush(heap, diff)
                totalheap += diff
                if len(heap) > ladders:
                    totalheap -= heapq.heappop(heap)
                if total - totalheap > bricks:
                    return i
        return n - 1

class Solution:
    def furthestDistanceFromOrigin(self, moves: str) -> int:
        res = 0
        curr = 0
        for c in moves:
            if c == "R" or c == "_":
                curr += 1
            else:
                curr -= 1
        res = max(res, abs(curr))
        curr = 0
        for c in moves:
            if c == "L" or c == "_":
                curr -= 1
            else:
                curr += 1
        res = max(res, abs(curr))
        return res

class Solution:
    def getNeighbors(self, i, j, m, n):
        neighbors = []
        for a in range(i - 1, i + 2):
            for b in range(j - 1, j + 2):
                if a == i and b == j:
                    continue
                if a < 0 or a >= m:
                    continue
                if b < 0 or b >= n:
                    continue
                neighbors.append((a, b))
        return neighbors

    def gameOfLife(self, board: List[List[int]]) -> None:
        m = len(board)
        n = len(board[0])
        shifts = set()
        for i in range(m):
            for j in range(n):
                curr = board[i][j]
                neighbors = self.getNeighbors(i, j, m, n)
                num = sum([board[x][y] for x, y in neighbors])
                if curr == 1:
                    if num < 2 or num > 3:
                        shifts.add((i, j))
                else:
                    if num == 3:
                        shifts.add((i, j))
        for i, j in shifts:
            board[i][j] = 1 - board[i][j]

class Solution:
    def canCompleteCircuit(self, gas: List[int], cost: List[int]) -> int:
        n = len(gas)
        total = 0
        abstotal = 0
        res = 0
        for i in range(n):
            diff = gas[i] - cost[i]
            total += diff
            abstotal += diff
            if total < 0:
                total = 0
                res = i + 1
        if abstotal < 0:
            return -1
        return res

