class Solution:
    def gcdSort(self, nums: List[int]) -> bool:
        n = len(nums)
        dsu = DSU(n)
        last = {}
        for i in range(n):
            curr = nums[i]
            while curr > 1:
                dsu.union(i, last.get(sp[curr], i))
                last[sp[curr]] = i
                curr //= sp[curr]
        groups = [[] for _ in range(n)]
        for i in range(n):
            groups[dsu.find(i)].append(i)
        for i in range(n):
            groups[i].sort(key = lambda x: nums[x], reverse = True)
        res = nums[:]
        for i in range(n):
            res[i] = nums[groups[dsu.find(i)].pop()]
        return res == sorted(nums)

class Solution:
    def validStrings(self, n: int) -> List[str]:
        def valid(s):
            for i in range(n - 1):
                if s[i] == '0' and s[i + 1] == '0':
                    return False
            return True
        return [("{:0"+str(n)+"b}").format(x) for x in range(1 << n) if valid(("{:0"+str(n)+"b}").format(x))]

class Solution:
    def generate(self, s, ctr, rem, ans):
        if rem == 0 and ctr == 0:
            ans.add(s)
        if rem > 0 and ctr >= 0:
            if ctr < rem:
                self.generate(s + '(', ctr + 1, rem - 1, ans)
            if ctr > 0:
                self.generate(s + ')', ctr - 1, rem - 1, ans)

    def generateParenthesis(self, n: int) -> List[str]:
        ans = set()
        self.generate("", 0, 2 * n, ans)
        return list(ans)

class Solution:
    def equalSubstring(self, s: str, t: str, maxCost: int) -> int:
        n = len(s)
        res = 0
        val = lambda x: abs(ord(s[x]) - ord(t[x]))
        i = 0
        cost = 0
        for j in range(n):
            cost += val(j)
            while i < j and cost > maxCost:
                cost -= val(i)
                i += 1
            if cost <= maxCost:
                res = max(res, j - i + 1)
        return res

class Solution:
    def getMaximumGenerated(self, n: int) -> int:
        if n == 0:
            return 0
        arr = [0] * (n + 1)
        arr[1] = 1
        for i in range(n + 1):
            if 2 * i <= n:
                arr[2 * i] = arr[i]
            if 2 * i + 1 <= n:
                arr[2 * i + 1] = arr[i] + arr[i + 1]
        return max(arr)

class Solution:
    def interpret(self, command: str) -> str:
        n = len(command)
        i = 0
        op = ""
        while i < n:
            if command[i] == "G":
                op += "G"
                i += 1
            elif i < n - 1 and command[i:i+2] == "()":
                op += "o"
                i += 2
            elif i < n - 3 and command[i:i+4] == "(al)":
                op += "al"
                i += 4
        return op

class Solution:
    def transform(self, word, i):
        vowels = { 'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U' }
        op = ""
        if word[0] in vowels:
            op += word + "ma"
        else:
            op += word[1:] + word[0] + "ma"
        op += "a" * i
        return op

    def toGoatLatin(self, sentence: str) -> str:
        words = sentence.split()
        return " ".join([self.transform(word, i+1) for i, word in enumerate(words)])

