class Solution:
    def areConnected(self, n: int, threshold: int, queries: List[List[int]]) -> List[bool]:
        dsu = DSU(n + 1)
        minfact = {}
        for i in range(threshold + 1, n + 1):
            mul = 1
            while i * mul <= n:
                dsu.union(i, i * mul)
                if i * mul not in minfact:
                    minfact[i * mul] = i
                else:
                    dsu.union(i, minfact[i * mul])
                mul += 1
        return [dsu.find(a) == dsu.find(b) for a, b in queries]

class Solution:
    def grayCode(self, n: int) -> List[int]:
        return [i ^ (i >> 1) for i in range(1 << n)]

class Solution:
    def valid(self, s, k, n):
        for i in range(n):
            if s[i] != s[i % k]:
                return False
        return True

    def gcd(self, a, b):
        while b:
            a, b = b, a % b
        return a

    def gcdOfStrings(self, str1: str, str2: str) -> str:
        m = len(str1)
        n = len(str2)
        k = self.gcd(m, n)
        if self.valid(str1, k, m) and self.valid(str2, k, n) and str1[:k] == str2[:k]:
            return str1[:k]
        return ""

