class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        if len(nums) == 1:
            return True
        if nums == [1] * len(nums):
            return False
        N = 1 + max(nums)
        sp = [1] * N
        v = [False] * N
        for i in range(2, N, 2):
            sp[i] = 2
        for i in range(3, N, 2):
            if not v[i]:
                sp[i] = i
                j = i
                while j * i < N:
                    v[j * i] = True
                    sp[j * i] = i
                    j += 2
        dsu = DSU(N)
        for el in nums:
            curr = el
            while curr > 1:
                dsu.union(el, sp[curr])
                curr //= sp[curr]
        comps = set()
        for el in nums:
            comps.add(dsu.find(el))
        return len(comps) == 1

class Solution:
    def greatestLetter(self, s: str) -> str:
        lower = set()
        upper = set()
        for c in s:
            if c.islower():
                lower.add(c)
            if c.isupper():
                upper.add(c.lower())
        common = set.intersection(lower, upper)
        if len(common) == 0:
            return ""
        return max(common).upper()

import bisect

class Solution:
    def maxSumDivThree(self, nums: List[int]) -> int:
        msum = 0
        n = len(nums)
        total = sum(nums)
        if total % 3 == 0:
            return total
        nums.sort()
        paths = [(nums[i], i) for i in range(n)]
        i = 0
        while i < len(paths):
            currsum, curr = paths[i]
            if (total - currsum) % 3 == 0:
                return total - currsum
            for j in range(curr + 1, n):
                bisect.insort(paths, (currsum + nums[j], j))
            i += 1
        return 0

class Solution:
    def gridGame(self, grid: List[List[int]]) -> int:
        n = len(grid[0])
        top = [0]
        bottom = [0]
        for el in grid[0]:
            top.append(top[-1] + el)
        for el in grid[1]:
            bottom.append(bottom[-1] + el)
        opponent = float('inf')
        mindex = None
        for i in range(n):
            curropp = max(top[-1] - top[i + 1], bottom[i])
            if curropp <= opponent:
                opponent = curropp
                mindex = i
        return max(top[-1] - top[mindex + 1], bottom[mindex])

from collections import Counter

class Solution:
    def gridIllumination(self, n: int, lamps: List[List[int]], queries: List[List[int]]) -> List[int]:
        rowctr = Counter()
        colctr = Counter()
        posdiagctr = Counter()
        negdiagctr = Counter()
        onlamps = set()
        for i, j in lamps:
            if (i, j) not in onlamps:
                rowctr[i] += 1
                colctr[j] += 1
                posdiagctr[i + j] += 1
                negdiagctr[i - j] += 1
                onlamps.add((i, j))
        res = []
        for i, j in queries:
            if rowctr[i] > 0 or colctr[j] > 0 or posdiagctr[i + j] > 0 or negdiagctr[i - j] > 0:
                res.append(1)
            else:
                res.append(0)
            for x in range(i - 1, i + 2):
                for y in range(j - 1, j + 2):
                    if 0 <= x < n and 0 <= y < n and (x, y) in onlamps:
                        onlamps.remove((x, y))
                        rowctr[x] -= 1
                        colctr[y] -= 1
                        posdiagctr[x + y] -= 1
                        negdiagctr[x - y] -= 1
        return res

class Solution:
    def minMoves(self, matrix: List[str]) -> int:
        m, n = len(matrix), len(matrix[0])
        portals = defaultdict(list)
        for i in range(m):
            for j in range(n):
                c = matrix[i][j]
                if 'A' <= c <= 'Z':
                    portals[c].append((i, j))
        dist = [[float('inf')] * n for _ in range(m)]
        dq = deque([(0, 0)])
        dist[0][0] = 0
        while dq:
            x, y = dq.popleft()
            d = dist[x][y]
            if (x, y) == (m-1, n-1):
                return d
            c = matrix[x][y]
            if 'A' <= c <= 'Z' and portals[c]:
                for nx, ny in portals[c]:
                    if d < dist[nx][ny]:
                        dist[nx][ny] = d
                        dq.appendleft((nx, ny))
                portals[c] = []
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < m and 0 <= ny < n and matrix[nx][ny] != '#':
                    nd = d + 1
                    if nd < dist[nx][ny]:
                        dist[nx][ny] = nd
                        dq.append((nx, ny))
        return -1

import hashlib
import pickle

def hash(obj):
    serialized_obj = pickle.dumps(obj)
    hash_object = hashlib.md5()
    hash_object.update(serialized_obj)
    md5_hash = hash_object.hexdigest()
    return md5_hash

class Solution:
    def groupAnagrams(self, strs: List[str]) -> List[List[str]]:
        res = {}
        for s in strs:
            h = hash(sorted(s))
            if h not in res:
                res[h] = []
            res[h].append(s)
        return res.values()

