class Solution:
    def groupStrings(self, words: List[str]) -> List[int]:
        dsu = DSU()
        seen = Counter()
        for w in words:
            curr = 0
            for c in w:
                c = ord(c) - ord('a')
                curr |= 1 << c
            seen[curr] += 1
        for curr in seen:
            for c in range(26):
                if not curr & (1 << c):
                    if curr | (1 << c) in seen:
                        dsu.union(curr, curr | (1 << c))
                else:
                    without = curr & ~(1 << c)
                    if without in seen:
                        dsu.union(curr, without)
                    for cc in range(26):
                        if without | (1 << cc) in seen:
                            dsu.union(curr, without | (1 << cc))
        comps = defaultdict(int)
        for el in dsu.parent:
            comps[dsu.find(el)] += seen[el]
        return [len(comps), max(comps.values())]

class Solution:
    def maxSatisfied(self, customers: List[int], grumpy: List[int], minutes: int) -> int:
        n = len(customers)
        res = 0
        rem = sum((1 - grumpy[i]) * customers[i] for i in range(n))
        curr = 0
        for i in range(n):
            curr += customers[i]
            rem -= (1 - grumpy[i]) * customers[i]
            if i >= minutes:
                curr -= customers[i - minutes]
                rem += (1 - grumpy[i - minutes]) * customers[i - minutes]
            if i >= minutes - 1:
                res = max(res, curr + rem)
        return res

class Solution:
    def getMoneyAmount(self, n: int) -> int:
        dp = [[0] * n for _ in range(n)]
        get = lambda i, j: 0 if i >= j else dp[i][j]
        for l in range(1, n + 1):
            for i in range(n - l):
                dp[i][i + l] = float('inf')
                for j in range(i, i + l + 1):
                    dp[i][i + l] = min(dp[i][i + l], j + 1 + max(get(i, j - 1), get(j + 1, i + l)))
        return dp[0][n - 1]

class Solution:
    def guessNumber(self, n: int) -> int:
        beg = 1
        end = n
        if guess(beg) == 0:
            return beg
        if guess(end) == 0:
            return end
        while beg <= end:
            mid = (beg + end) // 2
            curr = guess(mid)
            if curr == 0:
                return mid
            elif curr == -1:
                end = mid
            else:
                beg = mid

