from collections import Counter

class Solution:
    def isNStraightHand(self, hand: List[int], groupSize: int) -> bool:
        ctr = Counter(hand)
        vals = sorted(ctr.keys())
        for el in vals:
            if ctr[el] == 0:
                continue
            p = ctr[el]
            for x in range(el, el + groupSize):
                if ctr[x] < p:
                    return False
                ctr[x] -= p
        return True

class SQRT:
    def __init__(self, arr):
        n = len(arr)
        B = int(pow(n, 0.5) + 1)
        blocks = [[set(), set()] for _ in range(B)]
        self.total = 0
        for i in range(n):
            blocks[i // B][arr[i]].add(i % B)
            self.total += arr[i]
        self.B = B
        self.blocks = blocks

    def flip(self, l, r):
        i = l
        while i <= r:
            if i % self.B == 0 and i + self.B - 1 <= r:
                self.total -= len(self.blocks[i // self.B][1])
                self.blocks[i // self.B].reverse()
                self.total += len(self.blocks[i // self.B][1])
                i += self.B
            else:
                if i % self.B in self.blocks[i // self.B][0]:
                    self.blocks[i // self.B][0].remove(i % self.B)
                    self.blocks[i // self.B][1].add(i % self.B)
                    self.total += 1
                else:
                    self.blocks[i // self.B][1].remove(i % self.B)
                    self.blocks[i // self.B][0].add(i % self.B)
                    self.total -= 1
                i += 1

class Solution:
    def handleQuery(self, nums1: List[int], nums2: List[int], queries: List[List[int]]) -> List[int]:
        curr = sum(nums2)
        res = []
        sq = SQRT(nums1)
        for t, x, y in queries:
            if t == 1:
                sq.flip(x, y)
            if t == 2:
                curr += x * sq.total
            if t == 3:
                res.append(curr)
        return res

class Solution:
    def numberOfWays(self, numPeople: int) -> int:
        @lru_cache(maxsize = None)
        def dp(n):
            if n & 1:
                return 0
            if n <= 2:
                return 1
            l = 0
            res = 0
            while n - l >= 2:
                res += dp(l) * dp(n - l - 2)
                res %= 1000000007
                l += 2
            return res
        return dp(numPeople)

class Solution:
    def isHappy(self, n: int) -> bool:
        visited = set()
        while n != 1:
            if n in visited:
                return False
            visited.add(n)
            nn = 0
            while n != 0:
                c = n % 10
                nn += c * c
                n = n // 10
            n = nn
        return True

