    def countWays(self, nums: List[int]) -> int:
        n = len(nums)
        nums.sort()
        res = 0
        i = 0
        for choose in range(n + 1):
            while i < n and nums[i] < choose:
                i += 1
            if i == choose and (i == n or nums[i] > choose):
                res += 1
        return res

class Solution:
    def sumOfTheDigitsOfHarshadNumber(self, x: int) -> int:
        s = 0
        curr = x
        while curr:
            s += curr % 10
            curr //= 10
        if x % s == 0:
            return s
        return -1

class Solution:
    def stringHash(self, s: str, k: int) -> str:
        n = len(s)
        ctr = [0] * (n // k)
        for i in range(n):
            ctr[i // k] += ord(s[i]) - ord('a')
            ctr[i // k] %= 26
        return "".join(chr(ord('a') + c) for c in ctr)

import bisect

class Solution:
    def findRadius(self, houses: List[int], heaters: List[int]) -> int:
        houses.sort()
        heaters.sort()
        n = len(heaters)
        maxclosest = 0
        for h in houses:
            i = bisect.bisect_left(heaters, h)
            mindist = float('inf')
            if 0 <= i < n:
                mindist = min(mindist, abs(h - heaters[i]))
            if i < n - 1:
                mindist = min(mindist, abs(h - heaters[i + 1]))
            if i > 0:
                mindist = min(mindist, abs(h - heaters[i - 1]))
            maxclosest = max(maxclosest, mindist)
        return maxclosest

