#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def maxRob(self, root: Optional[TreeNode], pos, canLoot = True) -> int:
        if (pos, canLoot) in self.cache:
            return self.cache[(pos, canLoot)]
        maxLoot = 0
        if root:
            if canLoot:
                l = self.maxRob(root.left, 2 * pos, canLoot = False)
                r = self.maxRob(root.right, 2 * pos + 1, canLoot = False)
                maxLoot = max(maxLoot, root.val + l + r)
            l = self.maxRob(root.left, 2 * pos, canLoot = True)
            r = self.maxRob(root.right, 2 * pos + 1, canLoot = True)
            maxLoot = max(maxLoot, l + r)
        self.cache[(pos, canLoot)] = maxLoot
        return maxLoot

    def rob(self, root: Optional[TreeNode], canLoot = True) -> int:
        self.cache = {}
        return self.maxRob(root, 1, canLoot = True)

class Solution:
    def possible(self, nums, cap, k):
        n = len(nums)
        prev = False
        rem = k
        for el in nums:
            if not prev and el <= cap:
                prev = True
                rem -= 1
            else:
                prev = False
        return rem <= 0

    def minCapability(self, nums: List[int], k: int) -> int:
        beg = 0
        end = max(nums)
        res = end
        while beg <= end:
            mid = (beg + end) // 2
            if self.possible(nums, mid, k):
                res = mid
                end = mid - 1
            else:
                beg = mid + 1
        return res

class Solution:
    def rob(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return nums[0]
        dp = [0] * n
        dp[0] = nums[0]
        dp[1] = max(nums[0], nums[1])
        for i in range(2, n):
            dp[i] = max(dp[i - 2] + nums[i], dp[i - 1])
        return dp[-1]

import bisect

class Solution:
    def smallerNumbersThanCurrent(self, nums: List[int]) -> List[int]:
        n = len(nums)
        ans = [0] * n
        order = sorted([(num, i) for i, num in enumerate(nums)])
        for i in range(n):
            pos = bisect.bisect_left(order, (order[i][0], float('-inf')))
            ans[order[i][1]] = i - max(i - pos, 0)
        return ans

