from collections import Counter

class Solution:
    def largestOverlap(self, img1: List[List[int]], img2: List[List[int]]) -> int:
        n = len(img1)
        ctr = Counter()
        a = []
        b = []
        for i in range(n):
            for j in range(n):
                if img1[i][j] == 1:
                    a.append((i, j))
                if img2[i][j] == 1:
                    b.append((i, j))
        for x0, y0 in a:
            for x1, y1 in b:
                ctr[(x1 - x0, y1 - y0)] += 1
        if len(ctr) == 0:
            return 0
        return max(ctr.values())

class Solution:
    def getNeighbors(self, row, col, m, n):
        neighbors = []
        for i in range(row - 1, row + 2):
            for j in range(col - 1, col + 2):
                if i == row and j == col:
                    continue
                if i < 0 or i >= m:
                    continue
                if j < 0 or j >= n:
                    continue
                neighbors.append((i, j))
        return neighbors

    def imageSmoother(self, img: List[List[int]]) -> List[List[int]]:
        imgcp = [row[:] for row in img]
        m = len(img)
        n = len(img[0])
        for i in range(m):
            for j in range(n):
                nb = self.getNeighbors(i, j, m, n)
                total = sum([imgcp[a][b] for a, b in nb]) + imgcp[i][j]
                num = len(nb) + 1
                img[i][j] = int(total/num)
        return img

class MyQueue:
    def __init__(self):
        self.a = []
        self.b = []

    def push(self, x: int) -> None:
        self.a.append(x)

    def pop(self) -> int:
        self.peek()
        return self.b.pop()

    def peek(self) -> int:
        if len(self.b) == 0:
            while len(self.a) > 0:
                self.b.append(self.a.pop())
        return self.b[-1]

    def empty(self) -> bool:
        return len(self.a) + len(self.b) == 0

