class Node:
    def __init__(self):
        self.child = {}
        self.end = False

class Trie:
    def __init__(self):
        self.root = Node()

    def check(self, s):
        curr = self.root
        for c in s:
            if c not in curr.child:
                return None
            curr = curr.child[c]
        return curr

    def insert(self, word: str) -> None:
        curr = self.root
        for c in word:
            if c not in curr.child:
                curr.child[c] = Node()
            curr = curr.child[c]
        curr.end = True

    def search(self, word: str) -> bool:
        res = self.check(word)
        return res and res.end

    def startsWith(self, prefix: str) -> bool:
        res = self.check(prefix)
        return bool(res)

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def insert(self, root, key):
        if root:
            if key <= root.val:
                root.left = self.insert(root.left, key)
            else:
                root.right = self.insert(root.right, key)
        else:
            root = TreeNode(val = key)
        return root

    def insort(self, root):
        if root:
            self.insort(root.left)
            self.newroot = self.insert(self.newroot, root.val)
            self.insort(root.right)

    def increasingBST(self, root: TreeNode) -> TreeNode:
        self.newroot = None
        self.insort(root)
        return self.newroot

class Solution:
    def getSeq(self, nums, i, n):
        if i >= n:
            return [[]]
        op = []
        used = set()
        for j in range(i + 1, n):
            if nums[j] >= nums[i] and nums[j] not in used:
                val = self.getSeq(nums, j, n)
                op += [[nums[i], nums[j]]]
                op += [[nums[i]] + v for v in val]
                used.add(nums[j])
        return op

    def findSubsequences(self, nums: List[int]) -> List[List[int]]:
        n = len(nums)
        op = []
        used = set()
        for i in range(n):
            if nums[i] not in used:
                op += self.getSeq(nums, i, n)
                used.add(nums[i])
        return op

class Solution:
    def increasingTriplet(self, nums: List[int]) -> bool:
        n = len(nums)
        biggest = [float('-inf')] * (n + 1)
        for i in range(n - 1, -1, -1):
            biggest[i] = max(nums[i], biggest[i + 1])
        minyet = float('inf')
        for i in range(n):
            if minyet < nums[i] < biggest[i + 1]:
                return True
            minyet = min(minyet, nums[i])
        return False

class Solution:
    def rangeAddQueries(self, n: int, queries: List[List[int]]) -> List[List[int]]:
        mat = [[0] * (n + 1) for _ in range(n)]
        for a, b, c, d in queries:
            for i in range(a, c + 1):
                mat[i][b] += 1
                mat[i][d + 1] -= 1
        for i in range(n):
            for j in range(1, n + 1):
                mat[i][j] += mat[i][j - 1]
        for i in range(n):
            mat[i].pop()
        return mat

import bisect
import random

class RandomizedCollection:

    def __init__(self):
        self.items = []

    def exists(self, val):
        i = bisect.bisect_left(self.items, val)
        return i < len(self.items) and self.items[i] == val

    def insert(self, val: int) -> bool:
        if not self.exists(val):
            bisect.insort(self.items, val)
            return True
        bisect.insort(self.items, val)
        return False

    def remove(self, val: int) -> bool:
        if self.exists(val):
            del self.items[bisect.bisect_left(self.items, val)]
            return True
        return False

    def getRandom(self) -> int:
        return random.choice(self.items)


