import random

class RandomizedSet:

    def __init__(self):
        self.vals = []
        self.pos = {}

    def insert(self, val: int) -> bool:
        if val not in self.pos:
            self.vals.append(val)
            self.pos[val] = len(self.vals) - 1
            return True
        return False

    def remove(self, val: int) -> bool:
        if val in self.pos:
            i = self.pos[val]
            self.pos[self.vals[-1]] = i
            del self.pos[val]
            self.vals[i], self.vals[-1] = self.vals[-1], self.vals[i]
            self.vals.pop()
            return True
        return False

    def getRandom(self) -> int:
        return self.vals[random.randint(0, len(self.vals) - 1)]

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

class Solution:
    def insertGreatestCommonDivisors(self, head: Optional[ListNode]) -> Optional[ListNode]:
        curr = head
        while curr and curr.next:
            node = ListNode(gcd(curr.val, curr.next.val))
            curr.next, node.next = node, curr.next
            curr = curr.next.next
        return head

