class Solution:
    def insert(self, intervals: List[List[int]], newInterval: List[int]) -> List[List[int]]:
        bisect.insort(intervals, newInterval)
        n = len(intervals)
        i = 0
        while i < len(intervals) - 1:
            if intervals[i][1] >= intervals[i + 1][0]:
                if intervals[i][1] <= intervals[i + 1][1]:
                    intervals[i][1] = intervals[i + 1][1]
                intervals.pop(i + 1)
            else:
                i += 1
        return intervals

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def insertIntoBST(self, root: Optional[TreeNode], val: int) -> Optional[TreeNode]:
        if root:
            if val > root.val:
                root.right = self.insertIntoBST(root.right, val)
            else:
                root.left = self.insertIntoBST(root.left, val)
            return root
        else:
            return TreeNode(val=val)

class Solution:
    def clean(self, root, curr, limit):
        if not root:
            return (None, float('-inf'))
        root.left, lsum = self.clean(root.left, curr + root.val, limit)
        root.right, rsum = self.clean(root.right, curr + root.val, limit)
        p = max(lsum, rsum)
        if p == float('-inf'):
            p = 0
        msum = root.val + p
        if curr + msum < limit:
            return (None, msum)
        return (root, msum)

    def sufficientSubset(self, root: Optional[TreeNode], limit: int) -> Optional[TreeNode]:
        return self.clean(root, 0, limit)[0]

class Solution:
    def integerBreak(self, n: int) -> int:
        if n == 2:
            return 1
        if n == 3:
            return 2
        res = 1
        while n % 3 != 0:
            res *= 2
            n -= 2
        res *= pow(3, n // 3)
        return res

class Solution:
    def integerReplacement(self, n: int) -> int:
        if n == 1:
            return 0
        if n == 3:
            return 2
        if n & 1:
            if (n + 1) & 3 == 0:
                return 3 + self.integerReplacement((n + 1) >> 2)
            else:
                return 2 + self.integerReplacement((n - 1) >> 1)
        else:
            return 1 + self.integerReplacement(n >> 1)

class Solution:
    def threeDigit(self, num):
        res = []
        for x in [2, 1, 0]:
            pw = 10 ** x
            if num // pw:
                if x == 2:
                    res.append(f"{self.ones[num // pw]} hundred")
                if x == 1:
                    if num // pw == 1:
                        res.append(self.tenToNineteen[num % pw])
                        break
                    else:
                        res.append(self.hundreds[num // pw])
                if x == 0:
                    res.append(self.ones[num // pw])
            num -= pw * (num // pw)
        return " ".join(res)

    def numberToWords(self, num: int) -> str:
        self.hundreds = ["", "ten", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
        self.tenToNineteen = ["ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
        self.ones = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
        capitalize = lambda s: " ".join(w[0].upper() + w[1:] for w in s.split())
        res = []
        for x in [9, 6, 3, 0]:
            pw = 10 ** x
            if num // pw:
                if x == 9:
                    res.append(f"{self.threeDigit(num // pw)} billion")
                if x == 6:
                    res.append(f"{self.threeDigit(num // pw)} million")
                if x == 3:
                    res.append(f"{self.threeDigit(num // pw)} thousand")
                if x == 0:
                    res.append(f"{self.threeDigit(num // pw)}")
            num -= pw * (num // pw)
        return capitalize(" ".join(res) or "zero")

class Solution:
    def intToRoman(self, num: int) -> str:
        sym = {
            1: "I",
            5: "V",
            10: "X",
            50: "L",
            100: "C",
            500: "D",
            1000: "M"
        }
        keys = list(sym.keys())
        k = len(keys)
        vals = []
        i = 1
        while num > 0:
            curr = num % (10 ** i)
            vals.insert(0, curr)
            num -= curr
            i += 1
        op = ""
        curr = 0
        while curr < len(vals):
            v = vals[curr]
            if v in sym:
                op += sym[v]
            else:
                found = False
                for i in range(k):
                    for j in range(i + 1, k):
                        if v == keys[j] - keys[i]:
                            found = True
                            op += sym[keys[i]] + sym[keys[j]]
                            break
                if not found:
                    for key in keys[::-1]:
                        if v > key:
                            op += sym[key] * (v // key)
                            vals.insert(curr + 1, v % key)
                            break
            curr += 1
        return op

class Solution:
    def isLeave(self, s1, s2, s3, i, j, k, m, n, p):
        if (i, j, k) in self.cache:
            return self.cache[(i,j,k)]
        if i >= m or j >= n or k >= p:
            if i >= m:
                res = s2[j:] == s3[k:]
                self.cache[(i,j,k)] = res
                return res
            if j >= n:
                res = s1[i:] == s3[k:]
                self.cache[(i,j,k)] = res
                return res
            self.cache[(i,j,k)] = False
            return False
        if s1[i] == s3[k] and self.isLeave(s1, s2, s3, i + 1, j, k + 1, m, n, p):
            self.cache[(i,j,k)] = True
            return True
        if s2[j] == s3[k] and self.isLeave(s1, s2, s3, i, j + 1, k + 1, m, n, p):
            self.cache[(i,j,k)] = True
            return True
        self.cache[(i,j,k)] = False
        return False

    def isInterleave(self, s1: str, s2: str, s3: str) -> bool:
        m = len(s1)
        n = len(s2)
        p = len(s3)
        self.cache = {}
        return self.isLeave(s1, s2, s3, 0, 0, 0, m, n, p)

