# Definition for singly-linked list.
# class ListNode:
#     def __init__(self, x):
#         self.val = x
#         self.next = None

class Solution:
    def getIntersectionNode(self, headA: ListNode, headB: ListNode) -> Optional[ListNode]:
        if headA and headB:
            a = headA
            b = headB
            while a != b:
                a = a.next if a else headB
                b = b.next if b else headA
            return a
        else:
            return None

class Solution:
    def intervalIntersection(self, firstList: List[List[int]], secondList: List[List[int]]) -> List[List[int]]:
        points = []
        for a, b in firstList + secondList:
            points.append((a, 1))
            points.append((b + 1, -1))
        points.sort()
        res = []
        p = 0
        for x, d in points:
            p += d
            if p == 2:
                res.append([x, x])
            elif p == 1 and d == -1 and len(res) > 0:
                res[-1][1] = x - 1
        return res

import heapq

class Solution:
    def findMaximizedCapital(self, k: int, w: int, profits: List[int], capital: List[int]) -> int:
        n = len(profits)
        pairs = [(capital[i], profits[i]) for i in range(n)]
        pairs.sort()
        i = 0
        curr = w
        heap = []
        while k > 0:
            while i < n and pairs[i][0] <= curr:
                heapq.heappush(heap, -pairs[i][1])
                i += 1
            if len(heap) > 0:
                curr -= heapq.heappop(heap)
                k -= 1
            else:
                break
        return curr

class Solution:
    def DFS(self, graph, curr, visited, colors):
        for j in graph[curr]:
            if j not in visited:
                visited.add(j)
                colors[j] = not colors[curr]
                if not self.DFS(graph, j, visited, colors):
                    return False
            else:
                if colors[j] == colors[curr]:
                    return False
        return True

    def isBipartite(self, graph: List[List[int]]) -> bool:
        n = len(graph)
        for i in range(n):
            colors = [False for node in graph]
            visited = {i}
            if not self.DFS(graph, i, visited, colors):
                return False
        return True

