        return i == n

class Solution:
    def isEmpty(self, grid, i, j, m, n):
        if i < 0 or j < 0 or i >= m or  j >= n:
            return True
        if grid[i][j] == 1:
            return False
        return True

    def islandPerimeter(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        perimeter = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    for x, y in [(i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)]:
                        if self.isEmpty(grid, x, y, m, n):
                            perimeter += 1
        return perimeter

class Solution:
    def isIsomorphic(self, s: str, t: str) -> bool:
        smap = {}
        tmap = {}
        slist = []
        tlist = []
        i = 0
        for c in s:
            if c not in smap:
                smap[c] = i
                i += 1
            slist.append(smap[c])
        i = 0
        for c in t:
            if c not in tmap:
                tmap[c] = i
                i += 1
            tlist.append(tmap[c])
        return slist == tlist

class Solution:
    def numJewelsInStones(self, jewels: str, stones: str) -> int:
