class Solution:
    def longestValidParentheses(self, s: str) -> int:
        n = len(s)
        stack = [-1]
        mlen = 0
        for i, c in enumerate(s):
            if c == '(':
                stack.append(i)
            elif len(stack) > 0:
                stack.pop()
                if len(stack) > 0:
                    mlen = max(mlen, i - stack[-1])
                else:
                    stack.append(i)
        return mlen

class Solution:
    def findLongestWord(self, s: str, dictionary: List[str]) -> str:
        words = {}
        for word in dictionary:
            if len(word) <= len(s):
                i = 0
                j = 0
                while i < len(word) and j < len(s):
                    if word[i] == s[j]:
                        i += 1
                        j += 1
                    else:
                        j += 1
                if i == len(word):
                    words[len(word)] = words.get(len(word), []) + [word]
        if len(words) == 0:
            return ""
        return min(words[max(words.keys())])

class Solution:
    def longestWord(self, words: List[str]) -> str:
        words = set(words)
        mword = ""
        for word in words:
            n = len(word)
            valid = True
            for i in range(1, n):
                if word[:i] not in words:
                    valid = False
                    break
            if valid:
                if len(word) > len(mword):
                    mword = word
                elif len(word) == len(mword) and word < mword:
                    mword = word
        return mword

class Solution:
    def longestZigZag(self, root: Optional[TreeNode]) -> int:
        self.res = 0
        def inorder(r, l, left):
            if r:
                ll = 1
                rl = 1
                if left:
                    rl = l + 1
                elif left != None:
                    ll = l + 1
                inorder(r.left, ll, True)
                self.res = max(self.res, l)
                inorder(r.right, rl, False)
        inorder(root, 0, None)
        return self.res

class Solution:
    def loudAndRich(self, richer: List[List[int]], quiet: List[int]) -> List[int]:
        n = len(quiet)
        graph = {}
        for a, b in richer:
            graph[b] = graph.get(b, []) + [a]
        answer = [0] * n
        for beg in range(n):
            paths = [beg]
            visited = {beg}
            while len(paths) > 0:
                curr = paths.pop()
                for j in graph.get(curr, []):
                    if j not in visited:
                        visited.add(j)
                        paths.append(j)
            answer[beg] = min(visited, key = lambda p: quiet[p])
        return answer

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, x):
#         self.val = x
#         self.left = None
#         self.right = None

class Solution:
    def lowestCommonAncestor(self, root: 'TreeNode', p: 'TreeNode', q: 'TreeNode') -> 'TreeNode':
        if root:
            if (p.val <= root.val and q.val >= root.val) or (p.val >= root.val and q.val <= root.val):
                return root
            if p.val < root.val and q.val < root.val:
                return self.lowestCommonAncestor(root.left, p, q)
            if p.val > root.val and q.val > root.val:
                return self.lowestCommonAncestor(root.right, p, q)

class Solution:
    def maxDepth(self, root):
        if root:
            a = 1 + self.maxDepth(root.left)
            b = 1 + self.maxDepth(root.right)
            return max(a, b)
        return -1

    def lcaDeepestLeaves(self, root: Optional[TreeNode]) -> Optional[TreeNode]:
        if root:
            left = self.maxDepth(root.left)
            right = self.maxDepth(root.right)
            if left > right:
                return self.lcaDeepestLeaves(root.left)
            elif right > left:
                return self.lcaDeepestLeaves(root.right)
            else:
                return root

class Node:
    def __init__(self, key):
        self.key = key
        self.next = None
        self.prev = None

class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.map = {}
        self.nodemap = {}
        self.head = Node(-1)
        self.tail = Node(-1)
        self.head.next = self.tail
        self.tail.prev = self.head

    def get(self, key: int) -> int:
        if key not in self.map:
            return -1
        newnode = Node(key)
        newnode.next = self.head.next
        self.head.next.prev = newnode
        newnode.prev = self.head
        self.head.next = newnode
        if key in self.nodemap:
            node = self.nodemap[key]
            node.prev.next = node.next
            node.next.prev = node.prev
        self.nodemap[key] = newnode
        curr = self.head
        return self.map[key]

    def put(self, key: int, value: int) -> None:
        if len(self.map) == self.capacity and key not in self.map:
            lrukey = self.tail.prev.key
            if lrukey != -1:
                node = self.nodemap[lrukey]
                node.prev.next = node.next
                node.next.prev = node.prev
                del self.map[lrukey]
                del self.nodemap[lrukey]
        self.map[key] = value
        self.get(key)

class Solution:
    def numMagicSquaresInside(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        res = 0
        for i in range(1, m - 1):
            for j in range(1, n - 1):
                r = [0, 0, 0]
                c = [0, 0, 0]
                a = b = 0
                used = [0] * 9
                for x in range(i - 1, i + 2):
                    a += grid[x][j + x - i]
                    b += grid[x][j - x + i]
                    for y in range(j - 1, j + 2):
                        if 1 <= grid[x][y] <= 9:
                            used[grid[x][y] - 1] = 1
                        r[x - i + 1] += grid[x][y]
                        c[y - j + 1] += grid[x][y]
                if sum(used) == 9 and r[0] == r[1] == r[2] == c[0] == c[1] == c[2] == a == b:
                    res += 1
        return res

class Solution:
    def isPossible(self, position, n, d, m):
        i = 0
        for j in range(n):
            if position[j] - position[i] >= d:
                i = j
                m -= 1
        return m <= 1

    def maxDistance(self, position: List[int], m: int) -> int:
        n = len(position)
        position.sort()
        d = 1
        while self.isPossible(position, n, d, m):
            d = 2 * d
        beg = d // 2
        end = d
        res = beg
        while beg <= end:
            mid = (beg + end) // 2
            if self.isPossible(position, n, mid, m):
                res = mid
                beg = mid + 1
            else:
                end = mid - 1
        return res

from collections import Counter

class Solution:
    def majorityElement(self, nums: List[int]) -> List[int]:
