class Solution:
    def minops(self, arr, i, n, prev, mp):
        if i >= n:
            return 0
        key = (i, prev)
        if key in self.cache:
            return self.cache[key]
        res = float('inf')
        if arr[i] > prev:
            res = min(res, self.minops(arr, i + 1, n, arr[i], mp))
        if prev in mp:
            res = min(res, 1 + self.minops(arr, i + 1, n, mp[prev], mp))
        self.cache[key] = res
        return res

    def makeArrayIncreasing(self, arr1: List[int], arr2: List[int]) -> int:
        m = len(arr1)
        n = len(arr2)
        arr2.sort()
        mp = {}
        i = 0
        for el in sorted(arr1 + arr2 + [-1]):
            while i < n and arr2[i] <= el:
                i += 1
            if i < n:
                mp[el] = arr2[i]
        self.cache = {}
        res = self.minops(arr1, 0, m, -1, mp)
        if res == float('inf'):
            return -1
        return res

class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        n = len(nums)
        nums.sort()
        curr = 0
        res = 0
        for i in range(n):
            if nums[i] > curr:
                res += 1
                curr = nums[i]
        return res

class Solution:
    def minIncrements(self, n: int, cost: List[int]) -> int:
        def solve(i):
            if i > n:
                return 0, 0
            lcost, lsum = solve(2 * i)
            rcost, rsum = solve(2 * i + 1)
            return lcost + rcost + abs(lsum - rsum), cost[i - 1] + max(lsum, rsum)
        return solve(1)[0]

class Solution:
    def makeSubKSumEqual(self, arr: List[int], k: int) -> int:
        n = len(arr)
        res = 0
        v = [False] * n
        for i in range(n):
            curr = []
            while not v[i]:
                curr.append(arr[i])
                v[i] = True
                i += k
                i %= n
            curr.sort()
            for el in curr:
                res += abs(el - curr[len(curr) // 2])
        return res

from collections import Counter

class Solution:
    def numdist(self, ctr):
        res = 0
        for i in range(26):
            if ctr[chr(ord('a') + i)] > 0:
                res += 1
        return res

    def isItPossible(self, word1: str, word2: str) -> bool:
        ctr1 = Counter(word1)
        ctr2 = Counter(word2)
        for i in range(26):
            for j in range(26):
                c1 = chr(ord('a') + i)
                c2 = chr(ord('a') + j)
                if ctr1[c1] > 0 and ctr2[c2] > 0:
                    ctr1[c1] -= 1
                    ctr2[c1] += 1
                    ctr2[c2] -= 1
                    ctr1[c2] += 1
                    if self.numdist(ctr1) == self.numdist(ctr2):
                        return True
                    ctr1[c1] += 1
                    ctr2[c1] -= 1
                    ctr2[c2] += 1
                    ctr1[c2] -= 1
        return False

class Solution:
    def canMakeSubsequence(self, a: str, b: str) -> bool:
        m = len(a)
        n = len(b)
        def get(c):
            c = ord(c) - ord('a')
            c += 25
            c %= 26
            return chr(ord('a') + c)
        nxt = {}
        nxts = [-1] * (m + 1)
        for i in range(m - 1, -1, -1):
            nxts[i] = dict(nxt)
            nxt[a[i]] = i
        nxts[-1] = nxt
        prev = -1
        for c in b:
            x = nxts[prev].get(c, m)
            y = nxts[prev].get(get(c), m)
            prev = min(x, y)
            if prev == m:
                return False
        return True

class Solution:
    def minSubarray(self, nums: List[int], p: int) -> int:
        n = len(nums)
        k = sum(nums) % p
        if k == 0:
            return 0
        pf = [0] * (n + 1)
        for i in range(n):
            pf[i + 1] = (pf[i] + nums[i]) % p
        res = float('inf')
        lastpos = {}
        for i in range(n + 1):
            prev = pf[i] - k
            if prev < 0:
                prev += p
            if prev in lastpos:
                res = min(res, i - lastpos[prev])
            lastpos[pf[i]] = i
        if res > n - 1:
            return -1
        return res

class Solution:
    def makeGood(self, s: str) -> str:
        i = 0
        while i < len(s) - 1:
            if (s[i].isupper() ^ s[i + 1].isupper()) and s[i].lower() == s[i + 1].lower():
                s = s[:i] + s[i + 2:]
                i = max(i - 1, 0)
            else:
                i += 1
        return s

class Solution:
    def findMinimumOperations(self, s1: str, s2: str, s3: str) -> int:
        k = 0
        while k < min(len(s1), len(s2), len(s3)) and s1[k] == s2[k] == s3[k]:
            k += 1
        if k == 0:
            return -1
        return len(s1) + len(s2) + len(s3) - 3 * k

class Solution:
    def canBeEqual(self, target: List[int], arr: List[int]) -> bool:
        return sorted(arr) == sorted(target)

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, a):
        if a == self.parent[a]:
            return a
        self.parent[a] = self.find(self.parent[a])
        return self.parent[a]

    def union(self, a, b):
        parent_a = self.find(a)
        parent_b = self.find(b)
        if parent_a != parent_b:
            if self.size[parent_a] < self.size[parent_b]:
                parent_a, parent_b = parent_b, parent_a
            self.parent[parent_b] = parent_a
            self.size[parent_a] += self.size[parent_b]

class Solution:
    def largestIsland(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        dsu = DSU(m * n)
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 0:
                    continue
                for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
                    if 0 <= x < m and 0 <= y < n and grid[x][y] == 1:
                        dsu.union(m * i + j, m * x + y)
        res = max(dsu.size)
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    continue
                sizes = {}
                for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
                    if 0 <= x < m and 0 <= y < n and grid[x][y] == 1:
                        sizes[dsu.find(m * x + y)] = dsu.size[dsu.find(m * x + y)]
                res = max(res, 1 + sum(sizes.values()))
        return res

class Solution:
    def highestPeak(self, isWater):
        m, n = len(isWater), len(isWater[0])
        dist = [[-1 for _ in range(n)] for _ in range(m)]
        queue = deque()
        for i in range(m):
            for j in range(n):
                if isWater[i][j] == 1:
                    dist[i][j] = 0
                    queue.append((i, j))
        while queue:
            x, y = queue.popleft()
            for nx, ny in [(x-1,y), (x+1,y), (x,y-1), (x,y+1)]:
                if 0 <= nx < m and 0 <= ny < n and dist[nx][ny] == -1:
                    dist[nx][ny] = dist[x][y] + 1
                    queue.append((nx, ny))
        return dist

class Node:
    def __init__(self):
        self.child = {}
        self.total = 0
        self.end = False

class MapSum:
    def __init__(self):
        self.root = Node()
        self.val = {}

    def exists(self, s):
        curr = self.root
        for c in key:
            if c not in curr.child:
                return False
            curr = curr.child[c]
        return curr.end

    def insert(self, key: str, val: int) -> None:
        self.val[key], val = val, val - self.val.get(key, 0)
        curr = self.root
        curr.total += val
        for c in key:
            if c not in curr.child:
                curr.child[c] = Node()
            curr = curr.child[c]
            curr.total += val
        curr.end = True

    def sum(self, prefix: str) -> int:
        curr = self.root
        for c in prefix:
            if c not in curr.child:
                return 0
            curr = curr.child[c]
        return curr.total

from collections import defaultdict
import re

class Solution:
    def matchReplacement(self, s: str, sub: str, mappings: List[List[str]]) -> bool:
        reachable = defaultdict(set)
        for a, b in mappings:
            reachable[a].add(b)
        for c in sub:
            reachable[c].add(c)
        regex = ""
        for c in sub:
            if len(reachable[c]) > 1:
                regex += "("
                regex += "|".join(reachable[c])
                regex += ")"
            else:
                regex += c
        return re.compile(regex).search(s)

class Solution:
    def isPossible(self, i, sides, matchsticks, n, total):
        if i >= n:
            return len(set(sides)) == 1
        key = tuple(sorted(sides) + [i])
        if key in self.cache:
            return self.cache[key]
        for j in range(4):
            if 4 * (sides[j] + matchsticks[i]) > total:
                continue
            sides[j] += matchsticks[i]
            curr = self.isPossible(i + 1, sides, matchsticks, n, total)
            if curr:
                self.cache[key] = True
                return True
            else:
                sides[j] -= matchsticks[i]
        self.cache[key] = False
        return False

    def makesquare(self, matchsticks: List[int]) -> bool:
        matchsticks.sort(reverse = True)
        n = len(matchsticks)
        total = sum(matchsticks)
        self.cache = {}
        sides = [0, 0, 0, 0]
        return self.isPossible(0, sides, matchsticks, n, total)

class Solution:
    def allCellsDistOrder(self, rows: int, cols: int, rCenter: int, cCenter: int) -> List[List[int]]:
        return sorted([[i, j] for i in range(rows) for j in range(cols)], key = lambda p: abs(p[0] - rCenter) + abs(p[1] - cCenter))

class Solution:
    def diagonalSum(self, mat: List[List[int]]) -> int:
        n = len(mat)
        total = -mat[n//2][n//2] if n & 1 else 0
        for i in range(n):
            total += mat[i][i] + mat[i][n-i-1]
        return total

class Solution:
    def areSimilar(self, mat: List[List[int]], k: int) -> bool:
        k %= len(mat[0])
        for i in range(len(mat)):
            curr = mat[i][:]
            curr[:k] = curr[:k][::-1]
            curr[k:] = curr[k:][::-1]
            curr[:] = curr[::-1]
            if curr != mat[i]:
                return False
            k = len(mat[0]) - k
        return True

class Solution:
    def DFS(self, grid, i, j, m, n):
        if i >= 0 and j >= 0 and i < m and j < n and grid[i][j] == 1:
            grid[i][j] = 0
            self.ctr += 1
            for x, y in [(i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)]:
                self.DFS(grid, x, y, m, n)

    def maxAreaOfIsland(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        mArea = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    self.ctr = 0
                    self.DFS(grid, i, j, m, n)
                    mArea = max(mArea, self.ctr)
        return mArea

class Solution:
    def maxChunksToSorted(self, arr: List[int]) -> int:
        n = len(arr)
        sf = [float('inf')] * (n + 1)
        for i in range(n - 1, -1, -1):
            sf[i] = min(sf[i + 1], arr[i])
        res = 0
        i = 0
        while i < n:
            mx = float('-inf')
            while i < n and max(mx, arr[i]) > sf[i + 1]:
                mx = max(mx, arr[i])
                i += 1
            i += 1
            res += 1
        return res

class Solution:
    def maxChunksToSorted(self, arr: List[int]) -> int:
        n = len(arr)
        res = 0
        prev = -1
        for i in range(n):
            j =  n - 1
            while j > i and arr[j] >= arr[i]:
                j -= 1
            if i > prev:
                res += 1
            prev = max(prev, j)
        return res

class Solution:
    def longestOnes(self, nums: List[int], k: int) -> int:
        n = len(nums)
        p = [0]
        for el in nums:
            p.append(p[-1] + el)
        res = 0
        i = 0
        zeroes = lambda x, y: y - x + 1 - p[y + 1] + p[x]
        for j in range(n):
            while i < j and zeroes(i, j) > k:
                i += 1
            if zeroes(i, j) <= k:
                res = max(res, j - i + 1)
        return res

class Solution:
    def findMaxConsecutiveOnes(self, nums: List[int]) -> int:
        nums.append(-1)
        maxOnes = 0
        curr = 0
        for num in nums:
            if num <= 0:
                maxOnes = max(maxOnes, curr)
                curr = 0
            else:
                curr += 1
        return maxOnes

class Solution:
    def maxDiff(self, num: int) -> int:
        def remap(v, mp):
            return int(''.join(mp[1] if c == mp[0] else c for c in v))
        num = str(num)
        i = 0
        while i < len(num) and num[i] == '9':
            i += 1
        mx = ('9', '9')
        if i < len(num):
            mx = (num[i], '9')
        i = 0
        while i < len(num) and int(num[i]) <= 1:
            i += 1
        mn = ('0', '0')
        if i < len(num):
            mn = (num[i], '0')
        if int(num[0]) > 1:
            mn = (num[0], '1')
        return remap(num, mx) - remap(num, mn)

class Solution:
    def maxp(self, a, b, i, j, empty, m, n):
        if i >= m or j >= n:
            if empty:
                return float('-inf')
            return 0
        key = (i, j, empty)
        if key in self.cache:
            return self.cache[key]
        x = self.maxp(a, b, i + 1, j, empty, m, n)
        y = self.maxp(a, b, i, j + 1, empty, m, n)
        z = a[i] * b[j] + self.maxp(a, b, i + 1, j + 1, False, m, n)
        res = max(x, y, z)
        self.cache[key] = res
        return res

    def maxDotProduct(self, nums1: List[int], nums2: List[int]) -> int:
        self.cache = {}
        return self.maxp(nums1, nums2, 0, 0, True, len(nums1), len(nums2))

class Solution:
    def maxIncreaseKeepingSkyline(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        rowmax = [0] * m
        colmax = [0] * n
        for i in range(m):
            for j in range(n):
                rowmax[i] = max(rowmax[i], grid[i][j])
                colmax[j] = max(colmax[j], grid[i][j])
        res = 0
        for i in range(m):
            for j in range(n):
                res += min(rowmax[i], colmax[j]) - grid[i][j]
        return res

from collections import Counter

class Solution:
    def maxOperations(self, nums: List[int], k: int) -> int:
        pairs = 0
        ctr = Counter(nums)
        for num in ctr:
            if 2 * num <= k and (k - num) in ctr:
                a = ctr[num]
                b = ctr[k - num]
                if 2 * num == k:
                    pairs += a // 2
                else:
                    pairs += min(a, b)
        return pairs

class Solution:
    def maxSum(self, nums: List[int]) -> int:
        n = len(nums)
        res = -1
        for i in range(n):
            for j in range(i + 1, n):
                x = max(str(nums[i]))
                y = max(str(nums[j]))
                if x == y:
                    res = max(res, nums[i] + nums[j])
        return res

from collections import defaultdict

class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        sums = defaultdict(list)
        for el in nums:
            curr = sum(int(d) for d in str(el))
            sums[curr].append(el)
        msum = -1
        for el in sums:
            if len(sums[el]) > 1:
                currmax = sorted(sums[el])
                msum = max(msum, currmax[-1] + currmax[-2])
        return msum

from sortedcontainers import SortedList

class Solution:
    def maxSub(self, arr, m, k):
        msum = float('-inf')
        bst = SortedList()
        bst.add(0)
        c = 0
        for i in range(m):
            c += arr(i)
            prev = bst.bisect_left(c - k)
            if prev < len(bst):
                msum = max(msum, c - bst[prev])
            bst.add(c)
        return msum

    def maxSumSubmatrix(self, matrix, k):
        m = len(matrix)
        n = len(matrix[0])
        res = float('-inf')
        p = [[0] for _ in range(m)]
        for i in range(m):
            for j in range(n):
                p[i].append(p[i][-1] + matrix[i][j])
        for i in range(n + 1):
            for j in range(n - 1, i - 1, -1):
                arr = lambda x: p[x][j + 1] - p[x][i]
                res = max(res, self.maxSub(arr, m, k))
                if res == k:
                    break
        return res

from collections import deque

class Stack:
    def __init__(self, init, func):
        self.stack = deque([(init, init)])
        self.func = func

    def push(self, val):
        top, topfunc = self.stack[-1]
        self.stack.append((val, self.func(topfunc, val)))

    def empty(self):
        return len(self.stack) <= 1

    def size(self):
        return len(self.stack) - 1

    def pop(self):
        if not self.empty():
            top, topfunc = self.stack.pop()
            return top

    def funcval(self):
        top, topfunc = self.stack[-1]
        return topfunc

class Queue:
    def __init__(self, init, func):
        self.func = func
        self.f = Stack(init, func)
        self.s = Stack(init, func)

    def push(self, val):
        self.f.push(val)

    def empty(self):
        return self.f.empty() and self.s.empty()

    def size(self):
        return self.f.size() + self.s.size()

    def pop(self):
        if self.s.empty():
            while not self.f.empty():
                self.s.push(self.f.pop())
        if not self.s.empty():
            return self.s.pop()

    def funcval(self):
        return self.func(self.f.funcval(), self.s.funcval())

class Solution:
    def findMaxValueOfEquation(self, points: List[List[int]], k: int) -> int:
        n = len(points)
        res = float('-inf')
        q = Queue(float('-inf'), max)
        i = 0
        for x, y in points:
            while i < n and x - points[i][0] > k:
                q.pop()
                i += 1
            res = max(res, x + y + q.funcval())
            q.push(y - x)
        return res

from collections import defaultdict

class Solution:
    def maximalNetworkRank(self, n: int, roads: List[List[int]]) -> int:
        l = len(roads)
        edges = defaultdict(set)
        for k in range(l):
            a, b = roads[k]
            edges[a].add(k)
            edges[b].add(k)
        mnetwork = 0
        for i in range(n):
            for j in range(i + 1, n):
                mnetwork = max(mnetwork, len(set.union(edges[i], edges[j])))
        return mnetwork

class Solution:
    def maximumLengthOfRanges(self, nums: List[int]) -> List[int]:
        res = {}
        n = len(nums)
        stack = []
        nxt = [n] * n
        prv = [-1] * n
        for i in range(n):
            while len(stack) > 0 and nums[i] > nums[stack[-1]]:
                curr = stack.pop()
                nxt[curr] = i
            if len(stack) > 0:
                prv[i] = stack[-1]
            stack.append(i)
        for i in range(n):
            res[nums[i]] = max(res.get(nums[i], 1), nxt[i] - prv[i] - 1)
        return [res[el] for el in nums]

class Solution:
    def prevlowest(self, arr, n):
        prevlow = [-1 for i in range(n)]
        stack = []
        for i in range(n):
            while len(stack) > 0 and arr[i] <= arr[stack[-1]]:
                curr = stack.pop()
            if len(stack) > 0:
                prevlow[i] = stack[-1]
            stack.append(i)
        return prevlow

    def largestRectangleArea(self, heights: List[int]) -> int:
        n = len(heights)
        next_lowest = [n for i in range(n)]
        prev_lowest = [-1 for i in range(n)]
        maxArea = 0
        inc_stack = []
        for i in range(n):
            while len(inc_stack) > 0 and heights[i] < heights[inc_stack[-1]]:
                curr = inc_stack.pop()
                next_lowest[curr] = i
            if len(inc_stack) > 0:
                prev_lowest[i] = inc_stack[-1]
            inc_stack.append(i)
        for i in range(n):
            currArea = (next_lowest[i] - prev_lowest[i] - 1) * heights[i]
            maxArea = max(maxArea, currArea)
        return maxArea

    def maximalRectangle(self, matrix: List[List[str]]) -> int:
        m = len(matrix)
        n = len(matrix[0])
        prev = [self.prevlowest(matrix[i], n) for i in range(m)]
        mrec = 0
        for i in range(n):
            curr = self.largestRectangleArea([(i - prev[j][i]) if matrix[j][i] == "1" else 0 for j in range(m)])
            mrec = max(mrec, curr)
        return mrec

class Solution:
    def maximalSquare(self, matrix: List[List[str]]) -> int:
        m = len(matrix)
        n = len(matrix[0])
        biggest = 0
        for i in range(m):
            for j in range(n):
                for w in range(biggest, min(m - i, n - j) + 1):
                    valid = True
                    for p in range(w):
                        for q in range(w):
                            if matrix[i + p][j + q] != "1":
                                valid = False
                                break
                        if not valid:
                            break
                    if valid:
                        biggest = max(biggest, w)
                    else:
                        break
        return biggest * biggest

from collections import defaultdict
import heapq

class Solution:
    def maxAmount(self, initialCurrency: str, pairs1: List[List[str]], rates1: List[float], pairs2: List[List[str]], rates2: List[float]) -> float:
        graph = defaultdict(set)
        for i in range(len(pairs1)):
            graph[(pairs1[i][0], 0)].add((pairs1[i][1], 0, rates1[i]))
            graph[(pairs1[i][1], 0)].add((pairs1[i][0], 0, 1 / rates1[i]))
        for i in range(len(pairs2)):
            graph[(pairs2[i][0], 1)].add((pairs2[i][1], 1, rates2[i]))
            graph[(pairs2[i][1], 1)].add((pairs2[i][0], 1, 1 / rates2[i]))
        for curr in list(graph):
            graph[(curr[0], 0)].add((curr[0], 1, 1))
        dist = defaultdict(lambda: float('-inf'))
        heap = [(-1, initialCurrency, 0)]
        dist[(initialCurrency, 0)] = 1
        res = 1
        while heap:
            d, curr, day = heapq.heappop(heap)
            d = -d
            if curr == initialCurrency:
                res = max(res, d)
            for j, jd, jr in graph[(curr, day)]:
                if dist[(j, jd)] < d * jr:
                    dist[(j, jd)] = d * jr
                    heapq.heappush(heap, (-dist[(j, jd)], j, jd))
        return res

class Solution:
    def maximizeSquareHoleArea(self, n: int, m: int, hBars: List[int], vBars: List[int]) -> int:
        hBars.sort()
        vBars.sort()
        i = 0
        maxV = 1
        while i < len(vBars):
            ctr = 1
            while i < len(vBars) - 1 and vBars[i + 1] == vBars[i] + 1:
                ctr += 1
                i += 1
            maxV = max(maxV, ctr + 1)
            i += 1
        i = 0
        maxH = 1
        while i < len(hBars):
            ctr = 1
            while i < len(hBars) - 1 and hBars[i + 1] == hBars[i] + 1:
                ctr += 1
                i += 1
            maxH = max(maxH, ctr + 1)
            i += 1
        return min(maxV, maxH) * min(maxV, maxH)

from collections import *

class Solution:
    def maxSelectedElements(self, nums: List[int]) -> int:
        nums = sorted(Counter(nums).items(), reverse = True)
        res = 1
        dp = defaultdict(int)
        for el, f in nums:
            if f == 1:
                dp[el] = max(dp[el], 1 + dp[el + 1])
                dp[el + 1] = max(dp[el + 1], 1 + dp[el + 2])
            else:
                dp[el] = max(dp[el], 1 + dp[el + 1], 2 + dp[el + 2])
                dp[el + 1] = max(dp[el + 1], 1 + dp[el + 2])
        for el in dp:
            res = max(res, dp[el])
        return res

N = 100000
is_prime = [True] * (N + 1)
is_prime[0] = is_prime[1] = False
for i in range(2, int(N**0.5) + 1):
    if is_prime[i]:
        for j in range(i * i, N + 1, i):
            is_prime[j] = False

class LazySegmentTree:
    def __init__(self, data, default=0, func=max):
        self._default = default
        self._func = func
        self._len = len(data)
        self._size = 1 << (self._len - 1).bit_length()
        self._lazy = [0] * (2 * self._size)
        self.data = [default] * (2 * self._size)
        self.data[self._size:self._size + self._len] = data
        for i in range(self._size - 1, 0, -1):
            self.data[i] = func(self.data[2 * i], self.data[2 * i + 1])

    def _push(self, idx):
        q = self._lazy[idx]
        if q:
            self._lazy[2 * idx] += q
            self._lazy[2 * idx + 1] += q
            self.data[2 * idx] += q
            self.data[2 * idx + 1] += q
            self._lazy[idx] = 0

    def _update(self, idx):
        for h in range(idx.bit_length() - 1, 0, -1):
            self._push(idx >> h)

    def _build(self, idx):
        while idx > 1:
            idx >>= 1
            self.data[idx] = self._func(self.data[2 * idx], self.data[2 * idx + 1]) + self._lazy[idx]

    def add(self, l, r, v):
        l0, r0 = l + self._size, r + self._size
        l1, r1 = l0, r0
        while l0 < r0:
            if l0 & 1:
                self._lazy[l0] += v
                self.data[l0] += v
                l0 += 1
            if r0 & 1:
                r0 -= 1
                self._lazy[r0] += v
                self.data[r0] += v
            l0 >>= 1
            r0 >>= 1
        self._build(l1)
        self._build(r1 - 1)

    def query(self, l, r):
        l += self._size
        r += self._size
        self._update(l)
        self._update(r - 1)
        res = self._default
        while l < r:
            if l & 1:
                res = self._func(res, self.data[l])
                l += 1
            if r & 1:
                r -= 1
                res = self._func(res, self.data[r])
            l >>= 1
            r >>= 1
        return res

class Solution:
    def maximumCount(self, nums, queries):
        n = len(nums)
        self.nums = [0] * n
        self.pos = defaultdict(lambda: SortedList([-1, n]))
        self.st = LazySegmentTree([0] * (n + 1))
        def update(idx, val):
            old = self.nums[idx]
            if is_prime[old]:
                lst = self.pos[old]
                i = lst.bisect_left(idx)
                prv = lst[i-1]
                nxt = lst[i+1]
                if prv == -1:
                    self.st.add(idx+1, nxt+1, -1)
                if nxt == n:
                    self.st.add(prv+1, idx+1, -1)
                lst.remove(idx)
            self.nums[idx] = val
            if is_prime[val]:
                lst = self.pos[val]
                lst.add(idx)
                i = lst.bisect_left(idx)
                prv = lst[i-1]
                nxt = lst[i+1]
                if prv == -1:
                    self.st.add(idx+1, nxt+1, 1)
                if nxt == n:
                    self.st.add(prv+1, idx+1, 1)
        for i, v in enumerate(nums):
            update(i, v)
        res = []
        for idx, val in queries:
            update(idx, val)
            res.append(self.st.query(1, n))
        return res

class Solution:
    def maxDistToClosest(self, seats: List[int]) -> int:
        n = len(seats)
        i = 0
        firstGap = None
        lastGap = None
        curr = 0
        while i < n:
            ctr = 1
            while i < n -1 and seats[i] == seats[i + 1]:
                ctr += 1
                i += 1
            i += 1
            if seats[i - 1] == 0:
                if not firstGap:
                    firstGap = ctr
                lastGap = ctr
                curr = max(curr, (ctr + 1) // 2)
        if seats[0] == 0:
            curr = max(curr, firstGap)
        if seats[-1] == 0:
            curr = max(curr, lastGap)
        return curr

from collections import Counter

class Solution:
    def maximizeGreatness(self, nums: List[int]) -> int:
        return len(nums) - max(Counter(nums).values())

class Solution:
    def maximumHappinessSum(self, happiness: List[int], k: int) -> int:
        happiness.sort(reverse = True)
        res = 0
        sub = 0
        rem = k
        for el in happiness:
            el = max(el - sub, 0)
            if rem > 0:
                res += el
                rem -= 1
                sub += 1
            else:
                break
        return res

class Solution:
    def countSub(self, a, b):
        m = len(a)
        n = len(b)
        dp = [[0 for i in range(n + 1)] for j in range(m + 1)]
        for i in range(n + 1):
            dp[0][i] = 0
        for i in range(m + 1):
            dp[i][0] = 1
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if a[i - 1] == b[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
                else:
                    dp[i][j] = dp[i - 1][j]
        return dp[m][n]

    def maximumSubsequenceCount(self, text: str, pattern: str) -> int:
        n = len(text)
        mxsub = self.countSub(text, pattern)
        a = text.count(pattern[0])
        b = text.count(pattern[1])
        return mxsub + max(a, b)
