class Solution:
    def gcd(self, a, b):
        while b:
            a, b = b, a % b
        return a

    def score(self, nums, n, used, curr):
        if used + 1 == 1 << n:
            return 0
        key = (used, curr)
        if key in self.cache:
            return self.cache[key]
        res = 0
        for i in range(n):
            for j in range(i + 1, n):
                if not used & (1 << i) and not used & (1 << j):
                    res = max(res, curr * self.gcd(nums[i], nums[j]) + self.score(nums, n, used | (1 << i) | (1 << j), curr + 1))
        self.cache[key] = res
        return res

    def maxScore(self, nums: List[int]) -> int:
        self.cache = {}
        return self.score(nums, len(nums), 0, 1)

class Solution:
    def maxPossibleScore(self, start: List[int], d: int) -> int:
        start.sort()
        beg = 0
        end = start[-1] - start[0] + d
        while beg <= end:
            mid = (beg + end) // 2
            pos = True
            prev = float('-inf')
            for s in start:
                curr = min(max(prev + mid, s), s + d)
                if s <= curr <= s + d and curr >= prev + mid:
                    prev = curr
                else:
                    pos = False
                    break
            if pos:
                beg = mid + 1
            else:
                end = mid - 1
        return beg - 1

class SegmentTree:
    def __init__(self, data):
        self._len = len(data)
        self._size = _size = 1 << (self._len - 1).bit_length()
        default = (0, float('-inf'), float('-inf'), float('-inf'))
        self.data = [default] * (2 * _size)
        for i in range(self._len):
            val = data[i]
            self.data[_size + i] = (val, val, val, val)
        for i in reversed(range(_size)):
            self.data[i] = self._merge(self.data[2 * i], self.data[2 * i + 1])

    def _merge(self, left, right):
        total_sum = left[0] + right[0]
        max_prefix = max(left[1], left[0] + right[1])
        max_suffix = max(right[2], right[0] + left[2])
        max_subarray_sum = max(left[3], right[3], left[2] + right[1])
        return (total_sum, max_prefix, max_suffix, max_subarray_sum)

    def __getitem__(self, idx):
        return self.data[idx + self._size]

    def __setitem__(self, idx, value):
        idx += self._size
        self.data[idx] = (value, value, value, value)
        idx >>= 1
        while idx:
            self.data[idx] = self._merge(self.data[2 * idx], self.data[2 * idx + 1])
            idx >>= 1

    def query(self, start, stop):
        start += self._size
        stop += self._size
        left_result = (0, float('-inf'), float('-inf'), float('-inf'))
        right_result = (0, float('-inf'), float('-inf'), float('-inf'))
        while start < stop:
            if start & 1:
                left_result = self._merge(left_result, self.data[start])
                start += 1
            if stop & 1:
                stop -= 1
                right_result = self._merge(self.data[stop], right_result)
            start >>= 1
            stop >>= 1
        return self._merge(left_result, right_result)

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        segtree = SegmentTree(nums[:])
        pos = {}
        for i in range(n):
            if nums[i] not in pos:
                pos[nums[i]] = [-1]
            pos[nums[i]].append(i)
        for el in list(pos):
            pos[el].append(n)
        res = segtree.query(0, n)[3]
        for el in pos:
            poses = pos[el]
            curr = (0, float('-inf'), float('-inf'), float('-inf'))
            for i in range(len(poses) - 1):
                x = poses[i] + 1
                y = poses[i + 1] - 1
                curr = segtree._merge(curr, segtree.query(x, y + 1))
            res = max(res, curr[3])
        return res

class Solution:
    def maxSubarrays(self, n, conflictingPairs):
        m = len(conflictingPairs)
        vp = [[] for _ in range(n)]
        for i, (l, r) in enumerate(conflictingPairs):
            l -= 1; r -= 1
            if l > r: l, r = r, l
            vp[l].append((r, i))
        INF = n
        min1 = [INF] * n
        min2 = [INF] * n
        id1 = [-1] * n
        r1 = INF; r2 = INF; i1 = -1; i2 = -1
        for i in range(n - 1, -1, -1):
            for r, idx in vp[i]:
                if r < r1:
                    r2, i2 = r1, i1
                    r1, i1 = r, idx
                elif r < r2:
                    r2, i2 = r, idx
            min1[i], min2[i], id1[i] = r1, r2, i1
        base = 0
        delta = [0] * m
        for i in range(n):
            r1b = min1[i] if min1[i] < n else n
            r2b = min2[i] if min2[i] < n else n
            base += r1b - i
            k = id1[i]
            if k >= 0:
                delta[k] += (r2b - i) - (r1b - i)
        ans = base
        for d in delta:
            if base + d > ans:
                ans = base + d
        return ans

class Solution:
    def largestSumAfterKNegations(self, nums: List[int], k: int) -> int:
        negs = []
        pos = []
        for el in nums:
            if el >= 0:
                pos.append(el)
            else:
                negs.append(el)
        negs.sort()
        pos.sort()
        for i in range(min(k, len(negs))):
            negs[i] *= -1
        k -= min(k, len(negs))
        res = sum(negs) + sum(pos)
        if k % 2 != 0:
            a = float('inf') if len(negs) == 0 else negs[-1]
            b = float('inf') if len(pos) == 0 else pos[0]
            res -= 2 * min(a, b)
        return res

class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))
        cache = [[-1] * 2 for _ in range(n)]
        def minsum(i, p, hasparent):
            if cache[i][int(hasparent)] != -1:
                return cache[i][int(hasparent)]
            childs = []
            for j, w in graph[i]:
                if j == p:
                    continue
                childs.append((w + minsum(j, i, True), minsum(j, i, False)))
            childs.sort(key = lambda p: p[1] - p[0])
            total = 0
            for x, y in childs:
                total += y
            res = total
            take = k
            if hasparent:
                take = k - 1
            taken = 0
            for j in range(take):
                if j >= len(childs):
                    break
                taken += childs[j][0]
                total -= childs[j][1]
                res = max(res, taken + total)
            cache[i][int(hasparent)] = res
            return res
        return minsum(0, -1, False)

class Solution:
    def maximumBeauty(self, flowers: List[int]) -> int:
        n = len(flowers)
        res = float('-inf')
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] = p[i] + max(flowers[i], 0)
        mn = {}
        for i in range(n):
            res = max(res, 2 * flowers[i] + p[i] - mn.get(flowers[i], float('inf')))
            mn[flowers[i]] = min(mn.get(flowers[i], float('inf')), p[i + 1])
        return res

class Solution:
    def longest(self, arr, k):
        n = len(arr)
        p = [0]
        for el in arr:
            p.append(p[-1] + el)
        res = 0
        i = 0
        zeroes = lambda x, y: y - x + 1 - p[y + 1] + p[x]
        for j in range(n):
            while i < j and zeroes(i, j) > k:
                i += 1
            if zeroes(i, j) <= k:
                res = max(res, j - i + 1)
        return res

    def maxConsecutiveAnswers(self, answerKey: str, k: int) -> int:
        return max(self.longest([int(c == 'T') for c in answerKey], k), self.longest([int(c == 'F') for c in answerKey], k))

class Solution:
    def maxPower(self, stations: List[int], r: int, k: int) -> int:
        n = len(stations)
        beg = min(stations)
        end = sum(stations) + k
        res = beg
        arr = [0] * n
        while beg <= end:
            mid = (beg + end) // 2
            used = 0
            s = 0
            j = 0
            arr[:] = stations
            for i in range(n):
                while j < n and j - i <= r:
                    s += arr[j]
                    j += 1
                if s < mid:
                    diff = mid - s
                    used += diff
                    s -= arr[j - 1]
                    arr[j - 1] += diff
                    s += arr[j - 1]
                if used > k:
                    break
                if i - r >= 0:
                    s -= arr[i - r]
            if used <= k:
                res = mid
                beg = mid + 1
            else:
                end = mid - 1
        return res

class Solution:
    def process(self, edges, k):
        n = 1 + len(edges)
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        def dfs(i, p, d):
            ctr = int(d <= k)
            for j in graph[i]:
                if j != p:
                    ctr += dfs(j, i, d + 1)
            return ctr
        return [dfs(i, -1, 0) for i in range(n)]

    def maxTargetNodes(self, edges1, edges2, k):
        fctr = self.process(edges1, k)
        sctr = max(self.process(edges2, k - 1))
        res = []
        n = len(edges1) + 1
        for i in range(n):
            res.append(fctr[i] + sctr)
        return res

class Solution:
    def process(self, edges):
        n = 1 + len(edges)
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        odds = [False] * n
        def dfs(i, p, d):
            if d & 1:
                odds[i] = True
            curr = int(d % 2 == 0)
            for j in graph[i]:
                if j != p:
                    curr += dfs(j, i, d + 1)
            return curr
        x = dfs(0, -1, 0)
        return [n - x if odds[i] else x for i in range(n)]

    def maxTargetNodes(self, edges1: List[List[int]], edges2: List[List[int]]) -> List[int]:
        mctr = max(self.process(edges2))
        return [ctr + mctr for ctr in self.process(edges1)]

class Solution:
    def maximizeTheProfit(self, n: int, offers: List[List[int]]) -> int:
        left = [[] for _ in range(n + 1)]
        for a, b, gold in offers:
            left[b + 1].append((a, gold))
        dp = [0] * (n + 1)
        for i in range(n + 1):
            if i > 0:
                dp[i] = max(dp[i], dp[i - 1])
            for l, g in left[i]:
                dp[i] = max(dp[i], g + dp[l])
        return dp[n]

class Solution:
    def maximumTotalCost(self, nums: List[int]) -> int:
        n = len(nums)
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] = p[i] + (-1 if i % 2 == 1 else 1) * nums[i]
        dp = [0] * (n + 1)
        mx = p[n]
        mn = p[n]
        for i in range(n - 1, -1, -1):
            if i % 2 == 0:
                dp[i] = mx - p[i]
            else:
                dp[i] = p[i] - mn
            mx = max(mx, p[i] + dp[i])
            mn = min(mn, p[i] - dp[i])
        return dp[0]

class Solution:
    def maximizeWin(self, pos, k):
        n = len(pos)
        l = [0] * n
        r = [0] * n
        i = 0
        for j in range(n):
            while i < j and pos[j] - pos[i] > k:
                i += 1
            if pos[j] - pos[i] <= k:
                l[j] = j - i + 1
        i = n - 1
        for j in range(n - 1, -1, -1):
            while i > j and pos[i] - pos[j] > k:
                i -= 1
            if pos[i] - pos[j] <= k:
                r[j] = i - j + 1
        res = 0
        maxleft = 0
        for i in range(n):
            res = max(res, maxleft + r[i])
            maxleft = max(maxleft, l[i])
        return res

class Solution:
    def maximum69Number (self, num: int) -> int:
        currmax = num
        numstr = str(num)
        if '6' in numstr:
            i = numstr.index('6')
            curr = int(numstr[0:i] + '9' + numstr[i+1:])
            currmax = max(currmax, curr)
        return currmax

class Solution:
    def maxAbsoluteSum(self, nums: List[int]) -> int:
        maxsum = 0
        minyet = float('inf')
        maxyet = float('-inf')
        for el in nums:
            minyet = min(el, minyet + el)
            maxyet = max(el, maxyet + el)
            maxsum = max(maxsum, maxyet, -minyet)
        return maxsum

class Solution:
    def msum(self, nums, i, n, sign):
        if i >= n:
            return 0
        key = (i, sign)
        if key in self.cache:
            return self.cache[key]
        a = sign * nums[i] + self.msum(nums, i + 1, n, -sign)
        b = self.msum(nums, i + 1, n, sign)
        res = max(a, b)
        self.cache[key] = res
        return res

    def maxAlternatingSum(self, nums: List[int]) -> int:
        n = len(nums)
        self.cache = {}
        return self.msum(nums, 0, n, 1)

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m = len(coins)
        n = len(coins[0])
        dp = [[[float('-inf'), float('-inf'), float('-inf')] for _ in range(n + 1)] for _ in range(m + 1)]
        dp[m][n - 1] = [0, 0, 0]
        dp[m - 1][n] = [0, 0, 0]
        for i in range(m - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                for rem in range(3):
                    if rem > 0:
                        dp[i][j][rem] = max(dp[i][j][rem], dp[i][j][rem - 1])
                        dp[i][j][rem] = max(dp[i][j][rem], dp[i + 1][j][rem - 1], dp[i][j + 1][rem - 1])
                    dp[i][j][rem] = max(dp[i][j][rem], coins[i][j] + max(dp[i + 1][j][rem], dp[i][j + 1][rem]))
        return dp[0][0][2]

class Solution:
    def maxsum(self, nums, i, n, fmask, smask, numSlots):
        if i >= n:
            return 0
        key = (i, fmask, smask)
        if key in self.cache:
            return self.cache[key]
        res = 0
        for j in range(numSlots):
            if not fmask & (1 << j) or not smask & (1 << j):
                currfmask = fmask
                currsmask = smask
                if not currfmask & (1 << j):
                    currfmask |= 1 << j
                elif not currsmask & (1 << j):
                    currsmask |= 1 << j
                res = max(res, ((j + 1) & nums[i]) + self.maxsum(nums, i + 1, n, currfmask, currsmask, numSlots))
        self.cache[key] = res
        return res

    def maximumANDSum(self, nums: List[int], numSlots: int) -> int:
        self.cache = {}
        return self.maxsum(nums, 0, len(nums), 0, 0, numSlots)

class Solution:
    def maxArea(self, h: int, w: int, horizontalCuts: List[int], verticalCuts: List[int]) -> int:
        horizontalCuts = [0] + sorted(horizontalCuts) + [h]
        verticalCuts = [0] + sorted(verticalCuts) + [w]
        m = len(horizontalCuts)
        n = len(verticalCuts)
        a = max(horizontalCuts[i+1] - horizontalCuts[i] for i in range(m-1))
        b = max(verticalCuts[i+1] - verticalCuts[i] for i in range(n-1))
        return (a * b) % (10 ** 9 + 7)

class Solution:
    def areaOfMaxDiagonal(self, dimensions: List[List[int]]) -> int:
        res = max(dimensions, key = lambda p: (p[0] * p[0] + p[1] * p[1], p[0] * p[1]))
        return res[0] * res[1]

from collections import *
from sortedcontainers import SortedList

class SegTree:
    def __init__(self, points):
        self.points = points
        self.tree = defaultdict(SortedList)
        self.build(0, len(points), 1)

    def build(self, i, j, k):
        if i + 1 == j:
            self.tree[k].add(self.points[i][1])
            return
        mid = (i + j) // 2
        self.build(i, mid, 2 * k)
        self.build(mid, j, 2 * k + 1)
        self.tree[k] = self.tree[2 * k] + self.tree[2 * k + 1]

    def query(self, i, j, xmin, xmax, ymin, ymax, k):
        if self.points[i][0] > xmax or self.points[j - 1][0] < xmin:
            return 0
        if self.points[i][0] >= xmin and self.points[j - 1][0] <= xmax:
            return self.tree[k].bisect_right(ymax) - self.tree[k].bisect_left(ymin)
        mid = (i + j) // 2
        return self.query(i, mid, xmin, xmax, ymin, ymax, 2 * k) + self.query(mid, j, xmin, xmax, ymin, ymax, 2 * k + 1)

class Solution:
    def maxRectangleArea(self, xCoord: List[int], yCoord: List[int]) -> int:
        n = len(xCoord)
        points = [(xCoord[i], yCoord[i], i) for i in range(n)]
        segtree = SegTree(sorted(points))
        up = [-1] * n
        right = [-1] * n
        points.sort(key = lambda p: -p[1])
        last = {}
        for x, y, pos in points:
            if x in last:
                up[pos] = last[x]
            last[x] = pos
        points.sort(key = lambda p: -p[0])
        last = {}
        for x, y, pos in points:
            if y in last:
                right[pos] = last[y]
            last[y] = pos
        res = 0
        for i in range(n):
            if up[i] != -1 and right[i] != -1 and yCoord[up[i]] == yCoord[up[right[i]]]:
                if segtree.query(0, len(points), xCoord[i], xCoord[right[i]], yCoord[i], yCoord[up[i]], 1) == 4:
                    res = max(res, (xCoord[right[i]] - xCoord[i]) * (yCoord[up[i]] - yCoord[i]))
        if res == 0:
            res = -1
        return res

class Solution:
    def maxAscendingSum(self, nums: List[int]) -> int:
        x = 0
        res = 0
        for i in range(len(nums)):
            if i == 0 or nums[i] <= nums[i - 1]:
                x = nums[i]
            else:
                x += nums[i]
            res = max(res, x)
        return res

import heapq

class Solution:
    def maxAverageRatio(self, classes: List[List[int]], extraStudents: int) -> float:
        n = len(classes)
        diff = lambda a, b: (a + 1) / (b + 1) - a / b
        heap = []
        for a, b in classes:
            heapq.heappush(heap, (-diff(a, b), a, b))
        for _ in range(extraStudents):
            currdiff, a, b = heapq.heappop(heap)
            heapq.heappush(heap, (-diff(a + 1, b + 1), a + 1, b + 1))
        res = 0
        for diff, a, b in heap:
            res += a / b
        res /= n
        return res

class Solution:
    def findMaxAverage(self, nums: List[int], k: int) -> float:
        n = len(nums)
        total = 0
        res = float('-inf')
        for i in range(n):
            total += nums[i]
            if i >= k:
                total -= nums[i - k]
            if i >= k - 1:
                res = max(res, total)
        return res / k

class Solution:
    def findMaxAverage(self, nums: List[int], k: int) -> float:
        n = len(nums)
        beg = min(nums)
        end = max(nums)
        while end - beg > 0.00001:
            mid = (beg + end) / 2
            p = [0] * (n + 1)
            for i in range(n):
                p[i + 1] = p[i] + nums[i] - mid
            sp = [float('inf')] * (n + 2)
            for i in range(n + 1):
                sp[i + 1] = min(sp[i], p[i])
            pos = False
            for j in range(k - 1, n + 1):
                if sp[j - k + 1] <= p[j]:
                    pos = True
                    break
            if pos:
                beg = mid
            else:
                end = mid
        return beg

class Solution:
    def maximumBags(self, capacity: List[int], rocks: List[int], additionalRocks: int) -> int:
        n = len(rocks)
        diff = [capacity[i] - rocks[i] for i in range(n)]
        diff.sort(reverse = True)
        while len(diff) > 0 and diff[-1] <= additionalRocks:
            additionalRocks -= diff.pop()
        return n - len(diff)

import numpy as np

class Solution:
    def maxBalancedSubsequenceSum(self, nums: List[int]) -> int:
        n = len(nums)
        mp = {}
        for i in range(n):
            mp[nums[i] - i] = 0
        for i, el in enumerate(sorted(mp)):
            mp[el] = i
        fw = np.array([float('-inf')] * (len(mp) + 1))
        res = float('-inf')
        for i in range(n):
            curr = nums[i] + np.max(fw[:mp[nums[i] - i] + 1])
            curr = max(curr, nums[i])
            fw[mp[nums[i] - i]] = curr
            res = max(res, curr)
        return int(res)

class Solution:
    def maximumBeauty(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nums.sort()
        i = 0
        res = 1
        for j in range(n):
            while i < j and nums[i] + k < nums[j] - k:
                i += 1
            if nums[i] + k >= nums[j] - k:
                res = max(res, j - i + 1)
        return res

class Solution:
    def maximumBinaryString(self, binary: str) -> str:
        n = len(binary)
        i = 0
        while i < n and binary[i] == "1":
            i += 1
        o = z = 0
        for j in range(i, n):
            if binary[j] == "0":
                z += 1
            else:
                o += 1
        return "1" * i + "1" * max(z - 1, 0) + "0" * min(z, 1) + "1" * o

class Solution:
    def numChild(self, candies, candy):
        k = 0
        for pile in candies:
            k += int(pile / candy)
        return k

    def maximumCandies(self, candies: List[int], k: int) -> int:
        beg = 1
        end = max(candies)
        while beg <= end:
            mid = (beg + end) // 2
            val = self.numChild(candies, mid)
            nextval = self.numChild(candies, mid + 1)
            if val >= k and nextval < k:
                return mid
            elif beg == end:
                break
            elif val < k:
                end = mid
            else:
                beg = mid + 1
        return 0

class Solution:
    def maxCandies(self, status: List[int], candies: List[int], keys: List[List[int]], containedBoxes: List[List[int]], initialBoxes: List[int]) -> int:
        n = len(status)
        res = 0
        boxes = set(initialBoxes)
        akeys = set()
        done = set()
        while True:
            oldbox = len(boxes)
            oldkey = len(akeys)
            for b in list(boxes):
                if b in akeys:
                    status[b] = 1
            for i in range(n):
                if i in boxes and status[i] == 1:
                    if i not in done:
                        res += candies[i]
                        done.add(i)
                    for k in keys[i]:
                        akeys.add(k)
                    for b in containedBoxes[i]:
                        boxes.add(b)
            if len(boxes) == oldbox and len(akeys) == oldkey:
                break
        return res

class Solution:
    def maximumCoins(self, coins: List[List[int]], k: int) -> int:
        n = len(coins)
        coins.sort()
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] = p[i] + coins[i][2] * (coins[i][1] - coins[i][0] + 1)
        starts = set()
        for l, r, c in coins:
            starts.add(l)
            starts.add(r - k + 1)
        res = 0
        starts = sorted(starts)
        for s in starts:
            l = s
            r = s + k - 1
            beg = 0
            end = n - 1
            while beg <= end:
                mid = (beg + end) // 2
                if coins[mid][0] >= l:
                    end = mid - 1
                else:
                    beg = mid + 1
            first = end + 1
            beg = 0
            end = n - 1
            while beg <= end:
                mid = (beg + end) // 2
                if coins[mid][1] <= r:
                    beg = mid + 1
                else:
                    end = mid - 1
            last = beg - 1
            curr = 0
            if first <= last:
                curr += p[last + 1] - p[first]
            if first - 1 >= 0:
                if coins[first - 1][1] >= l:
                    curr += (coins[first - 1][1] - s + 1) * coins[first - 1][2]
            if last + 1 < n and last + 1 != first - 1:
                if coins[last + 1][0] <= r:
                    curr += (r - coins[last + 1][0] + 1) * coins[last + 1][2]
            res = max(res, curr)
        return res

import numpy as np

class Solution:
    def maxCompatibilitySum(self, students: List[List[int]], mentors: List[List[int]]) -> int:
        def auction_algorithm(w):
            n = len(w)
            epsilon = 1 / (n + 1)
            prices = np.zeros(n)
            assignment = -np.ones(n, dtype=int)
            while np.any(assignment == -1):
                for student in range(n):
                    if assignment[student] != -1:
                        continue
                    net_benefits = w[student] - prices
                    best_mentor = np.argmax(net_benefits)
                    best_value = net_benefits[best_mentor]
                    net_benefits[best_mentor] = -np.inf
                    second_best_value = np.max(net_benefits)
                    prices[best_mentor] += best_value - second_best_value + epsilon
                    for other_student, mentor in enumerate(assignment):
                        if mentor == best_mentor:
                            assignment[other_student] = -1
                            break
                    assignment[student] = best_mentor
            total_weight = sum(w[student, mentor] for student, mentor in enumerate(assignment))
            return int(total_weight)
        n = len(students)
        w = np.zeros((n, n), dtype=int)
        for i in range(n):
            for j in range(n):
                for k in range(len(students[i])):
                    if students[i][k] == mentors[j][k]:
                        w[i][j] += 1
        return auction_algorithm(w)

class Solution:
    def maxConsecutive(self, bottom: int, top: int, special: List[int]) -> int:
        points = sorted([bottom - 1] + special + [top + 1])
        mgap = 0
        n = len(points)
        for i in range(n - 1):
            mgap = max(mgap, points[i+1] - points[i] - 1)
        return mgap

class Solution:
    def maxContainers(self, n: int, w: int, maxWeight: int) -> int:
        return min(maxWeight // w, n * n)

class Solution:
    def maximumCost(self, n: int, highways: List[List[int]], k: int) -> int:
        graph = [[] for _ in range(n)]
        for u, v, w in highways:
            graph[u].append((v, w))
            graph[v].append((u, w))
        @lru_cache(maxsize = None)
        def dp(i, used, rem):
            if rem == 0:
                return 0
            res = float('-inf')
            for j, w in graph[i]:
                if not used & (1 << j):
                    res = max(res, w + dp(j, used | (1 << j), rem - 1))
            return res
        res = max(dp(i, 1 << i, k) for i in range(n))
        if res == float('-inf'):
            res = -1
        return res

class Solution:
    def maximumCount(self, nums: List[int]) -> int:
        pos = neg = 0
        for el in nums:
            if el < 0:
                neg += 1
            if el > 0:
                pos += 1
        return max(pos, neg)

class Solution:
    def deleteString(self, s: str) -> int:
        n = len(s)
        if len(set(s)) == 1:
            return n
        dp = [1] * n
        for i in range(n - 1, -1, -1):
            for j in range(i + 1, 1 + (n + i) // 2):
                if s[i : j] == s[j : 2 * j - i]:
                    dp[i] = max(dp[i], 1 + dp[j])
        return dp[0]

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def maxDepth(self, root: Optional[TreeNode]) -> int:
        if not root:
            return 0
        queue = [(root, 1)]
        maxDepth = 1
        while len(queue) > 0:
            curr, depth = queue.pop(0)
            maxDepth = max(maxDepth, depth)
            if curr.left:
                queue.append((curr.left, depth + 1))
            if curr.right:
                queue.append((curr.right, depth + 1))
        return maxDepth

