class Solution:
    def maxDepth(self, root: 'Node') -> int:
        if root:
            mdepth = 1
            if root.children:
                for c in root.children:
                    curr = 1 + self.maxDepth(c)
                    mdepth = max(mdepth, curr)
            return mdepth
        return 0

class Solution:
    def maxAdjacentDistance(self, nums: List[int]) -> int:
        n = len(nums)
        res = abs(nums[0] - nums[-1])
        for i in range(n - 1):
            res = max(res, abs(nums[i + 1] - nums[i]))
        return res

class Solution:
    def maxDifference(self, s: str) -> int:
        mn = [float('inf'), float('inf')]
        mx = [float('-inf'), float('-inf')]
        for x in Counter(s).values():
            mn[x % 2] = min(mn[x % 2], x)
            mx[x % 2] = max(mx[x % 2], x)
        return mx[1] - mn[0]

class Solution:
    def maxDifference(self, s: str, k: int) -> int:
        n = len(s)
        res = float('-inf')
        for a in '01234':
            for b in '01234':
                if a == b:
                    continue
                arr = [1 if c == a else (-1 if c == b else 0) for c in s]
                aa = [1 if c == a else 0 for c in s]
                bb = [1 if c == b else 0 for c in s]
                pa = [0] * (n + 1)
                pb = [0] * (n + 1)
                p = [0] * (n + 1)
                for i in range(n):
                    p[i + 1] = p[i] + arr[i]
                    pa[i + 1] = pa[i] + aa[i]
                    pb[i + 1] = pb[i] + bb[i]
                mn = [[float('inf'), float('inf')], [float('inf'), float('inf')]]
                i = 0
                for j in range(n + 1):
                    while j - i >= k and pa[j] - pa[i] > 0 and pb[j] - pb[i] > 0:
                        mn[pa[i] % 2][pb[i] % 2] = min(mn[pa[i] % 2][pb[i] % 2], p[i])
                        i += 1
                    res = max(res, p[j] - mn[1 - (pa[j] % 2)][pb[j] % 2])
        return res

class Solution:
    def maximumDifference(self, nums: List[int]) -> int:
        mdiff = float('-inf')
        minSoFar = nums[0]
        for num in nums:
            minSoFar = min(minSoFar, num)
            mdiff = max(mdiff, num - minSoFar)
        if mdiff > 0:
            return mdiff
        return -1

class Solution:
    def maxAncestorDiff(self, root):
        nodes = [(root, root.val, root.val)]
        mdiff = 0
        while len(nodes) > 0:
            curr, currmin, currmax = nodes.pop()
            mdiff = max(mdiff, currmax - currmin)
            if curr.left:
                nodes.append((curr.left, min(currmin, curr.left.val), max(currmax, curr.left.val)))
            if curr.right:
                nodes.append((curr.right, min(currmin, curr.right.val), max(currmax, curr.right.val)))
        return mdiff

class Solution:
    def minMaxDifference(self, num: int) -> int:
        def remap(v, mp):
            return int(''.join(mp[1] if c == mp[0] else c for c in v))
        num = str(num)
        i = 0
        while i < len(num) and num[i] == '9':
            i += 1
        mx = ('9', '9')
        if i < len(num):
            mx = (num[i], '9')
        mn = (num[0], '0')
        return remap(num, mx) - remap(num, mn)

class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        res = float('-inf')
        mx = [[float('-inf')] * (n + 1) for _ in range(m + 1)]
        for j in range(n - 1, -1, -1):
            for i in range(m - 1, -1, -1):
                mx[i][j] = max(mx[i + 1][j], mx[i][j + 1])
                res = max(res, mx[i][j] - grid[i][j])
                mx[i][j] = max(mx[i][j], grid[i][j])
        return res

class Solution:
    def maxDistance(self, nums1: List[int], nums2: List[int]) -> int:
        vals = []
        for i, el in enumerate(nums1):
            vals.append((el, i, 0))
        for i, el in enumerate(nums2):
            vals.append((el, i, 1))
        vals.sort()
        res = 0
        minfirst = float('inf')
        for val, pos, t in vals:
            if t == 1:
                res = max(res, pos - minfirst)
            else:
                minfirst = min(minfirst, pos)
        return res

class Solution:
    def maxDistance(self, arrays: List[List[int]]) -> int:
        res = 0
        mn = float('inf')
        mx = float('-inf')
        for arr in arrays:
            for el in arr:
                if mn < float('inf'):
                    res = max(res, abs(el - mn), abs(el - mx))
            for el in arr:
                mn = min(mn, el)
                mx = max(mx, el)
        return res

from collections import defaultdict

class Solution:
    def maxTaxiEarnings(self, n, rides):
        dp = [0] * (n + 1)
        graph = defaultdict(lambda: defaultdict(int))
        for a, b, d in rides:
            graph[a - 1][b - 1] = max(graph[a - 1][b - 1], b - a + d)
        for i in range(n - 1, -1, -1):
            for j in graph[i]:
                dp[i] = max(dp[i], graph[i][j] + dp[j])
            dp[i] = max(dp[i], dp[i + 1])
        return dp[0]

class Solution:
    def maximumElementAfterDecrementingAndRearranging(self, arr: List[int]) -> int:
        n = len(arr)
        arr.sort()
        arr[0] = 1
        for i in range(1, n):
            if arr[i] > arr[i - 1] + 1:
                arr[i] = arr[i - 1] + 1
        return arr[-1]

