class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        n = len(nums)
        sums = defaultdict(int)
        for i in range(n):
            curr = 1
            val = i + 1
            primes = Counter()
            while val > 1:
                primes[sp[val]] += 1
                val //= sp[val]
            for p in primes:
                curr *= pow(p, primes[p] % 2)
            sums[curr] += nums[i]
        return max(sums.values())

class Solution:
    def maximumInvitations(self, favorite: List[int]) -> int:
        n = len(favorite)
        graph = [[] for _ in range(n)]
        for i in range(n):
            graph[i].append(favorite[i])
            graph[favorite[i]].append(i)
        def longest(i, p):
            res = 1
            for j in graph[i]:
                if j == p:
                    continue
                res = max(res, 1 + longest(j, i))
            return res
        res = 0
        v = set()
        for node in range(n):
            i = 0
            pos = {}
            curr = []
            while node not in v:
                pos[node] = i
                curr.append(node)
                v.add(node)
                node = favorite[node]
                i += 1
            if node in pos:
                res = max(res, i - pos[node])
        extra = 0
        for i in range(n):
            if i < favorite[i] and favorite[favorite[i]] == i:
                extra += longest(i, favorite[i]) + longest(favorite[i], i)
        res = max(res, extra)
        return res

class Solution:
    def captureForts(self, forts: List[int]) -> int:
        n = len(forts)
        res = 0
        for i in range(n):
            if forts[i] == 1:
                l = i - 1
                r = i + 1
                while l >= 0 and forts[l] == 0:
                    l -= 1
                while r < n and forts[r] == 0:
                    r += 1
                if l >= 0 and forts[l] == -1:
                    res = max(res, i - l - 1)
                if r < n and forts[r] == -1:
                    res = max(res, r - i - 1)
        return res

class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        n = len(energyDrinkA)
        dp = [[0, 0] for _ in range(n + 1)]
        for i in range(n - 1, -1, -1):
            dp[i][0] = max(dp[i][0], energyDrinkA[i] + dp[i + 1][0])
            dp[i][1] = max(dp[i][1], energyDrinkB[i] + dp[i + 1][1])
            if i + 2 <= n:
                dp[i][0] = max(dp[i][0], energyDrinkA[i] + dp[i + 2][1])
                dp[i][1] = max(dp[i][1], energyDrinkB[i] + dp[i + 2][0])
        return max(dp[0])

from sortedcontainers import SortedList

class Solution:
    def maxEqualFreq(self, nums: List[int]) -> int:
        n = len(nums)
        ctr = Counter()
        bst = SortedList()
        res = 0
        while res < n and nums[res] == nums[0]:
            res += 1
        for i in range(n):
            if ctr[nums[i]] > 0:
                bst.remove(ctr[nums[i]])
            ctr[nums[i]] += 1
            bst.add(ctr[nums[i]])
            if i + 1 <= res:
                continue
            if bst[0] == bst[-1] == 1:
                res = i + 1
            if len(bst) == 1:
                continue
            if len(bst) >= 3:
                if bst[0] == 1 and bst[1] == bst[-1]:
                    res = i + 1
                if bst[0] == bst[-2] and bst[-1] == 1 + bst[-2]:
                    res = i + 1
            elif bst[0] == 1 or bst[1] == 1 + bst[0]:
                res = i + 1
        return res

class Solution:
    def maximumUniqueSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        msum = 0
        p = [0]
        for el in nums:
            p.append(p[-1] + el)
        prev = {}
        i = 0
        for j in range(n):
            if nums[j] in prev:
                i = max(i, prev[nums[j]] + 1)
            msum = max(msum, p[j + 1] - p[i])
            prev[nums[j]] = j
        return msum

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pk = [0] * (n + 1)
        for i in range(n):
            pk[i + 1] = pk[i] + int(nums[i] == k)
        res = 0
        p = [0] * (n + 1)
        for v in set(nums):
            for i in range(n):
                p[i + 1] = p[i] + int(nums[i] == v)
            mn = float('inf')
            for j in range(n):
                mn = min(mn, p[j] - pk[j])
                res = max(res, pk[n] - pk[j + 1] + p[j + 1] - mn)
        return res

class Solution:
    def maxFrequencyScore(self, nums: List[int], k: int) -> int:
        M = 10 ** 9 + 7
        n = len(nums)
        s = 0
        res = 0
        ctr = Counter()
        for i in range(n):
            if ctr[nums[i]]:
                s -= pow(nums[i], ctr[nums[i]], M)
            ctr[nums[i]] += 1
            s += pow(nums[i], ctr[nums[i]], M)
            s %= M
            if i >= k:
                s -= pow(nums[i - k], ctr[nums[i - k]], M)
                ctr[nums[i - k]] -= 1
                if ctr[nums[i - k]]:
                    s += pow(nums[i - k], ctr[nums[i - k]], M)
                s %= M
            if i >= k - 1:
                res = max(res, s % M)
        return res

class Solution:
    def maxTotalFruits(self, fruits: List[List[int]], startPos: int, k: int) -> int:
        n = len(fruits)
        l = []
        r = []
        for pos, val in fruits:
            if pos <= startPos:
                l.append((startPos - pos, val))
            else:
                r.append((pos - startPos, val))
        l.reverse()
        def solve(left, right):
            res = 0
            p = [0] * (len(right) + 1)
            for i in range(len(right)):
                p[i + 1] = p[i] + right[i][1]
            taken = 0
            for i in range(len(left)):
                curr = left[i][0]
                if curr > k:
                    break
                taken += left[i][1]
                extra = 0
                if 2 * curr < k:
                    rem = k - 2 * curr
                    beg = 0
                    end = len(right) - 1
                    while beg <= end:
                        mid = (beg + end) // 2
                        if right[mid][0] <= rem:
                            beg = mid + 1
                        else:
                            end = mid - 1
                    extra = p[beg]
                res = max(res, taken + extra)
            return res
        return max(solve(l, r), solve(r, l))

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

class Solution:
    def maxGcdSum(self, nums: List[int], k: int) -> int:
        res = 0
        stack = []
        for el in nums[::-1]:
            ns = []
            for g, gctr, s in [(el, 1, el)] + stack:
                if ns and gcd(g, el) == ns[-1][0]:
                    ns[-1][1] += gctr
                    ns[-1][2] += s
                else:
                    ns.append([gcd(g, el), gctr, s])
            pctr = 0
            ps = 0
            for g, gctr, s in ns:
                pctr += gctr
                ps += s
                if pctr >= k:
                    res = max(res, g * ps)
            stack = ns
        return res

class Node:
    def __init__(self):
        self.child = [None, None]
        self.ctr = 0

class Trie:
    def __init__(self):
        self.root = Node()

    def insert(self, s):
        curr = self.root
        curr.ctr += 1
        for c in s:
            c = int(c)
            if curr.child[c] == None:
                curr.child[c] = Node()
            curr = curr.child[c]
            curr.ctr += 1

    def delete(self, s):
        curr = self.root
        curr.ctr -= 1
        for c in s:
            c = int(c)
            if curr.child[c].ctr == 1:
                curr.child[c] = None
                break
            curr = curr.child[c]
            curr.ctr -= 1

    def getmax(self, s):
        curr = self.root
        res = 0
        for c in s:
            c = int(c)
            if curr.child[1 - c] != None and curr.child[1 - c].ctr > 0:
                curr = curr.child[1 - c]
                res = 2 * res + 1
            elif curr.child[c] != None and curr.child[c].ctr > 0:
                curr = curr.child[c]
                res = 2 * res
        return res

class Solution:
    def maxGeneticDifference(self, parents: List[int], queries: List[List[int]]) -> List[int]:
        n = len(parents)
        q = [[] for _ in range(n)]
        res = [0] * len(queries)
        for i in range(len(queries)):
            q[queries[i][0]].append((queries[i][1], i))
        graph = [[] for _ in range(n)]
        root = 0
        for i in range(n):
            if parents[i] == -1:
                root = i
                continue
            graph[parents[i]].append(i)
        val = lambda x: "{:018b}".format(x)
        trie = Trie()
        def dfs(curr):
            trie.insert(val(curr))
            for x, pos in q[curr]:
                res[pos] = trie.getmax(val(x))
            for j in graph[curr]:
                dfs(j)
            trie.delete(val(curr))
        dfs(root)
        return res

class Solution:
    def maximumGood(self, statements: List[List[int]]) -> int:
        n = len(statements)
        masks = []
        for i in range(n):
            good = bad = 0
            for j in range(n):
                if statements[i][j] == 0:
                    bad |= 1 << j
                if statements[i][j] == 1:
                    good |= 1 << j
            masks.append((good, bad))
        res = 0
        for mask in range(1 << n):
            bads = 0
            goods = 0
            for i in range(n):
                if mask & (1 << i):
                    goods |= masks[i][0]
                    bads |= masks[i][1]
            if goods | mask == mask and mask & bads == 0:
                res = max(res, mask.bit_count())
        return res

class Solution:
    def maximumSubarraySum(self, nums: List[int], k: int) -> int:
        def solve(arr):
            n = len(arr)
            p = [0] * (n + 1)
            for i in range(n):
                p[i + 1] = p[i] + arr[i]
            res = float('-inf')
            x = defaultdict(lambda: float('inf'))
            for j in range(n):
                res = max(res, p[j + 1] - x[arr[j] - k])
                x[arr[j]] = min(x[arr[j]], p[j])
            return res
        res = max(solve(nums), solve(nums[::-1]))
        if res == float('-inf'):
            res = 0
        return res

from itertools import permutations
from collections import defaultdict, deque

class Solution:
    def maxHeight(self, cuboids: List[List[int]]) -> int:
        n = len(cuboids)
        cuboids.sort()
        perms = [[] for _ in range(n)]
        for i in range(n):
            perms[i].extend(list(permutations(cuboids[i])))
        graph = defaultdict(set)
        indegree = defaultdict(int)
        for i in range(n):
            for j in range(n):
                if i != j:
                    for k in range(6):
                        for l in range(6):
                            l1, w1, h1 = perms[i][k]
                            l2, w2, h2 = perms[j][l]
                            if l1 == l2 and w1 == w2 and h1 == h2 and i > j:
                                continue
                            if l1 <= l2 and w1 <= w2 and h1 <= h2:
                                graph[(i, k)].add((j, l))
                                indegree[(j, l)] += 1
        q = deque()
        for i in range(n):
            for j in range(6):
                if indegree[(i, j)] == 0:
                    q.appendleft((i, j))
        order = []
        while len(q) > 0:
            curr = q.pop()
            order.append(curr)
            for i, j in graph[curr]:
                indegree[(i, j)] -= 1
                if indegree[(i, j)] == 0:
                    q.appendleft((i, j))
        order.reverse()
        res = 0
        maxheight = defaultdict(lambda: 0)
        for i, j in order:
            maxheight[(i, j)] = perms[i][j][2]
            for x, y in graph[(i, j)]:
                maxheight[(i, j)] = max(maxheight[(i, j)], perms[i][j][2] + maxheight[(x, y)])
            res = max(res, maxheight[(i, j)])
        return res

class Solution:
    def maxHeightOfTriangle(self, r: int, b: int) -> int:
        def h(red, blue):
            res = 0
            while True:
                if res % 2 == 0:
                    if blue >= res + 1:
                        blue -= res + 1
                    else:
                        break
                else:
                    if red >= res + 1:
                        red -= res + 1
                    else:
                        break
                res += 1
            return res
        return max(h(r, b), h(b, r))

class Solution:
    def maxIceCream(self, costs: List[int], coins: int) -> int:
        costs.sort()
        res = 0
        for el in costs:
            if coins >= el:
                res += 1
                coins -= el
        return res

class Solution:
    def longest(self, arr, i, n, used):
        if i >= n:
            return 0
        key = (i, used)
        if key in self.cache:
            return self.cache[key]
        p = lambda c: ord(c) - ord('a')
        a = float('-inf')
        valid = True
        currused = used
        for c in arr[i]:
            if currused & (1 << p(c)):
                valid = False
                break
            else:
                currused |= 1 << p(c)
        if valid:
            a = len(arr[i]) + self.longest(arr, i + 1, n, currused)
        b = self.longest(arr, i + 1, n, used)
        res = max(a, b)
        self.cache[key] = res
        return res

    def maxLength(self, arr: List[str]) -> int:
        self.cache = {}
        return self.longest(arr, 0, len(arr), 0)

class Solution:
    def biggestChain(self, pairs, i, n):
        if i == n - 1:
            return 1
        if i in self.cache:
            return self.cache[i]
        mlen = 1
        for j in range(i+1, n):
            if pairs[j][0] > pairs[i][1]:
                curr = self.biggestChain(pairs, j, n)
                mlen = max(mlen, 1 + curr)
        self.cache[i] = mlen
        return mlen

    def findLongestChain(self, pairs: List[List[int]]) -> int:
        pairs.sort(key = lambda x: x[0])
        self.cache = {}
        n = len(pairs)
        mlen = 1
        for i in range(n):
            curr = self.biggestChain(pairs, i, n)
            mlen = max(mlen, curr)
        return mlen

from collections import defaultdict

class Solution:
    def findLength(self, nums1: List[int], nums2: List[int]) -> int:
        pos = defaultdict(list)
        for i in range(len(nums1)):
            pos[nums1[i]].append(i)
        res = 0
        prev = defaultdict(int)
        for j in range(len(nums2)):
            curr = defaultdict(int)
            for i in pos[nums2[j]]:
                curr[i] = 1 + prev[i - 1]
                res = max(res, curr[i])
            prev = curr
        return res

from collections import Counter

class Solution:
    def maximumLengthSubstring(self, s: str) -> int:
        n = len(s)
        res = 0
        ctr = Counter()
        for i in range(n):
            ctr = Counter()
            for j in range(i, n):
                ctr[s[j]] += 1
                if max(ctr.values()) <= 2:
                    res = max(res, j - i + 1)
        return res

class Solution:
    def inorder(self, root, l):
        if root:
            self.inorder(root.left, l + 1)
            self.levels[l] = self.levels.get(l, 0) + root.val
            self.inorder(root.right, l + 1)

    def maxLevelSum(self, root: Optional[TreeNode]) -> int:
        self.levels = {}
        self.inorder(root, 1)
        return -max([(v, -k) for k, v in self.levels.items()])[1]

class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        a = [0, 0]
        b = [0, 0]
        res = 0
        for c in s:
            if c == 'N':
                a[0] += 1
            if c == 'S':
                a[1] += 1
            if c == 'E':
                b[0] += 1
            if c == 'W':
                b[1] += 1
            x = min(a[0], a[1])
            y = min(b[0], b[1])
            res = max(res, abs(a[0] - a[1]) + abs(b[0] - b[1]) + 2 * min(x + y, k))
        return res

class Solution:
    def matchPlayersAndTrainers(self, players: List[int], trainers: List[int]) -> int:
        n = len(players)
        players.sort()
        trainers.sort()
        i = 0
        for t in trainers:
            if i < n and t >= players[i]:
                i += 1
        return i

class Solution:
    def maxMatrixSum(self, matrix: List[List[int]]) -> int:
        n = len(matrix)
        res = 0
        maxneg = float('-inf')
        minpos = float('inf')
        ctr = 0
        for i in range(n):
            for j in range(n):
                res += abs(matrix[i][j])
                if matrix[i][j] <= 0:
                    ctr += 1
                    maxneg = max(maxneg, matrix[i][j])
                else:
                    minpos = min(minpos, matrix[i][j])
        if ctr % 2 == 0:
            maxneg = 0
        return max(res + 2 * maxneg, res - 2 * minpos)

class Solution:
    def maxScore(self, a: List[int], b: List[int]) -> int:
        @lru_cache(maxsize = None)
        def dp(i, j):
            if j >= 4:
                return 0
            if i >= len(b):
                return float('-inf')
            return max(a[j] * b[i] + dp(i + 1, j + 1), dp(i + 1, j))
        return dp(0, 0)

class Solution:
    def maxDepth(self, s: str) -> int:
        depth = 0
        mdepth = 0
        for c in s:
            if c == "(":
                depth += 1
            if c == ")":
                depth -= 1
            mdepth = max(mdepth, depth)
        return mdepth

class Solution:
    def maxProductPath(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        dp = [[(0, 0)] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                curr = []
                if i == 0 and j == 0:
                    curr += [grid[i][j]]
                if i > 0:
                    curr += [grid[i][j] * dp[i - 1][j][0], grid[i][j] * dp[i - 1][j][1]]
                if j > 0:
                    curr += [grid[i][j] * dp[i][j - 1][0], grid[i][j] * dp[i][j - 1][1]]
                dp[i][j] = (max(curr), min(curr))
        res = max(dp[m - 1][n - 1])
        if res < 0:
            return -1
        return res % (10 ** 9 + 7)

class Solution:
    def maximumRequests(self, n: int, requests: List[List[int]]) -> int:
        m = len(requests)
        res = 0
        left = {}
        l, r = m // 2, m - m // 2
        for mask in range(1 << l):
            ctr = [0] * n
            x = 0
            for i in range(l):
                if mask & (1 << i):
                    ctr[requests[i][0]] -= 1
                    ctr[requests[i][1]] += 1
                    x += 1
            ctr = tuple(ctr)
            if x > left.get(ctr, float('-inf')):
                left[ctr] = x
        for mask in range(1 << r):
            ctr = [0] * n
            x = 0
            for i in range(r):
                if mask & (1 << i):
                    ctr[requests[l + i][0]] += 1
                    ctr[requests[l + i][1]] -= 1
                    x += 1
            ctr = tuple(ctr)
            res = max(res, left.get(ctr, float('-inf')) + x)
        return res

class Solution:
    def maxNumberOfAlloys(self, n: int, k: int, budget: int, composition: List[List[int]], stock: List[int], cost: List[int]) -> int:
        def mincost(cmp, count):
            c = 0
            for i in range(n):
                c += max(cmp[i] * count - stock[i], 0) * cost[i]
            return c
        res = 0
        for i in range(k):
            end = 1
            while mincost(composition[i], end) <= budget:
                end *= 2
            beg = end // 2
            curr = beg
            while beg <= end:
                mid = (beg + end) // 2
                if mincost(composition[i], mid) <= budget:
                    curr = mid
                    beg = mid + 1
                else:
                    end = mid - 1
            res = max(res, curr)
        return res

class Solution:
    def maximumBooks(self, books: List[int]) -> int:
        n = len(books)
        prv = [-1] * n
        stack = []
        for i in range(n):
            while stack and books[stack[-1]] - stack[-1] >= books[i] - i:
                stack.pop()
            if stack:
                prv[i] = stack[-1]
            stack.append(i)
        dp = [0] * n
        for i in range(n):
            if prv[i] != -1:
                dp[i] = dp[prv[i]]
            l = min(i - prv[i], books[i])
            dp[i] += books[i] * l - l * (l - 1) // 2
        return max(dp)

class Solution:
    def getMaximumConsecutive(self, coins: List[int]) -> int:
        coins.sort()
        if coins[0] > 1:
            return 1
        p = 0
        for i in range(len(coins)):
            p += coins[i]
            if i == len(coins) - 1 or p + 1 < coins[i + 1]:
                return p + 1

class Solution:
    def maxDistinctElements(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nums.sort()
        prev = float('-inf')
        for i in range(n):
            if nums[i] <= prev:
                maxadd = min(k, prev - nums[i] + 1)
                nums[i] += maxadd
            else:
                maxsub = min(k, nums[i] - prev - 1)
                nums[i] -= maxsub
            prev = nums[i]
        return len(set(nums))

import heapq

class Solution:
    def eatenApples(self, apples: List[int], days: List[int]) -> int:
        n = len(apples)
        heap = []
        res = 0
        i = 0
        while i < n or heap:
            while heap and heap[0][0] < i:
                heapq.heappop(heap)
            if i < n and days[i] > 0:
                heapq.heappush(heap, (i + days[i] - 1, apples[i]))
            if heap:
                end, ctr = heapq.heappop(heap)
                res += 1
                if ctr - 1 > 0:
                    heapq.heappush(heap, (end, ctr - 1))
            i += 1
        return res

from collections import defaultdict

class Solution:
    def maxValue(self, events: List[List[int]], k: int) -> int:
        n = len(events)
        events.sort(key = lambda e: e[1])
        mp = {}
        for a, b, p in events:
            mp[a] = mp[b + 1] = 0
        for i, el in enumerate(sorted(mp)):
            mp[el] = i
        lefts = defaultdict(set)
        for a, b, p in events:
            lefts[mp[b + 1]].add((mp[a], p))
        dp = [[0] * (len(mp) + 1) for _ in range(k + 1)]
        for i in range(1, k + 1):
            for j in range(len(mp) + 1):
                if j > 0:
                    dp[i][j] = dp[i][j - 1]
                for l, p in lefts[j]:
                    dp[i][j] = max(dp[i][j], dp[i - 1][l] + p)
        return max(dp[k])

import heapq

class Solution:
    def maxEvents(self, events: List[List[int]]) -> int:
        events.sort()
        heap = []
        res = 0
        i = 0
        for t in range(min(e[0] for e in events), max(e[1] for e in events) + 1):
            while i < len(events) and events[i][0] <= t:
                heapq.heappush(heap, events[i][1])
                i += 1
            while heap and heap[0] < t:
                heapq.heappop(heap)
            if heap:
                res += 1
                heapq.heappop(heap)
        return res

class Solution:
    def find(self, i, j):
        if self.parent[i][j] == -1:
            return (i, j)
        self.parent[i][j] = self.find(self.parent[i][j][0], self.parent[i][j][1])
        return self.parent[i][j]

    def union(self, a, b, c, d):
        xa, ya = self.find(a, b)
        xb, yb = self.find(c, d)
        if (xa, ya) != (xb, yb):
            self.parent[xb][yb] = (xa, ya)

    def findMaxFish(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        self.parent = [[-1] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                if grid[i][j] != 0:
                    for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
                        if 0 <= x < m and 0 <= y < n and grid[x][y] != 0:
                            self.union(i, j, x, y)
        res = Counter()
        res[-1] = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] != 0:
                    res[self.find(i, j)] += grid[i][j]
        return max(res.values())

class Solution:
    def maxCount(self, banned: List[int], n: int, maxSum: int) -> int:
        banned = set(banned)
        s = 0
        res = 0
        for i in range(1, n + 1):
            if s + i <= maxSum and i not in banned:
                s += i
                res += 1
        return res

class Solution:
    def maximumJumps(self, nums: List[int], target: int) -> int:
        n = len(nums)
        dp = [float('-inf')] * n
        dp[n - 1] = 0
        for i in range(n - 2, -1, -1):
            for j in range(i + 1, n):
                if -target <= nums[i] - nums[j] <= target:
                    dp[i] = max(dp[i], 1 + dp[j])
        if dp[0] == float('-inf'):
            return -1
        return dp[0]

from collections import defaultdict

class Solution:
    def maxsplits(self, graph, i, prev, k, values):
        res = 0
        curr = values[i]
        res = 0
        for j in graph[i]:
            if j != prev:
                ncurr, nres = self.maxsplits(graph, j, i, k, values)
                curr += ncurr
                curr %= k
                res += nres
        if curr % k == 0:
            res += 1
            curr = 0
        return curr, res

    def maxKDivisibleComponents(self, n: int, edges: List[List[int]], values: List[int], k: int) -> int:
        graph = defaultdict(set)
        for a, b in edges:
            graph[a].add(b)
            graph[b].add(a)
        return self.maxsplits(graph, 0, -1, k, values)[1]

class Solution:
    def maxMoves(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        dp = [[0] * n for _ in range(m)]
        res = 0
        for j in range(n - 2, -1, -1):
            for i in range(m):
                for x in range(i - 1, i + 2):
                    if 0 <= x < m and grid[x][j + 1] > grid[i][j]:
                        dp[i][j] = max(dp[i][j], 1 + dp[x][j + 1])
                        if j == 0:
                            res = max(res, dp[i][j])
        return res

class Solution:
    def maxPalindromes(self, s: str, k: int) -> int:
        n = len(s)
        smallestpalodd = [[float('-inf'), float('inf')] for i in range(n)]
        smallestpaleven = [[float('-inf'), float('inf')] for i in range(n)]
        for i in range(n):
            x, y, p = i, i, 1
            l = 0
            while x - l >= 0 and y + l < n and s[x - l] == s[y + l]:
                l += 1
                if 2 * (l - 1) + p >= k:
                    if y + l < smallestpalodd[i][1]:
                        smallestpalodd[i][0] = x - l + 1
                        smallestpalodd[i][1] = y + l
                    break
        for i in range(n):
            x, y, p = i, i + 1, 2
            l = 0
            while x - l >= 0 and y + l < n and s[x - l] == s[y + l]:
                l += 1
                if 2 * (l - 1) + p >= k:
                    if y + l < smallestpaleven[i][1]:
                        smallestpaleven[i][0] = x - l + 1
                        smallestpaleven[i][1] = y + l
                    break
        dp = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            for j in range(i, n):
                if smallestpalodd[j][1] <= n and smallestpalodd[j][0] >= i:
                    dp[i] = max(dp[i], 1 + dp[smallestpalodd[j][1]])
                if smallestpaleven[j][1] <= n and smallestpaleven[j][0] >= i:
                    dp[i] = max(dp[i], 1 + dp[smallestpaleven[j][1]])
        return dp[0]

class Solution:
    def maxNonOverlapping(self, nums: List[int], target: int) -> int:
        n = len(nums)
        pos = {}
        p = 0
        pos[p] = 0
        prev = -1
        res = 0
        for i in range(n):
            p += nums[i]
            if pos.get(p - target, -1) > prev:
                res += 1
                prev = i
            pos[p] = i + 1
        return res

class Solution:
    def maxOperations(self, s: str) -> int:
        n = len(s)
        res = 0
        o = 0
        for i in range(n):
            if s[i] == '1':
                if i > 0 and s[i - 1] == '0':
                    res += o
                o += 1
        if s[-1] == '0':
            res += o
        return res

class Solution:
    def maxOperations(self, nums: List[int]) -> int:
        n = len(nums)
        res = 0
        i = 0
        while i < n - 1 and nums[i] + nums[i + 1] == nums[0] + nums[1]:
            i += 2
            res += 1
        return res

from collections import defaultdict

class Solution:
    def maxops(self, nums, i, j, s):
        res = 0
        if i >= j:
            return 0
        key = (i, j, s)
        if key in self.cache:
            return self.cache[key]
        if s == -1 or nums[i] + nums[j] == s:
            res = max(res, 1 + self.maxops(nums, i + 1, j - 1, s if s != -1 else nums[i] + nums[j]))
        if s == -1 or nums[i] + nums[i + 1] == s:
            res = max(res, 1 + self.maxops(nums, i + 2, j, s if s != -1 else nums[i] + nums[i + 1]))
        if s == -1 or nums[j - 1] + nums[j] == s:
            res = max(res, 1 + self.maxops(nums, i, j - 2, s if s != -1 else nums[j - 1] + nums[j]))
        self.cache[key] = res
        return res

    def maxOperations(self, nums: List[int]) -> int:
        n = len(nums)
        self.cache = {}
        return self.maxops(nums, 0, n - 1, -1)

from collections import Counter

class Solution:
    def numberOfPairs(self, nums: List[int]) -> List[int]:
        ctr = Counter(nums)
        res = [0, 0]
        for el in ctr:
            res[0] += ctr[el] // 2
            res[1] += ctr[el] % 2
        return res

import heapq
import bisect

class Solution:
    def maxPoints(self, grid, queries):
        m = len(grid)
        n = len(grid[0])
        heap = [(grid[0][0], 0, 0)]
        v = {(0, 0)}
        order = []
        while len(heap) > 0:
            curr, i, j = heapq.heappop(heap)
            order.append(curr)
            for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
                if 0 <= x < m and 0 <= y < n and (x, y) not in v:
                    v.add((x, y))
                    heapq.heappush(heap, (grid[x][y], x, y))
        myet = float('-inf')
        for i in range(len(order)):
            myet = max(myet, order[i])
            order[i] = myet
        res = []
        for q in queries:
            res.append(bisect.bisect_left(order, q))
        return res

class Solution:
    def maxPoints(self, points: List[List[int]]) -> int:
        m = len(points)
        n = len(points[0])
        prev = [0] * n
        curr = [0] * n
        pref = [float('-inf')] * n
        suff = [float('-inf')] * n
        for i in range(m):
            for j in range(n):
                curr[j] = max(curr[j], pref[j] - j + points[i][j] if i > 0 else points[i][j])
                curr[j] = max(curr[j], suff[j] + j + points[i][j] if i > 0 else points[i][j])
            prev, curr = curr, prev
            for j in range(n):
                pref[j] = max(prev[j] + j, pref[j - 1] if j > 0 else float('-inf'))
            for j in range(n - 1, -1, -1):
                suff[j] = max(prev[j] - j, suff[j + 1] if j + 1 < n else float('-inf'))
        return max(prev)

class Solution:
    def maximumRemovals(self, s: str, p: str, removable: List[int]) -> int:
        n = len(s)
        beg = 1
        end = len(removable)
        pos = {}
        for i in range(len(removable)):
            pos[removable[i]] = i
        res = 0
        while beg <= end:
            mid = (beg + end) // 2
            i = 0
            for j in range(n):
                if j not in pos or pos[j] >= mid:
                    if i < len(p) and s[j] == p[i]:
                        i += 1
            if i == len(p):
                res = mid
                beg = mid + 1
            else:
                end = mid - 1
        return res

import heapq

class Heap:
    def __init__(self):
        self.heap = []
        self.deleted = defaultdict(int)

    def push(self, val):
        heapq.heappush(self.heap, val)

    def clean(self):
        while len(self.heap) > 0 and self.heap[0] in self.deleted:
            self.deleted[self.heap[0]] -= 1
            if self.deleted[self.heap[0]] == 0:
                del self.deleted[self.heap[0]]
            heapq.heappop(self.heap)

    def __len__(self):
        self.clean()
        return len(self.heap)

    def min(self):
        self.clean()
        return self.heap[0]

    def __repr__(self):
        return str(self.deleted)

    def delete(self, val):
        self.deleted[val] += 1

    def pop(self):
        self.clean()
        return heapq.heappop(self.heap)

class Solution:
    def maximumRobots(self, chargeTimes: List[int], runningCosts: List[int], budget: int) -> int:
        n = len(chargeTimes)
        curr = Heap()
        currsum = 0
        i = 0
        res = 0
        for j in range(n):
            curr.push(-chargeTimes[j])
            currsum += runningCosts[j]
            while i < j and -curr.min() + (j - i + 1) * currsum > budget:
                currsum -= runningCosts[i]
                curr.delete(-chargeTimes[i])
                i += 1
            if -curr.min() + (j - i + 1) * currsum <= budget:
                res = max(res, j - i + 1)
        return res

from sortedcontainers import SortedList

def minops(A, B, s):
    A.sort(reverse = True)
    B = SortedList(B)
    u = 0
    for a in A:
        i = B.bisect_left(a)
        if i < len(B):
            B.pop(i)
        else:
            j = B.bisect_left(a - s)
            if j < len(B):
                B.pop(j)
                u += 1
            else:
                return float('inf')
    return u

class Solution:
    def maxTaskAssign(self, tasks: List[int], workers: List[int], pills: int, strength: int) -> int:
        n = len(tasks)
        tasks.sort()
        workers.sort(reverse = True)
        beg = 0
        end = n
        while beg <= end:
            mid = (beg + end) // 2
            if minops(tasks[:mid], workers[:mid], strength) <= pills:
                beg = mid + 1
            else:
                end = mid - 1
        return beg - 1

class Solution:
    def maxVowels(self, s: str, k: int) -> int:
        n = len(s)
        v = 0
        res = 0
        for i in range(n):
            if s[i] in "aeiou":
                v += 1
            if i >= k and s[i - k] in "aeiou":
                v -= 1
            res = max(res, v)
        return res

class Solution:
    def numberOfWeeks(self, milestones: List[int]) -> int:
        total = 0
        maxval = float('-inf')
        for m in milestones:
            total += m
            maxval = max(maxval, m)
        total -= maxval
        return min(2 * total + 1, total + maxval)

class Solution:
    def mostWordsFound(self, sentences: List[str]) -> int:
        return max([len(s.split()) for s in sentences])

class Solution:
    def canBeTypedWords(self, text: str, brokenLetters: str) -> int:
        broken = set(brokenLetters)
        return len([True for w in text.split() if len(set.intersection(set(w), broken)) == 0])

class Solution:
    def count(self, num, i, tight, s, x, cache):
        if i >= len(num):
            return s
        key = (i, tight, s)
        if key in cache:
            return cache[key]
        maxd = 1
        if tight:
            maxd = int(num[i])
        res = 0
        for d in range(maxd + 1):
            curr = self.count(num, i + 1, tight and d == maxd, s + int(d == 1 and (len(num) - i) % x == 0), x, cache)
            res += curr
        cache[key] = res
        return res

    def findMaximumNumber(self, k: int, x: int) -> int:
        end = 1
        while self.count("{:0b}".format(end), 0, True, 0, x, {}) <= k:
            end *= 2
        beg = end // 2
        res = beg
        while beg <= end:
            mid = (beg + end) // 2
            if self.count("{:0b}".format(mid), 0, True, 0, x, {}) <= k:
                res = mid
                beg = mid + 1
            else:
                end = mid - 1
        return res

class Solution:
    def maximumOddBinaryNumber(self, s: str) -> str:
        n = len(s)
        o = s.count('1')
        return '1' * (o - 1) + '0' * (n - o) + '1'

class Solution:
    def maximumOr(self, arr, k):
        n = len(arr)
        x = 1 << k
        p = [0] * (n + 1)
        s = [0] * (n + 1)
        for i in range(n):
            p[i + 1] |= p[i] | arr[i]
            s[i + 1] |= s[i] | arr[n - i - 1]
        res = 0
        for i in range(n):
            res = max(res, p[i] | (arr[i] * x) | s[n - i - 1])
        return res

from collections import Counter

class Solution:
    def maxPalindromesAfterOperations(self, words: List[str]) -> int:
        n = len(words)
        words.sort(key = lambda x: len(x))
        ctr = Counter()
        for w in words:
            ctr += Counter(w)
        evens = []
        for w in words:
            evens.append(2 * (len(w) // 2))
        evens.sort()
        for c in sorted(ctr, key = lambda x: ctr[x]):
            for i in range(len(evens)):
                give = min(2 * (ctr[c] // 2), evens[i])
                evens[i] -= give
                ctr[c] -= give
        return evens.count(0)

from collections import defaultdict

class Solution:
    def getPath(self, node, graph, visited, time, values, maxTime):
        if node == 0:
            currQuality = sum([values[i] for i in visited])
            if currQuality >= self.maxQuality:
                self.maxQuality = currQuality
        for j, t in graph[node]:
            if time + t <= maxTime:
                self.getPath(j, graph, visited.union({j}), time + t, values, maxTime)

    def maximalPathQuality(self, values: List[int], edges: List[List[int]], maxTime: int) -> int:
        self.maxQuality = float('-inf')
        graph = defaultdict(list)
        for a, b, t in edges:
            graph[a].append((b, t))
            graph[b].append((a, t))
        self.getPath(0, graph, {0}, 0, values, maxTime)
        return self.maxQuality

import heapq

class Solution:
    def maxPerformance(self, n: int, speed: List[int], efficiency: List[int], k: int) -> int:
        n = len(speed)
        vals = []
        for i in range(n):
            vals.append((efficiency[i], speed[i]))
        vals.sort()
        heap = []
        total = 0
        res = 0
        for i in range(n - 1, -1, -1):
            heapq.heappush(heap, vals[i][1])
            total += vals[i][1]
            if len(heap) > k:
                total -= heapq.heappop(heap)
            res = max(res, vals[i][0] * total)
        return res % (10 ** 9 + 7)

from collections import *

class Solution:
    def maximumPoints(self, edges: List[List[int]], coins: List[int], k: int) -> int:
        graph = defaultdict(set)
        for a, b in edges:
            graph[a].add(b)
            graph[b].add(a)
        cache = {}
        def maxscore(curr, prev, reduced):
            reduced = min(reduced, 14)
            key = (curr, prev, reduced)
            if key in cache:
                return cache[key]
            a = coins[curr] // pow(2, reduced) - k
            b = coins[curr] // pow(2, reduced + 1)
            for j in graph[curr]:
                if j == prev:
                    continue
                a += maxscore(j, curr, reduced)
                b += maxscore(j, curr, reduced + 1)
            res = max(a, b)
            cache[key] = res
            return res
        return maxscore(0, -1, 0)

class Solution:
    def maximumPoints(self, enemyEnergies: List[int], currentEnergy: int) -> int:
        n = len(enemyEnergies)
        enemyEnergies.sort(reverse = True)
        if currentEnergy < enemyEnergies[-1]:
            return 0
        for i in range(n - 1):
            currentEnergy += enemyEnergies[i]
        return currentEnergy // enemyEnergies[-1]

class Solution:
    def maxScore(self, n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
        dp = [0] * n
        ndp = [0] * n
        for day in range(k - 1, -1, -1):
            for city in range(n):
                ndp[city] = stayScore[day][city] + dp[city]
                for other in range(n):
                    ndp[city] = max(ndp[city], travelScore[city][other] + dp[other])
            dp, ndp = ndp, dp
        return max(dp)

class Solution:
    def maxScore(self, cardPoints: List[int], k: int) -> int:
        n = len(cardPoints)
        k = n - k
        currSum = sum(cardPoints[:k])
        minSum = currSum
        for i in range(n - k):
            currSum = currSum - cardPoints[i] + cardPoints[i + k]
            minSum = min(minSum, currSum)
        return sum(cardPoints) - minSum

import bisect

class Solution:
    def maximumPopulation(self, logs: List[List[int]]) -> int:
        pops = []
        for b, d in logs:
            bisect.insort(pops, (b, 1))
            bisect.insort(pops, (d, -1))
        mpop = 0
        mpopyear = None
        curr = 0
        for year, p in pops:
            curr += p
            if curr > mpop:
                mpop = curr
                mpopyear = year
        return mpopyear

from itertools import permutations

class Solution:
    def maxGoodNumber(self, nums: List[int]) -> int:
        b = lambda x: "{:0b}".format(x)
        return max([int(b(x) + b(y) + b(z), 2) for x, y, z in permutations(nums)])

class Solution:
    def maxProductDifference(self, nums: List[int]) -> int:
        nums.sort()
        return nums[-1] * nums[-2] - nums[0] * nums[1]

class Solution:
    def maxProduct(self, root: Optional[TreeNode]) -> int:
        M = 10 ** 9 + 7
        self.p = 0
        def inorder(r, t = None):
            res = 0
            if r:
                res += inorder(r.left, t)
                res += r.val
                res += inorder(r.right, t)
                if t != None:
                    self.p = max(self.p, res * (t - res))
            return res
        total = inorder(root)
        inorder(root, total)
        return self.p % M

class Solution:
    def maxProduct(self, nums, k, limit):
        @cache
        def zero(i, tot, add, has):
            if i == len(nums):
                return has and tot == k

            if zero(i + 1, tot, add, has):
                return True

            if nums[i] <= limit:
                new_tot = tot + nums[i] if add else tot - nums[i]
                new_has = has or (nums[i] == 0)
                if zero(i + 1, new_tot, not add, new_has):
                    return True

            return False

        @cache
        def dp(i, p, rem, mx, emp):
            if i >= len(nums):
                if not emp and rem == 0:
                    return 1
                return float('-inf')
            a = dp(i + 1, p, rem, mx, emp)
            b = float('-inf')
            if nums[i] <= mx:
                b = nums[i] * dp(i + 1, -p, rem - p * nums[i], mx // nums[i] if nums[i] > 0 else float('inf'), False)
            return max(a, b)

        return max(dp(0, 1, k, limit, True), 0 if zero(0, 0, True, False) else -1, -1)

class Solution:
    def maxPalindrome(self, s, i, j, cache):
        key = 1100 * i + j
        if key in cache:
            return cache[key]
        if i == j:
            cache[key] = 1
        elif s[i] == s[j] and i + 1 == j:
            cache[key] = 2
        elif s[i] == s[j]:
            cache[key] = self.maxPalindrome(s, i + 1, j - 1, cache) + 2
        else:
            cache[key] = max(self.maxPalindrome(s, i, j - 1, cache), self.maxPalindrome(s, i + 1, j, cache))
        return cache[key]

    def maxProduct(self, s: str) -> int:
        self.cache = {}
        maxP = float('-inf')
        n = len(s)
        for mask in range(1 << n):
            sub = ""
            rest = ""
            for j in range(n):
                if mask & (1 << j):
                    sub += s[j]
                else:
                    rest += s[j]
            if len(sub) > 0 and len(rest) > 0:
                maxP = max(maxP, self.maxPalindrome(sub, 0, len(sub) - 1, {}) * self.maxPalindrome(rest, 0, len(rest) - 1, {}))
        return maxP

class Solution:
    def maxProduct(self, nums: List[int]) -> int:
        a, b = 0, 0
        for el in nums:
            temp, a, b = sorted([a, b, el])
        return (a - 1) * (b - 1)

class Solution:
    def maxProduct(self, words: List[str]) -> int:
        n = len(words)
        lens = [len(word) for word in words]
        words = [set(word) for word in words]
        mprod = 0
        for i in range(n):
            for j in range(n):
                if i != j:
                    if len(set.intersection(words[i], words[j])) == 0:
                        mprod = max(mprod, lens[i] * lens[j])
        return mprod

class Solution:
    def maxProfit(self, n, edges, score):
        pre = [0] * n
        for u, v in edges:
            pre[v] |= 1 << u
        m = 1 << n
        dp = [float('-inf')] * m
        dp[0] = 0
        for mask in range(m):
            cur = dp[mask]
            if cur < 0:
                continue
            pos = mask.bit_count() + 1
            for i in range(n):
                if not (mask >> i & 1) and (mask & pre[i]) == pre[i]:
                    nxt = mask | (1 << i)
                    dp[nxt] = max(dp[nxt], cur + score[i] * pos)
        return dp[m - 1]

class Solution:
    def maxRepeating(self, sequence: str, word: str) -> int:
        n = len(sequence)
        m = len(word)
        res = 0
        for i in range(n):
            j = i
            while j < n and sequence[j] == word[(j - i) % m]:
                j += 1
            res = max(res, (j - i) // m)
        return res

class Solution:
    def maximumRows(self, mat: List[List[int]], cols: int) -> int:
        m = len(mat)
        n = len(mat[0])
        res = 0
        for i in range(1 << n):
            ctr = 0
            for j in range(n):
                if (i & (1 << j)) != 0:
                    ctr += 1
            if ctr == cols:
                curr = 0
                for x in range(m):
                    covered = True
                    for y in range(n):
                        if mat[x][y] == 1 and (i & (1 << y)) == 0:
                            covered = False
                            break
                    if covered:
                        curr += 1
                res = max(res, curr)
        return res

class Solution:
    def maxRunTime(self, n: int, batteries: List[int]) -> int:
        beg = 0
        end = sum(batteries)
        res = beg
        while beg <= end:
            mid = (beg + end) // 2
            used = 0
            for el in batteries:
                used += min(el, mid)
            if used >= mid * n:
                res = mid
                beg = mid + 1
            else:
                end = mid - 1
        return res

from collections import *

class Solution:
    def maxscore(self, graph, curr, prev, values, nonzero):
        key = (curr, prev, nonzero)
        if key in self.cache:
            return self.cache[key]
        take = values[curr]
        nottake = 0
        leaf = True
        for j in graph[curr]:
            if j != prev:
                leaf = False
                take += self.maxscore(graph, j, curr, values, nonzero)
                nottake += self.maxscore(graph, j, curr, values, True)
        if leaf and not nonzero:
            take = 0
        res = max(take, nottake)
        self.cache[key] = res
        return res

    def maximumScoreAfterOperations(self, edges: List[List[int]], values: List[int]) -> int:
        graph = defaultdict(set)
        for a, b in edges:
            graph[a].add(b)
            graph[b].add(a)
        self.cache = {}
        return self.maxscore(graph, 0, -1, values, False)

class Solution:
    def maxScore(self, s: str) -> int:
        n = len(s)
        total = s.count("1")
        curr = 0
        res = 0
        for i in range(n - 1):
            if s[i] == "1":
                total -= 1
            else:
                curr += 1
            res = max(res, curr + total)
        return res

class Solution:
    def maximumScore(self, grid: List[List[int]]) -> int:
        n = len(grid)
        pf = [[0] * (n + 1) for _ in range(n)]
        for j in range(n):
            for i in range(n):
                pf[j][i + 1] = pf[j][i] + grid[i][j]
        dp = [[0] * 2 for _ in range(n + 1)]
        ndp = [[0] * 2 for _ in range(n + 1)]
        for i in range(n - 1, -1, -1):
            for last in range(n + 1):
                for bigger in range(2):
                    for l in range(n + 1):
                        score = 0
                        if l < last:
                            score += pf[i][last] - pf[i][l]
                        elif l > last and bigger and i > 0:
                            score += pf[i - 1][l] - pf[i - 1][last]
                        ndp[last][bigger] = max(ndp[last][bigger], score + dp[l][int(l >= last)])
            dp, ndp = ndp, dp
        return max(dp[0][0], dp[0][1])

class Solution:
    def maxScore(self, nums, multipliers, i, j, k, m):
        if i >= m or j > k:
            return 0
        key = (i, j, k)
        if key in self.cache:
            return self.cache[key]
        a = multipliers[i] * nums[j] + self.maxScore(nums, multipliers, i + 1, j + 1, k, m)
        b = multipliers[i] * nums[k] + self.maxScore(nums, multipliers, i + 1, j, k - 1, m)
        res = max(a, b)
        self.cache[key] = res
        return res

    def maximumScore(self, nums: List[int], multipliers: List[int]) -> int:
        m = len(multipliers)
        n = len(nums)
        self.cache = {}
        return self.maxScore(nums, multipliers, 0, 0, n - 1, m)

class Solution:
    def maximumScore(self, a: int, b: int, c: int) -> int:
        a, b, c = sorted([a, b, c])
        res = 0
        while b > 0 and c > 0:
            res += 1
            b -= 1
            c -= 1
            a, b, c = sorted([a, b, c])
        return res

class Solution:
    def maximumGain(self, s: str, x: int, y: int) -> int:
        n = len(s)
        res = 0
        order = [("ab", x), ("ba", y)]
        order.sort(key = lambda p: -p[1])
        for ss, cost in order:
            stack = []
            for c in s:
                if stack and stack[-1] + c == ss:
                    stack.pop()
                    res += cost
                else:
                    stack.append(c)
            s = "".join(stack)
        return res

class Solution:
    def maximumScore(self, nums: List[int], k: int) -> int:
        n = len(nums)
        next_lowest = [n for i in range(n)]
        prev_lowest = [-1 for i in range(n)]
        res = 0
        stack = []
        for i in range(n):
            while len(stack) > 0 and nums[i] < nums[stack[-1]]:
                curr = stack.pop()
                next_lowest[curr] = i
            if len(stack) > 0:
                prev_lowest[i] = stack[-1]
            stack.append(i)
        for i in range(n):
            if prev_lowest[i] < k < next_lowest[i]:
                currArea = (next_lowest[i] - prev_lowest[i] - 1) * nums[i]
                res = max(res, currArea)
        return res

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)
        for i in range(n):
            intervals[i].append(i)
        intervals.sort()
        nxt = [n] * n
        for i in range(n):
            beg = i + 1
            end = n - 1
            while beg <= end:
                mid = (beg + end) // 2
                if intervals[mid][0] > intervals[i][1]:
                    end = mid - 1
                else:
                    beg = mid + 1
            nxt[i] = end + 1
        dp = [[(0, tuple())] * 5 for _ in range(n + 1)]
        for i in range(n - 1, -1, -1):
            for rem in range(5):
                a, avals = dp[i + 1][rem]
                b, bvals = dp[nxt[i]][rem - 1] if rem > 0 else (float('-inf'), tuple())
                b += intervals[i][2]
                if a > b:
                    dp[i][rem] = a, avals
                else:
                    bvals = sorted(tuple([intervals[i][3]] + list(bvals)))
                    if b > a:
                        dp[i][rem] = b, bvals
                    else:
                        dp[i][rem] = a, min(avals, bvals)
        return dp[0][4][1]

class Solution:
    def maximumsSplicedArray(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        n1 = 0
        n2 = 0
        minyet = 0
        maxyet = 0
        maxdiff = 0
        mindiff = float('inf')
        for i in range(n):
            n1 += nums1[i]
            n2 += nums2[i]
            maxdiff = max(maxdiff, n1 - n2 - minyet)
            mindiff = min(mindiff, n1 - n2 - maxyet)
            if n1 - n2 < minyet:
                minyet = n1 - n2
            if n1 - n2 > maxyet:
                maxyet = n1 - n2
        return max(n1 - mindiff, n2 + maxdiff)

class Solution:
    def maxScoreWords(self, words, letters, score):
        ctr = [0] * 26
        for c in letters:
            ctr[ord(c) - ord('a')] += 1
        @lru_cache(maxsize = None)
        def count(i, rem):
            if i >= len(words):
                return 0
            res = count(i + 1, rem)
            s = 0
            pos = True
            newrem = list(rem)
            for c in words[i]:
                if newrem[ord(c) - ord('a')] > 0:
                    s += score[ord(c) - ord('a')]
                    newrem[ord(c) - ord('a')] -= 1
                else:
                    pos = False
                    break
            if pos:
                res = max(res, s + count(i + 1, tuple(newrem)))
            return res
        return count(0, tuple(ctr))

class Solution:
    def maxSideLength(self, mat: List[List[int]], threshold: int) -> int:
        m = len(mat)
        n = len(mat[0])
        p = [[0] * (n + 1) for _ in range(m)]
        for i in range(m):
            for j in range(n):
                p[i][j + 1] += p[i][j] + mat[i][j]
        beg = 1
        end = min(m, n)
        res = 0
        while beg <= end:
            mid = (beg + end) // 2
            found = False
            for i in range(m - mid + 1):
                for j in range(n - mid + 1):
                    s = 0
                    for k in range(i, i + mid):
                        s += p[k][j + mid] - p[k][j]
                    if s <= threshold:
                        found = True
                        break
            if found:
                res = mid
                beg = mid + 1
            else:
                end = mid - 1
        return res

import heapq

class Solution:
    def maxSpending(self, values: List[List[int]]) -> int:
        res = 0
        m = len(values)
        n = len(values[0])
        for i in range(m):
            values[i].reverse()
        pos = [0] * m
        heap = []
        for i in range(m):
            if pos[i] < n:
                heapq.heappush(heap, (values[i][pos[i]], i))
                pos[i] += 1
        d = 1
        while len(heap) > 0:
            currval, i = heapq.heappop(heap)
            res += d * currval
            if pos[i] < n:
                heapq.heappush(heap, (values[i][pos[i]], i))
                pos[i] += 1
            d += 1
        return res

class Solution:
    def maximumEvenSplit(self, finalSum: int) -> List[int]:
        if finalSum % 2 == 1:
            return []
        pos = 0
        i = 1
        while i * (i + 1) <= finalSum:
            k = finalSum - i * (i + 1)
            if k % 2 == 0 and k > 2 * i:
                pos = i
            i += 1
        return [2 * i for i in range(1, pos + 1)] + [finalSum - pos * (pos + 1)]

from collections import defaultdict

class Solution:
    def maxStarSum(self, vals: List[int], edges: List[List[int]], k: int) -> int:
        graph = defaultdict(list)
        for i in range(len(vals)):
            graph[i] = []
        for a, b in edges:
            graph[a].append((b, vals[b]))
            graph[b].append((a, vals[a]))
        res = float('-inf')
        for el in graph:
            curr = vals[el]
            nb = []
            for j, c in graph[el]:
                nb.append(c)
            nb.sort(reverse = True)
            for i in range(min(len(nb), k)):
                curr += max(nb[i], 0)
            res = max(res, curr)
        return res

class Solution:
    def maxStrength(self, nums: List[int]) -> int:
        nums.sort(key = lambda x: (2 if x == 0 else int(x < 0), -abs(x)))
        res = float('-inf')
        p = 1
        for el in nums:
            p *= el
            res = max(res, p)
        return res

class Solution:
    def msum(self, p, i, rem, sign):
        if rem < 0:
            return float('-inf')
        if i >= len(p):
            if rem == 0 and sign == -1:
                return 0
            return float('-inf')
        key = (i, rem, sign)
        if key in self.cache:
            return self.cache[key]
        a = self.msum(p, i + 1, rem, sign)
        x = (rem + 1) // 2
        s = 1 if x & 1 else -1
        b = sign * p[i] * x * s + self.msum(p, i + 1, rem - 1, -sign)
        c = float('-inf')
        if sign == 1:
            c = p[i] * x * s + p[i] * (x - 1) * s + self.msum(p, i + 1, rem - 2, sign)
        res = max(a, b, c)
        self.cache[key] = res
        return res

    def maximumStrength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] = p[i] + nums[i]
        self.cache = {}
        return self.msum(p, 0, 2 * k, -1)

class Node:
    def __init__(self):
        self.child = [None, None]
        self.ctr = 0

class Trie:
    def __init__(self):
        self.root = Node()

    def insert(self, s):
        curr = self.root
        curr.ctr += 1
        for c in s:
            c = int(c)
            if curr.child[c] == None:
                curr.child[c] = Node()
            curr = curr.child[c]
            curr.ctr += 1

    def delete(self, s):
        curr = self.root
        curr.ctr -= 1
        for c in s:
            c = int(c)
            if curr.child[c] == None:
                curr.child[c] = Node()
            curr = curr.child[c]
            curr.ctr -= 1

    def getmax(self, s):
        curr = self.root
        res = 0
        for c in s:
            c = int(c)
            if curr.child[1 - c] != None and curr.child[1 - c].ctr > 0:
                curr = curr.child[1 - c]
                res = 2 * res + 1
            elif curr.child[c] != None and curr.child[c].ctr > 0:
                curr = curr.child[c]
                res = 2 * res
        return res

class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        n = len(nums)
        val = lambda x: "{:021b}".format(x)
        nums.sort()
        trie = Trie()
        i = 0
        res = 0
        for j in range(n):
            trie.insert(val(nums[j]))
            while i < j and nums[j] - nums[i] > nums[i]:
                trie.delete(val(nums[i]))
                i += 1
            if nums[j] - nums[i] <= nums[i]:
                res = max(res, trie.getmax(val(nums[j])))
        return res

