class Solution:
    def shift(self, mask, l, sb):
        mask &= ~(1 << l - 1)
        mask <<= 1
        if sb:
            mask |= 1
        return mask

    def check(self, seats, i, j, m, n):
        for dx, dy in [(0, -1), (-1, -1), (-1, 1)]:
            x = i + dx
            y = j + dy
            if 0 <= x < m and 0 <= y < n and seats[x][y] == "S":
                return False
        return True

    def maxcount(self, seats, i, j, m, n, mask):
        if i >= m:
            return 0
        key = (i, j, mask)
        if key in self.cache:
            return self.cache[key]
        newi = i
        newj = j + 1
        if newj == n:
            newi += 1
            newj = 0
        res = self.maxcount(seats, newi, newj, m, n, self.shift(mask, n + 1, False))
        if seats[i][j] == "." and self.check(seats, i, j, m, n):
            seats[i][j] = "S"
            res = max(res, 1 + self.maxcount(seats, newi, newj, m, n, self.shift(mask, n + 1, True)))
            seats[i][j] = "."
        self.cache[key] = res
        return res

    def maxStudents(self, seats: List[List[str]]) -> int:
        self.cache = {}
        return self.maxcount(seats, 0, 0, len(seats), len(seats[0]), 0)

class Solution:
    def maxSumMinProduct(self, nums: List[int]) -> int:
        n = len(nums)
        stack = []
        next_smaller = [n] * n
        prev_smaller = [-1] * n
        p = [0]
        for i in range(n):
            while len(stack) > 0 and nums[i] < nums[stack[-1]]:
                curr = stack.pop()
                next_smaller[curr] = i
            if len(stack) > 0:
                prev_smaller[i] = stack[-1]
            stack.append(i)
            p.append(p[-1] + nums[i])
        res = float('-inf')
        for i in range(n):
            l = prev_smaller[i]
            r = next_smaller[i]
            res = max(res, nums[i] * (p[r] - p[l + 1]))
        return res % (10 ** 9 + 7)

class Solution:
    def maximumSum(self, arr: List[int]) -> int:
        n = len(arr)
        p = [0] * n
        s = [0] * n
        p[0] = arr[0]
        s[-1] = arr[-1]
        for i in range(1, n):
            p[i] = max(arr[i], arr[i] + p[i - 1])
        for i in range(n - 2, -1, -1):
            s[i] = max(arr[i], arr[i] + s[i + 1])
        res = max(p)
        for i in range(n - 2):
            res = max(res, p[i] + s[i + 2])
        return res

class Solution:
    def maxSubArray(self, nums: List[int]) -> int:
        n = len(nums)
        maxSoFar = float('-inf')
        maxEndingHere = 0
        for i in range(n):
            maxEndingHere += nums[i]
            maxSoFar = max(maxSoFar, maxEndingHere)
            maxEndingHere = max(maxEndingHere, 0)
        return maxSoFar

import heapq

class Solution:
    def maxScore(self, nums1: List[int], nums2: List[int], k: int) -> int:
        n = len(nums1)
        vals = [(nums2[i], nums1[i]) for i in range(n)]
        if k == 1:
            return max(a * b for a, b in vals)
        vals.sort(reverse = True)
        res = 0
        s = 0
        heap = []
        for i in range(n):
            heapq.heappush(heap, vals[i][1])
            s += vals[i][1]
            if len(heap) > k - 1:
                s -= heapq.heappop(heap)
            if len(heap) == k - 1 and i < n - 1:
                res = max(res, vals[i + 1][0] * (vals[i + 1][1] + s))
        return res

class Solution:
    def maxSumBST(self, root: Optional[TreeNode]) -> int:
        self.res = 0
        def msum(root):
            if not root:
                return 0, float('inf'), float('-inf'), True
            lsum, lmin, lmax, lvalid = msum(root.left)
            rsum, rmin, rmax, rvalid = msum(root.right)
            currsum = lsum + rsum + root.val
            currmin = min(root.val, lmin, rmin)
            currmax = max(root.val, lmax, rmax)
            currvalid = lvalid and rvalid
            if lmax >= root.val or rmin <= root.val:
                currvalid = False
            if currvalid:
                self.res = max(self.res, currsum)
            return currsum, currmin, currmax, currvalid
        msum(root)
        return self.res

class Solution:
    def maxSubarraySumCircular(self, arr: List[int]) -> int:
        n = len(arr)
        total = sum(arr)
        res = total
        maxsumending = float('-inf')
        for el in arr:
            maxsumending = max(el, el + maxsumending)
            res = max(res, maxsumending)
        minsumending = float('inf')
        for el in arr:
            minsumending = min(el, el + minsumending)
            if minsumending != total:
                res = max(res, total - minsumending)
        return res

from collections import defaultdict

class Solution:
    def maxSumRangeQuery(self, nums: List[int], requests: List[List[int]]) -> int:
        n = len(nums)
        nums.sort()
        res = 0
        freq = defaultdict(int)
        for l, r in requests:
            freq[l] += 1
            freq[r + 1] -= 1
        for i in range(1, n + 1):
            freq[i] += freq[i - 1]
        weights = sorted([freq[i] for i in range(n)])
        for i in range(n):
            res += nums[i] * weights[i]
        return res % (10 ** 9 + 7)

class Solution:
    def maxSumOfThreeSubarrays(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        starts = [(float('-inf'), -1)] * n
        ends = [(float('-inf'), -1)] * n
        s = 0
        for i in range(n):
            s += nums[i]
            if i >= k:
                s -= nums[i - k]
            if i >= k - 1:
                starts[i - k + 1] = (s, k - i - 1)
                ends[i] = (s, k - i - 1)
        for i in range(1, n):
            ends[i] = max(ends[i], ends[i - 1])
        for i in range(n - 2, -1, -1):
            starts[i] = max(starts[i], starts[i + 1])
        res = (float('-inf'), -n, -n, -n)
        s = 0
        for i in range(n):
            s += nums[i]
            if i >= k:
                s -= nums[i - k]
            if k - 1 < i < n - 1:
                currs = ends[i - k][0] + s + starts[i + 1][0]
                res = max(res, (currs, ends[i - k][1], k - i - 1, starts[i + 1][1]))
        return [-res[1], -res[2], -res[3]]

from collections import Counter

class Solution:
    def maxSum(self, arr: List[int], m: int, k: int) -> int:
        n = len(arr)
        ctr = Counter()
        res = 0
        s = 0
        for i in range(n):
            ctr[arr[i]] += 1
            s += arr[i]
            if i >= k:
                s -= arr[i - k]
                ctr[arr[i - k]] -= 1
                if ctr[arr[i - k]] == 0:
                    del ctr[arr[i - k]]
            if i >= k - 1 and len(ctr) >= m:
                res = max(res, s)
        return res

class Solution:
    def maxSum(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        res = 0
        for i in range(1, m - 1):
            for j in range(1, n - 1):
                curr = 0
                for x in range(i - 1, i + 2):
                    for y in range(j - 1, j + 2):
                        curr += grid[x][y]
                curr -= grid[i][j - 1] + grid[i][j + 1]
                res = max(res, curr)
        return res

from collections import Counter

class Solution:
    def maximumSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        s = 0
        res = 0
        ctr = Counter()
        l = 0
        for i in range(n):
            s += nums[i]
            if ctr[nums[i]] == 0:
                l += 1
            ctr[nums[i]] += 1
            if i >= k:
                s -= nums[i - k]
                ctr[nums[i - k]] -= 1
                if ctr[nums[i - k]] == 0:
                    l -= 1
            if i >= k - 1:
                if l == k:
                    res = max(res, s)
        return res

from collections import defaultdict

M = 10 ** 9 + 7

class SegTree:
    def __init__(self):
        self.tree = defaultdict(lambda: (0, 0, 0, 0))

    def merge(self, l, r):
        l_with_f_with_end, l_with_f_without_end, l_without_f_with_end, l_without_f_without_end = l
        r_with_f_with_end, r_with_f_without_end, r_without_f_with_end, r_without_f_without_end = r
        r_end_max = max(r_with_f_with_end, r_without_f_with_end)
        r_without_end_max = max(r_with_f_without_end, r_without_f_without_end)
        return (max(l_with_f_with_end + r_without_f_with_end, l_with_f_without_end + r_end_max), max(l_with_f_with_end + r_without_f_without_end, l_with_f_without_end + r_without_end_max), max(l_without_f_with_end + r_without_f_with_end, l_without_f_without_end + r_end_max), max(l_without_f_with_end + r_without_f_without_end, l_without_f_without_end + r_without_end_max))

    def update(self, index, val, i, j, k):
        if i + 1 == j:
            self.tree[k] = (val, 0, 0, 0)
            return
        mid = (i + j) // 2
        if index < mid:
            self.update(index, val, i, mid, 2 * k)
        else:
            self.update(index, val, mid, j, 2 * k + 1)
        self.tree[k] = self.merge(self.tree[2 * k], self.tree[2 * k + 1])

    def query(self, x, y, i, j, k):
        if y - 1 < i or x >= j:
            return (0, 0, 0, 0)
        if i >= x and j <= y:
            return self.tree[k]
        mid = (i + j) // 2
        return self.merge(self.query(x, y, i, mid, 2 * k), self.query(x, y, mid, j, 2 * k + 1))

class Solution:
    def maximumSumSubsequence(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        res = 0
        segtree = SegTree()
        for i in range(n):
            segtree.update(i, nums[i], 0, n, 1)
        for i, val in queries:
            segtree.update(i, val, 0, n, 1)
            res += max(segtree.query(0, n, 0, n, 1))
            res %= M
        return res

class Solution:
    def maxSumTwoNoOverlap(self, nums: List[int], firstLen: int, secondLen: int) -> int:
        n = len(nums)
        p = [0]
        for el in nums:
            p.append(p[-1] + el)
        msum = 0
        for f, s in [(firstLen, secondLen), (secondLen, firstLen)]:
            for i in range(f - 1, n - s + 1):
                for j in range(i + 1, n - s + 1):
                    l = p[i + 1] - p[i - f + 1]
                    r = p[j + s] - p[j]
                    msum = max(msum, l + r)
        return msum

class SegTreeNode:
    def __init__(self, val):
        self.val = val

class SegTree:
    def __init__(self, n, func, init):
        self.nodes = defaultdict(lambda: SegTreeNode(init))
        self.func = func
        self.init = init
        self.beg = 0
        self.end = n

    def query(self, a, b, x = 0, y = None, k = 1):
        if y == None:
            y = self.end
        if b < x or a > y:
            return self.init
        if a <= x and b >= y:
            return self.nodes[k].val
        mid = (x + y) // 2
        l = self.query(a, b, x, mid, 2 * k)
        r = self.query(a, b, mid + 1, y, 2 * k + 1)
        return self.func(l, r)

    def update(self, i, val, x = 0, y = None, k = 1):
        if y == None:
            y = self.end
        if x == y:
            self.nodes[k].val = self.func(val, self.nodes[k].val)
            return
        mid = (x + y) // 2
        if i <= mid:
            self.update(i, val, x, mid, 2 * k)
        else:
            self.update(i, val, mid + 1, y, 2 * k + 1)
        self.nodes[k].val = self.func(self.nodes[2 * k].val, self.nodes[2 * k + 1].val)

class Solution:
    def maximumSumQueries(self, nums1: List[int], nums2: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums1)
        q = len(queries)
        for i in range(n):
            nums1[i] = (nums1[i], i)
            nums2[i] = (nums2[i], i)
        nums1.sort()
        res = [-1] * q
        for i in range(q):
            queries[i].append(i)
        queries.sort(reverse = True)
        i = n - 1
        vals = set()
        segtree = SegTree(10 ** 9, func = max, init = float('-inf'))
        for x, y, pos in queries:
            while i >= 0 and nums1[i][0] >= x:
                segtree.update(nums2[nums1[i][1]][0], nums1[i][0] + nums2[nums1[i][1]][0])
                i -= 1
            currval = segtree.query(y, 10 ** 9)
            if currval != float('-inf'):
                res[pos] = max(res[pos], currval)
        return res

class Solution:
    def maximizeSum(self, nums: List[int], k: int) -> int:
        m = max(nums)
        return m * k + k * (k - 1) // 2

class Solution:
    def maximumSwap(self, num: int) -> int:
        currmax = num
        d = list(str(num))
        n = len(d)
        for i in range(n - 1):
            j = max([(int(d[k]), k) for k in range(i + 1, n)])[1]
            if int(d[j]) > int(d[i]):
                d[i], d[j] = d[j], d[i]
                break
        currmax = max(currmax, int("".join(d)))
        return currmax

from collections import deque

class Solution:
    def maximumTastiness(self, price: List[int], k: int) -> int:
        n = len(price)
        if n == 1:
            return 0
        price.sort()
        def possible(price, n, gap):
            i = 0
            rem = k - 1
            for j in range(n):
                if price[j] - price[i] >= gap:
                    rem -= 1
                    i = j
            return rem <= 0
        beg = 0
        end = price[-1] - price[0]
        res = 0
        while beg <= end:
            mid = (beg + end) // 2
            if possible(price, n, mid):
                res = mid
                beg = mid + 1
            else:
                end = mid - 1
        return res

from collections import *

class Solution:
    def maximumTotalDamage(self, power: List[int]) -> int:
        ctr = defaultdict(int)
        for el in power:
            ctr[el] += el
        dp = defaultdict(int)
        vals = sorted(ctr.items())
        i = 0
        mx = 0
        for x, val in vals:
            while i < len(vals) and vals[i][0] < x - 2:
                mx = max(mx, dp[vals[i][0]])
                i += 1
            dp[x] = val + mx
        if len(dp) == 0:
            return 0
        return max(dp.values())

class Solution:
    def maximumImportance(self, n: int, roads: List[List[int]]) -> int:
        roadctr = [0] * n
        for a, b in roads:
            roadctr[a] += 1
            roadctr[b] += 1
        total = 0
        bigcities = sorted(range(n), key = lambda c: roadctr[c])
        for i in range(n):
            total += (i + 1) * roadctr[bigcities[i]]
        return total

class Solution:
    def maxTotalReward(self, rewardValues: List[int]) -> int:
        s = {0}
        rewardValues.sort()
        for el in rewardValues:
            s |= {x + el for x in s if el > x}
        return max(s)

class Solution:
    def num5divs(self, num):
        t = 0
        f = 0
        while num % 5 == 0:
            num = num // 5
            f += 1
        while num % 2 == 0:
            num = num // 2
            t += 1
        return (t, f)

    def maxTrailingZeros(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        vertprefix = [[(0, 0)] for i in range(n)]
        horprefix = [[(0, 0)] for i in range(m)]
        for i in range(m):
            for j in range(n):
                grid[i][j] = self.num5divs(grid[i][j])
                a, b = grid[i][j]
                ha, hb = horprefix[i][-1]
                va, vb = vertprefix[j][-1]
                horprefix[i].append((ha + a, hb + b))
                vertprefix[j].append((va + a, vb + b))
        maxtrail = 0
        for i in range(m):
            for j in range(n):
                hors = [vertprefix[j][i], (vertprefix[j][-1][0] - vertprefix[j][i + 1][0], vertprefix[j][-1][1] - vertprefix[j][i + 1][1])]
                verts = [horprefix[i][j], (horprefix[i][-1][0] - horprefix[i][j + 1][0], horprefix[i][-1][1] - horprefix[i][j + 1][1])]
                for ha, hb in hors:
                    for va, vb in verts:
                        a, b = grid[i][j]
                        maxtrail = max(maxtrail, min(a + ha + va, b + hb + vb))
        return maxtrail

class Solution:
    def lenList(self, head):
        if head:
            return 1 + self.lenList(head.next)
        return 0

    def pairSum(self, head: Optional[ListNode]) -> int:
        sums = {}
        n = self.lenList(head)
        curr = head
        i = 0
        while curr:
            key = min(i, n - i - 1)
            sums[key] = sums.get(key, 0) + curr.val
            curr = curr.next
            i += 1
        return max(sums.values())

class Solution:
    def maxSum(self, nums: List[int]) -> int:
        if max(nums) < 0:
            return max(nums)
        return sum(el for el in set(nums) if el >= 0)

class Solution:
    def maxValue(self, n: int, index: int, maxSum: int) -> int:
        beg = 1
        end = maxSum
        res = -1
        while beg <= end:
            mid = (beg + end) // 2
            currsum = mid * mid
            left = index - mid + 1
            right = index + mid - 1
            if left < 0:
                x = -left
                currsum -= x * (x + 1) // 2
            else:
                currsum += left
            if right >= n:
                x = right - n + 1
                currsum -= x * (x + 1) // 2
            else:
                currsum += n - right - 1
            if currsum <= maxSum:
                res = mid
                beg = mid + 1
            else:
                end = mid - 1
        return res

class Solution:
    def maximumValue(self, strs: List[str]) -> int:
        def val(x):
            try:
                return int(x)
            except:
                return len(x)
        return max([val(s) for s in strs])

class Solution:
    def maximumTripletValue(self, nums: List[int]) -> int:
        n = len(nums)
        mx = nums[:]
        mn = nums[:]
        for i in range(n - 2, -1, -1):
            mx[i] = max(mx[i], mx[i + 1])
            mn[i] = min(mn[i], mn[i + 1])
        res = 0
        mnval = float('inf')
        mxval = float('-inf')
        for j in range(n - 1):
            for l in [mnval, mxval]:
                for r in [mn[j + 1], mx[j + 1]]:
                    if j > 0:
                        res = max(res, (l - nums[j]) * r)
            mnval = min(mnval, nums[j])
            mxval = max(mxval, nums[j])
        return res

class Solution:
    def maximumTripletValue(self, nums: List[int]) -> int:
