class Solution:
    def maxValueOfCoins(self, piles: List[List[int]], k: int) -> int:
        n = len(piles)
        dp = [[0] * (k + 1) for _ in range(n + 1)]
        for i in range(n - 1, -1, -1):
            for rem in range(1, k + 1):
                dp[i][rem] = dp[i + 1][rem]
                val = 0
                for j in range(min(rem, len(piles[i]))):
                    val += piles[i][j]
                    dp[i][rem] = max(dp[i][rem], val + dp[i + 1][rem - j - 1])
        return dp[0][k]

from sortedcontainers import SortedList

class Solution:
    def maximumValueSum(self, board: List[List[int]]) -> int:
        m = len(board)
        n = len(board[0])
        dp = [[float('-inf')] * (n + 1) for _ in range(n + 1)]
        ndp = [[float('-inf')] * (n + 1) for _ in range(n + 1)]
        maxes = [[float('-inf')] * n for _ in range(n)]
        for i in range(m - 1, -1, -1):
            vals = SortedList()
            for j in range(n):
                vals.add(board[i][j])
            for j in range(n):
                vals.remove(board[i][j])
                for k in range(j + 1, n):
                    vals.remove(board[i][k])
                    maxes[j][k] = vals[-1]
                    vals.add(board[i][k])
                vals.add(board[i][j])
            for f in range(n + 1):
                mxl = [float('-inf')] * (n + 1)
                mxr = [float('-inf')] * (n + 1)
                for j in range(n):
                    mxl[j + 1] = max(mxl[j], board[i][j] + dp[f][j])
                    mxr[j + 1] = max(mxr[j], board[i][n - j - 1] + dp[f][n - j - 1])
                for s in range(n + 1):
                    ndp[f][s] = dp[f][s]
                    if f != n and s != n and f != s:
                        ndp[f][s] = max(ndp[f][s], maxes[min(f, s)][max(f, s)])
                    if f != n and s == n:
                        ndp[f][s] = max(ndp[f][s], mxl[f], mxr[n - f - 1])
            for s in range(n + 1):
                mval = float('-inf')
                for j in range(n):
                    mval = max(mval, board[i][j] + dp[j][s])
                for f in range(n + 1):
                    if f == n and s == n:
                        ndp[f][s] = max(ndp[f][s], mval)
            dp, ndp = ndp, dp
        return dp[n][n]

class Solution:
    def inorder(self, root, l, w):
        if root:
            self.inorder(root.left, l + 1, 2 * w)
            if l in self.levels:
                self.levels[l] = (min(self.levels[l][0], w), max(self.levels[l][1], w))
                self.mwidth = max(self.mwidth, self.levels[l][1] - self.levels[l][0] + 1)
            else:
                self.levels[l] = (w, w)
                self.mwidth = max(self.mwidth, 1)
            self.inorder(root.right, l + 1, 2 * w + 1)

    def widthOfBinaryTree(self, root: Optional[TreeNode]) -> int:
        self.levels = {}
        self.mwidth = 0
        self.inorder(root, 0, 0)
        return self.mwidth

class Solution:
    def maximumXOR(self, nums: List[int]) -> int:
        res = 0
        for el in nums:
            res |= el
        return res

class Solution:
    def getMaximumXor(self, nums: List[int], maximumBit: int) -> List[int]:
        res = []
        pw = [1] * 21
        for i in range(1, 21):
            pw[i] = 2 * pw[i - 1]
        x = 0
        for el in nums:
            x ^= el
            curr = 0
            for b in range(maximumBit - 1, -1, -1):
                if not x & pw[b]:
                    curr |= pw[b]
            res.append(curr)
        res.reverse()
        return res

class Trie:
    def __init__(self):
        self.child = {}

    def insert(self, number):
        cur = self
        for i in range(45, -1, -1):
            bit = (number >> i) & 1
            if bit not in cur.child:
                cur.child[bit] = Trie()
            cur = cur.child[bit]

    def findMax(self, number):
        cur, ans = self, 0
        for i in range(45, -1, -1):
            bit = (number >> i) & 1
            if (1-bit) in cur.child:
                cur = cur.child[1 - bit]
                ans |= (1 << i)
            elif bit in cur.child:
                cur = cur.child[bit]
            else:
                break
        return ans

class Solution:
    def maxXor(self, n: int, edges: List[List[int]], values: List[int]) -> int:
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        s = [0] * n
        ctr = [0] * n
        pos = [0] * n
        timer = 0
        def dfs(i, p):
            nonlocal timer
            pos[i] = timer
            timer += 1
            s[i] = values[i]
            ctr[i] = 1
            for j in graph[i]:
                if j != p:
                    dfs(j, i)
                    s[i] += s[j]
                    ctr[i] += ctr[j]
        dfs(0, -1)
        a = sorted([[pos[i], pos[i] + ctr[i] - 1, s[i]] for i in range(n)])
        b = sorted([[pos[i], pos[i] + ctr[i] - 1, s[i]] for i in range(n)], key = lambda p: p[1])
        res = 0
        trie = Trie()
        i = 0
        for x, y, v in a:
            while i < len(b) and b[i][1] < x:
                trie.insert(b[i][2])
                i += 1
            res = max(res, trie.findMax(v))
        trie = Trie()
        i = len(a) - 1
        for x, y, v in b[::-1]:
            while i >= 0 and a[i][0] > y:
                trie.insert(a[i][2])
                i -= 1
            res = max(res, trie.findMax(v))
        return res

class Solution:
    def findMaximumXOR(self, nums: List[int]) -> int:
        n = len(nums)
        maxx = 0
        mask = 0
        se = set()
        for i in range(30, -1, -1):
            mask |= (1 << i)
            newMaxx = maxx | (1 << i)
            for i in range(n):
                se.add(nums[i] & mask)
            for prefix in se:
                if (newMaxx ^ prefix) in se:
                    maxx = newMaxx
                    break
            se.clear()
        return maxx

class Solution:
    def maximumXorProduct(self, a: int, b: int, n: int) -> int:
        M = 10 ** 9 + 7
        aa = a
        bb = b
        for bit in range(n):
            aa &= ~(1 << bit)
            bb &= ~(1 << bit)
        v = a ^ b
        for bit in range(n - 1, -1, -1):
            aa += 1 << bit
            bb += 1 << bit
            if v & (1 << bit):
                if aa <= bb:
                    bb -= 1 << bit
                else:
                    aa -= 1 << bit
        return (aa * bb) % M

class Solution:
    def maximumSubarrayXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        msb = [-1] * (n + 1)
        for i in range(1, n + 1):
            msb[i] = 1 + msb[i // 2]
        msb[0] = 0
        dp = [[0] * n for _ in range(n)]
        for l in range(n):
            for i in range(n - l - 1, -1, -1):
                if l == 0:
                    dp[i][i + l] = nums[i]
                else:
                    w = l & ~(1 << msb[l])
                    dp[i][i + l] = dp[i][i + w] ^ dp[i + l - w][i + l]
        for l in range(1, n):
            for i in range(n - l - 1, -1, -1):
                dp[i][i + l] = max(dp[i][i +  l], dp[i + 1][i + l], dp[i][i + l - 1])
        return [dp[l][r] for l, r in queries]

class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        m = len(nums1)
        n = len(nums2)
        a = None
        b = None
        va = None
        vb = None
        if (m + n) & 1:
            a = b = (m + n - 1) // 2
        else:
            b = (m + n) // 2
            a = b - 1
        i = 0
        j = 0
        while va == None or vb == None:
            if i < m and (j >= n or nums1[i] <= nums2[j]):
                if i + j == a:
                    va = nums1[i]
                if i + j == b:
                    vb = nums1[i]
                i += 1
            if j < n and (i >= m or nums2[j] < nums1[i]):
                if i + j == a:
                    va = nums2[j]
                if i + j == b:
                    vb = nums2[j]
                j += 1
        return (va + vb) / 2

class Solution:
    def minMeetingRooms(self, intervals: List[List[int]]) -> int:
        v = []
        for a, b in intervals:
            v.append((a, 1))
            v.append((b, -1))
        v.sort()
        res = 0
        p = 0
        for x, d in v:
            p += d
            res = max(res, p)
        return res

import heapq

class Solution:
    def mostBooked(self, n: int, meetings: List[List[int]]) -> int:
        rooms = list(range(n))
        waiting = []
        ctr = [0] * n
        meetings.sort()
        for a, b in meetings:
            while len(waiting) > 0 and waiting[0][0] <= a:
                t, room = heapq.heappop(waiting)
                heapq.heappush(rooms, room)
            slot = a
            if len(rooms) == 0:
                slot, room = heapq.heappop(waiting)
            else:
                room = heapq.heappop(rooms)
            ctr[room] += 1
            heapq.heappush(waiting, (slot + b - a, room))
        return ctr.index(max(ctr))

class Solution:
    def getNode(self, head, k):
        while k:
            if not head.next and k < 0:
                break
            head = head.next
            k -= 1
        return head

    def mergeInBetween(self, list1, a, b, list2):
        curr = self.getNode(list2, -1)
        curr.next = self.getNode(list1, b + 1)
        beg = self.getNode(list1, a - 1)
        beg.next = list2
        return list1

class Solution:
    def merge(self, intervals: List[List[int]]) -> List[List[int]]:
        res = []
        intervals.sort()
        prev = float('-inf')
        for l, r in intervals:
            if l <= prev:
                res[-1][-1] = max(res[-1][1], r)
            else:
                res.append([l, r])
            prev = res[-1][1]
        return res

import heapq

class Solution:
    def merge(self, l1, l2):
        if not l1 or not l2:
            return l1 or l2
        if l1.val < l2.val:
            l1.next = self.merge(l1.next, l2)
            return l1
        else:
            l2.next = self.merge(l1, l2.next)
            return l2

    def mergeKLists(self, lists):
        if len(lists) == 0:
            return None
        l = lambda x: 0 if not x else 1 + l(x.next)
        heap = []
        for i, el in enumerate(lists):
            heapq.heappush(heap, (l(el), i))
        while len(heap) > 1:
            la, a = heapq.heappop(heap)
            lb, b = heapq.heappop(heap)
            lists.append(self.merge(lists[a], lists[b]))
            heapq.heappush(heap, (la + lb, len(lists) - 1))
        return lists[heap[0][1]]

class Solution:
    def mergeNodes(self, head: Optional[ListNode]) -> Optional[ListNode]:
        if not head:
            return head
        head = head.next
        curr = head
        total = 0
        while curr:
            total += curr.val
            if curr.val == 0:
                head = ListNode(val = total)
                head.next = self.mergeNodes(curr)
                return head
            curr = curr.next

