# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def mergeTrees(self, root1: Optional[TreeNode], root2: Optional[TreeNode]) -> Optional[TreeNode]:
        if not root1 and not root2:
            return None
        mroot = TreeNode()
        nodes = [(mroot, root1, root2)]
        while len(nodes) > 0:
            mcurr, curr1, curr2 = nodes.pop()
            if mcurr:
                mcurr.val = (curr1.val if curr1 else 0) + (curr2.val if curr2 else 0)
                if (curr1 and curr1.left) or (curr2 and curr2.left):
                    mcurr.left = TreeNode()
                if (curr1 and curr1.right) or (curr2 and curr2.right):
                    mcurr.right = TreeNode()
                nodes.append((mcurr.left, curr1.left if curr1 else None, curr2.left if curr2 else None))
                nodes.append((mcurr.right, curr1.right if curr1 else None, curr2.right if curr2 else None))
        return mroot

class Solution:
    def miceAndCheese(self, reward1: List[int], reward2: List[int], k: int) -> int:
        n = len(reward1)
        vals = [(reward1[i] - reward2[i], reward1[i], reward2[i]) for i in range(n)]
        vals.sort(reverse = True)
        res = 0
        for i in range(k):
            res += vals[i][1]
        for i in range(k, n):
            res += vals[i][2]
        return res

class Solution:
    def middleNode(self, head: Optional[ListNode]) -> Optional[ListNode]:
        slow = head
        fast = head
        while fast and fast.next:
            slow = slow.next
            fast = fast.next.next
        return slow

class Solution:
    def minCostClimbingStairs(self, cost: List[int]) -> int:
        n = len(cost)
        dp = [float('inf')] * (n + 2)
        dp[n] = 0
        for i in range(n - 1, -1, -1):
            dp[i] = cost[i] + min(dp[i + 1], dp[i + 2])
        return min(dp[0], dp[1])

import heapq
from collections import defaultdict

class Solution:
    def union(self, parent, i, j):
        parent[i] = j

    def getParent(self, parent, i):
        if i not in parent:
            return i
        return self.getParent(parent, parent[i])

    def isCycle(self, graph, n):
        parent = {}
        for i in graph:
            for j in graph[i]:
                x = self.getParent(parent, i)
                y = self.getParent(parent, j)
                if x == y:
                    return True
                self.union(parent, x, y)
        return False

    def minCostConnectPoints(self, points):
        n = len(points)
        edges = []
        for i in range(n):
            for j in range(i + 1, n):
                a, b = points[i]
                c, d = points[j]
                cost = abs(c - a) + abs(d - b)
                heapq.heappush(edges, (cost, i, j))
        graph = defaultdict(set)
        rem = n - 1
        op = 0
        while rem > 0:
            if len(edges) > 0:
                currdist, i, j = heapq.heappop(edges)
                graph[i].add(j)
                if self.isCycle(graph, n):
                    graph[i].remove(j)
                else:
                    rem -= 1
                    op += currdist
        return op

class Solution:
    def minMax(self, nums, i, j, minm):
        if j == i + 1:
            return nums[i]
        mid = (i + j) // 2
        a = self.minMax(nums, i, mid, True)
        b = self.minMax(nums, mid, j, False)
        if minm:
            return min(a, b)
        return max(a, b)

    def minMaxGame(self, nums: List[int]) -> int:
        n = len(nums)
        return self.minMax(nums, 0, n, True)

from sortedcontainers import SortedList

class Solution:
    def minimumDeviation(self, nums: List[int]) -> int:
        s = SortedList([2 * el if el & 1 else el for el in nums])
        res = s[-1] - s[0]
        while s[-1] % 2 == 0:
            s.add(s.pop(-1) // 2)
            res = min(res, s[-1] - s[0])
        return res

from collections import defaultdict, Counter

class Solution:
    def dfs(self, graph, node, visited):
        for j in graph[node]:
            if j not in visited:
                visited.add(j)
                self.dfs(graph, j, visited)

    def hammingDist(self, actr, bctr, n):
        ctr = 0
        for x in actr:
            ctr += min(actr[x], bctr[x])
        return n - ctr

    def minimumHammingDistance(self, source: List[int], target: List[int], allowedSwaps: List[List[int]]) -> int:
        graph = defaultdict(list)
        n = len(source)
        dist = 0
        for a, b in allowedSwaps:
            graph[a].append(b)
            graph[b].append(a)
        globalvisited = set()
        for x in graph:
            if x not in globalvisited:
                currvisited = {x}
                self.dfs(graph, x, currvisited)
                nv = len(currvisited)
                sourcenums = Counter([source[p] for p in currvisited])
                targetnums = Counter([target[p] for p in currvisited])
                dist += self.hammingDist(sourcenums, targetnums, nv)
                globalvisited.update(currvisited)
        for i in range(n):
            if i not in globalvisited and source[i] != target[i]:
                dist += 1
        return dist

def manhattan_distance(p1, p2):
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

def max_manhattan_distance(points):
    candidates = set()
    for a in [-1, 1]:
        for b in [-1, 1]:
            for c in [0, 1]:
                curr = (float('inf') if c == 0 else float('-inf'), -1)
                for i in range(len(points)):
                    val = a * points[i][0] + b * points[i][1]
                    if c == 0:
                        curr = min(curr, (val, i))
                    else:
                        curr = max(curr, (val, i))
                candidates.add(curr[1])
    d = float('-inf')
    res = None
    for i in range(len(points)):
        for j in candidates:
            if manhattan_distance(points[i], points[j]) > d:
                d = manhattan_distance(points[i], points[j])
                res = (points[i], points[j])
    return res

class Solution:
    def minimumDistance(self, points: List[List[int]]) -> int:
        a, b = max_manhattan_distance(points)
        res = manhattan_distance(a, b)
        points.remove(a)
        x, y = max_manhattan_distance(points)
        res = min(res, manhattan_distance(x, y))
        points.append(a)
        points.remove(b)
        x, y = max_manhattan_distance(points)
        res = min(res, manhattan_distance(x, y))
        points.append(a)
        return res

class Solution:
    def check(self, arr, M):
        n = len(arr)
        extra = 0
        for i in range(n):
            if arr[i] > M:
                if arr[i] - M > extra:
                    return False
                else:
                    extra -= arr[i] - M
            else:
                extra += M - arr[i]
        return True

    def minimizeArrayValue(self, nums: List[int]) -> int:
        n = len(nums)
        beg = 0
        end = max(nums)
        res = end
        while beg <= end:
            mid = (beg + end) // 2
            if self.check(nums, mid):
                res = mid
                end = mid - 1
            else:
                beg = mid + 1
        return res

class Solution:
    def minPairSum(self, nums: List[int]) -> int:
        nums.sort()
        n = len(nums)
        maxSum = float('-inf')
        for i in range(n // 2):
            maxSum = max(maxSum, nums[i] + nums[n - 1 - i])
        return maxSum

from collections import *

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, a):
        if a == self.parent[a]:
            return a
        self.parent[a] = self.find(self.parent[a])
        return self.parent[a]

    def union(self, a, b):
        parent_a = self.find(a)
        parent_b = self.find(b)
        if parent_a != parent_b:
            if self.size[parent_a] < self.size[parent_b]:
                parent_a, parent_b = parent_b, parent_a
            self.parent[parent_b] = parent_a
            self.size[parent_a] += self.size[parent_b]

class Solution:
    def minScore(self, matrix: List[List[int]]) -> List[List[int]]:
        m = len(matrix)
        n = len(matrix[0])
        res = [[0] * n for _ in range(m)]
        pos = lambda i, j: n * i + j
        dsu = DSU(m * n)
        for i in range(m):
            prev = {}
            for j in range(n):
                if matrix[i][j] in prev:
                    dsu.union(pos(i, j), pos(i, prev[matrix[i][j]]))
                prev[matrix[i][j]] = j
        for j in range(n):
            prev = {}
            for i in range(m):
                if matrix[i][j] in prev:
                    dsu.union(pos(i, j), pos(prev[matrix[i][j]], j))
                prev[matrix[i][j]] = i
        groups = defaultdict(set)
        for i in range(m):
            for j in range(n):
                groups[(matrix[i][j], dsu.find(pos(i, j)))].add((i, j))
        rowmax = [(float('-inf'), 0)] * m
        colmax = [(float('-inf'), 0)] * n
        for val, g in sorted(groups):
            rank = 1
            for x, y in groups[(val, g)]:
                rank = max(rank, int(val > rowmax[x][0]) + rowmax[x][1])
                rank = max(rank, int(val > colmax[y][0]) + colmax[y][1])
            for x, y in groups[(val, g)]:
                res[x][y] = rank
                rowmax[x] = max(rowmax[x], (val, rank))
                colmax[y] = max(colmax[y], (val, rank))
        return res

class Solution:
    def getInt(self, s):
        if len(s) == 0:
            return 1
        return int(s)

    def minimizeResult(self, expression: str) -> str:
        a, b = expression.split("+")
        minVal = float('inf')
        m = len(a)
        n = len(b)
        minPos = None
        for i in range(m):
            for j in range(1, n + 1):
                currVal = self.getInt(a[:i]) * (self.getInt(a[i:]) + self.getInt(b[:j])) * self.getInt(b[j:])
                if currVal < minVal:
                    minVal = currVal
                    minPos = (i, j)
        i , j = minPos
        return "{}({}+{}){}".format(a[:i], a[i:], b[:j], b[j:])

class Solution:
    def minimizedStringLength(self, s: str) -> int:
        return len(set(s))

import bisect

class Solution:
    def minimizeTheDifference(self, mat: List[List[int]], target: int) -> int:
        m = len(mat)
        upsums = {0}
        downsums = {0}
        for i in range(m // 2):
            upsums = {x + el for el in mat[i] for x in upsums}
        for i in range(m // 2, m):
            downsums = {x + el for el in mat[i] for x in downsums}
        downsums = sorted(downsums)
        n = len(downsums)
        res = float('inf')
        for s in upsums:
            i = bisect.bisect_left(downsums, target - s)
            if i < n:
                res = min(res, abs(s + downsums[i] - target))
            if i > 0:
                res = min(res, abs(s + downsums[i - 1] - target))
        return res

class Solution:
    def minimizeMax(self, nums: List[int], p: int) -> int:
        n = len(nums)
        nums.sort()
        beg = 0
        end = nums[-1] - nums[0]
        res = end
        while beg <= end:
            mid = (beg + end) // 2
            ctr = 0
            prev = -1
            for i in range(n - 1):
                if nums[i + 1] - nums[i] <= mid and i > prev:
                    ctr += 1
                    prev = i + 1
            if ctr >= p:
                res = mid
                end = mid - 1
            else:
                beg = mid + 1
        return res

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        def check(up):
            graph = [[] for _ in range(n)]
            v = [False] * n
            for a, b, w in edges:
                if w <= up:
                    graph[b].append(a)
            stack = [0]
            v[0] = True
            while stack:
                i = stack.pop()
                for j in graph[i]:
                    if not v[j]:
                        v[j] = True
                        stack.append(j)
            return not (False in v)
        ws = set()
        for a, b, w in edges:
            ws.add(w)
        ws = sorted(ws)
        beg = 0
        end = len(ws) - 1
        while beg <= end:
            mid = (beg + end) // 2
            up = ws[mid]
            if check(up):
                end = mid - 1
            else:
                beg = mid + 1
        return ws[end + 1] if end + 1 < len(ws) else -1

class Solution:
    def minimumTotalPrice(self, n: int, edges: List[List[int]], price: List[int], trips: List[List[int]]) -> int:
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        LOG = 18
        p = [[i] * LOG for i in range(n)]
        q = deque([(0, -1, 0)])
        depth = [0] * n
        order = []
        while q:
            curr, prev, d = q.pop()
            order.append((curr, prev))
            depth[curr] = d
            for j in graph[curr]:
                if j != prev:
                    p[j][0] = curr
                    q.appendleft((j, curr, d + 1))
        for l in range(1, LOG):
            for i in range(n):
                p[i][l] = p[p[i][l - 1]][l - 1]
        res = [0] * n
        for u, v in trips:
            res[u] += 1
            res[v] += 1
            if depth[u] > depth[v]:
                u, v = v, u
            ogu, ogv = u, v
            diff = depth[v] - depth[u]
            jump = 0
            while diff:
                if diff & 1:
                    v = p[v][jump]
                jump += 1
                diff //= 2
            for jump in range(LOG - 1, -1, -1):
                if p[u][jump] != p[v][jump]:
                    u = p[u][jump]
                    v = p[v][jump]
            LCA = p[u][0] if u != v else u
            res[LCA] -= 1
            if LCA != 0:
                res[p[LCA][0]] -= 1
        order.reverse()
        for i, prev in order:
            for j in graph[i]:
                if j != prev:
                    res[i] += res[j]
        @lru_cache(maxsize = None)
        def dp(i, p, pused):
            val = float('inf')
            if not pused:
                val = res[i] * (price[i] // 2) + sum(dp(j, i, True) for j in graph[i] if j != p)
            val = min(val, res[i] * price[i] + sum(dp(j, i, False) for j in graph[i] if j != p))
            return val
        return dp(0, -1, False)

class Solution:
    def minimizeXor(self, num1: int, num2: int) -> int:
        c = num2.bit_count()
        res = 0
        for b in range(32, -1, -1):
            if c and (b + 1 == c or num1 & (1 << b)):
                res += (1 << b)
                c -= 1
        return res

import math

class Solution:
    def isPossible(self, k, n, quantities):
        if k == 0:
            return False
        curr = 0
        for q in quantities:
            curr += math.ceil(q / k)
        return curr <= n

    def minimizedMaximum(self, n: int, quantities: List[int]) -> int:
        end = 1
        while not self.isPossible(end, n, quantities):
            end *= 2
        beg = end // 2
        res = end
        while beg <= end:
            mid = (beg + end) // 2
            if self.isPossible(mid, n, quantities):
                res = mid
                end = mid - 1
            else:
                beg = mid + 1
        return res

from sortedcontainers import SortedList

class Solution:
    def minAbsoluteDifference(self, nums: List[int], x: int) -> int:
        n = len(nums)
        i = 0
        bst = SortedList()
        res = float('inf')
        for j in range(n):
            while j - i >= x:
                bst.add(nums[i])
                i += 1
            k = bst.bisect_left(nums[j])
            for l in [k - 1, k, k + 1]:
                if 0 <= l < len(bst):
                    res = min(res, abs(nums[j] - bst[l]))
        return res

class Solution:
    def inorder(self, root):
        if root:
            self.inorder(root.left)
            if self.latest != None:
                self.currMin = min(self.currMin, root.val - self.latest)
            self.latest = root.val
            self.inorder(root.right)

    def getMinimumDifference(self, root: Optional[TreeNode]) -> int:
        self.currMin = float('inf')
        self.latest = None
        self.inorder(root)
        return self.currMin

from collections import defaultdict
import bisect

class Solution:
    def minDifference(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        pos = defaultdict(list)
        for i in range(n):
            pos[nums[i]].append(i)
        vals = sorted(pos)
        res = []
        for l, r in queries:
            curr = []
            for v in vals:
                if bisect.bisect_right(pos[v], r) - bisect.bisect_left(pos[v], l) > 0:
                    curr.append(v)
            if len(curr) >= 2:
                curr = min(curr[i + 1] - curr[i] for i in range(len(curr) - 1))
            else:
                curr = -1
            res.append(curr)
        return res

class Solution:
    def minimumAbsDifference(self, arr: List[int]) -> List[List[int]]:
        n = len(arr)
        mindiff = float('inf')
        mindiffindexes = []
        arr.sort()
        for i in range(n - 1):
            currdiff = arr[i + 1] - arr[i]
            if currdiff < mindiff:
                mindiff = currdiff
                mindiffindexes = []
            if currdiff == mindiff:
                mindiffindexes.append(i)
        return [[arr[i], arr[i + 1]] for i in mindiffindexes]

import bisect

class Solution:
    def minAbsoluteSumDiff(self, nums1: List[int], nums2: List[int]) -> int:
        M = 10 ** 9 + 7
        n = len(nums1)
        order = sorted(nums1)
        res = float('inf')
        for i in range(n):
            j = bisect.bisect_left(order, nums2[i])
            for k in [j - 1, j, j + 1]:
                if 0 <= k < n:
                    res = min(res, abs(order[k] - nums2[i]) - abs(nums1[i] - nums2[i]))
        for i in range(n):
            res += abs(nums1[i] - nums2[i])
            res %= M
        return res

class Solution:
    def minAddToMakeValid(self, s: str) -> int:
        stack = []
        ctr = 0
        for c in s:
            if c == '(':
                stack.append('(')
            else:
                if len(stack) == 0 or stack[-1] != '(':
                    ctr += 1
                else:
                    stack.pop()
        ctr += len(stack)
        return ctr

class Solution:
    def getsum(self, n):
        res = 0
        while n:
            res += n % 10
            n //= 10
        return res

    def makeIntegerBeautiful(self, n: int, target: int) -> int:
        prev = n
        k = 10
        while self.getsum(n) > target:
            n = n + (k - n % k)
            k *= 10
        return n - prev

import math

class Solution:
    def LCS(self, text1, text2):
        n,m=len(text1),len(text2)
        dp=[[0]*(m+1) for _ in range(n+1)]
        for i in range(n):
            for j in range(m):
                if text1[i]==text2[j]:
                    dp[i+1][j+1]=dp[i][j]+1
                else:
                    dp[i+1][j+1]=max(dp[i][j+1],dp[i+1][j])
        return dp[-1][-1]

    def addMinimum(self, word: str) -> int:
        n = len(word)
        res = float('inf')
        l = math.ceil(n / 3)
        ctr = 3 + max(word.count("a"), word.count("b"), word.count("c"))
        for i in range(ctr):
            x = self.LCS("abc" * l, word)
            if x >= n:
                res = min(res, 3 * l - x)
            l += 1
        return res

from sortedcontainers import SortedList

class Solution:
    def nextPermutation(self, nums: List[int]) -> None:
        n = len(nums)
        i = n - 1
        while i > 0 and nums[i - 1] >= nums[i]:
            i -= 1
        if i > 0:
            fn = lambda k: (float('inf') if nums[k] <= nums[i - 1] else nums[k], -k)
            closest = min(range(i, n), key = fn)
            nums[i - 1], nums[closest] = nums[closest], nums[i - 1]
        for p in range((n - i) // 2):
            nums[i + p], nums[n - p - 1] = nums[n - p - 1], nums[i + p]

    def getMinSwaps(self, num: str, k: int) -> int:
        n = len(num)
        vals = [int(c) for c in num]
        old = vals[:]
        for _ in range(k):
            self.nextPermutation(vals)
        res = 0
        pos = [[] for _ in range(10)]
        for i in range(n):
            pos[vals[i]].append(i)
        ctr = [0] * 10
        p = []
        bst = SortedList()
        for i in range(n):
            res += len(bst) - bst.bisect_left(pos[old[i]][ctr[old[i]]] + 1)
            bst.add(pos[old[i]][ctr[old[i]]])
            ctr[old[i]] += 1
        return res

class Solution:
    def garbageCollection(self, garbage: List[str], travel: List[int]) -> int:
        n = len(garbage)
        res = 0
        for c in 'MGP':
            j = n - 1
            while j >= 0 and c not in garbage[j]:
                j -= 1
            for i in range(j + 1):
                res += garbage[i].count(c)
                if i < j:
                    res += travel[i]
        return res

class Solution:
    def fillCups(self, amount: List[int]) -> int:
        t = 0
        amount.sort()
        while amount != [0, 0, 0]:
            if amount[2] > 0 and amount[1] > 0:
                amount[1] -= 1
                amount[2] -= 1
            elif amount[2] > 0:
                amount[2] -= 1
            amount.sort()
            t += 1
        return t

from collections import defaultdict

class Solution:
    def dist(self, a, b):
        return (b[0] - a[0]) * (b[0] - a[0]) + (b[1] - a[1]) * (b[1] - a[1])

    def area(self, a, b, c, d):
        if self.dist(a, c) != self.dist(b, d):
            return float('inf')
        if a[0] + c[0] != b[0] + d[0] or a[1] + c[1] != b[1] + d[1]:
            return float('inf')
        return self.dist(a, b) * self.dist(a, d)

    def gcd(self, a, b):
        while b:
            a, b = b, a % b
        return a

    def minAreaFreeRect(self, points: List[List[int]]) -> float:
        n = len(points)
        pairs = defaultdict(lambda: defaultdict(list))
        for i in range(n):
            for j in range(i + 1, n):
                a, b = points[i]
                c, d = points[j]
                x, y = c - a, d - b
                if y < 0:
                    x, y = -x, -y
                mul = self.gcd(abs(x), abs(y))
                x //= mul
                y //= mul
                if x >= 0 and y >= 0:
                    pairs[(x, y)][self.dist((a, b), (c, d))].append((i, j))
        res = float('inf')
        for slope in pairs:
            for d in pairs[slope]:
                m = len(pairs[slope][d])
                for i in range(m):
                    for j in range(i + 1, m):
                        p, q = pairs[slope][d][i]
                        r, s = pairs[slope][d][j]
                        p, q, s, r = sorted([p, q, r, s], key = lambda x: points[x])
                        res = min(res, self.area(points[p], points[q], points[r], points[s]))
        if res == float('inf'):
            return 0
        return res ** 0.5

from collections import defaultdict

class Solution:
    def minAreaRect(self, points: List[List[int]]) -> int:
        n = len(points)
        res = float('inf')
        pmap = defaultdict(set)
        for x, y in points:
            pmap[x].add(y)
        xlist = sorted(pmap.keys())
        m = len(xlist)
        for i in range(m):
            for j in range(i + 1, m):
                l = xlist[j] - xlist[i]
                ypoints = sorted(set.intersection(pmap[xlist[i]], pmap[xlist[j]]))
                p = len(ypoints)
                for k in range(p - 1):
                    res = min(res, l * (ypoints[k + 1] - ypoints[k]))
        if res == float('inf'):
            return 0
        return res

class Solution:
    def minEnd(self, n: int, x: int) -> int:
        res = x
        inc = n - 1
        p = 0
        for b in range(62):
            if not x & (1 << b):
                if inc & (1 << p):
                    res += 1 << b
                p += 1
        return res

class Solution:
    def minLengthAfterRemovals(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 1
        beg = 1
        end = n // 2
        while beg <= end:
            mid = (beg + end) // 2
            p = True
            for i in range(mid):
                if nums[i] >= nums[-mid+i]:
                    p = False
                    break
            if p:
                beg = mid + 1
            else:
                end = mid - 1
        return n - 2 * (beg - 1)

class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        n = len(nums)
        dp = [[[float('inf')] * (op2 + 1) for _ in range(op1 + 1)] for _ in range(n + 1)]
        for x in range(op1 + 1):
            for y in range(op2 + 1):
                dp[n][x][y] = 0
        for i in range(n - 1, -1, -1):
            for x in range(op1 + 1):
                for y in range(op2 + 1):
                    dp[i][x][y] = nums[i] + dp[i + 1][x][y]
                    if x > 0:
                        dp[i][x][y] = min(dp[i][x][y], (nums[i] + 1) // 2 + dp[i + 1][x - 1][y])
                    if y > 0 and nums[i] >= k:
                        dp[i][x][y] = min(dp[i][x][y], (nums[i] - k) + dp[i + 1][x][y - 1])
                    if x > 0 and y > 0:
                        v = float('inf')
                        if (nums[i] + 1) // 2 >= k:
                            v = min(v, (nums[i] + 1) // 2 - k)
                        elif nums[i] >= k:
                            v = min(v, (nums[i] - k + 1) // 2)
                        dp[i][x][y] = min(dp[i][x][y], v + dp[i + 1][x - 1][y - 1])
        return dp[0][op1][op2]

class Solution:
    def minimumDeleteSum(self, s1: str, s2: str) -> int:
        n, m = len(s1), len(s2)
        total = sum([ord(c) for c in s1]) + sum([ord(c) for c in s2])
        dp=[[0] * (m + 1) for _ in range(n + 1)]
        for i in range(n):
            for j in range(m):
                if s1[i] == s2[j]:
                    dp[i + 1][j + 1] = dp[i][j] + ord(s1[i])
                else:
                    dp[i + 1][j + 1] = max(dp[i][j + 1], dp[i + 1][j])
        return total - 2 * dp[-1][-1]

class Solution:
    def getDiff(self, prefix, i, n):
        l = (prefix[i + 1] - prefix[0])
        r = prefix[-1] - l
        l = l // (i + 1)
        r = r // (n - i - 1) if i < n - 1 else 0
        return abs(l - r)

    def minimumAverageDifference(self, nums: List[int]) -> int:
        n = len(nums)
        prefix = [0]
        for i in range(n):
            prefix.append(prefix[-1] + nums[i])
        return min(range(n), key = lambda i: self.getDiff(prefix, i, n))

class Solution:
    def minimumAverage(self, nums: List[int]) -> float:
        res = []
        nums.sort()
        i = 0
        j = len(nums) - 1
        while i < j:
            res.append((nums[i] + nums[j]) / 2)
            i += 1
            j -= 1
        return min(res)

class Solution:
    def minBitFlips(self, start: int, goal: int) -> int:
        return "{:b}".format(start ^ goal).count("1")

class Solution:
    def minOperations(self, s: str) -> int:
        a = b = 0
        for i in range(len(s)):
            if int(s[i]) == i % 2:
                a += 1
            else:
                b += 1
        return min(a, b)

class Solution:
    def minimumChanges(self, s: str, k: int) -> int:
        n = len(s)
        cost = [[float('inf')] * (n + 1) for _ in range(n)]
        diff = [[0] * n for _ in range(n)]
        curr = [[float('inf') if l > 1 else 0 for l in range(n + 1)] for _ in range(n)]
        for d in range(1, n + 1):
            for i in range(n - d + 1):
                for j in range(n - d + 1):
                    diff[i][j] += int(s[i + d - 1] != s[j + d - 1])
            l = 2 * d
            while l <= n:
                for i in range(n - l + d - 1, -1, -1):
                    curr[i][d] = 0
                    curr[i][l] = curr[i + d][l - 2 * d] + diff[i][i + l - d]
                    cost[i][l] = min(cost[i][l], curr[i][l])
                l += d
        dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 0
        for l in range(1, n + 1):
            for rem in range(1, k + 1):
                for m in range(2, l + 1):
                    dp[l][rem] = min(dp[l][rem], cost[l - m][m] + dp[l - m][rem - 1])
        return dp[n][k]

class Solution:
    def getCommon(self, nums1: List[int], nums2: List[int]) -> int:
        common = set(nums1) & set(nums2)
        if len(common) == 0:
            return -1
        return min(common)

class Solution:
    def minimumCardPickup(self, cards: List[int]) -> int:
        n = len(cards)
        pos = {}
        minDiff = float('inf')
        for i in range(n):
            if cards[i] in pos:
                minDiff = min(minDiff, i - pos[cards[i]] + 1)
            pos[cards[i]] = i
        if minDiff == float('inf'):
            return -1
        return minDiff

class Solution:
    def minimumCost(self, m: int, n: int, horizontalCut: List[int], verticalCut: List[int]) -> int:
        dp = [[[[-1] * (n + 1) for _ in range(m + 1)] for _ in range(n + 1)] for _ in range(m + 1)]
        def cost(i, j, w, h):
            if w == 1 and h == 1:
                return 0
            if dp[i][j][w][h] != -1:
                return dp[i][j][w][h]
            res = float('inf')
            for x in range(1, w):
                res = min(res, cost(i, j, x, h) + cost(i + x, j, w - x, h) + horizontalCut[i + x - 1])
            for y in range(1, h):
                res = min(res, cost(i, j, w, y) + cost(i, j + y, w, h - y) + verticalCut[j + y - 1])
            dp[i][j][w][h] = res
            return res
        return cost(0, 0, m, n)

class Solution:
    def minimumCost(self, m: int, n: int, horizontalCut: List[int], verticalCut: List[int]) -> int:
        vals = [(el, 0) for el in horizontalCut] + [(el, 1) for el in verticalCut]
        vals.sort()
        res = 0
        r = m
        c = n
        for x, t in vals:
            if t == 0:
                res += c * x
                r -= 1
            else:
                res += r * x
                c -= 1
        return res

class Solution:
    def mincostTickets(self, days: List[int], costs: List[int]) -> int:
        n = len(days)
        dp = [float('inf')] * (n + 1)
        dp[n] = 0
        x = y = z = n - 1
        for i in range(n - 1, -1, -1):
            while x >= i and days[x] - days[i] >= 1:
                x -= 1
            while y >= i and days[y] - days[i] >= 7:
                y -= 1
            while z >= i and days[z] - days[i] >= 30:
                z -= 1
            dp[i] = min(costs[0] + dp[x + 1], costs[1] + dp[y + 1], costs[2] + dp[z + 1])
        return dp[0]

class Solution:
    def minCost(self, startPos: List[int], homePos: List[int], rowCosts: List[int], colCosts: List[int]) -> int:
        ax, ay = startPos
        bx, by = homePos
        res = 0
        for i in range(min(ay, by), max(ay + 1, by + 1)):
            res += colCosts[i]
        for i in range(min(ax, bx), max(ax + 1, bx + 1)):
            res += rowCosts[i]
        res -=  rowCosts[ax] + colCosts[ay]
        return res

import heapq

class Solution:
    def minimumCost(self, start: List[int], target: List[int], specialRoads: List[List[int]]) -> int:
        specialRoads.append(target + target + [0])
        dist = {(start[0], start[1]): 0}
        heap = [(0, start[0], start[1])]
        while len(heap) > 0:
            currdist, x, y = heapq.heappop(heap)
            for a, b, c, d, cost in specialRoads:
                if dist.get((c, d), float('inf')) > currdist + abs(x - a) + abs(y - b) + cost:
                    dist[(c, d)] = currdist + abs(x - a) + abs(y - b) + cost
                    heapq.heappush(heap, (dist[(c, d)], c, d))
        return dist[(target[0], target[1])]

class Solution:
    def minimumCost(self, cost: List[int]) -> int:
        n = len(cost)
        cost.sort()
        curr = 0
        if len(cost) == 1:
            return cost[0]
        while len(cost) > 1:
            b = cost.pop()
            a = cost.pop()
            curr += a + b
            if len(cost) > 0:
                cost.pop()
        curr += sum(cost)
        return curr

class Solution:
    def cost(self, cost, i, j, m, n, took, used):
        if i >= m:
            if used + 1 != 1 << n:
                return float('inf')
            return 0
        key = (i, j, took, used)
        if key in self.cache:
            return self.cache[key]
        res = float('inf')
        newi = i
        newj = j + 1
        if newj >= n:
            newi += 1
            newj = 0
        res = min(res, cost[i][j] + self.cost(cost, newi, newj, m, n, bool(newj != 0), used | (1 << j)))
        if j != n - 1 or took:
            res = min(res, self.cost(cost, newi, newj, m, n, bool(took and newj != 0), used))
        self.cache[key] = res
        return res

    def connectTwoGroups(self, cost: List[List[int]]) -> int:
        m = len(cost)
        n = len(cost[0])
        self.cache = {}
        return self.cost(cost, 0, 0, m, n, False, 0)

class Solution:
    def minimumCost(self, source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
        dp = [[float('inf')] * 26 for _ in range(26)]
        for i in range(26):
            dp[i][i] = 0
        pos = lambda c: ord(c) - ord('a')
        for i in range(len(original)):
            if cost[i] < dp[pos(original[i])][pos(changed[i])]:
                dp[pos(original[i])][pos(changed[i])]  = cost[i]
        for j in range(26):
            for i in range(26):
                for k in range(26):
                    dp[i][k] = min(dp[i][k], dp[i][j] + dp[j][k])
        res = sum(dp[pos(a)][pos(b)] for a, b in zip(source, target))
        if res == float('inf'):
            res = -1
        return res

class Solution:
    def minCost(self, n: int, cuts: List[int]) -> int:
        cuts = [0] + sorted(cuts) + [n]
        k = len(cuts)
        dp = [[float('inf')] * k for _ in range(k)]
        for l in range(1, k + 1):
            for beg in range(k - l):
                end = beg + l
                if l == 1:
                    dp[beg][end] = 0
                    continue
                for i in range(beg + 1, end):
                    currcost = cuts[end] - cuts[beg]
                    currcost += dp[beg][i] + dp[i][end]
                    dp[beg][end] = min(dp[beg][end], currcost)
        return dp[0][k - 1]

class Solution:
    def cost(self, nums, cost, p):
        n = len(nums)
        res = 0
        for i in range(n):
            res += abs(nums[i] - p) * cost[i]
        return res

    def minCost(self, nums: List[int], cost: List[int]) -> int:
        beg = 1
        end = max(nums)
        res = float('inf')
        while beg < end:
            mid = (beg + end) // 2
            mid1val = self.cost(nums, cost, mid)
            mid2val = self.cost(nums, cost, mid + 1)
            if mid1val <= mid2val:
                res = min(res, mid1val)
                end = mid - 1
            else:
                res = min(res, mid2val)
                beg = mid + 1
        return res

pals = set()

def check(val):
    if val > 10 ** 9:
        return False
    v = val
    rev = 0
    while val:
        rev = 10 * rev + val % 10
        val //= 10
    return v == rev

for a in range(10):
    for b in range(10):
        for c in range(10):
            for d in range(10):
                for e in range(10):
                    s = f"{a}{b}{c}{d}{e}"
                    for i in range(1, 6):
                        curr = int(s[:i] + s[:i][::-1])
                        if check(curr):
                            pals.add(curr)
                        curr = int(s[:i] + s[:i][:-1][::-1])
                        if check(curr):
                            pals.add(curr)

pals = sorted(pals)

class Solution:
    def minimumCost(self, nums: List[int]) -> int:
        n = len(nums)
        M = max(nums)
        nums.sort()
        l = 0
        r = sum(nums)
        res = r
        i = 0
        for p in pals:
            while i < n and nums[i] <= p:
                l += nums[i]
                r -= nums[i]
                i += 1
            res = min(res, p * i - l + r - (n - i) * p)
            if p > M:
                break
        return res

class Solution:
    def minCost(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        ways = [(0, -1, 2), (0, 1, 1), (-1, 0, 4), (1, 0, 3)]
        q = deque([(0, 0)])
        d = [[float('inf')] * n for _ in range(m)]
        d[0][0] = 0
        while q:
            i, j = q.pop()
            if (i, j) == (m - 1, n - 1):
                return d[i][j]
            for dx, dy, need in ways:
                x, y = i + dx, j + dy
                if not 0 <= x < m or not 0 <= y < n:
                    continue
                cost = int(grid[i][j] != need)
                if d[x][y] > d[i][j] + cost:
                    d[x][y] = d[i][j] + cost
                    (q.appendleft if cost == 1 else q.append)((x, y))

class Solution:
    def minCostToMoveChips(self, position: List[int]) -> int:
        minCost = float('inf')
        for currpos in position:
            currCost = 0
            for pos in position:
                currCost += abs(pos - currpos) % 2
            minCost = min(minCost, currCost)
        return minCost

class Solution:
    def minCost(self, maxTime: int, edges: List[List[int]], passingFees: List[int]) -> int:
        n = len(passingFees)
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))
        dist = defaultdict(lambda: float('inf'))
        dist[(0, maxTime)] = passingFees[0]
        heap = [(passingFees[0], 0, maxTime)]
        while heap:
            cost, i, rem = heapq.heappop(heap)
            if i == n - 1:
                return cost
            for j, w in graph[i]:
                if w <= rem:
                    if dist[(j, rem - w)] > cost + passingFees[j]:
                        dist[(j, rem - w)] = cost + passingFees[j]
                        heapq.heappush(heap, (cost + passingFees[j], j, rem - w))
        return -1

class Solution:
    def minCosts(self, cost: List[int]) -> List[int]:
        n = len(cost)
        res = [float('inf')] * n

        for i in range(n):
            res[i] = min(res[i], cost[i])
            if i > 0:
                res[i] = min(res[i], res[i - 1])

        return res

