class Solution:
    def minCostSetTime(self, startAt: int, moveCost: int, pushCost: int, targetSeconds: int) -> int:
        res = float('inf')
        for pos in v[targetSeconds]:
            curr = 0
            prev = startAt
            for btn in pos:
                if btn != prev:
                    curr += moveCost
                curr += pushCost
                prev = btn
            res = min(res, curr)
        return res

class LazySegmentTree:
    def __init__(self, arr):
        self.arr = arr
        self.tree = [0] * (4 * len(arr))
        self.lazy = [0] * (4 * len(arr))
        self.build(1, 0, len(arr) - 1)

    def build(self, node, start, end):
        if start == end:
            self.tree[node] = self.arr[start]
        else:
            mid = (start + end) // 2
            self.build(2 * node, start, mid)
            self.build(2 * node + 1, mid + 1, end)
            self.tree[node] = min(self.tree[2 * node], self.tree[2 * node + 1])

    def update_range(self, node, start, end, left, right, value):
        if self.lazy[node] != 0:
            self.tree[node] += self.lazy[node]
            if start != end:
                self.lazy[2 * node] += self.lazy[node]
                self.lazy[2 * node + 1] += self.lazy[node]
            self.lazy[node] = 0
        if start > end or start > right or end < left:
            return
        if start >= left and end <= right:
            self.tree[node] += value
            if start != end:
                self.lazy[2 * node] += value
                self.lazy[2 * node + 1] += value
            return
        mid = (start + end) // 2
        self.update_range(2 * node, start, mid, left, right, value)
        self.update_range(2 * node + 1, mid + 1, end, left, right, value)
        self.tree[node] = min(self.tree[2 * node], self.tree[2 * node + 1])

    def query_range(self, node, start, end, left, right):
        if start > end or start > right or end < left:
            return float('inf')
        if self.lazy[node] != 0:
            self.tree[node] += self.lazy[node]
            if start != end:
                self.lazy[2 * node] += self.lazy[node]
                self.lazy[2 * node + 1] += self.lazy[node]
            self.lazy[node] = 0
        if start >= left and end <= right:
            return self.tree[node]
        mid = (start + end) // 2
        left_min = self.query_range(2 * node, start, mid, left, right)
        right_min = self.query_range(2 * node + 1, mid + 1, end, left, right)
        return min(left_min, right_min)

class Solution:
    def minCost(self, nums: List[int], k: int) -> int:
        n = len(nums)
        last = {}
        secondlast = {}
        ctr = LazySegmentTree([0] * n + [n])
        for i in range(n - 1, -1, -1):
            ctr.update_range(1, 0, n, i + 1, last.get(nums[i], n + 1) - 1, -1)
            ctr.update_range(1, 0, n, last.get(nums[i], n + 1), secondlast.get(nums[i], n + 1) - 1, 1)
            secondlast[nums[i]] = last.get(nums[i], n + 1)
            last[nums[i]] = i + 1
            curr = k - i + ctr.query_range(1, 0, n, i + 1, n)
            ctr.update_range(1, 0, n, i, i, i + curr)
        return ctr.query_range(1, 0, n, 0, 0)

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, a):
        if a == self.parent[a]:
            return a
        self.parent[a] = self.find(self.parent[a])
        return self.parent[a]

    def union(self, a, b):
        parent_a = self.find(a)
        parent_b = self.find(b)
        if parent_a != parent_b:
            if self.size[parent_a] < self.size[parent_b]:
                parent_a, parent_b = parent_b, parent_a
            self.parent[parent_b] = parent_a
            self.size[parent_a] += self.size[parent_b]

class Solution:
    def minimumCost(self, n: int, edges: List[List[int]], query: List[List[int]]) -> List[int]:
        dsu = DSU(n)
        for u, v, w in edges:
            dsu.union(u, v)
        ands = [-1] * n
        for u, v, w in edges:
            if ands[dsu.find(u)] == -1:
                ands[dsu.find(u)] = w
            else:
                ands[dsu.find(u)] &= w
        res = []
        for u, v in query:
            if u == v:
                res.append(0)
            elif dsu.find(u) == dsu.find(v):
                res.append(ands[dsu.find(u)])
            else:
                res.append(-1)
        return res

class Solution:
    def numberOfCuts(self, n: int) -> int:
        if n == 1:
            return 0
        if n % 2 == 0:
            return n // 2
        return n

class Solution:
    def minTrioDegree(self, n: int, edges: List[List[int]]) -> int:
        nb = [set() for _ in range(n)]
        B = 30
        d = [0] * n
        for u, v in edges:
            u -= 1
            v -= 1
            d[u] += 1
            d[v] += 1
            nb[u].add(v)
            nb[v].add(u)
        bigs = {i for i in range(n) if d[i] >= B}
        bigpairs = {}
        for i in bigs:
            for j in bigs:
                curr = float('inf')
                x = nb[i]
                y = nb[j]
                if len(x) > len(y):
                    x, y = y, x
                for k in x:
                    if k in y:
                        curr = min(curr, d[k])
                bigpairs[(i, j)] = min(bigpairs.get((i, j), float('inf')), curr)
        res = float('inf')
        for i in sorted(range(n), key = lambda x: d[x]):
            for j in nb[i]:
                if d[i] >= B and d[j] >= B:
                    res = min(res, d[i] + d[j] + bigpairs[(i, j)] - 6)
                    continue
                if d[i] + d[j] - 6 >= res:
                    continue
                x = nb[i]
                y = nb[j]
                if len(x) > len(y):
                    x, y = y, x
                for k in x:
                    if k in y:
                        res = min(res, d[i] + d[j] + d[k] - 6)
        if res == float('inf'):
            return -1
        return res

class Solution:
    def minDel(self, nums, i = 0, switch = False, dels = 0):
        n = len(nums)
        if i >= n:
            if (n - dels) % 2 == 0:
                return 0
            return 1
        if switch:
            if i < n - 1 and i % 2 == 1 and nums[i] == nums[i + 1]:
                return 1 + self.minDel(nums, i = i + 1, switch = False, dels = dels + 1)
            return self.minDel(nums, i = i + 1, switch = True, dels = dels)
        else:
            if i < n - 1 and i % 2 == 0 and nums[i] == nums[i + 1]:
                return 1 + self.minDel(nums, i = i + 1, switch = True, dels = dels + 1)
            return self.minDel(nums, i = i + 1, switch = False, dels = dels)

    def minDeletion(self, nums: List[int]) -> int:
        return self.minDel(nums, i = 0, switch = False, dels = 0)

class Solution:
    def gcd(self, a, b):
        while b:
            a, b = b, a % b
        return a

    def minOperations(self, nums: List[int], numsDivide: List[int]) -> int:
        n = len(nums)
        nums.sort()
        gcd = numsDivide[0]
        for el in numsDivide:
            gcd = self.gcd(gcd, el)
        for i in range(n):
            if gcd % nums[i] == 0:
                return i
        return -1

class Solution:
    def minDeletions(self, s: str) -> int:
        ctr = [0] * 26
        for c in s:
            ctr[ord(c) - ord('a')] += 1
        ctr = sorted([f for f in ctr if f != 0])
        n = len(ctr)
        seen = set()
        dels = 0
        for i in range(n):
            while ctr[i] in seen:
                ctr[i] -= 1
                dels += 1
            if ctr[i] > 0:
                seen.add(ctr[i])
        return dels

class Solution:
    def minimumDeletions(self, s: str) -> int:
        n = len(s)
        minDel = float('inf')
        curr = 0
        for i in range(n + 1):
            minDel = min(minDel, i - 2 * curr)
            if i < n and s[i] == 'a':
                curr += 1
        minDel += curr
        return minDel

class Solution:
    def minimumDeletions(self, word: str, k: int) -> int:
        n = len(word)
        ctr = Counter(word)
        res = float('inf')
        for minf in range(1, n + 1):
            maxf = minf + k
            curr = 0
            for c in ctr:
                if ctr[c] < minf:
                    curr += ctr[c]
                if ctr[c] > maxf:
                    curr += ctr[c] - maxf
            res = min(res, curr)
        return res

class Solution:
    def minDepth(self, root: Optional[TreeNode]) -> int:
        if root:
            a = self.minDepth(root.left)
            b = self.minDepth(root.right)
            if a == 0 or b == 0:
                return a + b + 1
            return 1 + min(a, b)
        return 0

class Solution:
    def minimumDifference(self, nums: List[int], k: int) -> int:
        nums.sort()
        n = len(nums)
        minDiff = float('inf')
        for i in range(n - k + 1):
            minDiff = min(minDiff, nums[i + k - 1] - nums[i])
        return minDiff

class Solution:
    def minDifference(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 4:
            return 0
        nums.sort()
        return min(nums[-1] - nums[3], nums[-2] - nums[2], nums[-3] - nums[1], nums[-1] - nums[0], nums[-4] - nums[0])

import heapq

class Solution:
    def minimumDifference(self, nums: List[int]) -> int:
        n = len(nums)
        pref = [float('inf')] * (n + 1)
        suff = [float('-inf')] * (n + 1)
        prefmin = []
        prefsum = 0
        for i in range(n):
            heapq.heappush(prefmin, -nums[i])
            prefsum += nums[i]
            while 3 * len(prefmin) > n:
                prefsum += heapq.heappop(prefmin)
            if 3 * len(prefmin) == n:
                pref[i + 1] = prefsum
        suffmax = []
        suffsum = 0
        for i in range(n - 1, -1, -1):
            heapq.heappush(suffmax, nums[i])
            suffsum += nums[i]
            while 3 * len(suffmax) > n:
                suffsum -= heapq.heappop(suffmax)
            if 3 * len(suffmax) == n:
                suff[n - i] = suffsum
        res = float('inf')
        for left in range(n + 1):
            res = min(res, pref[left] - suff[n - left])
        return res

class Solution:
    def minDiff(self, diff, i, n, d):
        if d < 0:
            return float('inf')
        if i >= n:
            if d == 0:
                return 0
            return float('inf')
        key = (i, d)
        if key in self.cache:
            return self.cache[key]
        res = float('inf')
        currdiff = float('-inf')
        for j in range(i, n):
            currdiff = max(currdiff, diff[j])
            res = min(res, currdiff + self.minDiff(diff, j + 1, n, d - 1))
        self.cache[key] = res
        return res

    def minDifficulty(self, jobDifficulty: List[int], d: int) -> int:
        n = len(jobDifficulty)
        if d > n:
            return -1
        self.cache = {}
        return self.minDiff(jobDifficulty, 0, n, d)

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def inorder(self, root):
        if root:
            self.inorder(root.left)
            if self.latest != None:
                if self.minDiff == None or root.val - self.latest < self.minDiff:
                    self.minDiff = root.val - self.latest
            self.latest = root.val
            self.inorder(root.right)

    def minDiffInBST(self, root: Optional[TreeNode]) -> int:
        self.minDiff = None
        self.latest = None
        self.inorder(root)
        return self.minDiff

import heapq

class Solution:
    def getMinDistance(self, nums: List[int], target: int, start: int) -> int:
        heap = []
        for i, num in enumerate(nums):
            heapq.heappush(heap, (abs(num - target), abs(i - start)))
        return heap[0][1]

MAX = 1 + 10 ** 6

v = [False] * MAX
sp = [0] * MAX

for i in range(2, MAX, 2):
    sp[i] = 2

for i in range(3, MAX, 2):
    if not v[i]:
        sp[i] = i
        j = i
        while j * i < MAX:
            if not v[j * i]:
                v[j * i] = True
                sp[j * i] = i
            j += 2

class Solution:
    def minOperations(self, nums: List[int]) -> int:
        nums.reverse()
        res = 0
        for i in range(1, len(nums)):
            while nums[i] > nums[i - 1]:
                if nums[i] == sp[nums[i]]:
                    return -1
                nums[i] = sp[nums[i]]
                res += 1
        return res

class Solution:
    def minDominoRotations(self, tops: List[int], bottoms: List[int]) -> int:
        n = len(tops)
        res = float('inf')
        for a in range(1, 7):
            cost = 0
            for i in range(n):
                if tops[i] == a:
                    continue
                if bottoms[i] == a:
                    cost += 1
                else:
                    cost = float('inf')
            res = min(res, cost)
        for a in range(1, 7):
            cost = 0
            for i in range(n):
                if bottoms[i] == a:
                    continue
                if tops[i] == a:
                    cost += 1
                else:
                    cost = float('inf')
            res = min(res, cost)
        if res == float('inf'):
            res = -1
        return res

from collections import defaultdict

class Solution:
    def minOperationsQueries(self, n: int, edges: List[List[int]], queries: List[List[int]]) -> List[int]:
        graph = defaultdict(set)
        for a, b, w in edges:
            graph[a].add((b, w))
            graph[b].add((a, w))
        LOG = 1 + len("{:0b}".format(n + 1))
        level = [0] * n
        nodectr = [Counter() for _ in range(n)]
        parent = [[_] * LOG for _ in range(n)]
        stack = [(0, -1, -1, 0, Counter())]
        while len(stack) > 0:
            curr, prev, weight, l, ctr = stack.pop()
            level[curr] = l
            nodectr[curr] = ctr
            if prev != -1:
                parent[curr][0] = prev
            for j, w in graph[curr]:
                if j != prev:
                    newctr = Counter(ctr)
                    newctr[w] += 1
                    stack.append((j, curr, w, l + 1, newctr))
        for d in range(1, LOG):
            for i in range(n):
                parent[i][d] = parent[parent[i][d - 1]][d - 1]
        def ancestor(i, k):
            ac = i
            p = 0
            while k:
                if k & 1:
                    ac = parent[ac][p]
                k //= 2
                p += 1
            return ac
        def lca(u, v):
            if level[u] < level[v]:
                u, v = v, u
            diff = level[u] - level[v]
            i = 0
            while diff:
                if diff & 1:
                    u = parent[u][i]
                diff //= 2
                i += 1
            if u == v:
                return u
            for i in range(LOG - 1, -1, -1):
                if parent[u][i] != parent[v][i]:
                    u = parent[u][i]
                    v = parent[v][i]
            return parent[u][0]
        res = []
        for x, y in queries:
            pathctr = nodectr[x] + nodectr[y]
            LCA = lca(x, y)
            for el in nodectr[LCA]:
                pathctr[el] -= 2 * nodectr[LCA][el]
            if len(pathctr) > 0:
                res.append(sum(pathctr.values()) - max(pathctr.values()))
            else:
                res.append(0)
        return res

import math

class Solution:
    def minElements(self, nums: List[int], limit: int, goal: int) -> int:
        diff = goal - sum(nums)
        return math.ceil(abs(diff) / limit)

class Solution:
    def minSum(self, nums1: List[int], nums2: List[int]) -> int:
        x = nums1.count(0)
        y = nums2.count(0)
        a = sum(nums1) + x
        b = sum(nums2) + y
        if (a > b and y == 0) or (b > a and x == 0):
            return -1
        return max(a, b)

class Solution:
    def minFallingPathSum(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        s, f = (0, -1), (0, -1)
        for i in range(m):
            for j in range(n):
                if f[1] != j:
                    grid[i][j] += f[0]
                else:
                    grid[i][j] += s[0]
            s, f = (float('inf'), 0), (float('inf'), 0)
            for j in range(n):
                f, s, x = sorted([s, f, (grid[i][j], j)])
        return f[0]

class Solution:
    def minSum(self, matrix, i, j, m, n):
        if i == m - 1:
            return matrix[i][j]
        if (i, j) in self.cache:
            return self.cache[(i, j)]
        minPath = float('inf')
        for col in [j - 1, j, j + 1]:
            if 0 <= col < n:
                minPath = min(minPath, matrix[i][j] + self.minSum(matrix, i + 1, col, m, n))
        self.cache[(i, j)] = minPath
        return minPath

    def minFallingPathSum(self, matrix: List[List[int]]) -> int:
        m = len(matrix)
        n = len(matrix[0])
        self.cache = {}
        minPath = float('inf')
        for i in range(n):
            minPath = min(minPath, self.minSum(matrix, 0, i, m, n))
        return minPath

class Solution:
    def minimumFlips(self, root: Optional[TreeNode], result: bool) -> int:
        op = lambda x, y, o: [x or y, x and y, x ^ y][o - 2]
        @lru_cache(maxsize = None)
        def dp(r, val):
            if not r.left and not r.right:
                return int(r.val != val)
            if r.val == 5:
                return dp(r.left or r.right, not val)
            res = float('inf')
            for x in [False, True]:
                for y in [False, True]:
                    if op(x, y, r.val) == val:
                        res = min(res, dp(r.left, x) + dp(r.right, y))
            return res
        return dp(root, result)

class Solution:
    def minFlips(self, a: int, b: int, c: int) -> int:
        res = 0
        for _ in range(32):
            if (a % 2) | (b % 2) != c % 2:
                if a % 2 == b % 2 == 1:
                    res += 1
                res += 1
            a = a // 2
            b = b // 2
            c = c // 2
        return res

from collections import defaultdict
import math

class Solution:
    def DFS(self, graph, i, prev, seats):
        size = 1
        for j in graph[i]:
            if j != prev:
                size += self.DFS(graph, j, i, seats)
        if i != 0:
            self.res += math.ceil(size / seats)
        return size

    def minimumFuelCost(self, roads: List[List[int]], seats: int) -> int:
        graph = defaultdict(set)
        for a, b in roads:
            graph[a].add(b)
            graph[b].add(a)
        self.res = 0
        self.DFS(graph, 0, -1, seats)
        return self.res

from collections import deque

class Solution:
    def minMutation(self, start: str, end: str, bank: List[str]) -> int:
        bank = set(bank)
        paths = deque([(start, 0)])
        seen = set()
        while len(paths) > 0:
            curr, t = paths.pop()
            if curr == end:
                return t
            n = len(curr)
            for i in range(n):
                for c in range(26):
                    mutation = curr[:i] + chr(ord('A') + c) + curr[i + 1:]
                    if mutation in bank and mutation not in seen:
                        paths.appendleft((mutation, t + 1))
                        seen.add(mutation)
        return -1

def solve(n, edges):
    g = [[] for _ in range(n)]
    for u, v in edges:
        g[u].append(v)
        g[v].append(u)
    ans = [0] * n
    removed = [False] * n
    size = [0] * n

    def dfs_size(u, p):
        size[u] = 1
        for v in g[u]:
            if v != p and not removed[v]:
                dfs_size(v, u)
                size[u] += size[v]

    def dfs_centroid(u, p, total):
        for v in g[u]:
            if v != p and not removed[v] and size[v] * 2 > total:
                return dfs_centroid(v, u, total)
        return u

    def dfs_collect(u, p, depth, sid, buf):
        buf.append((u, depth, sid))
        for v in g[u]:
            if v != p and not removed[v]:
                dfs_collect(v, u, depth + 1, sid, buf)

    def decompose(start):
        dfs_size(start, -1)
        c = dfs_centroid(start, -1, size[start])
        removed[c] = True
        buf = []
        max1 = max2 = 0
        best = -1
        sid = 0
        for v in g[c]:
            if removed[v]:
                continue
            tmp = []
            dfs_collect(v, c, 1, sid, tmp)
            lm = max(d for _, d, _ in tmp)
            if lm > max1:
                max2, max1 = max1, lm
                best = sid
            elif lm > max2:
                max2 = lm
            buf.extend(tmp)
            sid += 1
        ans[c] = max(ans[c], max1)
        for u, d, s in buf:
            use = max1 if s != best else max2
            ans[u] = max(ans[u], use + d)
        for v in g[c]:
            if not removed[v]:
                decompose(v)

    decompose(0)
    return ans

class Solution:
    def findMinHeightTrees(self, n: int, edges: List[List[int]]) -> List[int]:
        res = solve(n, edges)
        m = min(res)
        return [i for i in range(n) if res[i] == m]

class Solution:
    def minNumberOfHours(self, initialEnergy: int, initialExperience: int, energy: List[int], experience: List[int]) -> int:
        n = len(energy)
        res = 0
        for i in range(n):
            if initialEnergy > energy[i]:
                initialEnergy -= energy[i]
            else:
                res += energy[i] + 1 - initialEnergy
                initialEnergy = 1
            if initialExperience > experience[i]:
                initialExperience += experience[i]
            else:
                res += experience[i] + 1 - initialExperience
                initialExperience = 2 * experience[i] + 1
        return res

class Solution:
    def minIncrementForUnique(self, nums: List[int]) -> int:
        n = len(nums)
        res = 0
        nums.sort()
        for i in range(1, n):
            if nums[i] <= nums[i - 1]:
                res += nums[i - 1] + 1 - nums[i]
                nums[i] = nums[i - 1] + 1
        return res

import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        k = len(target)
        umask = (1 << k) - 1
        n = len(nums)

        v = []

        for cmask in range(1, 1 << k):
            l = 1
            for j in range(k):
                if cmask & (1 << j):
                    l = lcm(l, target[j])
            v.append((cmask, l))

        dp = [[float('inf')] * (1 << k) for _ in range(n + 1)]
        dp[n][umask] = 0

        for i in range(n - 1, -1, -1):
            for mask in range(1 << k):
                dp[i][mask] = dp[i + 1][mask]

                val = nums[i]
                for cmask, l in v:
                    new_mask = mask | cmask
                    cost = l * math.ceil(val / l) - val
                    dp[i][mask] = min(dp[i][mask], cost + dp[i + 1][new_mask])

        return dp[0][0]

class Solution:
    def get(self, arr):
        n = len(arr)
        res = []
        ctr = Counter()
        mx = (0, None)
        for i in range(n):
            ctr[arr[i]] += 1
            mx = max(mx, (ctr[arr[i]], arr[i]))
            if 2 * mx[0] > i + 1:
                res.append(mx[1])
            else:
                res.append(None)
        return res

    def minimumIndex(self, nums: List[int]) -> int:
        a = self.get(nums)
        b = self.get(nums[::-1])
        for i, el in enumerate(a):
            b.pop()
            if b and el == b[-1] and el != None:
                return i
        return -1

class Solution:
    def findRestaurant(self, list1: List[str], list2: List[str]) -> List[str]:
        l1pos = {}
        l2pos = {}
        for i, num in enumerate(list1):
            l1pos[num] = i
        for i, num in enumerate(list2):
            l2pos[num] = i
        common = set.intersection(set(list1), set(list2))
        sums = {}
        for c in common:
            curr = l1pos[c] + l2pos[c]
            sums[curr] = sums.get(curr, []) + [c]
        return sums[min(sums.keys())]

from functools import cmp_to_key

class Solution:
    def minimumEffort(self, tasks: List[List[int]]) -> int:
        def cmp(a, b):
            if max(a[1], a[0] + max(b[0], b[1])) > max(b[1], b[0] + max(a[0], a[1])):
                return 1
            return -1
        tasks.sort(key = cmp_to_key(cmp))
        res = 0
        used = 0
        for i in range(len(tasks)):
            res = max(res, used + tasks[i][1])
            used += tasks[i][0]
        return res

class Solution:
    def minIns(self, s, i, j):
        if i == j:
            return 0
        if i == j - 1:
            if s[i] == s[j]:
                return 0
            return 1
        if (i, j) in self.cache:
            return self.cache[(i, j)]
        if s[i] == s[j]:
            curr = self.minIns(s, i + 1, j - 1)
            self.cache[(i, j)] = curr
            return curr
        else:
            curr = 1 + min(self.minIns(s, i + 1, j), self.minIns(s, i, j - 1))
            self.cache[(i, j)] = curr
            return curr

    def minInsertions(self, s: str) -> int:
        self.cache = {}
        return self.minIns(s, 0, len(s) - 1)

class Solution:
    def minInsertions(self, s: str) -> int:
        n = len(s)
        res = 0
        stack = []
        i = 0
        while i < len(s):
            if s[i] == '(':
                stack.append(s[i])
            else:
                if i + 1 == n or s[i + 1] != ')':
                    res += 1
                else:
                    i += 1
                if not stack:
                    res += 1
                else:
                    stack.pop()
            i += 1
        res += 2 * len(stack)
        return res

from sortedcontainers import SortedList
import heapq

class Solution:
    def minInterval(self, intervals: List[List[int]], queries: List[int]) -> List[int]:
        intervals.sort()
        queries = sorted([(queries[i], i) for i in range(len(queries))])
        res = [-1] * len(queries)
        i = 0
        ends = []
        lens = SortedList()
        for q, qpos in queries:
            while i < len(intervals) and intervals[i][0] <= q:
                heapq.heappush(ends, (intervals[i][1], intervals[i][1] - intervals[i][0] + 1))
                lens.add(intervals[i][1] - intervals[i][0] + 1)
                i += 1
            while ends and ends[0][0] < q:
                lens.remove(heapq.heappop(ends)[1])
            if lens:
                res[qpos] = lens[0]
        return res

class Solution:
    def minimumLength(self, s: str) -> int:
        l, r = 0, len(s) - 1
        while l < r:
            if s[l] == s[r]:
                while l < r and s[l] == s[l + 1]:
                    l += 1
                while l < r and s[r] == s[r - 1]:
                    r -= 1
                l += 1
                r -= 1
            else:
                return r - l + 1
        return int(l == r)

from collections import Counter

class Solution:
    def minimumLength(self, s: str) -> int:
        res = 0
        ctr = Counter(s)
        for c in ctr:
            x = ctr[c]
            while x >= 3:
                x -= 2
            res += x
        return res

import math

class Solution:
    def isPossible(self, nums, maxOperations, l):
        curr = 0
        for b in nums:
            curr += math.ceil(b / l) - 1
        return curr <= maxOperations

    def minimumSize(self, nums: List[int], maxOperations: int) -> int:
        beg = 1
        end = max(nums)
        res = end
        while beg <= end:
            mid = (beg + end) // 2
            if self.isPossible(nums, maxOperations, mid):
                res = mid
                end = mid - 1
            else:
                beg = mid + 1
        return res

class Solution:
    def minimumLines(self, stockPrices: List[List[int]]) -> int:
        stockPrices.sort()
        stack = []
        for x, y in stockPrices:
            if len(stack) < 2:
                stack.append((x, y))
            else:
                ppx, ppy = stack[-2]
                px, py = stack[-1]
                if (py - ppy) * (x - px) == (px - ppx) * (y - py):
                    stack.pop()
                stack.append((x, y))
        return len(stack) - 1

class Solution:
    def minMoves(self, classroom, energy):
        n = len(classroom)
        m = len(classroom[0])
        lmap = {}
        lc = 0
        for i in range(n):
            for j in range(m):
                if classroom[i][j] == 'L':
                    lmap[(i, j)] = lc
                    lc += 1
                elif classroom[i][j] == 'S':
                    sr = i
                    sc = j
        fullmask = (1 << lc) - 1
        best = [[[-1] * (1 << lc) for _ in range(m)] for _ in range(n)]
        q = deque()
        q.append((sr, sc, energy, 0, 0))
        best[sr][sc][0] = energy

        while q:
            r, c, e, mask, steps = q.popleft()

            if mask == fullmask:
                return steps

            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr = r + dr
                nc = c + dc

                if nr < 0 or nr >= n or nc < 0 or nc >= m:
                    continue

                cell = classroom[nr][nc]
                if cell == 'X':
                    continue

                ne = e - 1
                if ne < 0:
                    continue

                if cell == 'R':
                    ne = energy

                nmask = mask
                if cell == 'L':
                    nmask |= 1 << lmap[(nr, nc)]

                if ne <= best[nr][nc][nmask]:
                    continue

                best[nr][nc][nmask] = ne
                q.append((nr, nc, ne, nmask, steps + 1))

        return -1

class Solution:
    def minimumMoves(self, s: str) -> int:
        n = len(s)
        s = list(s)
        res = 0
        for i in range(n - 2):
            if s[i] == 'X' and (i == 0 or s[i - 1] == 'O'):
                s[i] = 'O'
                s[i + 1] = 'O'
                s[i + 2] = 'O'
                res += 1
            elif i == n - 3 and (s[i + 1] != 'O' or s[i + 2] != 'O'):
                res += 1
        return res

class Solution:
    def minMoves2(self, nums: List[int]) -> int:
        n = len(nums)
        nums.sort()
        p = [0]
        for el in nums:
            p.append(p[-1] + el)
        mindels = float('inf')
        for i in range(1, n + 1):
            currdels = nums[i - 1] * (2 * i - n) - 2 * p[i]
            mindels = min(mindels, currdels)
        return mindels + p[-1]

class Solution:
    def minMoves(self, nums: List[int]) -> int:
        return sum(nums) - min(nums) * len(nums)

class Solution:
    def minMoves(self, rooks: List[List[int]]) -> int:
        res = 0
        rooks.sort(key = lambda p: p[0])
        for i in range(len(rooks)):
            res += abs(i - rooks[i][0])
        rooks.sort(key = lambda p: p[1])
        for i in range(len(rooks)):
            res += abs(i - rooks[i][1])
        return res

from collections import deque

class Solution:
    def minPushBox(self, grid: List[List[str]]) -> int:
        m = len(grid)
        n = len(grid[0])
        valid = lambda x, y: 0 <= x < m and 0 <= y < n and grid[x][y] != "#"
        start = box = -1
        for i in range(m):
            for j in range(n):
                if grid[i][j] == "S":
                    start = (i, j)
                if grid[i][j] == "B":
                    box = (i, j)
        q = deque([(start, box, 0)])
        v = {(start, box)}
        res = -1
        while len(q) > 0:
            curr, currbox, d = q.pop()
            if grid[currbox[0]][currbox[1]] == "T":
                return d
            for dx, dy in [(-1, 0), (0, -1), (1, 0), (0, 1)]:
                x, y = curr[0] + dx, curr[1] + dy
                if not valid(x, y):
                    continue
                if (x, y) == currbox:
                    newbox = (curr[0] + 2 * dx, curr[1] + 2 * dy)
                    if valid(newbox[0], newbox[1]) and ((x, y), newbox) not in v:
                        v.add(((x, y), newbox))
                        q.appendleft(((x, y), newbox, d + 1))
                elif ((x, y), currbox) not in v:
                    v.add(((x, y), currbox))
                    q.append(((x, y), currbox, d))
        return res

class Solution:
    def minMoves(self, target: int, maxDoubles: int) -> int:
        n = 0
        while target > 1 and maxDoubles > 0:
            n += 1 + target % 2
            target = target // 2
            maxDoubles -= 1
        return n + target - 1

from collections import deque

dp = {}
initial = (1,) * 9
queue = deque([initial])
dp[initial] = 0
neighbors = [[] for _ in range(9)]
for i in range(9):
    r, c = i // 3, i % 3
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        nr, nc = r + dr, c + dc
        if 0 <= nr < 3 and 0 <= nc < 3:
            neighbors[i].append(nr * 3 + nc)
while queue:
    state = queue.popleft()
    d = dp[state]
    for i in range(9):
        if state[i]:
            for j in neighbors[i]:
                ns = list(state)
                ns[i] -= 1
                ns[j] += 1
                ns = tuple(ns)
                if ns not in dp:
                    dp[ns] = d + 1
                    queue.append(ns)

class Solution:
    def minimumMoves(self, grid: List[List[int]]) -> int:
        state = tuple(grid[i][j] for i in range(3) for j in range(3))
        return dp[state]

class Solution:
    def findMinArrowShots(self, points: List[List[int]]) -> int:
        n = len(points)
        points.sort()
        prev = float('-inf')
        ctr = 0
        for a, b in points:
            prev = min(prev, b + 1)
            if prev <= a:
                ctr += 1
                prev = b + 1
        return ctr

class Solution:
    def minimumChairs(self, s: str) -> int:
        x = 0
        res = 0
        for c in s:
            x += 1 if c == 'E' else -1
            res = max(res, x)
        return res

class Solution:
    def minChanges(self, s: str) -> int:
        n = len(s)
        res = 0
        for i in range(0, n, 2):
            cost = int(s[i]) + int(s[i + 1])
            cost = min(cost, 2 - cost)
            res += cost
        return res

from collections import *

class Solution:
    def minimumCoins(self, prices: List[int]) -> int:
        n = len(prices)
        q = deque([(n, 0)])
        res = 0
        for i in range(n - 1, -1, -1):
            while q and q[-1][0] > 2 * i + 2:
                q.pop()
            curr = prices[i] + q[-1][1]
            while q and curr < q[0][1]:
                q.popleft()
            q.appendleft((i, curr))
            res = curr
        return res

class Solution:
    def minimumAddedCoins(self, coins: List[int], target: int) -> int:
        res = 0
        while True:
            coins.sort()
            found = 0
            if coins[0] > 1:
                found = 1
            else:
                p = 0
                for i in range(len(coins)):
                    p += coins[i]
                    if i == len(coins) - 1 or p + 1 < coins[i + 1]:
                        found = p + 1
                        break
            if found > target:
                break
            coins.append(found)
            res += 1
        return res

class Solution:
    def dfs(self, node, parent, vis, tin, low, mark, graph):
        vis[node] = 1
        tin[node] = low[node] = self.timer
        self.timer += 1
        child = 0
        for it in graph[node]:
            if it == parent:
                continue
            if not vis[it]:
                self.dfs(it, node, vis, tin, low, mark, graph)
                low[node] = min(low[node], low[it])
                if low[it] >= tin[node] and parent != -1:
                    mark[node] = 1
                child += 1
            else:
                low[node] = min(low[node], tin[it])
        if child > 1 and parent == -1:
            mark[node] = 1

    def minDays(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        graph = [[] for _ in range(m * n)]
        ones = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 0:
                    continue
                ones += 1
                for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
                    if 0 <= x < m and 0 <= y < n and grid[x][y] == 1:
                        graph[n * i + j].append(n * x + y)
        if ones == 1:
            return 1
        self.timer = 0
        vis = [0] * (m * n)
        tin = [0] * (m * n)
        low = [0] * (m * n)
        mark = [0] * (m * n)
        comp = 0
        for i in range(m * n):
            if not vis[i] and grid[i // n][i % n] == 1:
                comp += 1
                self.dfs(i, -1, vis, tin, low, mark, graph)
        if comp == 0 or comp > 1:
            return 0
        for i in range(m * n):
            if mark[i] == 1:
                return 1
        return 2

class Solution:
    def minDays(self, n: int) -> int:
        @lru_cache(maxsize = None)
        def dp(n):
            if n == 0:
                return -1
            return 1 + min(n % 2 + dp(n // 2), n % 3 + dp(n // 3))
        return dp(n)

class Solution:
    def minDays(self, bloomDay: List[int], m: int, k: int) -> int:
        n = len(bloomDay)
        beg = min(bloomDay)
        end = max(bloomDay)
        res = -1
        while beg <= end:
            mid = (beg + end) // 2
            curr = 0
            i = 0
            while i < n:
                ctr = 1
                while i < n - 1 and (bloomDay[i] <= mid) == (bloomDay[i + 1] <= mid):
                    i += 1
                    ctr += 1
                if bloomDay[i] <= mid:
                    curr += ctr // k
                i += 1
            if curr >= m:
                res = mid
                end = mid - 1
            else:
                beg = mid + 1
        return res

from collections import deque

class Solution:
    def minFlips(self, mat: List[List[int]]) -> int:
        m = len(mat)
        n = len(mat[0])
        matmask = 0
        for i in range(m * n):
            if mat[i // n][i % n] == 1:
                matmask ^= (1 << i)
        v = {matmask}
        q = deque([(matmask, 0)])
        while len(q) > 0:
            curr, steps = q.pop()
            if curr == 0:
                return steps
            for i in range(m):
                for j in range(n):
                    currmask = curr 
                    for x, y in [(i, j), (i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
                        if 0 <= x < m and 0 <= y < n:
                            currmask ^= (1 << (n * x + y))
                    if currmask not in v:
                        v.add(currmask)
                        q.appendleft((currmask, steps + 1))
        return -1

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        a = b = 0
        for i in range(m):
            for j in range(n // 2):
                if grid[i][j] != grid[i][~j]:
                    a += 1
        for j in range(n):
            for i in range(m // 2):
                if grid[i][j] != grid[~i][j]:
                    b += 1
        return min(a, b)

class Solution:
    def minsum(self, arr, n, k):
        res = float('inf')
        curr = 0
        for i in range(n):
            curr += arr[i]
            if i >= k:
                curr -= arr[i - k]
            if i >= k - 1:
                res = min(res, curr)
        return res

    def minFlips(self, s: str) -> int:
        n = len(s)
        res = n
        a = [0] * n * 2
        b = [0] * n * 2
        for i in range(2 * n):
            if int(s[i % n]) != i % 2:
                a[i] = 1
            else:
                b[i] = 1
        asum = self.minsum(a, 2 * n, n)
        bsum = self.minsum(b, 2 * n, n)
        return min(asum, bsum)

class Solution:
    def minimumBuckets(self, hamsters: str) -> int:
        hamsters = list(hamsters)
        n = len(hamsters)
        res = 0
        for i in range(n):
            valid = False
            if hamsters[i] == "H":
                if i > 0 and hamsters[i - 1] == "B":
                    valid = True
                if not valid:
                    res += 1
                    if i < n - 1 and hamsters[i + 1] == ".":
                        hamsters[i + 1] = "B"
                    elif i > 0 and hamsters[i - 1] == ".":
                        hamsters[i - 1] = "B"
                    else:
                        return -1
        return res

from collections import defaultdict

def firstlarger(arr, val):
    beg = 0
    end = len(arr) - 1
    res = float('inf')
    while beg <= end:
        mid = (beg + end) // 2
        if arr[mid] > val:
            res = arr[mid]
            end = mid - 1
        else:
            beg = mid + 1
    return res

class Solution:
    def minGroupsForValidAssignment(self, nums: List[int]) -> int:
        n = len(nums)
        ctr = defaultdict(int)
        for el in nums:
            ctr[el] += 1
        freqs = set()
        for el in ctr:
            freqs.add(ctr[el])
        sf = sorted(freqs)
        res = n
        for s in range(n, 0, -1):
            pos = True
            mul = 0
            while (s + 1) * mul <= n:
                rf = firstlarger(sf, (s + 1) * mul)
                if rf < (s + 1) * (mul + 1) and rf < mul * s + s:
                    pos = False
                    break
                mul += 1
            if pos:
                res = sum(ctr[el] // (s + 1) + int(ctr[el] % (s + 1) > 0) for el in ctr)
                break
        return res

class Solution:
    def minNumberOperations(self, target: List[int]) -> int:
        n = len(target)
        res = 0
        for i in range(n):
            prev = 0
            if i > 0:
                prev = target[i - 1]
            res += max(target[i] - prev, 0)
        return res

class Solution:
    def minKBitFlips(self, nums: List[int], k: int) -> int:
        n = len(nums)
        diffs = [0] * (n + 1)
        res = 0
        for i in range(n):
            if i > 0:
                diffs[i] += diffs[i - 1]
            if diffs[i] & 1:
                nums[i] = 1 - nums[i]
            if i + k <= n and nums[i] == 0:
                res += 1
                nums[i] = 1
                diffs[i] += 1
                diffs[i + k] -= 1
        if sum(nums) != n:
            return -1
        return res

class Solution:
    def minMovesToMakePalindrome(self, s: str) -> int:
        if len(s) <= 1:
            return 0
        f = {}
        l = {}
        for i in range(len(s)):
            if s[i] not in f:
                f[s[i]] = i
            l[s[i]] = i
        minmoves = (float('inf'), "z")
        for i in range(26):
            c = chr(ord('a') + i)
            if f.get(c, float('inf')) < l.get(c, float('-inf')):
                minmoves = min(minmoves, (f.get(c, float('inf')) + len(s) - 1 - l.get(c, float('-inf')), c))
        i = f[minmoves[1]]
        j = l[minmoves[1]]
        news = s[:i] + s[i+1:j] + s[j+1:]
        return minmoves[0] + self.minMovesToMakePalindrome(news)

class Solution:
    def minMovesToSeat(self, seats: List[int], students: List[int]) -> int:
        seats.sort()
        students.sort()
        return sum(abs(seats[i] - students[i]) for i in range(len(seats)))

class Solution:
    def convertTime(self, current: str, correct: str) -> int:
        bhh, bmm = [int(x) for x in current.split(":")]
        ehh, emm = [int(x) for x in correct.split(":")]
        diff = (ehh - bhh) * 60 + (emm - bmm)
        ctr = 0
        while diff > 0:
            if diff >= 60:
                ctr += diff // 60
                diff = diff % 60
            elif diff >= 15:
                ctr += diff // 15
                diff = diff % 15
            elif diff >= 5:
                ctr += diff // 5
                diff = diff % 5
            else:
                ctr += diff
                break
        return ctr

class Solution:
    def gcd(self, a, b):
        while b:
            a, b = b, a % b
        return a

    def minOperations(self, nums: List[int]) -> int:
        n = len(nums)
        if nums.count(1) > 0:
            return n - nums.count(1)
        minops = float('inf')
        for i in range(n):
            j = i
            g = nums[i]
            while j >= 0:
                g = self.gcd(g, nums[j])
                if g == 1:
                    break
                j -= 1
            if g == 1:
                minops = min(minops, i - j)
            j = i
            g = nums[i]
            while j < n:
                g = self.gcd(g, nums[j])
                if g == 1:
                    break
                j += 1
            if g == 1:
                minops = min(minops, j - i)
        if minops == float('inf'):
            return -1
        return n - 1 + minops

from bisect import *

class Solution:
    def minOperations(self, nums: List[int]) -> int:
        n = len(nums)
        nums.sort()
        vals = sorted(set(nums))
        def minops(beg):
            return n - bisect_right(vals, beg + n - 1) + bisect_left(vals, beg)
        res = n - 1
        for i in range(n):
            res = min(res, minops(nums[i]), minops(nums[i] - i))
        return res

from collections import Counter

class Solution:
    def minOperations(self, nums: List[int]) -> int:
        res = 0
        for f in Counter(nums).values():
            if f == 1:
                return -1
            while f % 3 != 0:
                f -= 2
                res += 1
            res += f // 3
        return res

class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        for el in nums:
            k ^= el
        return k.bit_count()

class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        res = 0
