from collections import deque

class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        q = deque([(x, 0)])
        v = {x}
        while len(q) > 0:
            curr, steps = q.pop()
            if curr == y:
                return steps
            if curr % 11 == 0 and (curr // 11) not in v:
                v.add(curr // 11)
                q.appendleft((curr // 11, steps + 1))
            if curr % 5 == 0 and (curr // 5) not in v:
                v.add(curr // 5)
                q.appendleft((curr // 5, steps + 1))
            if (curr + 1) not in v:
                v.add(curr + 1)
                q.appendleft((curr + 1, steps + 1))
            if curr > 1 and (curr - 1) not in v:
                v.add(curr - 1)
                q.appendleft((curr - 1, steps + 1))

class Solution:
    def minimumOperations(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        f = [[0] * 10 for _ in range(n)]
        for j in range(n):
            for i in range(m):
                f[j][grid[i][j]] += 1
        dp = [[float('inf')] * 10 for _ in range(n)]
        for i in range(n):
            for j in range(10):
                for prev in range(10):
                    if j != prev:
                        dp[i][j] = min(dp[i][j], m - f[i][j] + (dp[i - 1][prev] if i > 0 else 0))
        return min(dp[n - 1])

from collections import deque, defaultdict

class Solution:
    def minSwap(self, arr):
        n = len(arr)
        res = 0
        oldarr = arr[:]
        h = {}
        oldarr.sort()
        for i in range(n):
            h[arr[i]] = i
        init = 0
        for i in range(n):
            if arr[i] != oldarr[i]:
                res += 1
                init = arr[i]
                arr[i], arr[h[oldarr[i]]] = arr[h[oldarr[i]]], arr[i]
                h[init] = h[oldarr[i]]
                h[oldarr[i]] = i
        return res

    def minimumOperations(self, root: Optional[TreeNode]) -> int:
        q = deque([(root, 0)])
        levels = defaultdict(list)
        while len(q) > 0:
            curr, l = q.pop()
            if curr:
                levels[l].append(curr.val)
                q.appendleft((curr.left, l + 1))
                q.appendleft((curr.right, l + 1))
        res = 0
        for l in levels:
            res += self.minSwap(levels[l])
        return res

class Solution:
    def minRefuelStops(self, target: int, startFuel: int, stations: List[List[int]]) -> int:
        n = len(stations)
        dp = [0] * (n + 1)
        dp[0] = startFuel
        for i in range(n):
            l, c = stations[i]
            for j in range(i, -1, -1):
                if dp[j] >= l:
                    dp[j + 1] = max(dp[j + 1], dp[j] + c)
        for i in range(n + 1):
            if dp[i] >= target:
                return i
        return -1

class Solution:
    def minimumMountainRemovals(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [1] * n
        revdp = [1] * n
        for j in range(n):
            for i in range(j):
                if nums[i] < nums[j]:
                    dp[j] = max(dp[j], 1 + dp[i])
        for j in range(n - 1, -1, -1):
            for i in range(j + 1, n):
                if nums[i] < nums[j]:
                    revdp[j] = max(revdp[j], 1 + revdp[i])
        used = 0
        for i in range(n):
            if dp[i] > 1 and revdp[i] > 1:
                used = max(used, dp[i] + revdp[i] - 1)
        return n - used

class Solution:
    def minNumberOfSeconds(self, mountainHeight: int, workerTimes: List[int]) -> int:
        m = min(workerTimes)
        beg = 1
        end = m * mountainHeight * (mountainHeight + 1) // 2
        @lru_cache(maxsize = None)
        def tt(v):
            beg = 0
            end = v
            while beg <= end:
                mid = (beg + end) // 2
                if mid * (mid + 1) // 2 <= v:
                    beg = mid + 1
                else:
                    end = mid - 1
            return beg - 1
        while beg <= end:
            mid = (beg + end) // 2
            cut = 0
            for el in workerTimes:
                cut += tt(mid // el)
            if cut >= mountainHeight:
                end = mid - 1
            else:
                beg = mid + 1
        return end + 1

