class Solution:
    def jump(self, nums):
        l, r = 0, nums[0]
        times = 1
        while r < len(nums) - 1:
            times += 1
            nxt = max(i + nums[i] for i in range(l, r + 1))
            if nxt <= r:
                return -1
            l, r = r, nxt
        return times

    def minValidStrings(self, words: List[str], target: str) -> int:
        n = len(target)
        arr = [0] * (n + 1)
        groups = defaultdict(set)
        for w in words:
            shash = SHash(w)
            m = len(w)
            for l in range(1, m + 1):
                groups[l].add(shash.hash(0, l - 1))
        shash = SHash(target)
        for i in range(n - 1, -1, -1):
            beg = 1
            end = n - i
            while beg <= end:
                mid = (beg + end) // 2
                if shash.hash(i, i + mid - 1) in groups[mid]:
                    beg = mid + 1
                else:
                    end = mid - 1
            arr[i] = beg - 1
        return self.jump(arr)

class Solution:
    def findSmallestSetOfVertices(self, n: int, edges: List[List[int]]) -> List[int]:
        indegree = {}
        for a, b in edges:
            indegree[b] = indegree.get(b, 0) + 1
        return [i for i in range(n) if i not in indegree]

from sortedcontainers import SortedList

class Visiter:
    def __init__(self, m, n):
        self.m = m
        self.n = n
        self.rows = [SortedList(range(n)) for _ in range(m)]
        self.cols = [SortedList(range(m)) for _ in range(n)]

    def visit(self, i, j):
        self.rows[i].discard(j)
        self.cols[j].discard(i)

    def right(self, i, j, k):
        sl = self.rows[i]
        idx = sl.bisect_left(j + 1)
        res = []
        while idx < len(sl) and sl[idx] <= j + k:
            res.append(sl[idx])
            idx += 1
        return [(i, c) for c in res]

    def down(self, i, j, k):
        sl = self.cols[j]
        idx = sl.bisect_left(i + 1)
        res = []
        while idx < len(sl) and sl[idx] <= i + k:
            res.append(sl[idx])
            idx += 1
        return [(r, j) for r in res]

    def get(self, i, j, k):
        return self.right(i, j, k) + self.down(i, j, k)

class Solution:
    def minimumVisitedCells(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        q = deque([(1, 0, 0)])
        v = Visiter(m, n)
        v.visit(0, 0)
        while q:
            d, i, j = q.pop()
            if (i, j) == (m - 1, n - 1):
                return d
            for x, y in v.get(i, j, grid[i][j]):
                v.visit(x, y)
                q.appendleft((d + 1, x, y))
        return -1

class Solution:
    def minOperations(self, nums: List[int]) -> int:
        res = 0
        odds = 0
        for el in nums:
            curr = 0
            while el:
                if el & 1:
                    el -= 1
                    odds += 1
                else:
                    el //= 2
                    curr += 1
            res = max(res, curr)
        res += odds
        return res

from collections import deque

class Solution:
    def minimumObstacles(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        q = deque([(0, 0, 0)])
        v = {(0, 0)}
        while len(q) > 0:
            x, y, d = q.pop()
            if (x, y) == (m - 1, n - 1):
                return d
            for i, j in [(x - 1, y), (x, y - 1), (x + 1, y), (x, y + 1)]:
                if 0 <= i < m and 0 <= j < n:
                    if (i, j) in v:
                        continue
                    v.add((i, j))
                    if grid[i][j] == 1:
                        q.appendleft((i, j, d + 1))
                    else:
                        q.append((i, j, d))

class Solution:
    def minimumOneBitOperations(self, n: int) -> int:
        res = 0
        while n:
            res = -res - (n ^ (n - 1))
            n &= n - 1
        return abs(res)

class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        rem = set(range(1, k + 1))
        res = 0
        while len(nums) > 0 and len(rem) > 0:
            curr = nums.pop()
            if curr in rem:
                rem.remove(curr)
            res += 1
        return res

class Solution:
    def minimumOperations(self, nums: List[int], start: int, goal: int) -> int:
        paths = [(start, 0)]
        visited = {start}
        i = 0
        while i < len(paths):
            curr, steps = paths[i]
            if curr == goal:
                return steps
            if 0 <= curr <= 1000:
                for num in nums:
                    if (curr + num) not in visited:
                        visited.add((curr + num))
                        paths.append((curr + num, steps + 1))
                    if (curr - num) not in visited:
                        visited.add((curr - num))
                        paths.append((curr - num, steps + 1))
                    if (curr ^ num) not in visited:
                        visited.add((curr ^ num))
                        paths.append((curr ^ num, steps + 1))
            i += 1
        return -1

class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        res = 0
        for el in nums:
            if el < k:
                res += 1
        return res

class Solution:
    def maxsub(self, num, i, n, mod):
        if i >= n:
            return 0 if mod == 0 else float('-inf')
        key = (i, mod)
        if key in self.cache:
            return self.cache[key]
        a = self.maxsub(num, i + 1, n, mod)
        b = 1 + self.maxsub(num, i + 1, n, (10 * mod + int(num[i])) % 25)
        res = max(a, b)
        self.cache[key] = res
        return res

    def minimumOperations(self, num: str) -> int:
        self.cache = {}
        return len(num) - self.maxsub(num, 0, len(num), 0)

class Solution:
    def minOperations(self, target: List[int], arr: List[int]) -> int:
        res = []
        pos = {}
        for i in range(len(target)):
            pos[target[i]] = i
        for el in arr:
            if el not in pos:
                continue
            x = bisect.bisect_left(res, pos[el])
            if x < len(res):
                res[x] = pos[el]
            else:
                res.append(pos[el])
        return len(target) - len(res)

import bisect

class Solution:
    def minOperations(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        nums.sort()
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] += p[i] + nums[i]
        res = []
        for q in queries:
            i = bisect.bisect_left(nums, q)
            res.append(i * q - p[i] + (p[-1] - p[i]) - (n - i) * q)
        return res

import math

def ops(l, r):
    total = 0
    m = 0
    start = l
    k = 1
    while True:
        low = 4 ** (k - 1)
        high = 4 ** k - 1
        if low > r:
            break
        a = max(start, low)
        b = min(r, high)
        if a <= b:
            cnt = b - a + 1
            total += k * cnt
            m = k
        k += 1
    b1 = m
    b2 = math.ceil(total / 2)
    return max(b1, b2)

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        return sum(ops(l, r) for l, r in queries)

class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int], k: int) -> int:
        n = len(nums1)
        if k == 0:
            if nums1 == nums2:
                return 0
            return -1
        pos = neg = 0
        for i in range(n):
            d = nums1[i] - nums2[i]
            if abs(d) % k != 0:
                return -1
            if d >= 0:
                pos += abs(d) // k
            else:
                neg += abs(d) // k
        if pos != neg:
            return -1
        return pos

class Solution:
    def minimumOperations(self, nums: List[int], target: List[int]) -> int:
        n = len(nums)
        res = float('inf')
        arr = [target[i] - nums[i] for i in range(n)]
        res = abs(arr[0])
        for i in range(1, len(arr)):
            res += abs(arr[i] - arr[i - 1])
        res += abs(arr[-1])
        return res // 2

class Solution:
    def minOperations(self, n: int) -> int:
        return (n * n) >> 2

class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        if k > min(nums):
            return -1
        return len(set(x for x in nums if x > k))

class Solution:
    def minOperations(self, nums: List[int]) -> int:
        res = 0
        for i in range(len(nums) - 2):
            if nums[i] == 0:
                res += 1
                nums[i] = 1 - nums[i]
                nums[i + 1] = 1 - nums[i + 1]
                nums[i + 2] = 1 - nums[i + 2]
        if nums[-2] == 0 or nums[-1] == 0:
            return -1
        return res

class Solution:
    def minOperations(self, nums: List[int]) -> int:
        flips = 0
        res = 0
        for el in nums:
            if flips & 1:
                el = 1 - el
            if el == 0:
                flips += 1
                res += 1
        return res

class Solution:
    def minimumOperations(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        res = 0
        for j in range(n):
            for i in range(1, m):
                if grid[i][j] <= grid[i - 1][j]:
                    res += grid[i - 1][j] + 1 - grid[i][j]
                    grid[i][j] = grid[i - 1][j] + 1
        return res

from sortedcontainers import SortedList

class Solution:
    def ops(self, arr, k):
        left, right = SortedList(), SortedList()
        left_sum, right_sum = 0, 0
        res = []
        def rebalance():
            nonlocal left_sum, right_sum
            window = len(left) + len(right)
            required_left = (window + 1) // 2
            while len(left) > required_left:
                x = left.pop()
                left_sum -= x
                right.add(x)
                right_sum += x
            while len(left) < required_left:
                if not right:
                    break
                x = right.pop(0)
                right_sum -= x
                left.add(x)
                left_sum += x
        def add(x):
            nonlocal left_sum, right_sum
            if not left or x <= left[-1]:
                left.add(x)
                left_sum += x
            else:
                right.add(x)
                right_sum += x
            rebalance()
        def remove(x):
            nonlocal left_sum, right_sum
            if left and x <= left[-1]:
                idx = left.bisect_left(x)
                left_sum -= left[idx]
                left.pop(idx)
            else:
                idx = right.bisect_left(x)
                right_sum -= right[idx]
                right.pop(idx)
            rebalance()
        for i, x in enumerate(arr):
            add(x)
            if i >= k:
                remove(arr[i-k])
            if i >= k-1:
                m = left[-1]
                cost = m * len(left) - left_sum + right_sum - m * len(right)
                res.append(cost)
        return res

    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)
        mops = self.ops(nums, x)
        dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
        dp[n][0] = 0
        for i in range(n - 1, -1, -1):
            for rem in range(k + 1):
                dp[i][rem] = dp[i + 1][rem]
                if i + x <= n and rem:
                    dp[i][rem] = min(dp[i][rem], mops[i] + dp[i + x][rem - 1])
        return dp[0][k]

class Solution:
    def minOperationsToMakeMedianK(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nums.sort()
        median = n // 2
        res = 0
        res += abs(nums[median] - k)
        for i in range(median):
            if nums[i] > k:
                res += nums[i] - k
        for i in range(median + 1, n):
            if nums[i] < k:
                res += k - nums[i]
        return res

class Solution:
    def minOperations(self, nums: List[int], x: int, y: int) -> int:
        nums.sort()
        def check(ops):
            req = 0
            for el in [el - y * ops for el in nums if el - y * ops > 0]:
                req += math.ceil(el / (x - y))
            return req <= ops
        end = 1
        while not check(end):
            end *= 2
        beg = end // 2
        while beg <= end:
            mid = (beg + end) // 2
            if check(mid):
                end = mid - 1
            else:
                beg = mid + 1
        return end + 1

from collections import Counter

class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        n = len(nums)
        ctr = [Counter(), Counter()]
        for i in range(n):
            ctr[i % 2][nums[i]] += 1
        res = 0
        evensecmax, evenmax = (0, 0), (0, 0)
        oddsecmax, oddmax = (0, 0), (0, 0)
        for el in ctr[0]:
            temp, evensecmax, evenmax = sorted([evensecmax, evenmax, (ctr[0][el], el)])
        for el in ctr[1]:
            temp, oddsecmax, oddmax = sorted([oddsecmax, oddmax, (ctr[1][el], el)])
        for a in [evensecmax[1], evenmax[1]]:
            for b in [oddsecmax[1], oddmax[1]]:
                if a != b:
                    res = max(res, ctr[0][a] + ctr[1][b])
        return n - res

class Solution:
    def minOperations(self, nums: List[int]) -> int:
        n = len(nums)
        ctr = 0
        for i in range(n - 1):
            if nums[i + 1] <= nums[i]:
                ctr += nums[i] + 1 - nums[i + 1]
                nums[i + 1] = nums[i] + 1
        return ctr

import bisect

class Solution:
    def kIncreasing(self, arr: List[int], k: int) -> int:
        n = len(arr)
        lis = [[] for _ in range(k)]
        res = n
        for i in range(n):
            x = bisect.bisect_left(lis[i % k], (arr[i], i))
            if x < len(lis[i % k]):
                lis[i % k][x] = (arr[i], i)
            else:
                lis[i % k].append((arr[i], i))
                res -= 1
        return res

class Solution:
    def check(self, val, x):
        return "{:b}".format(val).count("1") <= x <= val

    def makeTheIntegerZero(self, num1: int, num2: int) -> int:
        res = -1
        x = 1
        while x < 65:
            if num1 - x * num2 > 0 and self.check(num1 - x * num2, x):
                return x
            x += 1
        return res

class Solution:
    def count(self, arr1, val1, arr2, val2):
        n = len(arr1)
        res = 0
        for i in range(n - 1):
            if arr1[i] > val1:
                if arr2[i] > val1:
                    res = float('inf')
                    break
                if arr1[i] > val2:
                    res = float('inf')
                    break
                res += 1
            elif arr2[i] > val2:
                if arr1[i] > val2:
                    res = float('inf')
                    break
                if arr2[i] > val1:
                    res = float('inf')
                    break
                res += 1
        return res

    def minOperations(self, nums1: List[int], nums2: List[int]) -> int:
        res = min(self.count(nums1, nums1[-1], nums2, nums2[-1]), 1 + self.count(nums1, nums2[-1], nums2, nums1[-1]))
        if res == float('inf'):
            return -1
        return res

class Solution:
    def minOperations(self, nums: List[int], x: int) -> int:
        n = len(nums)
        total = sum(nums)
        if total == x:
            return n
        curr = 0
        pos = {0: -1}
        mlen = 0
        for i in range(n):
            curr += nums[i]
            if (curr - total + x) in pos:
                mlen = max(mlen, i - pos[curr - total + x])
            pos[curr] = i
        if mlen == 0:
            return -1
        return n - mlen

class Solution:
    def minimumOperationsToWriteY(self, grid: List[List[int]]) -> int:
        n = len(grid)
        center = (n // 2, n // 2)
        ycells = set()
        x = y = 0
        while x <= center[0]:
            ycells.add((x, y))
            x += 1
            y += 1
        x = 0
        y = n - 1
        while x <= center[0]:
            ycells.add((x, y))
            x += 1
            y -= 1
        x = center[0]
        y = center[1]
        while x < n:
            ycells.add((x, y))
            x += 1
        res = n * n
        for ycolor in range(3):
            for rest in range(3):
                if ycolor == rest:
                    continue
                ychange = 0
                restchange = 0
                for i in range(n):
                    for j in range(n):
                        if (i, j) in ycells and grid[i][j] != ycolor:
                            ychange += 1
                        if (i, j) not in ycells and grid[i][j] != rest:
                            restchange += 1
                res = min(res, ychange + restchange)
        return res

class Solution:
    def minCost(self, grid, moveCost, i, j, m, n):
        if i == m - 1:
            return grid[i][j]
        if (i, j) in self.cache:
            return self.cache[(i, j)]
        mincost = float('inf')
        for col in range(n):
            curr = self.minCost(grid, moveCost, i + 1, col, m, n)
            mincost = min(mincost, grid[i][j] + moveCost[grid[i][j]][col] + curr)
        self.cache[(i, j)] = mincost
        return mincost

    def minPathCost(self, grid: List[List[int]], moveCost: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        self.cache = {}
        mincost = float('inf')
        for j in range(n):
            curr = self.minCost(grid, moveCost, 0, j, m, n)
            mincost = min(mincost, curr)
        return mincost

class Solution:
    def minPathSum(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        dp = [[0] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                prev = float('inf')
                if i > 0:
                    prev = min(prev, dp[i - 1][j])
                if j > 0:
                    prev = min(prev, dp[i][j - 1])
                if prev == float('inf'):
                    prev = 0
                dp[i][j] = prev + grid[i][j]
        return dp[m - 1][n - 1]

class Solution:
    def bestClosingTime(self, customers: str) -> int:
        n = len(customers)
        p = [0]
        for c in customers:
            x = 0
            if c == 'Y':
                x = 1
            p.append(p[-1] + x)
        vals = []
        for i in range(n + 1):
            curr = i + p[-1] - 2 * p[i]
            vals.append(curr)
        return vals.index(min(vals))

class Solution:
    def minimumSumSubarray(self, nums: List[int], l: int, r: int) -> int:
        n = len(nums)
        res = float('inf')
        for i in range(n):
            s = 0
            for j in range(i, n):
                s += nums[j]
                if l <= j - i + 1 <= r and s > 0:
                    res = min(res, s)
        if res == float('inf'):
            res = -1
        return res

from collections import defaultdict
from sortedcontainers import SortedList

class SegTree:
    def __init__(self, n):
        self.ctr = defaultdict(int)
        self.init = (float('inf'), n)
        self.vals = defaultdict(lambda: self.init)

    def update(self, i, v, x, y, k = 1):
        if x + 1 == y:
            self.ctr[k] = 0 if v == -1 else 1
            self.vals[k] = (float('inf'), i) if v == -1 else (v, i)
            return
        mid = (x + y) // 2
        if i < mid:
            self.update(i, v, x, mid, 2 * k)
        else:
            self.update(i, v, mid, y, 2 * k + 1)
        self.ctr[k] = self.ctr[2 * k] + self.ctr[2 * k + 1]
        self.vals[k] = min(self.vals[2 * k], self.vals[2 * k + 1])

    def getMin(self, p, x, y, k = 1):
        if p == 0:
            return self.init
        if x + 1 == y:
            return self.vals[k]
        mid = (x + y) // 2
        res = self.init
        if p >= self.ctr[2 * k]:
            res = min(res, self.vals[2 * k], self.getMin(p - self.ctr[2 * k], mid, y, 2 * k + 1))
        else:
            res = min(res, self.getMin(p, x, mid, 2 * k))
        return res

class Solution:
    def minInteger(self, num: str, k: int) -> str:
        n = len(num)
        segtree = SegTree(n)
        for i in range(n):
            segtree.update(i, int(num[i]), 0, n)
        w = k + 1
        res = []
        bst = SortedList()
        while len(res) < n:
            val, j = segtree.getMin(min(w, n), 0, n)
            res.append(num[j])
            pos = j - bst.bisect_right(j - 1)
            bst.add(j)
            w -= pos
            segtree.update(j, -1, 0, n)
        return "".join(res)

class Solution:
    def minProcessingTime(self, processorTime: List[int], tasks: List[int]) -> int:
        processorTime.sort(reverse = True)
        tasks.sort()
        res = 0
        for i in range(len(processorTime)):
            res = max(res, processorTime[i] + tasks[3 + i * 4])
        return res

class Solution:
    def minimumRecolors(self, blocks: str, k: int) -> int:
        n = len(blocks)
        res = float('inf')
        for i in range(n - k + 1):
            ctr = 0
            for j in range(i, i + k):
                if blocks[j] == "W":
                    ctr += 1
            res = min(res, ctr)
        return res

class Solution:
    def minRectanglesToCoverPoints(self, points: List[List[int]], w: int) -> int:
        points.sort()
        prev = float('-inf')
        res = 0
        for x, y in points:
            if x > prev + w:
                res += 1
                prev = x
        return res

class Solution:
    def minRemoveToMakeValid(self, s: str) -> str:
        op = set()
        n = len(s)
        stack = []
        for i in range(n):
            if s[i] == '(':
                stack.append(i)
                op.add(i)
            elif s[i] == ')':
                if len(stack) > 0:
                    stack.pop()
                    op.add(i)
            else:
                op.add(i)
        for i in stack:
            if i in op:
                op.remove(i)
        return "".join(s[i] for i in sorted(op))

import math

class Solution:
    def minimumReplacement(self, nums: List[int]) -> int:
        n = len(nums)
        res = 0
        for i in range(n - 2, -1, -1):
            if nums[i] > nums[i + 1]:
                k = math.ceil(nums[i] / nums[i + 1])
                res += k - 1
                nums[i] //= k
        return res

class Solution:
    def minimumRightShifts(self, nums: List[int]) -> int:
        n = len(nums)
        nums = nums + nums
        for i in range(n):
            if nums[n - i : 2 * n - i] == sorted(nums[n - i : 2 * n - i]):
                return i
        return -1

from collections import Counter

class Solution:
    def minimumRounds(self, tasks: List[int]) -> int:
        rounds = 0
        ctr = Counter(tasks)
        for f in ctr.values():
            found = False
            for i in range(f // 3, -1, -1):
                if (f - 3 * i) % 2 == 0:
                    rounds += i + (f - 3 * i) // 2
                    found = True
                    break
            if not found:
                return -1
        return rounds

class Solution:
    def minimizeSum(self, nums: List[int]) -> int:
        n = len(nums)
        nums.sort()
        res = float('inf')
        for i in [0, 1, n - 2, n - 1]:
            for j in [0, 1, n - 2, n - 1]:
                for x in [i - 1, i + 1]:
                    for y in [j - 1, j + 1]:
                        if 0 <= x < n and 0 <= y < n:
                            oldi = nums[i]
                            oldj = nums[j]
                            nums[i] = nums[x]
                            nums[j] = nums[y]
                            s = sorted(nums)
                            mindiff = min(s[i + 1] - s[i] for i in range(n - 1))
                            res = min(res, s[-1] - s[0] + mindiff)
                            nums[i] = oldi
                            nums[j] = oldj
        return res

from collections import defaultdict

class Solution:
    def DFS(self, graph, i, v):
        for j, d in graph[i]:
            if j not in v:
                v.add(j)
                self.DFS(graph, j, v)

    def minScore(self, n: int, roads: List[List[int]]) -> int:
        res = float('inf')
        graph = defaultdict(set)
        for a, b, d in roads:
            graph[a].add((b, d))
            graph[b].add((a, d))
        v = {1}
        self.DFS(graph, 1, v)
        for a, b, d in roads:
            if a in v and b in v:
                res = min(res, d)
        return res

class Solution:
    def minScoreTriangulation(self, values: List[int]) -> int:
        n = len(values)
        dp = [[float('inf')] * n for _ in range(n)]
        for l in range(n):
            for i in range(n - l):
                if l <= 1:
                    dp[i][i + l] = 0
                for j in range(i, i + l):
                    dp[i][i + l] = min(dp[i][i + l], values[i] * values[j] * values[i + l] + dp[i][j] + dp[j][i + l])
        return dp[0][n - 1]

from collections import defaultdict

class Solution:
    def minimumSeconds(self, nums: List[int]) -> int:
        n = len(nums)
        pos = defaultdict(list)
        for i in range(n):
            pos[nums[i]].append(n + i)
        for el in list(pos):
            beg = pos[el][-1]
            pos[el].insert(0, beg - n)
        res = float('inf')
        for el in pos:
            curr = 0
            m = len(pos[el])
            for i in range(m - 1):
                mid = (pos[el][i] + pos[el][i + 1]) // 2
                curr = max(curr, min(mid - pos[el][i], pos[el][i + 1] - mid))
            res = min(res, curr)
        return res

class Solution:
    def minSizeSubarray(self, nums: List[int], target: int) -> int:
        n = len(nums)
        s = sum(nums)
        res = float('inf')
        l = n * (target // s)
        target %= s
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] += p[i] + nums[i]
        for pref in range(n):
            rem = target - p[pref]
            beg = 0
            end = n - 1
            cextra = float('inf')
            while beg <= end:
                mid = (beg + end) // 2
                if p[n] - p[n - mid] == rem:
                    res = min(res, l + pref + mid)
                if p[n] - p[n - mid] >= rem:
                    end = mid - 1
                else:
                    beg = mid + 1
        last = {}
        for i in range(n + 1):
            prev = p[i] - target
            if prev in last:
                res = min(res, l + i - last[prev])
            last[p[i]] = i
        if res == float('inf'):
            return -1
        return res

class Solution:
    def minSubArrayLen(self, target: int, nums: List[int]) -> int:
        n = len(nums)
        i = 0
        s = 0
        res = n + 1
        for j in range(n):
            s += nums[j]
            while i < j and s - nums[i] >= target:
                s -= nums[i]
                i += 1
            if s >= target:
                res = min(res, j - i + 1)
        if res == n + 1:
            return 0
        return res

class Solution:
    def minWastedSpace(self, packages: List[int], boxes: List[List[int]]) -> int:
        n = len(packages)
        packages.sort()
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] = p[i] + packages[i]
        for box in boxes:
            box.sort()
        res = float('inf')
        for box in boxes:
            choosen = 0
            cost = 0
            for b in box:
                beg = 1
                end = n - choosen
                while beg <= end:
                    mid = (beg + end) // 2
                    if packages[choosen + mid - 1] <= b:
                        beg = mid + 1
                    else:
                        end = mid - 1
                cost += b * (beg - 1) - (p[choosen + beg - 1] - p[choosen])
                choosen += beg - 1
            if choosen != n:
                cost = float('inf')
            res = min(res, cost)
        if res == float('inf'):
            res = -1
        else:
            res %= 10 ** 9 + 7
        return res

import math

class Solution:
    def minSpeedOnTime(self, dist: List[int], hour: float) -> int:
        n = len(dist)
        hour = round(100 * hour)
        def check(x):
            t = 0
            for i in range(n - 1):
                t += 100 * math.ceil(dist[i] / x)
            return t * x + 100 * dist[-1] <= hour * x
        beg = 1
        end = 10 ** 7
        res = -1
        while beg <= end:
            mid = (beg + end) // 2
            if check(mid):
                res = mid
                end = mid - 1
            else:
                beg = mid + 1
        return res

class Solution:
    def minLength(self, s: str) -> int:
        while "AB" in s or "CD" in s:
            while "AB" in s:
                i = s.index("AB")
                s = s[:i] + s[i+2:]
            while "CD" in s:
                i = s.index("CD")
                s = s[:i] + s[i+2:]
        return len(s)

class Solution:
    def minSubsequence(self, nums: List[int]) -> List[int]:
        n = len(nums)
        nums.sort(reverse = True)
        s = sum(nums)
        curr = 0
        for i in range(n):
            curr += nums[i]
            s -= nums[i]
            if curr > s:
                return nums[:i + 1]

from collections import Counter

class Solution:
    def minimumSubstringsInPartition(self, s: str) -> int:
        n = len(s)
        dp = [float('inf')] * (n + 1)
        dp[n] = 0
        for i in range(n - 1, -1, -1):
            j = i
            ctr = Counter()
            ctrctr = Counter()
            while j < n:
                if ctr[s[j]] > 0:
                    ctrctr[ctr[s[j]]] -= 1
                    if ctrctr[ctr[s[j]]] == 0:
                        del ctrctr[ctr[s[j]]]
                ctr[s[j]] += 1
                ctrctr[ctr[s[j]]] += 1
                if len(ctrctr) == 1:
                    dp[i] = min(dp[i], 1 + dp[j + 1])
                j += 1
        return dp[0]

class Solution:
    def minFlips(self, target: str) -> int:
        n = len(target)
        res = 0
        flip = False
        for i in range(n):
            curr = '1' if flip else '0'
            if curr != target[i]:
                res += 1
                flip = not flip
        return res

class Solution:
    def minimumSum(self, num: int) -> int:
        digits = sorted([int(d) for d in str(num)])
        return 10 * (digits[0] + digits[1]) + (digits[2] + digits[3])

class Solution:
    def minimumSum(self, nums: List[int]) -> int:
        n = len(nums)
        res = float('inf')
        pmin = [float('inf')] * (n + 1)
        smin = [float('inf')] * (n + 1)
        for i in range(n):
            pmin[i + 1] = pmin[i]
            smin[i + 1] = smin[i]
            pmin[i + 1] = min(pmin[i + 1], nums[i])
            smin[i + 1] = min(smin[i + 1], nums[n - i - 1])
        for j in range(n):
            l = pmin[j]
            r = smin[n - j - 1]
            if l < nums[j] and r < nums[j]:
                res = min(res, l + nums[j] + r)
        if res == float('inf'):
            return -1
        return res

class Solution:
    def minimumSum(self, nums: List[int]) -> int:
        n = len(nums)
