class Solution:
    def minSumSquareDiff(self, nums1: List[int], nums2: List[int], k1: int, k2: int) -> int:
        n = len(nums1)
        diffs = [abs(nums1[i] - nums2[i]) for i in range(n)]
        beg = 0
        end = max(diffs)
        mindiff = end
        ops = k1 + k2
        while beg <= end:
            mid = (beg + end) // 2
            curr = 0
            for i in range(n):
                curr += max(diffs[i] - mid, 0)
            if curr > ops:
                beg = mid + 1
            else:
                mindiff = mid
                end = mid - 1
        res = 0
        for i in range(n):
            extra = max(diffs[i] - mindiff, 0)
            diffs[i] -= extra
            ops -= extra
        diffs.sort(reverse = True)
        for i in range(n):
            if ops > 0 and diffs[i] > 0:
                diffs[i] -= 1
                ops -= 1
        return sum(el * el for el in diffs)

class Solution:
    def minSwaps(self, nums: List[int]) -> int:
        n = len(nums)
        p = [0]
        k = 0
        for el in nums:
            p.append(p[-1] + el)
            if el == 1:
                k += 1
        res = float('inf')
        for i in range(n):
            if i <= n - k:
                res = min(res, k - p[i + k] + p[i])
            if i <= k:
                res = min(res, p[i + n - k] - p[i])
        return res

from collections import defaultdict

class Solution:
    def gettime(self, graph, curr, prev, hasApple):
        res = 0
        for j in graph[curr]:
            if j != prev:
                currtime = self.gettime(graph, j, curr, hasApple)
                if currtime > 0 or hasApple[j]:
                    res += 2 + currtime
        return res

    def minTime(self, n: int, edges: List[List[int]], hasApple: List[bool]) -> int:
        graph = defaultdict(set)
        for a, b in edges:
            graph[a].add(b)
            graph[b].add(a)
        return self.gettime(graph, 0, -1, hasApple)

class Solution:
    def numTrips(self, time, t):
        trips = 0
        for el in time:
            trips += t // el
        return trips

    def minimumTime(self, time: List[int], totalTrips: int) -> int:
        beg = 1
        end = min(time) * totalTrips
        while beg <= end:
            mid = (beg + end) // 2
            currtrips = self.numTrips(time, mid)
            nexttrips = self.numTrips(time, mid + 1)
            if currtrips < totalTrips and nexttrips >= totalTrips:
                return mid + 1
            elif beg == end:
                return mid
            elif currtrips < totalTrips:
                beg = mid
            else:
                end = mid

class Solution:
    def repairCars(self, ranks: List[int], cars: int) -> int:
        def check(x):
            res = 0
            for r in ranks:
                res += int((x // r) ** 0.5)
            return res
        end = 1
        while check(end) < cars:
            end *= 2
        beg = end // 2
        while beg <= end:
            mid = (beg + end) // 2
            if check(mid) >= cars:
                end = mid - 1
            else:
                beg = mid + 1
        return end + 1

class Solution:
    def minimumTimeToInitialState(self, word: str, k: int) -> int:
        n = len(word)
        dels = 1
        while dels * k < n:
            suff = n - dels * k
            if word[:suff] == word[-suff:]:
                return dels
            dels += 1
        return dels

class Solution:
    def minTimeToType(self, word: str) -> int:
        curr = 'a'
        t = 0
        for c in word:
            d = abs(ord(c) - ord(curr))
            t += min(d, 26 - d)
            curr = c
        return t + len(word)

import heapq
import math

class Solution:
    def minimumTime(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        if grid[0][1] > 1 and grid[1][0] > 1:
            return -1
        time = [[float('inf')] * n for _ in range(m)]
        time[0][0] = 0
        heap = [(0, 0, 0)]
        while heap:
            d, i, j = heapq.heappop(heap)
            if (i, j) == (m - 1, n - 1):
                return d
            for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
                if 0 <= x < m and 0 <= y < n:
                    ntime = d + 1
                    if d + 1 < grid[x][y]:
                        diff = grid[x][y] - d - 1
                        ntime = d + 1 + 2 * math.ceil(diff / 2)
                    if ntime < time[x][y]:
                        time[x][y] = ntime
                        heapq.heappush(heap, (ntime, x, y))
        return -1

