import heapq

class Solution:
    def minimumTime(self, n: int, edges: List[List[int]], disappear: List[int]) -> List[int]:
        graph = [set() for _ in range(n)]
        for u, v, w in edges:
            graph[u].add((v, w))
            graph[v].add((u, w))
        res = [-1] * n
        heap = [(0, 0)]
        dist = [float('inf')] * n
        dist[0] = 0
        while len(heap) > 0:
            d, curr = heapq.heappop(heap)
            if res[curr] == -1:
                res[curr] = d
            for j, w in list(graph[curr]):
                if disappear[j] > d + w and dist[j] > d + w:
                    dist[j] = d + w
                    heapq.heappush(heap, (dist[j], j))
                if disappear[j] <= d + w:
                    graph[curr].remove((j, w))
                    if (curr, w) in graph[j]:
                        graph[j].remove((curr, w))
        return res

class Solution:
    def minTimeToVisitAllPoints(self, points: List[List[int]]) -> int:
        res = 0
        for i in range(len(points) - 1):
            a, b = points[i]
            c, d = points[i + 1]
            x, y = abs(a - c), abs(b - d)
            res += max(x, y)
        return res

class Solution:
    def minimumTotalDistance(self, robot: List[int], factory: List[List[int]]) -> int:
        robot.sort()
        factory.sort(key = lambda p: p[0])
        @lru_cache(maxsize = None)
        def dp(i, j):
            if i >= len(robot):
                return 0
            if j >= len(factory):
                return float('inf')
            res = dp(i, j + 1)
            cost = 0
            for x in range(i, min(i + factory[j][1], len(robot))):
                cost += abs(robot[x] - factory[j][0])
                res = min(res, cost + dp(x + 1, j + 1))
            return res
        return dp(0, 0)

class Solution:
    def minSpaceWastedKResizing(self, nums: List[int], k: int) -> int:
        n = len(nums)
        k += 1
        dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
        for i in range(k + 1):
            dp[n][i] = 0
        for i in range(n - 1, -1, -1):
            for l in range(1, k + 1):
                mval = float('-inf')
                total = 0
                for j in range(i, n):
                    mval = max(mval, nums[j])
                    total += nums[j]
                    dp[i][l] = min(dp[i][l], (j - i + 1) * mval - total + dp[j + 1][l - 1])
        return dp[0][k]

class Solution:
    def minStartValue(self, nums: List[int]) -> int:
        p = 0
        res = 1
        for el in nums:
            p += el
            if p <= 0:
                res = max(res, -p + 1)
        return res

class Solution:
    def minTiles(self, floor: str, numCarpets: int, carpetLen: int, i, n) -> int:
        key = (i, numCarpets)
        if i >= n:
            return 0
        if key in self.cache:
            return self.cache[key]
        if numCarpets <= 0:
            val = floor[i:].count("1")
            self.cache[key] = val
            return val
        a = float('inf')
        if floor[i] == "1":
            a = self.minTiles(floor, numCarpets - 1, carpetLen, i + carpetLen, n)
        b = self.minTiles(floor, numCarpets, carpetLen, i + 1, n)
        if floor[i] == "1":
            b += 1
        val = min(a, b)
        self.cache[key] = val
        return val

    def minimumWhiteTiles(self, floor: str, numCarpets: int, carpetLen: int, i = 0) -> int:
        self.cache = {}
        return self.minTiles(floor, numCarpets, carpetLen, 0, len(floor))

class Solution:
    def minWindow(self, s1: str, s2: str) -> str:
        n = len(s1)
        nxt = [{} for _ in range(n + 1)]
        last = {}
        for i in range(n - 1, -1, -1):
            nxt[i] = dict(last)
            last[s1[i]] = i
        nxt[n] = dict(last)
        res = (0, float('inf'))
        for i in range(n):
            j = i - 1
            for c in s2:
                if c not in nxt[j]:
                    j = float('inf')
                    break
                j = nxt[j][c]
            if j - i + 1 < res[1]:
                res = (i, j - i + 1)
        if res[1] == float('inf'):
            return ""
        return s1[res[0]:res[0]+res[1]]

from collections import Counter

class Solution:
    def minWindow(self, s: str, t: str) -> str:
        n = len(s)
        tctr = Counter()
        for c in t:
            tctr[c] += 1
        ctr = Counter()
        def check(curr):
            for c in tctr:
                if tctr[c] > ctr[c] - int(curr == c):
                    return False
            return True
        reslength = -1
        res = ""
        i = 0
        for j in range(n):
            ctr[s[j]] += 1
            while i < j and check(s[i]):
                ctr[s[i]] -= 1
                i += 1
            if check(-1):
                if reslength == -1 or j - i + 1 < reslength:
                    reslength = j - i + 1
                    res = s[i:j+1]
        return res

class Solution:
    def maxsum(self, nums1, nums2, i, n, mask):
        if i >= n:
            return 0
        key = (i, mask)
        if key in self.cache:
            return self.cache[key]
        res = float('inf')
        for j in range(n):
            if not mask & (1 << j):
                res = min(res, (nums1[i] ^ nums2[j]) + self.maxsum(nums1, nums2, i + 1, n, mask | (1 << j)))
        self.cache[key] = res
        return res

    def minimumXORSum(self, nums1: List[int], nums2: List[int]) -> int:
        self.cache = {}
        return self.maxsum(nums1, nums2, 0, len(nums1), 0)

class Solution:
    def gcd(self, a, b):
        while b:
            a, b = b, a % b
        return a

    def mirrorReflection(self, p: int, q: int) -> int:
        mul = self.gcd(p, q)
        p, q = p // mul, q // mul
        return 1 - p % 2 + q % 2

class Solution:
    def missingNumber(self, nums: List[int]) -> int:
        res = len(nums)
        for i, el in enumerate(nums):
            res ^= el ^ i
        return res

class Solution:
    def modifiedGraphEdges(self, n, edges, source, destination, target):
        INF = 2 * 10 ** 9
        def calculate():
            graph = [[] for _ in range(n)]
            for u, v, w in edges:
                graph[u].append((v, w))
                graph[v].append((u, w))
            heap = [(0, source)]
            dist = [float('inf')] * n
            dist[source] = 0
            while heap:
                d, i = heapq.heappop(heap)
                if i == destination:
                    return d
                for j, w in graph[i]:
                    if dist[j] > d + w:
                        dist[j] = d + w
                        heapq.heappush(heap, (dist[j], j))
            return float('inf')
        mod = set()
        for i in range(len(edges)):
            if edges[i][2] == -1:
                mod.add(i)
        for i in mod:
            edges[i][2] = INF
        curr = calculate()
        if curr == target:
            return edges
        if curr < target:
            return []
        for i in mod:
            edges[i][2] = 1
        if calculate() > target:
            return []
        for i in mod:
            edges[i][2] = INF
        for i in mod:
            edges[i][2] = 1
            curr = calculate()
            if curr <= target:
                edges[i][2] += target - curr
                return edges
        return []

class Solution:
    def modifiedMatrix(self, matrix: List[List[int]]) -> List[List[int]]:
        m = len(matrix)
        n = len(matrix[0])
        cmax = [float('-inf')] * n
        for i in range(m):
            for j in range(n):
                cmax[j] = max(cmax[j], matrix[i][j])
        for i in range(m):
            for j in range(n):
                if matrix[i][j] == -1:
                    matrix[i][j] = cmax[j]
        return matrix

from collections import *

class Solution:
    def monotoneIncreasingDigits(self, n: int) -> int:
        q = deque([0])
        res = 0
        while q:
            curr = q.pop()
            if curr <= n:
                res = max(res, curr)
            for d in range(curr % 10, 10):
                val = 10 * curr + d
                if 0 < val <= n:
                    q.appendleft(val)
        return res

class Solution:
    def isMonotonic(self, nums: List[int]) -> bool:
        n = len(nums)
        grctr = 0
        lsctr = 0
        for i in range(1, n):
            if nums[i] >= nums[i - 1]:
                grctr += 1
            if nums[i] <= nums[i - 1]:
                lsctr += 1
        return grctr == 0 or grctr == n - 1 or lsctr == 0 or lsctr == n - 1

from collections import Counter

class Solution:
    def mostCommonWord(self, paragraph: str, banned: List[str]) -> str:
        banned = set(banned)
        w = []
        ctr = Counter()
        paragraph += " "
        for c in paragraph:
            if c in " !?',;.":
                if len(w) > 0:
                    ctr["".join(w)] += 1
                    w = []
            elif c.isalpha():
                w.append(c.lower())
        for w in sorted(ctr, key = lambda word: -ctr[word]):
            if w not in banned:
                return w

