class Solution:
    def mostFrequent(self, nums: List[int], key: int) -> int:
        n = len(nums)
        ctr = {}
        for i in range(n):
            if nums[i] == key:
                if i < n - 1:
                    ctr[nums[i + 1]] = ctr.get(nums[i + 1], 0) + 1
        return max((v, k) for k, v in ctr.items())[1]

from collections import Counter

def is_prime(n):
    if n < 5 or n & 1 == 0 or n % 3 == 0:
        return 2 <= n <= 3
    s = ((n - 1) & (1 - n)).bit_length() - 1
    d = n >> s
    for a in [2, 325, 9375, 28178, 450775, 9780504, 1795265022]:
        p = pow(a, d, n)
        if p == 1 or p == n - 1 or a % n == 0:
            continue
        for _ in range(s):
            p = (p * p) % n
            if p == n - 1:
                break
        else:
            return False
    return True

class Solution:
    def mostFrequentPrime(self, mat: List[List[int]]) -> int:
        res = (0, -1)
        ctr = Counter()
        m = len(mat)
        n = len(mat[0])
        for i in range(m):
            for j in range(n):
                for dx in range(-1, 2):
                    for dy in range(-1, 2):
                        if dx == dy == 0:
                            continue
                        val = 0
                        x = i
                        y = j
                        while 0 <= x < m and 0 <= y < n:
                            val = 10 * val + mat[x][y]
                            ctr[val] += 1
                            x += dx
                            y += dy
        for el in ctr:
            if el > 10 and is_prime(el):
                res = max(res, (ctr[el], el))
        return res[1]

from collections import Counter

class Solution:
    def mostPopularCreator(self, creators: List[str], ids: List[str], views: List[int]) -> List[List[str]]:
        n = len(creators)
        creatorctr = Counter()
        for i in range(n):
            creatorctr[creators[i]] += views[i]
        mviews = max(creatorctr.values())
        rescreators = set([creators[i] for i in range(n) if creatorctr[creators[i]] == mviews])
        mvideo = {}
        for i in range(n):
            if creators[i] not in mvideo:
                mvideo[creators[i]] = (ids[i], views[i])
            else:
                if views[i] > mvideo[creators[i]][1]:
                    mvideo[creators[i]] = (ids[i], views[i])
                elif views[i] == mvideo[creators[i]][1] and ids[i] < mvideo[creators[i]][0]:
                    mvideo[creators[i]] = (ids[i], views[i])
        return [[c, mvideo[c][0]] for c in rescreators]

class Solution:
    def maxProfitAssignment(self, difficulty: List[int], profit: List[int], worker: List[int]) -> int:
        n = len(difficulty)
        vals = [[difficulty[i], profit[i]] for i in range(n)]
        vals.sort()
        for i in range(1, n):
            vals[i][1] = max(vals[i][1], vals[i - 1][1])
        res = 0
        for w in worker:
            beg = 0
            end = n - 1
            curr = 0
            while beg <= end:
                mid = (beg + end) // 2
                if vals[mid][0] <= w:
                    curr = vals[mid][1]
                    beg = mid + 1
                else:
                    end = mid - 1
            res += curr
        return res

from collections import deque, defaultdict

class Solution:
    def bfs(self, graph, root, parent):
        q = deque([root])
        v = {root}
        while len(q) > 0:
            curr = q.pop()
            for j in graph[curr]:
                if j not in v:
                    v.add(j)
                    parent[j] = curr
                    q.appendleft(j)

    def mostProfitablePath(self, edges: List[List[int]], bob: int, amount: List[int]) -> int:
        n = len(amount)
        graph = defaultdict(set)
        for a, b in edges:
            graph[a].add(b)
            graph[b].add(a)
        parent = {}
        self.bfs(graph, bob, parent)
        curr = 0
        path = [curr]
        while curr in parent:
            curr = parent[curr]
            path.append(curr)
        path.reverse()
        exists = [0]
        for i in range(len(path) - 1):
            exists.append(exists[-1])
            exists[-1] |= 1 << path[i]
        q = deque([(0, 0, 0)])
        v = {0}
        res = float('-inf')
        while len(q) > 0:
            curr, t, cost = q.pop()
            c = amount[curr]
            if t < len(path):
                if path[t] == curr:
                    c //= 2
                elif exists[t] & (1 << curr):
                    c = 0
            if len(graph[curr]) == 1 and curr != 0:
                res = max(res, cost + c)
            for j in graph[curr]:
                if j not in v:
                    v.add(j)
                    q.appendleft((j, t + 1, cost + c))
        return res

