class Solution:
    def DFS(self, curr, stones, rows, cols, v):
        v.add(curr)
        x, y = stones[curr]
        for j in rows[x]:
            if j not in v:
                self.DFS(j, stones, rows, cols, v)
        for j in cols[y]:
            if j not in v:
                self.DFS(j, stones, rows, cols, v)

    def removeStones(self, stones: List[List[int]]) -> int:
        n = len(stones)
        rows = defaultdict(set)
        cols = defaultdict(set)
        for i in range(n):
            x, y = stones[i]
            rows[x].add(i)
            cols[y].add(i)
        res = 0
        v = set()
        for i in range(n):
            if i not in v:
                currv = set()
                self.DFS(i, stones, rows, cols, currv)
                res += len(currv) - 1
                v.update(currv)
        return res

class Solution:
    def getStats(self, s):
        rel = ""
        ctr = 0
        prefl = []
        prefr = []
        for c in s:
            if c != "_":
                rel += c
                if c == "L":
                    prefl.append(ctr)
                else:
                    prefr.append(ctr)
            else:
                ctr += 1
        return [rel, ctr, prefl, prefr]

    def canChange(self, start: str, target: str) -> bool:
        rels, ctrs, sprefl, sprefr = self.getStats(start)
        relt, ctrt, tprefl, tprefr = self.getStats(target)
        if rels != relt or ctrs != ctrt or len(sprefl) != len(tprefl) or len(sprefr) != len(tprefr):
            return False
        m = len(sprefl)
        for i in range(m):
            if tprefl[i] > sprefl[i]:
                return False
        n = len(sprefr)
        for i in range(n):
            if tprefr[i] < sprefr[i]:
                return False
        return True

class Solution:
    def moveZeroes(self, nums: List[int]) -> None:
        nums.sort(key = lambda a: 1 if a == 0 else 0)

class Solution:
    def addStrings(self, num1: str, num2: str) -> str:
        m = len(num1)
        n = len(num2)
        if m < n:
            num1 = "0" * (n - m) + num1
        else:
            num2 = "0" * (m - n) + num2
        carry = 0
        i = max(m, n) - 1
        op = ""
        while i >= 0:
            val = carry + int(num1[i]) + int(num2[i])
            op = str(val % 10) + op
            carry = val // 10
            i -= 1
        if carry > 0:
            op = "1" + op
        return op

    def mulNtimes(self, num, n):
        if n == 0:
            return "0"
        if n == 1:
            return num
        op = "0"
        if n & 1:
            a = num
            b = self.mulNtimes(num, (n - 1) // 2)
            b = self.addStrings(b, b)
            return self.addStrings(a, b)
        else:
            a = self.mulNtimes(num, n // 2)
            return self.addStrings(a, a)

    def multiply(self, num1: str, num2: str) -> str:
        op = "0"
        n = len(num2)
        for i in range(n):
            curr = self.mulNtimes(num1, int(num2[n - i - 1]))
            if curr != "0":
                curr += "0" * i
            op = self.addStrings(op, curr)
        return op

import bisect

class MyCalendar:

    def __init__(self):
        self.startinv = []
        self.endinv = []

    def book(self, start: int, end: int) -> bool:
        i = bisect.bisect_right(self.startinv, (end, start))
        j = bisect.bisect_right(self.endinv, (start, end))
        if i > j:
            return False
        bisect.insort(self.startinv, (start, end))
        bisect.insort(self.endinv, (end, start))
        return True

from collections import *

class LazySegmentTree:
    def __init__(self, default=0, func=max):
        self._default = default
        self._func = func
        self._len = 1 + 10**9
        self._size = _size = 1 << (self._len - 1).bit_length()
        self._lazy = defaultdict(int)
        self.data = defaultdict(int)

    def _push(self, idx):
        q, self._lazy[idx] = self._lazy[idx], 0
        self._lazy[2 * idx] += q
        self._lazy[2 * idx + 1] += q
        self.data[2 * idx] += q
        self.data[2 * idx + 1] += q

    def _update(self, idx):
        for i in reversed(range(1, idx.bit_length())):
            self._push(idx >> i)

    def _build(self, idx):
        idx >>= 1
        while idx:
            self.data[idx] = self._func(self.data[2 * idx], self.data[2 * idx + 1]) + self._lazy[idx]
            idx >>= 1

    def add(self, start, stop, value):
        start = start_copy = start + self._size
        stop = stop_copy = stop + self._size
        while start < stop:
            if start & 1:
                self._lazy[start] += value
                self.data[start] += value
                start += 1
            if stop & 1:
                stop -= 1
                self._lazy[stop] += value
                self.data[stop] += value
            start >>= 1
            stop >>= 1
        self._build(start_copy)
        self._build(stop_copy - 1)

    def query(self, start, stop, default=0):
        start += self._size
        stop += self._size
        self._update(start)
        self._update(stop - 1)
        res = default
        while start < stop:
            if start & 1:
                res = self._func(res, self.data[start])
                start += 1
            if stop & 1:
                stop -= 1
                res = self._func(res, self.data[stop])
            start >>= 1
            stop >>= 1
        return res

class MyCalendarTwo:
    def __init__(self):
        self.seg = LazySegmentTree()

    def book(self, start: int, end: int) -> bool:
        if self.seg.query(start, end) == 2:
            return False
        self.seg.add(start, end, 1)
        return True

from collections import defaultdict

class MyCalendarThree:
    def __init__(self):
        self.tree = defaultdict(lambda: [0, 0])
        self.M = 10 ** 9 + 1

    def update(self, root, start, end, pos, val):
        if start == end:
            self.tree[root][0] += val
            return
        mid = (start + end) // 2
        if pos <= mid:
            self.update(2 * root, start, mid, pos, val)
        else:
            self.update(2 * root + 1, mid + 1, end, pos, val)
        self.tree[root][0] = self.tree[2 * root][0] + self.tree[2 * root + 1][0]
        self.tree[root][1] = max(self.tree[2 * root][1], self.tree[2 * root][0] + self.tree[2 * root + 1][1])

    def book(self, start: int, end: int) -> int:
        self.update(1, 0, self.M, start, 1)
        self.update(1, 0, self.M, end, -1)
        return self.tree[1][1]

