class Solution:
    def preorder(self, root: 'Node') -> List[int]:
        if not root:
            return []
        children = []
        for node in root.children:
            children += self.preorder(node)
        return [root.val] + children

class Solution:
    def getAllPos(self, usedCols, usedPosDiag, usedNegDiag, i, n):
        if i >= n:
            return [[]]
        op = []
        for j in range(n):
            if j not in usedCols and (i + j) not in usedPosDiag and (i - j) not in usedNegDiag:
                val = self.getAllPos(usedCols.union({j}), usedPosDiag.union({i + j}), usedNegDiag.union({i - j}), i + 1, n)
                op += [[j] + v for v in val]
        return op

    def getRow(self, i, n):
        val = ["."] * n
        val[i] = "Q"
        return "".join(val)

    def totalNQueens(self, n: int) -> int:
        queens = self.getAllPos(set(), set(), set(), 0, n)
        return len(queens)

class Solution:
    def repeatedNTimes(self, nums: List[int]) -> int:
        n = len(nums)
        nums.sort()
        i = 0
        while i < n:
            ctr = 1
            while i < n - 1 and nums[i] == nums[i + 1]:
                ctr += 1
                i += 1
            i += 1
            if 2 * ctr == n:
                return nums[i - 1]

class Solution:
    def tribonacci(self, n: int) -> int:
        if n <= 2:
            return [0, 1, 1][n]
        a, b, c = 0, 1, 1
        for _ in range(n - 2):
            a, b, c = b, c, a + b + c
        return c

