            for j in range(i + 1, n):
                if nums2[j] > nums2[i]:
                    greater[nums2[i]] = nums2[j]
                    break
        return [greater.get(num, -1) for num in nums1]

class Solution:
    def nextGreaterElements(self, nums: List[int]) -> List[int]:
        nums += nums
        n = len(nums)
        mpow = [(0, 1)] * (n + 1)
        pw = [1]
        l = 0
        p = 1
        for i in range(1, n + 1):
            if p * 2 <= i:
                l += 1
                p *= 2
                pw.append(p)
            mpow[i] = (l, p)
        cache = {}
        def get(i, x):
            if x == 0:
                return nums[i]
            if (i, x) in cache:
                return cache[(i, x)]
            cache[(i, x)] = max(get(i, x - 1), get(i + pw[x - 1], x - 1))
            return cache[(i, x)]
        def getmax(i, j):
            x, px = mpow[j - i]
            return max(get(i, x), get(j - px, x))
        res = [-1] * (n // 2)
        for i in range(n // 2):
            beg = i
            end = n - 1
            while beg <= end:
                mid = (beg + end) // 2
                if getmax(i, mid + 1) > nums[i]:
                    res[i] = nums[mid]
                    end = mid - 1
                else:
                    beg = mid + 1
        return res

class Solution:
    def nextGreaterElement(self, n: int) -> int:
        digits = [int(c) for c in str(n)]
        k = len(digits)
        i = k - 1
        while i > 0:
            if digits[i - 1] < digits[i]:
                break
            i -= 1
        if i == 0:
            return -1
        closest = i
        for j in range(i, k):
            if digits[j] > digits[i - 1] and digits[j] - digits[i - 1] <= digits[closest] - digits[i - 1]:
                closest = j
        digits[i - 1], digits[closest] = digits[closest], digits[i - 1]
        op = 0
        for d in range(i):
            op = 10 * op + digits[d]
        for d in range(k - 1, i - 1, -1):
            op = 10 * op + digits[d]
        return op if op <= ((1 << 31) - 1) else -1

class SparseTable:
    def __init__(self, arr, func, init):
        self.func = func
        self.init = init
        n = len(arr)
        k = n.bit_length()
        table = [[self.init] * k for _ in range(n)]
        self.mpow = [(0, 1)] * (n + 1)
        l = 0
        p = 1
        for i in range(1, n + 1):
            if p * 2 <= i:
                l += 1
                p *= 2
            self.mpow[i] = (l, p)
        for l in range(k):
            for i in range(n):
                if l == 0:
                    table[i][l] = arr[i]
                else:
                    a = table[i][l - 1]
                    b = self.init
                    if i + (1 << l - 1) < n:
                        b = table[i + (1 << l - 1)][l - 1]
                    table[i][l] = self.func(a, b)
        self.table = table

    def query(self, l, r):
        i, p = self.mpow[r - l + 1]
        return self.func(self.table[l][i], self.table[r - p + 1][i])

class Solution:
    def secondGreaterElement(self, nums: List[int]) -> List[int]:
        n = len(nums)
        sp = SparseTable(nums, func = max, init = float('-inf'))
        s = []
        res = [-1] * n
        for i in range(n):
            while len(s) > 0 and nums[s[-1]] < nums[i]:
                curr = s.pop()
                if i + 1 >= n:
                    continue
                beg = i + 1
                end = n - 1
                while beg <= end:
                    mid = (beg + end) // 2
                    if sp.query(i + 1, mid) > nums[curr]:
                        res[curr] = nums[mid]
                        end = mid - 1
                    else:
                        beg = mid + 1
            s.append(i)
        return res

M1 = 10 ** 9 + 7
M2 = 10 ** 9 + 33
p1 = 10 ** 9 + 9
p2 = 10 ** 9 + 87
pw1 = [1] * 10
pw2 = [1] * 10
for i in range(1, 10):
    pw1[i] = p1 * pw1[i - 1]
    pw2[i] = p2 * pw2[i - 1]
    pw1[i] %= M1
    pw2[i] %= M2

class Solution:
    def find(self, num, i, n, ctr, fhash, shash, tight, curr):
        if i >= n:
            if tight or ctr[0] > 0:
                return float('inf')
            for d in range(1, 10):
                if ctr[d] > 0 and ctr[d] != d:
                    return float('inf')
            return curr
        key = (i, fhash, shash, tight)
        if key in self.cache:
            return self.cache[key]
        mindigit = 0
        if tight:
            mindigit = int(num[i])
        for d in range(mindigit, 10):
            if ctr[d] == d:
                continue
            ctr[d] += 1
            cres = self.find(num, i + 1, n, ctr, (fhash + d * pw1[d]) % M1, (shash + d * pw2[d]) % M2, tight and d == mindigit, 10 * curr + d)
            if cres < float('inf'):
                self.cache[key] = cres
                return cres
            ctr[d] -= 1
        self.cache[key] = float('inf')
        return float('inf')

    def nextBeautifulNumber(self, n: int) -> int:
        self.cache = {}
        a = self.find(str(n), 0, len(str(n)), [0] * 10, 0, 0, True, 0)
        self.cache = {}
        b = self.find(str(10 ** len(str(n))), 0, len(str(10 ** len(str(n)))), [0] * 10, 0, 0, True, 0)
        return min(a, b)

class Solution:
    def nextPermutation(self, nums: List[int]) -> None:
        n = len(nums)
        i = n - 1
        while i > 0 and nums[i - 1] >= nums[i]:
            i -= 1
        if i > 0:
            fn = lambda k: (float('inf') if nums[k] <= nums[i - 1] else nums[k], -k)
            closest = min(range(i, n), key = fn)
            nums[i - 1], nums[closest] = nums[closest], nums[i - 1]
        for p in range((n - i) // 2):
            nums[i + p], nums[n - p - 1] = nums[n - p - 1], nums[i + p]

class Solution:
    def canWinNim(self, n: int) -> bool:
