class Solution:
    def edgeScore(self, edges: List[int]) -> int:
        n = len(edges)
        ctr = [0] * n
        for i in range(n):
            ctr[edges[i]] += i
        return max(range(n), key = lambda i: ctr[i])

class Solution:
    def checkPossibility(self, nums: List[int]) -> bool:
        n = len(nums)
        changed = False
        for i in range(n - 1):
            if nums[i] > nums[i + 1]:
                if changed:
                    return False
                changed = True
                prev = float('-inf')
                if i > 0:
                    prev = nums[i - 1]
                if prev <= nums[i + 1]:
                    nums[i] = prev
                else:
                    nums[i + 1] = nums[i]
        return True

from collections import defaultdict

class Solution:
    def findSubsequences(self, nums: List[int]) -> List[List[int]]:
        n = len(nums)
        graph = defaultdict(set)
        for i in range(n):
            graph[-1].add(i)
            for j in range(i + 1, n):
                if nums[j] >= nums[i]:
                    graph[i].add(j)
        res = set()
        def DFS(graph, i, v, curr):
            if len(curr) >= 2:
                res.add(tuple(curr))
            for j in graph[i]:
                if j not in v:
                    v.add(j)
                    curr.append(nums[j])
                    DFS(graph, j, v, curr)
                    v.remove(j)
                    curr.pop()
        DFS(graph, -1, set(), [])
        return list(res)

class Solution:
    def count(self, s, i, n, tight, lastOne):
        if i >= n:
            return 1
        key = (i, tight, lastOne)
        if key in self.cache:
            return self.cache[key]
        res = 0
        d = 1
        if tight:
            d = int(s[i])
        for j in range(d + 1):
            if not lastOne or j != 1:
                res += self.count(s, i + 1, n, tight and j == d, j == 1)
        self.cache[key] = res
        return res

    def findIntegers(self, n: int) -> int:
        self.cache = {}
        b = "{:0b}".format(n)
        return self.count(b, 0, len(b), True, False)

class Solution:
    def eraseOverlapIntervals(self, intervals: List[List[int]]) -> int:
        intervals.sort(key = lambda x: x[1])
        prev = float('-inf')
        res = len(intervals)
        for a, b in intervals:
            if a >= prev:
                res -= 1
                prev = b
        return res

class Solution:
    def findNthDigit(self, n: int) -> int:
        prevcumsum = None
        cumsum = 0
        l = 1
        while n >= cumsum:
            prevcumsum = cumsum
            nextcumsum = cumsum + 9 * l * (10 ** (l - 1))
            if nextcumsum >= n:
                break
            cumsum = nextcumsum
            l += 1
        n -= prevcumsum
        k, n = divmod(n - 1, l)
        num = str(10 ** (l - 1) + k)
        return int(num[n])

class Solution:
    def nthMagicalNumber(self, n: int, a: int, b: int) -> int:
        M = 10 ** 9 + 7
        def gcd(a, b):
            while b:
                a, b = b, a % b
            return a
        def count(x):
            return x // a + x // b - x // ((a * b) // gcd(a, b))
        beg = end = 1
        while count(end) <= n:
            end *= 2
        res = end
        while beg <= end:
            mid = (beg + end) // 2
            if count(mid) >= n:
                res = mid % M
                end = mid - 1
            else:
                beg = mid + 1
        return res

class Solution:
    def findComplement(self, num: int) -> int:
        return int("".join([str(1 - int(c)) for c in "{:b}".format(num)]), 2)

class Solution:
    def hammingWeight(self, n: int) -> int:
        if n == 0:
            return 0
        return (n & 1) + self.hammingWeight(n >> 1)

class Solution:
    def colorTheArray(self, n: int, queries: List[List[int]]) -> List[int]:
        vals = [0] * n
        for i in range(n):
            vals[i] = -(i + 1)
        res = []
        curr = 0
        for i, c in queries:
            if i > 0 and vals[i] == vals[i - 1]:
                curr -= 1
            if i < n - 1 and vals[i] == vals[i + 1]:
                curr -= 1
            vals[i] = c
            if i > 0 and vals[i] == vals[i - 1]:
                curr += 1
            if i < n - 1 and vals[i] == vals[i + 1]:
                curr += 1
            res.append(curr)
        return res

class Solution:
    def arithmeticTriplets(self, nums: List[int], diff: int) -> int:
        n = len(nums)
        res = 0
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    if nums[k] - nums[j] == diff and nums[j] - nums[i] == diff:
                        res += 1
        return res

from collections import *

class Solution:
    def countOfAtoms(self, formula: str) -> str:
        n = len(formula)
        cnt = lambda x: str(x) if x > 1 else ""
        rnd = 2
        def tokentype(x):
            nonlocal rnd
            if x.isalpha() and x.isupper():
                rnd += 1
                return rnd
            if x.isalpha() and x.islower():
                return 1
            if x.isdigit():
                return 2
            if x == '(':
                rnd += 1
                return rnd
            rnd += 1
            return rnd
        tokens = []
        i = 0
        while i < n:
            ctr = 1
            while i < n - 1 and tokentype(formula[i]) == tokentype(formula[i + 1]):
                ctr += 1
                i += 1
            if tokentype(formula[i]) == 1:
                tokens.append(tokens.pop() + formula[i-ctr+1:i+1])
            elif tokentype(formula[i]) == 2:
                tokens.append(int(formula[i-ctr+1:i+1]))
            else:
                tokens.append(formula[i-ctr+1:i+1])
            i += 1
        stack = [Counter()]
        i = 0
        def next():
            if i >= len(tokens):
                return False
            return True
        def peek():
            return tokens[i]
        def consume():
            nonlocal i
            i += 1
            return tokens[i - 1]
        while next():
            curr = consume()
            if curr == '(':
                stack.append(Counter())
            elif curr == ')':
                mul = 1
                if next() and str(peek()).isdigit():
                    mul = consume()
                for x in stack[-1]:
                    stack[-1][x] *= mul
                if len(stack) > 1:
                    x = stack.pop()
                    stack[-1] += x
            elif str(curr).isalpha():
                atom = curr
                mul = 1
                if next() and str(peek()).isdigit():
                    mul = consume()
                stack[-1] += Counter({atom: mul})
        while len(stack) > 1:
            x = stack.pop()
            stack[-1] += x
        res = stack.pop()
        return "".join(f"{atom}{cnt(res[atom])}" for atom in sorted(res))

class Solution:
    def count(self, num, i, n, tight, nzseen, mod, k, diff, cache):
        if i >= n:
            return int(mod == 0 and diff == 0)
        key = (i, tight, nzseen, mod, diff)
        if key in cache:
            return cache[key]
        maxd = 9
        if tight:
            maxd = int(num[i])
        res = 0
        for d in range(maxd + 1):
            newnzseen = nzseen or d != 0
            newdiff = diff
            if newnzseen:
                if d & 1:
                    newdiff += 1
                else:
                    newdiff -= 1
            res += self.count(num, i + 1, n, tight and d == maxd, newnzseen, (10 * mod + d) % k, k, newdiff, cache)
        cache[key] = res
        return res

    def numberOfBeautifulIntegers(self, low: int, high: int, k: int) -> int:
        return self.count(str(high), 0, len(str(high)), True, False, 0, k, 0, {}) - self.count(str(low - 1), 0, len(str(low - 1)), True, False, 0, k, 0, {})

class Solution:
    def countBeautifulPairs(self, nums: List[int]) -> int:
        def gcd(a, b):
            while b:
                a, b = b, a % b
            return a
        n = len(nums)
        res = 0
        for i in range(n):
            for j in range(i + 1, n):
                a = nums[i]
                while a >= 10:
                    a //= 10
                b = nums[j] % 10
                if gcd(a, b) == 1:
                    res += 1
        return res

class Solution:
    def beautifulPartitions(self, s: str, k: int, minLength: int) -> int:
        M = 10 ** 9 + 7
        n = len(s)
        primes = "2357"
        isPrime = False
        isComp = False
        for c in s:
            if c in primes:
                isPrime = True
            else:
                isComp = True
        if not isPrime or not isComp:
            return 0
        dp = [[0] * (k + 1) for _ in range(n + 1)]
        dp[n][0] = 1
        primesum = [[0] for _ in range(k + 1)]
        primesum[0][0] = 1
        for i in range(n - 1, -1, -1):
            if s[i] in primes:
                for l in range(1, k + 1):
                    if minLength <= len(primesum[l - 1]):
                        dp[i][l] += primesum[l - 1][-minLength]
            for l in range(k + 1):
                val = 0
                if s[i] in primes and (i == 0 or s[i - 1] not in primes):
                    val = dp[i][l]
                primesum[l].append(primesum[l][-1] + val)
        return dp[0][k] % M

class Solution:
    def minChanges(self, n: int, k: int) -> int:
        res = 0
        for b in range(32):
            if k & (1 << b) and not n & (1 << b):
                return -1
            if n & (1 << b) and not k & (1 << b):
                res += 1
        return res

class Solution:
    def countBlackBlocks(self, m: int, n: int, coordinates: List[List[int]]) -> List[int]:
        res = [0] * 5
        res[0] = (m - 1) * (n - 1)
        cc = {}
        for a, b in coordinates:
            cc[(a, b)] = 1
        v = set()
        for a, b in coordinates:
            for dx in range(-1, 1):
                for dy in range(-1, 1):
                    if (a + dx, b + dy) in v:
                        continue
                    v.add((a + dx, b + dy))
                    curr = 0
                    total = 0
                    for x in range(a + dx, a + dx + 2):
                        for y in range(b + dy, b + dy + 2):
                            if 0 <= x < m and 0 <= y < n:
                                total += 1
                                curr += cc.get((x, y), 0)
                    if total == 4:
                        res[curr] += 1
                        res[0] -= 1
        return res

class Solution:
    def DFS(self, grid, i, j, m, n):
        if i >= 0 and j >= 0 and i < m and j < n and grid[i][j] == 0:
            if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                self.isBoundary = True
            grid[i][j] = 1
            for x, y in [(i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)]:
                self.DFS(grid, x, y, m, n)

    def closedIsland(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        ctr = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 0:
                    self.isBoundary = False
                    self.DFS(grid, i, j, m, n)
                    if not self.isBoundary:
                        ctr += 1
        return ctr

class Solution:
    def commonFactors(self, a: int, b: int) -> int:
        k = min(a, b)
        res = 0
        for i in range(1, k + 1):
            if a % i == 0 and b % i == 0:
                res += 1
        return res

class Solution:
    def numRollsToTarget(self, n: int, k: int, target: int) -> int:
        M = 10 ** 9 + 7
        @lru_cache(maxsize = None)
        def count(rem, x):
            if rem < 0:
                return 0
            if x == 0:
                return int(rem == 0)
            res = 0
            for i in range(1, k + 1):
                res += count(rem - i, x - 1)
                res %= M
            return res
        return count(target, n)

MX = 200000
v = [False] * (MX + 1)
f = [[] for _ in range(MX + 1)]
for i in range(1, MX + 1):
