class Solution:
    @cache
    def gcd(self, a, b):
        if b == 0:
            return a
        return self.gcd(b, a % b)

    def countDifferentSubsequenceGCDs(self, nums: List[int]) -> int:
        M = max(nums)
        for x in nums:
            v[x] = True
        res = 0
        cand = set()
        for el in nums:
            for c in f[el]:
                cand.add(c)
        for g in cand:
            mul = 1
            currgcd = 0
            while g * mul <= M:
                if v[g * mul]:
                    currgcd = self.gcd(currgcd, mul)
                mul += 1
            if currgcd == 1:
                res += 1
        for x in nums:
            v[x] = False
        return res

class Solution:
    def digitone(self, curr, i, n, val, tight, cache):
        if i >= n:
            return curr
        key = (curr, i, tight)
        if key in cache:
            return cache[key]
        res = 0
        maxd = 9
        if tight:
            maxd = int(val[i])
        for d in range(maxd + 1):
            currtight = False
            if d == maxd:
                currtight = tight
            x = 0
            if d == 1:
                x += 1
            res += self.digitone(curr + x, i + 1, n, val, currtight, cache)
        if not tight:
            cache[key] = res
        return res

    def countDigitOne(self, n: int) -> int:
        val = str(n)
        l = len(val)
        return self.digitone(0, 0, l, val, True, {})

class Solution:
    def distinctAverages(self, nums: List[int]) -> int:
        n = len(nums)
