class Solution:
    def dfs(self, grid, i, j, m, n, visited):
        visited.add((i, j))
        grid[i][j] = 0
        for x, y in [(i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)]:
            if 0 <= x < m and 0 <= y < n and grid[x][y] == 1 and (x, y) not in visited:
                self.dfs(grid, x, y, m, n, visited)

    def numEnclaves(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        boundary = set()
        for i in range(m):
            boundary.add((i, 0))
            boundary.add((i, n - 1))
        for i in range(n):
            boundary.add((0, i))
            boundary.add((m - 1, i))
        globalvisited = set()
        ctr = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    currvisited = set()
                    self.dfs(grid, i, j, m, n, currvisited)
                    if len(set.intersection(currvisited, boundary)) == 0:
                        ctr += len(currvisited)
        return ctr

class Solution:
    def numEquivDominoPairs(self, dominoes: List[List[int]]) -> int:
        n = len(dominoes)
        ctr = {}
        for i in range(n):
            curr = tuple(sorted(dominoes[i]))
            ctr[curr] = ctr.get(curr, 0) + 1
        op = 0
        for pair in ctr:
            op += ctr[pair] * (ctr[pair] - 1) // 2
        return op

class Solution:
    def evenOddBit(self, n: int) -> List[int]:
        even = odd = 0
        for b in range(32):
            if n & (1 << b):
                if b & 1:
                    odd += 1
                else:
                    even += 1
        return [even, odd]

