from sortedcontainers import SortedList

class Solution:
    def countPairs(self, root: TreeNode, distance: int) -> int:
        res = 0
        def dfs(r, d):
            nonlocal res
            leaf = True
            curr = SortedList()
            for c in [r.left, r.right]:
                if not c:
                    continue
                leaf = False
                ncurr = dfs(c, d + 1)
                if len(ncurr) > len(curr):
                    curr, ncurr = ncurr, curr
                for x in ncurr:
                    res += curr.bisect_right(distance + 2 * d - x)
                while ncurr:
                    x = ncurr.pop(0)
                    curr.add(x)
            if leaf:
                curr.add(d)
            return curr
        dfs(root, 0)
        return res

class Solution:
    def numIdenticalPairs(self, nums: List[int]) -> int:
        n = len(nums)
        valIndexes = {}
        total = 0
        for i in range(n):
            valIndexes[nums[i]] = valIndexes.get(nums[i], 0) + 1
        for val in valIndexes:
            freq = valIndexes[val]
            total += freq * (freq - 1) // 2
        return total

from sortedcontainers import SortedList

class Solution:
    def numberOfGoodPaths(self, vals: List[int], edges: List[List[int]]) -> int:
        n = len(edges) + 1
        graph = [set() for _ in range(n)]

        for u, v in edges:
            graph[u].add(v)
            graph[v].add(u)
        sizes = [0] * n

        def dfs(i, prev):
            sizes[i] = 1
            for j in graph[i]:
                if j != prev:
                    sizes[i] += dfs(j, i)
            return sizes[i]

        def getcentroid(i, prev, total):
            for j in graph[i]:
                if j != prev and sizes[j] > total // 2:
                    return getcentroid(j, i, total)
            return i

        def solve(i):
            total = dfs(i, -1)
            centroid = getcentroid(i, -1, total)
            ctr = defaultdict(SortedList)

            res = 1

            def find(x, prev, mx, store):
                nonlocal ctr, res
                if not store and vals[x] == vals[centroid] and mx <= vals[x]:
                    res += 1
                if x != centroid and store and mx <= vals[x]:
                    ctr[vals[x]].add(mx)
                elif x != centroid and mx <= vals[x]:
                    res += ctr[vals[x]].bisect_right(mx)
                for y in graph[x]:
                    if y != prev:
                        find(y, x, max(mx, vals[y]), store)

            for j in graph[centroid]:
                mx = max(vals[centroid], vals[j])
                find(j, centroid, mx, False)
                find(j, centroid, mx, True)

            for j in list(graph[centroid]):
                graph[centroid].remove(j)
                graph[j].remove(centroid)
                res += solve(j)

            return res

        return solve(0)

from collections import Counter

class Solution:
    def numSplits(self, s: str) -> int:
        right = Counter(s)
        left = Counter()
        lctr = 0
        rctr = len(right)
        res = 0
        for c in s:
            if left[c] == 0:
                lctr += 1
            left[c] += 1
            if right[c] == 1:
                rctr -= 1
            right[c] -= 1
            if lctr == rctr:
                res += 1
        return res

class Solution:
    def countPartitions(self, nums: List[int], k: int) -> int:
        M = 10 ** 9 + 7
        s = sum(nums)
        if k >= s - k:
            return 0
        fc = {}
        def countf(i, s):
            if s >= k:
                return 0
            if i >= len(nums):
                return 1
            if (i, s) in fc:
                return fc[(i, s)]
            res = countf(i + 1, s + nums[i]) + countf(i + 1, s)
            res %= M
            fc[(i, s)] = res
            return res
        res = 2 * countf(0, 0)
        res = pow(2, len(nums), M) - res
        res %= M
        return res

class Solution:
    def find(self, i, j):
        if self.parent[i][j] == -1:
            return (i, j)
        self.parent[i][j] = self.find(self.parent[i][j][0], self.parent[i][j][1])
        return self.parent[i][j]

    def union(self, a, b, c, d):
        xa, ya = self.find(a, b)
        xb, yb = self.find(c, d)
        if (xa, ya) != (xb, yb):
            self.parent[xb][yb] = (xa, ya)

    def numIslands(self, grid: List[List[str]]) -> int:
        m = len(grid)
        n = len(grid[0])
        self.parent = [[-1] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                if grid[i][j] == "1":
                    for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
                        if 0 <= x < m and 0 <= y < n and grid[x][y] == "1":
                            self.union(i, j, x, y)
        res = set()
        for i in range(m):
            for j in range(n):
                if grid[i][j] == "1":
                    res.add(self.find(i, j))
        return len(res)

class Solution:
    def numberOfBeams(self, bank: List[str]) -> int:
        bank = [b.count("1") for b in bank if b.count("1") != 0]
        val = 0
        n = len(bank)
        for i in range(n - 1):
            val += bank[i] * bank[i + 1]
        return val

class Solution:
    def findNumberOfLIS(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [0] * n
        dp[n - 1] = (1, 1)
        maxlen = 0
        maxctr = 0
        for i in range(n - 1, -1, -1):
            mlen = 0
            mctr = 0
            found = False
            for j in range(i + 1, n):
                if nums[j] > nums[i]:
                    found = True
                    l, ctr = dp[j]
                    if l > mlen:
                        mlen = l
                        mctr = ctr
                    elif l == mlen:
                        mctr += ctr
            if not found:
                mctr += 1
            dp[i] = (1 + mlen, mctr)
            if 1 + mlen > maxlen:
                maxlen = 1 + mlen
                maxctr = mctr
            elif 1 + mlen == maxlen:
                maxctr += mctr
        return maxctr

class Solution:
    def numMatchingSubseq(self, s: str, words: List[str]) -> int:
        n = len(s)
        last = {}
        nextpos = [None] * (n + 1)
        nextpos[n] = {}
        for i in range(n - 1, -1, -1):
            last[s[i]] = i
            nextpos[i] = dict(last)
        res = 0
        for w in words:
            prev = -1
            res += 1
            for c in w:
                if c in nextpos[prev + 1]:
                    prev = nextpos[prev + 1][c]
                else:
                    res -= 1
                    break
        return res

M = 10 ** 9 + 7

class Solution:
    def numMusicPlaylists(self, n: int, goal: int, k: int) -> int:
        dp = [[0] * (n + 1) for _ in range(goal + 1)]
        dp[0][0] = 1
        for i in range(1, goal + 1):
            for j in range(1, n + 1):
                if j > i:
                    continue
                dp[i][j] = dp[i - 1][j - 1] * (n - j + 1)
                if j > k:
                    dp[i][j] += dp[i - 1][j] * (j - k)
                dp[i][j] %= M
        return dp[goal][n]

from collections import defaultdict

class Solution:
    def DFS(self, graph, i, v):
        for j in graph[i]:
            self.edges.add((min(i, j), max(i, j)))
            if j not in v:
                v.add(j)
                self.DFS(graph, j, v)

    def makeConnected(self, n: int, connections: List[List[int]]) -> int:
        graph = defaultdict(set)
        for a, b in connections:
            graph[a].add(b)
            graph[b].add(a)
        ctr = 0
        extra = 0
        v = set()
        for i in range(n):
            if i not in v:
                ctr += 1
                currv = {i}
                self.edges = set()
                self.DFS(graph, i, currv)
                extra += len(self.edges) - len(currv) + 1
                v.update(currv)
        if extra < ctr - 1:
            return -1
        return ctr - 1

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

class Solution:
    def interchangeableRectangles(self, rectangles: List[List[int]]) -> int:
        res = 0
        ctr = {}
        for w, h in rectangles:
            mul = gcd(w, h)
            w //= mul
            h //= mul
            res += ctr.get((w, h), 0)
            ctr[(w, h)] = ctr.get((w, h), 0) + 1
        return res

from collections import Counter

class Solution:
    def numOfPairs(self, nums: List[str], target: str) -> int:
        k = len(target)
        nums = Counter(nums)
        ctr = 0
        for num in nums:
            if target.startswith(num):
                chunk = target[len(num) - k:]
                if chunk in nums:
                    ctr += nums[num] * nums[chunk]
                    if num == chunk:
                        ctr -= nums[chunk]
        return ctr

class Solution:
    def pathsWithMaxScore(self, board: List[str]) -> List[int]:
        M = 10 ** 9 + 7
        n = len(board)
        @lru_cache(maxsize = None)
        def dp(i, j):
            if (i, j) == (0, 0):
                return [0, 1]
            res = [float('-inf'), 0]
            for x, y in [(i - 1, j), (i, j - 1), (i - 1, j - 1)]:
                if x >= 0 and y >= 0 and board[x][y] != 'X':
                    nb = dp(x, y)
                    score = int(board[i][j] if board[i][j] not in 'ES' else 0) + nb[0]
                    if score == res[0]:
                        res[1] += nb[1]
                    elif score > res[0]:
                        res[0] = score
                        res[1] = nb[1]
            return [res[0] % M if res[0] != float('-inf') else res[0], res[1] % M]
        res = dp(n - 1, n - 1)
        if res[0] == float('-inf'):
            res[0] = 0
        return res

class Solution:
    def numberOfSets(self, n: int, maxDistance: int, roads: List[List[int]]) -> int:
        res = 0
        for mask in range(1 << n):
            dist = [[float('inf')] * n for _ in range(n)]
            for u, v, w in roads:
                if not mask & (1 << u) and not mask & (1 << v):
                    dist[u][v] = dist[v][u] = min(dist[u][v], dist[v][u], w)
            for j in range(n):
                if not mask & (1 << j):
                    dist[j][j] = 0
                for i in range(n):
                    for k in range(n):
                        dist[i][k] = min(dist[i][k], dist[i][j] + dist[j][k])
            valid = True
            for i in range(n):
                for j in range(n):
                    if not mask & (1 << i) and not mask & (1 << j) and dist[i][j] > maxDistance:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                res += 1
        return res

from collections import defaultdict

class Solution:
    def DFS(self, i, graph, v):
        v.add(i)
        for j in graph[i]:
            if j not in v:
                self.DFS(j, graph, v)

    def findCircleNum(self, isConnected: List[List[int]]) -> int:
        n = len(isConnected)
        graph = defaultdict(list)
        for i in range(n):
            for j in range(n):
                if i != j and isConnected[i][j] == 1:
                    graph[i].append(j)
                    graph[j].append(i)
        v = set()
        ctr = 0
        for i in range(n):
            if i not in v:
                self.DFS(i, graph, v)
                ctr += 1
        return ctr

