class Solution:
    def countShips(self, sea: 'Sea', topRight: 'Point', bottomLeft: 'Point') -> int:
        res = 0
        x, y = bottomLeft.x, bottomLeft.y
        while x <= topRight.x and y <= topRight.y:
            found = False
            beg = x
            end = topRight.x
            newx = topRight.x + 1
            while beg <= end:
                mid = (beg + end) // 2
                if sea.hasShips(Point(mid, topRight.y), Point(x, bottomLeft.y)):
                    found = True
                    newx = mid + 1
                    end = mid - 1
                else:
                    beg = mid + 1
            beg = y
            end = topRight.y
            newy = topRight.y + 1
            while beg <= end:
                mid = (beg + end) // 2
                if sea.hasShips(Point(topRight.x, mid), Point(bottomLeft.x, y)):
                    found = True
                    newy = mid + 1
                    end = mid - 1
                else:
                    beg = mid + 1
            if found:
                res += 1
            x = newx
            y = newy
        return res

class Solution:
    def deslen(self, prices, i, n):
        if i in self.cache:
            return self.cache[i]
        if i == n - 1 or prices[i] - prices[i + 1] != 1:
            self.cache[i] = 1
            return 1
        val = 1 + self.deslen(prices, i + 1, n)
        self.cache[i] = val
        return val

    def getDescentPeriods(self, prices: List[int]) -> int:
        n = len(prices)
        self.cache = {}
        ctr = 0
        for i in range(n):
            ctr += self.deslen(prices, i, n)
        return ctr

class Solution:
    def numSteps(self, s: str) -> int:
        val = 0
        for c in s:
            val = 2 * val + int(c)
        res = 0
        while val > 1:
            if val & 1:
                val += 1
            else:
                val //= 2
            res += 1
        return res

class Solution:
    def numberOfSteps(self, num: int) -> int:
        steps = 0
        while num > 0:
            if num & 1:
                num = (num - 1) // 2
                steps += 1 if num == 0 else 2
            else:
                num = num // 2
                steps += 1
        return steps

