M = 10 ** 9 + 7

class Solution:
    def stringCount(self, n: int) -> int:
        dp = [defaultdict(lambda: 0) for _ in range(n + 1)]
        dp[n][(1, 2, 1)] = 1
        for i in range(n - 1, -1, -1):
            for l in range(2):
                for e in range(3):
                    for t in range(2):
                        dp[i][(l, e, t)] += dp[i + 1][(min(l + 1, 1), e, t)] + dp[i + 1][(l, min(e + 1, 2), t)] + dp[i + 1][(l, e, min(t + 1, 1))]
                        dp[i][(l, e, t)] += 23 * dp[i + 1][(l, e, t)]
                        dp[i][(l, e, t)] %= M
        return dp[i][(0, 0, 0)]

from collections import deque

class Solution:
    def countStudents(self, students: List[int], sandwiches: List[int]) -> int:
        s = deque(students)
        sw = deque(sandwiches)
        ss = sum(s)
        while s:
            if s[0] == sw[0]:
                ss -= s.popleft()
                sw.popleft()
            else:
                s.append(s.popleft())
                if ss == 0 or ss == len(s):
                    break
        return len(s)

class Solution:
    def numOfSubarrays(self, arr: List[int], k: int, threshold: int) -> int:
        n = len(arr)
        total = 0
        res = 0
        for i in range(n):
            total += arr[i]
            if i >= k:
                total -= arr[i - k]
            if i >= k - 1:
                if total >= threshold * k:
                    res += 1
        return res

class Solution:
    def numOfSubarrays(self, arr: List[int]) -> int:
        z = 1
        o = 0
        p = 0
        res = 0
        for el in arr:
            p = (p + el) % 2
            if p == 0:
                res += o
                z += 1
            else:
                res += z
                o += 1
        return res % (10 ** 9 + 7)

def compute_lps(pattern):
    length = 0
    lps = [0] * len(pattern)
    i = 1

    while i < len(pattern):
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1

    return lps

def find_pattern_indices(string, pattern):
    indices = []
    n = len(string)
    m = len(pattern)
    lps = compute_lps(pattern)
    i = j = 0

    while i < n:
        if string[i] == pattern[j]:
            i += 1
            j += 1

            if j == m:
                indices.append(i - j)
                j = lps[j - 1]
        else:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return indices

