def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

class Solution:
    def count(self, nums, k):
        q = Queue(0, gcd)
        res = 0
        for el in nums:
            q.push(el)
            while not q.empty() and q.funcval() <= k:
                q.pop()
            res += q.size()
        return res

    def subarrayGCD(self, nums: List[int], k: int) -> int:
        return self.count(nums, k - 1) - self.count(nums, k)

class Solution:
    def gcd(self, a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(self, a, b):
        return a * b // self.gcd(a, b)

    def subarrayLCM(self, nums: List[int], k: int) -> int:
        n = len(nums)
        res = 0
        for i in range(n):
            lcm = 1
            for j in range(i, n):
                lcm = self.lcm(lcm, nums[j])
                if lcm == k:
                    res += 1
        return res

from collections import defaultdict

class Solution:
    def numSubmatrixSumTarget(self, matrix: List[List[int]], target: int) -> int:
        m = len(matrix)
        n = len(matrix[0])
        res = 0
        prefix = [[0] * (n + 1) for _ in range(m)]
        for i in range(m):
            for j in range(n):
                prefix[i][j + 1] = prefix[i][j] + matrix[i][j]
        for i in range(n):
            for j in range(i, n):
                seen = defaultdict(int)
                curr = 0
                seen[0] = 1
                for k in range(m):
                    curr += prefix[k][j + 1] - prefix[k][i]
                    if curr - target in seen:
                        res += seen[curr - target]
                    seen[curr] += 1
        return res

class Solution:
    def subsequenceCount(self, nums: List[int]) -> int:
        M = 10 ** 9 + 7
        n = len(nums)
        o = e = 0
        for el in nums:
            if el & 1:
                o += 1
            else:
                e += 1
        if o == 0:
            return 0
        return pow(2, o + e - 1, M)

class Solution:
    def numSub(self, s: str) -> int:
        M = 10 ** 9 + 7
        n = len(s)
        res = 0
        i = 0
        while i < n:
            ctr = 1
            while i < n - 1 and s[i] == s[i + 1]:
                i += 1
                ctr += 1
            if s[i] == '1':
                res = (res + ctr * (ctr + 1) // 2) % M
            i += 1
        return res

class Solution:
    def numberOfUniqueGoodSubsequences(self, binary: str) -> int:
        M = 10 ** 9 + 7
        n = len(binary)
        dp = [1] * (n + 1)
        prev = {}
        zerozero = False
        zeroone = False
        for i in range(1, n + 1):
            dp[i] = 2 * dp[i - 1]
            if binary[i - 1] in prev:
                dp[i] -= dp[prev[binary[i - 1]]]
            if "0" in prev:
                if binary[i - 1] == "0" and not zerozero:
                    dp[i] -= 1
                    zerozero = True
                if binary[i - 1] == "1" and not zeroone:
                    dp[i] -= 1
                    zeroone = True
            dp[i] %= M
            prev[binary[i - 1]] = i - 1
        dp[n] = (M + dp[n] - 1) % M
        return dp[n]

class Solution:
    def uniqueXorTriplets(self, nums: List[int]) -> int:
        n = len(nums)
        res = [1,2,4]
        p = 8
        while len(res) < n:
            res.extend([p] * (p // 2))
            p *= 2
        return res[n - 1]

class Solution:
    def uniqueXorTriplets(self, nums: List[int]) -> int:
        n = len(nums)
        s = {nums[i] ^ nums[j] for i in range(n) for j in range(i, n)}
        return len({el ^ x for el in set(nums) for x in s})

class Solution:
    def countTime(self, time: str) -> int:
        hres = 0
        mres = 0
        h = time[0:2]
        m = time[3:5]
        for i in range(24):
            s = "0" * (1 if i < 10 else 0) + str(i)
            match = True
            for j in range(2):
                if h[j] != '?' and s[j] != h[j]:
                    match = False
                    break
            if match:
                hres += 1
        for i in range(60):
            s = "0" * (1 if i < 10 else 0) + str(i)
            match = True
            for j in range(2):
                if m[j] != '?' and s[j] != m[j]:
                    match = False
                    break
            if match:
                mres += 1
        return hres * mres

class Solution:
    def validSubarrays(self, nums: List[int]) -> int:
        n = len(nums)
        stack = []
        r = [n] * n
        for i in range(n):
            while stack and nums[i] < nums[stack[-1]]:
                r[stack.pop()] = i
            stack.append(i)
        return sum(r[i] - i for i in range(n))

from collections import Counter

class Solution:
    def findNumOfValidWords(self, words: List[str], puzzles: List[str]) -> List[int]:
        ctr = Counter()
        for w in words:
            mask = 0
            for c in w:
                mask |= 1 << (ord(c) - ord('a'))
            ctr[mask] += 1
        res = []
        for w in puzzles:
            REQ = (1 << (ord(w[0]) - ord('a')))
            curr = 0
            mask = 0
            for c in w:
                mask |= 1 << (ord(c) - ord('a'))
            s = mask
            while s:
                if s & REQ:
                    curr += ctr[s]
                s = (s - 1) & mask
            res.append(curr)
        return res

class Solution:
    def canSeePersonsCount(self, heights: List[int]) -> List[int]:
        n = len(heights)
        prevhigher = [-1] * n
        nexthigher = [n] * n
        stack = []
        for i in range(n):
            while len(stack) > 0 and heights[stack[-1]] < heights[i]:
                curr = stack.pop()
                nexthigher[curr] = i
            if len(stack) > 0:
                prevhigher[i] = stack[-1]
            stack.append(i)
        res = [0] * n
        ctr = [0] * n
        for i in range(n - 1, -1, -1):
            res[i] = ctr[i]
            if nexthigher[i] != n:
                res[i] += 1
            if prevhigher[i] != -1:
                ctr[prevhigher[i]] += 1
        return res

M = 10 ** 9 + 7

class Solution:
    def getSum(self, i, j):
        if i < 0 or j < 0:
            return 0
        if self.qsum[i][j] != None:
            return self.qsum[i][j]
        prev = self.getSum(i - 1, j - 1)
        row = self.getSum(i - 1, j)
        col = self.getSum(i, j - 1)
        res = row + col - prev
        if self.pizza[i][j] == 'A':
            res += 1
        self.qsum[i][j] = res
        return res

    def numapples(self, i, j, m, n) -> int:
        c = self.getSum(i + m - 1, j + n - 1)
        l = self.getSum(i + m - 1, j - 1)
        t = self.getSum(i - 1, j + n - 1)
        s = self.getSum(i - 1, j - 1)
        return c - l - t + s

    def count(self, i, j, m, n, rem):
        if m == 0 or n == 0 or rem == 0:
            return 1
        key = (i, j, m, n, rem)
        if key in self.cache:
            return self.cache[key]
        res = 0
        for l in range(1, m):
            if self.numapples(i, j, l, n) > 0 and self.numapples(i + l, j, m - l, n):
                res += self.count(i + l, j, m - l, n, rem - 1)
                res %= M
        for l in range(1, n):
            if self.numapples(i, j, m, l) > 0 and self.numapples(i, j + l, m, n - l):
                res += self.count(i, j + l, m, n - l, rem - 1)
                res %= M
        self.cache[key] = res
        return res

    def ways(self, pizza: List[str], k: int) -> int:
        m = len(pizza)
        n = len(pizza[0])
        self.cache = {}
        self.qsum = [[None for i in range(n)] for j in range(m)]
        self.pizza = pizza
        return self.count(0, 0, m, n, k - 1)

class Solution:
    def waysToBuyPensPencils(self, total: int, cost1: int, cost2: int) -> int:
        ways = 0
        for i in range(1 + total // cost1):
            left = max(total - i * cost1, 0)
            ways += 1 + left // cost2
        return ways

M = 10 ** 9 + 7

class Solution:
    def numberOfWays(self, corridor: str) -> int:
        if corridor.count("S") % 2 != 0:
            return 0
        ctr = 0
        pos = []
        for i, c in enumerate(corridor):
            if c == "S":
                if ctr == 0:
                    pos.append(i)
                ctr += 1
            if ctr == 2:
                pos.append(i)
                ctr = 0
        if len(pos) <= 1:
            return 0
        if len(pos) == 2:
            return 1
        res = 1
        n = len(pos)
        for i in range(1, n, 2):
            if i < n and i + 1 < n:
                res *= pos[i + 1] - pos[i]
                res %= M
        return res

M = 10 ** 9 + 7

class Solution:
    def count(self, types, i, n, used, rem):
        if rem < 0:
            return 0
        if i >= n:
            return int(rem == 0)
        key = (i, used, rem)
        if key in self.cache:
            return self.cache[key]
        res = 0
        if used < types[i][0]:
            res += self.count(types, i, n, used + 1, rem - types[i][1])
        res += self.count(types, i + 1, n, 0, rem)
        res %= M
        self.cache[key] = res
        return res

    def waysToReachTarget(self, target: int, types: List[List[int]]) -> int:
        self.cache = {}
        return self.count(types, 0, len(types), 0, target)

from collections import Counter

M = 10 ** 9 + 7

class Solution:
    def numWays(self, words: List[str], target: str) -> int:
        m = len(target)
        n = len(words[0])
        chars = [Counter() for _ in range(n)]
        for w in words:
            for i in range(n):
                chars[i][w[i]] += 1
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(n + 1):
            dp[m][i] = 1
        for i in range(m - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                dp[i][j] = dp[i][j + 1]
                if chars[j][target[i]] > 0:
                    dp[i][j] += chars[j][target[i]] * dp[i + 1][j + 1]
                dp[i][j] %= M
        return dp[0][0]

M = 10 ** 9 + 7

class Solution:
    def numOfWays(self, n: int) -> int:
        vals = []
        for a in range(3):
            for b in range(3):
                for c in range(3):
                    if a != b and b != c:
                        vals.append((a, b, c))
        dp = defaultdict(int)
        for v in vals:
            dp[v] = 1
        ndp = defaultdict(int)
        for i in range(1, n):
            for curr in vals:
                ndp[curr] = 0
                for prev in vals:
                    if curr[0] != prev[0] and curr[1] != prev[1] and curr[2] != prev[2]:
                        ndp[curr] += dp[prev]
                        ndp[curr] %= M
            dp, ndp = ndp, dp
        return sum(dp.values()) % M

class Solution:
    def perm(self, n, k):
        C = [[0 for x in range(k+1)] for x in range(n+1)]
        for i in range(n+1):
            for j in range(min(i, k)+1):
                if j == 0 or j == i:
                    C[i][j] = 1
                else:
                    C[i][j] = C[i-1][j-1] + C[i-1][j]
        return C[n][k]

    def numberOfWays(self, startPos: int, endPos: int, k: int) -> int:
        diff = endPos - startPos
        if (diff + k) % 2 != 0:
            return 0
        x = (diff + k) // 2
        return self.perm(k, x) % (10 ** 9 + 7)

M = 10 ** 9 + 7

class Solution:
    def numOfWays(self, nums: List[int]) -> int:
        n = len(nums)
        f = [1] * (n + 1)
        fi = [1] * (n + 1)
        for i in range(1, n + 1):
            f[i] = i * f[i - 1]
            fi[i] = pow(i, M - 2, M) * fi[i - 1]
            f[i] %= M
            fi[i] %= M
        tree = {}
        for el in nums:
            curr = 1
            while curr in tree:
                if el < tree[curr]:
                    curr *= 2
                else:
                    curr *= 2
                    curr += 1
            tree[curr] = el
        ctr = {}
        size = {}
        for root in sorted(tree, reverse = True):
            l = ctr.get(2 * root, 1)
            r = ctr.get(2 * root + 1, 1)
            lsize = size.get(2 * root, 0)
            rsize = size.get(2 * root + 1, 0)
            size[root] = 1 + lsize + rsize
            ctr[root] = f[lsize + rsize] * fi[lsize] * fi[rsize] * l * r
            ctr[root] %= M
        return (M + ctr[1] - 1) % M

class Solution:
    def numberOfWays(self, s: str) -> int:
        n = len(s)
        z = 0
        o = 0
        zeroes = [z]
        ones = [o]
        for c in s:
            if c == '0':
                z += 1
            if c == '1':
                o += 1
            zeroes.append(z)
            ones.append(o)
        ways = 0
        for i in range(n):
            if s[i] == '0':
                ways += (ones[i] - ones[0]) * (ones[-1] - ones[i + 1])
            elif s[i] == '1':
                ways += (zeroes[i] - zeroes[0]) * (zeroes[-1] - zeroes[i + 1])
        return ways

M = 10 ** 9 + 7

class Solution:
    def numberOfCombinations(self, num: str) -> int:
        n = len(num)
        dp = [[0] * (n + 1) for _ in range(n)]
        lcp = [[0] * n for _ in range(n)]
        for i in range(n - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                lcp[i][j] = 1 + lcp[i + 1][j + 1] if i + 1 < n and j + 1 < n else 1
                if num[i] != num[j]:
                    lcp[i][j] = 0
        for i in range(n - 1, -1, -1):
            if num[i] == "0":
                continue
            for l in range(n - i, 0, -1):
                if l < n:
                    dp[i][l] += dp[i][l + 1]
                if i + l == n:
                    dp[i][l] += 1
                    continue
                if i + 2 * l > n or lcp[i][i + l] >= l or num[i + lcp[i][i + l]] < num[i + l + lcp[i][i + l]]:
                    dp[i][l] += dp[i + l][l]
                else:
                    dp[i][l] += dp[i + l][l + 1]
                dp[i][l] %= M
        return dp[0][1]

class Solution:
    def waysToSplitArray(self, nums: List[int]) -> int:
        n = len(nums)
        p = [0]
        for num in nums:
            p.append(p[-1] + num)
        ctr = 0
        for i in range(n - 1):
            l = p[i + 1]
            r = p[-1] - l
            if l >= r:
                ctr += 1
        return ctr

M = 10 ** 9 + 7

cache = {}

class Solution:
    def numWays(self, steps: int, arrLen: int) -> int:
        def count(rem, pos):
            if rem == 0:
                return int(pos == 0)
            key = (rem, pos, arrLen)
            if key in cache:
                return cache[key]
            res = 0
            for i in range(pos - 1, pos + 2):
                if 0 <= i < arrLen:
                    res += count(rem - 1, i)
                    res %= M
            cache[key] = res
            return res
        return count(steps, 0)

class Solution:
    def numberWays(self, hats: List[List[int]]) -> int:
        M = 10 ** 9 + 7
        n = len(hats)
        TARGET = (1 << n) - 1
        vals = {}
        for i in range(n):
            for h in hats[i]:
                if h not in vals:
                    vals[h] = []
                vals[h].append(i)
        vals = list(vals.values())
        @lru_cache(maxsize = None)
        def count(i, mask):
            if i >= len(vals):
                return int(mask == TARGET)
            res = count(i + 1, mask)
            for j in vals[i]:
                if not mask & (1 << j):
                    res += count(i + 1, mask | (1 << j))
                    res %= M
            return res
        return count(0, 0)

