class Solution:
    def numTriplets(self, nums1: List[int], nums2: List[int]) -> int:
        m = len(nums1)
        n = len(nums2)
        nums1ctr = Counter([el * el for el in nums1])
        nums2ctr = Counter([el * el for el in nums2])
        res = 0
        for i in range(m):
            for j in range(i + 1, m):
                res += nums2ctr[nums1[i] * nums1[j]]
        for i in range(n):
            for j in range(i + 1, n):
                res += nums1ctr[nums2[i] * nums2[j]]
        return res

from collections import Counter

class Solution:
    def wonderfulSubstrings(self, word: str) -> int:
        ctr = Counter()
        charctr = [0] * 10
        ctr[tuple(charctr)] = 1
        for c in word:
            charctr[ord(c) - ord('a')] += 1
            ctr[tuple([p % 2 for p in charctr])] += 1
        res = 0
        for p in ctr:
            res += ctr[p] * (ctr[p] - 1) // 2
            temp = list(p)
            for x in range(10):
                if p[x] == 0:
                    temp[x] = 1
                    res += ctr[p] * ctr[tuple(temp)]
                    temp[x] = 0
        return res

class Solution:
    def zeroFilledSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        i = 0
        res = 0
        while i < n:
            ctr = 1
            while i < n - 1 and nums[i] == nums[i + 1]:
                ctr += 1
                i += 1
            i += 1
            if nums[i - 1] == 0:
                res += ctr * (ctr + 1) // 2
        return res

class Solution:
    def atMostNGivenDigitSet(self, digits: List[str], n: int) -> int:
        digits = list(map(int, digits))
        cache = {}
        def count(num, i, tight, nzseen):
            if i >= len(num):
                return int(nzseen)
            key = (i, tight, nzseen)
            if key in cache:
                return cache[key]
            maxd = 9
            if tight:
                maxd = int(num[i])
            res = 0
            for d in ([] if nzseen else [0]) + digits:
                if d > maxd:
                    break
                res += count(num, i + 1, tight and d == maxd, nzseen or d != 0)
            cache[key] = res
            return res
        return count(str(n), 0, True, False)

class Solution:
    def count(self, num, i, n, tight, used):
        if i >= n:
            return 1
        key = (i, tight, used)
        if key in self.cache:
            return self.cache[key]
        maxd = 9
        if tight:
            maxd = int(num[i])
        res = 0
        for d in range(maxd + 1):
            if not used & (1 << d):
                newused = used | (1 << d)
                if used == 0 and d == 0:
                    newused = used
                res += self.count(num, i + 1, n, tight and d == maxd, newused)
        self.cache[key] = res
        return res

    def numDupDigitsAtMostN(self, n: int) -> int:
        self.cache = {}
        num = str(n)
        return n - self.count(num, 0, len(num), True, 0) + 1

class Solution:
    def gen(self, curr, k, rem):
        if rem == 0:
            return self.res.append(curr)
        d = curr % 10
        if d + k < 10:
            self.gen(10 * curr + d + k, k, rem - 1)
        if k > 0 and d - k >= 0:
            self.gen(10 * curr + d - k, k, rem - 1)

    def numsSameConsecDiff(self, n: int, k: int) -> List[int]:
        self.res = []
        for i in range(1, 10):
            self.gen(i, k, n - 1)
        return self.res

class Solution:
    def findOcurrences(self, text: str, first: str, second: str) -> List[str]:
        words = text.split()
        n = len(words)
        return [words[i] for i in range(n) if i > 1 and words[i - 1] == second and words[i - 2] == first]

from sortedcontainers import SortedList

class Solution:
    def oddEvenJumps(self, arr: List[int]) -> int:
        n = len(arr)
        M = max(arr)
        dp = [[False, False] for _ in range(n)]
        dp[n - 1][0] = dp[n - 1][1] = True
        vals = SortedList()
        valmap = {}
        res = 0
        for i in range(n - 1, -1, -1):
            odd = even = False
            pos = vals.bisect_left((arr[i], float('-inf')))
            if pos < len(vals):
                odd = vals[pos][1]
            if pos == len(vals) or vals[pos][0] > arr[i]:
                pos -= 1
            if pos >= 0:
                even = vals[pos][1]
            if arr[i] in valmap:
                vals.remove((arr[i], valmap[arr[i]]))
            valmap[arr[i]] = min(valmap.get(arr[i], float('inf')), i)
            vals.add((arr[i], i))
            if odd and dp[odd][0]:
                dp[i][1] = True
            if even and dp[even][1]:
                dp[i][0] = True
            if dp[i][1]:
                res += 1
        return res

class Solution:
    def oddEvenList(self, head: Optional[ListNode]) -> Optional[ListNode]:
        evenprev = None
        oddprev = None
        evenhead = None
        oddhead = None
        curr = head
        odd = False
        while curr:
            nextcurr = curr.next
            if odd:
                if oddprev != None:
                    oddprev.next = curr
                else:
                    oddhead = curr
                oddprev = curr
                oddprev.next = None
            else:
                if evenprev != None:
                    evenprev.next = curr
                else:
                    evenhead = curr
                evenprev = curr
                evenprev.next = None
            curr = nextcurr
            odd = not odd
        if evenprev:
            evenprev.next = oddhead
        return evenhead

