class Solution:
    def longest(self, strs, i, m, n, slen):
        if m < 0 or n < 0:
            return -1
        if i >= slen:
            return 0
        key = (i, m, n)
        if key in self.cache:
            return self.cache[key]
        x, y = strs[i]
        a = 1 + self.longest(strs, i + 1, m - x, n - y, slen)
        b = self.longest(strs, i + 1, m, n, slen)
        mlen = max(a, b)
        self.cache[key] = mlen
        return mlen

    def findMaxForm(self, strs: List[str], m: int, n: int) -> int:
        slen = len(strs)
        strs = [(s.count("0"), s.count("1")) for s in strs]
        self.cache = {}
        return self.longest(strs, 0, m, n, slen)

class TopVotedCandidate:
    def __init__(self, persons: List[int], times: List[int]):
        n = len(persons)
        count = [0] * n
        self.times = times
        self.winner = [-1] * n
        win = (float('-inf'), float('-inf'), -1)
        for i in range(n):
            count[persons[i]] += 1
            win = max(win, (count[persons[i]], times[i], persons[i]))
            self.winner[i] = win[2]

    def q(self, t: int) -> int:
        beg = 0
        end = len(self.times) - 1
        res = -1
        while beg <= end:
            mid = (beg + end) // 2
            if self.times[mid] <= t:
                res = self.winner[mid]
                beg = mid + 1
            else:
                end = mid - 1
        return res

import bisect

class TrieNode:
    def __init__(self):
        self.child = {}
        self.pos = []

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, s, i):
        curr = self.root
        curr.pos.append(i)
        for c in s:
            if c not in curr.child:
                curr.child[c] = TrieNode()
            curr = curr.child[c]
            curr.pos.append(i)

    def check(self, s):
        curr = self.root
        for c in s:
            if c not in curr.child or curr.child[c].ctr == 0:
                return False
            curr = curr.child[c]
        return curr.end

    def majority(self, l, r, threshold):
        curr = self.root
        res = 0
        freq = 0
        while True:
            maxchild = (-1, None)
            for c in curr.child:
                ctr = bisect.bisect_right(curr.child[c].pos, r) - bisect.bisect_left(curr.child[c].pos, l)
                maxchild = max(maxchild, (ctr, c))
            if maxchild[1] != None:
                freq = maxchild[0]
                curr = curr.child[maxchild[1]]
                res = 10 * res + int(maxchild[1])
            else:
                break
        if freq < threshold:
            return -1
        return res

class MajorityChecker:
    def __init__(self, arr: List[int]):
        n = len(arr)
        self.trie = Trie()
        pad = lambda x: "{:06d}".format(x)
        for i in range(n):
            self.trie.insert(pad(arr[i]), i)

    def query(self, left: int, right: int, threshold: int) -> int:
        return self.trie.majority(left, right, threshold)

class StockSpanner:
    def __init__(self):
        self.stack = []
        self.ctr = 0

    def next(self, price: int) -> int:
        while len(self.stack) > 0 and price >= self.stack[-1][1]:
            self.stack.pop()
        res = -1
        if len(self.stack) > 0:
            res = self.stack[-1][0]
        self.stack.append((self.ctr, price))
        self.ctr += 1
        return self.ctr - res - 1

class Solution:
    def getSteps(self, curr):
        steps = set()
        for i in range(4):
            for d in [1, -1]:
                now = list(curr)
                now[i] = (10 + now[i] + d) % 10
                steps.add(tuple(now))
        return steps

    def openLock(self, deadends: List[str], target: str) -> int:
        beg = (0, 0, 0, 0)
        target = tuple(int(d) for d in target)
        paths = [(beg, 0)]
        visited = {beg}
        for end in deadends:
            end = tuple(int(d) for d in end)
            if beg == end:
                return -1
            visited.add(end)
        i = 0
        while i < len(paths):
            curr, steps = paths[i]
            if curr == target:
                return steps
            for j in self.getSteps(curr):
                if j not in visited:
                    visited.add(j)
                    paths.append((j, steps + 1))
            i += 1
        return -1

class Solution:
    def minTransfers(self, transactions: List[List[int]]) -> int:
        debt = [0] * 12
        for u, v, amount in transactions:
            debt[u] -= amount
            debt[v] += amount
        debts = [d for d in debt if d != 0]
        m = len(debt)
        dp = [float('inf')] * (1 << m)
        dp[0] = 0
        for mask in range(1, 1 << m):
            s = 0
            for i in range(m):
                if mask & (1 << i):
                    s += debt[i]
            if s == 0:
                dp[mask] = mask.bit_count() - 1
                submask = mask
                while submask:
                    if s == 0:
                        dp[mask] = min(dp[mask], dp[submask] + dp[mask ^ submask])
                    submask = (submask - 1) & mask
        return dp[-1]

class Solution:
    def partitionString(self, s: str) -> int:
        n = len(s)
        seen = set()
        res = 1
        for i in range(n):
            if s[i] in seen:
                res += 1
                seen.clear()
            seen.add(s[i])
        return res

def booth_algorithm(string):
    string = string + string  # Duplicate the string to avoid modulo operation
    n = len(string)
    i = 0
    j = 1
    k = 0
    while i < n and j < n and k < n:
        diff = ord(string[(i + k) % n]) - ord(string[(j + k) % n])
        if diff == 0:
            k += 1
        else:
            if diff > 0:
                i = i + k + 1
            else:
                j = j + k + 1
            if i == j:
                j += 1
            k = 0
    rotation_index = min(i, j)
    return string[rotation_index:rotation_index + n//2]

class Solution:
    def orderlyQueue(self, s: str, k: int) -> str:
        if k > 1:
            return "".join(sorted(s))
        else:
            return booth_algorithm(s)

class Solution:
    def find(self, i, j, m, n, rem):
        if rem < 0:
            return 0
        if i < 0 or i >= m or j < 0 or j >= n:
            return 1
        key = (i, j, rem)
        if key in self.cache:
            return self.cache[key]
        ctr = 0
        for x, y in [(i - 1, j), (i, j + 1), (i + 1, j), (i, j - 1)]:
            ctr += self.find(x, y, m, n, rem - 1)
        self.cache[key] = ctr
        return ctr

    def findPaths(self, m: int, n: int, maxMove: int, startRow: int, startColumn: int) -> int:
        self.cache = {}
        return self.find(startRow, startColumn, m, n, maxMove) % (10 ** 9 + 7)

class Solution:
    def DFS(self, i, j, m, n, heights, visited):
        for di, dj in [(-1, 0), (0, 1), (1, 0), (0, -1)]:
            if 0 <= i + di < m and 0 <= j + dj < n:
                if (i + di, j + dj) not in visited and heights[i + di][j + dj] <= heights[i][j]:
                    visited.add((i + di, j + dj))
                    self.DFS(i + di, j + dj, m, n, heights, visited)

    def pacificAtlantic(self, heights: List[List[int]]) -> List[List[int]]:
        m = len(heights)
        n = len(heights[0])
        pacific = set([(i, 0) for i in range(m)] + [(0, i) for i in range(n)])
        atlantic = set([(i, n - 1) for i in range(m)] + [(m - 1, i) for i in range(n)])
        op = []
        for i in range(m):
            for j in range(n):
                visited = {(i, j)}
                self.DFS(i, j, m, n, heights, visited)
                if len(set.intersection(visited, pacific)) > 0 and len(set.intersection(visited, atlantic)) > 0:
                    op.append([i, j])
        return op

class Solution:
    def numWays(self, n: int, k: int) -> int:
        dp = [[0] * k for _ in range(n + 1)]
        s = [0] * (n + 1)
        for i in range(1, n + 1):
            for j in range(k):
                for l in range(1, 3):
                    if i > l:
                        dp[i][j] += s[i - l] - dp[i - l][j]
                    elif i == l:
                        dp[i][j] += 1
            s[i] = sum(dp[i])
        return sum(dp[n])

class Solution:
    def minCostII(self, costs: List[List[int]]) -> int:
        n = len(costs)
        k = len(costs[0])
        dp = [[float('inf')] * k for _ in range(n)]
        dp[0] = costs[0]
        for i in range(1, n):
            p = [float('inf')] * (k + 1)
            s = [float('inf')] * (k + 1)
            for j in range(k):
                p[j + 1] = min(p[j], dp[i - 1][j])
                s[j + 1] = min(s[j], dp[i - 1][k - j - 1])
            for j in range(k):
                dp[i][j] = min(dp[i][j], min(p[j], s[k - j - 1]) + costs[i][j])
        return min(dp[n - 1])

class Solution:
    def minpaint(self, houses, i, cost, rem, m, n, prev):
        if rem < 0:
            return float('inf')
        if i == m:
            if rem == 0:
                return 0
            return float('inf')
        if (i, rem, prev) in self.cache:
            return self.cache[(i, rem, prev)]
        if houses[i] != 0:
            newrem = rem
            if houses[i] != prev:
                newrem -= 1
            return self.minpaint(houses, i + 1, cost, newrem, m, n, houses[i])
        mincost = float('inf')
        for j in range(1, n + 1):
            newrem = rem
            if j != prev:
                newrem -= 1
            curr = cost[i][j - 1] + self.minpaint(houses, i + 1, cost, newrem, m, n, j)
            mincost = min(mincost, curr)
        self.cache[(i, rem, prev)] = mincost
        return mincost

    def minCost(self, houses: List[int], cost: List[List[int]], m: int, n: int, target: int) -> int:
        self.cache = {}
        res = self.minpaint(houses, 0, cost, target, m, n, -1)
        if res == float('inf'):
            return -1
        return res

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        dp = [[[float('inf')] * 4 for _ in range(4)] for _ in range(n // 2 + 1)]
        for pl in range(-1, 3):
            for pr in range(-1, 3):
                dp[n // 2][pl][pr] = 0
        for i in range(n // 2 - 1, -1, -1):
            for pl in range(-1, 3):
                for pr in range(-1, 3):
                    for f in range(3):
                        for s in range(3):
                            if f != s and f != pl and s != pr:
                                dp[i][pl][pr] = min(dp[i][pl][pr], cost[i][f] + cost[n - i - 1][s] + dp[i + 1][f][s])
        return dp[0][-1][-1]

class Solution:
    def minCost(self, costs: List[List[int]]) -> int:
        n = len(costs)
        dp = [[float('inf')] * 3 for _ in range(n)]
        dp[0] = costs[0]
        for i in range(1, n):
            for j in range(3):
                for k in range(3):
                    if j != k:
                        dp[i][k] = min(dp[i][k], dp[i - 1][j] + costs[i][k])
        return min(dp[n - 1])

M = 10 ** 9 + 7

cache = {}

class Solution:
    def colorTheGrid(self, m: int, n: int) -> int:
        if m not in cache:
            good = []
            def gen(arr):
                if len(arr) == m:
                    good.append(arr[:])
                    return
                for l in range(3):
                    if arr and l == arr[-1]:
                        continue
                    arr.append(l)
                    gen(arr)
                    arr.pop()
            gen([])
            edges = [[] for _ in range(len(good))]
            g = len(good)
            for i in range(g):
                for j in range(g):
                    valid = True
                    for k in range(m):
                        if good[i][k] == good[j][k]:
                            valid = False
                            break
                    if valid:
                        edges[i].append(j)
            cache[m] = edges
        edges = cache[m]
        g = len(edges)
        dp = [1] * g
        ndp = [0] * g
        for _ in range(1, n):
            for i in range(g):
                ndp[i] = 0
                for j in edges[i]:
                    ndp[i] += dp[j]
                    ndp[i] %= M
            dp, ndp = ndp, dp
        return sum(dp) % M

class Solution:
    def paintWalls(self, cost: List[int], time: List[int]) -> int:
        n = len(cost)
        dp = [float('inf')] * (n + 1)
        dp[n] = 0
        ndp = dp[:]
        for i in range(n - 1, -1, -1):
            for used in range(n + 1):
                ndp[used] = min(dp[used], cost[i] + dp[min(used + time[i] + 1, n)])
            dp, ndp = ndp, dp
        return dp[0]

class Solution:
    def isPalindrome(self, head: Optional[ListNode]) -> bool:
        curr = head
        stack = []
        while curr:
            stack.append(curr.val)
            curr = curr.next
        curr = head
        while curr:
            if curr.val != stack.pop():
                return False
            curr = curr.next
        return True

class Solution:
    def isPalindrome(self, x: int) -> bool:
        xx = x
        nx = 0
        while x > 0:
            nx = 10 * nx + x % 10
            x = x // 10
        return xx == nx

class Trie:
    def __init__(self):
        self.c = {}
        self.pos = []

class Solution:
    def manachers(self, s):
        T = '#'.join('^{}$'.format(s))
        n = len(T)
        P = [0] * n
        C = R = 0
        for i in range(1, n - 1):
            if R > i:
                P[i] = min(R - i, P[2 * C - i])
            while T[i + 1 + P[i]] == T[i - 1 - P[i]]:
                P[i] += 1
            if i + P[i] > R:
                C, R = i, i + P[i]
        return P

    def pals(self, s):
        n = len(s)
        P = self.manachers(s)
        return {i for i in range(n + 1) if i + P[i + n + 1] >= n}

    def palindromePairs(self, words: List[str]) -> List[List[int]]:
        ftrie = Trie()
        ltrie = Trie()
        for i, w in enumerate(words):
            for s, trie in [(w, ftrie), (w[::-1], ltrie)]:
                curr = trie
                for c in s:
                    if c not in curr.c:
                        curr.c[c] = Trie()
                    curr = curr.c[c]
                curr.pos.append(i)
        res = [set() for _ in range(len(words))]
        for i, w in enumerate(words):
            for s, trie, rev in [(w, ltrie, False), (w[::-1], ftrie, True)]:
                lens = self.pals(s)
                l = 0
                curr = trie
                for j in curr.pos:
                    if l not in lens:
                        break
                    if i == j:
                        continue
                    res[i].add(j)
                    res[j].add(i)
                for c in s:
                    if c not in curr.c:
                        break
                    curr = curr.c[c]
                    l += 1
                    if l in lens and not (rev and l == len(s)):
                        for j in curr.pos:
                            if i == j:
                                continue
                            if rev:
                                res[j].add(i)
                            else:
                                res[i].add(j)
        return [[i, j] for i, v in enumerate(res) for j in v]

class Solution:
    def minCut(self, s: str) -> int:
        n = len(s)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0
        prevpal = [True] * n
        pal = [False] * n
        for i in range(1, n + 1):
            for j in range(i - 1, n):
                pal[j] = True
            l = 1
            while l <= i:
                if i >= 2 and i - l < n - 1:
                    pal[i - l] = s[i - l] == s[i - 1] and prevpal[i - l + 1]
                if pal[i - l]:
                    dp[i] = min(dp[i], 1 + dp[i - l])
                l += 1
            prevpal, pal = pal, prevpal
        return dp[n] - 1

from collections import defaultdict
import heapq

class Solution:
    def palindromePartition(self, s: str, k: int) -> int:
        n = len(s)
        graph = defaultdict(set)
        for i in range(n):
            for x, y in [(i, i), (i, i + 1)]:
                minops = 0
                while x >= 0 and y < n:
                    minops += int(s[x] != s[y])
                    graph[x].add((y + 1, minops))
                    x -= 1
                    y += 1
        dist = defaultdict(lambda: float('inf'))
        heap = [(0, 0, k)]
        dist[(0, k)] = 0
        while len(heap) > 0:
            d, curr, rem = heapq.heappop(heap)
            if curr == n and rem == 0:
                return d
            if rem == 0:
                continue
            for j, cost in graph[curr]:
                if dist[(j, rem - 1)] > d + cost:
                    dist[(j, rem - 1)] = d + cost
                    heapq.heappush(heap, (dist[(j, rem - 1)], j, rem - 1))

class Solution:
    def strech(self, s, i, j, n):
        l = 0
        while i - l >= 0 and j + l < n and s[i - l] == s[j + l]:
            self.pals.add((i - l, j + l + 1))
            l += 1

    def checkPartitioning(self, s: str) -> bool:
        n = len(s)
        self.pals = set()
        for i in range(n):
            for a, b in [(i, i), (i, i + 1)]:
                self.strech(s, a, b, n)
        for i in range(1, n):
            for j in range(i, n):
                if (0, i) in self.pals and (i, j) in self.pals and (j, n) in self.pals:
                    return True
        return False

class Solution:
    def getPos(self, s, lpal, i, n):
        if i == n:
            return [[]]
        res = []
        for l in lpal[i]:
            curr = s[i:i+l]
            val = self.getPos(s, lpal, i + l, n)
            res += [[curr] + v for v in val]
        return res

    def partition(self, s: str) -> List[List[str]]:
        n = len(s)
        lpal = [[] for _ in range(n)]
        prevpal = [True] * n
        pal = [False] * n
        for i in range(1, n + 1):
            for j in range(i - 1, n):
                pal[j] = True
            l = 1
            while l <= i:
                if i >= 2 and i - l < n - 1:
                    pal[i - l] = s[i - l] == s[i - 1] and prevpal[i - l + 1]
                if pal[i - l]:
                    lpal[i - l].append(l)
                l += 1
            prevpal, pal = pal, prevpal
        return self.getPos(s, lpal, 0, len(s))

class Solution:
    def minimumMoves(self, arr: List[int]) -> int:
        n = len(arr)
        def cost(i, j):
            if i > j:
                return 1
            return 0
        @lru_cache(maxsize = None)
        def dp(i, j):
            if i > j:
                return 0
            if i == j:
                return 1
            res = 1 + min(dp(i, j - 1), dp(i + 1, j))
            for k in range(i, j):
                if arr[k] == arr[j]:
                    res = min(res, cost(k + 1, j - 1) + dp(i, k - 1) + dp(k + 1, j - 1))
            for k in range(i + 1, j + 1):
                if arr[i] == arr[k]:
                    res = min(res, cost(i + 1, k - 1) + dp(i + 1, k - 1) + dp(k + 1, j))
            return res
        return dp(0, n - 1)

class Solution:
    def countSubstrings(self, s: str, i = 0) -> int:
        n = len(s)
        if i == n - 1:
            return 1
        k = self.countSubstrings(s, i + 1)
        ctr = 0
        for j in range(i + 1, n + 1):
            if s[i:j] == s[i:j][::-1]:
                ctr += 1
        return ctr + k

from collections import deque, defaultdict

class Solution:
    def minimumTime(self, n: int, relations: List[List[int]], time: List[int]) -> int:
        q = deque()
        indegree = [0] * n
        graph = defaultdict(set)
        revgraph = defaultdict(set)
        for a, b in relations:
            indegree[b - 1] += 1
            graph[a - 1].add(b - 1)
            revgraph[b - 1].add(a - 1)
        for i in range(n):
            if indegree[i] == 0:
                q.appendleft(i)
        res = [0] * n
        while len(q) > 0:
            curr = q.pop()
            res[curr] = time[curr]
            for j in revgraph[curr]:
                res[curr] = max(res[curr], time[curr] + res[j])
            for j in graph[curr]:
                indegree[j] -= 1
                if indegree[j] == 0:
                    q.appendleft(j)
        return max(res)

class Solution:
    def parseBoolExpr(self, expression: str) -> bool:
        n = len(expression)
        stack = []
        i = 0
        while i < n:
            if i < n - 1 and expression[i:i+2] in {"!(", "&(", "|("}:
                stack.append(expression[i:i+2])
                i += 2
            elif expression[i] == ')':
                vals = []
                while stack[-1] not in {"!(", "&(", "|("}:
                    vals.append(stack.pop())
                op = stack.pop()[0]
                if op == '!':
                    stack.append(not vals[0])
                if op == '&':
                    stack.append(False not in vals)
                if op == '|':
                    stack.append(True in vals)
                i += 1
            elif expression[i] == 'f':
                stack.append(False)
                i += 1
            elif expression[i] == 't':
                stack.append(True)
                i += 1
            else:
                i += 1
        return stack.pop()

class Solution:
    def pivotArray(self, nums: List[int], pivot: int) -> List[int]:
        left = []
        mid = []
        right = []
        for num in nums:
            if num < pivot:
                left.append(num)
            elif num > pivot:
                right.append(num)
            else:
                mid.append(num)
        return left + mid + right

class Solution:
    def maxSumAfterPartitioning(self, arr: List[int], k: int) -> int:
        n = len(arr)
        dp = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            m = float('-inf')
            for j in range(i, min(i + k, n)):
                m = max(m, arr[j])
                dp[i] = max(dp[i], m * (j - i + 1) + dp[j + 1])
        return dp[0]

class Solution:
    def partitionDisjoint(self, nums: List[int]) -> int:
        n = len(nums)
        minvals = [0] * n
        minvals[n - 1] = nums[n - 1]
        for i in range(n - 2, -1, -1):
            minvals[i] = min(nums[i], minvals[i + 1])
        currmax = float('-inf')
        for i in range(n - 1):
            currmax = max(currmax, nums[i])
            if currmax <= minvals[i + 1]:
                return i + 1

class Solution:
    def canThreePartsEqualSum(self, arr: List[int]) -> bool:
        n = len(arr)
        total = sum(arr)
        curr = 0
        f = -1
        s = -1
        for i in range(n):
            curr += arr[i]
            if f < 0 and curr * 3 == total:
                f = i
            if curr * 3 == 2 * total:
                s = i
            if f >= 0 and s >= 0 and f < s and s < n - 1:
                return True
        return False

from collections import defaultdict
import bisect

class Solution:
    def minimumDifference(self, nums: List[int]) -> int:
        n = len(nums)
        total = sum(nums)
        target = total // 2
        k = n // 2
        left = defaultdict(set)
        right = defaultdict(set)
        for mask in range(1 << k):
            l = r = 0
            ctr = 0
            for i in range(k):
                if mask & (1 << i):
                    l += nums[i]
                    r += nums[k + i]
                    ctr += 1
            left[ctr].add(l)
            right[ctr].add(r)
        for x in list(right.keys()):
            right[x] = sorted(right[x])
        res = float('inf')
        for x in left:
            for s in left[x]:
                i = bisect.bisect_left(right[k - x], target - s)
                if i < len(right[k - x]):
                    res = min(res, abs(2 * (s + right[k - x][i]) - total))
                if i > 0:
                    res = min(res, abs(2 * (s + right[k - x][i - 1]) - total))
        return res

class Solution:
    def partitionArray(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if k == 0:
            return len(set(nums))
        nums.sort()
        subs = [[float('inf'), float('-inf')] for i in range(n)]
        res = 0
        for num in nums:
            for i in range(n):
                mn, mx = subs[i]
                nmn = min(mn, num)
                nmx = max(mx, num)
                if nmx - nmn <= k:
                    subs[i][0], subs[i][1] = nmn, nmx
                    res = max(res, i + 1)
                    break
        return res

import heapq
import numpy as np

def add_poly(p, q):
    max_len = max(len(p), len(q))
    p = np.pad(p, (0, max_len - len(p)))
    q = np.pad(q, (0, max_len - len(q)))
    return p + q

def multiply_naive(p, q):
    return np.polynomial.polynomial.polymul(p, q)

class Solution:
    def canPartition(self, nums):
        s = sum(nums)
        if s & 1:
            return False
        s //= 2
        heap = []
        for num in nums:
            poly = np.zeros(num + 1, dtype=int)
            poly[0], poly[num] = 1, 1
            heapq.heappush(heap, (len(poly), poly.tolist()))
        while len(heap) > 1:
            _, poly1 = heapq.heappop(heap)
            _, poly2 = heapq.heappop(heap)
            result_poly = multiply_naive(np.array(poly1), np.array(poly2))
            heapq.heappush(heap, (len(result_poly), result_poly.tolist()))
        _, final_poly = heap[0]
        return bool(s < len(final_poly) and final_poly[s] > 0)

class Solution:
    def partition(self, s, pos, k, n):
        if k >= n:
            return []
        j = float('-inf')
        for i in range(k, n):
            j = max(pos[s[i]], j)
            if j == i:
                return [i + 1 - k] + self.partition(s, pos, i + 1, n)

    def partitionLabels(self, s: str, k = 0) -> List[int]:
        pos = {}
        n = len(s)
        for i, c in enumerate(s):
            pos[c] = i
        return self.partition(s, pos, 0, n)

class Solution:
    def lessThan(self, head, x):
        if not head:
            return head
        if head.val >= x:
            return self.lessThan(head.next, x)
        newhead = TreeNode(val = head.val)
        newhead.next = self.lessThan(head.next, x)
        return newhead

    def greaterThan(self, head, x):
        if not head:
            return head
        if head.val < x:
            return self.greaterThan(head.next, x)
        newhead = TreeNode(val = head.val)
        newhead.next = self.greaterThan(head.next, x)
        return newhead

    def partition(self, head: Optional[ListNode], x: int) -> Optional[ListNode]:
        left = self.lessThan(head, x)
        right = self.greaterThan(head, x)
        if not left:
            return right
        curr = left
        while curr and curr.next:
            curr = curr.next
        curr.next = right
        return left

class Solution:
    def minimumBeautifulSubstrings(self, s: str) -> int:
        n = len(s)
        p = {pow(5, i) for i in range(10)}
        dp = [float('inf')] * (n + 1)
        dp[n] = 0
        for i in range(n - 1, -1, -1):
            if s[i] == "0":
                continue
            curr = 0
            for j in range(i, n):
                curr = 2 * curr + int(s[j])
                if curr in p:
                    dp[i] = min(dp[i], 1 + dp[j + 1])
        if dp[0] == float('inf'):
            return -1
        return dp[0]

class Solution:
    def minimumPartition(self, s: str, k: int) -> int:
        n = len(s)
        v = 0
        res = 1
        for c in s:
            if 10 * v + int(c) > k:
                res += 1
                v = int(c)
                if v > k:
                    return -1
            else:
                v = 10 * v + int(c)
        return res

class Solution:
    def isPossible(self, i, sides, k, nums, n, total):
        if i >= n:
            return len(set(sides)) == 1
        key = tuple(sorted(sides) + [i])
        if key in self.cache:
            return self.cache[key]
        for j in range(k):
            if k * (sides[j] + nums[i]) > total:
                continue
            sides[j] += nums[i]
            curr = self.isPossible(i + 1, sides, k, nums, n, total)
            if curr:
                self.cache[key] = True
                return True
            else:
                sides[j] -= nums[i]
        self.cache[key] = False
        return False

    def canPartitionKSubsets(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        total = sum(nums)
        nums.sort(reverse = True)
        self.cache = {}
        return self.isPossible(0, [0] * k, k, nums, n, total)

class Solution:
    def minPartitions(self, n: str) -> int:
        return max([int(d) for d in n])

class Solution:
    def getRow(self, rowIndex: int) -> List[int]:
        curr = [1]
        for i in range(rowIndex):
            curr = [0] + curr + [0]
            n = len(curr)
            for i in range(n - 1):
                curr[i] = curr[i] + curr[i + 1]
            curr.pop()
        return curr

class Solution:
    def generate(self, numRows: int) -> List[List[int]]:
        tri = []
        curr = [1]
        n = 1
        for i in range(numRows):
            tri.append(curr)
            curr = [0] + curr
            n += 1
            for i in range(n - 1):
                curr[i] = curr[i] + curr[i + 1]
        return tri

class Solution:
    def passThePillow(self, n: int, time: int) -> int:
        i = 1
        f = True
        for _ in range(time):
            if i == 1:
                f = True
            if i == n:
                f = False
            if f:
                i += 1
            else:
                i -= 1
        return i

class Solution:
    def minPatches(self, nums: List[int], n: int) -> int:
        res = 0
        while True:
            nums.sort()
            found = 0
            if nums[0] > 1:
                found = 1
            else:
                p = 0
                for i in range(len(nums)):
                    p += nums[i]
                    if i == len(nums) - 1 or p + 1 < nums[i + 1]:
                        found = p + 1
                        break
            if found > n:
                break
            nums.append(found)
            res += 1
        return res

class Solution:
    def isPathCrossing(self, path: str) -> bool:
        x = 0
        y = 0
        visited = set()
        visited.add((x, y))
        for c in path:
            if c == 'N':
                y += 1
            if c == 'E':
                x += 1
            if c == 'S':
                y -= 1
            if c == 'W':
                x -= 1
            if (x, y) in visited:
                return True
            visited.add((x, y))
        return False

class Solution:
    def pathExistenceQueries(self, n: int, nums: List[int], maxDiff: int, queries: List[List[int]]) -> List[int]:
        arr = sorted((v, i) for i, v in enumerate(nums))
        vals = [v for v, _ in arr]
        pos = [0] * n
        for i, (_, j) in enumerate(arr):
            pos[j] = i

        comp = [0] * n
        for i in range(1, n):
            comp[i] = comp[i - 1] + (vals[i] - vals[i - 1] > maxDiff)

        nxt = [0] * n
        j = 0
        for i in range(n):
            while j < n and vals[j] <= vals[i] + maxDiff:
                j += 1
            nxt[i] = j - 1

        logn = (n - 1).bit_length()
        jump = [nxt]
        for k in range(1, logn):
            pre = jump[k - 1]
            cur = [0] * n
            for i in range(n):
                cur[i] = pre[pre[i]]
            jump.append(cur)

        out = []
        for u, v in queries:
            pu, pv = pos[u], pos[v]
            if comp[pu] != comp[pv]:
                out.append(-1)
            elif pu == pv:
                out.append(0)
            else:
                if pu > pv:
                    pu, pv = pv, pu
                x = pu
                ans = 0
                for k in range(logn - 1, -1, -1):
                    y = jump[k][x]
                    if y < pv:
                        x = y
                        ans |= 1 << k
                out.append(ans + 1)
        return out

class Solution:
    def pathInZigZagTree(self, label: int) -> List[int]:
        res = []
        p = pow(2, label.bit_length() - 1)
        while p >= 1:
            res.append(label)
            p //= 2
            label = 3 * p - label // 2 - 1
        res.reverse()
        return res

class Solution:
    def inorder(self, root, path, rem):
        if root:
            path.append(root.val)
            rem -= root.val
            self.inorder(root.left, path, rem)
            self.inorder(root.right, path, rem)
            if not root.left and not root.right and rem == 0:
                self.res.append(path[:])
            path.pop()

    def pathSum(self, root: Optional[TreeNode], targetSum: int) -> List[List[int]]:
        self.res = []
        self.inorder(root, [], targetSum)
        return self.res

