from collections import defaultdict

class Solution:
    def count(self, root, currsum, ctr, targetSum):
        if root:
            self.res += ctr[currsum - targetSum]
            ctr[currsum] += 1
            if root.left:
                self.count(root.left, currsum + root.left.val, ctr, targetSum)
            if root.right:
                self.count(root.right, currsum + root.right.val, ctr, targetSum)
            ctr[currsum] -= 1
        else:
            self.res += ctr[currsum - targetSum]

    def pathSum(self, root: Optional[TreeNode], targetSum: int) -> int:
        ctr = defaultdict(int)
        self.res = 0
        ctr[0] = 1
        if root:
            self.count(root, root.val, ctr, targetSum)
        return self.res

class Solution:
    def inorder(self, root, curr):
        if root:
            curr -= root.val
            if not root.left and not root.right and curr == 0:
                self.res = True
            self.inorder(root.left, curr)
            self.inorder(root.right, curr)

    def hasPathSum(self, root: Optional[TreeNode], targetSum: int) -> bool:
        self.res = False
        self.inorder(root, targetSum)
        return self.res

class Solution:
    def getMaximumGold(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        graph = [[] for _ in range(m * n)]
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 0:
                    continue
                for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
                    if 0 <= x < m and 0 <= y < n and grid[x][y] != 0:
                        graph[n * i + j].append((n * x + y, grid[x][y]))
        @lru_cache(maxsize = None)
        def mpath(i, used):
            res = 0
            for j, w in graph[i]:
                if not used & (1 << j):
                    res = max(res, w + mpath(j, used | (1 << j)))
            return res
        return max(grid[i // n][i % n] + mpath(i, 1 << i) for i in range(m * n))

from collections import defaultdict
import heapq

class Solution:
    def maxProbability(self, n: int, edges: List[List[int]], succProb: List[float], start: int, end: int) -> float:
        res = 0
        graph = defaultdict(set)
        for i in range(len(edges)):
            graph[edges[i][0]].add((edges[i][1], succProb[i]))
            graph[edges[i][1]].add((edges[i][0], succProb[i]))
        heap = []
        dist = defaultdict(int)
        dist[start] = 1
        for i in range(n):
            heapq.heappush(heap, (-dist[i], i))
        while len(heap) > 0:
            currp, curr = heapq.heappop(heap)
            for j, p in graph[curr]:
                if dist[j] < dist[curr] * p:
                    dist[j] = dist[curr] * p
                    heapq.heappush(heap, (-dist[j], j))
        return dist[end]

class Solution:
    def isPossible(self, heights, i, j, m, n, visited, k):
        if (i, j) == (m - 1, n - 1):
            return True
        for (x, y) in [(i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)]:
            if 0 <= x < m and 0 <= y < n and (x, y) not in visited:
                effort = abs(heights[x][y] - heights[i][j])
                if effort <= k:
                    visited.add((x, y))
                    if self.isPossible(heights, x, y, m, n, visited, k):
                        return True
        return False

    def minimumEffortPath(self, heights: List[List[int]]) -> int:
        m = len(heights)
        n = len(heights[0])
        beg = 0
        end = 1
        while not self.isPossible(heights, 0, 0, m, n, {(0, 0)}, end):
            end = end << 1
        while beg <= end:
            mid = (beg + end) // 2
            iscurrpossible = self.isPossible(heights, 0, 0, m, n, {(0, 0)}, mid)
            isprevpossible = self.isPossible(heights, 0, 0, m, n, {(0, 0)}, mid - 1)
            if not isprevpossible and iscurrpossible:
                return mid
            elif beg == end:
                break
            elif not isprevpossible and not iscurrpossible:
                beg = mid + 1
            elif isprevpossible and iscurrpossible:
                end = mid
        return beg

c = {}

def cache(fn):
    def inner(*args):
        args = tuple(args)
        if args in c:
            return c[args]
        c[args] = fn(*args)
        return c[args]
    return inner

class Solution:
    def numberOfPaths(self, grid: List[List[int]], k: int) -> int:
        m = len(grid)
        n = len(grid[0])
        M = 10 ** 9 + 7
        @cache
        def count(i, j, mod):
            if (i, j) == (m - 1, n - 1):
                return int((mod + grid[i][j]) % k == 0)
            res = (count(i + 1, j, (mod + grid[i][j]) % k) if i < m - 1 else 0) + (count(i, j + 1, (mod + grid[i][j]) % k) if j < n - 1 else 0)
            res %= M
            return res
        c.clear()
        return count(0, 0, 0)

class Solution:
    def peakIndexInMountainArray(self, arr: List[int]) -> int:
        old = True
        new = True
        for i in range(len(arr) - 1):
            new = arr[i + 1] > arr[i]
            if new ^ old:
                return i
            old = new

from sortedcontainers import SortedList

class Solution:
    def countOfPeaks(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        def ispeak(i):
            if i == 0 or i == n - 1:
                return False
            return nums[i - 1] < nums[i] > nums[i + 1]
        peaks = SortedList()
        for i in range(1, n - 1):
            if ispeak(i):
                peaks.add(i)
        res = []
        for t, x, y in queries:
            if t == 1:
                if x + 1 > y - 1:
                    res.append(0)
                else:
                    res.append(peaks.bisect_right(y - 1) - peaks.bisect_left(x + 1))
            else:
                for xx in range(x - 1, x + 2):
                    if 0 <= xx < n and ispeak(xx):
                        peaks.remove(xx)
                nums[x] = y
                for xx in range(x - 1, x + 2):
                    if 0 <= xx < n and ispeak(xx):
                        peaks.add(xx)
        return res

class Solution:
    def percentageLetter(self, s: str, letter: str) -> int:
        n = len(s)
        ctr = 0
        for c in s:
            if c == letter:
                ctr += 1
        return floor(100 * ctr / n)

class Solution:
    def getFactors(self, n, factors):
        for i in range(n - 1, 0, -1):
            if i not in factors and n % i == 0:
                factors.update({i})
                factors.update({n//i})
                self.getFactors(i, factors)

    def checkPerfectNumber(self, num: int) -> bool:
        fsum = 1
        i = 2
        while i * i <= num:
            if num % i == 0:
                fsum = fsum + i + num//i
            i += 1
        return (True if fsum == num and num!=1 else False)

from collections import deque

class Solution:
    def numSquares(self, n: int) -> int:
        q = deque([(n, 0)])
        v = {n}
        while len(q) > 0:
            curr, d = q.pop()
            if curr == 0:
                return d
            i = 0
            while i * i <= curr:
                j = curr - i * i
                if j not in v:
                    v.add(j)
                    q.appendleft((j, d + 1))
                i += 1

class Solution:
    def findPermutationDifference(self, s: str, t: str) -> int:
        res = 0
        for i in range(len(s)):
            res += abs(i - t.index(s[i]))
