from collections import Counter

class Solution:
    def checkInclusion(self, p: str, s: str) -> bool:
        np = len(p)
        ns = len(s)
        ctrp = Counter(p)
        ctrs = Counter()
        for i in range(ns):
            ctrs[s[i]] += 1
            if i >= np:
                ctrs[s[i - np]] -= 1
            if i >= np - 1 and ctrp == ctrs:
                return True
        return False

class Solution:
    def getPermutation(self, n: int, k: int) -> str:
        f = [1] * (n + 1)
        for i in range(1, n + 1):
            f[i] = i * f[i - 1]
        res = []
        used = set()
        for i in range(n):
            for d in range(1, n + 1):
                if d in used:
                    continue
                if k > f[n - i - 1]:
                    k -= f[n - i - 1]
                else:
                    used.add(d)
                    res.append(str(d))
                    break
        return "".join(res)

class Solution:
    def permuteUnique(self, nums: List[int]) -> List[List[int]]:
        n = len(nums)
        ctr = {}
        for num in nums:
            ctr[num] = ctr.get(num, 0) + 1
        nums = set(nums)
        paths = [([num], { **ctr, num: ctr[num] - 1 }, 1) for num in nums]
        while paths[0][2] < n:
            curr, currCtr, l = paths.pop(0)
            for num in nums:
                if currCtr[num] > 0:
                    paths.append((curr + [num], { **currCtr, num: currCtr[num] - 1 }, l + 1))
        return [perm[0] for perm in paths]

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        def cnt(a, b, r):
            if a + b == 0:
                return 1
            if r is None:
                if a == b:
                    return 2 * math.factorial(a) * math.factorial(b)
                elif a == b + 1 or b == a + 1:
                    return math.factorial(a) * math.factorial(b)
                else:
                    return 0
            else:
                if r == 1:
                    if (a + b) % 2 == 0:
                        if a != b:
                            return 0
                    else:
                        if a != b + 1:
                            return 0
                    return math.factorial(a) * math.factorial(b)
                else:
                    if (a + b) % 2 == 0:
                        if a != b:
                            return 0
                    else:
                        if b != a + 1:
                            return 0
                    return math.factorial(a) * math.factorial(b)

        o = [x for x in range(1, n + 1) if x % 2]
        e = [x for x in range(1, n + 1) if not x % 2]
        if k > cnt(len(o), len(e), None):
            return []
        r = []
        req = None
        for _ in range(n):
            c = sorted(o + e) if req is None else (o if req == 1 else e)
            f = False
            for x in c:
                if x % 2:
                    nr = 0
                    na = len(o) - 1
                    nb = len(e)
                else:
                    nr = 1
                    na = len(o)
                    nb = len(e) - 1
                cval = cnt(na, nb, nr)
                if k > cval:
                    k -= cval
                else:
                    r.append(x)
                    (o if x % 2 else e).remove(x)
                    req = nr
                    f = True
                    break
            if not f:
                return []
        return r

class Solution:
    def permute(self, nums: List[int]) -> List[List[int]]:
        n = len(nums)
        paths = [([num], {num}, 1) for num in nums]
        while paths[0][2] < n:
            curr, currSet, l = paths.pop(0)
            for num in nums:
                if num not in currSet:
                    paths.append((curr + [num], currSet.union({num}), l + 1))
        return [perm[0] for perm in paths]

from bisect import *

def larger(arr, val):
    beg = 0
    end = len(arr) - 1
    res = -1
    while beg <= end:
        mid = (beg + end) // 2
        if arr[mid] >= val:
            res = arr[mid]
            end = mid - 1
        else:
            beg = mid + 1
    return res

def smaller(arr, val):
    beg = 0
    end = len(arr) - 1
    res = -1
    while beg <= end:
        mid = (beg + end) // 2
        if arr[mid] <= val:
            res = arr[mid]
            beg = mid + 1
        else:
            end = mid - 1
    return res

class Solution:
    def platesBetweenCandles(self, s: str, queries: List[List[int]]) -> List[int]:
        n = len(s)
        plates = [i for i in range(n) if s[i] == '*']
        candles = [i for i in range(n) if s[i] == '|']
        res = []
        for l, r in queries:
            l = larger(candles, l)
            r = smaller(candles, r)
            if l >= r or l == - 1 or r == -1:
                res.append(0)
                continue
            res.append(bisect_right(plates, r) - bisect_left(plates, l))
        return res

class Solution:
    def plusOne(self, digits: List[int]) -> List[int]:
        carry = 1
        i = len(digits) - 1
        while carry > 0 and i >= 0:
            val = digits[i] + carry
            digits[i] = val % 10
            carry = val // 10
            i -= 1
        if carry > 0:
            digits.insert(0, carry)
        return digits

class Solution:
    def numberOfPoints(self, nums: List[List[int]]) -> int:
        ctr = [0] * 102
        for a, b in nums:
            ctr[a] += 1
            ctr[b + 1] -= 1
        for i in range(1, 102):
            ctr[i] += ctr[i - 1]
        return len(ctr) - ctr.count(0)

class Solution:
    def poorPigs(self, buckets: int, minutesToDie: int, minutesToTest: int) -> int:
        T = minutesToTest // minutesToDie
        x = 0
        while (T + 1) ** x < buckets:
            x += 1
        return x

class Solution:
    def largeGroupPositions(self, s: str) -> List[List[int]]:
        n = len(s)
        i = 0
        op = []
        while i < n:
            ctr = 1
            while i < n - 1 and s[i] == s[i + 1]:
                ctr += 1
                i += 1
            i += 1
            if ctr >= 3:
                op.append([i - ctr, i - 1])
        return op

from collections import defaultdict

class Solution:
    def possibleBipartition(self, n: int, dislikes: List[List[int]]) -> bool:
        graph = defaultdict(set)
        for a, b in dislikes:
            graph[a - 1].add(b - 1)
            graph[b - 1].add(a - 1)
        stack = []
        color = [None] * n
        v = set()
        for i in graph:
            if i not in v:
                v.add(i)
                stack.append(i)
                color[i] = 0
                while len(stack) > 0:
                    curr = stack.pop()
                    for j in graph[curr]:
                        if color[j] != None and color[j] == color[curr]:
                            return False
                        if j not in v:
                            v.add(j)
                            stack.append(j)
                            color[j] = 1 - color[curr]
        return True

class Solution:
    def isPowerOfFour(self, n: int) -> bool:
        if n <= 0:
            return False
        if n == 1:
            return True
        return not n & 3 and self.isPowerOfFour(n >> 2)

class Solution:
    def isPowerOfThree(self, n: int) -> bool:
        if n <= 0:
            return False
        while n % 3 == 0:
            n = n // 3
        return n == 1

class Solution:
    def isPowerOfTwo(self, n: int) -> bool:
        if n <= 0:
            return False
        if n == 1:
            return True
        return not (n & 1) and self.isPowerOfTwo(n >> 1)

import heapq

class Solution:
    def powerfulIntegers(self, x: int, y: int, bound: int) -> List[int]:
        res = []
        heap = [(2, 1, 1)]
        v = {(1, 1)}
        while heap:
            val, i, j = heapq.heappop(heap)
            if val > bound:
                break
            if not res or val != res[-1]:
                res.append(val)
            for a, b in [(i * x, j), (i, j * y)]:
                if (a, b) not in v:
                    v.add((a, b))
                    heapq.heappush(heap, (a + b, a, b))
        return res

class Solution:
    def myPow(self, x: float, n: int) -> float:
        if n < 0:
            return 1 / self.myPow(x, -n)
        if n == 0:
            return 1
        sub = self.myPow(x, n // 2)
        res = sub * sub
        if n % 2 == 1:
            res *= x
        return res

class Solution:
    def canWin(self, nums, i, j, ascore, bscore, aturn):
        if i > j:
            if aturn:
                return ascore >= bscore
            return bscore > ascore
        if aturn:
            return not self.canWin(nums, i + 1, j, ascore + nums[i], bscore, False) or not self.canWin(nums, i, j - 1, ascore + nums[j], bscore, False)
        return not self.canWin(nums, i + 1, j, ascore, bscore + nums[i], True) or not self.canWin(nums, i, j - 1, ascore, bscore + nums[j], True)

    def PredictTheWinner(self, nums: List[int]) -> bool:
        n = len(nums)
        return self.canWin(nums, 0, n - 1, 0, 0, True)

class WordFilter:
    def __init__(self, words: List[str]):
        self.vals = {}
        for pos in range(len(words)):
            n = len(words[pos])
            for i in range(1, n + 1):
                for j in range(1, n + 1):
                    self.vals[(words[pos][:i], words[pos][n-j:])] = pos

    def f(self, pref: str, suff: str) -> int:
        return self.vals.get((pref, suff), -1)

class Solution:
    def preimageSizeFZF(self, k: int) -> int:
        def count(z):
            def zeroes(v):
                p = 5
                res = 0
                while p <= v:
                    res += v // p
                    p *= 5
                return res
            end = 1
            while zeroes(end) <= z:
                end *= 2
            beg = end // 2
            while beg <= end:
                mid = (beg + end) // 2
                if zeroes(mid) <= z:
                    beg = mid + 1
                else:
                    end = mid - 1
            return beg - 1
        return count(k) - count(k - 1)

class Solution:
    def prevPermOpt1(self, arr: List[int]) -> List[int]:
        n = len(arr)
        for i in range(n - 2, -1, -1):
            j = max(range(i + 1, n), key = lambda x: arr[x] if arr[x] < arr[i] else float('-inf'))
            if arr[i] > arr[j]:
                arr[i], arr[j] = arr[j], arr[i]
                break
        return arr

import math

class Solution:
    def isPrime(self, n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(math.sqrt(n)) + 1, 2):
            if n % i == 0:
                return False
        return True

    def factorial(self, n):
        if n <= 1:
            return 1
        return n * self.factorial(n - 1)

    def numPrimeArrangements(self, n: int) -> int:
        numPrimes = 0
        for i in range(1, n + 1):
            if self.isPrime(i):
                numPrimes += 1
        return (self.factorial(numPrimes) * self.factorial(n - numPrimes)) % (10 ** 9 + 7)

class Solution:
    def diagonalPrime(self, nums: List[List[int]]) -> int:
        N = max(max(r) for r in nums)
        primes = [True] * (N + 1)
        primes[0] = primes[1] = False
        i = 0
        while i * i <= N:
            if primes[i]:
                j = i * i
                while j <= N:
                    primes[j] = False
                    j += i
            i += 1
        res = 0
        m = len(nums)
        n = len(nums[0])
        for i in range(m):
            for j in range(n):
                if i - j == 0 or i + j == n - 1:
                    if primes[nums[i][j]]:
                        res = max(res, nums[i][j])
        return res

class Solution:
    def countPrimeSetBits(self, left: int, right: int) -> int:
        isPrime = [True] * 33
        isPrime[0], isPrime[1] = False, False
        for i in range(33):
            if isPrime[i]:
                for j in range(2, 1 + 32 // i):
                    isPrime[i * j] = False
        ctr = 0
        for i in range(left, right + 1):
            curr = "{:b}".format(i).count("1")
            if isPrime[curr]:
                ctr += 1
        return ctr

class Solution:
    def findPrimePairs(self, n: int) -> List[List[int]]:
        N = 1 + n
        sp = [1] * N
        v = [False] * N
        for i in range(2, N, 2):
            sp[i] = 2
        for i in range(3, N, 2):
            if not v[i]:
                sp[i] = i
                j = i
                while j * i < N:
                    v[j * i] = True
                    sp[j * i] = i
                    j += 2
        plist = [i for i in range(2, n + 1) if sp[i] == i]
        res = []
        seen = set()
        for p in plist:
            seen.add(p)
            if n - p in seen:
                res.append((n - p, p))
        res.sort()
        return res

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def mid(a, b):
    x = a[0] * b[1] + a[1] * b[0]
    y = 2 * a[1] * b[1]
    mul = gcd(x, y)
    x //= mul
    y //= mul
    return (x, y)

class Solution:
    def printTree(self, root: Optional[TreeNode]) -> List[List[str]]:
        res = []
        M = 0
        def dfs(rt, l, r, d):
            if not rt:
                return
            nonlocal res, M
            m = mid(l, r)
            M = max(M, m[1])
            if d + 1 > len(res):
                res.append([])
            res[d].append((m, rt.val))
            dfs(rt.left, l, m, d + 1)
            dfs(rt.right, m, r, d + 1)
        dfs(root, (0, 1), (1, 1), 0)
        def get(arr):
            val = [""] * (M - 1)
            for pos, v in arr:
                val[pos[0] * M // pos[1] - 1] = str(v)
            return val
        return [get(el) for el in res]

class Foo:
    def __init__(self):
        self.f = False
        self.s = False

    def first(self, printFirst: 'Callable[[], None]') -> None:
        printFirst()
        self.f = True

    def second(self, printSecond: 'Callable[[], None]') -> None:
        while not self.f:
            pass
        printSecond()
        self.s = True

    def third(self, printThird: 'Callable[[], None]') -> None:
        while not self.f or not self.s:
            pass
        printThird()

class Solution:
    def printVertically(self, s: str) -> List[str]:
        words = s.split()
        n = max([len(w) for w in words])
        res = [[] for _ in range(n)]
        for w in words:
            for i in range(n):
                if i < len(w):
                    res[i].append(w[i])
                else:
                    res[i].append(" ")
        return ["".join(row).rstrip() for row in res]

class DSU:
    def __init__(self, n):
        self.p = list(range(n))
        self.sz = [1] * n
        self.history = []
        self.components = n

    def find(self, x):
        return x if self.p[x] == x else self.find(self.p[x])

    def union(self, a, b):
        a = self.find(a)
        b = self.find(b)
        if self.sz[a] < self.sz[b]:
            a, b = b, a
        self.history.append((self.sz, a, self.sz[a]))
        self.history.append((self.p, b, self.p[b]))
        self.history.append((self, "components", self.components))
        if a != b:
            self.p[b] = a
            self.sz[a] += self.sz[b]
            self.components -= 1

    def rollback(self):
        for _ in range(3):
            arr, index, old_value = self.history.pop()
            if isinstance(arr, DSU):
                setattr(arr, index, old_value)
            else:
                arr[index] = old_value

class Solution:
    def friendRequests(self, n: int, restrictions: List[List[int]], requests: List[List[int]]) -> List[bool]:
        dsu = DSU(n)
        g = [[] for _ in range(n)]
        for u, v in restrictions:
            g[u].append(v)
            g[v].append(u)
        res = []
        for u, v in requests:
            dsu.union(u, v)
            allowed = True
            for x, y in restrictions:
                if dsu.find(x) == dsu.find(y):
                    allowed = False
                    break
            res.append(allowed)
            if not allowed:
                dsu.rollback()
        return res

class ProductOfNumbers:
    def __init__(self):
        self.LOG = 20
        self.dp = [[1] * self.LOG]
        self.parent = [[0] * self.LOG]

    def add(self, num: int) -> None:
        i = len(self.dp)
        ndp = [num] + [1] * (self.LOG - 1)
        npar = [i - 1] + [0] * (self.LOG - 1)
        for j in range(1, self.LOG):
            npar[j] = self.parent[npar[j - 1]][j - 1]
            ndp[j] = ndp[j - 1] * self.dp[npar[j - 1]][j - 1]
        self.dp.append(ndp)
        self.parent.append(npar)

    def getProduct(self, k: int) -> int:
        pos, res, bit = len(self.dp) - 1, 1, 0
        while k:
            if k & 1:
                res *= self.dp[pos][bit]
                pos = self.parent[pos][bit]
            k //= 2
            bit += 1
        return res

M = 10 ** 9 + 7

class Solution:
    def count(self, i, rem, curr, group, profit):
        if i >= len(group):
            if curr >= 0:
                return 1
            return 0
        key = (i, rem, curr)
        if key in self.cache:
            return self.cache[key]
        res = 0
        res += self.count(i + 1, rem, curr, group, profit)
        if rem >= group[i]:
            res += self.count(i + 1, rem - group[i], curr + profit[i], group, profit)
        res %= M
        self.cache[key] = res
        return res

    def profitableSchemes(self, n: int, minProfit: int, group: List[int], profit: List[int]) -> int:
        m = len(group)
        self.cache = {}
        seq = sorted(range(m), key = lambda i: -group[i])
        group = [group[i] for i in seq]
        profit = [profit[i] for i in seq]
        return self.count(0, n, -minProfit, group, profit)

class Solution:
    def numberOfComponents(self, p: List[List[int]], k: int) -> int:
        n = len(p)
        g = [[] for _ in range(n)]
        for i in range(n):
            s = set(p[i])
            for j in range(i + 1, n):
                if len(s.intersection(p[j])) >= k:
                    g[i].append(j)
                    g[j].append(i)
        v = [False] * n
        def dfs(u):
            v[u] = True
            for w in g[u]:
                if not v[w]:
                    dfs(w)
        comp = 0
        for i in range(n):
            if not v[i]:
                comp += 1
                dfs(i)
        return comp

