            self.inorder(root.left, ctr)
            self.inorder(root.right, ctr)
            if not root.left and not root.right:
                if ctr in target:
                    self.res += 1

    def pseudoPalindromicPaths (self, root: Optional[TreeNode]) -> int:
        self.res = 0
        self.inorder(root, 0)
