class NumMatrix:
    def __init__(self, matrix: List[List[int]]):
        m = len(matrix)
        n = len(matrix[0])
        self.sums = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                self.sums[i][j] = matrix[i - 1][j - 1] + self.sums[i][j - 1] + self.sums[i - 1][j] - self.sums[i - 1][j - 1]

    def sumRegion(self, row1: int, col1: int, row2: int, col2: int) -> int:
        c = self.sums[row2 + 1][col2 + 1]
        l = self.sums[row2 + 1][col1]
        t = self.sums[row1][col2 + 1]
        s = self.sums[row1][col1]
        return c - l - t + s

class NumArray:
    def __init__(self, nums: List[int]):
        self.cache = {}
        for i in range(len(nums)):
            self.cache[(i, i + 1)] = nums[i]

    def sum(self, l, r):
        if (l, r) in self.cache:
            return self.cache[(l, r)]
        mid = (l + r) // 2
        res = self.sum(l, mid) + self.sum(mid, r)
        self.cache[(l, r)] = res
        return res

    def sumRange(self, left: int, right: int) -> int:
        return self.sum(left, right + 1)

class NumArray:
    def __init__(self, nums: List[int]):
        n = len(nums)
        self.nums = nums
        self.tree = {}
        self.build(0, n, 1)

    def build(self, i, j, k):
        if i + 1 == j:
            self.tree[k] = self.nums[i]
            return
        mid = (i + j) // 2
        l = self.build(i, mid, 2 * k)
        r = self.build(mid, j, 2 * k + 1)
        self.tree[k] = self.tree.get(2 * k, 0) + self.tree.get(2 * k + 1, 0)

    def upd(self, index, val, i, j, k):
        if i + 1 == j:
            self.tree[k] = val
            return
        mid = (i + j) // 2
        if index < mid:
            self.upd(index, val, i, mid, 2 * k)
        else:
            self.upd(index, val, mid, j, 2 * k + 1)
        self.tree[k] = self.tree.get(2 * k, 0) + self.tree.get(2 * k + 1, 0)

    def query(self, x, y, i, j, k):
        if y - 1 < i or x >= j:
            return 0
        if i >= x and j <= y:
            return self.tree[k]
        mid = (i + j) // 2
        return self.query(x, y, i, mid, 2 * k) + self.query(x, y, mid, j, 2 * k + 1)

    def update(self, index: int, val: int) -> None:
        self.upd(index, val, 0, len(self.nums), 1)

    def sumRange(self, left: int, right: int) -> int:
        return self.query(left, right + 1, 0, len(self.nums), 1)

