class Solution:
    def minCost(self, basket1: List[int], basket2: List[int]) -> int:
        f = Counter()
        for el in basket1:
            f[el] += 1
        for el in basket2:
            f[el] -= 1
        for el in f.values():
            if el & 1:
                return -1
        v = []
        for el, c in sorted(f.items()):
            v.extend([el] * (abs(c) // 2))
        if not v:
            return 0
        m = min(f)
        return sum(min(2 * m, x) for x in v[:len(v)//2])

class Solution:
    def reconstructMatrix(self, upper: int, lower: int, colsum: List[int]) -> List[List[int]]:
        n = len(colsum)
        op = [[0 for i in range(n)] for j in range(2)]
        ctr = []
        for i in range(n):
            if colsum[i] == 2:
                op[0][i] = 1
                upper -= 1
                op[1][i] = 1
                lower -= 1
            elif colsum[i] == 1:
                ctr.append(i)
        if upper >= 0 and lower >= 0 and upper + lower == len(ctr):
            if upper > 0:
                for i in ctr[:upper]:
                    op[0][i] = 1
            if lower > 0:
                for i in ctr[-lower:]:
                    op[1][i] = 1
            return op
        return []

from collections import defaultdict

class Solution:
    def findItinerary(self, tickets: List[List[str]]) -> List[str]:
        tickets.sort()
        graph = defaultdict(list)
        for a, b in tickets:
            graph[a].append(b)
        res = ["JFK"]
        def DFS(curr):
            if len(res) == len(tickets) + 1:
                return True
            if len(graph[curr]) == 0:
                return False
            nb = list(graph[curr])
            for i, v in enumerate(nb):
                res.append(v)
                graph[curr].pop(i)
                if DFS(v):
                    return True
                graph[curr].insert(i, v)
                res.pop()
        DFS("JFK")
        return res

class Solution:
    def recoverFromPreorder(self, traversal: str, d = 0) -> Optional[TreeNode]:
        if len(traversal) == 0:
            return None
        val = 0
        for c in traversal:
            if c == '-':
                break
            val = 10 * val + int(c)
        res = TreeNode(val)
        f = s = len(traversal)
        dash = 0
        for i in range(len(traversal)):
            if traversal[i] == '-':
                dash += 1
                if i + 1 < len(traversal) and dash == d + 1 and traversal[i + 1] != '-':
                    if f == len(traversal):
                        f = i + 1
                    else:
                        s = i + 1
            else:
                dash = 0
        last = len(traversal)
        if s != len(traversal):
            last = s - d - 1
        res.left = self.recoverFromPreorder(traversal[f:last], d + 1)
        res.right = self.recoverFromPreorder(traversal[s:], d + 1)
        return res

class Solution:
    def computeArea(self, ax1: int, ay1: int, ax2: int, ay2: int, bx1: int, by1: int, bx2: int, by2: int) -> int:
        cx1 = max(ax1, bx1)
        cx2 = min(ax2, bx2)
        cy1 = max(ay1, by1)
        cy2 = min(ay2, by2)
        return (ax2 - ax1) * (ay2 - ay1) + (bx2 - bx1) * (by2 - by1) - max(cx2 - cx1, 0) * max(cy2 - cy1, 0)

class Solution:
    def makeEqual(self, words: List[str]) -> bool:
        n = len(words)
        ctr = [0] * 26
        for w in words:
            for c in w:
                ctr[ord(c) - ord('a')] += 1
        for i in ctr:
            if i % n != 0:
                return False
        return True

import heapq

class Solution:
    def minSetSize(self, arr: List[int]) -> int:
        n = len(arr)
        ctr = {}
        for num in arr:
            ctr[num] = ctr.get(num, 0) + 1
        heap = [(-v, k) for k, v in ctr.items()]
        heapq.heapify(heap)
        i = 0
        size = 0
        while size < n / 2:
            v, k = heapq.heappop(heap)
            size -= v
            i += 1
        return i

class Solution:
    def maxsat(self, satisfaction, i, n, t):
        if i >= n:
            return 0
        if (i, t) in self.cache:
            return self.cache[(i, t)]
        a = self.maxsat(satisfaction, i + 1, n, t)
        b = satisfaction[i] * t + self.maxsat(satisfaction, i + 1, n, t + 1)
        res = max(a, b)
        self.cache[(i, t)] = res
        return res

    def maxSatisfaction(self, satisfaction: List[int]) -> int:
        n = len(satisfaction)
        satisfaction.sort()
        self.cache = {}
        return self.maxsat(satisfaction, 0, n, 1)

