from collections import deque

class Solution:
    def findRedundantDirectedConnection(self, edges):
        n = len(edges)
        indegree = [0] * n
        graph = [[] for _ in range(n)]
        for a, b in edges:
            a -= 1
            b -= 1
            graph[a].append(b)
            indegree[b] += 1
        z = indegree.count(0)
        for a, b in edges[::-1]:
            a -= 1
            b -= 1
            if z + int(indegree[b] == 1) != 1:
                continue
            deg = indegree[:]
            deg[b] -= 1
            q = deque()
            ctr = 0
            for i in range(n):
                if deg[i] == 0:
                    q.appendleft(i)
            while len(q) > 0:
                curr = q.pop()
                ctr += 1
                for j in graph[curr]:
                    if (curr, j) == (a, b):
                        continue
                    deg[j] -= 1
                    if deg[j] == 0:
                        q.appendleft(j)
            if ctr == n:
                return [a + 1, b + 1]

from collections import defaultdict

class Solution:
    def DFS(self, graph, i, v, a, b):
        for j in graph[i]:
            if j not in v and (i, j) != (a, b) and (i, j) != (b, a):
                v.add(j)
                self.DFS(graph, j, v, a, b)

    def findRedundantConnection(self, edges: List[List[int]]) -> List[int]:
        graph = defaultdict(set)
        for a, b in edges:
            graph[a].add(b)
            graph[b].add(a)
        for a, b in edges[::-1]:
            v = {a}
            self.DFS(graph, a, v, a, b)
            if len(v) == len(graph):
                return [a, b]

from collections import *

class Solution:
    def regionsBySlashes(self, grid: List[str]) -> int:
        n = len(grid)
        graph = defaultdict(list)
        for i in range(n):
            for j in range(n):
                for x, y, s, p in [(i, j - 1, 3, 1), (i - 1, j, 0, 2), (i, j + 1, 1, 3), (i + 1, j, 2, 0)]:
                    if 0 <= x < n and 0 <= y < n:
                        graph[(i, j, s)].append((x, y, p))
                        graph[(x, y, p)].append((i, j, s))
                ops = []
                if grid[i][j] == '/' or grid[i][j] == ' ':
                    ops.extend([(2, 1), (3, 0)])
                if grid[i][j] == '\\' or grid[i][j] == ' ':
                    ops.extend([(0, 1), (2, 3)])
                for x, y in ops:
                    graph[(i, j, x)].append((i, j, y))
                    graph[(i, j, y)].append((i, j, x))
        res = 0
        v = set()
        def dfs(x):
            v.add(x)
            for y in graph.get(x, []):
                if y not in v:
                    dfs(y)
        for x in graph:
            if x not in v:
                res += 1
                dfs(x)
        return res

class Solution:
    def isSame(self, a, b):
        if a == "." or b == ".":
            return True
        return a == b

    def isMatchRec(self, s, p, i, j, m, n):
        if i >= m:
            if j >= n:
                return True
            return j < n - 1 and p[j + 1] == "*" and self.isMatchRec(s, p, i, j + 2, m, n)
        if j >= n:
            return i >= m
        if j == n - 1 or p[j + 1] != "*":
            return self.isSame(s[i], p[j]) and self.isMatchRec(s, p, i + 1, j + 1, m, n)
        if p[j + 1] == "*":
            return self.isMatchRec(s, p, i, j + 2, m, n) or (self.isSame(s[i], p[j]) and self.isMatchRec(s, p, i + 1, j, m, n))
        return False

    def isMatch(self, s: str, p: str) -> bool:
        m = len(s)
        n = len(p)
        return self.isMatchRec(s, p, 0, 0, m, n)

class Solution:
    def findRelativeRanks(self, score: List[int]) -> List[str]:
