class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.numsets = n

    def find(self, a):
        if a == self.parent[a]:
            return a
        self.parent[a] = self.find(self.parent[a])
        return self.parent[a]

    def union(self, a, b):
        parent_a = self.find(a)
        parent_b = self.find(b)
        if parent_a != parent_b:
            if self.size[parent_a] < self.size[parent_b]:
                parent_a, parent_b = parent_b, parent_a
            self.parent[parent_b] = parent_a
            self.size[parent_a] += self.size[parent_b]
            self.numsets -= 1

class Solution:
    def maxNumEdgesToRemove(self, n: int, edges: List[List[int]]) -> int:
        alice = DSU(n)
        bob = DSU(n)
        used = 0
        for t, a, b in edges:
            a -= 1
            b -= 1
            if t == 3:
                if alice.find(a) != alice.find(b) and bob.find(a) != bob.find(b):
                    alice.union(a, b)
                    bob.union(a, b)
                    used += 1
        for t, a, b in edges:
            a -= 1
            b -= 1
            if t == 1:
                if alice.find(a) != alice.find(b):
                    alice.union(a, b)
                    used += 1
            if t == 2:
                if bob.find(a) != bob.find(b):
                    bob.union(a, b)
                    used += 1
            if alice.numsets == 1 and bob.numsets == 1:
                return len(edges) - used
        return -1

class Solution:
    def remainingMethods(self, n: int, k: int, invocations: List[List[int]]) -> List[int]:
        graph = [[] for _ in range(n)]
        rgraph = [[] for _ in range(n)]
        for a, b in invocations:
            graph[a].append(b)
            rgraph[b].append(a)
        bad = {k}
        stack = [k]
        while stack:
            i = stack.pop()
            for j in graph[i]:
                if j not in bad:
                    bad.add(j)
                    stack.append(j)
        for i in bad:
            for j in rgraph[i]:
                if j not in bad:
                    return list(range(n))
        return [i for i in range(n) if i not in bad]

class Solution:
    def removeNodes(self, head: Optional[ListNode]) -> Optional[ListNode]:
        vals = []
        curr = head
        while curr:
            vals.append(curr.val)
            curr = curr.next
        n = len(vals)
        rem = [False] * n
        mval = float('-inf')
        for i in range(n - 1, -1, -1):
            if vals[i] < mval:
                rem[i] = True
            mval = max(mval, vals[i])
        nodes = []
        curr = head
        i = 0
        while curr:
            if not rem[i]:
                nodes.append(curr)
            curr = curr.next
            i += 1
        n = len(nodes)
        for i in range(n - 1):
            nodes[i].next = nodes[i + 1]
        return nodes[0]

class Solution:
    def removeNthFromEnd(self, head, n):
        slow = head
        fast = head
        for _ in range(n):
            fast = fast.next
        while fast and fast.next:
            slow = slow.next
            fast = fast.next
        if slow == head and not fast:
            return head.next
        slow.next = slow.next.next
        return head

class Solution:
