class Node:
    def __init__(self):
        self.children = {}
        self.end = False

class Solution:
    def removeSubfolders(self, folder: List[str]) -> List[str]:
        trie = Node()
        for path in folder:
            curr = trie
            for c in path.split("/"):
                if c not in curr.children:
                    curr.children[c] = Node()
                curr = curr.children[c]
            curr.end = True
        res = []
        def dfs(curr, path):
            if curr.end:
                res.append(path)
                return
            for c in curr.children:
                dfs(curr.children[c], path + ("/" if curr != trie else "") + c)
        dfs(trie, "")
        return res

class Solution:
    def removeZeroSumSublists(self, head: Optional[ListNode]) -> Optional[ListNode]:
        if head:
            total = 0
            curr = head
            while curr:
                total += curr.val
                if total == 0:
                    return self.removeZeroSumSublists(curr.next)
                curr = curr.next
            head.next = self.removeZeroSumSublists(head.next)
        return head

class Solution:
    def minimumDeletions(self, nums: List[int]) -> int:
        n = len(nums)
        a = min(nums)
        b = max(nums)
        i = nums.index(a)
        j = nums.index(b)
        i, j = min(i, j), max(i, j)
        return min(i + 1 + n - j, j + 1, n - i)

class Solution:
    def minimumRemoval(self, beans: List[int]) -> int:
        n = len(beans)
        beans.sort()
        total = sum(beans)
        cost = total
        for i in range(n):
            currcost = total - (n - i) * beans[i]
            cost = min(cost, currcost)
        return cost

