        return "".join(stack)

class Solution:
    def reorderList(self, head: Optional[ListNode]) -> None:
        curr = head
        curr.prev = None
        n = 1
        while curr and curr.next:
            curr.next.prev = curr
            curr = curr.next
            n += 1
        if n <= 2:
            return
        beg = head
        while beg and curr:
            newbeg = beg.next
            newcurr = curr.prev
            beg.next, curr.next = curr, beg.next
            beg = newbeg
            curr = newcurr
            if newbeg and newcurr and (newbeg == newcurr or newbeg.next == newcurr):
                if newbeg != newcurr:
                    newcurr.prev.next = None
                newcurr.next = None

from collections import defaultdict, deque

class Solution:
    def minReorder(self, n: int, connections: List[List[int]]) -> int:
        graph = defaultdict(set)
        for a, b in connections:
            graph[a].add((b, 1))
            graph[b].add((a, 0))
        res = 0
        q = deque([(0, -1)])
        while len(q) > 0:
            i, prev = q.pop()
            for j, c in graph[i]:
                if j != prev:
                    res += c
                    q.appendleft((j, i))
        return res

class Solution:
    def reorderedPowerOf2(self, n: int) -> bool:
        l = len(str(n))
        k = 0
        currlen = len(str(1 << k))
        sortedval = sorted(str(n))
        while currlen <= l:
            if currlen == l:
                if sorted(str(1 << k)) == sortedval:
                    return True
            k += 1
            currlen = len(str(1 << k))
        return False

import heapq

class Solution:
    def reorganizeString(self, s: str) -> str:
        op = ""
        ctr = {}
        for c in s:
            ctr[c] = ctr.get(c, 0) + 1
        heap = [(-n, c) for c, n in ctr.items()]
        hlen = len(heap)
        heapq.heapify(heap)
        while len(heap) > 0:
            currn, currc = heapq.heappop(heap)
            if currc != op[-1] if len(op) > 0 else True:
                op += currc
                if currn + 1 < 0:
                    heapq.heappush(heap, (currn + 1, currc))
            else:
                if len(heap) == 0:
                    return ""
                nextn, nextc = heapq.heappop(heap)
                op += nextc
                heapq.heappush(heap, (currn, currc))
                if nextn + 1 < 0:
                    heapq.heappush(heap, (nextn + 1, nextc))
        return op

class Solution:
    def findRepeatedDnaSequences(self, s: str) -> List[str]:
        n = len(s)
        ctr = {}
        for i in range(0, n - 9):
            curr = s[i:i+10]
            ctr[curr] = ctr.get(curr, 0) + 1
        return [patt for patt, freq in ctr.items() if freq > 1]

class Solution:
    def possible(self, a, b, n):
        return b in a * n

    def repeatedStringMatch(self, a: str, b: str) -> int:
        end = 1
        while not self.possible(a, b, end):
            end *= 2
            if end > 2 and len(a) * end > len(b) * 3:
                return -1
        beg = end // 2
        res = end
        while beg <= end:
            mid = (beg + end) // 2
            if self.possible(a, b, mid):
                res = mid
                end = mid - 1
            else:
                beg = mid + 1
        return res

class Solution:
    def factors(self, n):
        N = n
        i = 2
        factors = set()
        while i * i <= n:
            if n % i:
                i += 1
                continue
            while n % i == 0:
                n //= i
            factors.add(i)
        if n > 1:
            factors.add(n)
        return factors

    def repeatedSubstringPattern(self, s: str) -> bool:
        n = len(s)
        for p in self.factors(n):
            l = n // p
            found = True
            for i in range(n):
                if s[i] != s[i % l]:
                    found = False
                    break
            if found:
                return True
        return False

class Solution:
    def replaceDigits(self, s: str) -> str:
