class Solution:
    def arrayChange(self, nums: List[int], operations: List[List[int]]) -> List[int]:
        n = len(nums)
        pos = {}
        for i in range(n):
            pos[nums[i]] = i
        for a, b in operations:
            i = pos[a]
            nums[i] = b
            pos[b] = i
        return nums

class Solution:
    def gcd(self, a, b):
        while b:
            a, b = b, a % b
        return a

    def replaceNonCoprimes(self, nums: List[int]) -> List[int]:
        n = len(nums)
        stack = [nums[0]]
        for i in range(1, n):
            currval = nums[i]
            while len(stack) > 0 and self.gcd(stack[-1], currval) > 1:
                prev = stack.pop()
                currval = prev * currval // self.gcd(prev, currval)
            stack.append(currval)
        return stack

from collections import Counter
import heapq

class Solution:
    def minimizeStringValue(self, s: str) -> str:
        n = len(s)
        add = s.count('?')
        ctr = Counter()
        og = Counter()
        for c in s:
            if c != '?':
                og[c] += 1
                ctr[c] += 1
        for c in "abcdefghijklmnopqrstuvwxyz":
            if c not in ctr:
                ctr[c] = 0
        heap = []
        for c in ctr:
            heapq.heappush(heap, (ctr[c], c))
        for _ in range(add):
            count, c = heapq.heappop(heap)
            ctr[c] += 1
            heapq.heappush(heap, (count + 1, c))
        s = list(s)
        for i in range(n):
            if s[i] == '?':
                for c in "abcdefghijklmnopqrstuvwxyz":
                    if ctr[c] <= og[c]:
                        continue
                    s[i] = c
                    ctr[c] -= 1
                    break
        return "".join(s)

class Solution:
    def replaceWords(self, dictionary: List[str], sentence: str) -> str:
        dictionary = set(dictionary)
        lens = sorted([len(w) for w in dictionary])
        words = sentence.split()
        op = []
        for w in words:
            found = False
            for l in lens:
                if w[:l] in dictionary:
                    op.append(w[:l])
                    found = True
                    break
            if not found:
                op.append(w)
        return " ".join(op)

class Solution:
    def reportSpam(self, message: List[str], bannedWords: List[str]) -> bool:
