        return len([w for w in message if w in bannedWords]) >= 2

class Solution:
    def maxFreeTime(self, eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
        n = len(startTime)
        res = 0
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] += p[i] + endTime[i] - startTime[i]
        if k == n:
            return eventTime - p[n]
        res = max(res, startTime[k] - p[k], eventTime - endTime[-(k + 1)] - p[n] + p[n - k])
        for i in range(n - k - 1):
            total = startTime[i + k + 1] - endTime[i]
            used = p[i + k + 1] - p[i + 1]
            res = max(res, total - used)
        return res

class Solution:
    def matrixReshape(self, mat: List[List[int]], r: int, c: int) -> List[List[int]]:
        m = len(mat)
        n = len(mat[0])
        if m * n != r * c:
            return mat
        for i in range(0, r * c, c):
            mat.append([])
            for j in range(i, i + c):
                mat[-1].append(mat[j // n][j % n])
        return mat[m:]

class Solution:
    def isValidChunk(self, s):
        if len(s) > 1 and s[0] == "0":
            return False
        if int(s) < 0 or int(s) > 255:
            return False
        return True

    def getAddress(self, s, curr, i, n):
        op = []
        if len(curr) == 4 and i == n:
            return [curr]
        for j in range(i + 1, n + 1):
            chunk = s[i:j]
            if self.isValidChunk(chunk):
                val = self.getAddress(s, curr + [chunk], j, n)
                op.extend(val)
        return op

    def restoreIpAddresses(self, s: str) -> List[str]:
        val = self.getAddress(s, [], 0, len(s))
        return [".".join(v) for v in val]

from collections import defaultdict

class Solution:
    def restoreArray(self, adjacentPairs: List[List[int]]) -> List[int]:
        nums = defaultdict(list)
        singles = set()
        for a, b in adjacentPairs:
            nums[a].append(b)
            nums[b].append(a)
            if a in singles:
                singles.remove(a)
            else:
                singles.add(a)
            if b in singles:
                singles.remove(b)
            else:
                singles.add(b)
        first = list(singles)[0]
        n = len(nums)
        res = []
        res.extend([first, nums[first][0]])
        while len(res) < n:
            prev = res[-1]
            prevprev = res[-2]
            res.extend([k for k in nums[prev] if k != prevprev])
        return res

class Solution:
    def numberOfArrays(self, s: str, k: int) -> int:
        n = len(s)
        M = 10 ** 9 + 7
        dp = [0] * (n + 1)
        dp[n] = 1
        for i in range(n - 1, -1, -1):
            v = 0
            for j in range(i, n):
                v = 10 * v + int(s[j])
                if 1 <= v <= k:
                    dp[i] += dp[j + 1]
                    dp[i] %= M
                else:
                    break
        return dp[0]

class Solution:
    def deckRevealedIncreasing(self, deck: List[int]) -> List[int]:
        deck.sort(reverse = True)
        n = len(deck)
        cards = deque(list(range(n - 1, -1, -1)))
        res = [-1] * n
        while cards:
            res[cards.pop()] = deck.pop()
            if cards:
                cards.appendleft(cards.pop())
        return res

