import math

class Solution:
    def reverse(self, x: int) -> int:
        LIMIT = (1 << 31) - 1
        if x == 0:
            return x
        sign = x//abs(x)
        x = abs(x)
        op = 0
        while x > 0:
            d = x % 10
            x = x // 10
            op = 10 * op + d
            if (sign == 1 and op > LIMIT) or (sign == -1 and op > LIMIT + 1):
                return 0
        return op * sign

class Solution:
    def reverseBetween(self, head: Optional[ListNode], left: int, right: int) -> Optional[ListNode]:
        curr = head
        stack = []
        i = 1
        while curr:
            if left <= i <= right:
                stack.append(curr.val)
            curr = curr.next
            i += 1
        curr = head
        i = 1
        while curr:
            if left <= i <= right:
                curr.val = stack.pop()
            curr = curr.next
            i += 1
        return head

