class Solution:
    def numberOfRightTriangles(self, grid: List[List[int]]) -> int:
        res = 0
        m = len(grid)
        n = len(grid[0])
        row = []
        col = []
        for i in range(m):
            row.append([0])
            for j in range(n):
                row[-1].append(row[-1][-1] + grid[i][j])
        for j in range(n):
            col.append([0])
            for i in range(m):
                col[-1].append(col[-1][-1] + grid[i][j])
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    top = col[j][i]
                    left = row[i][j]
                    bottom = col[j][m] - top - 1
                    right = row[i][n] - left - 1
                    res += top * left + left * bottom + bottom * right + top * right
        return res

class Solution:
    def countPoints(self, rings: str) -> int:
        n = len(rings)
        rods = [set(), set(), set()]
        for i in range(0, n, 2):
            if rings[i] == 'R':
                rods[0].add(int(rings[i + 1]))
            if rings[i] == 'G':
                rods[1].add(int(rings[i + 1]))
            if rings[i] == 'B':
                rods[2].add(int(rings[i + 1]))
        return len(set.intersection(*rods))

class Solution:
    def survivedRobotsHealths(self, positions: List[int], healths: List[int], directions: str) -> List[int]:
        n = len(positions)
        vals = [(positions[i], healths[i], directions[i], i) for i in range(n)]
        vals.sort()
        stack = []
        for p, h, d, pos in vals:
            if d == "L":
                add = True
                while stack and stack[-1][2] == "R":
                    if stack[-1][1] < h:
                        stack.pop()
                        h -= 1
                    elif stack[-1][1] > h:
                        stack[-1][1] -= 1
                        add = False
                        break
                    else:
                        stack.pop()
                        add = False
                        break
                if add:
                    stack.append([p, h, d, pos])
            else:
                stack.append([p, h, d, pos])
        stack.sort(key = lambda x: x[3])
        return [x[1] for x in stack]

class Solution:
    def judgeCircle(self, moves: str) -> bool:
        x, y = 0, 0
        for m in moves:
            if m == "U":
                y += 1
            elif m == "D":
                y -= 1
            elif m == "R":
                x += 1
            elif m == "L":
                x -= 1
        return (x, y) == (0, 0)

class Solution:
    def romanToInt(self, s: str) -> int:
        sym = {
            "I": 1,
            "V": 5,
            "X": 10,
            "L": 50,
            "C": 100,
            "D": 500,
            "M": 1000
        }
        n = len(s)
        val = 0
        for i in range(n):
            if i < n - 1 and sym[s[i]] < sym[s[i + 1]]:
                val -= sym[s[i]]
            else:
                val += sym[s[i]]
        return val

