    def checkTree(self, root: Optional[TreeNode]) -> bool:
        return root.val == root.left.val + root.right.val

class Solution:
    def reverse(self, nums, a, b):
        n = b - a
        for i in range(n // 2):
            nums[a + i], nums[a + n - i - 1] = nums[a + n - i - 1], nums[a + i]
        return nums

    def rotate(self, nums: List[int], k: int) -> None:
        n = len(nums)
        k = n - k % n
        self.reverse(nums, 0, k)
        self.reverse(nums, k, n)
        self.reverse(nums, 0, n)
        return nums

class Solution:
    def maxRotateFunction(self, nums: List[int]) -> int:
        n = len(nums)
        total = 0
        curr = 0
        for i in range(n):
            curr += i * nums[i]
            total += nums[i]
        mval = float('-inf')
        for i in range(n - 1, -1, -1):
            curr -= n * nums[i] - total
            mval = max(mval, curr)
        return mval

class Solution:
    def verticalFlip(self, matrix, n):
        for i in range(n // 2):
            for j in range(n):
                matrix[i][j], matrix[n - i - 1][j] = matrix[n - i - 1][j], matrix[i][j]

    def diagonalFlip(self, matrix, n):
        for i in range(n):
            for j in range(i, n):
                matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    def rotate(self, matrix: List[List[int]]) -> None:
        n = len(matrix)
        self.verticalFlip(matrix, n)
        self.diagonalFlip(matrix, n)

class Solution:
