class Solution:
    def rotateTheBox(self, box: List[List[str]]) -> List[List[str]]:
        m = len(box)
        n = len(box[0])
        res = [["."] * m for _ in range(n)]
        for i in range(m):
            ctr = 0
            for j in range(n):
                if box[i][j] == "#":
                    ctr += 1
                elif box[i][j] == "*":
                    res[j][m - i - 1] = "*"
                if j == n - 1 or box[i][j + 1] == "*":
                    for x in range(ctr):
                        res[j - x][m - i - 1] = "#"
                    ctr = 0
        return res

from collections import deque

class Solution:
    def orangesRotting(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        queue = deque()
        ctr = 0
        maxt = 0
        seen = set()
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 2:
                    queue.appendleft((i, j, 0))
                    seen.add((i, j))
                elif grid[i][j] == 0:
                    ctr += 1
        while len(queue) > 0:
            x, y, t = queue.pop()
            for i, j in [(x - 1, y), (x, y + 1), (x + 1, y), (x, y - 1)]:
                if 0 <= i < m and 0 <= j < n and grid[i][j] == 1:
                    if (i, j) not in seen:
                        queue.appendleft((i, j, t + 1))
                        seen.add((i, j))
            maxt = t
        if len(seen) + ctr != m * n:
            return -1
        return maxt

class Solution:
