        op = [0]
        for num in nums:
            op.append(op[-1] + num)
        return op[1:]

import bisect

class Solution:
    def maxEnvelopes(self, envelopes: List[List[int]]) -> int:
        n = len(envelopes)
        envelopes.sort(key = lambda x: (x[0], -x[1]))
        sub = []
        for w, h in envelopes:
            i = bisect.bisect_left(sub, h)
            if i == len(sub):
                sub.append(h)
            else:
                sub[i] = h
        return len(sub)

class Solution:
    def isSameTree(self, p: Optional[TreeNode], q: Optional[TreeNode]) -> bool:
        if not p or not q:
            if p or q:
                return False
            return True
        if p.val == q.val and self.isSameTree(p.left, q.left) and self.isSameTree(p.right, q.right):
            return True

class Solution:
    def equationsPossible(self, equations: List[str]) -> bool:
        equalGraph = {}
        inequalities = []
        for eq in equations:
            a = eq[0]
            b = eq[-1]
            opr = eq[1:-1]
            if opr == "==":
                equalGraph[a] = equalGraph.get(a, []) + [b]
                equalGraph[b] = equalGraph.get(b, []) + [a]
            else:
                inequalities.append((a, b))
        for a, b in inequalities:
            paths = [a]
            visited = {a}
            while len(paths) > 0:
                curr = paths.pop()
                for j in equalGraph.get(curr, []):
                    if j not in visited:
                        visited.add(j)
                        paths.append(j)
            if b in visited:
                return False
        return True

class Solution:
    def scoreOfString(self, s: str) -> int:
        return sum(abs(ord(s[i]) - ord(s[i+1])) for i in range(len(s) - 1))

class Solution:
    def scoreOfParentheses(self, s: str) -> int:
        if s == '':
            return 0.5
        score = 0
        pos = [0]
        ctr = 0
        for i, c in enumerate(s):
            if c == '(':
                ctr += 1
            else:
                ctr -= 1
            if ctr == 0:
                pos.append(i + 1)
        n = len(pos)
        for i in range(n - 1):
            score += 2 * self.scoreOfParentheses(s[pos[i] + 1 : pos[i + 1] - 1])
        return int(score)

class Solution:
    def isPos(self, s1, s2, a, b, c, d):
        n = b - a
        if n == 1:
            if s1[a] == s2[c]:
                return True
            else:
                return False
        key = (a, b, c, d)
        if key in self.cache:
            return self.cache[key]
        for l in range(1, n):
            r = n - l
            if self.isPos(s1, s2, a, a + l, c, c + l) and self.isPos(s1, s2, a + l, b, d - r, d):
                self.cache[key] = True
                return True
            if self.isPos(s1, s2, a, a + l, d - l, d) and self.isPos(s1, s2, a + l, b, c, c + r):
                self.cache[key] = True
                return True
        self.cache[key] = False
        return False

    def isScramble(self, s1: str, s2: str) -> bool:
        n = len(s1)
        self.cache = {}
        return self.isPos(s1, s2, 0, n, 0, n)

import bisect

class Solution:
    def searchMatrix(self, matrix: List[List[int]], target: int) -> bool:
        m = len(matrix)
        n = len(matrix[0])
        for i in range(m):
            j = bisect.bisect_left(matrix[i], target)
            j = min(j, n - 1)
            if matrix[i][j] == target:
                return True
        return False

class Solution:
    def searchMatrix(self, matrix: List[List[int]], target: int) -> bool:
        m = len(matrix)
        n = len(matrix[0])
        beg = 0
        end = m * n - 1
        while beg <= end:
            mid = (beg + end) // 2
            i = mid // n
            j = mid % n
            if matrix[i][j] == target:
                return True
            elif beg == end:
                break
            elif matrix[i][j] < target:
                beg = mid + 1
            else:
                end = mid
        return False

