class Solution:
    def searchBST(self, root: Optional[TreeNode], val: int) -> Optional[TreeNode]:
        if root:
            if root.val == val:
                return root
            elif val > root.val:
                return self.searchBST(root.right, val)
            else:
                return self.searchBST(root.left, val)
        else:
            return None

class Solution:
    def search(self, nums: List[int], target: int) -> int:
        n = len(nums)
        beg = 0
        end = len(nums) - 1
        while beg <= end:
            mid = (beg + end) // 2
            if nums[mid] >= nums[0]:
                beg = mid + 1
            else:
                end = mid - 1
        end = beg + n - 1
        while beg <= end:
            mid = (beg + end) // 2
            if nums[mid % n] <= target:
                beg = mid + 1
            else:
                end = mid - 1
        if nums[(beg - 1) % n] != target:
            return -1
        return (beg - 1) % n

class Solution:
    def searchInsert(self, nums: List[int], target: int) -> int:
        n = len(nums)
        beg = 0
        end = n - 1
        res = n
        while beg <= end:
            mid = (beg + end) // 2
            if nums[mid] >= target:
                res = mid
                end = mid - 1
            else:
                beg = mid + 1
        return res

class Node:
    def __init__(self, val, children, words):
        self.val = val
        self.children = children
        self.words = words

class Trie:
    def __init__(self):
        self.root = Node(None, {}, set())

    def insert(self, word, pos) -> None:
        n = len(word)
        curr = self.root
        for i, c in enumerate(word):
            if c in curr.children:
                curr = curr.children[c]
            else:
                newcurr = Node(c, {}, set())
                curr.children[c] = newcurr
                curr = newcurr
            curr.words.add(pos)

    def startsWith(self, prefix, res):
        n = len(prefix)
        curr = self.root
        for i, c in enumerate(prefix):
            if c in curr.children:
                curr = curr.children[c]
                res.append(curr.words)
            else:
                return set()
        return curr.words

class Solution:
    def suggestedProducts(self, products: List[str], searchWord: str) -> List[List[str]]:
        n = len(searchWord)
        trie = Trie()
        for i, product in enumerate(products):
            trie.insert(product, i)
        res = []
        trie.startsWith(searchWord, res)
        while len(res) < n:
            res.append({})
        return [sorted([products[i] for i in curr])[:3] for curr in res]

import heapq

class SeatManager:
    def __init__(self, n: int):
        self.unreserved = []
        for s in range(1, n + 1):
            heapq.heappush(self.unreserved, s)

    def reserve(self) -> int:
        return heapq.heappop(self.unreserved)

    def unreserve(self, seatNumber: int) -> None:
        heapq.heappush(self.unreserved, seatNumber)

from collections import *

class Solution:
    def secondMinimum(self, n: int, edges: List[List[int]], time: int, change: int) -> int:
        graph = [[] for _ in range(n)]
        for u, v in edges:
            u -= 1
            v -= 1
            graph[u].append(v)
            graph[v].append(u)
        def get(x):
            res = 0
            for _ in range(x - 1):
                res += time;
                if (res // change) % 2:
                    res = (res // change + 1) * change
            return res + time
        q = deque([0])
        dist = [float('inf')] * n
        steps = 0
        while q:
            if steps > dist[n - 1] + 1:
                break
            for _ in range(len(q)):
                i = q.pop()
                if steps == dist[i] or steps > dist[i] + 1:
                    continue
                dist[i] = min(dist[i], steps)
                if i == n - 1 and steps > dist[n - 1]:
                    return get(steps)
                for j in graph[i]:
                    q.appendleft(j)
            steps += 1
        return get(dist[n - 1] + 2)

class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        n = len(grid)
        vals = {}
        for i in range(n):
            for h in grid[i]:
                if h not in vals:
                    vals[h] = []
                vals[h].append(i)
        vals = list(vals.items())
        @lru_cache(maxsize = None)
        def maxval(i, mask):
            if i >= len(vals):
                return 0
            res = maxval(i + 1, mask)
            for j in vals[i][1]:
                if not mask & (1 << j):
                    res = max(res, vals[i][0] + maxval(i + 1, mask | (1 << j)))
            return res
        return maxval(0, 0)

class Solution:
    def check(self, intervals, k):
        intervals.sort(key=lambda x: x[1])
        count, last_end = 0, -float('inf')
        for start, end in intervals:
            if start >= last_end:
                count += 1
                last_end = end
                if count >= k:
                    return True
        return False

    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True
        n = len(s)
        p = [Counter() for _ in range(n + 1)]
        for i in range(n):
            p[i + 1] += p[i]
            p[i + 1][s[i]] += 1
        invs = []
        f = {}
        l = {}
        for i in range(n):
            if s[i] not in f:
                f[s[i]] = i
            l[s[i]] = i
        for c in f:
            left = f[c]
            right = l[c]
            while True:
                found = False
                for nc in f:
                    if p[right + 1][nc] - p[left][nc] > 0:
                        if f[nc] < left:
                            found = True
                        if l[nc] > right:
                            found = True
                        left = min(left, f[nc])
                        right = max(right, l[nc])
                if not found:
                    break
            if (left, right) == (0, n - 1):
                continue
            invs.append((left, right))
        return self.check(invs, k)

class Solution:
    def selfDividingNumbers(self, left: int, right: int) -> List[int]:
        op = []
        for i in range(left, right + 1):
            curr = i
            valid = True
            while curr != 0:
                d = curr % 10
                if d == 0 or i % d != 0:
                    valid = False
                    break
                curr //= 10
            if valid:
                op.append(i)
        return op

class Solution:
    def sellingWood(self, m: int, n: int, prices: List[List[int]]) -> int:
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for h, w, p in prices:
            dp[h][w] = p
        for h in range(m + 1):
            for w in range(n + 1):
                for hh in range(1, h):
                    dp[h][w] = max(dp[h][w], dp[hh][w] + dp[h - hh][w])
                for ww in range(1, w):
                    dp[h][w] = max(dp[h][w], dp[h][ww] + dp[h][w - ww])
        return dp[m][n]

class Solution:
    def semiOrderedPermutation(self, nums: List[int]) -> int:
        n = len(nums)
        one = nums.index(1)
        last = nums.index(n)
        if one < last:
            return one + n - last - 1
        return one - last + one + n - (one + 1) - 1

from collections import Counter

class Solution:
    def largestWordCount(self, messages: List[str], senders: List[str]) -> str:
        n = len(senders)
        ctr = Counter()
        for i in range(n):
            ctr[senders[i]] += len(messages[i].split())
        return max(senders, key = lambda sender: (ctr[sender], sender))

class Solution:
    def areSentencesSimilar(self, sentence1: str, sentence2: str) -> bool:
        a = sentence1.split()
        b = sentence2.split()
        def check(x, y):
            m = len(x)
            n = len(y)
            j = 0
            pf = [0] * (n + 1)
            sf = [0] * (n + 1)
            for i in range(m):
                if j < n and x[i] == y[j]:
                    pf[j + 1] = i + 1
                    j += 1
            j = n - 1
            for i in range(m - 1, -1, -1):
                if j >= 0 and x[i] == y[j]:
                    sf[n - j] = m - i
                    j -= 1
            for l in range(n + 1):
                if pf[l] == l and sf[n - l] == n - l:
                    return True
            return False
        return check(a, b) or check(b, a)

class Solution:
    def minimumSteps(self, s: str) -> int:
        res = o = 0
        for c in s:
            if c == "0":
                res += o
            else:
                o += 1
        return res

class Solution:
    def rectangleArea(self, rectangles):
        res = 0
        for x0, y0, x1, y1 in rectangles:
            res += (x1 - x0) * (y1 - y0)
        return res

    def split(self, squares, y):
        below = []
        above = []
        for x, yi, li in squares:
            if yi + li <= y:
                below.append((x, yi, x + li, yi + li))
            elif yi >= y:
                above.append((x, yi, x + li, yi + li))
            else:
                below.append((x, yi, x + li, y))
                above.append((x, y, x + li, yi + li))
        return below, above

    def separateSquares(self, squares: List[List[int]]) -> float:
        def check(y):
            b, a = self.split(squares, y)
            return self.rectangleArea(b) >= self.rectangleArea(a)
        end = 1
        while not check(end):
            end *= 2
        beg = end / 2
        while end - beg > 1e-6:
            mid = (beg + end) / 2
            if check(mid):
                end = mid
            else:
                beg = mid
        return end

import bisect
import math

class Solution:
    def sequentialDigits(self, low: int, high: int) -> List[int]:
        nums = "123456789"
        n = len(nums)
        a = int(1 + math.log10(low))
        b = int(1 + math.log10(high))
        op = []
        for l in range(a, b + 1):
            for i in range(n - l + 1):
                curr = int(nums[i:i + l])
                if curr >= low and curr <= high:
                    bisect.insort(op, curr)
        return op

# Definition for a binary tree node.
