class Solution:
    def setZeroes(self, matrix: List[List[int]]) -> None:
        m = len(matrix)
        n = len(matrix[0])
        rows = set()
        cols = set()
        for i in range(m):
            for j in range(n):
                if matrix[i][j] == 0:
                    rows.add(i)
                    cols.add(j)
        for i in range(m):
            for j in range(n):
                if i in rows or j in cols:
                    matrix[i][j] = 0

class Solution:
    def findErrorNums(self, nums: List[int]) -> List[int]:
        ctr = set()
        n = len(nums)
        for i in range(1, n + 1):
            ctr.add(i)
        for num in nums:
            if num in ctr:
                ctr.remove(num)
            else:
                dup = num
        return [dup, list(ctr)[0]]

class Solution:
    def shiftGrid(self, grid: List[List[int]], k: int) -> List[List[int]]:
        m = len(grid)
        n = len(grid[0])
        for _ in range(k):
            lastcol = [row[-1] for row in grid]
            for i in range(m):
                for j in range(n - 1, 0, -1):
                    grid[i][j] = grid[i][j - 1]
            for i in range(m):
                grid[i][0] = lastcol[(m + i - 1) % m]
        return grid

from collections import defaultdict

class Solution:
    def shift(self, c, k):
        return chr(ord('a') + (26 + ord(c) - ord('a') + k) % 26)

    def shiftingLetters(self, s: str, shifts: List[List[int]]) -> str:
        n = len(s)
        freq = defaultdict(int)
        for l, r, d in shifts:
            d = 2 * d - 1
            freq[l] += d
            freq[r + 1] -= d
        for i in range(1, n + 1):
            freq[i] += freq[i - 1]
        return "".join([self.shift(s[i], freq[i]) for i in range(n)])

class Solution:
    def shiftingLetters(self, s: str, shifts: List[int]) -> str:
        s = list(s)
        p = 0
        for i in range(len(s) - 1, -1, -1):
            p += shifts[i]
            s[i] = chr(ord('a') + (ord(s[i]) - ord('a') + p) % 26)
        return "".join(s)

from collections import defaultdict
import heapq

class Solution:
    def shoppingOffers(self, price: List[int], special: List[List[int]], needs: List[int]) -> int:
        dist = defaultdict(lambda: float('inf'))
        beg = tuple([0] * len(needs))
        dist[beg] = 0
        heap = [(0, beg)]
        while len(heap) > 0:
            cost, curr = heapq.heappop(heap)
            if list(curr) == needs:
                return cost
            for i in range(len(price)):
                if curr[i] + 1 <= needs[i]:
                    newcurr = list(curr)
                    newcurr[i] += 1
                    newcurr = tuple(newcurr)
                    if dist[newcurr] > cost + price[i]:
                        dist[newcurr] = cost + price[i]
                        heapq.heappush(heap, (dist[newcurr], newcurr))
            for offer in special:
                newcurr = list(curr)
                valid = True
                for i in range(len(curr)):
                    if newcurr[i] + offer[i] > needs[i]:
                        valid = False
                        break
                    newcurr[i] += offer[i]
                newcurr = tuple(newcurr)
                if valid and dist[newcurr] > cost + offer[-1]:
                    dist[newcurr] = cost + offer[-1]
                    heapq.heappush(heap, (dist[newcurr], newcurr))
        return -1

class Solution:
    def minimumLengthEncoding(self, words: List[str]) -> int:
        words = set(words)
        deleted = set()
        for word in words:
            n = len(word)
            for j in range(1, n):
                curr = word[-j:]
                if curr in words:
                    deleted.add(curr)
        for word in deleted:
            words.remove(word)
        return len(words) + sum([len(w) for w in words])

class Solution:
    def shortestBeautifulSubstring(self, s: str, k: int) -> str:
        n = len(s)
        res = (float('inf'), "")
        for i in range(n):
            ctr = 0
            for j in range(i, n):
                ctr += int(s[j])
                if ctr == k:
                    res = min(res, (j - i + 1, s[i : j + 1]))
        return res[1]

from collections import deque, defaultdict

class Solution:
    def shortestBridge(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        q = deque()
        dist = defaultdict(lambda: float('inf'))
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    q.appendleft((0, i, j))
                    dist[(i, j)] = 0
                    break
            if len(q) > 0:
                break
        while len(q) > 0:
            currdist, i, j = q.pop()
            if grid[i][j] == 1 and currdist > 0:
                return currdist
            for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
                if 0 <= x < m and 0 <= y < n:
                    w = 0 if grid[x][y] == 1 else 1
                    if dist[(x, y)] > currdist + w:
                        dist[(x, y)] = currdist + w
                        if w == 0:
                            q.append((currdist + w, x, y))
                        else:
                            q.appendleft((currdist + w, x, y))

class Solution:
    def shortestCommonSupersequence(self, a: str, b: str) -> str:
        m, n = len(a), len(b)
        dp = [[0]*(n+1) for _ in range(m+1)]
        for i in range(m-1, -1, -1):
            for j in range(n-1, -1, -1):
                dp[i][j] = 1 + dp[i+1][j+1] if a[i] == b[j] else max(dp[i+1][j], dp[i][j+1])
        i = j = 0
        aLCS = []
        bLCS = []
        while i < m and j < n:
            if a[i] == b[j]:
                aLCS.append(i)
                bLCS.append(j)
                i += 1
                j += 1
            elif dp[i+1][j] >= dp[i][j+1]:
                i += 1
            else:
                j += 1
        alcs = [-1] + aLCS + [m]
        blcs = [-1] + bLCS + [n]
        res = []
        for i in range(len(alcs) - 1):
            res.append(a[alcs[i]+1:alcs[i+1]] + b[blcs[i]+1:blcs[i+1]])
            if alcs[i+1] < m:
                res.append(a[alcs[i+1]])
        return "".join(res)

from collections import defaultdict, deque

class Solution:
    def findShortestCycle(self, n: int, edges: List[List[int]]) -> int:
        graph = defaultdict(set)
        for a, b in edges:
            graph[a].add(b)
            graph[b].add(a)
        res = float('inf')
        for a, b in edges:
            q = deque([(a, 0)])
            v = {a}
            while len(q) > 0:
                curr, d = q.pop()
                if curr == b:
                    res = min(res, d + 1)
                for j in graph[curr]:
                    if j not in v and (curr, j) not in {(a, b), (b, a)}:
                        v.add(j)
                        q.appendleft((j, d + 1))
        if res == float('inf'):
            return -1
        return res

class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        edges = [[] for _ in range(n)]
        res = []
        for l, r in queries:
            edges[l].append(r)
            dp = [float('inf')] * n
            dp[n - 1] = 0
            for i in range(n - 2, -1, -1):
                dp[i] = min(dp[i], 1 + dp[i + 1])
                for r in edges[i]:
                    dp[i] = min(dp[i], 1 + dp[r])
            res.append(dp[0])
        return res

class Solution:
    def shortestToChar(self, s: str, c: str) -> List[int]:
        n = len(s)
        res = [float('inf')] * n
        lastpos = float('-inf')
        for i in range(n):
            if s[i] == c:
                lastpos = i
            res[i] = min(res[i], i - lastpos)
        lastpos = float('inf')
        for i in range(n - 1, -1, -1):
            if s[i] == c:
                lastpos = i
            res[i] = min(res[i], lastpos - i)
        return res

class Solution:
    def closetTarget(self, words: List[str], target: str, startIndex: int) -> int:
        n = len(words)
        if target not in words:
            return -1
        res = float('inf')
        for i in range(n):
            if words[i] == target:
                res = min(res, abs(i - startIndex), n + startIndex - i, n + i - startIndex)
        return res

class Solution:
    def shortestSequence(self, rolls: List[int], k: int) -> int:
        res = []
        n = len(rolls)
        subs = set()
        for i in range(n):
            subs.add(rolls[i])
            if len(subs) == k:
                res.append(rolls[i])
                subs.clear()
        for j in range(1, k + 1):
            if j not in subs:
                res.append(j)
                return len(res)
        return len(res)

def compute_lps(pattern):
    lps = [0] * len(pattern)
    j = 0
    i = 1

    while i < len(pattern):
        if pattern[i] == pattern[j]:
            j += 1
            lps[i] = j
            i += 1
        else:
            if j != 0:
                j = lps[j - 1]
            else:
                lps[i] = 0
                i += 1
    return lps

def kmp(text, pattern):
    n, m = len(text), len(pattern)
    lps = compute_lps(pattern)

    occurrences = []
    i = 0
    j = 0

    while i < n:
        if pattern[j] == text[i]:
            i += 1
            j += 1

        if j == m:
            occurrences.append(i - j)
            j = lps[j - 1]

        elif i < n and pattern[j] != text[i]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return occurrences

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        if p == '**':
            return 0
        n = len(s)
        m = len(p)
        p = p.split("*")
        p = [el for el in p if el]
        if len(p) == 1:
            if p[0] in s:
                return len(p[0])
            return -1
        if len(p) == 2:
            res = float('inf')
            a = kmp(s, p[0])
            b = kmp(s, p[1])
            a.sort()
            i = 0
            for j in b:
                while i < len(a) and a[i] + len(p[0]) - 1 < j:
                    res = min(res, j + len(p[1]) - a[i])
                    i += 1
            if res == float('inf'):
                res = -1
            return res
        a = kmp(s, p[0])
        b = kmp(s, p[1])
        c = kmp(s, p[2])
        res = float('inf')
        for i in b:
            curr = len(p[0]) + len(p[1]) + len(p[2])
            f = i
            l = f + len(p[1]) - 1
            beg = 0
            end = len(a) - 1
            e = False
            while beg <= end:
                mid = (beg + end) // 2
                if a[mid] + len(p[0]) - 1 < f:
                    e = True
                    beg = mid + 1
                else:
                    end = mid - 1
            if not e:
                continue
            curr += f - a[beg - 1] - len(p[0])
            beg = 0
            end = len(c) - 1
            e = False
            while beg <= end:
                mid = (beg + end) // 2
                if c[mid] > l:
                    e = True
                    end = mid - 1
                else:
                    beg = mid + 1
            if not e:
                continue
            curr += c[end + 1] - l - 1
            res = min(res, curr)
        if res == float('inf'):
            return -1
        return res

class Solution:
    def shortestPalindrome(self, s: str) -> str:
        T = '#'.join('^{}$'.format(s))
        n = len(T)
        P = [0] * n
        C = R = 0
        for i in range(1, n - 1):
            if R > i:
                P[i] = min(R - i, P[2 * C - i])
            while T[i + 1 + P[i]] == T[i - 1 - P[i]]:
                P[i] += 1
            if i + P[i] > R:
                C, R = i, i + P[i]
        res = 0
        for l in range(len(s) + 1):
            if P[l + 1] == l:
                res = l
        return s[res:][::-1] + s

from collections import deque, defaultdict

class Solution:
    def shortestPath(self, grid: List[List[int]], k: int) -> int:
        m = len(grid)
        n = len(grid[0])
        if k + 2 > m + n:
            return m + n - 2
        dist = defaultdict(lambda: float('inf'))
        beg = (0, 0, k, 0)
        q = deque([beg])
        v = {(0, 0, k)}
        res = float('inf')
        while len(q) > 0:
            x, y, rem, d = q.pop()
            if (x, y) == (m - 1, n - 1):
                res = min(res, d)
            for i, j in [(x - 1, y), (x, y - 1), (x + 1, y), (x, y + 1)]:
                if 0 <= i < m and 0 <= j < n:
                    newrem = rem - grid[i][j]
                    if newrem >= 0 and (i, j, newrem) not in v:
                        v.add((i, j, newrem))
                        q.appendleft((i, j, newrem, d + 1))
        if res == float('inf'):
            return -1
        return res

from collections import deque

class Solution:
    def neighbours(self, a, b, m, n):
        for i in range(a - 1, a + 2):
            for j in range(b - 1, b + 2):
                if (i, j) != (a, b) and 0 <= i < m and 0 <= j < n:
                    yield (i, j)

    def shortestPathBinaryMatrix(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        if grid[0][0] != 0 or grid[-1][-1] != 0:
            return -1
        path = deque([(0, 0, 1)])
        visited = {(0, 0)}
        while len(path) > 0:
            a, b, d = path.popleft()
            if (a, b) == (m - 1, n - 1):
                return d
            for i, j in self.neighbours(a, b, m, n):
                if grid[i][j] == 0 and (i, j) not in visited:
                    visited.add((i, j))
                    path.append((i, j, d + 1))
        return -1

from collections import deque

class Solution:
    def shortestPathAllKeys(self, grid: List[str]) -> int:
        m = len(grid)
        n = len(grid[0])
        si = sj = -1
        target = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == "@":
                    si, sj = i, j
                if grid[i][j].isalpha() and grid[i][j].islower():
                    target |= 1 << (ord(grid[i][j]) - ord('a'))
        q = deque([(si, sj, 0, 0, 0)])
        v = {(si, sj, 0, 0)}
        while len(q) > 0:
            i, j, key, lock, steps = q.pop()
            if key == target:
                return steps
            for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
                if 0 <= x < m and 0 <= y < n and grid[x][y] != "#":
                    newkey = key
                    newlock = lock
                    if grid[x][y].isalpha():
                        if grid[x][y].islower():
                            newkey |= 1 << (ord(grid[x][y]) - ord('a'))
                        if grid[x][y].isupper():
                            if not key & (1 << (ord(grid[x][y]) - ord('A'))):
                                continue
                            newlock |= 1 << (ord(grid[x][y]) - ord('A'))
                    if (x, y, newkey, newlock) not in v:
                        v.add((x, y, newkey, newlock))
                        q.appendleft((x, y, newkey, newlock, steps + 1))
        return -1

class Solution:
    def shortestPathLength(self, graph: List[List[int]]) -> int:
        n = len(graph)
        if n == 1:
            return 0
        req = (1 << n) - 1
        visited = {}
        queue = []
        for i in range(n):
            queue.append((0 | (1 << i), i))
        lvl = 1
        qi = 0
        while qi < len(queue):
            k = len(queue) - qi
            while k > 0:
                curr, currnode = queue[qi]
                qi += 1
                for u in graph[currnode]:
                    newMask = curr | (1 << u)
                    if newMask == req:
                        return lvl
                    if newMask in visited.get(u, {}):
                        continue
                    visited[u] = visited.get(u, set()).union({newMask})
                    queue.append((newMask, u))
                k -= 1
            lvl += 1
        return -1

from collections import defaultdict, deque

class Solution:
    def shortestAlternatingPaths(self, n: int, redEdges: List[List[int]], blueEdges: List[List[int]]) -> List[int]:
        graph = defaultdict(set)
        for u, v in redEdges:
            graph[u].add((v, 0))
        for u, v in blueEdges:
            graph[u].add((v, 1))
        res = [-1] * n
        q = deque([(0, -1, 0)])
        v = {(0, -1)}
        while len(q) > 0:
            curr, prev, d = q.pop()
            if res[curr] == -1 or d < res[curr]:
                res[curr] = d
            for j, c in graph[curr]:
                if c != prev and (j, c) not in v:
                    v.add((j, c))
                    q.appendleft((j, c, d + 1))
        return res

from itertools import permutations

class Solution:
    def merge(self, x, y):
        if y in x:
            return x
        res = 0
        for i in range(1, min(len(x), len(y))):
            if x[-i:] == y[:i]:
                res = i
        return x + y[res:]

    def minimumString(self, a: str, b: str, c: str) -> str:
        res = (float('inf'), "")
        for perm in permutations([a, b, c]):
            curr = ""
            for s in perm:
                curr = self.merge(curr, s)
            res = min(res, (len(curr), curr))
        return res[1]

class Solution:
    def findLengthOfShortestSubarray(self, arr: List[int]) -> int:
        n = len(arr)
        res = n
        suff = [False] * n
        pref = [False] * n
        pref[0] = suff[n - 1] = True
        for i in range(n - 2, -1, -1):
            if arr[i] <= arr[i + 1] and suff[i + 1]:
                suff[i] = True
                res = min(res, i)
        for i in range(1, n):
            if arr[i] >= arr[i - 1] and pref[i - 1]:
                pref[i] = True
                res = min(res, n - i - 1)
        i = 0
        for j in range(n):
            if suff[j]:
                while i < j and pref[i] and arr[i] <= arr[j]:
                    i += 1
                res = min(res, j - i)
        return res

class Solution:
    def minimumSubarrayLength(self, nums: List[int], k: int) -> int:
        if k == 0:
            return 1
        n = len(nums)
        last = [n] * 32
        res = n + 1
        for i in range(n - 1, -1, -1):
            for b in range(32):
                if nums[i] & (1 << b):
                    last[b] = i
            v = 0
            for x in sorted(last):
                if x == n:
                    break
                v |= nums[x]
                if v >= k:
                    res = min(res, x - i + 1)
        if res == n + 1:
            res = -1
        return res

from collections import deque

class Solution:
    def shortestSubarray(self, nums: List[int], k: int) -> int:
        n = len(nums)
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] = p[i] + nums[i]
        q = deque()
        res = n + 1
        i = 0
        for j in range(n + 1):
            while q and p[q[-1]] > p[j]:
                q.pop()
            q.append(j)
            while len(q) > 1 and p[j] - p[q[1]] >= k:
                q.popleft()
            if q and p[j] - p[q[0]] >= k:
                res = min(res, j - q[0])
        if res == n + 1:
            res = -1
        return res

from collections import Counter

class Solution:
    def shortestSubstrings(self, arr: List[str]) -> List[str]:
        subset = Counter()
        for s in arr:
            n = len(s)
            for i in range(n):
                for j in range(i, n):
                    x = s[i:j+1]
                    subset[x] += 1
        res = [""] * len(arr)
        for pos, s in enumerate(arr):
            n = len(s)
            for i in range(n):
                for j in range(i, n):
                    x = s[i:j+1]
                    subset[x] -= 1
            for i in range(n):
                for j in range(i, n):
                    x = s[i:j+1]
                    if subset[x] == 0:
                        if res[pos] == "":
                            res[pos] = x
                        elif len(x) < len(res[pos]):
                            res[pos] = x
                        elif len(x) == len(res[pos]) and x < res[pos]:
                            res[pos] = x
            for i in range(n):
                for j in range(i, n):
                    x = s[i:j+1]
                    subset[x] += 1
        return res

class Solution:
    def findUnsortedSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        i = float('inf')
        j = float('-inf')
        sortednums = sorted(nums)
        for x in range(n):
            if sortednums[x] != nums[x]:
                i = min(i, x)
                j = max(j, x)
        return max(j - i + 1, 0)

from collections import defaultdict

class WordDistance:
    def __init__(self, wordsDict: List[str]):
        self.pos = defaultdict(list)
        for i in range(len(wordsDict)):
            self.pos[wordsDict[i]].append(i)

    def shortest(self, word1: str, word2: str) -> int:
        res = float('inf')
        a = self.pos[word1]
        b = self.pos[word2]
        if len(a) > len(b):
            a, b = b, a
        i = 0
        for j in range(len(a)):
            while i < len(b) and b[i] <= a[j]:
                res = min(res, a[j] - b[i])
                i += 1
        i = len(b) - 1
        for j in range(len(a) - 1, -1, -1):
            while i >= 0 and b[i] >= a[j]:
                res = min(res, b[i] - a[j])
                i -= 1
        return res

class Solution:
    def shortestWordDistance(self, wordsDict: List[str], word1: str, word2: str) -> int:
        res = float('inf')
        a = [i for i in range(len(wordsDict)) if wordsDict[i] == word1]
        b = [i for i in range(len(wordsDict)) if wordsDict[i] == word2]
        if len(a) > len(b):
            a, b = b, a
        if word1 == word2:
            return min(a[i + 1] - a[i] for i in range(len(a) - 1))
        i = 0
        for j in range(len(a)):
            while i < len(b) and b[i] <= a[j]:
                res = min(res, a[j] - b[i])
                i += 1
        i = len(b) - 1
        for j in range(len(a) - 1, -1, -1):
            while i >= 0 and b[i] >= a[j]:
                res = min(res, b[i] - a[j])
                i -= 1
        return res

