class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, a):
        if a == self.parent[a]:
            return a
        self.parent[a] = self.find(self.parent[a])
        return self.parent[a]

    def union(self, a, b):
        parent_a = self.find(a)
        parent_b = self.find(b)
        if parent_a != parent_b:
            if self.size[parent_a] < self.size[parent_b]:
                parent_a, parent_b = parent_b, parent_a
            self.parent[parent_b] = parent_a
            self.size[parent_a] += self.size[parent_b]


class Solution:
    def numSimilarGroups(self, strs: List[str]) -> int:
        n = len(strs)
        m = len(strs[0])
        dsu = DSU(n)
        for i in range(n):
            for j in range(i + 1, n):
                err = 0
                for k in range(m):
                    if strs[i][k] != strs[j][k]:
                        err += 1
                if err == 0 or err == 2:
                    dsu.union(i, j)
        res = set()
        for i in range(n):
            res.add(dsu.find(i))
        return len(res)

class Solution:
    def gcd(self, a, b):
        while b:
            a, b = b, a % b
        return a

    def simplifiedFractions(self, n: int) -> List[str]:
        op = set()
        for j in range(1, n + 1):
            for i in range(1, j):
                mul = self.gcd(i, j)
                op.add("{}/{}".format(i // mul, j // mul))
        return op

class Solution:
    def simplifyPath(self, path: str) -> str:
        path += "/"
        chunk = ""
        chunks = []
        for c in path:
            if c == "/":
                if len(chunk) > 0:
                    chunks.append(chunk)
                chunk = ""
            else:
                chunk += c
        curr = []
        for folder in chunks:
            if folder == "..":
                if len(curr) > 0:
                    curr.pop()
            elif folder != ".":
                curr.append(folder)
        return "/" + "/".join(curr)

class Solution:
    def singleNonDuplicate(self, arr: List[int]) -> int:
        n = len(arr)
        beg = 0
        end = n
        while beg <= end:
            mid = (beg + end) // 2
            if mid < n - 1 and arr[mid] == arr[mid + 1]:
                i = mid
                j = mid + 1
            elif mid >  0 and arr[mid] == arr[mid - 1]:
                i = mid - 1
                j = mid
            else:
                return arr[mid]
            if i % 2 == 0:
                beg = i + 1
            else:
                end = i

class Solution:
    def singleNumber(self, nums: List[int]) -> int:
        bits = [0] * 32
        for el in nums:
            for b in range(32):
                if abs(el) & (1 << b):
                    bits[b] += 1
        res = 0
        for b in range(32):
            if bits[b] % 3 == 1:
                res |= 1 << b
        a = 0
        b = 0
        for el in nums:
            if el == res:
                a += 1
            if -el == res:
                b += 1
        if a == 1:
            return res
        return -res

import bisect

class Solution:
    def singleNumber(self, nums: List[int]) -> List[int]:
        nums.sort()
        op = []
        numset = set(nums)
        for num in numset:
            if bisect.bisect_right(nums, num) == bisect.bisect_left(nums, num) + 1:
                op.append(num)
        return op

class Solution:
    def singleNumber(self, nums: List[int]) -> int:
        n = nums[0]
        for num in nums[1:]:
            n = n ^ num
        return n

import heapq

class Solution:
    def nexthigher(self, tasks, n, t):
        beg = 0
        end = n - 1
        res = float('inf')
        while beg <= end:
            mid = (beg + end) // 2
            if tasks[mid][0] > t:
                res = tasks[mid][0]
                end = mid - 1
            else:
                beg = mid + 1
        return res

    def getOrder(self, tasks: List[List[int]]) -> List[int]:
        n = len(tasks)
        for i in range(n):
            tasks[i].append(i)
        tasks.sort()
        res = []
        heap = []
        i = 0
        t = 0
        while i < n:
            t = self.nexthigher(tasks, n, t)
            while i < n and tasks[i][0] <= t:
                heapq.heappush(heap, (tasks[i][1], tasks[i][2]))
                i += 1
            while len(heap) > 0:
                ptime, idx = heapq.heappop(heap)
                res.append(idx)
                t += ptime
                while i < n and tasks[i][0] <= t:
                    heapq.heappush(heap, (tasks[i][1], tasks[i][2]))
                    i += 1
        return res

