    for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
        if 0 <= x < 2 and 0 <= y < 3:
            newcurr = list(curr)
            newcurr[pos], newcurr[3 * x + y] = newcurr[3 * x + y], newcurr[pos]
            newcurr = tuple(newcurr)
            if newcurr not in v:
                v.add(newcurr)
                q.appendleft((newcurr, d + 1))

