from collections import Counter

class Solution:
    def getSubarrayBeauty(self, nums: List[int], k: int, x: int) -> List[int]:
        n = len(nums)
        ctr = [0] * 101
        res = []
        for i in range(n):
            ctr[nums[i] + 50] += 1
            if i >= k:
                ctr[nums[i - k] + 50] -= 1
            if i >= k - 1:
                rem = x
                val = 0
                for j in range(50):
                    if ctr[j] > 0:
                        rem -= ctr[j]
                    if rem <= 0:
                        val = j - 50
                        break
                res.append(val)
        return res

class Solution:
    def maxSlidingWindow(self, nums: List[int], k: int) -> List[int]:
        res = []
        parent = [-1] * len(nums)
        def find(x):
            if parent[x] == -1:
                return x
            parent[x] = find(parent[x])
            return parent[x]
        stack = []
        for i, el in enumerate(nums):
            while stack and el > nums[stack[-1]]:
                curr = stack.pop()
                parent[curr] = find(i)
            stack.append(i)
            if i >= k - 1:
                res.append(nums[find(i - k + 1)])
        return res

from sortedcontainers import SortedList

class Solution:
    def medianSlidingWindow(self, nums: List[int], k: int) -> List[float]:
        n = len(nums)
        l = SortedList()
        r = SortedList()
        def balance():
            while len(l) < len(r):
                l.add(r.pop(0))
            while len(l) - len(r) > 1:
                r.add(l.pop(-1))
        def add(val):
            if len(r) > 0 and val >= r[0]:
                r.add(val)
            else:
                l.add(val)
            balance()
        def remove(val):
            if len(r) > 0 and val >= r[0]:
                r.remove(val)
            else:
                l.remove(val)
            balance()
        def getmedian():
            if len(l) > len(r):
                return l[-1]
            return (l[-1] + r[0]) / 2
        res = []
        for i in range(n):
            add(nums[i])
            if i >= k:
                remove(nums[i - k])
            if i >= k - 1:
                res.append(getmedian())
        return res

class Solution:
    def slowestKey(self, releaseTimes: List[int], keysPressed: str) -> str:
        n = len(keysPressed)
        releaseTimes.append(0)
        i = max(range(n), key = lambda j: (releaseTimes[j] - releaseTimes[j - 1], keysPressed[j]))
        return keysPressed[i]

from collections import defaultdict

class Solution:
    def findSmallestRegion(self, regions: List[List[str]], region1: str, region2: str) -> str:
        graph = defaultdict(set)
        for r in regions:
            for i in range(1, len(r)):
                graph[r[0]].add(r[i])
        res = -1
        v = set()
        def dfs(x):
            has = False
            ctr = 0
            nonlocal res
            if x == region1 or x == region2:
                has = True
                ctr += 1
            for y in graph.get(x, []):
                if y not in v:
                    v.add(y)
                    childhas = dfs(y)
                    if childhas:
                        has = True
                        ctr += 1
            if ctr >= 2:
                res = x
            return has
        for el in graph:
            if el not in v:
                v.add(el)
                dfs(el)
        return res

class Solution:
    def smallestNumber(self, n: int, t: int) -> int:
        def prod(x):
            p = 1
            while x:
                p *= (x % 10)
                x //= 10
            return p
        while prod(n) % t != 0:
            n += 1
        return n

class Solution:
