import bisect

class Solution:
    def smallestSubsequence(self, s: str, k: int, letter: str, repetition: int) -> str:
        n = len(s)
        s = [ord(c) - ord('a') for c in s]
        letter = ord(letter) - ord('a')
        pos = [[] for _ in range(26)]
        for i in range(n):
            pos[s[i]].append(i)
        prev = -1
        rem = repetition
        res = [""] * k
        for i in range(k):
            for c in range(26):
                p = bisect.bisect_right(pos[c], prev)
                if p == len(pos[c]):
                    continue
                j = pos[c][p]
                if k - i > n - j:
                    continue
                newrem = rem - int(c == letter)
                available = bisect.bisect_right(pos[letter], n - 1) - bisect.bisect_left(pos[letter], j + 1)
                if k - i - 1 < newrem:
                    continue
                if available >= newrem:
                    res[i] = chr(ord('a') + c)
                    rem = newrem
                    prev = j
                    break
        return "".join(res)

from collections import deque

class Solution:
    def smallestMissingValueSubtree(self, parents: List[int], nums: List[int]) -> List[int]:
        n = len(parents)
        q = deque([0])
        graph = [[] for _ in range(n)]
        for i in range(n):
            if parents[i] != -1:
                graph[parents[i]].append(i)
        order = []
        while q:
            curr = q.pop()
            order.append(curr)
            for j in graph[curr]:
                q.appendleft(j)
        order.reverse()
        vals = [set() for _ in range(n)]
        res = [0] * n
        for i in order:
            vals[i].add(nums[i])
            MEX = 1
            for j in graph[i]:
                MEX = max(MEX, res[j])
                if len(vals[i]) < len(vals[j]):
                    vals[i], vals[j] = vals[j], vals[i]
                vals[i].update(vals[j])
                vals[j] = set()
            while MEX in vals[i]:
                MEX += 1
            res[i] = MEX
        return res

class Solution:
    def missingInteger(self, nums: List[int]) -> int:
        x = set(nums)
        n = len(nums)
        s = nums[0]
        i = 1
        while i < n and nums[i] == nums[i - 1] + 1:
            s += nums[i]
            i += 1
        res = s
        while res in x:
            res += 1
        return res

class Solution:
    def findSmallestInteger(self, nums: List[int], value: int) -> int:
        have = Counter()
        for el in nums:
            have[(value + (el % value)) % value] += 1
        mex = 0
        while True:
            if have[mex % value] == 0:
                return mex
            have[mex % value] -= 1
            mex += 1

import heapq

class SmallestInfiniteSet:
    def __init__(self):
        self.heap = []
        self.seen = set()
        self.end = 1

    def popSmallest(self) -> int:
        if len(self.heap) > 0:
            val = heapq.heappop(self.heap)
            self.seen.remove(val)
            return val
        self.end += 1
        return self.end - 1

    def addBack(self, num: int) -> None:
        if num < self.end and num not in self.seen:
            heapq.heappush(self.heap, num)
            self.seen.add(num)

