from collections import defaultdict, Counter

class Solution:
    def smallestRange(self, nums: List[List[int]]) -> List[int]:
        m = len(nums)
        vals = defaultdict(set)
        for i in range(m):
            for el in nums[i]:
                vals[el].add(i)
        vals = sorted(vals.items())
        k = len(vals)
        res = [float('-inf'), float('inf')]
        i = 0
        ctr = Counter()
        for j in range(k):
            for el in vals[j][1]:
                ctr[el] += 1
            beg = i
            while i < j and len(ctr) == m:
                distvals = len(ctr)
                for el in vals[i][1]:
                    if ctr[el] == 1:
                        distvals -= 1
                if len(ctr) == m and distvals < m:
                    break
                if len(ctr) == m and distvals == m:
                    for el in vals[i][1]:
                        ctr[el] -= 1
                        if ctr[el] == 0:
                            del ctr[el]
                i += 1
            if len(ctr) == m and vals[j][0] - vals[i][0] < res[1] - res[0]:
                res = [vals[i][0], vals[j][0]]
        return res

class Solution:
    def smallestRangeI(self, nums: List[int], k: int) -> int:
        mn = float('inf')
        mx = float('-inf')
        for num in nums:
            mn = min(mn, num)
            mx = max(mx, num)
        return max(0, mx - mn - 2 * k)

class Solution:
    def minArea(self, image: List[List[str]], x: int, y: int) -> int:
        m = len(image)
        n = len(image[0])
        stack = [(x, y)]
        v = {(x, y)}
        mnx = mxx = x
        mny = mxy = y
        while stack:
            i, j = stack.pop()
            mnx = min(mnx, i)
            mny = min(mny, j)
            mxx = max(mxx, i)
            mxy = max(mxy, j)
            for ii, jj in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
                if 0 <= ii < m and 0 <= jj < n and (ii, jj) not in v and image[ii][jj] == "1":
                    v.add((ii, jj))
                    stack.append((ii, jj))
        return (mxy - mny + 1) * (mxx - mnx + 1)

