class Solution:
    def bestRotation(self, nums: List[int]) -> int:
        n = len(nums)
        res = (0, float('inf'))
        vals = SortedList()
        for i in range(2 * n):
            vals.add(i - nums[i % n])
            if i >= n:
                vals.remove(i - n - nums[(i - n) % n])
            if i >= n - 1:
                res = max(res, (len(vals) - vals.bisect_left(i - n + 1), n - i - 1))
        return -res[1]

class Solution:
    def smallestFromLeaf(self, root: Optional[TreeNode]) -> str:
        paths = [(root, [root.val] if root else [])]
        i = 0
        smallest = None
        while i < len(paths):
            curr, val = paths[i]
            if curr:
                if not curr.left and not curr.right:
                    n = len(val)
                    currval = "".join(["abcdefghijklmnopqrstuvwxyz"[val[i]] for i in range(n - 1, -1, -1)])
                    if smallest:
                        if currval < smallest:
                            smallest = currval
                    else:
                        smallest = currval
                if curr.left:
                    paths.append((curr.left, val + [curr.left.val]))
                if curr.right:
                    paths.append((curr.right, val + [curr.right.val]))
            i += 1
        return smallest

