class Solution:
    def smallestSubarrays(self, nums: List[int]) -> List[int]:
        n = len(nums)
        b = [[] for _ in range(30)]
        for i in range(n):
            for j in range(30):
                if nums[i] & (1 << j):
                    b[j].append(i)
        res = []
        for i in range(n):
            curr = 1
            for j in range(30):
                k = bisect.bisect_left(b[j], i)
                if k < len(b[j]):
                    curr = max(curr, b[j][k] - i + 1)
            res.append(curr)
        return res

from collections import defaultdict

class Solution:
    def smallestSubsequence(self, s: str) -> str:
        n = len(s)
        pos = defaultdict(list)
        for i in range(n):
            pos[s[i]].append(i)
        prev = -1
        res = []
        rem = set(s)
        k = len(rem)
        for _ in range(k):
            for cc in sorted(rem):
                beg = 0
                end = len(pos[cc]) - 1
                curr = n
                while beg <= end:
                    mid = (beg + end) // 2
                    if pos[cc][mid] > prev:
                        curr = pos[cc][mid]
                        end = mid - 1
                    else:
                        beg = mid + 1
                if curr < n:
                    if all(pos[ccc][-1] > curr for ccc in rem if ccc != cc):
                        res.append(cc)
                        rem.remove(cc)
                        prev = curr
                        break
        return "".join(res)

from collections import deque

def ops(s, mid, p, dp):
    n = len(s)
    dp[n][0] = dp[n][1] = 0
    q = [deque(maxlen = n + 1), deque(maxlen = n + 1)]
    for i in range(n, -1, -1):
        for val in range(2):
            while q[1 - val] and q[1 - val][-1][1] > i + mid:
                q[1 - val].pop()
            if q[1 - val]:
                dp[i][val] = q[1 - val][-1][0] - p[1 - val][i]
        for val in range(2):
            while q[val] and dp[i][val] + p[val][i] < q[val][0][0]:
                q[val].popleft()
            q[val].appendleft((dp[i][val] + p[val][i], i))
    return min(dp[0])

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        dp = [[float('inf'), float('inf')] for _ in range(n + 1)]
        p = [[0] * (n + 1), [0] * (n + 1)]
        for i in range(n):
            p[0][i + 1] = p[0][i] + 1 - int(s[i])
            p[1][i + 1] = p[1][i] + int(s[i])
        beg = 1
        end = n
        while beg <= end:
            mid = (beg + end) // 2
            if ops(s, mid, p, dp) <= numOps:
                end = mid - 1
            else:
                beg = mid + 1
        return end + 1

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def maxDepth(self, root):
        if root:
            a = 1 + self.maxDepth(root.left)
            b = 1 + self.maxDepth(root.right)
            return max(a, b)
        return -1

    def subtreeWithAllDeepest(self, root: TreeNode) -> TreeNode:
        if root:
            left = self.maxDepth(root.left)
            right = self.maxDepth(root.right)
            if left > right:
                return self.subtreeWithAllDeepest(root.left)
            elif right > left:
                return self.subtreeWithAllDeepest(root.right)
            else:
                return root

class Solution:
    def find(self, people, i, n, curr, skills):
        if i >= n:
            if curr & skills != skills:
                return float('inf')
            return 0
        key = (i, curr)
        if key in self.cache:
            return self.cache[key]
        a = self.find(people, i + 1, n, curr, skills)
        b = 1 + self.find(people, i + 1, n, curr | people[i], skills)
        res = min(a, b)
        self.cache[key] = res
        return res

    def smallestSufficientTeam(self, skills, people):
        n = len(people)
        mp = {}
        for s in skills:
            mp[s] = 0
        for p in people:
            for s in p:
                mp[s] = 0
        for i, el in enumerate(sorted(mp)):
            mp[el] = i
        skills = sum(1 << mp[el] for el in skills)
        for p in range(n):
            people[p] = sum(1 << mp[el] for el in people[p])
        self.cache = {}
        res = []
        curr = (0, 0)
        for i in range(n):
            if self.find(people, curr[0] + 1, n, curr[1], skills) <= self.find(people, curr[0] + 1, n, curr[1] | people[i], skills):
                curr = (curr[0] + 1, curr[1])
            else:
                res.append(i)
                curr = (curr[0] + 1, curr[1] | people[i])
        return res

import math

class Solution:
    def smallestValue(self, n: int) -> int:
        prev = n
        i = 2
        newval = 0
        for i in range(2, int(math.sqrt(n)) + 1):
            while n % i == 0:
                n = n // i
                newval += i
        if n > 1:
            newval += n
        if newval == prev:
            return newval
        return self.smallestValue(newval)

class Solution:
    def smallestNumber(self, num: int) -> int:
        if num == 0:
            return num
        negative = num < 0
        num = abs(num)
        num = list(str(num))
        if negative:
            return -int("".join(sorted(num, reverse = True)))
        minDigit = min(d for d in num if d != "0")
        num.remove(minDigit)
        return int(minDigit + "".join(sorted(num)))

class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        x, y = 0, 0
        for c in commands:
            if c == "UP":
                x -= 1
            if c == "RIGHT":
                y += 1
            if c == "LEFT":
                y -= 1
            if c == "DOWN":
                x += 1
        return n * x + y

class Solution:
    def snakesAndLadders(self, board: List[List[int]]) -> int:
        n = len(board)
        graph = {}
        for i in range(n * n):
            row = i // n
            col = i % n
            if row % 2 == 1:
                col = n - col - 1
            row = n - row - 1
            if board[row][col] != -1:
                graph[i + 1] = board[row][col]
        visited = set()
        paths = [(1, 0)]
        i = 0
        while i < len(paths):
            curr, moves = paths[i]
            if curr == n * n:
                return moves
            for jump in range(curr + 1, min(curr + 7, (n * n) + 1)):
                if jump not in visited:
                    visited.add(jump)
                    paths.append((graph.get(jump, jump), moves + 1))
            i += 1
        return -1

import bisect

class SnapshotArray:
    def __init__(self, length: int):
        self.snaps = {}
        self.sid = 0
        for i in range(length):
            self.snaps[i] = [(0, 0)]

    def set(self, index: int, val: int) -> None:
        self.snaps[index].append((self.sid, val))

    def snap(self) -> int:
        res = self.sid
        self.sid += 1
        return res

    def get(self, index: int, snap_id: int) -> int:
        beg = 0
        end = len(self.snaps[index]) - 1
        res = 0
        while beg <= end:
            mid = (beg + end) // 2
            if self.snaps[index][mid][0] <= snap_id:
                res = self.snaps[index][mid][1]
                beg = mid + 1
            else:
                end = mid - 1
        return res

class Solution:
    def parse(self, s):
        vals = [0, 0]
        chunk = ""
        sign = 1
        for c in s:
            if c == "+" or c == "-" or c == "s":
                if len(chunk) > 0:
                    if chunk[-1] == "x":
                        coefficient = chunk[:-1]
                        if not coefficient:
                            coefficient = "1"
                        vals[0] += sign * int(coefficient)
                    else:
                        vals[1] += sign * int(chunk)
                    chunk = ""
                if c == "+":
                    sign = 1
                elif c == "-":
                    sign = -1
            else:
                chunk += c
        return vals

    def solveEquation(self, equation: str) -> str:
        l, r = equation.split("=")
        lvals = self.parse(l + "s")
        rvals = self.parse(r + "s")
        numer = rvals[1] - lvals[1]
        denom = lvals[0] - rvals[0]
        if denom != 0:
            return "x={}".format(numer // denom)
        if numer != 0:
            return "No solution"
        return "Infinite solutions"

class Solution:
    def mostPoints(self, questions: List[List[int]]) -> int:
        n = len(questions)
        dp = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            dp[i] = max(dp[i + 1], questions[i][0] + dp[min(i + questions[i][1] + 1, n)])
        return dp[0]

class Solution:
    def sortArray(self, nums: List[int]) -> List[int]:
        n = len(nums)
        def mergesort(i, j):
            if i + 1 == j:
                return
            mid = (i + j) // 2
            mergesort(i, mid)
            mergesort(mid, j)
            vals = []
            x = i
            y = mid
            while x < mid and y < j:
                if nums[x] <= nums[y]:
                    vals.append(nums[x])
                    x += 1
                else:
                    vals.append(nums[y])
                    y += 1
            while x < mid:
                vals.append(nums[x])
                x += 1
            while y < j:
                vals.append(nums[y])
                y += 1
            for x in range(i, j):
                nums[x] = vals[x - i]
        mergesort(0, n)
        return nums

