class Solution:
    def sortEvenOdd(self, nums: List[int]) -> List[int]:
        n = len(nums)
        evens = []
        odds = []
        for i in range(n):
            if i & 1:
                heapq.heappush(odds, -nums[i])
            else:
                heapq.heappush(evens, nums[i])
        for i in range(n):
            if i & 1:
                nums[i] = -heapq.heappop(odds)
            else:
                nums[i] = heapq.heappop(evens)
        return nums

class Solution:
    def sortByBits(self, arr: List[int]) -> List[int]:
        c = {}
        def count(x):
            if x == 0:
                return 0
            if x in c:
                return c[x]
            c[x] = x % 2 + count(x // 2)
            return c[x]
        return sorted(arr, key = lambda x: (count(x), x))

class Solution:
    def findKthSmallest(self, nums, k):
        if not nums: return
        pivot = random.choice(nums)
        left =  [x for x in nums if x < pivot]
        mid  =  [x for x in nums if x == pivot]
        right = [x for x in nums if x > pivot]
        L, M = len(left), len(mid)
        if k <= L:
            return self.findKthSmallest(left, k)
        elif k > L + M:
            return self.findKthSmallest(right, k - L - M)
        else:
            return mid[0]

    def getKth(self, lo: int, hi: int, k: int) -> int:
        c = {}
        def getp(x):
            if x == 1:
                return 0
            if x in c:
                return c[x]
            c[x] = 1 + getp(x // 2) if x % 2 == 0 else 1 + getp(3 * x + 1)
            return c[x]
        return self.findKthSmallest([(getp(i), i) for i in range(lo, hi + 1)], k)[1]

from collections import defaultdict, deque, Counter

class Solution:
    def sortItems(self, n: int, m: int, group: List[int], beforeItems: List[List[int]]) -> List[int]:
        groups = defaultdict(set)
        extra = m
        for i in range(n):
            if group[i] != -1:
                groups[group[i]].add(i)
            else:
                groups[extra].add(i)
                group[i] = extra
                extra += 1
        graph = defaultdict(lambda: defaultdict(set))
        groupgraph = defaultdict(set)
        for j in range(n):
            for i in beforeItems[j]:
                graph[i][group[j]].add(j)
                if group[i] != group[j]:
                    groupgraph[group[i]].add(group[j])
        gindegree = Counter()
        for g in groupgraph:
            for j in groupgraph[g]:
                gindegree[j] += 1
        res = defaultdict(list)
        for g in groups:
            indegree = Counter()
            for i in groups[g]:
                for j in graph[i][g]:
                    indegree[j] += 1
            q = deque()
            for i in groups[g]:
                if indegree[i] == 0:
                    q.appendleft(i)
            while len(q) > 0:
                curr = q.pop()
                res[g].append(curr)
                for j in graph[curr][g]:
                    indegree[j] -= 1
                    if indegree[j] == 0:
                        q.appendleft(j)
        order = []
        q = deque()
        for g in groups:
            if gindegree[g] == 0:
                q.appendleft(g)
        while len(q) > 0:
            curr = q.pop()
            order.extend(res[curr])
            for j in groupgraph[curr]:
                gindegree[j] -= 1
                if gindegree[j] == 0:
                    q.appendleft(j)
        if len(order) < n:
            return []
        return order

# Definition for singly-linked list.
