#     def __init__(self, val=0, next=None):
#         self.val = val
#         self.next = next
class Solution:
    def mergeTwoLists(self, list1, list2):
        if not list1 or not list2:
            return list1 or list2
        if list1.val < list2.val:
            list1.next = self.mergeTwoLists(list1.next, list2)
            return list1
        else:
            list2.next = self.mergeTwoLists(list1, list2.next)
            return list2

    def sortList(self, head: Optional[ListNode]) -> Optional[ListNode]:
        if not head or not head.next:
            return head
        prev = None
        slow = head
        fast = head
        while slow and fast and fast.next:
            prev = slow
            slow = slow.next
            fast = fast.next.next
        prev.next = None
        return self.mergeTwoLists(self.sortList(head), self.sortList(slow))

class Solution:
    def mapNum(self, num, mapping):
        op = 0
        for c in str(num):
            op = 10 * op + mapping[int(c)]
        return op

    def sortJumbled(self, mapping: List[int], nums: List[int]) -> List[int]:
        return sorted(nums, key = lambda num: self.mapNum(num, mapping))

import bisect

class Solution:
    def diagonalSort(self, mat: List[List[int]]) -> List[List[int]]:
        m = len(mat)
        n = len(mat[0])
        diags = {}
        for i in range(m):
            for j in range(n):
                if i - j in diags:
                    bisect.insort(diags[i - j], mat[i][j])
                else:
                    diags[i - j] = [mat[i][j]]
        for i in range(m):
            for j in range(n):
                mat[i][j] = diags[i - j][min(i, j)]
        return mat

