class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        lis = []
        for i, el in enumerate(nums):
            el = (el, i)
            pos = bisect_left(lis, el)
            if pos < len(lis):
                lis[pos] = el
            else:
                lis.append(el)
        return len(nums) - len(lis)

class Solution:
    def prob(self, a, b):
        if a <= 0 and b <= 0:
            return 0.5
        if a <= 0 and b > 0:
            return 1
        if a <= 0 or b <= 0:
            return 0
        key = (a, b)
        if key in self.cache:
            return self.cache[key]
        res = 0
        for ax, bx in [(100, 0), (75, 25), (50, 50), (25, 75)]:
            res += self.prob(a - ax, b - bx)
        res /= 4
        self.cache[key] = res
        return res

    def soupServings(self, n: int) -> float:
        if n >= 4800:
            return 1
        self.cache = {}
        return self.prob(n, n)

class Solution:
    def isArraySpecial(self, nums: List[int]) -> bool:
        for i in range(len(nums) - 1):
            if (nums[i] + nums[i + 1]) % 2 == 0:
                return False
        return True

class Solution:
    def isArraySpecial(self, nums: List[int], queries: List[List[int]]) -> List[bool]:
        n = len(nums)
        dp = [1] * n
        for i in range(n - 2, -1, -1):
            if nums[i] % 2 != nums[i + 1] % 2:
                dp[i] = 1 + dp[i + 1]
        return [dp[l] >= r - l + 1 for l, r in queries]

class Solution:
    def specialArray(self, nums: List[int]) -> int:
        nums.sort(reverse=True)
        i = 0
        while i < len(nums) and nums[i] > i:
            i += 1
        if i < len(nums) and i == nums[i]:
            return -1
        return i

class Solution:
    def specialPerm(self, nums: List[int]) -> int:
        n = len(nums)
        g = [[] for _ in range(n + 1)]
        for i in range(n):
            g[n].append(i)
            for j in range(n):
                if i != j and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                    g[i].append(j)
        M = 10 ** 9 + 7
        cache = {}
        def count(i, used):
            if used + 1 == 1 << n:
                return 1
            key = (i, used)
            if key in cache:
                return cache[key]
            res = 0
            for j in g[i]:
                if not used & (1 << j):
                    res += count(j, used | (1 << j))
                    res %= M
            cache[key] = res
            return res
        return count(n, 0)

class Solution:
    def numSpecial(self, mat: List[List[int]]) -> int:
        m = len(mat)
        n = len(mat[0])
        pr = [0 for _ in range(m)]
        pc = [0 for _ in range(n)]
        for i in range(m):
            for j in range(n):
                pr[i] += mat[i][j]
                pc[j] += mat[i][j]
        res = 0
        for i in range(m):
            for j in range(n):
                if mat[i][j] == 1 and pr[i] == 1 and pc[j] == 1:
                    res += 1
        return res

class Solution:
    def spiralMatrixIII(self, rows: int, cols: int, rStart: int, cStart: int) -> List[List[int]]:
        dx = [0, 1, 0, -1]
        dy = [1, 0, -1, 0]
        x, y = rStart, cStart
        res = [(x, y)]
        l = 1
        d = 0
        while len(res) < rows * cols:
            for _ in range(2):
                for _ in range(l):
                    x += dx[d % 4]
                    y += dy[d % 4]
                    if 0 <= x < rows and 0 <= y < cols:
                        res.append((x, y))
                d += 1
            l += 1
        return res

class Solution:
    def spiralMatrix(self, m: int, n: int, head: Optional[ListNode]) -> List[List[int]]:
        res = [[-1] * n for _ in range(m)]
        k = 2 * min(m, n)
        dx = [0, 1, 0, -1]
        dy = [1, 0, -1, 0]
        x, y = 0, -1
        for d in range(k):
            if not head:
                break
            for i in range(n):
                x += dx[d % 4]
                y += dy[d % 4]
                res[x][y] = head.val
                head = head.next
                if not head:
                    break
            m, n = n, m - 1
        return res

class Solution:
    def balancedStringSplit(self, s: str) -> int:
        ctr = 0
        curr = 0
        for c in s:
            if curr == 0:
                ctr += 1
            if c == 'L':
                curr += 1
            else:
                curr -= 1
        if curr == 0:
            ctr += 1
        return ctr - 1

class Solution:
    def maxUniqueSplit(self, s: str) -> int:
        n = len(s)
        def dp(i, used):
            if i >= n:
                return 0
            res = 0
            for j in range(i, n):
                if s[i:j+1] not in used:
                    used.add(s[i:j+1])
                    res = max(res, 1 + dp(j + 1, used))
                    used.remove(s[i:j+1])
            return res
        return dp(0, set())

