import heapq

class Solution:
    def isPossible(self, nums: List[int]) -> bool:
        numctr = defaultdict(list)
        for val in nums:
            l = 0
            currheap = numctr[val]
            if (val - 1) in numctr:
                prevheap = numctr[val - 1]
                if len(prevheap) > 0:
                    l = heapq.heappop(prevheap)
            heapq.heappush(currheap, 1 + l)
        for val in numctr:
            if len(numctr[val]) > 0 and numctr[val][0] < 3:
                return False
        return True

class Solution:
    def splitIntoFibonacci(self, num: str) -> List[int]:
        n = len(num)
        def gen(i, curr):
            if i >= n:
                return len(curr) >= 3
            v = 0
            for j in range(i, n):
                v = 10 * v + int(num[j])
                if v.bit_length() >= 32:
                    break
                if len(curr) < 2 or v == curr[-2] + curr[-1]:
                    curr.append(v)
                    if gen(j + 1, curr):
                        return True
                    curr.pop()
                if len(curr) >= 2 and v > curr[-2] + curr[-1]:
                    break
                if num[i] == '0':
                    break
            return False
        res = []
        gen(0, res)
        return res

class Solution:
    def maxSubarrays(self, nums: List[int]) -> int:
        n = len(nums)
        score = nums[0]
        for el in nums:
            score &= el
        if score != 0:
            return 1
        res = 0
        curr = nums[0]
        for i in range(n):
            curr &= nums[i]
            if curr == score:
                res += 1
                if i < n - 1:
                    curr = nums[i + 1]
        return res

class Solution:
    def maxSum(self, prefix, i, j, m):
        if m == 1:
            return prefix[j] - prefix[i]
        key = (i, j, m)
        if key in self.cache:
            return self.cache[key]
        minVal = float('inf')
        for k in range(i + 1, j - m + 2):
            if prefix[k] - prefix[i] >= minVal:
                break
            val = max(prefix[k] - prefix[i], self.maxSum(prefix, k, j, m - 1))
            minVal = min(minVal, val)
        self.cache[key] = minVal
        return minVal

    def splitArray(self, nums: List[int], m: int) -> int:
        self.cache = {}
        n = len(nums)
        prefix = [0]
        for el in nums:
            prefix.append(prefix[-1] + el)
        return self.maxSum(prefix, 0, n, m)

from collections import defaultdict

class Solution:
    def splitArraySameAverage(self, nums: List[int]) -> bool:
        n = len(nums)
        total = sum(nums)
        k = n // 2
        left = defaultdict(set)
        right = defaultdict(set)
        for mask in range(1 << k):
            s = 0
            ctr = 0
            for i in range(k):
                if mask & (1 << i):
                    s += nums[i]
                    ctr += 1
            left[ctr].add(s)
        for mask in range(1 << (n - k)):
            s = 0
            ctr = 0
            for i in range(n - k):
                if mask & (1 << i):
                    s += nums[k + i]
                    ctr += 1
            right[ctr].add(s)
        for ll in range(1, n):
            if (total * ll) % n != 0:
                continue
            val = (total * ll) // n
            for l in range(ll + 1):
                for ls in left[l]:
                    if val - ls in right[ll - l]:
                        return True
        return False

class Solution:
    def splitListToParts(self, head: Optional[ListNode], k: int) -> List[Optional[ListNode]]:
        ln = lambda h: 1 + ln(h.next) if h else 0
        l = ln(head)
        res = []
        prev = None
        curr = head
        for i in range(k):
            res.append(curr)
            for _ in range(l // k + int(i < l % k)):
                prev, curr = curr, curr.next
            if prev:
                prev.next = None
        return res

