class Solution:
    def findValidSplit(self, nums: List[int]) -> int:
        n = len(nums)
        bothcount = 0
        left = Counter()
        right = Counter()
        for el in nums:
            curr = el
            while curr > 1:
                right[sp[curr]] += 1
                curr //= sp[curr]
        for i in range(n - 1):
            curr = nums[i]
            while curr > 1:
                bothcount -= int(left[sp[curr]] > 0 and right[sp[curr]] > 0)
                right[sp[curr]] -= 1
                left[sp[curr]] += 1
                bothcount += int(left[sp[curr]] > 0 and right[sp[curr]] > 0)
                curr //= sp[curr]
            if bothcount == 0:
                return i
        return -1

class Solution:
    def manachers(self, s):
        T = '#'.join('^{}$'.format(s))
        n = len(T)
        P = [0] * n
        C = R = 0
        for i in range(1, n - 1):
            if R > i:
                P[i] = min(R - i, P[2 * C - i])
            while T[i + 1 + P[i]] == T[i - 1 - P[i]]:
                P[i] += 1
            if i + P[i] > R:
                C, R = i, i + P[i]
        return P

    def check(self, a, b):
        n = len(a)
        s = a + b
        pal = self.manachers(s)
        ispal = lambda x, y: pal[x + y + 2] >= y - x + 1
        maxmatch = 0
        i = 0
        j = 2 * n - 1
        while i < j and s[i] == s[j]:
            maxmatch += 1
            i += 1
            j -= 1
        for pref in range(n + 1):
            suff = n - pref
            if min(pref, suff) > maxmatch:
                continue
            diff = abs(pref - suff)
            if pref >= suff:
                if diff == 0 or ispal(pref - diff, pref - 1):
                    return True
            else:
                if ispal(2 * n - suff, 2 * n - suff + diff - 1):
                    return True
        return False

    def checkPalindromeFormation(self, a: str, b: str) -> bool:
        return self.check(a, b) or self.check(b, a)

class Solution:
    def splitString(self, s: str) -> bool:
        n = len(s)
        def gen(i, curr):
            if i >= n:
                return len(curr) >= 2
            v = 0
            for j in range(i, n):
                v = 10 * v + int(s[j])
                if len(curr) == 0 or v == curr[-1] - 1:
                    curr.append(v)
                    if gen(j + 1, curr):
                        return True
                    curr.pop()
                if len(curr) > 0 and v >= curr[-1]:
                    break
            return False
        return gen(0, [])

class Solution:
    def mySqrt(self, x: int) -> int:
        sqrt = 0
        for p in range(20, -1, -1):
            pw = 1 << p
            if (sqrt + pw) * (sqrt + pw) <= x:
                sqrt += pw
        return sqrt

class Solution:
    def sortedSquares(self, nums: List[int]) -> List[int]:
        i = 0
        while i < len(nums) and nums[i] < 0:
            i += 1
        j = i - 1
        res = []
        while i < len(nums) and j >= 0:
            if nums[i] * nums[i] <= nums[j] * nums[j]:
                res.append(nums[i] * nums[i])
                i += 1
            else:
                res.append(nums[j] * nums[j])
                j -= 1
        while i < len(nums):
            res.append(nums[i] * nums[i])
            i += 1
        while j >= 0:
            res.append(nums[j] * nums[j])
            j -= 1
        return res

class Solution:
    def movesToStamp(self, stamp: str, target: str) -> List[int]:
        n = len(target)
        k = len(stamp)
        res = []
        target = list(target)
        last = ['?'] * n
        while target != last:
            changed = False
            for i in range(n - k + 1):
                valid = True
                charseen = False
                for j in range(i, i + k):
                    if target[j] != '?':
                        charseen = True
                        if target[j] != stamp[j - i]:
                            valid = False
                if valid and charseen:
                    changed = True
                    res.append(i)
                    for j in range(i, i + k):
                        target[j] = '?'
            if not changed:
                return []
        if len(res) > 10 * n:
            return []
        return res[::-1]

class Solution:
    def getDirections(self, root, startValue, destValue) -> str:
        if not root:
            return ""
        graph = defaultdict(set)
        stack = [root]
        while stack:
            curr = stack.pop()
            if curr.left:
                graph[curr.val].add((curr.left.val, "L"))
                graph[curr.left.val].add((curr.val, "U"))
                stack.append(curr.left)
            if curr.right:
                graph[curr.val].add((curr.right.val, "R"))
                graph[curr.right.val].add((curr.val, "U"))
                stack.append(curr.right)
        q = deque([startValue])
        v = {startValue}
        prev = {}
        while q:
            x = q.pop()
            for y, d in graph[x]:
                if y not in v:
                    prev[y] = (x, d)
                    v.add(y)
                    q.appendleft(y)
        res = [(destValue, "")]
        while res[-1][0] != startValue:
            res.append(prev[res[-1][0]])
        res.reverse()
        return "".join(x[1] for x in res)

class Solution:
    def stoneGameII(self, piles: List[int]) -> int:
        n = len(piles)
        p = piles[:]
        for i in range(n - 2, -1, -1):
            p[i] += p[i + 1]
        p.append(0)
        dp = [[0] * 101 for _ in range(n + 1)]
        for i in range(n - 1, -1, -1):
            for m in range(1, 101):
                curr = 0
                for j in range(i, min(i + 2 * m, n)):
                    curr += piles[j]
                    dp[i][m] = max(dp[i][m], curr + p[j + 1] - dp[j + 1][max(j - i + 1, m)])
        return dp[0][1]

class Solution:
    def stoneGameIII(self, arr):
        n = len(arr)
        dp = [float('-inf')] * (n + 3)
        dp[n] = dp[n + 1] = dp[n + 2] = 0
        for i in range(n - 1, -1, -1):
            s = 0
            for j in range(i, min(i + 3, n)):
                s += arr[j]
                dp[i] = max(dp[i], s - dp[j + 1])
        if dp[0] > 0:
            return "Alice"
        if dp[0] < 0:
            return "Bob"
        return "Tie"

