class Solution:
    def minLen(self, s, i, n, prev, ctr, k):
        if k < 0:
            return float('inf')
        if i >= n:
            return 0
        key = (i, prev, ctr, k)
        if key in self.cache:
            return self.cache[key]
        res = float('inf')
        res = min(res, self.minLen(s, i + 1, n, prev, ctr, k - 1))
        if s[i] != prev:
            res = min(res, 1 + self.minLen(s, i + 1, n, s[i], 1, k))
        else:
            l = 0
            if ctr == 1 or ctr == 9 or ctr == 99:
                l = 1
            res = min(res, l + self.minLen(s, i + 1, n, s[i], ctr + 1, k))
        self.cache[key] = res
        return res

    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        n = len(s)
        self.cache = {}
        return self.minLen(s, 0, n, None, 0, k)

class Solution:
    def compressedString(self, word: str) -> str:
        res = []
        n = len(word)
        i = 0
        while i < n:
            ctr = 1
            while i < n - 1 and word[i] == word[i + 1]:
                i += 1
                ctr += 1
            while ctr:
                d = min(ctr, 9)
                res.append(f"{d}{word[i]}")
                ctr -= d
            i += 1
        return "".join(res)

class Solution:
    def compress(self, chars: List[str]) -> int:
        n = len(chars)
        i = 0
        while i < n:
            ctr = 1
            while i < n - 1 and chars[i] == chars[i + 1]:
                i += 1
                ctr += 1
            i += 1
            if ctr == 1:
                chars.extend([chars[i - 1]])
            else:
                chars.extend([chars[i - 1]] + list(str(ctr)))
        for i in range(n):
            chars.pop(0)
        return len(chars)

class Solution:
    def stringMatching(self, words: List[str]) -> List[str]:
        wordset = set(words)
        res = set()
        for w in words:
            n = len(w)
            for i in range(n):
                for j in range(i + 1, n + 1):
                    if w[i:j] in wordset and (i, j) != (0, n):
                        res.add(w[i:j])
        return list(res)

class Solution:
    def clamp(self, val, MIN, MAX):
        if val < MIN:
            return MIN
        if val > MAX:
            return MAX
        return val

    def myAtoi(self, s: str) -> int:
        MIN = -1 << 31
        MAX = -MIN - 1
        sign = None
        val = None
        for c in s:
            if c == "+" or c == "-":
                if val != None:
                    break
                if sign == None:
                    sign = [-1, 1][c == "+"]
                else:
                    return 0
            elif 48 <= ord(c) < 58:
                d = ord(c) - 48
                val = 10 * (val or 0) + d
            elif val == None and sign == None:
                if c != " ":
                    return 0
            else:
                break
        return self.clamp((sign or 1) * (val or 0), MIN, MAX)

class Solution:
    def strWithout3a3b(self, a: int, b: int) -> str:
        res = []
        n = a + b
        while len(res) < n:
            apos = True
            bpos = True
            if len(res) >= 2 and res[-1] == res[-2] == 'a':
                apos = False
            if len(res) >= 2 and res[-1] == res[-2] == 'b':
                bpos = False
            if apos and bpos:
                if a >= b:
                    res.append('a')
                    a -= 1
                else:
                    res.append('b')
                    b -= 1
            elif apos:
                res.append('a')
                a -= 1
            elif bpos:
                res.append('b')
                b -= 1
        return "".join(res)

class Solution:
    def strongPasswordCheckerII(self, p: str) -> bool:
        n = len(p)
        if len(p) < 8:
            return False
        lc = 0
        uc = 0
        dg = 0
        sc = 0
        for i in range(n):
            if p[i].islower():
                lc += 1
            if p[i].isupper():
                uc += 1
            if p[i].isdigit():
                dg += 1
            if p[i] in "!@#$%^&*()-+":
                sc += 1
            if i < n - 1 and p[i] == p[i + 1]:
                return False
        return lc >= 1 and uc >= 1 and dg >= 1 and sc >= 1

class Solution:
    def checkRecord(self, s: str) -> bool:
        n = len(s)
        a = 0
        i = 0
        while i < n:
            ctr = 1
            while i < n - 1 and s[i] == s[i + 1]:
                ctr += 1
                i += 1
            if s[i] == 'L' and ctr >= 3:
                return False
            if s[i] == 'A':
                a += ctr
            i += 1
        return a < 2

class Solution:
    def checkRecord(self, n: int) -> int:
        M = 10 ** 9 + 7
        dp = [[[0] * 3 for _ in range(2)] for _ in range(n + 1)]
        for i in range(2):
            for j in range(3):
                dp[0][i][j] = 1
        for i in range(1, n + 1):
            for j in range(2):
                for k in range(3):
                    dp[i][j][k] = dp[i - 1][j][0]
                    if j == 0:
                        dp[i][j][k] = (dp[i][j][k] + dp[i - 1][j + 1][0]) % M
                    if k < 2:
                        dp[i][j][k] = (dp[i][j][k] + dp[i - 1][j][k + 1]) % M
        return dp[n][0][0]

class Solution:
    def numSubarrayProductLessThanK(self, nums: List[int], k: int) -> int:
        n = len(nums)
        dp = [1] * n
        for i in range(n - 1, -1, -1):
            if i < n - 1 and nums[i] == nums[i + 1] == 1:
                dp[i] = 1 + dp[i + 1]
        res = 0
        for i in range(n):
            p = 1
            j = i
            while j < n and p * nums[j] < k:
                p *= nums[j]
                res += dp[j]
                j += dp[j]
        return res

from collections import defaultdict

class Solution:
    def subarraysDivByK(self, nums: List[int], k: int) -> int:
        total = 0
        ctr = defaultdict(int)
        ctr[0] += 1
        for num in nums:
            total = (total + num) % k
            ctr[total] += 1
        return sum(n * (n - 1) // 2 for n in ctr.values())

class Solution:
    def validSubarraySize(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        s = []
        left = [-1] * (n + 1)
        right = [n] * (n + 1)
        for i in range(n):
            while (len(s) != 0 and
                   nums[s[-1]] >= nums[i]):
                s.pop()
            if len(s) != 0:
                left[i] = s[-1]
            s.append(i)
        s = []
        for i in range(n - 1, -1, -1):
            while (len(s) != 0 and nums[s[-1]] >= nums[i]):
                s.pop()
            if len(s) != 0:
                right[i] = s[-1]
            s.append(i)
        for i in range(n):
            l = right[i] - left[i] - 1
            if l * nums[i] > threshold:
                return l
        return -1

from sortedcontainers import SortedList

class Solution:
    def subarraysWithKDistinct(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pos = defaultdict(list)
        for i in range(n - 1, -1, -1):
            pos[nums[i]].append(i)
        bst = SortedList()
        for el in pos:
            bst.add(pos[el][-1])
        res = 0
        for i in range(n):
            a = bst[k - 1] if k - 1 < len(bst) else n
            b = bst[k] if k < len(bst) else n
            res += b - a
            bst.remove(pos[nums[i]].pop())
            if len(pos[nums[i]]) > 0:
                bst.add(pos[nums[i]][-1])
            else:
                bst.add(n)
        return res

class Solution:
    def subdomainVisits(self, cpdomains: List[str]) -> List[str]:
        ctr = {}
        for val in cpdomains:
            rep, domain = val.split(" ")
            rep = int(rep)
            doms = domain.split(".")
            n = len(doms)
            for i in range(n):
                curr = ".".join(doms[i:])
                ctr[curr] = ctr.get(curr, 0) + rep
        return ["{} {}".format(v, k) for k, v in ctr.items()]

class SubrectangleQueries:

    def __init__(self, rectangle: List[List[int]]):
        self.rec = rectangle

    def updateSubrectangle(self, row1: int, col1: int, row2: int, col2: int, newValue: int) -> None:
        for i in range(row1, row2 + 1):
            for j in range(col1, col2 + 1):
                self.rec[i][j] = newValue

    def getValue(self, row: int, col: int) -> int:
