class Solution:
    def gensets(self, nums, i, curr):
        if i == len(nums):
            self.subsets.add(tuple(curr))
            return
        self.gensets(nums, i + 1, curr)
        self.gensets(nums, i + 1, curr + [nums[i]])

    def subsetsWithDup(self, nums: List[int]) -> List[List[int]]:
        nums.sort()
        self.subsets = set()
        self.gensets(nums, 0, [])
        return list(self.subsets)

class Solution:
    def subsets(self, nums: List[int]) -> List[List[int]]:
        n = len(nums)
        subsets = []
        for mask in range(1 << n):
            subset = []
            for i in range(n):
                if mask & 1 << i:
                    subset.append(nums[i])
            subsets.append(subset)
        return subsets

class Solution:
    def hasMatch(self, s: str, p: str) -> bool:
        n = len(s)
        a = p.split("*")[0]
        b = p.split("*")[1]
        if a not in s or b not in s:
            return False
        if a in s and b == "":
            return True
        if a == "" and b in s:
            return True
        first = -1
        last = -1
        for i in range(n):
            if s[i:i+len(a)] == a and first == -1:
                first = i + len(a) - 1
            if s[i:i+len(b)] == b:
                last = i
        return first < last

class Solution:
    def maxsum(self, arr):
        n = len(arr)
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] += p[i] + arr[i]
        msub = [float('-inf')] * n
        msub[0] = arr[0]
        for i in range(1, n):
            msub[i] = max(arr[i], arr[i] + msub[i - 1])
        lastone = lastneg = -1
        res = 0
        for i in range(n):
            if arr[i] == 1:
                if lastneg != -1:
                    res = max(res, msub[lastneg] + p[i + 1] - p[lastneg + 1])
                lastone = i
            if arr[i] == -1:
                if lastone != -1:
                    res = max(res, msub[lastone] + p[i + 1] - p[lastone + 1])
                lastneg = i
        return res

    def largestVariance(self, s: str) -> int:
        res = 0
        chars = set(s)
        for a in chars:
            for b in chars:
                mp = {a: 1, b: -1}
                res = max(res, self.maxsum([mp[c] for c in s if c in mp]))
        return res

class Solution:
    def substringXorQueries(self, s: str, queries: List[List[int]]) -> List[List[int]]:
        n = len(s)
        pos = {}
        for l in range(1, 33):
            for i in range(n - l + 1):
                curr = int(s[i : i + l], 2)
                if curr not in pos:
                    pos[curr] = [i, i + l - 1]
        res = []
        for l, r in queries:
            q = l ^ r
            if q in pos:
                res.append(pos[q])
            else:
                res.append([-1, -1])
        return res

class Solution:
    def countGoodSubstrings(self, s: str) -> int:
        n = len(s)
        if n < 3:
            return 0
        dist = 0
        ctr = [0] * 26
        for i in range(3):
            ctr[ord(s[i]) - ord('a')] += 1
        for i in range(n - 3):
            if max(ctr) == 1:
                dist += 1
            ctr[ord(s[i]) - ord('a')] -= 1
            ctr[ord(s[i+3]) - ord('a')] += 1
        if set(ctr) == {0, 1}:
            dist += 1
        return dist

class Solution:
    def subtractProductAndSum(self, n: int) -> int:
        p = 1
        s = 0
        while n > 0:
            d = n % 10
            p *= d
            s += d
            n = n // 10
        return p - s

import bisect

class Solution:
    def successfulPairs(self, spells: List[int], potions: List[int], success: int) -> List[int]:
        n = len(potions)
        potions.sort()
        return [n - bisect.bisect_left(potions, success / sp) for sp in spells]

class Solution:
    def getPos(self, board, i, j):
        pos = set(map(str, range(1, 10)))
        ci, cj = i - i % 3, j - j % 3
        for a in range(3):
            for b in range(3):
                if board[ci + a][cj + b] != "." and board[ci + a][cj + b] in pos:
                    pos.remove(board[ci + a][cj + b])
        for a in range(9):
            if board[i][a] in pos:
                pos.remove(board[i][a])
            if board[a][j] in pos:
                pos.remove(board[a][j])
        return pos

    def solve(self, board, spi):
        if spi >= len(self.spaces):
            return True
        if spi < len(self.spaces):
            i, j = self.spaces[spi]
            pos = self.getPos(board, i, j)
            for p in pos:
                board[i][j] = p
                currsolution = self.solve(board, spi + 1)
                if currsolution:
                    return True
                else:
                    board[i][j] = "."
        return False

    def solveSudoku(self, board: List[List[str]]) -> None:
        self.spaces = []
        for i in range(9):
            for j in range(9):
                if board[i][j] == ".":
                    self.spaces.append((i, j))
        self.solve(board, 0)

class Solution:
    def matrixSum(self, nums: List[List[int]]) -> int:
        m = len(nums)
        n = len(nums[0])
        for i in range(m):
            nums[i].sort()
        mx = [0] * n
        for i in range(m):
            for j in range(n):
                mx[j] = max(mx[j], nums[i][j])
        return sum(mx)

class Solution:
    def sumOfMultiples(self, n: int) -> int:
        val = lambda k: k * (n // k) * (n // k + 1) // 2
        return val(3) + val(5) + val(7) - val(15) - val(21) - val(35) + val(105)

class Solution:
    def getSumAbsoluteDifferences(self, nums: List[int]) -> List[int]:
        n = len(nums)
        order = sorted(nums)
        diff = {}
        p = [0]
        for el in order:
            p.append(p[-1] + el)
        for i in range(1, n + 1):
            diff[order[i - 1]] = order[i - 1] * (2 * i - n) - 2 * p[i] + p[-1]
        return [diff[el] for el in nums]

class Solution:
    def subsetXORSum(self, nums: List[int]) -> int:
        return (1 << len(nums) - 1) * reduce(lambda x, y: x | y, nums)

class Solution:
    def sumOfBeauties(self, nums: List[int]) -> int:
        n = len(nums)
        beauty = 0
        minvals = [0] * n
        minvals[n - 1] = nums[n - 1]
        for i in range(n - 2, -1, -1):
            minvals[i] = min(nums[i], minvals[i + 1])
        currmax = float('-inf')
        for i in range(n):
            if 1 <= i <= n - 2:
                if currmax < nums[i] < minvals[i + 1]:
                    beauty += 2
                elif nums[i - 1] < nums[i] < nums[i + 1]:
                    beauty += 1
            currmax = max(currmax, nums[i])
        return beauty

from collections import Counter

class Solution:
    def beautySum(self, s: str) -> int:
        n = len(s)
        res = 0
        for i in range(n):
            ctr = Counter()
            for j in range(i, n):
                ctr[s[j]] += 1
                res += max(ctr.values()) - min(ctr.values())
        return res

class Solution:
    def sumDigitDifferences(self, nums: List[int]) -> int:
        n = len(nums)
        res = 0
        while nums[0]:
            res += n * n
            ctr = [0] * 10
            for i in range(n):
                d = nums[i] % 10
                res -= 2 * ctr[d] + 1
                ctr[d] += 1
                nums[i] //= 10
        return res // 2

class Solution:
    def sumBase(self, n: int, k: int) -> int:
        total = 0
        while n > 0:
            total += n % k
            n = n // k
        return total

class Solution:
    def getLucky(self, s: str, k: int) -> int:
        op = ""
        for c in s:
            op += str(ord(c) - ord('a') + 1)
        for i in range(k):
            op = str(sum([int(d) for d in op]))
        return int(op)

class Solution:
    def sumOfDistancesInTree(self, n, edges):
        res = [0] * n
        subctr = [0] * n
        graph = [[] for _ in range(n)]
        for a, b in edges:
            graph[a].append(b)
            graph[b].append(a)
        def dfs(root, prev):
            s = 0
            ctr = 1
            for j in graph[root]:
                if j != prev:
                    currs, currctr = dfs(j, root)
                    ctr += currctr
                    s += currs + currctr
            subctr[root] = ctr
            return s, ctr
        res[0], tmp = dfs(0, -1)
        stack = [(0, -1)]
        while len(stack) > 0:
            curr, prev = stack.pop()
            for j in graph[curr]:
                if j != prev:
                    res[j] = n + res[curr] - 2 * subctr[j]
                    stack.append((j, curr))
        return res

class Solution:
    def sumEvenAfterQueries(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        evensum = 0
        for el in nums:
            if el % 2 == 0:
                evensum += el
        res = []
        for val, i in queries:
            if nums[i] % 2 == 0:
                evensum -= nums[i]
            nums[i] += val
            if nums[i] % 2 == 0:
                evensum += nums[i]
            res.append(evensum)
        return res

class Solution:
    def sumOfFlooredPairs(self, nums: List[int]) -> int:
        M = 10 ** 9 + 7
        MX = max(nums)
        ctr = [0] * (MX + 2)
        c = collections.Counter(nums)
        for el in c:
            mul = 1
            while el * mul <= MX:
                ctr[el * mul] += c[el] * mul
                ctr[min(el * (mul + 1), MX + 1)] -= c[el] * mul
                mul += 1
        for i in range(MX):
            ctr[i + 1] += ctr[i]
            ctr[i + 1] %= M
        return sum(ctr[el] for el in nums) % M

class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        n = len(nums)
        res = 0
        for i in range(n):
            good = True
            if i - k >= 0 and nums[i - k] >= nums[i]:
                good = False
            if i + k < n and nums[i + k] >= nums[i]:
                good = False
            if good:
                res += nums[i]
        return res

from sortedcontainers import SortedList

class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        res = 0
        for i in range(n):
            curr = SortedList()
            ctr = 0
            for j in range(i, n):
                curr.add(nums[j])
                k = curr.bisect_left(nums[j])
                p = 0
                diff = 0
                for l in [k - 1, k + 1]:
                    if 0 <= l < len(curr):
                        p += 1
                        if l == k - 1:
                            diff -= curr[l]
                        else:
                            diff += curr[l]
                        if abs(curr[k] - curr[l]) > 1:
                            ctr += 1
                if p == 2 and diff > 1:
                    ctr -= 1
                res += ctr
        return res

def gen(b, n, m=40):
    c = 0
    s = 0
    for l in range(1, m + 1):
        h = (l + 1) // 2
        a = b ** (h - 1)
        e = b ** h
        for p in range(a, e):
            d = []
            t = p
            for _ in range(h):
                d.append(t % b)
                t //= b
            d = d[::-1]
            if l % 2 == 0:
                q = d + d[::-1]
            else:
                q = d + d[-2::-1]
            v = 0
            for x in q:
                v = v * b + x
            if str(v) == str(v)[::-1]:
                s += v
                c += 1
                if c >= n:
                    return s

class Solution:
    def kMirror(self, k: int, n: int) -> int:
        return gen(k, n)

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] = p[i] + nums[i]
        dp = [[float('-inf')] * (k + 2) for _ in range(n + 1)]
        dp[n][0] = 0
        for rem in range(k + 1):
            best = [float('-inf')] * (n + 2)
            for t in range(n, -1, -1):
                best[t] = max(best[t + 1], p[t] + dp[t][rem - 1])
            for i in range(n - 1, -1, -1):
                dp[i][rem] = dp[i + 1][rem]
                if i + m <= n:
                    dp[i][rem] = max(dp[i][rem], best[i + m] - p[i])
        return dp[0][k]

class Solution:
    def sumOfLeftLeaves(self, root: Optional[TreeNode]) -> int:
        def dfs(r, left):
            if not r:
                return 0
            if not r.left and not r.right and left:
                return r.val
            return dfs(r.left, True) + dfs(r.right, False)
        return dfs(root, False)

class Solution:
    def matrixSumQueries(self, n: int, queries: List[List[int]]) -> int:
        q = len(queries)
        r = set()
        c = set()
        res = 0
        for i in range(q - 1, -1, -1):
            if queries[i][0] == 0 and queries[i][1] not in r:
                res += (n - len(c)) * queries[i][2]
                r.add(queries[i][1])
            if queries[i][0] == 1 and queries[i][1] not in c:
                res += (n - len(r)) * queries[i][2]
                c.add(queries[i][1])
        return res

class Solution:
    def findBestValue(self, arr: List[int], target: int) -> int:
        n = len(arr)
        total = sum(arr)
        beg = min(arr)
        end = max(arr)
        res = (float('inf'), -1)
        while beg <= end:
            mid = (beg + end) // 2
            curr = 0
            for el in arr:
                curr += el if el < mid else mid
            if curr >= target:
                res = min(res, (curr - target, mid))
                end = mid - 1
            else:
                res = min(res, (target - curr, mid))
                beg = mid + 1
        for extra in [target // n, target // n + 1]:
            curr = 0
            for el in arr:
                curr += el if el < extra else extra
            res = min(res, (abs(curr - target), extra))
        return res[1]

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def sumEvenGrandparent(self, root: TreeNode) -> int:
        paths = [(root, [root.val] if root else [])]
        i = 0
        total = 0
        while i < len(paths):
            curr, currpath = paths[i]
            if curr:
                if len(currpath) > 2 and currpath[-3] % 2 == 0:
                    total += curr.val
                if curr.left:
                    paths.append((curr.left, currpath + [curr.left.val]))
                if curr.right:
                    paths.append((curr.right, currpath + [curr.right.val]))
            i += 1
        return total

class Solution:
    def rev(self, n):
        res = 0
        while n:
            res = 10 * res + n % 10
            n //= 10
        return res

    def sumOfNumberAndReverse(self, num: int) -> bool:
        if num <= 18:
            return num % 2 == 0 or num % 11 == 0
        elif num < 100:
            return num % 11 == 0
        for i in range(num + 1):
            a = i
            b = num - i
            if self.rev(a) == b:
                return True
        return False

class Solution:
    def minimumNumbers(self, num: int, k: int) -> int:
        if num == 0:
            return 0
        d = num % 10
        for n in range(1, num + 1):
            if (k * n) % 10 == d:
                newnum = num - k * n
                if newnum >= 0 and newnum % 10 == 0:
                    return n
        return -1

from collections import defaultdict

class Solution:
    def sumPrefixScores(self, words: List[str]) -> List[int]:
        ctr = defaultdict(int)
        for w in words:
            n = len(w)
            for i in range(1, n + 1):
                ctr[w[:i]] += 1
        res = []
        for w in words:
            n = len(w)
            curr = 0
            for i in range(1, n + 1):
                curr += ctr[w[:i]]
            res.append(curr)
        return res

from collections import *

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, a):
        if a == self.parent[a]:
            return a
        self.parent[a] = self.find(self.parent[a])
        return self.parent[a]

    def union(self, a, b):
        parent_a = self.find(a)
        parent_b = self.find(b)
        if parent_a != parent_b:
            if self.size[parent_a] < self.size[parent_b]:
                parent_a, parent_b = parent_b, parent_a
            self.parent[parent_b] = parent_a
            self.size[parent_a] += self.size[parent_b]

class Solution:
    def sumRemoteness(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        res = [[0] * n for _ in range(m)]
        pos = lambda i, j: n * i + j
        dsu = DSU(m * n)
        for i in range(m):
            for j in range(n):
                if grid[i][j] == -1:
                    continue
                for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
                    if 0 <= x < m and 0 <= y < n and grid[x][y] != -1:
                        dsu.union(pos(i, j), pos(x, y))
        s = Counter()
        total = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] != -1:
                    s[dsu.find(pos(i, j))] += grid[i][j]
                    total += grid[i][j]
        res = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] != -1:
                    res += total - s[dsu.find(pos(i, j))]
        return res

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def sumRootToLeaf(self, root: Optional[TreeNode]) -> int:
        total = 0
        paths = [(root, root.val if root else 0)]
        i = 0
        while i < len(paths):
            curr, currval = paths[i]
            if curr.left or curr.right:
                if curr.left:
                    paths.append((curr.left, 2 * currval + curr.left.val))
                if curr.right:
                    paths.append((curr.right, 2 * currval + curr.right.val))
            else:
                total += currval
            i += 1
        return total

from collections import Counter

class Solution:
    def solve(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        M = 10 ** 9 + 7
        n = len(nums)
        for i in range(len(queries)):
            queries[i].append(i)
        res = [0] * len(queries)
        queries.sort()
        s = defaultdict(Counter)
        j = n - 1
        for i in range(len(queries) - 1, -1, -1):
            while j >= queries[i][0]:
                x = 1
                while x * x <= n:
                    s[x][j % x] += nums[j]
                    s[x][j % x] %= M
                    x += 1
                j -= 1
            if queries[i][1] * queries[i][1] <= n:
                res[queries[i][2]] = s[queries[i][1]][queries[i][0] % queries[i][1]]
            else:
                curr = 0
                pos = queries[i][0]
                while pos < n:
                    curr += nums[pos]
                    curr %= M
                    pos += queries[i][1]
                res[queries[i][2]] = curr
        return res

import math

class Solution:
    def isPerfectSquare(self, num: int) -> bool:
        beg = 0
        end = num
        while beg <= end:
            mid = (beg + end) // 2
            if mid * mid == num:
                return True
            elif beg == end:
                break
            elif mid * mid > num:
                end = mid
            else:
                beg = mid + 1
        return False

    def judgeSquareSum(self, c: int) -> bool:
        k = 1 + int(math.sqrt(c))
        for i in range(0, k):
            if self.isPerfectSquare(c - i * i):
                return True
        return False

class Solution:
    def sumOfSquares(self, nums: List[int]) -> int:
        n = len(nums)
        res = 0
        for i in range(n):
            if n % (i + 1) == 0:
                res += nums[i] * nums[i]
        return res

class Solution:
    def getSum(self, nums, n, cmp):
        stack = []
        nextpos = [n] * n
        prevpos = [-1] * n
        for i in range(n):
            while len(stack) > 0 and cmp(nums[i], nums[stack[-1]]):
                curr = stack.pop()
                nextpos[curr] = i
            if len(stack) > 0:
                prevpos[i] = stack[-1]
            stack.append(i)
        res = 0
        for i in range(n):
            l = prevpos[i]
            r = nextpos[i]
            res += (i - l) * (r - i) * nums[i]
        return res

    def subArrayRanges(self, nums: List[int]) -> int:
        n = len(nums)
        maxvals = self.getSum(nums, n, lambda a, b: a > b)
        minvals = self.getSum(nums, n, lambda a, b: a < b)
        return maxvals - minvals

from collections import Counter

class Solution:
    def sumOfUnique(self, nums: List[int]) -> int:
