class Solution:
    def subarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        res = [0] * (n + 1)
        for i in range(n):
            res[max(i - nums[i], 0)] += 1
            res[i + 1] -= 1
        for i in range(n):
            res[i + 1] += res[i]
        return sum(res[i] * nums[i] for i in range(n))

class Solution:
    def inorder(self, root, val):
        if root:
            newval = val * 10 + root.val
            self.inorder(root.left, newval)
            self.inorder(root.right, newval)
            if not root.left and not root.right:
                self.res += newval

    def sumNumbers(self, root: Optional[TreeNode]) -> int:
        self.res = 0
        self.inorder(root, 0)
        return self.res

class Solution:
    def summaryRanges(self, nums: List[int]) -> List[str]:
        n = len(nums)
        if n == 0:
            return []
        ranges = [[nums[0]]]
        for i in range(1, n):
            if nums[i] == ranges[-1][-1] + 1:
                ranges[-1].append(nums[i])
            else:
                ranges.append([nums[i]])
        m = len(ranges)
        for i in range(m):
            if len(ranges[i]) == 1:
                ranges[i] = "{}".format(ranges[i][0])
            else:
                ranges[i] = "{}->{}".format(ranges[i][0], ranges[i][-1])
        return ranges

class Solution:
    def superPow(self, a: int, b: List[int]) -> int:
        res = 1
        for d in b:
            res = pow(res, 10, 1337) * pow(a, d, 1337)
            res %= 1337
        return res

import heapq

class Solution:
    def nthSuperUglyNumber(self, n: int, primes: List[int]) -> int:
        heap = [1]
        v = {1}
        MAX = 1 << 32
        primes.sort()
        for _ in range(n - 1):
            curr = heapq.heappop(heap)
            for p in primes:
                if curr * p <= MAX:
                    if curr * p not in v:
                        v.add(curr * p)
                        heapq.heappush(heap, curr * p)
                else:
                    break
        return heap[0]

class Solution:
    def DFS(self, board, v, i, j, m, n):
        v.add((i, j))
        for di, dj in [(-1, 0), (0, 1), (1, 0), (0, -1)]:
            if 0 <= i + di < m and 0 <= j + dj < n:
                if board[i + di][j + dj] == "O" and (i + di, j + dj) not in v:
                    self.DFS(board, v, i + di, j + dj, m, n)

    def solve(self, board: List[List[str]]) -> None:
        m = len(board)
        n = len(board[0])
        for i in range(m):
            for j in range(n):
                if board[i][j] == "O":
                    v = set()
                    self.DFS(board, v, i, j, m, n)
                    isEnclosed = True
                    for x, y in v:
                        if x == 0 or x == m - 1 or y == 0 or y == n - 1:
                            isEnclosed = False
                            break
                    if isEnclosed:
                        for x, y in v:
                            board[x][y] = "X"

class Solution:
    def getStats(self, s):
        rel = ""
        ctr = 0
        prefl = []
        prefr = []
        for c in s:
            if c != "X":
                rel += c
                if c == "L":
                    prefl.append(ctr)
                else:
                    prefr.append(ctr)
            else:
                ctr += 1
        return [rel, ctr, prefl, prefr]

    def canTransform(self, start: str, target: str) -> bool:
        rels, ctrs, sprefl, sprefr = self.getStats(start)
        relt, ctrt, tprefl, tprefr = self.getStats(target)
        if rels != relt or ctrs != ctrt or len(sprefl) != len(tprefl) or len(sprefr) != len(tprefr):
            return False
        m = len(sprefl)
        for i in range(m):
            if tprefl[i] > sprefl[i]:
                return False
        n = len(sprefr)
        for i in range(n):
            if tprefr[i] < sprefr[i]:
                return False
        return True

class Solution:
    def maxRepOpt1(self, text: str) -> int:
        n = len(text)
        c = Counter(text)
        v = []
        res = 0
        i = 0
        while i < n:
            ctr = 1
            while i < n - 1 and text[i] == text[i + 1]:
                i += 1
                ctr += 1
            res = max(res, ctr + int(ctr < c[text[i]]))
            v.append((text[i], ctr))
            i += 1
        for i in range(len(v) - 2):
            if v[i + 1][1] == 1 and v[i][0] == v[i + 2][0]:
                res = max(res, v[i][1] + v[i + 2][1] + int(c[v[i][0]] > v[i][1] + v[i + 2][1]))
        return res

class Solution:
    def swapPairs(self, head: Optional[ListNode]) -> Optional[ListNode]:
        if not head or not head.next:
            return head
        newhead = head.next
        head.next = self.swapPairs(head.next.next)
        newhead.next = head
        return newhead

class Solution:
    def lenList(self, head, a, k):
        if head:
            curr = 1 + self.lenList(head.next, a + 1, k)
            if a == k:
                self.a = head
            if curr == k:
                self.b = head
            return curr
        return 0

    def swapNodes(self, head: Optional[ListNode], k: int) -> Optional[ListNode]:
        n = self.lenList(head, 1, k)
        self.a.val, self.b.val = self.b.val, self.a.val
        return head

class Solution:
    def isMirror(self, p: Optional[TreeNode], q: Optional[TreeNode]) -> bool:
        if not p or not q:
            if p or q:
                return False
            return True
        if p.val == q.val and self.isMirror(p.left, q.right) and self.isMirror(p.right, q.left):
            return True

    def isSymmetric(self, root: Optional[TreeNode]) -> bool:
        if root:
            return self.isMirror(root.left, root.right)
        return True

import heapq

class Solution:
    def pickGifts(self, gifts: List[int], k: int) -> int:
        heap = []
        for el in gifts:
            heapq.heappush(heap, -el)
        for _ in range(k):
            v = -heapq.heappop(heap)
            heapq.heappush(heap, -int(v ** 0.5))
        return -sum(heap)

class Solution:
    def takeCharacters(self, s: str, k: int) -> int:
        n = len(s)
        a, b, c = s.count('a'), s.count('b'), s.count('c')
        ctr = [0, 0, 0]
        res = float('inf')
        i = 0
        for j in range(n):
            ctr[ord(s[j]) - ord('a')] += 1
            while i <= j and (a - ctr[0] < k or b - ctr[1] < k or c - ctr[2] < k):
                ctr[ord(s[i]) - ord('a')] -= 1
                i += 1
            if a - ctr[0] >= k and b - ctr[1] >= k and c - ctr[2] >= k:
                res = min(res, n - (j - i + 1))
        if res == float('inf'):
            return -1
        return res

class Solution:
    def maximumEnergy(self, energy: List[int], k: int) -> int:
        n = len(energy)
        s = [0] * n
        res = float('-inf')
        for i in range(n - 1, -1, -1):
            s[i % k] += energy[i]
            res = max(res, s[i % k])
        return res

class Solution:
    def tallestBillboard(self, rods: List[int]) -> int:
        S = sum(rods) + 1
        prev = [float('-inf')] * S
        prev[0] = 0
        curr = [float('-inf')] * S
        g = lambda x: prev[x] if 0 <= x < len(prev) else float('-inf')
        for i in range(len(rods) - 1, -1, -1):
            for j in range(S):
                curr[j] = max(rods[i] + g(j + rods[i]), rods[i] + g(abs(j - rods[i])), g(j))
            prev, curr = curr, prev
        return prev[0] // 2

class Solution:
    def count(self, nums, i, n, curr, target):
        if i >= n:
            if 2 * curr == target:
                return 1
            return 0
        key = (i, curr)
        if key in self.cache:
            return self.cache[key]
        a = self.count(nums, i + 1, n, curr + nums[i], target)
        b = self.count(nums, i + 1, n, curr, target)
        res = a + b
        self.cache[key] = res
        return res

    def findTargetSumWays(self, nums: List[int], target: int) -> int:
        n = len(nums)
        total = sum(nums)
        self.cache = {}
        return self.count(nums, 0, n, 0, total + target)

class Solution:
    def taskSchedulerII(self, tasks: List[int], space: int) -> int:
        t = 0
        prev = {}
        for task in tasks:
            if task in prev:
                t += max(space - t + prev[task] + 1, 0)
            prev[task] = t
            t += 1
        return t

from collections import *

class Solution:
    def leastInterval(self, tasks: List[str], n: int) -> int:
        t = 0
        available = defaultdict(lambda: -1)
        ctr = Counter(tasks)
        while ctr:
            best = (0, "")
            for c in ctr:
                if available[c] <= t:
                    best = max(best, (ctr[c], c))
            t += 1
            if best[0] == 0:
                continue
            ctr[best[1]] -= 1
            if ctr[best[1]] == 0:
                del ctr[best[1]]
            available[best[1]] = t + n
        return t

class Solution:
    def findPoisonedDuration(self, timeSeries: List[int], duration: int) -> int:
        n = len(timeSeries)
        total = duration
        for i in range(1, n):
            total += min(timeSeries[i] - timeSeries[i - 1], duration)
        return total

class Solution:
    def format(self, words, a, b, maxWidth, p, isLast):
        n = b - a
        if n == 1 or isLast:
            used = p[b] - p[a] + n - 1
            return " ".join(words[a:b]) + " " * (maxWidth - used)
        spaces = maxWidth - (p[b] - p[a])
        gap = spaces // (n - 1)
        k = spaces % (n - 1)
        res = []
        for i in range(a, b):
            res.append(words[i])
            if i == b - 1:
                break
            if k > 0:
                res.append(" " * (gap + 1))
                k -= 1
            else:
                res.append(" " * gap)
        return "".join(res)

    def justify(self, words, maxWidth, p, i, n):
        if i >= n:
            return []
        j = i
        l = 0
        while j < n and l + len(words[j]) <= maxWidth:
            l += len(words[j]) + 1
            j += 1
        rem = self.justify(words, maxWidth, p, j, n)
        return [self.format(words, i, j, maxWidth, p, len(rem) == 0)] + rem

    def fullJustify(self, words: List[str], maxWidth: int) -> List[str]:
        p = [0]
        for w in words:
            p.append(p[-1] + len(w))
        return self.justify(words, maxWidth, p, 0, len(words))

class Solution:
    def earliestAndLatest(self, n, f, s):
        f -= 1
        s -= 1
        f0, s0 = f, s
        start = (1 << n) - 1
        min_r = n + 1
        max_r = 0
        stack = [(start, 1)]
        seen = set()
        while stack:
            mask, r = stack.pop()
            if mask in seen:
                continue
            seen.add(mask)
            if not ((mask >> f0) & 1 and (mask >> s0) & 1):
                continue
            alive = [i for i in range(n) if (mask >> i) & 1]
            m = len(alive)
            pairs = []
            i, j = 0, m - 1
            while i < j:
                pairs.append((alive[i], alive[j]))
                i += 1
                j -= 1
            mid = alive[i] if i == j else None
            meet = False
            for x, y in pairs:
                if {x, y} == {f0, s0}:
                    if r < min_r:
                        min_r = r
                    if r > max_r:
                        max_r = r
                    meet = True
                    break
            if meet:
                continue
            next_masks = [0]
            for x, y in pairs:
                tmp = []
                if {x, y} != {f0, s0}:
                    for m0 in next_masks:
                        tmp.append(m0 | (1 << x))
                        tmp.append(m0 | (1 << y))
                else:
                    for m0 in next_masks:
                        tmp.append(m0 | (1 << f0))
                next_masks = tmp
            if mid is not None:
                for k in range(len(next_masks)):
                    next_masks[k] |= (1 << mid)
            for nm in next_masks:
                stack.append((nm, r + 1))
        return [min_r, max_r]

class Solution:
    def hardestWorker(self, n: int, logs: List[List[int]]) -> int:
        memp = 0
        mtime = 0
        prev = 0
        for eid, t in logs:
            if t - prev > mtime:
                mtime = t - prev
                memp = eid
            elif t - prev == mtime and eid < memp:
                memp = eid
            prev = t
        return memp

class Solution:
    def getHappyString(self, n: int, k: int) -> str:
        @lru_cache(None)
        def getcount(i, prev):
            if i >= n:
                return 1
            ctr = 0
            for x in range(3):
                if x != prev:
                    ctr += getcount(i + 1, x)
            return ctr
        if getcount(0, -1) < k:
            return ""
        res = []
        for i in range(n):
            for c in range(3):
                if len(res) > 0 and c == res[-1]:
                    continue
                curr = getcount(i + 1, c)
                if curr >= k:
                    res.append(c)
                    break
                else:
                    k -= curr
        return "".join(chr(ord('a') + x) for x in res)

import bisect
import heapq

class Solution:
    def kWeakestRows(self, mat: List[List[int]], k: int) -> List[int]:
        mat = [row[::-1] for row in mat]
        heap = []
        for i, row in enumerate(mat):
            strength = -bisect.bisect_left(row, 1)
            heapq.heappush(heap, (strength, i))
        res = []
        for i in range(k):
            res.append(heapq.heappop(heap)[1])
        return res

class Solution:
    def mostSimilar(self, n: int, roads: List[List[int]], names: List[str], targetPath: List[str]) -> List[int]:
        graph = [[] for _ in range(n)]
        for u, v in roads:
            graph[u].append(v)
            graph[v].append(u)
        @lru_cache(maxsize = None)
        def dp(i, pos):
            if pos >= len(targetPath):
                return 0
            cost = int(names[i] != targetPath[pos])
            res = float('inf')
            for j in graph[i]:
                res = min(res, cost + dp(j, pos + 1))
            return res
        start = min(range(n), key = lambda p: dp(p, 0))
        res = [start]
        for pos in range(1, len(targetPath)):
            curr = (float('inf'), -1)
            for j in graph[res[-1]]:
                curr = min(curr, (dp(j, pos), j))
            res.append(curr[1])
        return res

class Solution:
    def count(self, nums, i, n, used, k, pos):
        if i >= n:
            return 1 if used > 0 else 0
        if used in self.cache:
            return self.cache[used]
        res = self.count(nums, i + 1, n, used, k, pos)
        if pos.get(nums[i] - k, 0) & used == 0:
            res += self.count(nums, i + 1, n, used | (1 << i), k, pos)
        self.cache[used] = res
        return res

    def beautifulSubsets(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nums.sort()
        pos = {}
        for i in range(n):
            if nums[i] not in pos:
                pos[nums[i]] = 0
            pos[nums[i]] |= (1 << i)
        used = 0
        self.cache = {}
        return self.count(nums, 0, n, used, k, pos)

class FenwickTree:
    def __init__(self, x):
        self.bit = x
        for i in range(len(x)):
            j = i | (i + 1)
            if j < len(x):
                x[j] += x[i]

    def update(self, idx, x):
        while idx < len(self.bit):
            self.bit[idx] += x
            idx |= idx + 1

    def query(self, end):
        x = 0
        while end:
            x += self.bit[end - 1]
            end &= end - 1
        return x

class Solution:
    def smallestChair(self, times: List[List[int]], targetFriend: int) -> int:
        n = len(times)
        pos = []
        for i in range(n):
            pos.append((times[i][0], 1, i))
            pos.append((times[i][1], -1, i))
        pos.sort()
        used = FenwickTree([0] * (n + 1))
        seat = {}
        for t, inc, friend in pos:
            if inc == 1:
                beg = 0
                end = n
                chair = end
                while beg <= end:
                    mid = (beg + end) // 2
                    if used.query(mid + 1) < mid + 1:
                        chair = mid
                        end = mid - 1
                    else:
                        beg = mid + 1
                used.update(chair, 1)
                seat[friend] = chair
            else:
                used.update(seat[friend], -1)
        return seat[targetFriend]

class Solution:
    def numberOfWeakCharacters(self, properties: List[List[int]]) -> int:
        n = len(properties)
        seq = sorted(range(n), key = lambda i: properties[i][0])
        res = 0
        mval = float('-inf')
        currmval = float('-inf')
        for i in range(n - 1, -1, -1):
            if i < n - 1 and properties[seq[i]][0] < properties[seq[i + 1]][0]:
                mval = currmval
            if properties[seq[i]][1] < mval:
                res += 1
            currmval = max(currmval, properties[seq[i]][1])
        return res

