import bisect

class TimeMap:
    def __init__(self):
        self.store = defaultdict(list)

    def set(self, key: str, value: str, timestamp: int) -> None:
        bisect.insort(self.store[key], (timestamp, value))

    def get(self, key: str, timestamp: int) -> str:
        i = bisect.bisect_left(self.store[key], (timestamp, "z" * 101))
        if i == 0:
            return ""
        return self.store[key][i - 1][1]

from collections import deque

class Solution:
    def timeRequiredToBuy(self, tickets: List[int], k: int) -> int:
        n = len(tickets)
        q = deque()
        for i in range(n):
            q.appendleft((tickets[i], i))
        t = 0
        while q:
            t += 1
            c, pos = q.pop()
            c -= 1
            if c > 0:
                q.appendleft((c, pos))
            elif pos == k:
                return t

from collections import deque, defaultdict

class Solution:
    def numOfMinutes(self, n: int, headID: int, manager: List[int], informTime: List[int]) -> int:
        graph = defaultdict(set)
        for i in range(n):
            graph[manager[i]].add(i)
        q = deque([(headID, 0)])
        res = 0
        while len(q) > 0:
            curr, t = q.pop()
            res = max(res, t)
            for person in graph[curr]:
                q.appendleft((person, t + informTime[curr]))
        return res

class Solution:
    def secondsToRemoveOccurrences(self, s: str) -> int:
        n = len(s)
        res = 0
        s = list(s)
        while True:
            changes = []
            for i in range(n - 1):
                if s[i] == "0" and s[i + 1] == "1":
                    changes.append(i)
            if len(changes) > 0:
                for i in changes:
                    s[i] = "1"
                    s[i + 1] = "0"
                res += 1
            else:
                break
        return res

class Solution:
    def timeTaken(self, edges: List[List[int]]) -> List[int]:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for a, b in edges:
            graph[a].append(b)
            graph[b].append(a)
        f = [0] * n
        s = [0] * n
        c = [0] * n
        def dfs(i, p):
            for j in graph[i]:
                if j != p:
                    cost = 1 if j & 1 else 2
                    dfs(j, i)
                    if f[j] + cost > f[i]:
                        s[i] = f[i];
                        f[i] = f[j] + cost
                        c[i] = j
                    elif f[j] + cost > s[i]:
                        s[i] = f[j] + cost
        dfs(0, -1)
        res = [0] * n
        def sdfs(i, p):
            for j in graph[i]:
                if j != p:
                    cost = 1 if i & 1 else 2
                    if c[i] == j:
                        if f[j] < s[i] + cost:
                            s[j] = f[j]
                            f[j] = s[i] + cost
                            c[j] = i
                        else:
                            s[j] = max(s[j], s[i] + cost)
                    else:
                        s[j] = f[j]
                        f[j] = f[i] + cost
                        c[j] = i
                    sdfs(j, i)
        sdfs(0, -1)
        return f

