class Solution:
    def appealSum(self, s: str) -> int:
        ind = lambda c: ord(s[i]) - ord('a')
        n = len(s)
        res = 0
        last = [-1] * 26
        for i in range(n):
            res += (i - last[ind(s[i])]) * (n - i)
            last[ind(s[i])] = i
        return res

M = 10 ** 9 + 7

def mat_mult(A, B):
    size = len(A)
    result = [[0] * size for _ in range(size)]
    for i in range(size):
        for j in range(size):
            for k in range(size):
                result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % M
    return result

def mat_pow(mat, exp):
    size = len(mat)
    result = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
    base = mat
    while exp > 0:
        if exp % 2 == 1:
            result = mat_mult(result, base)
        base = mat_mult(base, base)
        exp //= 2
    return result

class Solution:
    def lengthAfterTransformations(self, s: str, t: int):
        mul = [[0] * 26 for _ in range(26)]
        for i in range(26):
            for c in range(i + 1, i + (2 if i != 25 else 3)):
                mul[c % 26][i] += 1
        ctr = [0] * 26
        for c in s:
            ctr[ord(c) - ord('a')] += 1
        mul = mat_pow(mul, t)
        res = [0] * 26
        for i in range(26):
            for j in range(26):
                res[i] = (res[i] + mul[i][j] * ctr[j]) % M
        return sum(res) % M

M = 10 ** 9 + 7

def mat_mult(A, B):
    size = len(A)
    result = [[0] * size for _ in range(size)]
    for i in range(size):
        for j in range(size):
            for k in range(size):
                result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % M
    return result

def mat_pow(mat, exp):
    size = len(mat)
    result = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
    base = mat
    while exp > 0:
        if exp % 2 == 1:
            result = mat_mult(result, base)
        base = mat_mult(base, base)
        exp //= 2
    return result

class Solution:
    def lengthAfterTransformations(self, s: str, t: int, nums: List[int]) -> int:
        mul = [[0] * 26 for _ in range(26)]
        for i in range(26):
            for c in range(i + 1, i + nums[i] + 1):
                mul[c % 26][i] += 1
        ctr = [0] * 26
        for c in s:
            ctr[ord(c) - ord('a')] += 1
        mul = mat_pow(mul, t)
        res = [0] * 26
        for i in range(26):
            for j in range(26):
                res[i] = (res[i] + mul[i][j] * ctr[j]) % M
        return sum(res) % M

import heapq

class Solution:
    def totalCost(self, costs: List[int], k: int, candidates: int) -> int:
        n = len(costs)
        heap = []
        i = 0
        j = n - 1
        for _ in range(candidates):
            if i <= j:
                heapq.heappush(heap, (costs[i], i, True))
                i += 1
                if i <= j:
                    heapq.heappush(heap, (costs[j], j, False))
                    j -= 1
        res = 0
        for _ in range(k):
            curr, pos, left = heapq.heappop(heap)
            res += curr
            if left and i <= j:
                heapq.heappush(heap, (costs[i], i, True))
                i += 1
            if not left and i <= j:
                heapq.heappush(heap, (costs[j], j, False))
                j -= 1
        return res

class Solution:
    def distanceTraveled(self, mainTank: int, additionalTank: int) -> int:
        res = 0
        ctr = 0
        while mainTank > 0:
            res += 10
            mainTank -= 1
            ctr += 1
            ctr %= 5
            if ctr == 0 and additionalTank > 0:
                mainTank += 1
                additionalTank -= 1
        return res

class Solution:
    def totalHammingDistance(self, nums: List[int]) -> int:
        n = len(nums)
        res = 0
        for b in range(32):
            x = 0
            for el in nums:
                if el & (1 << b):
                    x += 1
            res += x * (n - x)
        return res

