import heapq

class Solution:
    def trapRainWater(self, heightMap: List[List[int]]) -> int:
        m = len(heightMap)
        n = len(heightMap[0])
        heap = []
        v = [[False] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                    heapq.heappush(heap, (heightMap[i][j], i, j))
                    v[i][j] = True
        res = 0
        while heap:
            h, i, j = heapq.heappop(heap)
            for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
                if 0 <= x < m and 0 <= y < n and not v[x][y]:
                    v[x][y] = True
                    if heightMap[x][y] < h:
                        res += h - heightMap[x][y]
                    heightMap[x][y] = max(heightMap[x][y], h)
                    heapq.heappush(heap, (heightMap[x][y], x, y))
        return res

class Solution:
    def trap(self, height: List[int]) -> int:
        blocks = 0
        n = 0
        h = float('-inf')
        for hh in height:
            blocks += hh
            n += 1
            h = max(h, hh)
        total = 0
        left = 0
        right = n - 1
        for i in range(h):
            while height[left] <= i:
                left += 1
            while height[right] <= i:
                right -= 1
            total += right - left
        total -= (blocks - h)
        return total

from collections import defaultdict

class Solution:
    def getCoprimes(self, nums: List[int], edges: List[List[int]]) -> List[int]:
        n = len(nums)
        m = min(nums)
        M = max(nums)
        graph = defaultdict(set)
        latest = defaultdict(list)
        for a, b in edges:
            graph[a].add(b)
            graph[b].add(a)
        res = [-1] * n
        def gcd(a, b):
            while b:
                a, b = b, a % b
            return a
        def dfs(graph, curr, prev, d):
            maxdepth = (-1, -1)
            for g in range(m, M + 1):
                if gcd(nums[curr], g) == 1 and len(latest[g]) > 0:
                    maxdepth = max(maxdepth, latest[g][-1])
            res[curr] = maxdepth[1]
            for j in graph[curr]:
                if j == prev:
                    continue
                latest[nums[curr]].append((d, curr))
                dfs(graph, j, curr, d + 1)
                latest[nums[curr]].pop()
        dfs(graph, 0, -1, 0)
        return res

class Solution:
    def minPath(self, triangle, i, j, n):
        if i == n - 1:
            return triangle[i][j]
        if (i, j) in self.cache:
            return self.cache[(i, j)]
        currmin = min(self.minPath(triangle, i + 1, j, n), self.minPath(triangle, i + 1, j + 1, n))
        self.cache[(i, j)] = triangle[i][j] + currmin
        return self.cache[(i, j)]

    def minimumTotal(self, triangle: List[List[int]]) -> int:
        self.cache = {}
        return self.minPath(triangle, 0, 0, len(triangle))

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def trimBST(self, root: Optional[TreeNode], low: int, high: int) -> Optional[TreeNode]:
        if root:
            if low <= root.val <= high:
                root.left = self.trimBST(root.left, low, high)
                root.right = self.trimBST(root.right, low, high)
            elif root.val < low:
                root = self.trimBST(root.right, low, high)
            else:
                root = self.trimBST(root.left, low, high)
        return root

from collections import defaultdict

class Solution:
    def countTriplets(self, nums: List[int]) -> int:
        n = len(nums)
        ctr = defaultdict(int)
        for i in range(n):
            for j in range(n):
                ctr[nums[i] & nums[j]] += 1
        res = 0
        for i in range(n):
            for val in ctr:
                if nums[i] & val == 0:
                    res += ctr[val]
        return res

class Solution:
    def truncateSentence(self, s: str, k: int) -> str:
        n = len(s)
