from collections import Counter

class Solution:
    def tupleSameProduct(self, nums) -> int:
        n = len(nums)
        ctr = Counter()
        for i in range(n):
            for j in range(i + 1, n):
                ctr[nums[i] * nums[j]] += 1
        res = 0
        for p in ctr:
            res += 4 * ctr[p] * (ctr[p] - 1)
        return res

class Solution:
    def maxTwoEvents(self, events: List[List[int]]) -> int:
        n = len(events)
        mp = {}
        for a, b, c in events:
            mp[a] = mp[b] = 0
        for i, el in enumerate(sorted(mp)):
            mp[el] = i
        events.sort()
        maxscore = [0] * (len(mp) + 1)
        j = n - 1
        maxyet = 0
        for i in range(len(mp), -1, -1):
            while j >= 0 and mp[events[j][0]] >= i:
                maxyet = max(maxyet, events[j][2])
                j -= 1
            maxscore[i] = maxyet
        res = 0
        for a, b, c in events:
            res = max(res, c + maxscore[mp[b] + 1])
        return res

from functools import cmp_to_key

class Solution:
    def compare(self, cost1, cost2):
        a, b = cost1
        c, d = cost2
        if a + d <= b + c:
            return -1
        return 1

    def twoCitySchedCost(self, costs: List[List[int]]) -> int:
        n = len(costs)
        costs.sort(key = cmp_to_key(self.compare))
        cost = 0
        for i in range(n // 2):
            cost += costs[i][0]
        for i in range(n // 2, n):
            cost += costs[i][1]
        return cost

class Solution:
    def maxDistance(self, colors: List[int]) -> int:
        indexes = {}
        for i, c in enumerate(colors):
            if c in indexes:
                indexes[c] = (min(i, indexes[c][0]), max(i, indexes[c][1]))
            else:
                indexes[c] = (i, i)
        mdiff = 1
        n = len(indexes)
        colors = list(indexes.keys())
        for i in range(n):
            for j in range(i + 1, n):
                mdiff = max(mdiff, abs(indexes[colors[i]][1] - indexes[colors[j]][0]), abs(indexes[colors[j]][1] - indexes[colors[i]][0]))
        return mdiff

class Solution:
    def twoOutOfThree(self, nums1: List[int], nums2: List[int], nums3: List[int]) -> List[int]:
        nums1 = set(nums1)
        nums2 = set(nums2)
        nums3 = set(nums3)
        checklist = set.union(nums1, nums2, nums3)
        op = []
        for num in checklist:
            ctr = 0
            if num in nums1:
                ctr += 1
            if num in nums2:
                ctr += 1
            if num in nums3:
                ctr += 1
            if ctr >= 2:
                op.append(num)
        return op

class Solution:
    def twoSum(self, numbers: List[int], target: int) -> List[int]:
        n = len(numbers)
        i = 0
        j = n - 1
        while i <= j:
            curr = numbers[i] + numbers[j]
            if curr < target:
                i += 1
            elif curr > target:
                j -= 1
            else:
                return [i + 1, j + 1]

class Solution:
    def inorder(self, root, k):
        if root and not self.possible:
            self.inorder(root.left, k)
            if (k - root.val) in self.exists:
                self.possible = True
            self.exists.add(root.val)
            self.inorder(root.right, k)

    def findTarget(self, root: Optional[TreeNode], k: int) -> bool:
        self.possible = False
        self.exists = set()
        self.inorder(root, k)
        return self.possible

class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        exists = {}
        op = []
        for i in range(len(nums)):
            compliment = target - nums[i]
            if compliment in exists:
                op += [i, exists[compliment]]
                break
            exists[nums[i]] = i
        return op

class Solution:
    def triangleType(self, nums: List[int]) -> str:
        nums.sort()
        if nums[0] + nums[1] <= nums[2]:
            return "none"
        if nums[0] == nums[2]:
            return "equilateral"
        if len(set(nums)) == 3:
            return "scalene"
        return "isosceles"

import heapq

class Solution:
    def nthUglyNumber(self, n: int) -> int:
        uglies = [1]
        uglySet = {1}
        while len(uglies) < n * 10:
            for num in uglies[:]:
                for k in [2, 3, 5]:
                    p = num * k
                    if p not in uglySet:
                        heapq.heappush(uglies, p)
                        uglySet.add(p)
        return heapq.nsmallest(n, uglies)[n - 1]

class Solution:
    def isUgly(self, n: int) -> bool:
        if n == 0:
            return False
        while n % 2 == 0:
            n = n // 2
        while n % 3 == 0:
            n = n // 3
        while n % 5 == 0:
            n = n // 5
        return n == 1

from collections import Counter

class Solution:
    def uncommonFromSentences(self, s1: str, s2: str) -> List[str]:
        ws = Counter(s1.split()) + Counter(s2.split())
        op = []
        for w in ws:
            if ws[w] == 1:
                op.append(w)
        return op

class Solution:
    def maxUncrossedLines(self, nums1: List[int], nums2: List[int]) -> int:
        m = len(nums1)
        n = len(nums2)
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])
                if nums1[i] == nums2[j]:
                    dp[i][j] = max(dp[i][j], 1 + dp[i + 1][j + 1])
        return dp[0][0]

class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        n = len(digits)
        res = set()
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    if len({i, j, k}) == 3:
                        x = 100 * digits[i] + 10 * digits[j] + digits[k]
                        if len(str(x)) == 3 and x % 2 == 0:
                            res.add(x)
        return len(res)

class Solution:
    def getTrees(self, beg, end):
        trees = []

        if beg > end:
            trees.append(None)
            return trees

        for i in range(beg, end + 1):
            left_subtrees = self.getTrees(beg, i - 1)
            right_subtrees = self.getTrees(i + 1, end)

            for l in left_subtrees:
                for r in right_subtrees:
                    tree = TreeNode(val = i, left = l, right = r)
                    trees.append(tree)
        return trees

    def generateTrees(self, n: int) -> List[Optional[TreeNode]]:
        return self.getTrees(1, n)

class Solution:
    def getTrees(self, beg, end):
        if beg > end:
            return 1
        if (beg, end) in self.cache:
            return self.cache[(beg, end)]
        ways = 0
        for i in range(beg, end + 1):
            ways += self.getTrees(beg, i - 1) * self.getTrees(i + 1, end)
        self.cache[(beg, end)] = ways
        return ways

    def numTrees(self, n: int) -> int:
        self.cache = {}
        return self.getTrees(1, n)

class Solution:
    def numUniqueEmails(self, emails: List[str]) -> int:
        diff = set()
        for email in emails:
            host, domain = email.split('@')
            host = host.split('+')[0]
            host = "".join(host.split('.'))
            diff.add("{}@{}".format(host, domain))
        return len(diff)

from collections import Counter

def mos_algorithm(arr, queries):
    block_size = int(math.sqrt(len(arr)))
    sorted_queries = sorted(queries, key=lambda x: x[0] // block_size)
    left, right, dctr = 0, -1, 0
    ctr = [0] * 26
    def remove(x):
        nonlocal dctr
        ctr[x] -= 1
        if ctr[x] == 0:
            dctr -= 1
    def add(x):
        nonlocal dctr
        ctr[x] += 1
        if ctr[x] == 1:
            dctr += 1
    res = 0
    for query_left, query_right in sorted_queries:
        while left > query_left:
            left -= 1
            add(arr[left])
        while right < query_right:
            right += 1
            add(arr[right])
        while left < query_left:
            remove(arr[left])
            left += 1
        while right > query_right:
            remove(arr[right])
            right -= 1
        res += dctr
    return res

class Solution:
    def countPalindromicSubsequence(self, s):
        s = [ord(c) - ord('a') for c in s]
        n = len(s)
        f = [-1] * 26
        l = [-1] * 26
        for i in range(n):
            if f[s[i]] == -1:
                f[s[i]] = i
            l[s[i]] = i
        inv = []
        for x in range(26):
            if f[x] + 1 < l[x]:
                inv.append((f[x] + 1, l[x] - 1))
        return mos_algorithm(s, inv)

class Solution:
    def toMorse(self, s):
        morseMap = [".-","-...","-.-.","-..",".","..-.","--.","....","..",".---","-.-",".-..","--","-.","---",".--.","--.-",".-.","...","-","..-","...-",".--","-..-","-.--","--.."]
        return "".join([morseMap[ord(c)-ord('a')] for c in s])

    def uniqueMorseRepresentations(self, words: List[str]) -> int:
        return len(set([self.toMorse(w) for w in words]))

class Solution:
    def uniqueOccurrences(self, arr: List[int]) -> bool:
        return len(Counter(arr).values()) == len(set(Counter(arr).values()))

class Solution:
    memo = {}

    def uniquePathsRec(self, m, n, i, j, obstacleGrid):
        if i == m - 1 and j == n - 1:
            if obstacleGrid[i][j] != 1:
                return 1
            return 0
        if obstacleGrid[i][j] == 1:
            return 0
        if (i, j) not in self.memo:
            self.memo[(i, j)] = 0
            if i + 1 < m:
                self.memo[(i, j)] += self.uniquePathsRec(m, n, i + 1, j, obstacleGrid)
            if j + 1 < n:
                self.memo[(i, j)] += self.uniquePathsRec(m, n, i, j + 1, obstacleGrid)
        return self.memo[(i , j)]  

    def uniquePathsWithObstacles(self, obstacleGrid: List[List[int]]) -> int:
        self.memo = {}
        return self.uniquePathsRec(len(obstacleGrid), len(obstacleGrid[0]), 0, 0, obstacleGrid)

class Solution:
    def count(self, grid, i, j, m, n, mask, target):
        if grid[i][j] == 2:
            if mask == target:
                return 1
            return 0
        key = (i, j, mask)
        if key in self.cache:
            return self.cache[key]
        res = 0
        for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
            if 0 <= x < m and 0 <= y < n and grid[x][y] != -1 and not mask & (1 << (n * x + y)):
                res += self.count(grid, x, y, m, n, mask | (1 << (n * x + y)), target)
        self.cache[key] = res
        return res

    def uniquePathsIII(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        self.cache = {}
        start = (-1, -1)
        target = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    start = (i, j)
                if grid[i][j] != -1:
                    target |= 1 << (n * i + j)
        return self.count(grid, start[0], start[1], m, n, 1 << (n * start[0] + start[1]), target)

class Solution:
    def uniquePathsRec(self, m, n, i, j):
        if i == m - 1 or j == n - 1:
            return 1
        if (i, j) in self.cache:
            return self.cache[(i , j)]
        res = self.uniquePathsRec(m, n, i + 1, j) + self.uniquePathsRec(m, n, i, j + 1)
        self.cache[(i, j)] = res
        return res

    def uniquePaths(self, m: int, n: int, i = 0, j = 0) -> int:
        self.cache = {}
        return self.uniquePathsRec(m, n, 0, 0)

class Solution:
    def findSubstringInWraproundString(self, s: str) -> int:
        n = len(s)
        char = [0] * 26
        res = 0
        longest = 0
        for i in range(n):
            curr = ord(s[i]) - ord('a')
            if i > 0 and (ord(s[i - 1]) - ord('a') + 1) % 26 == curr:
                longest += 1
            else:
                longest = 1
            char[curr] = max(char[curr], longest)
        return sum(char)

