class Solution:
    def isUnivalTree(self, root: Optional[TreeNode]) -> bool:
        l = True
        r = True
        if root:
            if root.left and (root.val != root.left.val or not self.isUnivalTree(root.left)):
                l = False
            if root.right and (root.val != root.right.val or not self.isUnivalTree(root.right)):
                r = False
        return l and r

class Solution:
    def robotWithString(self, s: str) -> str:
        n = len(s)
        smaller = [None] * n
        minchar = "z"
        for i in range(n - 1, -1, -1):
            minchar = min(minchar, s[i])
            if s[i] > minchar:
                smaller[i] = minchar
        res = []
        stack = []
        for i in range(n):
            if smaller[i] != None:
                while len(stack) > 0 and smaller[i] >= stack[-1]:
                    res.append(stack.pop())
                stack.append(s[i])
            else:
                while len(stack) > 0 and s[i] >= stack[-1]:
                    res.append(stack.pop())
                res.append(s[i])
        while len(stack) > 0:
            res.append(stack.pop())
        return "".join(res)

class Solution:
    def getbin(self, num):
        return "{:08b}".format(num)

    def getctr(self, num):
        b = self.getbin(num)
        i = 0
        while i < 8 and b[i] == "1":
            i += 1
        return i

    def validUtf8(self, data: List[int]) -> bool:
        n = len(data)
        i = 0
        while i < n:
            ctr = self.getctr(data[i])
            if ctr > 4 or ctr == 1:
                return False
            if i + ctr > n:
                return False
            j = i + ctr
            i += 1
            while i < j:
                if self.getctr(data[i]) != 1:
                    return False
                i += 1
        return True

class Solution:
    def isAnagram(self, s: str, t: str) -> bool:
        ctr = {}
        for c in s:
            ctr[c] = ctr.get(c, 0) + 1
        for c in t:
            if c in ctr:
                ctr[c] -= 1
            else:
                return False
        for val in ctr.values():
            if val != 0:
                return False
        return True

class Solution:
    def validPalindrome(self, s: str) -> bool:
        n = len(s)
        i = 0
        j = n - 1
        while s[i] == s[j] and i < j:
            i += 1
            j -= 1
        if s[i] != s[j]:
            option1 = s[:i] + s[i + 1:]
            option2 = s[:j] + s[j + 1:]
            if option1 == option1[::-1]:
                return True
            if option2 == option2[::-1]:
                return True
            return False
        return True

class Solution:
    def isValidPalindrome(self, s: str, k: int) -> bool:
        n = len(s)
        @lru_cache(maxsize = None)
        def check(i, j, l):
            if i > j:
                return int(l == 0)
            if j - i + 1 < l:
                return False
            if l == 1:
                return i <= j
            if check(i + 1, j, l) or check(i, j - 1, l):
                return True
            if s[i] == s[j] and check(i + 1, j - 1, l - 2):
                return True
            return False
        return check(0, n - 1, n - k)

class Solution:
    def makePalindrome(self, s: str) -> bool:
        i = 0
        j = len(s) - 1
        ops = 0
        while i < j:
            if s[i] != s[j]:
                ops += 1
            i += 1
            j -= 1
        return ops <= 2

class Solution:
    def isPalindrome(self, s: str) -> bool:
        s = "".join([c.lower() for c in s if c.isalnum()])
        return s == s[::-1]

class Solution:
    def isValid(self, s: str) -> bool:
        stack = []
        validPairs = ['()', '[]', '{}']
        valid = True
        for bracket in s:
            if bracket in [b[0] for b in validPairs]:
                stack.append(bracket)
            else:
                if len(stack) > 0:
                    if (stack.pop() + bracket) not in validPairs:
                        valid = False
                        break
                else:
                    valid = False
                    break
        if len(stack) > 0:
            valid = False
        return valid

class Solution:
    def isValid(self, s, i, n, ctr):
        if ctr < 0:
            return False
        if i >= n:
            return ctr == 0
        if (i, ctr) in self.cache:
            return self.cache[(i, ctr)]
        res = False
        if s[i] == '(':
            res = self.isValid(s, i + 1, n, ctr + 1)
        elif s[i] == ')':
            res = self.isValid(s, i + 1, n, ctr - 1)
        else:
            for diff in [-1, 0, 1]:
                if self.isValid(s, i + 1, n, ctr + diff):
                    res = True
                    break
        self.cache[(i, ctr)] = res
        return res

    def checkValidString(self, s: str) -> bool:
        n = len(s)
        self.cache = {}
        return self.isValid(s, 0, n, 0)

class Solution:
    def isPerfectSquare(self, num: int) -> bool:
        beg = 0
        end = num
        while beg <= end:
            mid = (beg + end) // 2
            if mid * mid == num:
                return True
            elif beg == end:
                break
            elif mid * mid > num:
                end = mid
            else:
                beg = mid + 1
        return False

class Solution:
    def dist(self, a, b):
        return (a[0] - b[0]) * (a[0] - b[0]) + (a[1] - b[1]) * (a[1] - b[1])

    def isPerpendicular(self, a, b, c, d):
        return (b[1] - a[1]) * (d[1] - c[1]) == (b[0] - a[0]) * (c[0] - d[0])

    def midPoint(self, a, b):
        return (a[0] + b[0], a[1] + b[1])

    def validSquare(self, p1: List[int], p2: List[int], p3: List[int], p4: List[int]) -> bool:
        plist = [p1, p2, p3, p4]
        points = [[(0, 1), (2, 3)], [(0, 2), (1, 3)], [(0, 3), (1, 2)]]
        for diag in points:
            a, b = [plist[d] for d in diag[0]]
            c, d = [plist[d] for d in diag[1]]
            isBisector = self.midPoint(a, b) == self.midPoint(c, d)
            if not isBisector:
                continue
            d1, d2 = self.dist(a, b), self.dist(c, d)
            if d1 != d2 or d1 == 0:
                continue
            if self.isPerpendicular(a, b, c, d):
                return True
        return False

from collections import defaultdict

class Solution:
    def isValidSudoku(self, board: List[List[str]]) -> bool:
        n = 9
        k = 3
        rowseen = defaultdict(set)
        colseen = defaultdict(set)
        cellseen = defaultdict(set)
        for i in range(n):
            for j in range(n):
                curr = board[i][j]
                if curr != ".":
                    if curr in rowseen[i] or curr in colseen[j]:
                        return False
                    rowseen[i].add(curr)
                    colseen[j].add(curr)
                    cell = (i // k, j // k)
                    if curr in cellseen[cell]:
                        return False
                    cellseen[cell].add(curr)
        return True

class Solution:
    def triangleNumber(self, nums: List[int]) -> int:
        nums.sort()
        n = len(nums)
        ctr = 0
        i = 2
        while i < n:
            a = 0
            b = i - 1
            while a < b:
                if nums[a] + nums[b] > nums[i]:
                    ctr += (b - a)
                    b -= 1
                else:
                    a += 1
            i += 1
        return ctr

class Solution:
    def isValid(self, word: str) -> bool:
        if len(word) < 3:
            return False
        vowels = set("aeiouAEIOU")
        has_vowel = has_consonant = False
        for c in word:
            if not c.isalnum():
                return False
            if c.isalpha():
                if c in vowels:
                    has_vowel = True
                else:
                    has_consonant = True
        return has_vowel and has_consonant

class Solution:
    def check(self, root):
        maxval, minval, valid = float('-inf'), float('inf'), True
        if root:
            lmax, lmin, lvalid = self.check(root.left)
            rmax, rmin, rvalid = self.check(root.right)
            maxval = max(maxval, lmax, rmax, root.val)
            minval = min(minval, lmin, rmin, root.val)
            valid = lvalid and rvalid and lmax < root.val < rmin
        return maxval, minval, valid

    def isValidBST(self, root: Optional[TreeNode]) -> bool:
        return self.check(root)[2]

class Solution:
    def validateBinaryTreeNodes(self, n: int, leftChild: List[int], rightChild: List[int]) -> bool:
        parent = [0] * n
        for i in range(n):
            if leftChild[i] != -1:
                parent[leftChild[i]] += 1
            if rightChild[i] != -1:
                parent[rightChild[i]] += 1
        if parent.count(0) != 1 or parent.count(1) != n - 1:
            return False
        root = parent.index(0)
        stack = [root]
        v = {root}
        while len(stack) > 0:
            curr = stack.pop()
            if leftChild[curr] in v:
                return False
            if rightChild[curr] in v:
                return False
            if leftChild[curr] != -1:
                v.add(leftChild[curr])
                stack.append(leftChild[curr])
            if rightChild[curr] != -1:
                v.add(rightChild[curr])
                stack.append(rightChild[curr])
        return len(v) == n

class Solution:
    def validIPAddress(self, queryIP: str) -> str:
        isv4 = True
        isv6 = True
        if "." in queryIP:
            isv6 = False
            queryIP = queryIP.split(".")
            if len(queryIP) != 4:
                isv4 = False
        else:
            isv4 = False
        if ":" in queryIP:
            isv4 = False
            queryIP = queryIP.split(":")
            if len(queryIP) != 8:
                isv6 = False
        else:
            isv6 = False
        if isv4:
            for x in queryIP:
                if not x.isnumeric() or (len(x) > 1 and x[0] == "0") or not 0 <= int(x) < 256:
                    isv4 = False
                    break
        if isv6:
            for x in queryIP:
                try:
                    int(x, 16)
                    if len(x) > 4:
                        raise
                except:
                    isv6 = False
                    break
        if isv4:
            return "IPv4"
        if isv6:
            return "IPv6"
        return "Neither"

class Solution:
    def validateStackSequences(self, pushed: List[int], popped: List[int]) -> bool:
        n = len(popped)
        i = 0
        j = 0
        stack = []
        while j < n:
            while len(stack) == 0 or stack[-1] != popped[j]:
                if i >= n:
                    return False
                stack.append(pushed[i])
                i += 1
            stack.pop()
            j += 1
        return True

class Solution:
    def isSorted(self, nums):
        n = len(nums)
        for i in range(n - 1):
            if nums[i] > nums[i + 1]:
                return False
        return True

    def isAlienSorted(self, words: List[str], order: str) -> bool:
        pos = {}
        for i, c in enumerate(order):
            pos[c] = i
        return self.isSorted([tuple([pos.get(c, 0) for c in word]) for word in words])

from collections import defaultdict

class Solution:
    def inorder(self, root, w, h, res):
        if root:
            self.inorder(root.left, w - 1, h + 1, res)
            res[w][h].append(root.val)
            self.inorder(root.right, w + 1, h + 1, res)

    def verticalTraversal(self, root):
        res = defaultdict(lambda: defaultdict(list))
        self.inorder(root, 0, 0, res)
        traversal = []
        for w in sorted(res.keys()):
            col = []
            for h in sorted(res[w].keys()):
                col.extend(sorted(res[w][h]))
            traversal.append(col)
        return traversal

class Solution:
    def videoStitching(self, clips: List[List[int]], time: int) -> int:
        n = len(clips)
        clips.sort()
        dp = [float('inf')] * (time + 1)
        dp[0] = 0
        for beg, end in clips:
            newend = min(end + 1, time + 1)
            for i in range(beg, newend):
                dp[i] = min(dp[i], dp[beg] + 1)
        if dp[time] == float('inf'):
            return -1
        return dp[time]

class Solution:
    def maxScore(self, nums: List[int], x: int) -> int:
        n = len(nums)
        maxeven = float('-inf')
        maxodd = float('-inf')
        for i in range(n - 1, 0, -1):
            if nums[i] & 1:
                maxodd = max(maxodd, nums[i], nums[i] + maxodd, nums[i] - x + maxeven)
            else:
                maxeven = max(maxeven, nums[i], nums[i] + maxeven, nums[i] - x + maxodd)
        if nums[0] & 1:
            return max(nums[0], nums[0] + maxodd, nums[0] - x + maxeven)
        return max(nums[0], nums[0] + maxeven, nums[0] - x + maxodd)

class Solution:
    def doesAliceWin(self, s: str) -> bool:
