        while i < len(paths):
            a, b = paths[i]
            if a == targetCapacity or b == targetCapacity or a + b == targetCapacity:
                return True
            opts = [(jug1Capacity, b), (a, jug2Capacity), (jug1Capacity, jug2Capacity), (0, b), (a, 0), (min(a + b, jug1Capacity), max(b - (jug1Capacity - a), 0)), (max(a - (jug2Capacity - b), 0), min(b + a, jug2Capacity))]
            for opt in opts:
                if opt not in visited:
                    visited.add(opt)
                    paths.append(opt)
            i += 1
        return False

class Solution:
    def numWaterBottles(self, numBottles: int, numExchange: int) -> int:
        total = numBottles
        numFilled = 0
        numEmpty = numBottles
        while numEmpty >= numExchange:
            numFilled = (numEmpty // numExchange)
            total += numFilled
            numEmpty = numFilled + numEmpty % numExchange
        return total

class Solution:
    def wateringPlants(self, plants: List[int], capacity: int) -> int:
        n = len(plants)
        i = 0
        water = capacity
        steps = 0
        while i < n:
            if water >= plants[i]:
                water -= plants[i]
                i += 1
                steps += 1
            else:
                steps += 2 * i
                water = capacity
        return steps

import heapq
import numpy as np

MOD = 10**9 + 7

def add_poly(p, q):
    max_len = max(len(p), len(q))
    p = np.pad(p, (0, max_len - len(p)))
    q = np.pad(q, (0, max_len - len(q)))
    return (p + q) % MOD

def multiply_naive(p, q, n):
    result = np.polynomial.polynomial.polymul(p, q) % MOD
    return result[:n+1]

class Solution:
    def numberOfWays(self, n: int, x: int) -> int:
        heap = []
        for i in range(1, n + 1):
            a = pow(i, x)
            if a > n:
                break
            poly = np.zeros(a + 1, dtype=int)
            poly[0], poly[a] = 1, 1
            heapq.heappush(heap, (len(poly), poly.tolist()))

        while len(heap) > 1:
            _, poly1 = heapq.heappop(heap)
            _, poly2 = heapq.heappop(heap)
            result_poly = multiply_naive(np.array(poly1), np.array(poly2), n)
            heapq.heappush(heap, (len(result_poly), result_poly.tolist()))

        _, final_poly = heap[0]
        if len(final_poly) < n + 1:
            return 0
        return int(final_poly[n] % MOD)

class Solution:
    def waysToMakeFair(self, nums: List[int]) -> int:
        n = len(nums)
        p = [(0, 0)]
        for i in range(n):
            e, o = p[-1]
            if i % 2 == 0:
                e += nums[i]
            else:
                o += nums[i]
            p.append((e, o))
        res = 0
        for i in range(n):
            e0, o0 = p[i]
            e1, o1 = p[-1]
            e1 -= e0
            o1 -= o0
            if i % 2 == 0:
                e1 -= nums[i]
            else:
                o1 -= nums[i]
            if e0 + o1 == e1 + o0:
                res += 1
        return res

class Solution:
    def getpos(self, grid, i, j, m, n):
        if i == m:
            return j
        nj = j - 1
        if grid[i][j] == 1:
            nj = j + 1
        if 0 <= nj < n and grid[i][j] == grid[i][nj]:
            return self.getpos(grid, i + 1, nj, m, n)
        return -1

    def findBall(self, grid: List[List[int]]) -> List[int]:
        m = len(grid)
        n = len(grid[0])
        return [self.getpos(grid, 0, j, m, n) for j in range(n)]

class Solution:
    def maxWidthOfVerticalArea(self, points: List[List[int]]) -> int:
        n = len(points)
        points = sorted(points)
        return max([points[i + 1][0] - points[i][0] for i in range(n - 1)])

class FenwickTree:
    def __init__(self, x):
        self.bit = x
        for i in range(len(x)):
            j = i | (i + 1)
            if j < len(x):
                x[j] = max(x[j], x[i])

    def update(self, idx, x):
        while idx < len(self.bit):
            self.bit[idx] = max(self.bit[idx], x)
            idx |= idx + 1

    def query(self, end):
        x = 0
        while end:
            x = max(x, self.bit[end - 1])
            end &= end - 1
        return x

class Solution:
    def wiggleMaxLength(self, nums: List[int]) -> int:
        n = len(nums)
        inc = [0] * n
        dec = [0] * n
        M = max(nums)
        inctree = FenwickTree([0] * (M + 1))
        dectree = FenwickTree([0] * (M + 1))
        for i in range(n):
            inc[i] = 1 + dectree.query(nums[i])
            dec[i] = 1 + inctree.query(M - nums[i])
            inctree.update(M - nums[i], inc[i])
            dectree.update(nums[i], dec[i])
        return max(max(inc), max(dec))

class Solution:
    def isSame(self, a, b):
        if a == "?" or b == "?":
            return True
        return a == b

    def isMatchRec(self, s, p, i, j, m, n):
        if j >= n:
            return i >= m
        if i >= m:
            if j >= n:
                return True
        if (i, j) in self.cache:
            return self.cache[(i, j)]
        if i >= m:    
            res = p[j] == "*" and self.isMatchRec(s, p, i, j + 1, m, n)
            self.cache[(i, j)] = res
            return res
        if p[j] == "*":
            res = self.isMatchRec(s, p, i, j + 1, m, n) or self.isMatchRec(s, p, i + 1, j, m, n)
            self.cache[(i, j)] = res
            return res
        res = self.isSame(s[i], p[j]) and self.isMatchRec(s, p, i + 1, j + 1, m, n)
        self.cache[(i, j)] = res
        return res

    def isMatch(self, s: str, p: str) -> bool:
        m = len(s)
        n = len(p)
        self.cache = {}
        return self.isMatchRec(s, p, 0, 0, m, n)

class Solution:
    def genline(self, s, i, n, words, curr, res):
        if i >= n:
            res.append(" ".join(curr))
        for j in range(i + 1, n + 1):
            if s[i:j] in words:
                curr.append(s[i:j])
                self.genline(s, j, n, words, curr, res)
                curr.pop()

    def wordBreak(self, s: str, wordDict: List[str]) -> List[str]:
        n = len(s)
        words = set(wordDict)
        res = []
        self.genline(s, 0, n, words, [], res)
        return res

class TrieNode:
    def __init__(self):
        self.child = {}
        self.end = False

class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> bool:
        n = len(s)
        root = TrieNode()
        for w in wordDict:
            curr = root
            for c in w:
                if c not in curr.child:
                    curr.child[c] = TrieNode()
                curr = curr.child[c]
            curr.end = True
        dp = [False] * (n + 1)
        dp[n] = True
        for i in range(n - 1, -1, -1):
            j = i
            curr = root
            while j < n and curr:
                curr = curr.child.get(s[j], None)
                if curr and curr.end and dp[j + 1]:
                    dp[i] = True
                    break
                j += 1
        return dp[0]

from collections import defaultdict, deque

class Solution:
    def getPaths(self, parent, currpath, beginWord):
        if currpath[-1] == beginWord:
            self.paths.append(currpath[::-1])
            return
        for j in parent[currpath[-1]]:
            currpath.append(j)
            self.getPaths(parent, currpath, beginWord)
            currpath.pop()

    def findLadders(self, beginWord: str, endWord: str, wordList: List[str]) -> List[List[str]]:
        n = len(beginWord)
        wordList = set(wordList + [beginWord])
        graph = defaultdict(list)
        for word in wordList:
            for i in range(n):
                for c in "abcdefghijklmnopqrstuvwxyz":
                    currstr = word[0:i] + c + word[i+1:]
                    if currstr != word and currstr in wordList:
                        graph[word].append(currstr)
        dist = defaultdict(lambda: float('inf'))
        parent = defaultdict(list)
        dist[beginWord] = 0
        queue = deque([beginWord])
        while len(queue) > 0:
            curr = queue.pop()
            for j in graph[curr]:
                if dist[j] > dist[curr] + 1:
                    dist[j] = dist[curr] + 1
                    parent[j].clear()
                    parent[j].append(curr)
                    queue.appendleft(j)
                elif dist[j] == dist[curr] + 1:
                    parent[j].append(curr)
        self.paths = []
        self.getPaths(parent, [endWord], beginWord)
        return self.paths

from collections import defaultdict, deque

class Solution:
    def ladderLength(self, beginWord: str, endWord: str, wordList: List[str]) -> int:
        n = len(beginWord)
        wordList = set(wordList + [beginWord])
        graph = defaultdict(list)
        for word in wordList:
            for i in range(n):
                for c in "abcdefghijklmnopqrstuvwxyz":
                    currstr = word[0:i] + c + word[i+1:]
                    if currstr != word and currstr in wordList:
                        graph[word].append(currstr)
        queue = deque([(beginWord, 1)])
        visited = set()
        while len(queue) > 0:
            curr, k = queue.pop()
            for j in graph.get(curr, []):
                if j not in visited:
                    if j == endWord:
                        return k + 1
                    visited.add(j)
                    queue.appendleft((j, k + 1))
        return 0

class Solution:
    def wordPattern(self, pattern: str, s: str) -> bool:
        patt = []
        pattset = {}
        i = 0
        for p in pattern:
            if p not in pattset:
                pattset[p] = i
                i += 1
            patt.append(pattset[p])
        words = []
        wordset = {}
        i = 0
        for w in s.split():
            if w not in wordset:
                wordset[w] = i
                i += 1
            words.append(wordset[w])
        return patt == words

class Node:
  def __init__(self):
    self.child = {}
    self.end = False
    self.s = None

class Trie:
  def __init__(self):
    self.root = Node()

  def insert(self, s):
    curr = self.root
    for c in s:
      if c not in curr.child:
        curr.child[c] = Node()
      curr = curr.child[c]
    curr.end = True
    curr.s = s

class Solution:
    def find(self, board, i, j, m, n, node):
        if self.k == 0:
            return
        c = board[i][j]
        if c not in node.child:
            return
        node = node.child[c]
        if node.end:
            self.res.append(node.s)
            node.end = False
            node.s = None
            self.k -= 1
        board[i][j] = "#"
        for x, y in [(i - 1, j), (i, j - 1), (i + 1, j), (i, j + 1)]:
            if 0 <= x < m and 0 <= y < n and board[x][y] != "#":
                self.find(board, x, y, m, n, node)
        board[i][j] = c

    def findWords(self, board: List[List[str]], words: List[str]) -> List[str]:
        m = len(board)
        n = len(board[0])
        chars = set.union(*[set(r) for r in board])
        words = [w for w in words if not set(w).isdisjoint(chars)]
        self.k = len(words)
        trie = Trie()
        for w in words:
            trie.insert(w)
        self.res = []
        for i in range(m):
            for j in range(n):
                self.find(board, i, j, m, n, trie.root)
        return self.res

class Solution:
    def getNeighbors(self, i, j, m, n):
        nb = []
        if i > 0:
            nb.append((i - 1, j))
        if i < m - 1:
            nb.append((i + 1, j))
        if j > 0:
            nb.append((i, j - 1))
        if j < n - 1:
            nb.append((i, j + 1))
        return nb

    def isPossible(self, board, m, n, pos, word, i, used):
        if i == len(word) - 1:
            return True
        neighbors = self.getNeighbors(pos[0], pos[1], m, n)
        for a, b in neighbors:
            if (a, b) not in used and board[a][b] == word[i + 1]:
                if self.isPossible(board, m, n, (a, b), word, i + 1, used.union({(a, b)})):
                    return True
        return False

    def exist(self, board: List[List[str]], word: str) -> bool:
        m = len(board)
        n = len(board[0])
        wlen = len(word)
        for i in range(m):
            for j in range(n):
                if board[i][j] == word[0]:
                    if self.isPossible(board, m, n, (i, j), word, 0, {(i, j)}):
                        return True
        return False

from collections import Counter

class Solution:
    def isSubset(self, ctr1, ctr2):
        for c in ctr1:
            if ctr2[c] < ctr1[c]:
                return False
        return True

    def wordSubsets(self, words1: List[str], words2: List[str]) -> List[str]:
        univ = Counter()
        for w in words2:
            curr = Counter(w)
            for c in curr:
                univ[c] = max(univ[c], curr[c])
        return [w for w in words1 if self.isSubset(univ, Counter(w))]

class Solution:
    def twoEditWords(self, queries: List[str], dictionary: List[str]) -> List[str]:
        res = []
        d = set(dictionary)
        for q in queries:
            found = False
            for w in d:
                n = len(w)
                ctr = 0
                for i in range(n):
                    if w[i] != q[i]:
                        ctr += 1
                if ctr <= 2:
                    found = True
                    break
            if found:
                res.append(q)
        return res

from collections import Counter

class Solution:
    def gcd(self, a, b):
        while b:
            a, b = b, a % b
        return a

    def hasGroupsSizeX(self, deck: List[int]) -> bool:
        ctr = Counter(deck)
        l = 0
        for el in ctr:
            l = self.gcd(l, ctr[el])
        return l > 1

class Solution:
    def xorOperation(self, n: int, start: int) -> int:
        op = start
        for i in range(1, n):
            op = op ^ (start + 2 * i)
        return op

class Solution:
    def xorQueries(self, arr: List[int], queries: List[List[int]]) -> List[int]:
        n = len(arr)
        p = [0] * (n + 1)
        for i in range(n):
            p[i + 1] ^= p[i] ^ arr[i]
        res = []
        for a, b in queries:
            res.append(p[b + 1] ^ p[a])
        return res

class Solution:
    def isZeroArray(self, nums: List[int], queries: List[List[int]]) -> bool:
        n = len(nums)
        ctr = [0] * (n + 1)
        for l, r in queries:
            ctr[l] += 1
            ctr[r + 1] -= 1
        for i in range(n):
            ctr[i + 1] += ctr[i]
        for i in range(n):
            if ctr[i] < nums[i]:
                return False
        return True

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        beg = 0
        end = len(queries)
        while beg <= end:
            mid = (beg + end) // 2
            curr = [0] * (n + 1)
            for i in range(mid):
                curr[queries[i][0]] += queries[i][2]
                curr[queries[i][1] + 1] -= queries[i][2]
            for i in range(n):
                curr[i + 1] += curr[i]
            done = True
            for i in range(n):
                if nums[i] > curr[i]:
                    done = False
                    break
            if done:
                end = mid - 1
            else:
                beg = mid + 1
        return end + 1 if end + 1 <= len(queries) else -1

import heapq

class FenwickTree:
    def __init__(self, x):
        self.bit = x
        for i in range(len(x)):
            j = i | (i + 1)
            if j < len(x):
                x[j] += x[i]

    def update(self, idx, x):
        while idx < len(self.bit):
            self.bit[idx] += x
            idx |= idx + 1

    def query(self, end):
        x = 0
        while end:
            x += self.bit[end - 1]
            end &= end - 1
        return x

class Solution:
    def maxRemoval(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        queries.sort()
        dec = FenwickTree([0] * n)
        i = 0
        heap = []
        res = len(queries)
        for j in range(n):
            while i < len(queries) and queries[i][0] <= j:
                heapq.heappush(heap, (-queries[i][1], queries[i][0]))
                i += 1
            while nums[j] - dec.query(j + 1) > 0 and heap:
                res -= 1
                x = heapq.heappop(heap)
                l, r = x[1], -x[0]
                dec.update(l, 1)
                dec.update(r + 1, -1)
            if nums[j] - dec.query(j + 1) > 0:
                return -1
        return res

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        q = len(queries)
        beg = 0
        end = q
        res = -1
        while beg <= end:
            mid = (beg + end) // 2
            vals = [[] for _ in range(n)]
            for i in range(mid):
                l, r, v = queries[i]
                for j in range(l, r + 1):
                    vals[j].append(v)
            pos = True
            for i in range(n):
                s = {0}
                for v in vals[i]:
                    s |= {x + v for x in s}
                if nums[i] not in s:
                    pos = False
                    break
            if pos:
                res = mid
                end = mid - 1
            else:
                beg = mid + 1
        return res

class Solution:
    def convert(self, s: str, numRows: int) -> str:
        n = len(s)
        if numRows == 1:
            return s
        op = ""
        for i in range(numRows):
            curr = i
            down = True
            while curr < n:
                op += s[curr]
                if down:
                    if numRows - i - 1 > 0:
                        curr += 2 * (numRows - i - 1)
                    else:
                        curr += 2 * i
                else:
                    if i > 0:
                        curr += 2 * i
                    else:
                        curr += 2 * (numRows - i - 1)
                down = not down
        return op

class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        res = []
        f = True
        for r in grid:
            res.extend(r if f else r[::-1])
            f = not f
        return [res[i] for i in range(0, len(res), 2)]
